export const PDEX = {
  1: [{"g": "Noir", "t": "Au matin de sa vie, la graine sur son dos lui fournit les éléments dont il a besoin pour grandir."}, {"g": "X", "t": "Il a une étrange graine plantée sur son dos. Elle grandit avec lui depuis sa naissance."}, {"g": "Rubis Oméga", "t": "Bulbizarre passe son temps à faire la sieste sous le soleil. Il y a une graine sur son dos. Il absorbe les rayons du soleil pour faire doucement pousser la graine."}, {"g": "Let's Go Pikachu", "t": "Il peut survivre plusieurs jours sans manger grâce aux nutriments contenus dans le bulbe sur son dos."}, {"g": "Épée", "t": "Il y a une graine sur son dos depuis sa naissance. Elle grossit un peu chaque jour."}, {"g": "Bouclier", "t": "Quand il est jeune, il absorbe les nutriments conservés dans son dos pour grandir et se développer."}],
  2: [{"g": "Noir", "t": "Lorsque le bourgeon sur son dos éclot, il répand un doux parfum pour célébrer sa floraison."}, {"g": "X", "t": "Il y a un bulbe sur son dos. On dit que s’il absorbe assez de nutriments, ce bulbe se transforme en une jolie fleur."}, {"g": "Rubis Oméga", "t": "Un bourgeon a poussé sur le dos de ce Pokémon. Pour en supporter le poids, Herbizarre a dû se muscler les pattes. Lorsqu’il commence à se prélasser au soleil, ça signifie que son bourgeon va éclore, donnant naissance à une fleur."}, {"g": "Let's Go Pikachu", "t": "En emmagasinant de l’énergie, son bulbe grossit. Un arôme en émane quand il s’apprête à éclore."}, {"g": "Épée", "t": "Son bulbe dorsal est devenu si gros qu’il ne peut plus se tenir sur ses pattes postérieures."}, {"g": "Bouclier", "t": "La lumière du soleil le rend plus fort et vigoureux. Le bulbe sur son dos grossit en conséquence."}],
  3: [{"g": "Noir", "t": "Le parfum de sa fleur se fait plus pénétrant les lendemains de pluie. Cela appâte les autres Pokémon."}, {"g": "X", "t": "Ses pétales lui servent à capter la lumière du soleil. Il peut ainsi en canaliser l’énergie."}, {"g": "Rubis Oméga", "t": "Une belle fleur se trouve sur le dos de Florizarre. Elle prend une couleur vive lorsqu’elle est bien nourrie et bien ensoleillée. Le parfum de cette fleur peut apaiser les gens."}, {"g": "Let's Go Pikachu", "t": "Les pétales de sa fleur dorsale absorbent les rayons du soleil pour les convertir en énergie."}, {"g": "Épée", "t": "Sa plante donne une grosse fleur quand elle absorbe les rayons du soleil. Il est toujours à la recherche des endroits les plus ensoleillés."}, {"g": "Bouclier", "t": "Une douce senteur émane de sa plante. Cette fragrance calme tous ceux qui sont engagés dans un combat."}],
  4: [{"g": "Noir", "t": "La flamme de sa queue symbolise sa vitalité. Elle est intense quand il est en bonne santé."}, {"g": "X", "t": "La flamme sur sa queue représente l’énergie vitale de Salamèche. Quand il est vigoureux, elle brûle plus fort."}, {"g": "Y", "t": "Depuis sa naissance, une petite flamme brûle au bout de sa queue. Si cette flamme s’éteint, la vie de ce Pokémon s’éteindra elle aussi."}, {"g": "Rubis Oméga", "t": "La flamme qui brûle au bout de sa queue indique l’humeur de ce Pokémon. Elle vacille lorsque Salamèche est content. En revanche, lorsqu’il s’énerve, la flamme prend de l’importance et brûle plus ardemment."}, {"g": "Let's Go Pikachu", "t": "La flammèche au bout de sa queue émet un crépitement audible seulement dans les endroits calmes."}, {"g": "Épée", "t": "Il préfère ce qui est chaud. En cas de pluie, de la vapeur se forme autour de sa queue."}],
  5: [{"g": "Noir", "t": "La nuit, la queue ardente du Reptincel brille comme une étoile dans son repaire montagneux."}, {"g": "X", "t": "Il se sert de sa queue pour faire tomber ses adversaires. Une fois qu’ils sont au sol, il les lacère de ses griffes acérées."}, {"g": "Y", "t": "En agitant sa queue, il peut élever la température à un niveau incroyable."}, {"g": "Rubis Oméga", "t": "Reptincel lacère ses ennemis sans pitié grâce à ses griffes acérées. S’il rencontre un ennemi puissant, il devient agressif et la flamme au bout de sa queue s’embrase et prend une couleur bleu clair."}, {"g": "Let's Go Pikachu", "t": "Exalté quand il affronte des adversaires puissants, ce Pokémon en vient parfois à cracher des flammes bleutées."}, {"g": "Épée", "t": "Il est très brutal. En combat, il se sert de ses griffes acérées et de sa queue enflammée pour mettre en pièces ses adversaires."}, {"g": "Bouclier", "t": "S’il s’excite pendant un combat, il crache de grandes flammes, brûlant tout ce qui se trouve aux alentours."}],
  6: [{"g": "Noir", "t": "On raconte que la flamme du Dracaufeu s’intensifie après un combat difficile."}, {"g": "X", "t": "Quand il crache son souffle brûlant, la flamme au bout de sa queue s’embrase."}, {"g": "Y", "t": "Ses ailes peuvent le faire voler à plus de 1 400 m d’altitude. Ce Pokémon crache du feu à des températures très élevées."}, {"g": "Rubis Oméga", "t": "Dracaufeu parcourt les cieux pour trouver des adversaires à sa mesure. Il crache de puissantes flammes capables de faire fondre n’importe quoi. Mais il ne dirige jamais son souffle destructeur vers un ennemi plus faible."}, {"g": "Épée", "t": "Son souffle brûlant peut faire fondre la roche. Il est parfois la cause d’incendies de forêt."}, {"g": "Bouclier", "t": "Ses ailes lui permettent de voler à plus de 1 400 m d’altitude. Ce Pokémon crache du feu à des températures très élevées."}],
  7: [{"g": "Noir", "t": "Il se réfugie dans sa carapace et réplique en éclaboussant l’ennemi à la première occasion."}, {"g": "Y", "t": "Caché sous l’eau, il crache un jet d’eau sur sa proie et se cache à l’intérieur de sa carapace."}, {"g": "Rubis Oméga", "t": "La carapace de Carapuce ne sert pas qu’à le protéger. La forme ronde de sa carapace et ses rainures lui permettent d’améliorer son hydrodynamisme. Ce Pokémon nage extrêmement vite."}, {"g": "Let's Go Pikachu", "t": "Caché sous les flots, il crache un jet d’eau sur sa proie et se réfugie à l’intérieur de sa carapace en cas de danger."}, {"g": "Épée", "t": "Quand il rentre son cou dans sa carapace, il peut projeter de l’eau à haute pression."}, {"g": "Bouclier", "t": "S’il se sent menacé, il rétracte ses pattes dans sa carapace pour se protéger et crache de l’eau."}],
  8: [{"g": "Noir", "t": "On prétend qu’il vit 10 000 ans. Sa queue duveteuse est un symbole de longévité populaire."}, {"g": "X", "t": "Attaqué, il cache sa tête dans sa carapace, mais son corps trop gros ne peut y tenir en entier."}, {"g": "Rubis Oméga", "t": "Carabaffe a une large queue recouverte d’une épaisse fourrure. Elle devient de plus en plus foncée avec l’âge. Les éraflures sur la carapace de ce Pokémon témoignent de son expérience au combat."}, {"g": "Let's Go Pikachu", "t": "Quand on lui tapote la tête, il se cache dans sa carapace, mais son corps ne peut pas y tenir en entier."}, {"g": "Épée", "t": "Il est considéré comme un symbole de longévité. On reconnaît les spécimens les plus âgés à la mousse qui pousse sur leur carapace."}, {"g": "Bouclier", "t": "Il se sert habilement de sa queue et de ses oreilles touffues pour garder son équilibre sous l’eau."}],
  9: [{"g": "Noir", "t": "Les trombes d’eau projetées par les canons de sa carapace peuvent percer le métal le plus résistant."}, {"g": "X", "t": "Il écrase ses adversaires de tout son poids pour leur faire perdre connaissance. Il rentre dans sa carapace s’il se sent en danger."}, {"g": "Y", "t": "Ce Pokémon brutal est armé de canons hydrauliques. Ses puissants jets d’eau sont dévastateurs."}, {"g": "Rubis Oméga", "t": "Tortank dispose de canons à eau émergeant de sa carapace. Ils sont très précis et peuvent envoyer des balles d’eau capables de faire mouche sur une cible située à plus de 50 m."}, {"g": "Let's Go Pikachu", "t": "Une fois sa cible dans sa ligne de mire, il projette des jets d’eau plus puissants qu’une lance à incendie."}, {"g": "Bouclier", "t": "Les canons sur sa carapace tirent des jets d’eau capables de percer même de l’acier trempé."}],
  10: [{"g": "Noir", "t": "Ses antennes rouges libèrent une puanteur qui repousse l’ennemi. Il grandit par mues régulières."}, {"g": "X", "t": "Pour se protéger, il émet un gaz puant par ses antennes, qui fait fuir ses ennemis audacieux."}, {"g": "Y", "t": "Ses pattes ont des ventouses lui permettant de grimper sur toute surface, notamment les arbres."}, {"g": "Rubis Oméga", "t": "Chenipan a un appétit d’ogre. Il peut engloutir des feuilles plus grosses que lui. Les antennes de ce Pokémon dégagent une odeur particulièrement entêtante."}, {"g": "Soleil", "t": "Lorsqu’il est attaqué par un Pokémon Vol, il utilise ses antennes pour dégager une odeur nauséabonde, mais cela le sauve rarement."}, {"g": "Lune", "t": "Un Pokémon facile à attraper et qui croît rapidement. C’est l’un des partenaires privilégiés des Dresseurs débutants."}, {"g": "Ultra-Soleil", "t": "C’est peut-être parce qu’il a envie de grandir le plus vite possible qu’il est si vorace. Il engloutit une centaine de feuilles par jour."}, {"g": "Ultra-Lune", "t": "Son corps est mou et sans force. La nature semble l’avoir destiné à servir de proie aux autres Pokémon."}, {"g": "Let's Go Pikachu", "t": "Quand on touche l’appendice sur son front, il sécrète une odeur nauséabonde pour se protéger."}, {"g": "Épée", "t": "Pour se protéger, il émet par ses antennes une odeur nauséabonde qui fait fuir ses ennemis."}, {"g": "Bouclier", "t": "Ses petites pattes munies de ventouses lui permettent de monter les pentes et de grimper aux murs sans se fatiguer."}],
  11: [{"g": "Noir", "t": "Son corps frêle est protégé par sa carapace d’acier. Il encaisse les coups durs en attendant d’évoluer."}, {"g": "Y", "t": "Il est vulnérable aux attaques tant que sa carapace est molle, car il expose son corps tendre et mou."}, {"g": "Rubis Oméga", "t": "La carapace protégeant ce Pokémon est dure comme du métal. Chrysacier ne bouge pas beaucoup. Il reste immobile pour préparer les organes à l’intérieur de sa carapace en vue d’une évolution future."}, {"g": "Soleil", "t": "Sous sa carapace, il est tout mou et tendre. Il bouge très peu afin de ne pas secouer son corps encore fragile."}, {"g": "Lune", "t": "Même si sa carapace est solide, elle n’est guère composée que de chitine et peut se briser aisément. Mieux vaut éviter les combats rudes."}, {"g": "Ultra-Soleil", "t": "Sa carapace contient un liquide gluant. Sa structure cellulaire est en cours de modification en vue de son évolution prochaine."}, {"g": "Ultra-Lune", "t": "Sa carapace est très solide et résiste sans peine aux assauts des Picassaut. Si elle bascule, par contre, son contenu s’éparpille au sol."}, {"g": "Let's Go Pikachu", "t": "Il renforce sa carapace pour se protéger, mais un coup puissant peut l’en déloger."}, {"g": "Épée", "t": "En attendant sa prochaine évolution, il ne peut que durcir sa carapace et rester immobile pour éviter de se faire attaquer."}, {"g": "Bouclier", "t": "Bien que son corps soit entouré d’une carapace solide, l’intérieur est si mou qu’il ne résisterait pas à une attaque violente."}],
  12: [{"g": "Noir", "t": "Il raffole du nectar des fleurs. Il est capable de repérer la plus petite quantité de pollen."}, {"g": "Y", "t": "Ses ailes sont recouvertes d’une poudre les protégeant de la pluie. Ce Pokémon peut donc voler pendant de grosses averses."}, {"g": "Rubis Oméga", "t": "Papilusion est très doué pour repérer le délicieux nectar qu’il butine dans les fleurs. Il peut détecter, extraire et transporter le nectar de fleurs situées à plus de 10 km de son nid."}, {"g": "Soleil", "t": "Si l’on regarde ses grands yeux de plus près, on remarque qu’il s’agit en réalité d’une multitude de petits yeux réunis."}, {"g": "Lune", "t": "Pour se défendre contre les agressions d’autres Pokémon, il bat des ailes en éparpillant autour de lui un nuage de poussière toxique."}, {"g": "Ultra-Soleil", "t": "Lorsqu’il surprend un Pokémon oiseau attaquant un Chenipan, il répand les écailles très toxiques qui recouvrent ses ailes sur l’assaillant."}, {"g": "Ultra-Lune", "t": "Il raffole du nectar des plus jolies fleurs. Dans les prairies, les luttes territoriales l’opposant à Bombydou sont impitoyables."}, {"g": "Let's Go Pikachu", "t": "Ses ailes sont enduites d’une poudre toxique imperméable lui permettant de voler sous la pluie."}, {"g": "Épée", "t": "En combat, il bat des ailes très rapidement pour projeter de la poudre toxique sur ses ennemis."}, {"g": "Bouclier", "t": "Il ramasse du nectar chaque jour et l’agglutine sur les poils de ses pattes pour le transporter jusqu’à son nid."}],
  13: [{"g": "Noir", "t": "Il mange chaque jour son poids en feuilles. Il utilise l’aiguillon sur sa tête pour repousser l’ennemi."}, {"g": "X", "t": "On trouve souvent ce Pokémon dans les forêts et les hautes herbes. L’aiguillon de 5 cm sur sa tête contient un venin très toxique."}, {"g": "Y", "t": "Son aiguillon empoisonné est très dangereux. Son corps est coloré afin de repousser ses ennemis."}, {"g": "Rubis Oméga", "t": "L’odorat d’Aspicot est extrêmement développé. Il lui suffit de renifler ses feuilles préférées avec son gros appendice nasal pour les reconnaître entre mille."}, {"g": "Let's Go Pikachu", "t": "L’aiguillon sur son front est très pointu. Il se cache dans les bois et les hautes herbes, où il se gave de feuilles."}],
  14: [{"g": "Noir", "t": "Il se cache sous les feuilles et les branches pour fuir les prédateurs en attendant d’évoluer."}, {"g": "X", "t": "Incapable de se déplacer de lui-même, il se défend en durcissant sa carapace."}, {"g": "Rubis Oméga", "t": "Coconfort est la plupart du temps immobile et reste accroché à un arbre. Cependant, intérieurement, il est très actif, car il se prépare pour sa prochaine évolution. En touchant sa carapace, on peut sentir sa chaleur."}, {"g": "Let's Go Pikachu", "t": "Il peut à peine bouger. Quand il est menacé, il sort parfois son aiguillon pour empoisonner ses ennemis."}],
  15: [{"g": "Noir", "t": "Il virevolte rapidement autour de l’ennemi et frappe de son dard empoisonné avant de décamper."}, {"g": "X", "t": "Il se sert de ses trois aiguillons empoisonnés pour attaquer sans relâche ses adversaires."}, {"g": "Y", "t": "On le voit souvent voler dans un essaim. Il vole très rapidement, piquant sans cesse ses adversaires de son dard toxique."}, {"g": "Rubis Oméga", "t": "Dardargnan est extrêmement possessif. Il vaut mieux ne pas toucher son nid si on veut éviter d’avoir des ennuis. Lorsqu’ils sont en colère, ces Pokémon attaquent en masse."}, {"g": "Let's Go Pikachu", "t": "Il se sert de ses trois aiguillons empoisonnés situés sur les pattes avant et l’abdomen pour attaquer sans relâche ses adversaires."}],
  16: [{"g": "Noir", "t": "Ce Pokémon docile préfère éviter le combat. Toutefois, il se montre très féroce quand on l’agresse."}, {"g": "X", "t": "On l’aperçoit souvent dans les forêts. Avec ses ailes, il brasse l’air près du sol pour projeter du sable."}, {"g": "Rubis Oméga", "t": "Roucool a un excellent sens de l’orientation. Il est capable de retrouver son nid sans jamais se tromper, même s’il est très loin de chez lui et dans un environnement qu’il ne connaît pas."}, {"g": "Let's Go Pikachu", "t": "De nature très docile, il préfère projeter du sable pour se défendre plutôt que contre-attaquer."}],
  17: [{"g": "Noir", "t": "Il survole son vaste territoire en quête d’une proie avant de fondre sur elle toutes griffes en avant."}, {"g": "X", "t": "Grâce à ses griffes très puissantes, il est capable de transporter des Noeunoeuf vers un nid éloigné de plus de 100 km."}, {"g": "Y", "t": "Il protège son territoire avec ardeur et repousse à coups de bec tout intrus."}, {"g": "Rubis Oméga", "t": "Roucoups utilise une vaste surface pour son territoire. Ce Pokémon surveille régulièrement son espace aérien. Si quelqu’un pénètre sur son territoire, il corrige l’ennemi sans pitié d’un coup de ses terribles serres."}, {"g": "Let's Go Pikachu", "t": "Ce Pokémon est très endurant. Il survole en permanence son territoire pour chasser."}],
  18: [{"g": "Noir", "t": "En battant des ailes de toutes ses forces, Roucarnage génère une rafale à en déraciner les arbres."}, {"g": "X", "t": "Il survole la surface de l’eau pour repérer une proie et plonge en piqué pour l’attraper."}, {"g": "Y", "t": "Roucarnage déploie ses ailes majestueuses pour effrayer ses ennemis. Il peut voler à Mach 2."}, {"g": "Rubis Oméga", "t": "Ce Pokémon est doté d’un plumage magnifique et luisant. Bien des Dresseurs sont captivés par la beauté fatale de sa huppe et décident de choisir Roucarnage comme leur Pokémon favori."}, {"g": "Let's Go Pikachu", "t": "Ce Pokémon vole à Mach 2 quand il chasse. Ses grandes serres sont des armes redoutables."}],
  19: [{"g": "Noir", "t": "D’une prudence extrême, sa nature robuste lui permet de s’adapter à tous les terrains."}, {"g": "X", "t": "Vivant là où se trouve la nourriture, ce charognard passe ses journées à la rechercher."}, {"g": "Y", "t": "Les dents de Rattata sont longues et tranchantes. Comme elles poussent sans arrêt, il doit ronger tout ce qu’il trouve pour pouvoir les tailler."}, {"g": "Rubis Oméga", "t": "Rattata est extrêmement prudent. Même lorsqu’il est endormi, il fait pivoter ses oreilles pour écouter autour de lui. En ce qui concerne son habitat, il n’est vraiment pas difficile. Il peut faire son nid n’importe où."}, {"g": "Soleil", "t": "Il doit toujours prendre soin de ses incisives car elles poussent sans arrêt. S’il n’a rien pour les limer, il se rabattra sur un pilier."}, {"g": "Lune", "t": "Un Pokémon très résistant, capable de survivre même dans des milieux très insalubres. Il prolifère si l’on n’y prend pas garde."}, {"g": "Ultra-Soleil", "t": "Ses incisives poussent tout au long de sa vie. Si elles dépassent une certaine longueur, il ne peut plus s’alimenter et meurt de faim."}, {"g": "Ultra-Lune", "t": "Prenez garde à ce Pokémon très répandu : ses puissantes incisives sont si acérées qu’elles peuvent couper des troncs d’arbre."}, {"g": "Let's Go Pikachu", "t": "Il peut ronger n’importe quoi avec ses deux dents. Quand on en voit un, il y en a certainement 40 dans le coin."}],
  20: [{"g": "Y", "t": "Ses pattes arrière lui permettent de traverser les rivières. Il est toujours en quête de nourriture."}, {"g": "Noir", "t": "Il grignote sans cesse pour apaiser la poussée de ses crocs. Il peut transpercer un mur de parpaings."}, {"g": "Rubis Oméga", "t": "Les crocs robustes de Rattatac poussent constamment. Pour éviter qu’ils raclent le sol, il se fait les dents sur des cailloux ou des troncs d’arbre. Il lui arrive même de ronger les murs des maisons."}, {"g": "Soleil", "t": "C’est un très bon nageur. Les doigts de ses pattes arrière sont palmés, ce qui lui permet de traverser les rivières et parfois même les mers."}, {"g": "Lune", "t": "Beaucoup plus agressif qu’il n’en a l’air, mieux vaut éviter de lui tendre la main si l’on veut la récupérer entière."}, {"g": "Ultra-Soleil", "t": "Les petites palmes de ses pattes postérieures lui permettraient de se rendre d’île en île à la nage afin d’échapper à ses prédateurs."}, {"g": "Ultra-Lune", "t": "Il se sert de ses moustaches pour garder l’équilibre. Que le Rattatac soit apprivoisé ou non, ne le touchez pas ou il vous mordrait !"}, {"g": "Let's Go Pikachu", "t": "Ses pattes arrière sont palmées. Il peut donc poursuivre sa proie dans les cours d’eau et les rivières."}],
  21: [{"g": "Noir", "t": "Il fait battre vigoureusement ses petites ailes pour voler et cherche à manger dans l’herbe avec le bec."}, {"g": "X", "t": "Très protecteur de son territoire, il bat vite des ailes pour se déplacer à toute allure."}, {"g": "Y", "t": "Il chasse les insectes dans les hautes herbes. Ses petites ailes lui permettent de voler très vite."}, {"g": "Rubis Oméga", "t": "Piafabec crie tellement fort qu’il peut être entendu à 1 km de distance. Ces Pokémon se préviennent d’un danger en entonnant une mélopée très aiguë, qu’ils se renvoient les uns les autres, comme un écho."}, {"g": "Soleil", "t": "Ses petites ailes le handicapent pour voler. Il préfère se déplacer en hâte et piquer les Pokémon Insecte dans les hautes herbes."}, {"g": "Lune", "t": "Il est doté d’un appétit insatiable. Les fermiers assaillis par des Pokémon Insecte prennent grand soin des Piafabec."}, {"g": "Ultra-Soleil", "t": "Un Pokémon téméraire qui n’hésite pas à affronter des Pokémon plus gros que lui pour protéger son territoire."}, {"g": "Ultra-Lune", "t": "Ses courtes ailes ne lui permettent pas de voler sur de longues distances. Il quadrille son territoire pour picorer les Pokémon Insecte."}, {"g": "Let's Go Pikachu", "t": "Il est incapable de voler à haute altitude. Il se déplace très vite pour protéger son territoire."}],
  22: [{"g": "Noir", "t": "Il a assez d’énergie pour voler toute la journée avec ses grandes ailes. Il frappe de son bec acéré."}, {"g": "X", "t": "Ses ailes géantes lui permettent de voler sur de longues distances sans qu’il ait besoin de se reposer."}, {"g": "Rubis Oméga", "t": "On reconnaît un Rapasdepic à son long cou et à son bec allongé. Ces attributs lui permettent d’attraper facilement ses proies dans la terre ou dans l’eau. Il bouge son bec long et fin avec une grande agilité."}, {"g": "Soleil", "t": "Un Pokémon robuste et extrêmement endurant. Il est capable de voler du matin au soir tout en transportant de lourdes charges."}, {"g": "Lune", "t": "Un Pokémon fort ancien, qui a même été identifié sur des fresques antiques."}, {"g": "Ultra-Soleil", "t": "Si vous vous promenez sur le territoire d’un Rapasdepic en transportant de la nourriture, vous risquez de vite la voir s’envoler !"}, {"g": "Ultra-Lune", "t": "À Alola, il se repaît de Pokémon poissons. On le voit souvent voler en cercle au-dessus des flots en quête de nourriture."}, {"g": "Let's Go Pikachu", "t": "Un Pokémon très ancien. S’il perçoit un danger, il fuit instantanément à haute altitude."}],
  23: [{"g": "Noir", "t": "Il se faufile dans l’herbe sans un bruit et frappe dans le dos quand sa proie s’y attend le moins."}, {"g": "X", "t": "Plus il est âgé, plus son corps est long. Il se love autour des arbres pour se reposer."}, {"g": "Y", "t": "Il se déplace en silence pour dévorer des œufs de Roucool ou de Piafabec."}, {"g": "Rubis Oméga", "t": "Abo s’enroule en spirale pour dormir. Sa tête reste relevée de telle sorte que cette position lui permette de réagir rapidement si une menace survenait."}, {"g": "Ultra-Soleil", "t": "Il peut se déboîter la mâchoire pour avaler tout rond des proies plus grosses que lui. Il se replie ensuite sur lui-même pour digérer."}, {"g": "Ultra-Lune", "t": "Il aime tout particulièrement les œufs des Pokémon oiseaux. Comme il les avale d’un coup, il lui arrive de s’étouffer et de s’évanouir."}, {"g": "Let's Go Pikachu", "t": "Plus il est âgé, plus son corps est long. La nuit, il s’enroule autour de branches d’arbres pour se reposer."}],
  24: [{"g": "Noir", "t": "Il utilise la marque sur son ventre pour intimider l’ennemi. Il étouffe l’ennemi pétrifié par la peur."}, {"g": "X", "t": "Les motifs sur son corps ressemblent à un visage menaçant. Les adversaires les plus craintifs fuient à la seule vue de ce Pokémon."}, {"g": "Y", "t": "Pour apeurer ses ennemis, il gonfle sa poitrine et émet d’étranges sons avec sa bouche."}, {"g": "Rubis Oméga", "t": "Ce Pokémon doté d’une force extraordinaire peut étrangler ses proies avec son corps. Il peut même écraser des tonneaux métalliques. Une fois sous l’étreinte d’Arbok, il est impossible de lui échapper."}, {"g": "Ultra-Soleil", "t": "Une étude récente aurait recensé plus de vingt motifs différents pouvant orner le devant du capuchon des Arbok."}, {"g": "Ultra-Lune", "t": "Il intimide sa proie grâce au motif situé sur le devant de son capuchon, puis l’enserre jusqu’à ce que son cœur cesse de battre."}, {"g": "Let's Go Pikachu", "t": "Des études ont révélé que les marques effrayantes de son corps pouvaient former six motifs différents."}],
  25: [{"g": "Noir", "t": "Il lui arrive de remettre d’aplomb un Pikachu allié en lui envoyant une décharge électrique."}, {"g": "X", "t": "Il élève sa queue pour surveiller les environs. Elle attire souvent la foudre dans cette position."}, {"g": "Y", "t": "Pikachu a de petites poches pleines d’électricité sur ses joues. S’il se sent menacé, il laisse s’échapper des décharges électriques."}, {"g": "Rubis Oméga", "t": "Chaque fois que Pikachu découvre quelque chose de nouveau, il envoie un arc électrique. Lorsqu’on tombe sur une Baie carbonisée, ça signifie sans doute qu’un de ces Pokémon a envoyé une charge trop forte."}, {"g": "Saphir Alpha", "t": "Ce Pokémon dispose de petites poches dans les joues pour stocker de l’électricité. Elles semblent se charger pendant que Pikachu dort. Il libère parfois un peu d’électricité lorsqu’il n’est pas encore bien réveillé."}, {"g": "Soleil", "t": "Un projet de centrale électrique fonctionnant en rassemblant une foule de Pikachu a été récemment annoncé."}, {"g": "Lune", "t": "Un Pokémon capable de condenser l’électricité. Il doit décharger l’énergie accumulée de temps en temps au risque d’accroître son stress."}, {"g": "Ultra-Soleil", "t": "Son corps peut accumuler de l’électricité. Les forêts abritant des groupes de Pikachu sont d’ailleurs souvent frappées par la foudre."}, {"g": "Ultra-Lune", "t": "Quand il dort, il génère de l’électricité dans les poches de ses joues. S’il manque de sommeil, il ne peut plus émettre qu’un faible courant."}, {"g": "Let's Go Pikachu", "t": "Ce Pokémon des bois accumule de l’électricité dans les poches de ses joues. Il ne faut pas les toucher sous peine de recevoir une décharge."}, {"g": "Épée", "t": "Plus la puissance électrique de Pikachu est élevée, plus les poches de ses joues sont extensibles."}, {"g": "Bouclier", "t": "Les Pikachu se disent bonjour en se frottant la queue et en y faisant passer du courant électrique."}],
  26: [{"g": "Noir", "t": "Il se protège des décharges grâce à sa queue qui dissipe l’électricité dans le sol."}, {"g": "X", "t": "Quand il se charge en électricité, ses muscles se contractent et il devient plus agressif."}, {"g": "Y", "t": "Il peut terrasser des ennemis bien plus imposants en libérant une décharge de 100 000 V."}, {"g": "Rubis Oméga", "t": "Si ses joues contiennent trop d’électricité, Raichu plante sa queue dans le sol pour se décharger. On trouve des parcelles de terre brûlée à proximité du nid de ce Pokémon."}, {"g": "Saphir Alpha", "t": "Ce Pokémon libère un faible champ électrique tout autour de son corps, ce qui le rend légèrement lumineux dans le noir. Raichu plante sa queue dans le sol pour évacuer de l’électricité."}, {"g": "Soleil", "t": "Ce Pokémon peut accumuler jusqu’à 100 000 volts. Il peut ainsi assommer un éléphant juste en le touchant."}, {"g": "Lune", "t": "Il devient plus agressif au fur et à mesure qu’il accumule de l’électricité. Même son Dresseur doit faire attention à ne pas se faire attaquer."}, {"g": "Ultra-Soleil", "t": "Plus il est chargé en électricité, plus il se montre agressif. D’aucuns pensent que ce courant électrique le stresse."}, {"g": "Ultra-Lune", "t": "Ce Pokémon est très rare, car la plupart des Dresseurs lui préfèrent Pikachu."}, {"g": "Let's Go Pikachu", "t": "Il devient agressif quand il emmagasine de l’électricité. Il brille alors dans le noir."}, {"g": "Épée", "t": "Sa longue queue agit comme une prise de terre qui l’empêche d’être affecté par le courant à haute tension accumulé dans son corps."}, {"g": "Bouclier", "t": "Si ses joues sont à court d’énergie, il lève la queue et capte l’électricité contenue dans l’atmosphère."}],
  27: [{"g": "Noir", "t": "Il vit sur des terres arides épargnées par la pluie. Il se roule en boule pour se protéger."}, {"g": "X", "t": "Il s’enterre et vit dans les sous-sols. S’il se sent menacé, il se met en boule pour se protéger."}, {"g": "Y", "t": "Détestant l’eau, il vit dans de profondes tanières des régions arides. Il aime se rouler en boule."}, {"g": "Rubis Oméga", "t": "Le corps de Sabelette lui permet d’économiser l’eau qu’il absorbe, afin de survivre longtemps dans le désert. Ce Pokémon s’enroule sur lui-même pour se protéger de ses ennemis."}, {"g": "Saphir Alpha", "t": "Sabelette a une peau très sèche et extrêmement dure. Ce Pokémon peut s’enrouler sur lui-même pour repousser les attaques. La nuit, il s’enterre dans le sable du désert pour dormir."}, {"g": "Soleil", "t": "Il peut se changer en boule parfaitement ronde et rouler à toute allure à travers le désert."}, {"g": "Lune", "t": "Il vit principalement dans les zones désertiques où il ne pleut jamais. Il creuse dans le sol pour dénicher des Pokémon Insecte."}, {"g": "Ultra-Soleil", "t": "Il vit dans les régions où il pleut rarement. Quand il est en danger, il se roule en boule pour protéger son ventre, qui est son point faible."}, {"g": "Ultra-Lune", "t": "Lorsque sa peau est saturée d’humidité, il se dirige vers un volcan et se sèche à la chaleur du magma."}, {"g": "Let's Go Pikachu", "t": "Son corps est sec. Quand la nuit déploie ses ailes de fraîcheur, son épiderme se couvre de rosée."}, {"g": "Épée", "t": "Il aime se rouler dans le sable des zones désertiques pour se débarrasser des traces de terre et d’humidité qui lui collent à la peau."}, {"g": "Bouclier", "t": "Il creuse le sol pour construire sa tanière. Rien n’arrête ses griffes acérées, pas même la roche la plus solide."}],
  28: [{"g": "Noir", "t": "Il se met en boule pour percuter l’ennemi. Ses épines aiguisées font beaucoup de dégâts."}, {"g": "X", "t": "Il creuse si vite qu’il peut briser ses épines et ses griffes. Mais elles repoussent en une journée."}, {"g": "Y", "t": "Il se roule en boule hérissée de piques s’il est menacé. Il peut ainsi s’enfuir ou attaquer."}, {"g": "Rubis Oméga", "t": "Le corps de Sablaireau est recouvert de pointes très dures, qui sont des extensions de sa peau. Une fois par an, ce Pokémon mue et les vieilles pointes tombent, remplacées par de nouvelles."}, {"g": "Saphir Alpha", "t": "Sablaireau peut enrouler son corps pour prendre la forme d’une balle hérissée de pointes. Ce Pokémon essaie de faire peur à son ennemi en le frappant avec ses pointes. Puis, il se rue sur lui avec ses griffes acérées."}, {"g": "Soleil", "t": "Ses griffes et épines sont tranchantes, mais elles se brisent facilement. Cela dit, il n’en a que faire, puisqu’elles repoussent le lendemain."}, {"g": "Lune", "t": "Il escalade les arbres avec ses griffes. Quand une proie passe à proximité, il se laisse tomber dessus toutes épines dressées."}, {"g": "Ultra-Soleil", "t": "Ses épines et ses griffes se cassent souvent. Ces pointes brisées peuvent servir d’outils pour creuser le sol."}, {"g": "Ultra-Lune", "t": "Ses grosses griffes lui permettent de grimper aux arbres sans peine. Il n’est pas rare de voir un Sablaireau endormi dans les frondaisons."}, {"g": "Let's Go Pikachu", "t": "Ses griffes sont redoutables. Si l’une d’elles se casse en combat, elle repousse en un jour."}, {"g": "Épée", "t": "Plus son habitat est sec, plus ses épines dorsales deviennent dures et lisses."}, {"g": "Bouclier", "t": "Il grimpe aux arbres grâce à ses griffes acérées et fait tomber des Baies pour les Sabelette qui attendent au sol."}],
  29: [{"g": "Noir", "t": "Bien qu’il rechigne à se battre, une goutte du poison sécrété par ses piquants peut s’avérer fatale."}, {"g": "X", "t": "Ce Pokémon est hérissé de dards empoisonnés. Les femelles ont une corne plus petite."}, {"g": "Y", "t": "Petit et docile, il se protège avec sa minuscule corne empoisonnée lorsqu’il est attaqué."}, {"g": "Rubis Oméga", "t": "Nidoran♀ est couvert de pointes qui sécrètent un poison puissant. On pense que ce petit Pokémon a développé ces pointes pour se défendre. Lorsqu’il est en colère, une horrible toxine sort de sa corne."}, {"g": "Let's Go Pikachu", "t": "Un Pokémon paisible qui n’aime pas se battre. Sa petite corne est empoisonnée."}, {"g": "Épée", "t": "Son odorat est plus développé que celui du mâle. Quand Nidoran♀ cherche à manger, il reste dans le sens du vent, qu’il détecte avec ses vibrisses."}, {"g": "Bouclier", "t": "Ce Pokémon se nourrit de Baies en les ouvrant avec ses incisives. Le bout de sa corne est plus arrondi que celui du mâle."}],
  30: [{"g": "Noir", "t": "Ce Pokémon dresse ses piquants en cas de danger. Ils poussent moins vite que ceux de Nidorino."}, {"g": "X", "t": "La femelle a un tempérament doux. Elle émet des cris ultrasoniques capables de déstabiliser ses ennemis."}, {"g": "Y", "t": "Pour nourrir ses petits, il mâche les aliments pour les rendre tendres et il les recrache à ses bébés."}, {"g": "Rubis Oméga", "t": "Lorsqu’un Nidorina est avec ses amis ou sa famille, il replie ses pointes pour ne pas blesser ses proches. Ce Pokémon devient vite nerveux lorsqu’il est séparé de son groupe."}, {"g": "Let's Go Pikachu", "t": "Quand ce Pokémon s’abrite au fond de son terrier, ses cornes se rétractent. C’est signe qu’il est détendu."}, {"g": "Épée", "t": "On pense que sa corne frontale s’est atrophiée pour lui permettre de nourrir ses petits sans les blesser."}, {"g": "Bouclier", "t": "Si un danger menace le groupe, ces Pokémon se réunissent et l’affrontent en émettant des ultrasons en chœur."}],
  31: [{"g": "Noir", "t": "Son corps est recouvert d’écailles solides. Il donnera sa vie pour secourir les petits de son terrier."}, {"g": "X", "t": "Il se sert de son corps lourdement protégé pour empêcher les prédateurs d’accéder à son nid."}, {"g": "Y", "t": "Son corps est recouvert d’écailles en forme de pointes. Quand ce Pokémon s’énerve, ses pointes se dressent de façon menaçante."}, {"g": "Rubis Oméga", "t": "Le corps de Nidoqueen est protégé par des écailles extrêmement dures. Il aime envoyer ses ennemis voler en leur fonçant dessus. Ce Pokémon utilise toute sa puissance lorsqu’il protège ses petits."}, {"g": "Let's Go Pikachu", "t": "Son corps musclé est recouvert de dures écailles. On dit qu’elles peuvent repousser."}, {"g": "Épée", "t": "Il est plus doué pour se défendre que pour attaquer. Grâce à son blindage d’écailles, il protège ses petits de toute agression."}, {"g": "Bouclier", "t": "Ce Pokémon calme les petits de son espèce en les plaçant entre ses épines dorsales. Dans ce cas, elles ne libèrent pas de poison."}],
  32: [{"g": "Noir", "t": "Il jauge le terrain en laissant ses oreilles dépasser de l’herbe. Il se défend avec sa corne toxique."}, {"g": "Y", "t": "Ce Pokémon agite ses oreilles comme pour entendre tout ce qui se passe au loin. Il déploie des aiguillons toxiques quand il est en colère."}, {"g": "Rubis Oméga", "t": "Nidoran♂ a développé des muscles pour bouger ses oreilles. Ainsi, il peut les orienter à sa guise. Ce Pokémon peut entendre le plus discret des bruits."}, {"g": "Let's Go Pikachu", "t": "Ses grandes oreilles sont toujours dressées et à l’affût de ce qu’il se passe alentour. S’il est menacé, il se défend avec ses dards venimeux."}, {"g": "Épée", "t": "Sa corne frontale contient un puissant poison. Les grandes oreilles de ce Pokémon très prudent sont constamment dressées."}, {"g": "Bouclier", "t": "Malgré sa petite taille, il est très téméraire. Afin de protéger sa compagne, il est prêt à se battre et à risquer sa vie."}],
  33: [{"g": "Noir", "t": "D’un tempérament violent, il empale l’ennemi sur sa corne qui distille un poison puissant."}, {"g": "X", "t": "Il dresse ses oreilles à l’affût d’un bruit suspect et attaque toute menace se rapprochant de lui."}, {"g": "Y", "t": "Très agressif, il est prompt à répondre à la violence. La corne sur sa tête est venimeuse."}, {"g": "Rubis Oméga", "t": "Nidorino dispose d’une corne plus dure que du diamant. S’il sent une présence hostile, toutes les pointes de son dos se hérissent d’un coup, puis il défie son ennemi."}, {"g": "Let's Go Pikachu", "t": "Sa corne est venimeuse. Si elle perce un ennemi, elle lui injecte un poison violent."}, {"g": "Épée", "t": "Il erre à la recherche d’une Pierre Lune, brisant tous les rochers sur son passage avec sa corne plus solide qu’un diamant."}, {"g": "Bouclier", "t": "D’un naturel nerveux, il est prompt à se battre. Lorsqu’il a une montée d’adrénaline, la concentration de son poison augmente."}],
  34: [{"g": "Noir", "t": "Un coup de sa puissante queue peut briser un poteau téléphonique comme une allumette."}, {"g": "X", "t": "On le reconnaît facilement grâce à sa peau dure comme de la pierre ainsi qu’à sa grosse corne pleine de poison."}, {"g": "Rubis Oméga", "t": "L’épaisse queue de Nidoking est d’une puissance incroyable. En un seul coup, il peut renverser une tour métallique. Lorsque ce Pokémon se déchaîne, plus rien ne peut l’arrêter."}, {"g": "Let's Go Pikachu", "t": "Ses charges sont dévastatrices grâce à sa peau d’acier. Sa corne perce même le diamant."}, {"g": "Épée", "t": "Lorsqu’il s’énerve, il devient incontrôlable, mais il retrouve son calme face à Nidoqueen, sa compagne de longue date."}, {"g": "Bouclier", "t": "Très fier de sa force, il se bat vigoureusement à l’aide de sa queue robuste et de sa corne capable de briser le diamant."}],
  35: [{"g": "Noir", "t": "On dit que ceux qui voient danser un groupe de Mélofée sous la pleine lune connaîtront un grand bonheur."}, {"g": "Y", "t": "La lumière de la lune qu’il emmagasine dans ses ailes dorsales lui permet de flotter dans les airs."}, {"g": "Rubis Oméga", "t": "Les nuits de pleine lune, des groupes de ces Pokémon sortent jouer. Lorsque l’aube commence à poindre, les Mélofée fatigués rentrent dans leur retraite montagneuse et vont dormir, blottis les uns contre les autres."}, {"g": "Soleil", "t": "Son apparence et ses mimiques charmantes lui ont valu de nombreux fans de tous âges, mais il reste un Pokémon relativement rare."}, {"g": "Lune", "t": "Ce Pokémon retrouve ses congénères et danse lors des nuits de pleine lune. Un champ magnétique mystérieux s’étend alors alentour."}, {"g": "Ultra-Soleil", "t": "Il est très rare en dépit de sa popularité. Ne le laissez pas sans surveillance, car il risquerait de se faire dérober par un voleur de Pokémon !"}, {"g": "Ultra-Lune", "t": "Quand ses ailes absorbent la lumière de la lune, elles brillent légèrement et le font léviter pour lui permettre de danser dans les airs."}, {"g": "Let's Go Pikachu", "t": "Adoré pour son aspect mignon et joyeux, on le suppose rare, car on en voit très peu de spécimens."}, {"g": "Bouclier", "t": "Son comportement et son cri adorables font de lui un Pokémon très populaire. Malheureusement, il est difficile d’en croiser un spécimen."}],
  36: [{"g": "Noir", "t": "Il est très farouche et se laisse rarement approcher. De plus, il détecte les sons à plus d’1 km."}, {"g": "X", "t": "Il aime le calme des montagnes. Son ouïe exceptionnelle entendrait une aiguille tomber à 1 km."}, {"g": "Y", "t": "Ce Pokémon est une sorte de petite fée très rare. Il court vite se cacher s’il aperçoit un être humain."}, {"g": "Rubis Oméga", "t": "Les Mélodelfe se déplacent en sautant doucement, comme s’ils volaient. Leur démarche légère leur permet même de marcher sur l’eau. On raconte qu’ils se promènent sur les lacs, les soirs où la lune est claire."}, {"g": "Soleil", "t": "Il n’aime pas être aperçu par les humains. Il préfère donc vivre paisiblement en groupes au fond des montagnes."}, {"g": "Lune", "t": "Une tradition raconte qu’apercevoir un Mélodelfe gambader joyeusement signifie que l’on fera un heureux mariage."}, {"g": "Ultra-Soleil", "t": "Il préfère vivre au fond des montagnes, loin des humains et des Pokémon, car il peut entendre une aiguille tomber à un kilomètre de distance."}, {"g": "Ultra-Lune", "t": "Selon certains scientifiques, c’est parce qu’il a le mal du pays qu’il fixe le ciel les soirs de pleine lune."}, {"g": "Let's Go Pikachu", "t": "Ce Pokémon à l’aspect féérique semble très attaché à son habitat et ne se montre que rarement."}, {"g": "Épée", "t": "Ce Pokémon s’apparente à une petite fée qui n’apparaît que rarement devant les humains. Il court se cacher dès qu’il ressent une présence."}, {"g": "Bouclier", "t": "Capable d’entendre une aiguille tomber à plus d’un kilomètre, ce Pokémon préfère les endroits calmes et isolés."}],
  37: [{"g": "Noir", "t": "Il envoie des boules de feu. Avec l’âge, ses six queues en forment de nouvelles."}, {"g": "X", "t": "Il n’a qu’une seule queue à la naissance. Sa queue se divise à la pointe au fil des ans."}, {"g": "Y", "t": "Quand il est jeune, ce Pokémon a six queues magnifiques. De nouvelles queues apparaissent tout au long de sa croissance."}, {"g": "Rubis Oméga", "t": "À sa naissance, Goupix a une queue blanche. Cette queue se divise en six si le Pokémon reçoit de l’amitié de la part de son Dresseur. Les six queues sont courbées et magnifiques."}, {"g": "Saphir Alpha", "t": "À l’intérieur du corps de Goupix se trouve une flamme qui ne s’éteint jamais. Pendant la journée, lorsque la température augmente, ce Pokémon crache des flammes pour éviter que son corps ne devienne trop chaud."}, {"g": "Soleil", "t": "Un Pokémon très populaire de par son pelage et ses superbes queues. Au fur et à mesure de sa croissance, elles se multiplient en se divisant."}, {"g": "Lune", "t": "Certaines personnes prennent ce Pokémon pour un fantôme à cause des flammes qui sortent de sa bouche, similaires à des âmes de défunts."}, {"g": "Ultra-Soleil", "t": "Ses queues magnifiques en font un Pokémon très populaire. Il faut toutefois les lui brosser fréquemment pour éviter les nœuds."}, {"g": "Ultra-Lune", "t": "Il attrape ses proies en manipulant des boules de feu. Élevé depuis son plus jeune âge, il se révélera aussi affectueux qu’un Pokémon Chiot."}, {"g": "Let's Go Pikachu", "t": "Sa fourrure et sa queue sont magnifiques. Cette dernière se divise lors de la croissance."}, {"g": "Bouclier", "t": "Avec l’âge, la fourrure de ses six queues devient de plus en plus belle et soyeuse. Elle est chaude au toucher."}],
  38: [{"g": "Noir", "t": "On raconte que ses neuf queues détiennent un pouvoir mystique. Il peut vivre pendant mille ans."}, {"g": "X", "t": "Il a neuf longues queues et une fourrure qui brille comme de l’or. On dit qu’il peut vivre 1 000 ans."}, {"g": "Y", "t": "Il est très intelligent et rancunier. Attrapez une de ses queues et il vous maudira pour 1 000 ans."}, {"g": "Rubis Oméga", "t": "Feunard peut envoyer un inquiétant rayon avec ses yeux rouge vif pour prendre le contrôle de l’esprit de son ennemi. On raconte que ce Pokémon peut vivre 1 000 ans."}, {"g": "Saphir Alpha", "t": "La légende raconte que Feunard est apparu lorsque neuf sorciers aux pouvoirs sacrés décidèrent de fusionner. Ce Pokémon est très intelligent. Il comprend la langue des hommes."}, {"g": "Soleil", "t": "L’aura mystique de ce Pokémon est telle qu’une légende raconte que neuf grands sages ont un jour fusionné pour devenir un Feunard."}, {"g": "Lune", "t": "On raconte que ce Pokémon vit 1 000 ans. Ses pouvoirs lui permettent de contrôler les flammes à volonté pour griller ses proies."}, {"g": "Ultra-Soleil", "t": "Un Pokémon très rancunier. S’il est offensé, son ressentiment peut poursuivre le coupable et sa descendance pendant un millénaire."}, {"g": "Ultra-Lune", "t": "Un Pokémon extrêmement intelligent qui crache des flammes vacillantes pour hypnotiser et capturer ses proies."}, {"g": "Let's Go Pikachu", "t": "Selon la légende, neuf sages se sont unis et incarnés dans ce Pokémon mystique."}, {"g": "Épée", "t": "On dit qu’il vit 1 000 ans et que chacune de ses queues a un pouvoir magique."}, {"g": "Bouclier", "t": "Il est très intelligent et rancunier. Quiconque attrape une de ses queues se fera maudire pour 1 000 ans."}],
  39: [{"g": "Noir", "t": "Lorsqu’il roule ses grands yeux ronds, il entonne une berceuse qui endort son auditoire."}, {"g": "X", "t": "Il hypnotise ses ennemis grâce à ses grands yeux avant de les plonger dans un profond sommeil en chantant une douce mélopée."}, {"g": "Y", "t": "En se gonflant, il peut chanter une longue berceuse qui endort inévitablement ses adversaires."}, {"g": "Rubis Oméga", "t": "Rondoudou utilise ses cordes vocales pour ajuster librement la longueur d’onde de sa voix. Cela permet à ce Pokémon de chanter en utilisant une longueur d’onde qui endort ses ennemis."}, {"g": "Saphir Alpha", "t": "Lorsque ce Pokémon chante, il ne s’arrête pas pour respirer. Quand il se bat contre un adversaire qu’il ne peut pas facilement endormir, Rondoudou reste donc sans respirer, mettant sa vie en danger."}, {"g": "Soleil", "t": "Ce Pokémon aime inspirer profondément et chanter une mélodie mystérieuse qui endort immédiatement tous ceux qui l’entendent."}, {"g": "Lune", "t": "Cette espèce possède une tessiture de douze octaves, mais la beauté du chant dépend des efforts déployés par chaque individu."}, {"g": "Ultra-Soleil", "t": "Les rayons literie des magasins proposent généralement des CD de berceuses chantées par des Rondoudou."}, {"g": "Ultra-Lune", "t": "Les airs qu’il chante varient selon la région où il habite. Certains chants s’apparentent à des hurlements."}, {"g": "Let's Go Pikachu", "t": "Il déstabilise ses adversaires grâce à son regard, puis chante une berceuse pour les endormir."}, {"g": "Épée", "t": "Il a une des meilleures capacités pulmonaires parmi les Pokémon. Il chante des berceuses à son adversaire jusqu’à ce que sommeil s’ensuive."}, {"g": "Bouclier", "t": "Il module librement la longueur d’onde de sa voix pour chanter une étrange mélodie qui endort à tous les coups celui qui l’écoute."}],
  40: [{"g": "Noir", "t": "Sa fourrure est d’une douceur incomparable au toucher. Il peut gonfler en aspirant de l’air."}, {"g": "X", "t": "Leur fourrure est si douce que s’ils se font des câlins, ils ne voudront plus se séparer."}, {"g": "Y", "t": "En cas de danger, il gonfle d’air son corps doux et potelé dans des proportions gigantesques."}, {"g": "Rubis Oméga", "t": "Grodoudou a des yeux immenses et écarquillés. La surface de ses yeux est couverte d’une fine couche de larmes. Si de la poussière est projetée dans les yeux de ce Pokémon, elle est rapidement évacuée."}, {"g": "Saphir Alpha", "t": "Le corps de Grodoudou est très élastique. S’il inspire profondément, ce Pokémon peut se gonfler à volonté. Une fois gonflé, Grodoudou peut rebondir comme un ballon."}, {"g": "Soleil", "t": "Son pelage est doux et soyeux, mais il en change à chaque saison. Certains le récupèrent et en font des manteaux de grand luxe."}, {"g": "Lune", "t": "Il aime se gonfler d’air au maximum. Les conflits de Grodoudou se règlent en regardant lequel réussit à se faire plus gros que les autres."}, {"g": "Ultra-Soleil", "t": "Il est célébré pour son corps élastique et son pelage soyeux. Quel bonheur que de faire une sieste en serrant un Grodoudou contre soi !"}, {"g": "Ultra-Lune", "t": "Lorsqu’il se fâche, il se gonfle d’air et peut atteindre jusqu’à vingt fois son volume normal."}, {"g": "Let's Go Pikachu", "t": "Son corps est malléable. En aspirant de l’air, il se gonfle jusqu’à atteindre des proportions gigantesques."}, {"g": "Épée", "t": "Son corps gonfle à mesure qu’il inspire de l’air. Il se sert de cette particularité pour se grandir et intimider son adversaire quand il est en colère."}, {"g": "Bouclier", "t": "Sa fourrure soyeuse fait sa fierté. La touffe sur son front est si douce que la caresser donne l’impression d’être sur un petit nuage."}],
  41: [{"g": "Ultra-Soleil", "t": "Dépourvu d’yeux, il se repère dans l’espace grâce aux ultrasons qu’il émet avec sa bouche."}, {"g": "Noir", "t": "Il se repère dans l’espace grâce aux ultrasons émis par sa gueule."}, {"g": "X", "t": "Bien que dépourvu d’yeux, il repère les obstacles grâce aux ultrasons émis par sa gueule."}, {"g": "Y", "t": "Comme il ne possède pas d’yeux, il n’utilise que ses ultrasons pour se déplacer dans les ténèbres."}, {"g": "Rubis Oméga", "t": "Nosferapti reste calme et immobile dans un coin sombre pendant la journée. En effet, une exposition trop longue à la lumière du soleil lui brûle légèrement la peau."}, {"g": "Saphir Alpha", "t": "Nosferapti évite la lumière du soleil, car ça le rend malade. Pendant la journée, il reste dans les cavernes ou à l’ombre des vieilles maisons, où il dort, la tête à l’envers."}, {"g": "Soleil", "t": "Il dort dans des grottes pendant la journée. Comme il n’a pas d’yeux, il vole en se repérant grâce à ses ultrasons."}, {"g": "Lune", "t": "S’il vole en journée, la lumière du soleil brûle sa peau. La fréquence de ses ultrasons est légèrement différente d’un groupe à l’autre."}, {"g": "Ultra-Lune", "t": "Sa peau est si fine que la lumière du soleil lui cause des brûlures. Lorsqu’il fait froid, ses congénères et lui se serrent pour se réchauffer."}, {"g": "Let's Go Pikachu", "t": "Il émet des ultrasons pour se diriger et éviter les obstacles sur son trajet."}, {"g": "Épée", "t": "Il sonde les environs en émettant des ultrasons avec sa bouche, et peut ainsi se frayer un chemin même dans les grottes les plus étroites."}, {"g": "Bouclier", "t": "Ils vivent dans les grottes où la lumière du jour ne perce jamais. Le matin, ils se blottissent les uns contre les autres pour se réchauffer et dormir."}],
  42: [{"g": "Noir", "t": "Ses crocs acérés et creux peuvent pénétrer la plus épaisse des peaux et sucer le sang de la victime."}, {"g": "X", "t": "Il mord son adversaire et absorbe toute son énergie, même s’il devient trop lourd pour voler."}, {"g": "Y", "t": "Quand il se met à sucer du sang, il ne s’arrête qu’une fois rassasié. C’est un chasseur nocturne."}, {"g": "Rubis Oméga", "t": "Nosferalto adore boire le sang des créatures vivantes. Il est particulièrement actif pendant les nuits noires. Ce Pokémon se balade dans les cieux étoilés, à la recherche de sang frais."}, {"g": "Saphir Alpha", "t": "Nosferalto mord sa proie grâce à ses quatre crocs pour boire son sang. Il ne sort que lorsque la nuit est noire et sans lune, pour voleter en quête de gens et de Pokémon à mordre."}, {"g": "Soleil", "t": "Ses crocs sont creux comme des pailles et étonnamment fragiles. Ils sont en revanche parfaits pour sucer le sang de ses victimes."}, {"g": "Lune", "t": "Il arrive qu’un Nosferalto ayant trop sucé de sang ne puisse plus voler et tombe au sol, où il est dévoré par d’autres Pokémon."}, {"g": "Ultra-Soleil", "t": "On rencontre parfois des Nosferalto édentés que la faim a poussés à attaquer un Pokémon de type Acier."}, {"g": "Ultra-Lune", "t": "Ce Pokémon peut absorber jusqu’à 300 ml de sang d’un coup. Victime de sa gourmandise, il en devient parfois trop lourd pour voler."}, {"g": "Let's Go Pikachu", "t": "Il s’approche furtivement et attaque sans crier gare. Ses crocs acérés lui servent à sucer le sang."}, {"g": "Épée", "t": "Le sang des êtres vivants est son péché mignon. On dit qu’il partage parfois ce précieux breuvage avec ses congénères affamés."}, {"g": "Bouclier", "t": "Il se déplace habilement sur ses petites pattes, s’approche silencieusement de sa proie endormie, et lui suce le sang à l’aide de ses crocs."}],
  43: [{"g": "Noir", "t": "En journée, il plante ses pieds-racines dans le sol. La nuit, il se promène en semant des graines."}, {"g": "X", "t": "Le jour, il reste en sous-sol et évite le soleil. Il grandit en se baignant au clair de lune."}, {"g": "Y", "t": "Son nom scientifique est « Oddium Wanderus ». Lorsqu’il fait nuit, il se déplace à l’aide de ses racines pour disséminer ses graines."}, {"g": "Rubis Oméga", "t": "Pendant la journée, Mystherbe s’enterre dans le sol pour absorber avec son corps tout entier les nutriments présents dans la terre. Plus le sol est fertile, plus ses feuilles sont brillantes."}, {"g": "Saphir Alpha", "t": "Mystherbe cherche un sol fertile et riche en nutriments, pour s’y planter. Pendant la journée, quand il est planté, les pieds de ce Pokémon changent de forme et deviennent similaires à des racines."}, {"g": "Let's Go Pikachu", "t": "On le confond souvent avec de l’herbe. Si on essaie de le soulever du sol, il pousse un cri terrifiant."}, {"g": "Épée", "t": "Il ne bouge que lorsqu’il est exposé aux rayons de la lune. Il se déplace alors pour disséminer ses graines."}, {"g": "Bouclier", "t": "Pendant la journée, il reste en sous-sol et évite le soleil. Il grandit en se baignant au clair de lune."}],
  44: [{"g": "Noir", "t": "L’odeur du nectar de sa bouche est si répugnante qu’elle agresse les narines à deux kilomètres."}, {"g": "X", "t": "Il sent très mauvais ! Mais une personne sur 1 000 aime la puanteur de son corps nauséabond."}, {"g": "Y", "t": "L’odeur du nectar de sa bouche est si répugnante qu’elle agresse les narines à 2 km."}, {"g": "Rubis Oméga", "t": "La plupart du temps, Ortide dégage un parfum immonde du pistil de sa fleur. Lorsqu’il se sent en danger, la puanteur est encore pire. Lorsque ce Pokémon se sent bien et en sécurité, il ne dégage aucune odeur nauséabonde."}, {"g": "Saphir Alpha", "t": "Ortide bave un miel qui sent horriblement mauvais. Apparemment, il adore cette odeur nauséabonde. Il en renifle les fumées toxiques et se met à baver du miel de plus belle."}, {"g": "Let's Go Pikachu", "t": "Il sent très mauvais, mais une personne sur mille aime l’odeur de son corps nauséabond."}, {"g": "Épée", "t": "Ses pistils sécrètent une odeur incroyablement fétide qui fait perdre connaissance à ses adversaires jusqu’à 2 km à la ronde."}, {"g": "Bouclier", "t": "Ce qui semble être sa bave est en fait du nectar très collant. Si on le touche, il est très difficile de s’en dépêtrer."}],
  45: [{"g": "Noir", "t": "Ses pétales sont les plus grands du monde. Il marche en répandant un pollen extrêmement allergène."}, {"g": "X", "t": "Plus ses pétales sont grands, plus ils contiennent de pollen toxique."}, {"g": "Y", "t": "Il possède des pétales énormes. À chaque pas, ils sèment d’épais nuages de pollen toxique."}, {"g": "Rubis Oméga", "t": "Le pollen toxique de Rafflesia déclenche d’affreuses réactions allergiques. C’est pourquoi il est conseillé de ne jamais s’approcher des jolies fleurs trouvées dans la jungle, même lorsqu’elles sont magnifiques."}, {"g": "Saphir Alpha", "t": "Rafflesia dispose des plus grands pétales du monde. Il s’en sert pour attirer ses proies avant de les endormir avec ses spores toxiques. Ce Pokémon n’a plus alors qu’à attraper sa proie et à la manger."}, {"g": "Let's Go Pikachu", "t": "Il fait un bruit terrible quand il secoue ses pétales pour disperser son pollen empoisonné."}, {"g": "Épée", "t": "Il possède les plus gros pétales au monde, qui sèment d’épais nuages de pollen toxique à chacun de ses pas."}, {"g": "Bouclier", "t": "Plus ses pétales sont grands, plus il produit de pollen toxique. Toutefois, le poids de sa tête le fatigue."}],
  46: [{"g": "Noir", "t": "Des champignons appelés “tochukaso” poussent sur son dos. Ils évoluent avec le Paras hôte."}, {"g": "X", "t": "Sur le dos de ce Pokémon se trouvent des champignons appelés tochukaso. Ils se développent au même rythme que leur hôte."}, {"g": "Y", "t": "Il s’enfouit sous terre pour ronger des racines afin de nourrir les champignons sur son dos."}, {"g": "Rubis Oméga", "t": "Paras accueille des champignons parasites appelés tochukaso qui poussent sur son dos. Ils grandissent grâce aux nutriments trouvés sur le dos de ce Pokémon Insecte. Ils peuvent rallonger l’espérance de vie."}, {"g": "Soleil", "t": "Il a beau manger autant qu’il peut, les champignons qui poussent sur son dos lui volent la plupart de ses nutriments."}, {"g": "Lune", "t": "Les champignons qui poussent sur son dos, appelés tochukaso, peuvent être séchés puis broyés pour obtenir un élixir de longue vie."}, {"g": "Ultra-Soleil", "t": "C’est probablement par manque de nutriments et d’humidité que les champignons sur son dos peinent à se développer à Alola."}, {"g": "Ultra-Lune", "t": "Les champignons, appelés tochukaso, contrôlent l’insecte contre sa volonté."}, {"g": "Let's Go Pikachu", "t": "Il s’enfouit pour ronger des racines, mais ce sont les champignons sur son dos qui absorbent presque tous les nutriments."}],
  47: [{"g": "Noir", "t": "Un champignon parasite plus gros que Parasect contrôle son corps. Il répand des spores empoisonnées."}, {"g": "Y", "t": "Plus le champignon sur son dos grandit, plus celui-ci émet des spores puissantes dans l’air."}, {"g": "Rubis Oméga", "t": "On sait que les Parasect vivent en groupe dans les grands arbres et se nourrissent des nutriments contenus dans le tronc et les racines. Lorsqu’un arbre infesté meurt, ils se précipitent vers le prochain."}, {"g": "Soleil", "t": "Le gros champignon sur son dos contrôle le Pokémon. Lampignon et Parasect se disputent souvent un même territoire."}, {"g": "Lune", "t": "Il répand des spores empoisonnées depuis son chapeau. On peut les récolter et les faire sécher pour préparer des remèdes traditionnels."}, {"g": "Ultra-Soleil", "t": "L’insecte est quasiment mort, à ce stade, et le champignon est devenu le véritable cerveau. Si on l’ôte de son dos, il ne peut plus bouger."}, {"g": "Ultra-Lune", "t": "Des remèdes traditionnels sont préparés avec ses spores empoisonnées, mais ceux produits à Alola seraient de moindre qualité."}, {"g": "Let's Go Pikachu", "t": "À force de voir son énergie aspirée, il semblerait que ce ne soit plus l’insecte qui réfléchisse, mais le champignon sur son dos."}],
  48: [{"g": "Noir", "t": "Ses grands yeux sont en fait des amas d’yeux minuscules. La nuit, il est attiré par la lumière."}, {"g": "Y", "t": "Il vit à l’ombre des grands arbres où il se nourrit d’insectes. Il est attiré par la lumière."}, {"g": "Rubis Oméga", "t": "On raconte que Mimitoss a évolué avec une fourrure de poils fins et drus qui protège son corps tout entier. Il est doté de grands yeux capables de repérer ses proies, même minuscules."}, {"g": "Let's Go Pikachu", "t": "Ses grands yeux lui servent de radar. En pleine lumière, on peut y distinguer des facettes."}],
  49: [{"g": "Noir", "t": "Il répand ses écailles poudreuses en battant des ailes. Elles sont toxiques au toucher."}, {"g": "X", "t": "Les écailles qu’il sème ont le pouvoir de paralyser totalement un ennemi."}, {"g": "Y", "t": "Ses ailes sont couvertes d’écailles poudreuses. À chaque battement d’ailes, il laisse tomber de la poudre hautement toxique."}, {"g": "Rubis Oméga", "t": "Aéromite est un Pokémon nocturne, il ne sort donc que la nuit. Ses proies préférées sont les petits insectes qui se rassemblent autour des réverbères, attirés par la lumière."}, {"g": "Let's Go Pikachu", "t": "Les écailles de ses ailes sont presque impossibles à retirer lorsqu’elles se collent à la peau, et elles libèrent un poison violent au contact."}],
  50: [{"g": "Noir", "t": "Un Pokémon qui vit sous terre. Habitué aux souterrains, il fuit la lumière du jour."}, {"g": "X", "t": "Il vit à 1 m sous la terre et se nourrit de racines. Il apparaît rarement à la surface."}, {"g": "Y", "t": "Son épiderme est très fin. S’il est exposé au soleil, son sang se réchauffe, ce qui l’affaiblit."}, {"g": "Rubis Oméga", "t": "Les Taupiqueur sont élevés dans la plupart des fermes. En effet, lorsque ce Pokémon creuse quelque part, le sol est comme labouré, prêt à recevoir les semences. On peut alors y planter de délicieux légumes."}, {"g": "Soleil", "t": "Il mange les racines souterraines des arbres, et cause beaucoup de soucis aux fermiers qui cultivent certains légumes."}, {"g": "Lune", "t": "Ce Pokémon laboure le sol et le fertilise avec ses déjections. Pour cette raison, beaucoup d’agriculteurs l’élèvent avec soin."}, {"g": "Ultra-Soleil", "t": "Il se déplace en creusant des tunnels. Il déteste la lumière et n’apparaît à la surface qu’une fois le soleil couché."}, {"g": "Ultra-Lune", "t": "Pour encourager les Taupiqueur à labourer leurs champs, les agriculteurs les bordent d’arbres appréciés de ces Pokémon."}, {"g": "Let's Go Pikachu", "t": "Il aime les lieux sombres. Il passe la majeure partie de son temps sous terre mais il remonte souvent dans les cavernes."}, {"g": "Épée", "t": "Si un Taupiqueur creuse un tunnel sous un champ, il retourne la terre et améliore les récoltes."}, {"g": "Bouclier", "t": "Ce Pokémon creuse sous terre à faible profondeur. La terre qu’il laisse dans son sillage le rend facile à repérer."}],
  51: [{"g": "Noir", "t": "Ses trois têtes creusent le sol à tour de rôle. Il peut atteindre des profondeurs de 100 kilomètres."}, {"g": "X", "t": "Au combat, il s’enfouit sous terre pour pouvoir frapper ses adversaires depuis n’importe quelle direction."}, {"g": "Y", "t": "Terriblement puissants, ils peuvent creuser un tunnel dans tout type de sol et jusqu’à 100 km de profondeur."}, {"g": "Rubis Oméga", "t": "Les Triopikeur sont en fait des triplés qui ont émergé du même corps. C’est pourquoi chaque triplé pense exactement comme les deux autres. Ils creusent inlassablement, dans une coopération parfaite."}, {"g": "Soleil", "t": "Des triplés Taupiqueur qui s’entraident en tout. En se coordonnant, ils peuvent creuser en équipe jusqu’à 100 km de profondeur."}, {"g": "Lune", "t": "Bien que beaucoup d’agriculteurs élèvent ce Pokémon, personne n’a jamais vu la partie enfouie de son corps."}, {"g": "Ultra-Soleil", "t": "Ces triplés s’entendent à merveille, mais en de rares occasions, une terrible dispute éclate pour savoir qui va manger en premier."}, {"g": "Ultra-Lune", "t": "D’apparence lisse, ses têtes sont incroyablement dures. Il creuse la terre à coups de crâne répétés."}, {"g": "Let's Go Pikachu", "t": "À trois, ils peuvent creuser jusqu’à 100 km de profondeur. On les dit responsables des tremblements de terre."}, {"g": "Épée", "t": "Ces triplés forment une équipe de choc. Ils causent parfois des séismes lorsqu’ils creusent jusqu’à 100 km de profondeur."}, {"g": "Bouclier", "t": "Ce trio de Taupiqueur est capable de creuser jusqu’à 100 km sous terre, vers l’inconnu."}],
  52: [{"g": "Noir", "t": "Son regard s’anime à la vue d’un objet brillant. C’est un Pokémon nocturne."}, {"g": "Y", "t": "Il adore les pièces de monnaie. Il hante les rues à la recherche de pièces oubliées par les passants."}, {"g": "Rubis Oméga", "t": "Miaouss peut rentrer ses griffes dans ses pattes pour rôder gracieusement sans laisser de traces. Étrangement, ce Pokémon raffole des pièces d’or qui brillent à la lumière."}, {"g": "Soleil", "t": "Il fait la sieste pendant la journée et devient actif quand le soir tombe. Il passe sa nuit à chercher des pièces perdues dans les rues."}, {"g": "Lune", "t": "Il adore tout ce qui brille et doit souvent affronter des Cornèbre qui convoitent le même trophée que lui."}, {"g": "Ultra-Soleil", "t": "Il n’est pas rare de l’apercevoir dans les décharges, où il se dispute souvent quelque objet brillant avec un Cornèbre."}, {"g": "Ultra-Lune", "t": "Il raffole des pièces de monnaie. Il suffit de lui en donner une pour acheter son affection, mais vu son caractère, cela ne dure jamais longtemps."}, {"g": "Let's Go Pikachu", "t": "Il est surtout actif la nuit. Il aime ramasser les objets ronds et brillants."}, {"g": "Épée", "t": "Il aime rassembler des objets brillants. S’il est de bonne humeur, il montre sa collection à son Dresseur."}, {"g": "Bouclier", "t": "Tatillon sur la propreté de la pièce sur son front, il se lave la figure avec grand soin. Il ne s’entend pas avec les Miaouss de Galar."}],
  53: [{"g": "Noir", "t": "Un Pokémon très snob. La taille du joyau qui orne son front alimente bien des débats parmi ses fans."}, {"g": "X", "t": "Très apprécié pour sa fourrure, il est difficile à apprivoiser en raison de son caractère rétif."}, {"g": "Y", "t": "Ses muscles souples lui permettent de marcher sans un bruit et d’attaquer en l’espace d’un instant."}, {"g": "Rubis Oméga", "t": "Persian a six grosses vibrisses qui lui donnent un air costaud et lui permettent de sentir les mouvements de l’air pour savoir ce qui se trouve à proximité. Il devient docile lorsqu’on l’attrape par les moustaches."}, {"g": "Soleil", "t": "Un Pokémon très agressif, qui peut sauter à la gorge si on le regarde dans les yeux. Ses griffes acérées infligent de graves blessures."}, {"g": "Lune", "t": "Un Pokémon naturellement fier, mais pas aussi orgueilleux que les Persian d’Alola. Il est très difficile à apprivoiser."}, {"g": "Ultra-Soleil", "t": "Malgré une composition quasiment identique, sa gemme est d’une couleur différente de celle du Persian d’Alola."}, {"g": "Ultra-Lune", "t": "Un Pokémon prisé des classes aisées. Il est néanmoins la cible des voleurs convoitant la gemme qui orne son front."}, {"g": "Let's Go Pikachu", "t": "La pierre sur son front brille de mille feux. Sa démarche est souple et majestueuse."}, {"g": "Épée", "t": "Très fier, il est difficile à apprivoiser. Dès que quelque chose ne lui plaît pas, il sort les griffes."}, {"g": "Bouclier", "t": "Il se comporte avec grâce et élégance, et ne s’entend pas avec les rustres Berserkatt : les deux espèces se méprisent."}],
  54: [{"g": "Noir", "t": "Ses pouvoirs déconcertants et mystérieux lui font subir de constantes migraines."}, {"g": "X", "t": "Ce Pokémon a tout le temps la migraine. Quand la douleur devient insupportable, il se met à utiliser ses pouvoirs psy."}, {"g": "Y", "t": "Il ne se souvient pas qu’il a des pouvoirs psy. C’est pour cela qu’il a l’air si confus."}, {"g": "Rubis Oméga", "t": "Psykokwak utilise un mystérieux pouvoir. Ce Pokémon peut générer des ondes cérébrales normalement observées chez les dormeurs. Cette découverte a lancé une polémique dans le milieu universitaire."}, {"g": "Saphir Alpha", "t": "Lorsqu’il utilise son mystérieux pouvoir, Psykokwak ne s’en souvient pas. Apparemment, il ne peut pas garder ce genre d’événement en mémoire, car il pratique ce pouvoir dans un état proche du sommeil profond."}, {"g": "Soleil", "t": "Il arrive que des ondes psychiques fusent de son cerveau sans qu’il n’y soit pour rien, ce qui lui donne mal à la tête au point de gémir."}, {"g": "Lune", "t": "Il souffre d’une migraine permanente. Plus sa douleur augmente, plus il émet des ondes psychiques intenses."}, {"g": "Ultra-Soleil", "t": "Utiliser ses pouvoirs psychiques lui donne de terribles migraines, aussi préfère-t-il passer tout son temps immobile à ne rien faire."}, {"g": "Ultra-Lune", "t": "Des scientifiques ont découvert que lorsqu’il souffre de migraines, ses neurones fonctionnent dix fois plus vite qu’en temps normal."}, {"g": "Let's Go Pikachu", "t": "Il est toujours en proie à des maux de tête. On ignore s’il contrôle ses pouvoirs psychiques."}, {"g": "Épée", "t": "Il a toujours la migraine, mais la douleur semble s’atténuer momentanément s’il laisse exploser son pouvoir mystérieux."}, {"g": "Bouclier", "t": "Sa migraine s’intensifie à mesure que son stress monte. Il libère une force psychique puissante qui terrasse tous ceux qui l’entourent."}],
  55: [{"g": "Noir", "t": "Ses membres palmés et son corps parfaitement adapté font de lui un nageur exceptionnel."}, {"g": "X", "t": "Il apparaît dans les étendues d’eau au crépuscule. Si son front brille, il se sert de sa télékinésie."}, {"g": "Y", "t": "Ses pattes arrière palmées font de ce Pokémon un excellent nageur. On peut souvent le voir nager élégamment dans les lacs."}, {"g": "Rubis Oméga", "t": "Les pattes avant et arrière palmées et le corps aérodynamique d’Akwakwak lui donnent une vitesse effrayante. Ce Pokémon est bien plus rapide que les plus grands champions de natation."}, {"g": "Saphir Alpha", "t": "Akwakwak est le Pokémon qui nage le plus vite. Il nage sans se fatiguer, même lorsque la mer est agitée. Il sauve parfois des gens coincés dans les navires bloqués en haute mer."}, {"g": "Soleil", "t": "Certains prétendaient que tenir la gemme rouge de son front donnait des pouvoirs psychiques, aussi a-t-il été braconné à certaines époques."}, {"g": "Lune", "t": "Il nage à travers les lacs pour attraper des Pokémon poissons, puis il remonte sur la rive pour les déguster tranquillement."}, {"g": "Ultra-Soleil", "t": "Même les Pokémon poissons les plus rapides ne peuvent pas lui échapper. Il les capture avec facilité en les immobilisant."}, {"g": "Ultra-Lune", "t": "Ce professionnel de la natation dispose d’une longue queue souple qui lui permet de nager sans interruption pendant deux jours."}, {"g": "Let's Go Pikachu", "t": "Ses membres longs et fins se terminent par des nageoires qui lui permettent de nager élégamment."}, {"g": "Épée", "t": "Vivant dans les rivières au cours tranquille, il se sert de ses longs membres pour nager avec élégance."}, {"g": "Bouclier", "t": "D’après de vieilles légendes, ce Pokémon entraînait au fond de l’eau tous ceux qui osaient souiller sa rivière."}],
  56: [{"g": "Noir", "t": "Ils vivent en colonies sylvestres. Quand un Férosinge s’énerve, toute la colonie suit son exemple."}, {"g": "X", "t": "Il ne peut dissocier ses amis de ses ennemis et a tendance à enrager lorsqu’on l’approche."}, {"g": "Rubis Oméga", "t": "Lorsque Férosinge commence à trembler et que sa respiration devient haletante, cela signifie qu’il est en colère. En outre, la moutarde lui monte au nez tellement vite qu’il est presque impossible d’échapper à sa colère."}, {"g": "Soleil", "t": "Quand il pique soudain une terrible colère, tout le monde autour de lui s’enfuit. Mais il supporte mal la solitude, et ça l’énerve encore davantage."}, {"g": "Lune", "t": "Fatigué de sa colère permanente, il lui arrive de dormir, mais il rêve de ses frustrations, se réveille, et se met en colère d’avoir été réveillé."}, {"g": "Ultra-Soleil", "t": "La moindre contrariété le rend furieux. Comme rien ne l’atteint durablement, il n’accumule pas de stress et peut vivre très vieux."}, {"g": "Ultra-Lune", "t": "Il suffit qu’un Férosinge s’énerve pour que ses congénères en fassent de même, aussi leurs groupes ne connaissent-ils jamais la paix."}, {"g": "Let's Go Pikachu", "t": "Agile et rapide, ce Pokémon vit dans les arbres. Il s’énerve facilement et s’attaque à tout ce qui bouge quand il est en colère."}],
  57: [{"g": "Noir", "t": "Il grogne quand on le toise, rugit quand on s’enfuit et devient fou de rage quand on le frappe."}, {"g": "X", "t": "Sa fureur prend fin quand il n’a plus personne à frapper. Il est difficile d’en être témoin."}, {"g": "Y", "t": "Ce Pokémon est constamment en rogne. Lorsqu’il traque une proie, il la pourchasse n’importe où, peu importe la distance."}, {"g": "Rubis Oméga", "t": "Lorsque Colossinge devient furieux, sa circulation sanguine s’accélère. Du coup, ses muscles sont encore plus puissants. En revanche, il devient bien moins intelligent."}, {"g": "Soleil", "t": "Il arrive qu’il s’énerve tellement qu’il en meurt. Son visage, lorsqu’il meurt ainsi, est empreint d’une grande sérénité."}, {"g": "Lune", "t": "D’après les recherches d’un certain scientifique, les Colossinge continuent de bouillonner de fureur même à l’intérieur d’une Poké Ball."}, {"g": "Ultra-Soleil", "t": "Il ne pardonne rien et poursuit sans relâche ceux qui l’ont courroucé. Même les assommer ne suffira pas à apaiser sa rancune."}, {"g": "Ultra-Lune", "t": "Les vaisseaux sanguins de son cerveau étant plus résistants que ceux d’autres Pokémon, il peut rester en état de colère perpétuelle."}],
  58: [{"g": "Noir", "t": "Un Pokémon très loyal. Il restera immobile jusqu’à ce que son Dresseur lui donne un ordre."}, {"g": "X", "t": "Ce Pokémon est particulièrement affectueux et loyal. Il aboie et il mord pour se débarrasser de ses adversaires."}, {"g": "Y", "t": "Il est courageux et fier. Il se dresse vaillamment devant ses ennemis même s’ils sont plus puissants."}, {"g": "Rubis Oméga", "t": "Caninos a un odorat très développé. Ce Pokémon n’oublie jamais un parfum, quel qu’il soit. Il utilise son puissant sens olfactif pour deviner les émotions des autres créatures vivantes."}, {"g": "Soleil", "t": "Un Pokémon très intelligent et affectueux. Il aboie pour intimider les inconnus et ceux qui pénètrent sur son territoire."}, {"g": "Lune", "t": "Même s’il a l’air adorable, mieux vaut ne pas s’approcher du Caninos d’un Dresseur inconnu. On risque de se faire mordre."}, {"g": "Ultra-Soleil", "t": "Il est très facile à apprivoiser, mais à l’état sauvage, il combat férocement les Rocabot pour le contrôle de son territoire."}, {"g": "Ultra-Lune", "t": "Cela fait des siècles qu’il vit avec les humains. Des ossements de Caninos ont été retrouvés sur des sites datant de l’âge de pierre."}, {"g": "Let's Go Pikachu", "t": "Ce Pokémon est de nature amicale, mais il devient hargneux quand son territoire est menacé."}, {"g": "Épée", "t": "Il est courageux et fiable. Il se dresse vaillamment devant ses ennemis même s’ils sont plus puissants."}, {"g": "Bouclier", "t": "Très fidèle, il aboie de toutes ses forces pour protéger son Dresseur d’Origine quand un danger le guette."}],
  59: [{"g": "Noir", "t": "Son port altier et son attitude fière ont depuis longtemps conquis le cœur des hommes."}, {"g": "X", "t": "Un Pokémon très recherché pour sa grâce légendaire. Il court avec tellement d’agilité qu’on dirait qu’il vole."}, {"g": "Y", "t": "Son aboiement est tout simplement majestueux. On ne peut que ramper à ses pieds après l’avoir entendu."}, {"g": "Rubis Oméga", "t": "Arcanin est célèbre pour son extraordinaire vitesse. On le dit capable de parcourir plus de 10 000 km en 24 h. Le feu qui fait rage à l’intérieur du corps de ce Pokémon est la source de son pouvoir."}, {"g": "Soleil", "t": "Ce Pokémon apparaît dans de vieux contes d’Extrême-Orient. Aussi beau que majestueux, sa puissance est légendaire."}, {"g": "Lune", "t": "La flamme qui brûle dans son corps lui donne l’énergie de parcourir les contrées. De nombreuses légendes existent à son sujet."}, {"g": "Ultra-Soleil", "t": "Une légende célèbre relate les exploits d’un chef de guerre et de son Arcanin à la conquête d’un certain royaume antique."}, {"g": "Ultra-Lune", "t": "Tant de mythes circulent sur son compte qu’il est parfois qualifié de légendaire, alors qu’en réalité, il est on ne peut plus commun."}, {"g": "Let's Go Pikachu", "t": "Un Pokémon légendaire en Extrême-Orient. Il est admiré pour la grâce et la beauté de sa course."}, {"g": "Épée", "t": "De nombreuses personnes ont été charmées à la vue de ce Pokémon parcourant 10 000 km en 24 heures."}, {"g": "Bouclier", "t": "Ce Pokémon est admiré depuis toujours pour sa beauté. Il court avec tellement de légèreté qu’on dirait qu’il vole."}],
  60: [{"g": "Noir", "t": "Sa peau est si mince qu’on voit ses organes internes. Il tient à peine sur ses nouveaux pieds."}, {"g": "X", "t": "Sa peau est humide, lisse et surtout très fine. La forme en spirale sur son ventre est en fait une partie de ses organes internes que l’on peut apercevoir."}, {"g": "Y", "t": "Le sens de la spirale sur son ventre diffère selon son origine. Il préfère la nage à la marche."}, {"g": "Rubis Oméga", "t": "Ptitard a une peau très fine. On peut même voir les entrailles en spirale de ce Pokémon à travers sa peau. Malgré sa finesse, cette peau est aussi très élastique. Même les crocs les plus acérés rebondissent dessus."}, {"g": "Soleil", "t": "La spirale est son intestin que l’on distingue par transparence. Lorsqu’elle blanchit, c’est signe qu’il a attrapé une maladie."}, {"g": "Lune", "t": "Il ne sait pas encore bien marcher. Un Dresseur de Ptitard doit l’entraîner à marcher tous les jours."}, {"g": "Ultra-Soleil", "t": "Malgré le danger, il ne cesse de sortir de l’eau. Comme il a encore du mal à marcher, il s’y réfugie toutefois dès qu’un prédateur approche."}, {"g": "Ultra-Lune", "t": "L’orientation de sa spirale diffère légèrement selon les régions. Les fans de ces Pokémon peuvent les différencier au premier coup d’œil."}, {"g": "Épée", "t": "Il est plus à l’aise dans l’eau que sur la terre ferme. Le motif de spirale sur son ventre est en fait une partie de ses organes visibles à travers la peau."}, {"g": "Bouclier", "t": "Dans les rivières au courant puissant, il se sert de ses lèvres épaisses comme d’une ventouse pour s’accrocher aux rochers."}],
  61: [{"g": "Noir", "t": "La spirale qui orne son ventre ondule doucement. Celui qui la fixe est saisi d’une étrange torpeur."}, {"g": "X", "t": "Ce Pokémon amphibie transpire continuellement quand il est hors de l’eau afin d’hydrater son corps."}, {"g": "Y", "t": "Ses deux jambes sont très développées. Bien qu’il puisse se déplacer sur la terre ferme, ce Pokémon préfère vivre sous l’eau."}, {"g": "Rubis Oméga", "t": "La peau de Têtarte est toujours maintenue humide par un liquide huileux. Grâce à cette protection graisseuse, il peut facilement se glisser hors de l’étreinte de n’importe quel ennemi."}, {"g": "Soleil", "t": "Il est capable de vivre normalement sur la terre ferme, mais il préfère vivre dans l’eau, où il a beaucoup moins de prédateurs naturels."}, {"g": "Lune", "t": "Il patrouille sur la terre ferme à la recherche de nourriture, à savoir des Pokémon Insecte. Il les mange dans l’eau, où il est en sécurité."}, {"g": "Ultra-Soleil", "t": "Il est enfin capable de vivre sur la terre ferme, mais il passe le plus clair de son temps à chasser dans les eaux poissonneuses."}, {"g": "Ultra-Lune", "t": "Son état de santé se dégrade à mesure que sa peau s’assèche, aussi faut-il veiller à ce qu’il soit toujours bien hydraté."}, {"g": "Let's Go Pikachu", "t": "S’il se fait attaquer, il se sert de sa spirale pour endormir ses ennemis. Il peut ainsi s’enfuir."}, {"g": "Épée", "t": "Il suffit de fixer la spirale sur son ventre pour s’assoupir. On se sert parfois de lui à la place d’une berceuse pour endormir les enfants."}, {"g": "Bouclier", "t": "Il sécrète une sorte de mucus huileux qui lui permet d’échapper aux ennemis qui tentent de l’attraper."}],
  62: [{"g": "Noir", "t": "Il possède de sacrés biscoteaux. Il peut parcourir sans relâche l’Océan Pacifique."}, {"g": "X", "t": "Il possède de sacrés biscoteaux. Il peut parcourir sans relâche l’océan Pacifique."}, {"g": "Y", "t": "Excellent nageur, il pratique le crawl ou la nage papillon mieux qu’un champion olympique."}, {"g": "Rubis Oméga", "t": "Les muscles solides et surdéveloppés de Tartard ne se fatiguent jamais, quels que soient les efforts qu’il produit. Ce Pokémon est tellement endurant qu’il peut traverser un océan à la nage avec une étonnante facilité."}, {"g": "Soleil", "t": "Les Tartard d’Alola nagent la brasse avec habileté. Beaucoup d’enfants apprennent à nager en les imitant."}, {"g": "Lune", "t": "Il a un indice de masse grasse proche de zéro. Comme il est plein de muscles, il est très lourd et a dû apprendre à nager pour se déplacer."}, {"g": "Ultra-Soleil", "t": "Bien qu’il fasse partie des Pokémon de type Eau les plus doués pour la nage, il reste en général sur la terre ferme."}, {"g": "Ultra-Lune", "t": "Son impressionnante musculature a été sculptée par sa nage vigoureuse. Un direct du droit lui suffit à réduire un gros rocher en miettes."}, {"g": "Let's Go Pikachu", "t": "Son corps très musclé lui permet de nager plus rapidement qu’un champion de natation."}, {"g": "Épée", "t": "Cette véritable montagne de muscles peut se frayer un chemin même dans les eaux glaciales en éclatant la banquise avec ses bras robustes."}, {"g": "Bouclier", "t": "Aussi habile à la nage qu’au combat, il peut donner de vigoureux coups de poing avec ses bras musclés."}],
  63: [{"g": "Noir", "t": "L’utilisation de ses pouvoirs mentaux le fatigue tellement qu’il dort 18 heures par jour."}, {"g": "X", "t": "Il dort 18 h par jour. Il peut utiliser de nombreux pouvoirs psy, même pendant son sommeil."}, {"g": "Y", "t": "Il prévoit les attaques futures et se téléporte pour se mettre à l’abri et éviter le combat."}, {"g": "Rubis Oméga", "t": "Abra dort dix-huit heures par jour. Pourtant, il peut sentir la présence de ses ennemis, même endormi. Dans ce genre de situation, ce Pokémon se téléporte en lieu sûr."}, {"g": "Saphir Alpha", "t": "Abra doit dormir dix-huit heures par jour. S’il dort moins, ce Pokémon ne peut plus utiliser ses pouvoirs télékinétiques. Lorsqu’il est attaqué, Abra s’enfuit en utilisant Téléport, sans même se réveiller."}, {"g": "Soleil", "t": "Il dort 18 heures par jour. Il lui arrive de se téléporter dans les arbres et d’en manger les Baies sans même se réveiller."}, {"g": "Lune", "t": "Il lui arrive de se téléporter pendant son sommeil pour se protéger, mais lorsqu’il se réveille, il se retrouve dans un endroit inconnu et panique."}, {"g": "Ultra-Soleil", "t": "Il utilise certains de ses pouvoirs psychiques même quand il dort, aussi est-ce impossible de savoir s’il est éveillé ou non."}, {"g": "Ultra-Lune", "t": "Il lit les pensées de ses adversaires et se téléporte au loin avant d’être en danger. Pour l’attraper, il faut faire le vide dans son esprit."}, {"g": "Let's Go Pikachu", "t": "Il dort 18 heures par jour. En cas de danger, il se téléporte vers un lieu sûr, même s’il est assoupi."}, {"g": "Épée", "t": "Le contenu de ses rêves influe sur les pouvoirs psychiques qu’il utilise dans son sommeil."}, {"g": "Bouclier", "t": "Il peut se téléporter en dormant. On dit que plus son sommeil est profond, plus il se téléporte loin."}],
  64: [{"g": "Noir", "t": "Il fixe sa cuillère d’argent afin de concentrer son esprit et d’émettre un maximum d’ondes alpha."}, {"g": "X", "t": "Son pouvoir psychique émet des ondes alpha qui brouillent les appareils électroniques."}, {"g": "Y", "t": "En utilisant ses pouvoirs, il émet des ondes alpha et cause des distorsions électroniques."}, {"g": "Rubis Oméga", "t": "Kadabra émet une onde alpha si particulière qu’elle vous donne mal à la tête. Seuls les gens avec un psychisme puissant peuvent espérer devenir Dresseur de ce Pokémon."}, {"g": "Saphir Alpha", "t": "Kadabra tient une cuiller en argent dans la main. Elle est utilisée pour amplifier les ondes alpha de son cerveau. Sans elle, on raconte que ce Pokémon ne peut utiliser que la moitié de ses pouvoirs télékinétiques."}, {"g": "Soleil", "t": "Certains pensent que lorsqu’un enfant humain télépathe perd le contrôle de ses pouvoirs psychiques, il devient un Kadabra."}, {"g": "Lune", "t": "Lorsqu’un Kadabra se trouve à proximité d’un écran, une télé par exemple, une ombre sinistre dont la vision porte malheur traverse l’image."}, {"g": "Ultra-Soleil", "t": "Il fixe sa cuiller d’argent pour concentrer son énergie psychique avant de la libérer, mais il ne peut rien faire avec une cuiller en or."}, {"g": "Ultra-Lune", "t": "Son esprit est doté d’impressionnantes facultés, mais elles sont diminuées de moitié s’il n’a pas de cuiller d’argent."}, {"g": "Let's Go Pikachu", "t": "Sa présence cause des évènements étranges, comme des horloges tournant à l’envers."}, {"g": "Épée", "t": "Ses pouvoirs psychiques lui permettent de léviter en dormant. Il utilise alors sa queue très souple comme un oreiller."}, {"g": "Bouclier", "t": "Incroyablement doué en télékinésie, il concentre son énergie psychique dans l’étoile sur son front en prévision de son évolution."}],
  65: [{"g": "Noir", "t": "On dit que les cuillères qu’il tient en permanence ont été créées par la puissance de son esprit."}, {"g": "X", "t": "Ses cellules cérébrales se multiplient jusqu’à sa mort. Il se souvient donc de tout."}, {"g": "Y", "t": "Son cerveau hors du commun peut effectuer des opérations à la vitesse d’un ordinateur. Il a un QI de 5 000."}, {"g": "Rubis Oméga", "t": "Le cerveau d’Alakazam grossit sans arrêt, si bien que sa tête devient trop lourde pour son cou. Ce Pokémon maintient sa tête relevée grâce à son pouvoir télékinétique."}, {"g": "Saphir Alpha", "t": "Le cerveau d’Alakazam grossit sans arrêt, multipliant sans cesse ses cellules. Ce Pokémon a un QI incroyablement élevé, de 5 000. Il peut garder en mémoire tout ce qui s’est passé dans le monde."}, {"g": "Soleil", "t": "Son Q.I. atteindrait les 5 000. Il émet des ondes psychiques si fortes qu’il suffit de se tenir près de lui pour avoir mal à la tête."}, {"g": "Lune", "t": "Ses neurones se développent jusqu’à sa mort. Plus un Alakazam est vieux, plus sa tête est grosse."}, {"g": "Ultra-Soleil", "t": "Il a lui-même créé ses cuillers avec sa propre force psychique. Chaque exemplaire est unique au monde."}, {"g": "Ultra-Lune", "t": "S’il a pleinement confiance en quelqu’un, il lui offre une cuiller en gage d’amitié. Tout ce que l’on mange avec cette cuiller a un goût délicieux."}, {"g": "Let's Go Pikachu", "t": "Ce Pokémon est très intelligent. Sa mémoire infaillible lui permet de retenir tout ce qu’il apprend."}, {"g": "Épée", "t": "Doué d’une intelligence hors du commun, ce Pokémon serait capable de conserver tous ses souvenirs, de sa naissance jusqu’à sa mort."}, {"g": "Bouclier", "t": "Il dispose d’immenses pouvoirs psychiques. On raconte qu’il s’en est servi afin de créer les cuillères qu’il tient dans chaque main."}],
  66: [{"g": "Blanc", "t": "Malgré sa petite taille, sa force lui permet de soulever plusieurs Racaillou à la fois."}, {"g": "X", "t": "Il muscle son corps en soulevant régulièrement un Gravalanch. Il est rompu à tous les arts martiaux."}, {"g": "Y", "t": "Son corps est essentiellement composé de muscles. Même s’il a la taille d’un petit enfant, il peut soulever 100 adultes avec ses bras."}, {"g": "Rubis Oméga", "t": "Les muscles de Machoc sont spéciaux. Quels que soient les efforts qu’il produit, il n’a jamais de courbature. Ce Pokémon est assez puissant pour lancer une centaine d’hommes adultes."}, {"g": "Saphir Alpha", "t": "Machoc s’entraîne en soulevant un Gravalanch, comme s’il s’agissait d’haltères. Certains Machoc voyagent un peu partout dans le monde pour apprendre à maîtriser tous les types d’arts martiaux."}, {"g": "Soleil", "t": "Il aime faire travailler ses muscles. Jour après jour, il regarde sa masse musculaire gonfler, et cela l’encourage à s’entraîner encore davantage."}, {"g": "Lune", "t": "Il s’entraîne en soulevant des Gravalanch tous les jours jusqu’à pouvoir projeter en l’air une centaine d’humains adultes d’un coup."}, {"g": "Ultra-Soleil", "t": "Il s’entraîne avec ses amis pour accroître sa masse musculaire et gagner en confiance. Une fois prêt, il ira défier un Makuhita."}, {"g": "Ultra-Lune", "t": "Il aime les aliments très nutritifs. Il les choisit instinctivement pour développer sa musculature aussi efficacement que possible."}, {"g": "Let's Go Pikachu", "t": "Très puissant malgré sa petite taille, il est passé maître en plusieurs types d’arts martiaux."}, {"g": "Épée", "t": "Son corps est essentiellement composé de muscles. Même s’il fait la taille d’un petit enfant, il peut soulever 100 adultes avec ses bras."}, {"g": "Bouclier", "t": "Il essaie de dépenser son énergie débordante en soulevant des rochers, ce qui le rend encore plus fort."}],
  67: [{"g": "Noir", "t": "Il soulève les plus lourdes charges avec plaisir et facilité. Il donne un coup de main tout en s’entraînant!"}, {"g": "X", "t": "Son corps est si puissant qu’il lui faut une ceinture de force pour équilibrer ses mouvements."}, {"g": "Y", "t": "Il peut soulever un camion d’une main. Il se sert de sa force pour aider dans les tâches physiques."}, {"g": "Rubis Oméga", "t": "Les muscles toniques de Machopeur sont durs comme de l’acier. Ce Pokémon est si fort qu’il peut facilement soulever un sumo avec un seul doigt."}, {"g": "Saphir Alpha", "t": "Machopeur pratique le body-building tous les jours, même lorsqu’il aide les gens à réaliser de durs travaux. Pendant ses congés, ce Pokémon va s’entraîner dans les champs et les montagnes."}, {"g": "Soleil", "t": "Grâce à un long entraînement, il a obtenu une force incroyable, qu’il met au service des humains pour les aider dans leurs travaux."}, {"g": "Lune", "t": "Il aide les humains dans les travaux de force. Il n’y a aucun scrupule à avoir, car il est ravi de pouvoir faire travailler ses muscles."}, {"g": "Ultra-Soleil", "t": "Quand il rencontre un adversaire vraiment redoutable, il retire sa ceinture de force et déchaîne toute sa puissance."}, {"g": "Ultra-Lune", "t": "C’est un modèle très en vogue chez les sculpteurs. De nombreux artistes ne jurent que par sa musculature parfaite."}, {"g": "Let's Go Pikachu", "t": "Sa ceinture sert à retenir son énergie. Sans elle, il serait incontrôlable."}, {"g": "Épée", "t": "Son corps est si puissant qu’il lui faut une ceinture pour maîtriser sa force."}, {"g": "Bouclier", "t": "Son corps robuste ne se fatigue jamais. Il n’hésite pas à aider les gens lorsqu’il s’agit de soulever des objets très lourds."}],
  68: [{"g": "Noir", "t": "La puissance et la rapidité de ses quatre bras puissants font des ravages sur ses adversaires."}, {"g": "X", "t": "Ses deux paires de bras permettent à Mackogneur d’envoyer une série de 1 000 coups de poing en 2 s."}, {"g": "Y", "t": "Il se sert de ses quatre bras pour enserrer les membres de sa victime puis il la projette au loin."}, {"g": "Rubis Oméga", "t": "Mackogneur est capable de déplacer n’importe quelle masse. Cependant, ses bras s’emmêlent dès qu’il essaie de réaliser un travail délicat ou minutieux. Ce Pokémon a tendance à cogner d’abord et à réfléchir ensuite."}, {"g": "Saphir Alpha", "t": "Mackogneur est célèbre, car c’est le seul Pokémon qui a réussi à maîtriser tous les types d’arts martiaux. S’il parvient à attraper son ennemi avec ses quatre bras, il le projette par-delà l’horizon."}, {"g": "Soleil", "t": "Il est capable de donner des coups de poing d’une puissance d’une mégatonne, qui envoient ses adversaires voler jusqu’à l’horizon."}, {"g": "Lune", "t": "Il soulève sans effort les plus gros camions à benne. Mais il n’est pas habile de ses mains, et est incapable de faire un travail de précision."}, {"g": "Ultra-Soleil", "t": "Il attrape son adversaire avec ses quatre mains avant de le tordre de différentes façons. On appelle cela le Massage Spécial Mackogneur."}, {"g": "Ultra-Lune", "t": "Ses quatre bras lui permettent d’attaquer et de se défendre en même temps. Il maîtriserait tous les arts martiaux existants."}, {"g": "Let's Go Pikachu", "t": "Il peut bouger une montagne d’un bras, alors rien ne lui résiste quand il utilise les quatre en même temps."}, {"g": "Épée", "t": "Il peut bouger ses quatre bras à grande vitesse et frapper du poing ou du tranchant de la main dans toutes les directions sans se fatiguer."}, {"g": "Bouclier", "t": "Il enchaîne les coups de poing avec ses quatre bras à une vitesse surprenante."}],
  69: [{"g": "Noir", "t": "Il préfère les climats chauds et humides. Ses lianes peuvent capturer une proie en un clin d’œil."}, {"g": "X", "t": "Même si son corps est très frêle, ce Pokémon est extrêmement rapide quand il attaque ses adversaires."}, {"g": "Y", "t": "Son bourgeon ressemble à un visage humain. Selon la légende, Chétiflor serait un type de mandragore légendaire."}, {"g": "Rubis Oméga", "t": "Le corps long et flexible de Chétiflor lui permet de se tordre et d’osciller pour éviter tout type d’attaque, même les plus puissantes. Ce Pokémon crache un fluide corrosif qui peut même dissoudre le fer."}, {"g": "Let's Go Pikachu", "t": "Il préfère les endroits chauds et humides. Il capture les Pokémon Insecte avec ses lianes pour les dévorer."}],
  70: [{"g": "Noir", "t": "Un Pokémon végétal. Il capture les proies étourdies en les endormant à l’aide d’une poudre toxique."}, {"g": "X", "t": "Ses membres en forme de feuilles permettent à Boustiflor de trancher ses adversaires. Il crache un fluide capable de tout dissoudre."}, {"g": "Y", "t": "Il crache de la Poudre Toxik pour immobiliser sa proie et il l’achève avec de l’Acide."}, {"g": "Rubis Oméga", "t": "Boustiflor est doté d’un gros crochet. La nuit, ce Pokémon s’accroche à une branche pour s’endormir. Quand il a un sommeil agité, il se réveille par terre."}, {"g": "Let's Go Pikachu", "t": "Quand il a faim, il avale tout ce qui bouge, puis achève ses proies avec de l’acide."}],
  71: [{"g": "Noir", "t": "Sa bouche sécrète un fluide à l’odeur de miel, qui s’avère être un acide extrêmement corrosif."}, {"g": "X", "t": "On dit qu’il vit en colonie dans la jungle, mais personne n’en est jamais revenu vivant pour le confirmer."}, {"g": "Y", "t": "Tout corps ingéré par ce Pokémon est systématiquement dissous en bouillie."}, {"g": "Rubis Oméga", "t": "Empiflor est doté d’une longue liane qui part de sa tête. Cette liane se balance et remue comme un animal pour attirer ses proies. Lorsque l’une d’elles s’approche un peu trop près, ce Pokémon l’avale entièrement."}, {"g": "Let's Go Pikachu", "t": "Il attire ses proies avec une odeur de miel et les avale tout entières. Il les digère en un jour seulement, les os y compris."}],
  72: [{"g": "Noir", "t": "Presque entièrement composé d’eau, son corps a tendance à se dessécher sur la terre ferme."}, {"g": "X", "t": "Son corps est principalement composé d’eau. Ses yeux cristallins projettent d’étranges rayons."}, {"g": "Y", "t": "Il vit en bord de mer. Les pêcheurs se font souvent arroser d’acide quand ils en accrochent un."}, {"g": "Rubis Oméga", "t": "Le corps de Tentacool est principalement aqueux. Si on le retire de l’eau, il se déshydrate complètement. Si cela arrive, il suffit de le replonger dans un liquide pour qu’il reprenne sa forme normale."}, {"g": "Saphir Alpha", "t": "Grâce à l’eau de son corps, Tentacool convertit la lumière du soleil absorbée et la renvoie sous forme de rayon d’énergie. Ce Pokémon lance ces rayons par le petit organe rond situé au-dessus de ses yeux."}, {"g": "Soleil", "t": "On en trouve parfois échoués sur le sable et desséchés, mais certains sont encore en vie. Il suffit de les mettre à l’eau pour les ranimer."}, {"g": "Lune", "t": "Il flotte dans les chenaux sablonneux. En cas de piqûre par l’un de ses tentacules empoisonnés, il faut aller à l’hôpital de toute urgence."}, {"g": "Ultra-Soleil", "t": "Il flotte près des côtes à la recherche de proies. Il lui arrive de perdre ses tentacules toxiques, mais ceux-ci repoussent avec le temps."}, {"g": "Ultra-Lune", "t": "Son corps est composé à 99 % d’eau. Le 1 % restant est occupé par l’organe qui sécrète les toxines."}, {"g": "Let's Go Pikachu", "t": "Certains échouent sur la plage et sèchent sur le sable. Poussez-les dans l’eau pour les ranimer."}, {"g": "Épée", "t": "Peu doué pour la natation, ce Pokémon se contente de flotter à la surface des eaux peu profondes pour chasser ses proies."}, {"g": "Bouclier", "t": "Il est presque totalement composé d’eau. Lorsqu’il s’immerge dans les flots, son corps se fond dans l’eau, ce qui le rend presque invisible."}],
  73: [{"g": "Noir", "t": "Ses 80 tentacules lui permettent d’emprisonner ses adversaires dans un redoutable filet venimeux."}, {"g": "X", "t": "Ses tentacules sont rétractés au repos. En situation de chasse, ils s’allongent pour prendre ses proies au piège."}, {"g": "Y", "t": "Les 80 tentacules que Tentacruel laisse s’agiter lui permettent d’injecter du poison dans le corps de ses ennemis mais aussi de les trancher."}, {"g": "Rubis Oméga", "t": "Tentacruel a deux gros globes sur la tête. Les globes s’illuminent lorsqu’il va envoyer un violent rayon d’ultrasons. Lorsque ce Pokémon se déchaîne, il crée d’énormes vagues autour de lui."}, {"g": "Saphir Alpha", "t": "Les tentacules de Tentacruel peuvent s’allonger et se rétracter à volonté. Il serre sa proie dans ses tentacules et l’affaiblit en lui injectant une toxine. Il peut attraper jusqu’à 80 proies en même temps."}, {"g": "Soleil", "t": "Ce Pokémon a en moyenne 80 tentacules venimeux. Plus un spécimen vit longtemps, moins il lui en reste."}, {"g": "Lune", "t": "Il arrive qu’une foule de Tentacruel se regroupe en masse dans la mer. Lorsque cela arrive, tous les Pokémon poissons alentour disparaissent."}, {"g": "Ultra-Soleil", "t": "Il émet des ultrasons par ses globes rouges afin d’affaiblir ses proies, puis les enserre de ses 80 tentacules."}, {"g": "Ultra-Lune", "t": "Il communique avec ses congénères en faisant briller ses globes rouges. Il les fait clignoter s’il veut leur envoyer un avertissement."}, {"g": "Let's Go Pikachu", "t": "Ses 80 tentacules peuvent s’allonger et se rétracter à volonté. Il les utilise pour enserrer sa proie et l’affaiblir avec une toxine."}, {"g": "Épée", "t": "Il faut faire attention lorsque les globes rouges sur sa tête se mettent à briller intensément, car c’est qu’il s’apprête à émettre des ultrasons."}, {"g": "Bouclier", "t": "Il peut allonger ses 80 tentacules à volonté et les utiliser comme un filet pour attraper sa proie et la transpercer de ses pics empoisonnés."}],
  74: [{"g": "Noir", "t": "Au repos, rien ne le distingue d’un vulgaire caillou. Malheur à ceux qui lui marchent dessus par mégarde!"}, {"g": "X", "t": "Il vit dans les plaines ou les montagnes. On le confond souvent avec un petit caillou."}, {"g": "Y", "t": "Son corps se fond dans la roche. Les Pokémon de cette espèce se bousculent au cours d’épreuves de force."}, {"g": "Rubis Oméga", "t": "Lorsqu’un Racaillou prend de l’âge, ses bords s’ébrèchent et s’usent, ce qui lui donne une apparence plus ronde. Cependant, le cœur de ce Pokémon reste dur, rocailleux et rugueux."}, {"g": "Saphir Alpha", "t": "Pour dormir profondément, Racaillou s’enterre à moitié dans le sol. Il ne se réveille pas, même si des randonneurs lui marchent dessus. Au petit matin, ce Pokémon roule en contrebas en quête de nourriture."}, {"g": "Soleil", "t": "Il est rond comme une balle, mais aussi très dur et lourd. Mieux vaut ne pas le lancer sur quelqu’un comme si c’était une boule de neige."}, {"g": "Lune", "t": "On en trouve en masse sur le bas-côté des routes. Un universitaire qui s’ennuyait en a dénombré une centaine sur la même route."}, {"g": "Ultra-Soleil", "t": "Les aspérités de Racaillou s’adoucissent au fil des années, tout comme sa personnalité. Il devient tout lisse, tout rond, et tout calme."}, {"g": "Ultra-Lune", "t": "Il grimpe les côtes escarpées à mains nues. C’est en le voyant à l’œuvre que des humains se sont mis à l’escalade de bloc."}, {"g": "Let's Go Pikachu", "t": "On en trouve près des sentiers de montagne. Si vous marchez dessus par inadvertance, ils s’énervent et attaquent."}],
  75: [{"g": "Noir", "t": "Il dévale les montagnes pour se déplacer. Une fois qu’il a pris tout son élan, dur dur de l’arrêter!"}, {"g": "X", "t": "D’une nature téméraire, il se moque de perdre des parties de son corps quand il dévale les pentes."}, {"g": "Y", "t": "Pour se déplacer, il dégringole le long des pentes. Il pulvérise tous les obstacles qui se trouvent sur son passage."}, {"g": "Rubis Oméga", "t": "Gravalanch grandit en se nourrissant de cailloux. Apparemment, il a une préférence pour les cailloux recouverts de mousse. En moyenne, il mange une tonne de rochers par jour."}, {"g": "Saphir Alpha", "t": "La nourriture préférée de Gravalanch est la roche. Ce Pokémon escalade parfois les montagnes, dévorant les rochers sur son passage. Une fois au sommet, il se laisse rouler jusqu’en bas."}, {"g": "Soleil", "t": "Ses aliments préférés sont les cailloux couverts de mousse. Il peut en engloutir une tonne par jour en les broyant bruyamment."}, {"g": "Lune", "t": "Ses jambes sont faibles, aussi se déplace-t-il en se roulant en boule. Il peut ainsi rouler jusqu’à 100 km/h."}, {"g": "Ultra-Soleil", "t": "Il escalade les falaises pour en atteindre les sommets. Une fois tout en haut, il se laisse rouler par le chemin d’où il est arrivé."}, {"g": "Ultra-Lune", "t": "Il se déplace en se laissant rouler le long des falaises. Si par malheur il finit dans une rivière, il se fait exploser en dernier recours."}, {"g": "Let's Go Pikachu", "t": "Il dévale les sentiers de montagne et traverse les obstacles en les pulvérisant."}],
  76: [{"g": "Noir", "t": "Aucun explosif ne pourrait entamer sa carapace de pierre. Il mue une fois par an."}, {"g": "X", "t": "À force de dévaler les falaises, il a creusé de larges sillons. Mieux vaut ne pas s’en approcher."}, {"g": "Rubis Oméga", "t": "Grolem vit à la montagne. Lorsqu’il y a un tremblement de terre, ces Pokémon roulent en groupe vers les contreforts montagneux."}, {"g": "Saphir Alpha", "t": "On sait que les Grolem se laissent rouler en bas des montagnes. Afin d’éviter qu’ils roulent sur les maisons des gens, des tranchées ont été creusées le long des montagnes pour les guider dans leurs descentes infernales."}, {"g": "Soleil", "t": "Son corps est si solide qu’il peut résister à l’explosion d’un bâton de dynamite, mais il craint l’humidité et la pluie."}, {"g": "Lune", "t": "Ce Pokémon mue une fois par an. Sa carapace se transforme en humus très prisé par les agriculteurs."}, {"g": "Ultra-Soleil", "t": "Lorsqu’il arrive à un âge avancé, il arrête de muer. Un Grolem ayant vécu très longtemps est recouvert de mousse verte."}, {"g": "Ultra-Lune", "t": "Il est capable de faire exploser une partie de son corps. Le souffle lui permet de se projeter à toute vitesse vers les sommets."}, {"g": "Let's Go Pikachu", "t": "Juste après la mue, son corps est blanc et tendre. Au contact de l’air, sa peau se solidifie et forme une armure."}],
  77: [{"g": "Noir", "t": "Chancelantes à la naissance, ses pattes deviennent très vite sûres et solides à force de galoper."}, {"g": "Y", "t": "Il muscle ses pattes en suivant ses parents. Il arpente les plaines et les montagnes toute la journée."}, {"g": "Rubis Oméga", "t": "À sa naissance, Ponyta est très faible. Il peut à peine tenir debout. Ce Pokémon se muscle en trébuchant et en tombant, lorsqu’il essaie de suivre ses parents."}, {"g": "Let's Go Pikachu", "t": "Il est capable de sauter très haut. Ses sabots et ses jambes peuvent amortir l’impact de l’atterrissage."}, {"g": "Épée", "t": "À la naissance, il ne court pas très vite. C’est en faisant la course avec ses camarades qu’il se muscle les jambes."}, {"g": "Bouclier", "t": "Il semblerait qu’une fois qu’un Dresseur a gagné la confiance de Ponyta, sa crinière enflammée ne le brûle plus au toucher."}],
  78: [{"g": "Noir", "t": "Au grand galop, sa crinière de feu disperse au vent une myriade d’étincelles ardentes."}, {"g": "X", "t": "Doté d’un esprit de compétition, il poursuit toute créature rapide pour faire la course."}, {"g": "Y", "t": "Son galop dépasse les 240 km/h. Il file comme une flèche, laissant flotter sa crinière ardente."}, {"g": "Rubis Oméga", "t": "On voit souvent Galopa trotter dans les champs et les plaines. Cependant, lorsque ce Pokémon s’en donne la peine, il peut galoper à plus de 240 km/h et sa crinière flamboyante s’embrase."}, {"g": "Let's Go Pikachu", "t": "Il aime la course. Il poursuit tout ce qui va plus vite que lui. Question d’honneur."}, {"g": "Épée", "t": "Ce Pokémon traverse les plaines à plus de 240 km/h, sa crinière flamboyante flottant au vent."}, {"g": "Bouclier", "t": "Au sein d’un troupeau, c’est le plus rapide qui devient le chef. Il choisit les lieux où se rendre et détermine la vitesse de galop."}],
  79: [{"g": "Noir", "t": "Bien que lent, c’est un pêcheur adroit qui utilise sa queue. Elle est insensible aux morsures."}, {"g": "X", "t": "Ramoloss semble toujours perdu dans ses pensées, mais personne ne sait vraiment à quoi il pense. Il adore pêcher en utilisant sa queue."}, {"g": "Y", "t": "Il est tellement paresseux qu’il lui faut une journée pour remarquer qu’on lui mord la queue."}, {"g": "Rubis Oméga", "t": "Ramoloss trempe sa queue dans l’eau au bord des rivières pour attraper ses proies. Cependant, ce Pokémon oublie souvent ce qu’il fait là et passe des jours entiers à traîner au bord de l’eau."}, {"g": "Soleil", "t": "Souvent, sa longue queue se coupe toute seule. Cela ne lui cause aucune douleur et une autre pousse aussitôt, donc il n’y a pas à s’en faire."}, {"g": "Lune", "t": "Une recette traditionnelle d’Alola consiste à faire sécher des queues de Ramoloss puis à les faire bouillir dans de l’eau salée."}, {"g": "Ultra-Soleil", "t": "Ce Pokémon, vénéré et considéré comme un devin dans certaines régions, a donné naissance au dicton : Ramoloss a bâillé, attention à l’ondée."}, {"g": "Ultra-Lune", "t": "Les queues de Ramoloss parfois retrouvées dans la nature étaient un ingrédient de cuisine particulièrement prisé."}, {"g": "Let's Go Pikachu", "t": "Lent et stupide, il aime se la couler douce sans se soucier du temps qui passe."}, {"g": "Épée", "t": "Il est si bête et si lent qu’il n’a pas mal lorsqu’on mange un morceau de sa queue. Il ne remarque même pas quand elle repousse."}, {"g": "Bouclier", "t": "Lorsqu’il trempe le bout de sa queue dans l’eau, une substance sucrée s’en dégage. Il s’en sert pour appâter ses proies quand il pêche."}],
  80: [{"g": "Noir", "t": "Ce grand benêt connaît des éclairs de lucidité lorsque le Kokiyas de sa queue se met à mordre."}, {"g": "X", "t": "Le Kokiyas accroché à sa queue est friand de ce qu’il dévore et ne veut pas lâcher prise."}, {"g": "Y", "t": "Un Kokiyas s’est un jour accroché à la queue d’un Ramoloss qui pêchait et l’a fait évoluer en Flagadoss."}, {"g": "Rubis Oméga", "t": "Flagadoss a un Kokiyas solidement attaché à sa queue. Du coup, il ne peut plus l’utiliser pour pêcher. Flagadoss est donc obligé, à contrecœur, de nager pour attraper ses proies."}, {"g": "Soleil", "t": "Il aime contempler la mer sans bouger. Le poison du Kokiyas répandu dans son organisme a encore plus ralenti son métabolisme."}, {"g": "Lune", "t": "Chaque fois que le Kokiyas mord avec force, il a soudain une idée de génie, mais il l’oublie immédiatement."}, {"g": "Ultra-Soleil", "t": "Ce Pokémon passe son temps dans l’oisiveté la plus totale. Sa queue se détache parfois et il perd son Kokiyas, redevenant ainsi un Ramoloss."}, {"g": "Ultra-Lune", "t": "Un Kokiyas avide s’est accroché à sa queue pour en sucer le jus sucré et s’est transformé pour prendre une forme en spirale."}, {"g": "Let's Go Pikachu", "t": "Il mène une vie tranquille en bord de mer. Si le Kokiyas accroché à sa queue s’en va, il redevient un Ramoloss."}, {"g": "Épée", "t": "Il a évolué après qu’un Kokiyas lui a mordu la queue. Celle-ci sécrète une substance sucrée qui enchante particulièrement les Kokiyas."}, {"g": "Bouclier", "t": "La morsure du Kokiyas l’a tellement surpris qu’il est devenu bipède. Il paraît qu’il redevient un Ramoloss si le Kokiyas lâche prise."}],
  81: [{"g": "Noir", "t": "Plus la rotation de ses extrémités est rapide, plus la force du champ magnétique qu’il génère est grande."}, {"g": "X", "t": "Les parties sur les côtés de son corps génèrent une énergie lui permettant de léviter."}, {"g": "Y", "t": "Il reste constamment en sustentation pour se déplacer. Ce Pokémon peut envoyer de l’électricité par les aimants situés sur ses côtés."}, {"g": "Rubis Oméga", "t": "Magnéti s’attache aux lignes à haute tension pour se charger en électricité. Si une maison a une panne de courant, il est conseillé de vérifier les fusibles car on trouve parfois ces Pokémon amassés sur la boîte à fusibles."}, {"g": "Saphir Alpha", "t": "Magnéti flotte dans les airs en émettant des ondes électromagnétiques par les aimants sur ses côtés. Ces ondes annulent les effets de la gravité. Ce Pokémon ne peut plus voler si son stock d’électricité est épuisé."}, {"g": "Soleil", "t": "Les Magnéti se rassemblent aux endroits où il y a beaucoup d’électricité, et s’agglutinent par exemple autour des pylônes électriques."}, {"g": "Lune", "t": "Il lévite en émettant des ondes électro- magnétiques. Si on le touche quand il s’alimente en énergie, on risque un choc électrique."}, {"g": "Ultra-Soleil", "t": "Ce Pokémon causant des coupures de courant, certaines centrales l’éloignent en diffusant des ondes qu’il déteste."}, {"g": "Ultra-Lune", "t": "De nos jours, les câbles électriques sont enterrés, aussi les Magnéti attaquent-ils de plus en plus les centrales électriques."}, {"g": "Let's Go Pikachu", "t": "Sa nature défie les lois de la gravité. Il flotte grâce à un champ électromagnétique."}, {"g": "Épée", "t": "Il lui arrive d’être à court d’électricité et de tomber au sol, mais il suffit de lui donner une batterie pour le ranimer."}, {"g": "Bouclier", "t": "Il se nourrit d’électricité et flotte dans les airs en libérant des ondes électromagnétiques avec les aimants situés de part et d’autre de son corps."}],
  82: [{"g": "Noir", "t": "Des groupes apparaissent si des taches solaires couvrent le soleil. Ils brouillent les télévisions."}, {"g": "X", "t": "Ce Pokémon est composé de plusieurs Magnéti. Il est capable de projeter de puissantes décharges magnétiques à haute tension."}, {"g": "Y", "t": "Il émet un signal radio étrange. Sa présence augmente la température de 1 °C dans un rayon de 1 000 m."}, {"g": "Rubis Oméga", "t": "Magnéton émet un puissant champ magnétique qui neutralise les appareils mécaniques. Lorsque ces Pokémon débarquent en masse, les villes sonnent l’alarme et préviennent les habitants."}, {"g": "Saphir Alpha", "t": "Magnéton émet un puissant champ magnétique qui neutralise les appareils électroniques. Certaines villes demandent aux propriétaires de ces Pokémon de les garder dans leurs Poké Balls."}, {"g": "Soleil", "t": "Lorsque trois Magnéti fusionnent, leurs cerveaux fusionnent aussi. Mais cela ne signifie pas que Magnéton est trois fois plus intelligent."}, {"g": "Lune", "t": "Il possède le triple de la puissance d’un Magnéti. Il en apparaît beaucoup lorsque les taches solaires sont nombreuses."}, {"g": "Ultra-Soleil", "t": "Les Magnéton émettent d’étranges ondes, et les appareils de précision ont tendance à tomber en panne à leur approche."}, {"g": "Ultra-Lune", "t": "Quand de gros nuages de pluie s’amoncellent dans le ciel, les Magnéton se rassemblent sur les hauteurs pour attendre la foudre."}, {"g": "Let's Go Pikachu", "t": "Il émet un signal radio étrange. Sa présence augmente la température de 2 ºC dans un rayon de 1 000 m."}, {"g": "Épée", "t": "La fusion de trois Magnéti a donné naissance à ce Pokémon. Il surveille les alentours en libérant de puissantes ondes électriques."}, {"g": "Bouclier", "t": "Il émet constamment une énergie magnétique puissante qui interfère avec la grande majorité des ordinateurs dont il s’approche."}],
  83: [{"g": "Noir", "t": "Il ne peut pas vivre sans son légume, c’est pourquoi il le protégera au péril de sa vie."}, {"g": "X", "t": "Il utilise le légume qu’il tient comme s’il s’agissait d’une épée."}, {"g": "Y", "t": "Ce Pokémon se promène toujours en tenant un légume. Il l’utilise pour faire son nid."}, {"g": "Rubis Oméga", "t": "On voit souvent des Canarticho avec une tige, récupérée sur une plante quelconque. Apparemment, ils peuvent distinguer les bonnes des mauvaises. On a vu ces Pokémon se battre pour des histoires de tiges."}, {"g": "Let's Go Pikachu", "t": "Il vit là où poussent des tiges. Ces endroits sont rares, ce qui pourrait faire penser que cette espèce de Pokémon est en voie d’extinction."}, {"g": "Épée", "t": "Il tranche ses adversaires avec sa tige, qu’il manie comme une épée. Quand la situation l’exige, il s’en nourrit."}, {"g": "Bouclier", "t": "Il se bat à l’aide de sa tige. Il existe plusieurs écoles quant à son maniement."}],
  84: [{"g": "Noir", "t": "Ses deux cerveaux semblent communiquer leurs émotions grâce à un lien télépathique."}, {"g": "X", "t": "Ce Pokémon à deux têtes est le résultat d’une soudaine mutation. Il peut courir jusqu’à 100 km/h."}, {"g": "Rubis Oméga", "t": "Les deux têtes de Doduo ne dorment jamais en même temps. Elles se reposent à tour de rôle pour que l’une puisse monter la garde pendant que l’autre dort."}, {"g": "Saphir Alpha", "t": "Les deux têtes de Doduo contiennent des cerveaux totalement identiques. Une étude scientifique démontra que dans des cas rares, certains de ces Pokémon possèdent des cerveaux différents."}, {"g": "Let's Go Pikachu", "t": "Ses petites ailes ne lui permettent pas de voler, mais grâce à ses puissantes pattes, il peut courir très rapidement."}],
  85: [{"g": "Noir", "t": "Quand Doduo connaît cette étrange évolution, l’une de ses têtes se dédouble. Il atteint les 60 km/h."}, {"g": "X", "t": "Un ennemi ne faisant pas attention à l’une des trois têtes pendant une seconde se fait picorer."}, {"g": "Y", "t": "Une espèce étrange que l’on trouve rarement. Les trois têtes représentent la joie, la tristesse et la colère."}, {"g": "Rubis Oméga", "t": "Il faut se méfier lorsque les trois têtes de Dodrio regardent dans des directions différentes. Cela signifie qu’il est sur ses gardes. Si c’est le cas, il vaut mieux ne pas s’approcher de ce Pokémon, il pourrait décider d’attaquer."}, {"g": "Saphir Alpha", "t": "Apparemment, Dodrio ne se contente pas d’avoir trois têtes. Il semble également avoir trois cœurs et six poumons, ce qui lui permet de courir très longtemps sans s’épuiser."}, {"g": "Let's Go Pikachu", "t": "Quand une des têtes de Doduo se divise, il devient un Dodrio capable de courir à 60 km/h."}],
  86: [{"g": "Noir", "t": "Un habitant des icebergs. En mer, il utilise la corne sur sa tête pour briser la banquise."}, {"g": "Y", "t": "Sa peau épaisse et dure est recouverte d’une fourrure bleu clair. Elle permet à ce Pokémon de résister aux températures les plus glaciales."}, {"g": "Rubis Oméga", "t": "Otaria chasse ses proies dans l’eau gelée, sous la couche de glace. Lorsqu’il cherche à respirer, il perce un trou en frappant la glace avec la partie saillante de sa tête."}, {"g": "Ultra-Soleil", "t": "Tout le monde pensait qu’il ne pouvait survivre que dans les mers froides. Personne ne sait donc ce qu’il fait à Alola."}, {"g": "Ultra-Lune", "t": "Sa couche de gras lui permet d’être à l’aise dans les eaux les plus froides. Il a par contre plus de mal à supporter les mers chaudes."}, {"g": "Let's Go Pikachu", "t": "Il est à l’aise dans les endroits gelés. Il nage avec plaisir dans de l’eau à -10 ºC."}],
  87: [{"g": "Noir", "t": "Son corps est couvert d’un grand manteau blanc qui, dans la neige, le dissimule aux yeux des prédateurs."}, {"g": "X", "t": "Son corps est recouvert d’une fourrure d’un blanc pur. Plus il fait froid, et plus ce Pokémon est actif."}, {"g": "Y", "t": "Son corps hydrodynamique glisse dans l’eau. Plus l’eau est froide plus il se sent à l’aise."}, {"g": "Rubis Oméga", "t": "Lamantine adore piquer un roupillon à même la glace. Il y a très longtemps, un marin ayant aperçu ce Pokémon dormant sur un glacier a cru voir une sirène."}, {"g": "Let's Go Évoli", "t": "Son corps entier est aussi blanc que la neige. Il résiste bien au froid et peut même nager au milieu des icebergs."}, {"g": "Ultra-Soleil", "t": "Il sillonne les mers à la recherche de ses proies à une vitesse de 8 nœuds. Il raffole des Froussardine."}, {"g": "Ultra-Lune", "t": "Après manger, il s’étale de tout son long sur les plages de sable fin. Le soleil le réchauffe et facilite sa digestion."}],
  88: [{"g": "Noir", "t": "Il est né d’un torrent de boue exposé aux rayons X de la lune. Il vit dans les ordures."}, {"g": "X", "t": "Tadmorv est né d’un tas de déchets exposé aux rayons X lunaires. Ce Pokémon adore se nourrir de choses dégoûtantes."}, {"g": "Y", "t": "Vivant dans des tas d’ordures, il se nourrit des déchets polluants rejetés par les usines."}, {"g": "Rubis Oméga", "t": "Le corps boueux et gélatineux de Tadmorv peut s’enfoncer dans n’importe quelle ouverture, même la plus petite. Ce Pokémon se promène dans les tuyaux des égouts pour boire de l’eau croupie."}, {"g": "Saphir Alpha", "t": "Tadmorv est apparu dans la vase accumulée sur un bord de mer pollué. Ce Pokémon aime tout ce qui est dégoûtant. Une substance pleine de germes suinte constamment de tout son corps."}, {"g": "Soleil", "t": "Il s’alimente principalement des déchets chimiques rejetés par les usines. Ce Pokémon est devenu plus rare ces derniers temps."}, {"g": "Lune", "t": "Né d’un tas de déchets exposés aux rayons X réfléchis par la lune, il meurt si les microbes qui pullulent sur son corps diminuent en nombre."}, {"g": "Ultra-Soleil", "t": "Il est né de la vase polluée des fonds marins. Dans les lieux trop propres, sa flore bactérienne ne peut pas proliférer et il dépérit."}, {"g": "Ultra-Lune", "t": "Les usines ne rejetant désormais plus de déchets toxiques, il n’a plus rien à se mettre sous la dent et se voit menacé d’extinction."}, {"g": "Let's Go Pikachu", "t": "Ce tas de fange sent si mauvais qu’il est impossible de le toucher. Plus rien ne pousse dans son sillage putride."}],
  89: [{"g": "Noir", "t": "Son corps exsude un fluide toxique qui tue instantanément les plantes et les arbres au contact."}, {"g": "X", "t": "Il recherche les endroits sales où il y a des ordures pour y établir son habitat puant et infect."}, {"g": "Rubis Oméga", "t": "Un fluide nauséabond suinte du corps de Grotadmorv, agressant les narines de ses ennemis. Une seule goutte de ce fluide suffit à faire croupir un bassin d’eau propre."}, {"g": "Saphir Alpha", "t": "Ce Pokémon ne mange que ce qui est répugnant et abject. Les Grotadmorv se rassemblent dans les villes où les gens jettent tout par terre, dans la rue."}, {"g": "Soleil", "t": "La puanteur qu’il dégage est presque insoutenable. Mais certains aficionados trouvent que c’est ce qui fait son charme."}, {"g": "Lune", "t": "La qualité de l’environnement s’étant améliorée récemment, ce Pokémon est devenu plus rare. On dit qu’il est en voie d’extinction."}, {"g": "Ultra-Soleil", "t": "Faute de nourriture, la population de Grotadmorv diminue rapidement. Pour éviter son extinction, des étangs de fange artificiels ont été creusés."}, {"g": "Ultra-Lune", "t": "Comme il répand des microbes, on lui a beaucoup fait la chasse. La population de Grotadmorv a diminué de manière drastique."}, {"g": "Let's Go Pikachu", "t": "Son odeur immonde provoque des évanouissements. Son odorat s’est atrophié à cause de sa propre puanteur."}],
  90: [{"g": "Noir", "t": "Il nage à reculons en ouvrant et en refermant ses deux coquilles. Il laisse traîner sa large langue."}, {"g": "X", "t": "Protégé par une carapace très résistante, il est vulnérable quand celle-ci s’ouvre."}, {"g": "Y", "t": "Il se referme sur un ennemi pour attaquer, mais ceci le rend vulnérable et il ne le fait que rarement."}, {"g": "Rubis Oméga", "t": "La nuit, ce Pokémon utilise sa grande langue pour creuser un trou dans le sable des fonds marins afin d’y dormir. Une fois endormi, Kokiyas referme sa coquille, mais laisse sa langue dépasser."}, {"g": "Soleil", "t": "Sa coquille est plus dure que le diamant. Dans l’Antiquité, elle a été utilisée comme bouclier."}, {"g": "Lune", "t": "Il utilise sa langue protubérante avec habileté pour creuser le sable au fond de la mer et trouver sa nourriture."}, {"g": "Ultra-Soleil", "t": "Avec le temps, les grains de sable accumulés dans sa coquille se changent en perles, mais comme elles le gênent, il préfère les recracher."}, {"g": "Ultra-Lune", "t": "Sa langue dépasse même quand sa coquille est fermée. Si on tire fort dessus, cette dernière s’ouvre sous l’effet de la surprise."}, {"g": "Let's Go Pikachu", "t": "Sa coquille le protège de toute attaque. Si elle s’ouvre, son corps fragile devient vulnérable."}, {"g": "Épée", "t": "Il nage vers l’arrière à grande vitesse en ouvrant puis refermant sa coquille."}, {"g": "Bouclier", "t": "Sa coquille est si résistante qu’elle repousse toutes les attaques. En revanche, il est vulnérable quand celle-ci s’ouvre."}],
  91: [{"g": "Noir", "t": "Il se défend en fermant sa coquille et projette des piquants qui repoussent ses agresseurs."}, {"g": "X", "t": "Les Crustabri vivant dans des mers aux courants forts développent des dards sur leur coquille."}, {"g": "Y", "t": "Sa coquille est extrêmement résistante. Rien ne peut la détruire, pas même une bombe. Il ne l’ouvre que lorsqu’il attaque."}, {"g": "Rubis Oméga", "t": "Crustabri est capable de se déplacer dans les fonds marins en avalant de l’eau et en la rejetant vers l’arrière. Ce Pokémon envoie des pointes en utilisant la même méthode."}, {"g": "Soleil", "t": "Sa carapace peut même résister à une bombe au napalm. Personne ne sait ce qu’elle dissimule."}, {"g": "Lune", "t": "Les archéologues qui explorent les tombes de chasseurs primitifs trouvent souvent des lances faites avec des épines tombées de sa carapace."}, {"g": "Ultra-Soleil", "t": "Il a une coquille à toute épreuve. En cicatrisant, les blessures sur ses valves forment des excroissances qui évoluent en dards pointus."}, {"g": "Ultra-Lune", "t": "Il raffole tant des queues de Ramoloss qu’il lui arrive de ramper jusqu’à la terre ferme pour rechercher son péché mignon."}, {"g": "Let's Go Pikachu", "t": "Sa coquille, plus dure que le diamant, le protège. Elle peut aussi envoyer de redoutables volées de dards."}, {"g": "Épée", "t": "Sa coquille est tellement résistante que rien ne peut la détruire, pas même une déflagration. Il ne l’ouvre que lorsqu’il attaque."}, {"g": "Bouclier", "t": "Quand il referme sa coquille, il est impossible de la rouvrir, même avec une force hors du commun."}],
  92: [{"g": "Noir", "t": "Son corps composé de gaz toxique pourrait asphyxier n’importe qui en quelques secondes."}, {"g": "X", "t": "Son corps est composé de gaz. Il peut ainsi envelopper un adversaire et le faire suffoquer."}, {"g": "Rubis Oméga", "t": "Fantominus est principalement constitué de matière gazeuse. Lorsqu’il est exposé au vent, son corps gazeux se disperse et diminue. Des groupes de ce Pokémon se rassemblent sous les auvents des maisons pour se protéger."}, {"g": "Soleil", "t": "Lorsqu’on aperçoit une lueur diaphane dans un bâtiment désaffecté, c’est qu’un Fantominus s’y terre."}, {"g": "Lune", "t": "Il est presque invisible, mais lorsqu’il se manifeste à proximité, une étrange odeur sucrée flotte dans l’air."}, {"g": "Ultra-Soleil", "t": "Ce Pokémon serait né des émanations gazeuses des cimetières et de la rancœur qui les habite."}, {"g": "Ultra-Lune", "t": "Il est composé à 95 % de gaz toxiques. Les 5 % restants ? Aux dires de certains, il s’agirait d’un mélange de gaz toxiques et d’âmes damnées."}, {"g": "Let's Go Pikachu", "t": "On en trouve dans les maisons en ruine. Composé de gaz, il ne possède pas de forme définie."}, {"g": "Épée", "t": "Le corps de ce Pokémon s’est formé à partir de gaz si toxiques qu’ils pourraient faire perdre connaissance à n’importe qui."}, {"g": "Bouclier", "t": "Son corps gazéiforme lui permet de se glisser n’importe où, mais au moindre coup de vent, il s’envole."}],
  93: [{"g": "Noir", "t": "Il adore se tapir dans l’ombre et faire frissonner ses proies en leur touchant l’épaule."}, {"g": "X", "t": "Si vous avez l’impression qu’on vous surveille dans le noir, c’est sûrement qu’un Spectrum est dans le coin."}, {"g": "Y", "t": "Il vole l’énergie vitale de l’ennemi d’un coup de langue gazeuse. Il aime chasser dans l’ombre."}, {"g": "Rubis Oméga", "t": "Spectrum est un Pokémon dangereux. Si l’un d’entre eux fait signe d’approcher, il ne faut jamais l’écouter. Ce Pokémon risque de sortir sa langue pour essayer de voler votre vie."}, {"g": "Soleil", "t": "Il assaille les humains depuis les ténèbres. Une personne léchée par sa langue glaciale s’affaiblit jour après jour jusqu’à décéder."}, {"g": "Lune", "t": "Il a peur de la lumière et se délecte de la nuit noire. Dans les grandes villes où l’éclairage est omniprésent, il est en voie d’extinction."}, {"g": "Ultra-Soleil", "t": "Gare aux nuits sans lune ! C’est là que Spectrum erre à la recherche d’âmes à damner. Toute promenade est fortement déconseillée."}, {"g": "Ultra-Lune", "t": "Évitez les balades nocturnes en solitaire en cas de vague à l’âme : si Spectrum vous attrape, vous ne pourrez plus rentrer chez vous !"}, {"g": "Let's Go Pikachu", "t": "Il lèche ses ennemis pour voler leur énergie vitale. Ceux-ci sont alors pris de tremblements jusqu’à ce que mort s’ensuive."}, {"g": "Épée", "t": "On raconte que quiconque est léché par sa langue faite de gaz est pris de tremblements jusqu’à ce que mort s’ensuive."}, {"g": "Bouclier", "t": "On dit que lorsque quelqu’un a l’impression d’être surveillé dans le noir, c’est sûrement qu’un Spectrum se trouve dans les parages."}],
  94: [{"g": "Noir", "t": "Si vous croisez un regard inquiétant qui perce la nuit, c’est sûrement un Ectoplasma."}, {"g": "X", "t": "On dit que lorsqu’Ectoplasma se cache dans l’ombre, la température alentour chute de 5 °C."}, {"g": "Y", "t": "Il se cache dans l’ombre des passants et vole leur chaleur. Ses victimes ressentent alors un frisson."}, {"g": "Rubis Oméga", "t": "Parfois, pendant les nuits noires, une ombre projetée par un réverbère peut tout à coup vous dépasser. Il s’agit d’un Ectoplasma qui court, en se faisant passer pour l’ombre de quelqu’un d’autre."}, {"g": "Soleil", "t": "Si vous frissonnez soudainement, c’est qu’un Ectoplasma en veut à votre vie. Vous ne pouvez y échapper. Abandonnez toute espérance."}, {"g": "Lune", "t": "S’il attente à la vie des humains, c’est parce qu’ils deviendront des Ectoplasma après la mort et qu’il veut les entraîner avec lui."}, {"g": "Ultra-Soleil", "t": "Les enfants du monde entier redoutent la menace de l’Ectoplasma qui viendra les chercher s’ils ne sont pas sages."}, {"g": "Ultra-Lune", "t": "Même chez soi, on n’est pas à l’abri. Ectoplasma attend, tapi dans un recoin sombre, pour mieux bondir sur ses proies..."}, {"g": "Let's Go Pikachu", "t": "Si vous êtes pris de frissons soudains, c’est qu’un Ectoplasma rôde dans les parages. Il pourrait peut-être même vous lancer une malédiction."}, {"g": "Épée", "t": "Un soir de pleine lune, si une ombre se met à bouger et éclate de rire, c’est sûrement l’œuvre d’un Ectoplasma."}, {"g": "Bouclier", "t": "On dit qu’Ectoplasma surgit parfois des ténèbres pour prendre la vie des personnes égarées en montagne."}],
  95: [{"g": "Noir", "t": "Il se nourrit des pierres qu’il rencontre en creusant le sol. Il peut creuser à 80 km/h!"}, {"g": "X", "t": "Il creuse sous terre en quête de nourriture. Ses tunnels servent de maison aux Taupiqueur."}, {"g": "Y", "t": "Onix vit généralement sous terre. Il cherche de la nourriture en creusant à plus de 80 km/h."}, {"g": "Rubis Oméga", "t": "Onix a dans le cerveau un aimant qui lui sert de boussole. Il permet à ce Pokémon de ne pas se perdre pendant qu’il creuse. En prenant de l’âge, son corps s’arrondit et se polit."}, {"g": "Let's Go Pikachu", "t": "Il creuse la terre à toute allure en quête de nourriture. Ses tunnels servent de maison aux Taupiqueur."}, {"g": "Épée", "t": "Il absorbe des éléments solides en creusant le sol, ce qui le rend plus robuste."}, {"g": "Bouclier", "t": "Il creuse dans le sol à une vitesse de 80 km/h en contorsionnant son immense corps de pierre."}],
  96: [{"g": "Noir", "t": "Son grand nez lui permet de lire les rêves d’autrui. Il adore les songes amusants."}, {"g": "X", "t": "Il endort ses ennemis et dévore leurs songes. S’il mange trop de cauchemars, il fait une indigestion."}, {"g": "Y", "t": "Si vous pensez avoir rêvé mais que vous ne vous en souvenez pas, c’est que Soporifik a tout mangé."}, {"g": "Rubis Oméga", "t": "Lorsque les enfants ont le nez qui les démange en dormant, c’est sans doute parce que ce Pokémon se tient au-dessus de leur oreiller, afin d’essayer de manger leurs rêves par leurs narines."}, {"g": "Soleil", "t": "Un Pokémon qui se nourrit de rêves. On suppose qu’il a un ancêtre commun avec Munna et Mushana."}, {"g": "Lune", "t": "Les rêves agréables ont meilleur goût. S’il vous considère comme un ami, il peut transformer les vôtres en ceux qu’il a trouvés les plus délicieux."}, {"g": "Ultra-Soleil", "t": "Il aime musarder près des parcs d’attractions : après y avoir passé une bonne journée, les enfants font de beaux rêves, dont il se délecte."}, {"g": "Ultra-Lune", "t": "Il regarde ses proies dormir et avale leurs rêves. Les cauchemars ayant un petit goût aigrelet, il a tendance à les bouder."}, {"g": "Let's Go Pikachu", "t": "Si vous dormez tout le temps près de lui, il partagera parfois avec vous les rêves qu’il a dévorés par le passé."}],
  97: [{"g": "Noir", "t": "La vue de son pendule oscillant endort en trois secondes, même quand on vient de se réveiller."}, {"g": "X", "t": "Il transporte toujours un petit pendule. On raconte qu’il aurait un jour enlevé un enfant après l’avoir hypnotisé."}, {"g": "Rubis Oméga", "t": "Hypnomade tient un pendule dans sa main. Le mouvement de balancier et les reflets brillants du pendule hypnotisent profondément son ennemi. Lorsque ce Pokémon cherche ses proies, il nettoie son pendule."}, {"g": "Soleil", "t": "Bien que ce soit un Pokémon extrêmement dangereux, les personnes victimes d’insomnie le considèrent comme un sauveur."}, {"g": "Lune", "t": "Quand il rencontre quelqu’un, il l’endort et goûte ses rêves. S’ils ont bon goût, il emporte la personne avec lui."}, {"g": "Ultra-Soleil", "t": "À Alola, les Hypnomade s’en prennent principalement aux Dodoala. Les humains n’ont donc pas grand-chose à craindre."}, {"g": "Ultra-Lune", "t": "Certains Hypnomade travaillent comme assistants dans les cliniques visant à guérir les patients de leurs insomnies."}, {"g": "Let's Go Pikachu", "t": "Évitez son regard quand vous en croisez un, ou il pourrait essayer de vous hypnotiser avec son pendule."}],
  98: [{"g": "Noir", "t": "Il creuse son terrier sur des plages sablonneuses. Ses pinces repoussent si on les brise."}, {"g": "X", "t": "S’il est menacé, il se cache derrière les bulles émises par sa bouche pour paraître plus gros."}, {"g": "Y", "t": "On trouve ce Pokémon près de la mer. Ses grosses pinces peuvent repousser si elles se font arracher."}, {"g": "Rubis Oméga", "t": "Krabby vit sur les plages, enterré dans le sable. Sur les plages où on trouve peu de nourriture, on peut voir ces Pokémon se disputer pour défendre leur territoire."}, {"g": "Let's Go Pikachu", "t": "Ses pinces sont des armes puissantes. Il peut arriver qu’elles se brisent durant un combat, mais elles repoussent vite."}, {"g": "Épée", "t": "On trouve ce Pokémon près de la mer. Ses grosses pinces peuvent repousser si elles sont arrachées."}, {"g": "Bouclier", "t": "S’il se sent menacé, il se cache derrière les bulles émises par sa bouche pour paraître plus gros."}],
  99: [{"g": "Noir", "t": "Sa grande pince possède une puissance de 10 000 chevaux. Son poids la rend difficile à manier."}, {"g": "X", "t": "Sa grosse pince développe une puissance de 10 000 CV. Toutefois, sa taille imposante la rend difficile à utiliser."}, {"g": "Y", "t": "Sa pince devient énorme. S’il la soulève trop vite, il risque de perdre l’équilibre."}, {"g": "Rubis Oméga", "t": "Krabboss est doté d’une pince gigantesque, surdimensionnée. Il l’agite en l’air pour communiquer avec ses semblables. En revanche, sa pince est tellement lourde que ce Pokémon se fatigue très vite."}, {"g": "Let's Go Pikachu", "t": "Sa grosse pince, dure comme de l’acier, est d’une puissance incommensurable, mais elle est trop lourde."}, {"g": "Épée", "t": "Sa grosse pince est dotée d’une puissance incommensurable. Sa taille imposante la rend toutefois difficile à utiliser."}, {"g": "Bouclier", "t": "Sa pince gigantesque possède une puissance destructrice phénoménale, mais hors combat, son poids devient un handicap."}],
  100: [{"g": "Noir", "t": "Il ressemble à une Poké Ball. Ce Pokémon dangereux peut exploser ou s’électrifier au toucher."}, {"g": "X", "t": "Découvert en même temps que les Poké Balls. Il paraît qu’il existe un lien entre les deux."}, {"g": "Y", "t": "Vivant près des centrales électriques, ce Pokémon survolté est souvent confondu avec une Poké Ball."}, {"g": "Rubis Oméga", "t": "La première fois qu’on a vu Voltorbe, c’était dans une usine qui fabrique des Poké Balls. Personne n’a jamais pu expliquer le lien entre cet événement et la ressemblance frappante de ce Pokémon avec une Poké Ball."}, {"g": "Saphir Alpha", "t": "Voltorbe est extrêmement sensible. Il explose au moindre choc. On raconte qu’il fut créé par l’exposition d’une Poké Ball à une puissante dose d’énergie."}, {"g": "Let's Go Pikachu", "t": "On dit qu’il se déguise en Poké Ball. Il s’autodétruit à la moindre stimulation."}],
  101: [{"g": "Noir", "t": "Il se laisse porter par les vents lorsque son corps est gonflé d’électricité à en éclater."}, {"g": "X", "t": "Il explose au moindre choc. Son seul surnom de « Bomb Ball » suffit à effrayer ses adversaires."}, {"g": "Y", "t": "Il stocke tellement d’énergie dans son corps qu’une simple secousse peut le faire exploser."}, {"g": "Rubis Oméga", "t": "Électrode mange l’électricité qui se trouve dans l’atmosphère. Les jours d’orage, on peut voir ce Pokémon exploser sans arrêt parce qu’il a avalé trop d’électricité."}, {"g": "Saphir Alpha", "t": "L’une des caractéristiques d’Électrode est son attirance pour l’électricité. Ces Pokémon posent problème lorsqu’ils se rassemblent dans les centrales électriques pour se nourrir de courant fraîchement généré."}, {"g": "Let's Go Pikachu", "t": "Il stocke de l’énergie électrique dans son corps, ce qui le rend instable et explosif."}],
  102: [{"g": "Noir", "t": "Ces six œufs communiquent par télépathie. Ils peuvent se réunir rapidement si on les sépare."}, {"g": "Y", "t": "Même s’il ressemble à des œufs, ce Pokémon appartient à la famille des végétaux."}, {"g": "Rubis Oméga", "t": "Ce Pokémon est constitué de six œufs formant une grappe serrée. Ces six œufs s’attirent mutuellement et pivotent. Quand des fissures apparaissent sur les coquilles, ça signifie que Noeunoeuf est sur le point d’évoluer."}, {"g": "Soleil", "t": "Il communique avec ses amis par télépathie. Son ADN est un mélange de celui d’une plante et d’un autre type non identifié."}, {"g": "Lune", "t": "Ce Pokémon est composé de six œufs. Ils sont souvent attaqués par des Crabagarre, mais ils se défendent avec leurs pouvoirs psy."}, {"g": "Ultra-Soleil", "t": "Six pour le prix d’un ! Si par malheur l’un d’entre eux disparaît, il est remplacé dès le lendemain matin par une nouvelle recrue."}, {"g": "Ultra-Lune", "t": "Bien qu’ils fassent la même taille, les Noeunoeuf d’Alola sont plus lourds que ceux des autres régions, car leur intérieur est bien plus dense."}, {"g": "Let's Go Pikachu", "t": "Ses têtes sont attirées les unes vers les autres et pivotent. Il en faut six pour qu’il maintienne son équilibre."}, {"g": "Épée", "t": "Même s’il ressemble à un tas d’œufs, il s’agit bien d’un Pokémon. Il paraît qu’ils communiquent entre eux par télépathie."}, {"g": "Bouclier", "t": "Il a besoin d’être constitué de ses six membres pour rester calme. Sitôt qu’il en manque un, il lui prend soudainement l’envie de fuir."}],
  103: [{"g": "Noir", "t": "On l’appelle “jungle sur pattes”. Si une tête devient trop grosse, elle tombe et produit un Noeunoeuf."}, {"g": "X", "t": "Ses trois têtes sont autonomes. Elles semblent toutefois en harmonie et ne se disputent jamais."}, {"g": "Y", "t": "On l’appelle « jungle sur pattes ». Si une tête devient trop grosse, elle tombe et produit un Noeunoeuf."}, {"g": "Rubis Oméga", "t": "Noadkoko vient des tropiques. À force de vivre sous un soleil ardent, ses têtes ont rapidement grandi. On raconte que lorsque ses têtes tombent, elles se rassemblent et forment un Noeunoeuf."}, {"g": "Soleil", "t": "Chaque tête a sa volonté propre. Toutes discutent ensemble par télépathie et décident de ce qu’elles vont faire d’un commun accord."}, {"g": "Lune", "t": "À un certain moment de sa vie, l’une des trois têtes tombe. Elle germera en un nouveau Noeunoeuf."}, {"g": "Ultra-Soleil", "t": "Il frappe ses adversaires de ses pouvoirs psychiques. Comme il a trois têtes, la puissance de ses attaques s’en voit triplée."}, {"g": "Ultra-Lune", "t": "Ses trois têtes pensent indépendamment. Si elles ne se mettent pas d’accord sur le chemin à emprunter, Noadkoko fait du surplace."}, {"g": "Let's Go Pikachu", "t": "Si son cri est aussi bruyant, c’est parce que chacune de ses trois têtes dit ce qu’elle pense."}, {"g": "Épée", "t": "Chacune de ses trois têtes pense de manière autonome. Elles ne semblent s’intéresser qu’à elles-mêmes."}, {"g": "Bouclier", "t": "Les attaques psychiques lancées par ses trois têtes à l’unisson sont très puissantes. Par temps nuageux, ses mouvements sont plus lents."}],
  104: [{"g": "Noir", "t": "Il pleure en pensant à sa mère disparue, et ses larmes résonnent dans son crâne creux."}, {"g": "X", "t": "Ce Pokémon porte le crâne de sa défunte mère sur sa tête. On raconte qu’il se met à pleurer dès qu’il se retrouve seul."}, {"g": "Y", "t": "Il porte constamment le crâne de sa mère. Personne ne sait à quoi il ressemble sans ce crâne."}, {"g": "Rubis Oméga", "t": "La maman d’Osselait lui manque terriblement et il ne la reverra jamais. La lune le fait pleurer, car elle lui rappelle sa mère. Les taches sur le crâne que porte ce Pokémon sont les marques de ses larmes."}, {"g": "Soleil", "t": "Quand il se souvient de la mort de sa mère, il pleure à grands sanglots. Les Vaututrice entendent ces cris et fondent sur leur proie."}, {"g": "Lune", "t": "Le crâne qu’il porte sur la tête est celui de sa mère décédée. On dit qu’il évolue lorsqu’il parvient à surpasser la douleur de sa mort."}, {"g": "Ultra-Soleil", "t": "La nuit, il pense avec nostalgie à sa défunte mère et éclate en sanglots. Vaututrice, son prédateur, le localise au son de ses pleurs."}, {"g": "Ultra-Lune", "t": "Comme il porte le crâne de sa mère sur sa tête, nul ne connaît son vrai visage. Une seule chose est sûre : il ne cesse de pleurer."}, {"g": "Let's Go Pikachu", "t": "Il porte le crâne de sa défunte mère. Ses pleurs résonnent dans son casque en une triste mélodie."}, {"g": "Épée", "t": "Lorsqu’il repense à sa mère défunte, ses sanglots résonnent tristement sous le crâne qu’il porte sur la tête."}, {"g": "Bouclier", "t": "Il porte sur sa tête le crâne de sa défunte mère. Il lui arrive de rêver d’elle et de pleurer, mais chaque larme qu’il verse le rend plus fort."}],
  105: [{"g": "Noir", "t": "Ce Pokémon sauvage possède des os depuis sa naissance. Il s’en sert pour combattre avec dextérité."}, {"g": "X", "t": "Ce petit Pokémon était à l’origine très faible. Il est devenu redoutable le jour où il a appris à se servir de ses os."}, {"g": "Y", "t": "L’os qu’il tient dans la main est son arme la plus efficace. Il s’en sert comme d’un boomerang pour assommer sa proie."}, {"g": "Rubis Oméga", "t": "Ossatueur est la forme évoluée d’Osselait. Il a surmonté le chagrin causé par la perte de sa maman et s’est endurci. Le tempérament décidé et entier de ce Pokémon le rend très difficile à amadouer."}, {"g": "Soleil", "t": "Il était faible et peureux, mais après avoir évolué, il a appris à manier son os avec férocité et est devenu plus violent et agressif."}, {"g": "Lune", "t": "Il lance le grand os comme un boomerang pour abattre son ancien prédateur, les Vaututrice, pour se venger."}, {"g": "Ultra-Soleil", "t": "Il lance son os pour abattre les Vaututrice. On pense qu’il agit ainsi pour venger sa mère."}, {"g": "Ultra-Lune", "t": "Il joue des percussions avec son os afin de communiquer avec ses congénères. Il existe une cinquantaine de mélodies différentes."}, {"g": "Let's Go Pikachu", "t": "Ce Pokémon, autrefois si petit et si faible, est devenu très féroce. Il se bat habilement, armé de son os."}, {"g": "Épée", "t": "Il s’est endurci et a évolué depuis qu’il a réussi à surmonter sa peine. Il utilise son os en guise d’arme et affronte ses ennemis avec bravoure."}, {"g": "Bouclier", "t": "En évoluant, il est devenu violent, et le crâne de sa mère qu’il portait a fusionné avec sa tête."}],
  106: [{"g": "Noir", "t": "Ses pattes élastiques s’allongent, ce qui ne manque jamais de surprendre au premier combat."}, {"g": "X", "t": "Kicklee peut rétracter et allonger ses jambes à sa guise. La formidable allonge dont il dispose lui donne souvent l’avantage en plein combat."}, {"g": "Y", "t": "S’il commence à donner des séries de coups de pied, ses jambes grandissent et il gagne en allonge."}, {"g": "Rubis Oméga", "t": "Les jambes de Kicklee peuvent se contracter et s’étirer à volonté. Grâce à ces jambes à ressort, il terrasse ses ennemis en les rouant de coups de pied. Après les combats, il masse ses jambes pour éviter de sentir la fatigue."}, {"g": "Let's Go Pikachu", "t": "Ses pieds deviennent durs comme le diamant quand il donne des coups, pulvérisant ainsi ses adversaires."}, {"g": "Épée", "t": "Il possède un fantastique sens de l’équilibre, et peut donner des rafales de coups de pied dans toutes les positions."}, {"g": "Bouclier", "t": "Kicklee peut rétracter et étendre ses jambes à sa guise. La formidable allonge dont il dispose lui permet de frapper des adversaires éloignés."}],
  107: [{"g": "Noir", "t": "Même le béton cède sous ses poings dévastateurs. Au combat, il s’essouffle au bout de 3 minutes."}, {"g": "X", "t": "Même le béton cède sous ses poings dévastateurs. Au combat, il s’essouffle au bout de trois minutes."}, {"g": "Y", "t": "Tygnon possède l’esprit combatif des plus grands champions de boxe. Ses coups de poing partent plus vite qu’un boulet de canon."}, {"g": "Rubis Oméga", "t": "On raconte que Tygnon dispose de l’état d’esprit d’un boxeur qui s’entraîne pour le championnat du monde. Ce Pokémon est doté d’une ténacité à toute épreuve et n’abandonne jamais face à l’adversité."}, {"g": "Let's Go Pikachu", "t": "Ses coups de poing rotatifs sont si puissants qu’ils peuvent percer le béton comme une foreuse."}, {"g": "Épée", "t": "Ses poings fendent l’air. Ils sont si rapides qu’un simple frôlement peut causer une brûlure."}, {"g": "Bouclier", "t": "Ses poings fendent l’air, mais il se fatigue au bout de trois minutes à enchaîner les coups."}],
  108: [{"g": "Noir", "t": "Quand il déploie sa langue de près de deux mètres, sa queue s’agite. Elles seraient reliées entre elles."}, {"g": "X", "t": "Sa longue langue sécrète une salive gluante qui se colle à n’importe quoi. Elle est très efficace !"}, {"g": "Y", "t": "Sa langue fait deux fois la taille de son corps. Il l’utilise comme un bras pour saisir de la nourriture mais aussi pour attaquer."}, {"g": "Rubis Oméga", "t": "Chaque fois qu’Excelangue découvre quelque chose de nouveau, il le lèche. Sa mémoire est basée sur le goût et la texture des objets. Il n’aime pas les choses acides."}, {"g": "Ultra-Soleil", "t": "Sa longue langue lui sert à goûter tout ce qui l’intrigue. Attention, car s’il vous lèche une partie du corps, vous risquez l’infection cutanée."}, {"g": "Ultra-Lune", "t": "Il nettoie les saletés d’un coup de langue, mais vu l’odeur nauséabonde qui s’en dégage, ce n’est probablement pas très efficace."}, {"g": "Let's Go Pikachu", "t": "Sa langue mesure 2 m et elle est plus agile que ses pattes. Son contact provoque la paralysie."}, {"g": "Épée", "t": "Si sa salive gluante entre en contact avec la peau et qu’on ne l’essuie pas bien, elle provoque de terribles démangeaisons qui ne s’arrêtent jamais."}, {"g": "Bouclier", "t": "Excelangue se nourrit essentiellement de Pokémon Insecte. Il lèche ses ennemis avec sa longue langue pour les paralyser, puis les avale tout rond."}],
  109: [{"g": "Noir", "t": "Il flotte en retenant des gaz plus légers que l’air. Ceux-ci sont explosifs, en plus d’être fétides."}, {"g": "X", "t": "Son corps très fin en forme de ballon est rempli d’un horrible gaz toxique. L’air est nauséabond à proximité de ce Pokémon."}, {"g": "Rubis Oméga", "t": "Lorsque Smogo s’agite, ça augmente la toxicité de ses gaz internes. Il les projette ensuite par les nombreux orifices de son corps. Ce Pokémon peut aussi gonfler son corps et le faire exploser."}, {"g": "Saphir Alpha", "t": "Smogo est composé de substances toxiques. Il mélange des toxines et des détritus pour déclencher une réaction chimique générant un gaz très dangereux. Plus la température est élevée, plus la quantité de gaz est importante."}, {"g": "Let's Go Pikachu", "t": "Les gaz que renferme son corps deviennent instables lorsqu’il se trouve dans un endroit chaud. Prenez garde, il pourrait exploser !"}, {"g": "Épée", "t": "Son corps est gonflé de gaz toxique. Il se rend dans les décharges, attiré par l’odeur des déchets alimentaires en décomposition."}, {"g": "Bouclier", "t": "On raconte qu’il y a longtemps, ces Pokémon amateurs d’air pollué étaient beaucoup plus nombreux à Galar."}],
  110: [{"g": "Noir", "t": "Il grandit en absorbant les gaz des détritus. Des triplés existent, bien qu’ils soient fort rares."}, {"g": "X", "t": "Si l’un des deux Smogo se gonfle, l’autre se dégonfle. Ils mélangent leurs gaz en permanence."}, {"g": "Y", "t": "Il peut arriver que deux Smogo mutent et s’associent pour former un Smogogo, mais c’est très rare."}, {"g": "Rubis Oméga", "t": "Smogogo adore les gaz qui se dégagent des aliments pourris dans les poubelles. Ce Pokémon cherche généralement les maisons sales et mal tenues pour y habiter. La nuit, quand tout le monde est endormi, il fouille les détritus."}, {"g": "Saphir Alpha", "t": "Smogogo rétrécit ou gonfle ses deux corps pour mélanger les gaz toxiques qui s’y trouvent. Lorsque les gaz sont bien mélangés, la toxine devient très puissante. Le Pokémon se putréfie aussi un peu plus."}, {"g": "Let's Go Pikachu", "t": "Ce Pokémon se nourrit des gaz toxiques, des germes et de la poussière qu’il trouve dans les tas d’ordures."}, {"g": "Épée", "t": "Il mélange des gaz dans ses deux corps. On raconte qu’autrefois, on en voyait partout dans la région de Galar."}, {"g": "Bouclier", "t": "Il ne peut pas aspirer autant d’air que le Smogogo de Galar, mais le poison qu’il produit est plus puissant."}],
  111: [{"g": "Noir", "t": "Ses puissantes charges pourraient démolir n’importe quel bâtiment. Dommage qu’il soit stupide."}, {"g": "X", "t": "Costaud mais pas très intelligent, ce Pokémon est capable de détruire un immeuble entier en utilisant sa Charge."}, {"g": "Y", "t": "Ses petites jambes ne lui permettent pas de tourner facilement. Il ne peut charger que tout droit."}, {"g": "Rubis Oméga", "t": "Rhinocorne charge droit devant lui, détruisant tout sur son passage. Il ne s’arrête jamais, même lorsqu’il charge un bloc d’acier. Malgré tout, il sent la douleur le lendemain."}, {"g": "Saphir Alpha", "t": "Le cerveau de Rhinocorne est tout petit, à tel point que lorsqu’il attaque, il lui arrive d’oublier pourquoi il a commencé à charger. Il lui arrive de se souvenir qu’il a démoli certaines choses."}, {"g": "Let's Go Pikachu", "t": "Un Pokémon obstiné. S’il se met à charger, il s’arrête uniquement quand il s’endort."}, {"g": "Épée", "t": "Costaud, mais pas très intelligent, ce Pokémon est capable de détruire un immeuble entier en fonçant dessus."}, {"g": "Bouclier", "t": "Il ne peut se souvenir que d’une chose à la fois. S’il se met à courir, il en oublie tout de suite la raison."}],
  112: [{"g": "Noir", "t": "La station debout a libéré ses pattes avant et l’a rendu plus intelligent, mais il est distrait."}, {"g": "X", "t": "Son épiderme très épais lui permet de survivre dans un environnement où il fait plus de 2 000 °C."}, {"g": "Y", "t": "L’évolution a permis à ce Pokémon de marcher sur ses pattes arrière. Il peut facilement faire des trous dans les rochers en utilisant sa corne."}, {"g": "Rubis Oméga", "t": "La corne de Rhinoféros peut même casser du diamant brut. Et avec un simple coup de queue, il peut détruire un bâtiment. La peau de ce Pokémon est incroyablement dure. Un boulet de canon ne lui ferait même pas une égratignure."}, {"g": "Saphir Alpha", "t": "La corne de Rhinoféros lui sert de foreuse. Il l’utilise pour détruire des rochers et des cailloux. Ce Pokémon charge de temps en temps dans du magma en fusion, mais sa peau blindée le protège de la chaleur."}, {"g": "Let's Go Pikachu", "t": "L’évolution a permis à ce Pokémon de développer son intelligence et de se tenir debout. Son épiderme résiste à la lave."}, {"g": "Épée", "t": "L’évolution a permis à ce Pokémon de marcher sur ses pattes postérieures. Il peut faire des trous dans les rochers en utilisant sa corne."}, {"g": "Bouclier", "t": "Son épiderme est si épais qu’il lui permet même de survivre dans du magma d’une température de 2 000 °C."}],
  113: [{"g": "Noir", "t": "Ce Pokémon très serviable distribue ses œufs hautement nutritifs aux humains et Pokémon blessés."}, {"g": "X", "t": "Il est censé apporter la joie. Ce Pokémon charitable offre ses œufs aux blessés."}, {"g": "Y", "t": "Il peut pondre plusieurs œufs par jour. Ses œufs sont très riches en nutriments et vraiment délicieux."}, {"g": "Rubis Oméga", "t": "Leveinard pond tous les jours des œufs pleins de vitamines. Ces œufs sont tellement bons que les gens les mangent même quand ils n’ont pas faim."}, {"g": "Soleil", "t": "Les œufs pondus par Leveinard sont extrêmement nutritifs. C’est la nourriture favorite de beaucoup de Pokémon."}, {"g": "Lune", "t": "C’est un Pokémon assez rare et qui prend la fuite très rapidement. Apercevoir ce Pokémon est un signe que la chance vous sourit."}, {"g": "Ultra-Soleil", "t": "À force de fuir les Pokémon qui en avaient après ses œufs, réputés pour leur goût et leur valeur nutritive, il a appris à courir plus vite."}, {"g": "Ultra-Lune", "t": "Pendant longtemps, ce Pokémon a été chassé à outrance pour ses œufs, ce qui explique sa population fort réduite."}, {"g": "Let's Go Pikachu", "t": "D’un naturel gentil et aimable, il partage ses œufs nourrissants avec les blessés."}, {"g": "Épée", "t": "Ses œufs sont si délicieux et nutritifs qu’on les considère comme des ingrédients de luxe."}, {"g": "Bouclier", "t": "Ce Pokémon lent à l’origine a appris à fuir plus vite pour protéger ses œufs des voleurs."}],
  114: [{"g": "Noir", "t": "Il se cache derrière des lianes bleues recouvertes d’un fin duvet. Il est chatouilleux."}, {"g": "X", "t": "Ses lianes s’allongent au fil du temps. Elles recouvrent tout son corps, dont on ignore la véritable forme."}, {"g": "Y", "t": "Il paralyse tout ce qui bouge avec ses lianes. Elles vous chatouillent si vous êtes capturé."}, {"g": "Rubis Oméga", "t": "Les lianes de Saquedeneu se brisent facilement lorsqu’on les attrape. Cela ne lui fait pas mal et lui permet simplement de s’échapper rapidement. Les lianes cassées repoussent le lendemain."}, {"g": "Let's Go Pikachu", "t": "Son corps est masqué par une masse épaisse de lianes bleues qui poussent en permanence."}, {"g": "Épée", "t": "On ne sait toujours pas ce qui se cache sous ses lianes. Même si on les coupe, elles repoussent à l’infini."}, {"g": "Bouclier", "t": "Ses lianes ont une odeur particulière. Elles servent d’herbes aromatiques dans une certaine zone de Galar."}],
  115: [{"g": "Noir", "t": "Il élève ses petits dans sa poche ventrale. Il attend d’être en lieu sûr pour les laisser jouer dehors."}, {"g": "Y", "t": "Dans les endroits sûrs, le petit quitte sa poche pour jouer sous la protection des adultes."}, {"g": "Rubis Oméga", "t": "Lorsqu’on rencontre un petit Kangourex qui joue tout seul, il ne faut jamais le déranger ou essayer de l’attraper. Les parents du bébé Pokémon sont sûrement dans le coin et ils risquent d’entrer dans une colère noire."}, {"g": "Soleil", "t": "L’amour maternel de Kangourex est sans limites. Elle marcherait au-devant de la mort pour protéger son bébé."}, {"g": "Lune", "t": "Le bébé quitte la poche de sa mère au bout de trois ans. C’est le seul moment de sa vie où elle pleure à chaudes larmes."}, {"g": "Ultra-Soleil", "t": "Kangourex protège son petit en le mettant dans sa poche, et se montre sans pitié envers quiconque ose lui faire du mal."}, {"g": "Ultra-Lune", "t": "Ne vous approchez surtout pas d’un bébé Kangourex sorti de sa poche pour jouer ! Sa mère le surveille sûrement d’un peu plus loin."}, {"g": "Let's Go Pikachu", "t": "Ce Pokémon élève son petit dans sa poche ventrale. Il est prêt à combattre n’importe quel ennemi pour le protéger."}, {"g": "Épée", "t": "Porter son petit dans sa poche ventrale ne l’empêche pas d’avoir un bon jeu de jambes. Ses coups rapides intimident ses ennemis."}, {"g": "Bouclier", "t": "Certains documents certifient que les Kangourex sans progéniture élevaient des enfants humains en détresse."}],
  116: [{"g": "Noir", "t": "Il niche à l’ombre du corail. Quand il se sent menacé, il disparaît dans un nuage d’encre opaque."}, {"g": "X", "t": "Il abat les insectes volants en leur tirant un jet d’encre depuis la surface de l’eau. Ses tirs sont toujours précis."}, {"g": "Rubis Oméga", "t": "Hypotrempe mange des petits insectes et de la mousse trouvée sur les cailloux. Lorsque les courants océaniques sont trop forts, ce Pokémon peut s’ancrer en accrochant sa queue aux rochers ou aux coraux."}, {"g": "Saphir Alpha", "t": "Lorsque Hypotrempe sent un danger, il libère instinctivement une épaisse encre noire pour pouvoir s’échapper. Ce Pokémon nage en agitant sa nageoire dorsale."}, {"g": "Let's Go Pikachu", "t": "Lorsqu’il est menacé, ce Pokémon crache une encre spéciale ou de l’eau pour se défendre."}, {"g": "Épée", "t": "Il vit dans les mers calmes. Quand on l’attaque, il crache de l’encre noire et profite de la diversion pour s’enfuir."}, {"g": "Bouclier", "t": "Hypotrempe crée des tourbillons en dansant sous l’eau. Il s’amuse à comparer la taille des remous qu’il fait avec ceux de ses congénères."}],
  117: [{"g": "Noir", "t": "Son épine dorsale le protège. Ses os et ses nageoires sont très prisés en médecine traditionnelle."}, {"g": "X", "t": "Son corps est recouvert de pointes tranchantes. Il faut la plus grande attention pour le saisir, sous peine de se faire piquer."}, {"g": "Y", "t": "Il peut nager à l’envers en agitant ses petites nageoires pectorales."}, {"g": "Rubis Oméga", "t": "Hypocéan s’accroche aux récifs de corail avant de s’endormir. Les pêcheurs de coraux se font parfois piquer par les aiguillons de ce Pokémon lorsqu’ils ne font pas attention."}, {"g": "Saphir Alpha", "t": "Hypocéan déclenche des tourbillons en faisant tournoyer son corps. Ces tourbillons sont assez puissants pour engloutir des bateaux de pêche. Ce Pokémon affaiblit sa proie grâce à ces courants, puis l’avale en une bouchée."}, {"g": "Let's Go Pikachu", "t": "Le contact de ses nageoires dorsales engourdit. Il ancre sa queue au corail quand il dort pour éviter que le courant ne l’emporte."}, {"g": "Épée", "t": "Les mâles s’occupent des petits, et tant qu’ils en ont à élever, le venin contenu dans leurs épines dorsales devient beaucoup plus fort."}, {"g": "Bouclier", "t": "Sa puissance de succion est si forte qu’il peut aspirer en un instant ses proies pour les manger, même si elles sont plus grosses que sa bouche."}],
  118: [{"g": "Noir", "t": "Malgré son élégance quand il nage, ses coups de corne sont redoutables."}, {"g": "X", "t": "Il nage à 5 nœuds. Quand on l’agresse, il réplique d’un bon coup de corne aiguisée."}, {"g": "Y", "t": "Ses nageoires dorsales et pectorales bougent avec élégance. Il est surnommé le danseur des flots."}, {"g": "Rubis Oméga", "t": "Poissirène est un Pokémon magnifique doté de nageoires qui ondulent élégamment dans les profondeurs. Il ne faut pourtant pas baisser sa garde face à ce Pokémon, car il peut charger avec sa puissante corne."}, {"g": "Saphir Alpha", "t": "Poissirène adore nager librement dans les rivières et les étangs. Si l’un de ces Pokémon est mis dans un aquarium, il n’hésitera pas à casser la vitre avec sa puissante corne pour s’enfuir."}, {"g": "Soleil", "t": "À la fin de l’hiver, des bancs de Poissirène remontent les fleuves. Ce spectacle annonce traditionnellement l’arrivée du printemps."}, {"g": "Lune", "t": "Séduits par la longueur de sa corne et la beauté de ses nageoires, de nombreux Dresseurs esthètes n’élèvent plus que des Poissirène."}, {"g": "Ultra-Soleil", "t": "Prisés pour la beauté de leur nageoire caudale, les Poissirène rivalisent quant à eux pour savoir qui a la corne la plus épaisse et la plus acérée."}, {"g": "Ultra-Lune", "t": "La beauté de ses nageoires, qu’il agite telle une robe de bal, lui a valu le surnom de « princesse des eaux »."}, {"g": "Let's Go Pikachu", "t": "Quand vient la saison de ponte des Poissirène, on peut en voir de larges groupes remonter les rivières et les cascades."}, {"g": "Épée", "t": "Ses nageoires dorsales, pectorales et caudales ondulent avec élégance. Il est surnommé le « danseur des flots »."}, {"g": "Bouclier", "t": "Ses nageoires dorsales et pectorales sont très développées. Elles lui permettent de nager à une vitesse de cinq nœuds."}],
  119: [{"g": "Noir", "t": "En automne, à la saison des amours, il fait des réserves de graisse et arbore des couleurs chatoyantes."}, {"g": "X", "t": "Pendant la saison des amours, on peut le voir nager dans les rivières et les lacs."}, {"g": "Y", "t": "Il niche dans des rochers du ruisseau qu’il évide avec sa corne. Il donnerait sa vie pour ses Œufs."}, {"g": "Rubis Oméga", "t": "En automne, on peut voir les Poissoroy mâles effectuer des danses nuptiales dans les rivières pour plaire aux femelles. C’est pendant cette saison que le corps de ce Pokémon prend ses plus belles couleurs."}, {"g": "Saphir Alpha", "t": "Les Poissoroy font tout pour protéger leurs œufs. Les mâles et les femelles patrouillent pour surveiller le nid et les œufs. La garde de ces œufs dure un peu plus d’un mois."}, {"g": "Soleil", "t": "Quand il commence à faire froid, son corps devient rouge vif. Ce spectacle annonce traditionnellement la venue de l’automne."}, {"g": "Lune", "t": "Il existe deux types de Dresseurs de Poissoroy : ceux qui aiment sa corne et ceux qui préfèrent ses nageoires. Les deux groupes se détestent."}, {"g": "Ultra-Soleil", "t": "Il peut forer des rocs en faisant tourner sa corne comme une perceuse. Les mâles ont des couleurs plus vives que les femelles."}, {"g": "Ultra-Lune", "t": "Les mâles dansent devant les femelles pour s’attirer leurs faveurs ; les plus talentueux gagneront leur admiration."}, {"g": "Let's Go Pikachu", "t": "Le mâle utilise la corne située sur son front pour creuser un nid dans les rochers au fond des rivières."}, {"g": "Bouclier", "t": "S’il fait des trous dans les rochers avec sa corne pour bâtir son nid, c’est pour éviter que ses Œufs ne soient emportés par les flots."}],
  120: [{"g": "Noir", "t": "Même amoché, son corps se régénère tant que le noyau rouge est intact. Le noyau s’illumine à minuit."}, {"g": "X", "t": "Même si son corps est détruit, il peut se régénérer aussi longtemps que son cœur est en bon état."}, {"g": "Y", "t": "On peut voir des Stari en grand nombre près des côtes. La nuit, le centre de son corps clignote d’une lumière rouge."}, {"g": "Rubis Oméga", "t": "Au centre de Stari se trouve un organe rouge et brillant appelé le cœur. À la fin de l’été, sur les plages, les cœurs de ces Pokémon brillent comme les étoiles dans le ciel."}, {"g": "Saphir Alpha", "t": "Stari communique apparemment avec les étoiles dans le ciel en faisant clignoter son cœur rouge. Si des parties de son corps sont cassées, ce Pokémon les régénère."}, {"g": "Soleil", "t": "Ce Pokémon vit en grand nombre au fond de la mer. À la nuit tombée, son cœur émet une étrange lumière rouge."}, {"g": "Lune", "t": "Même s’il se fait manger des bras par un Luminéon, il peut les régénérer tant que son cœur rouge est intact, aussi ne s’en fait-il pas."}, {"g": "Ultra-Soleil", "t": "Si l’on en croit une légende populaire, il serait né d’une pluie de poussière d’étoiles tombée dans la mer."}, {"g": "Ultra-Lune", "t": "Étant capable de se régénérer en une demi- journée seulement, il ne craint aucune blessure."}, {"g": "Let's Go Pikachu", "t": "Même découpé en mille morceaux, il peut régénérer les parties de son corps tant que sa partie centrale reste indemne."}, {"g": "Épée", "t": "Lorsqu’on se rend en bord de mer à la fin de l’été, on peut voir des groupes de Stari clignoter à un rythme régulier."}, {"g": "Bouclier", "t": "Il ne se soucie guère des Pokémon poissons qui viennent le grignoter, car même si son corps est déchiqueté, il se régénère aussitôt."}],
  121: [{"g": "Noir", "t": "Un noyau rouge trône en son centre. Il envoie des signaux radio mystérieux vers le ciel nocturne."}, {"g": "X", "t": "Son cœur brille des couleurs de l’arc-en-ciel. On raconte que c’est une pierre précieuse."}, {"g": "Rubis Oméga", "t": "Le centre de Staross, son cœur, resplendit de sept différentes couleurs. Du fait de sa brillance naturelle, on appelle ce Pokémon le « joyau des mers »."}, {"g": "Saphir Alpha", "t": "Staross nage en faisant tournoyer son corps en forme d’étoile, un peu à la manière d’une hélice de bateau. Le cœur au centre du corps de ce Pokémon brille de sept couleurs."}, {"g": "Soleil", "t": "Son cœur lumineux envoie et reçoit des signaux mystérieux. Ils donnent la migraine à quiconque s’en approche."}, {"g": "Lune", "t": "La forme abstraite de son corps ne ressemble à rien de connu. On raconte dans les campagnes qu’il s’agit d’un envahisseur venu de l’espace."}, {"g": "Ultra-Soleil", "t": "On appelle son cœur lumineux « le joyau de la mer ». Les bijoux fabriqués à partir de celui-ci se vendent à prix d’or et en secret."}, {"g": "Ultra-Lune", "t": "Ce Pokémon fait tourner son corps géométrique pour se déplacer dans l’eau. Il semblerait qu’il émette continuellement des ondes mystérieuses."}, {"g": "Let's Go Pikachu", "t": "On dit que si le centre de son corps, appelé le cœur, brille de sept couleurs, c’est parce qu’il est en train de communiquer."}, {"g": "Épée", "t": "S’il déchaîne son pouvoir psychique puissant, son organe appelé « cœur » se met à briller de sept couleurs."}, {"g": "Bouclier", "t": "Il aspire du plancton quand il nage dans la mer en faisant tourner son corps à grande vitesse."}],
  122: [{"g": "Noir", "t": "En modifiant les molécules de l’air du bout de ses doigts, il parvient à créer un mur invisible devant lui."}, {"g": "X", "t": "Les murs invisibles qu’il matérialise du bout des doigts repoussent les attaques les plus puissantes."}, {"g": "Y", "t": "Il adore imiter les gens. On le dit capable de créer de véritables murs juste en les mimant."}, {"g": "Rubis Oméga", "t": "M. Mime est un pantomime hors pair. Ses gestes et ses mouvements parviennent à faire croire que quelque chose d’invisible existe réellement. Lorsqu’on y croit, ces choses deviennent palpables."}, {"g": "Ultra-Soleil", "t": "Il est tellement doué pour l’art du mime qu’il est capable de faire apparaître un vrai mur sous le regard médusé de son public."}, {"g": "Ultra-Lune", "t": "Grâce à ses talents de mime, il est capable de faire apparaître de vrais murs. Applaudissez-le, au risque de recevoir une ou deux Torgnoles !"}, {"g": "Let's Go Pikachu", "t": "Ce Pokémon très doué pour le mime s’entraîne sans cesse. Il arrive à faire croire que quelque chose d’inexistant est réel."}, {"g": "Épée", "t": "De nombreux savants pensent que ses mains se sont développées pour faire de la pantomime."}, {"g": "Bouclier", "t": "Son talent pour le mime est indéniable. Il émet des ondes du bout des doigts pour créer un mur qui le protège de nombreuses attaques."}],
  123: [{"g": "Noir", "t": "À force de trancher des objets solides, les faux de ses bras sont très aiguisées."}, {"g": "X", "t": "Il déchiquette ses proies à l’aide de ses bras tranchants comme des faux. Il n’utilise ses ailes pour voler que très rarement."}, {"g": "Y", "t": "Il fauche les herbes avec ses lames acérées. Il bouge si vite qu’on ne peut le voir à l’œil nu."}, {"g": "Rubis Oméga", "t": "Insécateur est incroyablement rapide. Sa vitesse fulgurante améliore l’efficacité des deux lames situées sur ses avant-bras. Elles sont si coupantes qu’elles peuvent trancher un énorme tronc d’arbre en un coup."}, {"g": "Soleil", "t": "Sa rapidité de ninja embrouille sa proie. Au moindre moment d’hésitation, il la coupe en deux d’un coup de tranchant."}, {"g": "Lune", "t": "Les jeunes Insécateur se rassemblent au fond des montagnes pour s’entraîner à se battre avec leurs lames et à se déplacer à toute allure."}, {"g": "Ultra-Soleil", "t": "Ses avant-bras en forme de faux ne lui servent pas uniquement à se battre : il les utilise aussi pour dépecer ses proies avant de les dévorer."}, {"g": "Ultra-Lune", "t": "Sa vitesse incroyable lui permet de trancher l’air. Il jouit d’une grande popularité à Alola, où il est surnommé « le ninja »."}, {"g": "Let's Go Pikachu", "t": "Bondissant hors de l’herbe comme un ninja, il lacère sa proie de ses griffes acérées."}, {"g": "Épée", "t": "Ses faux deviennent plus aiguisées à mesure qu’il se bat. Il peut trancher un grand arbre d’un seul coup."}, {"g": "Bouclier", "t": "Si l’on voit un grand nombre d’arbres abattus au même endroit dans une forêt, cela signifie que l’on se trouve sur le territoire d’un Insécateur."}],
  124: [{"g": "Noir", "t": "Son cri ressemble à des paroles humaines. Mais nul n’est jamais parvenu à les comprendre."}, {"g": "X", "t": "Il ondule ses hanches en marchant et entraîne les gens dans des danses frénétiques."}, {"g": "Y", "t": "Il communique en utilisant un langage qui semble être humain. Des recherches sont en cours pour déterminer ce qu’il dit."}, {"g": "Rubis Oméga", "t": "Lippoutou marche en rythme, ondule de tout son corps et se déhanche comme s’il dansait. Ses mouvements sont si communicatifs que les gens qui le voient sont soudain pris d’une terrible envie de bouger les hanches, sans réfléchir."}, {"g": "Ultra-Soleil", "t": "Les Lippoutou se déhanchent sur un tempo très particulier, et ceux d’Alola sont particulièrement réputés pour leur admirable sens du rythme."}, {"g": "Ultra-Lune", "t": "Ses étranges cris s’apparentent à des mots. Certains musiciens lui composent des chansons pour qu’il les interprète."}, {"g": "Let's Go Pikachu", "t": "Ce Pokémon bouge en rythme comme s’il dansait. Il ondule même du popotin quand il marche."}, {"g": "Épée", "t": "Dans une certaine zone de Galar, Lippoutou était craint et vénéré par la population qui l’avait surnommé la « reine des glaces »."}, {"g": "Bouclier", "t": "Les Lippoutou vivant à Galar sont souvent dotés d’une belle voix cristalline, ce qui leur vaut d’attirer des fans."}],
  125: [{"g": "Noir", "t": "Il fait tournoyer ses bras pour donner de la force à ses coups. Profitez-en pour filer!"}, {"g": "X", "t": "Des ondes électriques parcourent la surface de son corps. Il brille d’un éclat bleuté dans le noir."}, {"g": "Y", "t": "Il adore se nourrir d’électricité. Il apparaît occasionnellement près des grandes centrales électriques."}, {"g": "Rubis Oméga", "t": "Lorsqu’une tempête approche, des groupes entiers de ce Pokémon se battent pour grimper sur les hauteurs, où la foudre a le plus de chance de tomber. Certaines villes se servent d’Élektek en guise de paratonnerres."}, {"g": "Soleil", "t": "La moitié des coupures de courant soudaines est due à des groupes d’Élektek rassemblés dans une centrale électrique pour se nourrir."}, {"g": "Lune", "t": "L’électricité qui se dégage de son corps est largement supérieure à celle qu’il ingère pour se nourrir."}, {"g": "Ultra-Soleil", "t": "Son corps regorge d’électricité. Il la concentre dans ses bras en faisant des moulinets, avant de décocher un coup d’une violence fulgurante."}, {"g": "Ultra-Lune", "t": "On l’accuse d’être à l’origine des coupures de courant, mais c’est souvent une excuse pour couvrir les bévues du personnel des centrales."}, {"g": "Let's Go Pikachu", "t": "Il provoque de grosses pannes de courant en se nourrissant de l’électricité des centrales."}, {"g": "Épée", "t": "De nombreuses centrales électriques gardent des Pokémon Sol à proximité afin d’empêcher les Élektek de leur voler de l’électricité."}, {"g": "Bouclier", "t": "Quand un orage approche, ils se réunissent tous autour d’un grand arbre et attendent patiemment que la foudre s’abatte."}],
  126: [{"g": "Noir", "t": "Quand il respire profondément, des vagues de chaleur émanent de son corps et le rendent difficile à voir."}, {"g": "X", "t": "On trouve ce Pokémon près des bouches de volcans. Son corps incandescent atteint 1 200 °C."}, {"g": "Y", "t": "Il est né au milieu d’un volcan. Son corps est couvert de flammes qui flambent comme un soleil."}, {"g": "Rubis Oméga", "t": "Lorsqu’il se bat, Magmar fait jaillir des flammes de son corps pour intimider son adversaire. Les explosions enflammées de ce Pokémon déclenchent des vagues de chaleur qui embrasent la végétation environnante."}, {"g": "Soleil", "t": "Quand il est fatigué, il se jette dans un volcan pour se soigner dans le magma. Son corps brûle à 1 200 °C."}, {"g": "Lune", "t": "Quand il s’énerve, une flamme ardente l’enveloppe tout entier. Il ne se calme que quand son adversaire est réduit en cendres."}, {"g": "Ultra-Soleil", "t": "Son corps est tellement ardent que même son souffle brûle. Lorsqu’il éternue, des flammes s’échappent de son bec."}, {"g": "Ultra-Lune", "t": "Plus il fait chaud, mieux il se porte. On dit d’ailleurs que le Magmar d’Alola est plus robuste que ses cousins habitant d’autres contrées."}, {"g": "Let's Go Pikachu", "t": "Né dans le cratère d’un volcan, son corps est recouvert de flammes. Il ressemble ainsi à une boule de feu."}, {"g": "Épée", "t": "Il achève ses proies avec ses flammes, mais il lui arrive de les calciner accidentellement, à son plus grand regret."}, {"g": "Bouclier", "t": "Tout son corps est en combustion permanente. Il est craint, car on dit qu’il cause des incendies."}],
  127: [{"g": "Noir", "t": "Il serre les proies dans ses pinces pour les trancher en deux. S’il n’y arrive pas, il les jette au loin."}, {"g": "Y", "t": "Il attaque sauvagement avec ses cornes. En hiver, il se cache au plus profond des forêts."}, {"g": "Rubis Oméga", "t": "Scarabrute est incroyablement fort. Il peut attraper un ennemi qui pèse deux fois son poids dans ses mandibules et le soulever sans le moindre problème. Lorsqu’il fait froid, les mouvements de ce Pokémon sont un peu ralentis."}, {"g": "Saphir Alpha", "t": "Scarabrute est doté de cornes imposantes. Des pointes jaillissent de la surface de ses cornes. Ces pointes s’enfoncent profondément dans le corps de l’ennemi, l’empêchant ainsi de s’échapper."}, {"g": "Soleil", "t": "Il attrape ses adversaires entre ses cornes et les tranche en deux d’un seul coup. Malgré sa force, il a une faiblesse : le froid."}, {"g": "Lune", "t": "Il peut abattre un grand arbre d’un coup de corne. À Alola, son plus grand rival est Lucanon."}, {"g": "Ultra-Soleil", "t": "Des luttes territoriales l’opposent aux Lucanon. À Alola, il semble bien s’entendre avec Scarhino."}, {"g": "Ultra-Lune", "t": "Ce Pokémon a beau être robuste, il supporte mal le froid. La nuit, il s’enfouit donc sous un tas de feuilles pour dormir au chaud."}, {"g": "Let's Go Pikachu", "t": "Il enserre sa proie de sa puissante pince. Il ne peut pas se déplacer dans le froid, donc on le trouve dans les milieux chauds."}, {"g": "Épée", "t": "Ses cornes déterminent son rang au sein du groupe. Plus elles sont imposantes, plus les membres du sexe opposé l’apprécient."}, {"g": "Bouclier", "t": "Une fois sa proie enserrée entre ses cornes, deux choix s’offrent à lui : la couper en deux ou la projeter au loin de toutes ses forces."}],
  128: [{"g": "Noir", "t": "Après avoir choisi sa cible, il fonce dessus tête baissée. Il est réputé pour sa nature violente."}, {"g": "X", "t": "Après s’être fouetté avec ses trois queues pour augmenter son agressivité, il charge."}, {"g": "Y", "t": "Juste avant d’utiliser Charge, ce Pokémon agite frénétiquement ses trois grandes queues."}, {"g": "Rubis Oméga", "t": "Ce Pokémon n’est pas satisfait s’il ne détruit pas tout sur son passage. Lorsque Tauros ne trouve pas d’adversaire, il se rue sur de gros arbres et les déracine pour passer ses nerfs."}, {"g": "Soleil", "t": "Beaucoup de sociétés à travers le monde ont appris à monter Tauros au cours de leur histoire. Les premières à l’avoir fait habitaient à Alola."}, {"g": "Lune", "t": "Il s’agit normalement d’un Pokémon très agressif, mais les Tauros natifs d’Alola sont d’une nature un peu plus paisible."}, {"g": "Ultra-Soleil", "t": "Les Tauros vivent en troupeaux menés par ceux dont les cornes sont les plus grosses, les plus longues et les plus abimées."}, {"g": "Ultra-Lune", "t": "La douceur du climat local explique sans doute pourquoi les Tauros d’Alola sont plus paisibles que leurs congénères d’outre-mer."}, {"g": "Let's Go Pikachu", "t": "Ce Pokémon brutal est très endurant. Rien n’arrête sa charge tant qu’il n’a pas pulvérisé sa cible."}, {"g": "Épée", "t": "Il faut prendre garde quand un Tauros fouette son corps avec ses queues. Cela signifie qu’il s’apprête à charger à une vitesse démentielle."}, {"g": "Bouclier", "t": "Les Tauros vivant à Galar ont un tempérament violent et ne tolèrent pas que les êtres humains montent sur leur dos."}],
  129: [{"g": "Noir", "t": "Un vénérable Magicarpe peut franchir une montagne en utilisant Trempette. Mais c’est tout..."}, {"g": "X", "t": "Magicarpe manque totalement de vitesse et de force. C’est le Pokémon le plus pathétique sur terre."}, {"g": "Y", "t": "La puissance de cette créature a beaucoup régressé au fil des siècles."}, {"g": "Rubis Oméga", "t": "Magicarpe est un Pokémon ridicule qui ne sait faire que des ronds dans l’eau ou se laisser porter par les courants. Son comportement a donné envie aux savants d’étudier son cas."}, {"g": "Saphir Alpha", "t": "Magicarpe est virtuellement inutile en combat. Il se contente de faire des ronds dans l’eau. On le considère plutôt faible. Pourtant, ce Pokémon est très robuste et peut survivre dans n’importe quel environnement, même très pollué."}, {"g": "Soleil", "t": "Ce Pokémon est faible et ne sait pas faire grand-chose à part se multiplier à toute allure. On en trouve à ne plus savoir qu’en faire."}, {"g": "Lune", "t": "Il bondit hors de l’eau sans faire attention et se fait attraper par toutes sortes de Pokémon. Beaucoup d’espèces dépendent de cette manne."}, {"g": "Ultra-Soleil", "t": "Il y a fort, fort longtemps, il était relativement puissant. Il est toutefois devenu de plus en plus nul au fil du temps."}, {"g": "Ultra-Lune", "t": "Sa survie ne dépendant pas de la salubrité des eaux dans lesquelles il nage, on rencontre ce Pokémon aux quatre coins du monde."}, {"g": "Let's Go Pikachu", "t": "Célèbre pour son inutilité, on en trouve beaucoup dans les océans, les étangs, les rivières et même les flaques d’eau."}, {"g": "Épée", "t": "Il manque totalement de vitesse et de force. C’est le Pokémon le plus pathétique au monde."}, {"g": "Bouclier", "t": "Ce Pokémon est si faible que, dans les eaux à forts courants, il se contente de se laisser porter lamentablement."}],
  130: [{"g": "Noir", "t": "Quand il se laisse emporter par la rage, il ne se calme qu’après avoir détruit tout ce qui l’entoure."}, {"g": "X", "t": "La littérature ancienne fait état d’un Léviator qui aurait rasé un village sous le coup de la colère."}, {"g": "Y", "t": "Gigantesque et maléfique, il est capable de raser une ville entière dans un accès de rage."}, {"g": "Rubis Oméga", "t": "Quand Magicarpe évolue et devient Léviator, la structure de ses cellules cérébrales est modifiée. On pense que l’extrême violence de ce Pokémon découle de cette modification."}, {"g": "Saphir Alpha", "t": "Lorsque Léviator commence à s’énerver, sa nature violente ne se calme qu’une fois qu’il a tout réduit en cendres. La fureur de ce Pokémon peut durer pendant un mois."}, {"g": "Soleil", "t": "Il existe une légende à propos d’une ville qui a mis un Léviator en colère et qui a été réduite en cendres en une nuit."}, {"g": "Lune", "t": "Certaines personnes croient que les endroits où un Léviator apparaît sont destinés à connaître la destruction."}, {"g": "Ultra-Soleil", "t": "Avec son Ultralaser, il anéantit d’immenses étendues. Dans ces régions dévastées, il est surnommé « le dieu de la destruction »."}, {"g": "Ultra-Lune", "t": "L’énergie libérée au moment de son évolution a fortement stimulé ses cellules cérébrales et causé son tempérament pour le moins violent."}, {"g": "Let's Go Pikachu", "t": "Brutal et dangereux, il est connu pour avoir rasé des villes entières par le passé."}, {"g": "Épée", "t": "Il est d’une nature très agressive. Les lasers qu’il tire de sa bouche sont capables de désintégrer n’importe quelle cible."}, {"g": "Bouclier", "t": "Quand il se laisse emporter par la rage, même la plus violente des tempêtes ne peut l’empêcher de détruire tout ce qui l’entoure."}],
  131: [{"g": "Noir", "t": "Il aime naviguer en portant des humains et des Pokémon sur son dos. Il comprend le langage humain."}, {"g": "X", "t": "Ils sont d’une nature gentille. Comme ils se défendent rarement, ils sont en voie d’extinction."}, {"g": "Y", "t": "Son intelligence lui permet de comprendre le langage des humains. Il adore promener les gens sur son dos."}, {"g": "Rubis Oméga", "t": "Les Lokhlass sont en voie d’extinction. Le soir, on entend ce Pokémon chantonner une complainte mélancolique, espérant retrouver ses rares congénères."}, {"g": "Soleil", "t": "Ce Pokémon est très intelligent et comprend le langage humain. Quand il est de bonne humeur, il chante avec une voix magnifique."}, {"g": "Lune", "t": "Il était en voie d’extinction à cause de la pêche illégale, mais après de stricts programmes de protection, il y en a maintenant trop."}, {"g": "Ultra-Soleil", "t": "Il prend plaisir à transporter des humains sur son dos quand il nage. Les habitants d’Alola adorent ce moyen de transport."}, {"g": "Ultra-Lune", "t": "Cette espèce protégée a tellement proliféré que les Pokémon poissons se font apparemment plus rares dans les eaux peuplées de Lokhlass."}, {"g": "Let's Go Pikachu", "t": "Ce gentil Pokémon comprend le langage humain. Il parcourt les mers en transportant des gens sur son dos."}, {"g": "Épée", "t": "C’est un Pokémon doux et intelligent. Il vogue sur la mer en émettant un chant magnifique."}, {"g": "Bouclier", "t": "Il résiste bien aux très basses températures et peut nager dans des mers glaciales. Sa peau est lisse et légèrement froide au toucher."}],
  132: [{"g": "Noir", "t": "Il a la capacité de modifier sa structure cellulaire pour prendre l’apparence de ce qu’il voit."}, {"g": "Y", "t": "Métamorph peut modifier sa structure cellulaire à sa guise pour se transformer en n’importe quelle forme vivante."}, {"g": "Rubis Oméga", "t": "Métamorph peut modifier sa structure moléculaire pour prendre d’autres formes. Lorsqu’il essaie de se transformer de mémoire, il lui arrive de se tromper sur certains détails."}, {"g": "Soleil", "t": "Il peut modifier sa structure moléculaire pour prendre l’apparence de son adversaire. Le degré de ressemblance dépend de chaque individu."}, {"g": "Lune", "t": "Grâce à son don de transformation, ce Pokémon peut devenir l’ami de tous les êtres vivants, sauf des autres Métamorph, qu’il déteste."}, {"g": "Ultra-Soleil", "t": "Il peut prendre l’apparence de n’importe quoi, mais chaque Métamorph a son propre domaine de prédilection et ses propres faiblesses."}, {"g": "Ultra-Lune", "t": "Il prend la forme de ce qu’il voit. Lorsqu’il n’a pas de modèle sous les yeux, il doit se fier à sa mémoire et le résultat laisse parfois à désirer."}, {"g": "Let's Go Pikachu", "t": "Quand il repère un ennemi, il adapte son corps pour en faire une copie presque parfaite de celui de son adversaire."}, {"g": "Épée", "t": "Il modifie sa structure cellulaire pour copier l’apparence de ce qu’il voit, mais au repos, il reprend sa forme normale."}, {"g": "Bouclier", "t": "Quand il rencontre l’un de ses semblables, il s’agite avec plus de vivacité que d’habitude pour adopter exactement la même forme que lui."}],
  133: [{"g": "Noir", "t": "Son ADN particulier lui permet de s’adapter très rapidement à son environnement."}, {"g": "X", "t": "Un Pokémon rare qui s’adapte aux environnements hostiles en variant ses formes évolutives."}, {"g": "Y", "t": "L’ADN de ce Pokémon très particulier recèle de nombreuses possibilités d’évolution."}, {"g": "Rubis Oméga", "t": "Évoli a une structure génétique instable qui se transforme en fonction de l’environnement dans lequel il vit. Ce Pokémon peut évoluer grâce aux radiations de diverses pierres."}, {"g": "Soleil", "t": "Son ADN est instable et possède de nombreuses possibilités d’évolution."}, {"g": "Lune", "t": "D’après les dernières recherches, il semble que ce Pokémon soit capable d’évoluer en huit espèces différentes."}, {"g": "Ultra-Soleil", "t": "À ce jour, nul ne sait pourquoi Évoli est le seul Pokémon dont l’ADN est instable."}, {"g": "Ultra-Lune", "t": "L’ADN d’Évoli est sujet aux influences de son environnement. Sa tête finit même par ressembler à celle de son Dresseur."}, {"g": "Let's Go Pikachu", "t": "Il peut évoluer de diverses façons. Son ADN est la clé pour percer le secret de l’évolution."}, {"g": "Épée", "t": "Il a la capacité de changer la composition de son corps pour s’adapter à son environnement."}],
  134: [{"g": "Noir", "t": "Sa composition moléculaire est proche de celle de l’eau, ce qui lui permet de se liquéfier."}, {"g": "X", "t": "Il préfère les belles plages. Il peut se dissoudre à volonté grâce à ses cellules proches de l’eau."}, {"g": "Y", "t": "Il a évolué pour s’adapter au milieu aquatique. Il peut se fondre et disparaître dans l’élément liquide."}, {"g": "Rubis Oméga", "t": "Aquali a subi une mutation spontanée. Des nageoires et des branchies sont apparues sur son corps, ce qui lui permet de vivre dans les fonds marins. Ce Pokémon peut contrôler l’eau à volonté."}, {"g": "Soleil", "t": "La structure de ses cellules ressemble à celle des molécules d’eau. Il vit sur les rives, et il arrive qu’il soit pris pour une sirène."}, {"g": "Lune", "t": "Ce Pokémon plonge dans l’eau et y reste caché jusqu’à ce qu’un Pokémon poisson passe à sa portée."}, {"g": "Ultra-Soleil", "t": "On le trouve principalement dans les sources limpides. Lorsqu’un ennemi est sur le point de l’attaquer, il plonge se réfugier dans l’eau."}, {"g": "Ultra-Lune", "t": "Il perçoit l’humidité ambiante grâce aux ailerons de sa tête. S’ils frémissent, c’est qu’il pleuvra d’ici quelques heures."}, {"g": "Let's Go Pikachu", "t": "Sa structure moléculaire est semblable à celle de l’eau. Il est invisible en milieu aquatique."}, {"g": "Épée", "t": "Quand ses nageoires se mettent à vibrer, c’est le signe qu’il va pleuvoir dans les heures qui suivent."}, {"g": "Bouclier", "t": "Sa structure cellulaire est similaire à la composition moléculaire de l’eau. Une fois dans cet élément, il devient indétectable à l’œil nu."}],
  135: [{"g": "Noir", "t": "Face au danger, il fait appel à l’électricité pour dresser ses poils et lancer des décharges."}, {"g": "X", "t": "Chaque poil sur son corps se dresse quand il se charge en électricité."}, {"g": "Y", "t": "Il se charge d’électricité statique pour envoyer des décharges de 10 000 V."}, {"g": "Rubis Oméga", "t": "Les cellules de Voltali génèrent un courant de faible intensité. Ce pouvoir est amplifié par l’électricité statique de ses poils, ce qui lui permet d’envoyer des éclairs. Sa fourrure hérissée est faite d’aiguilles chargées d’électricité."}, {"g": "Soleil", "t": "Il peut projeter des décharges de 10 000 volts. Il est très nerveux, ce qui le rend difficile à apprivoiser."}, {"g": "Lune", "t": "Quand son pelage se hérisse, c’est signe qu’il va projeter de l’électricité. Attention, car il arrive que la foudre tombe près de lui."}, {"g": "Ultra-Soleil", "t": "Un organe situé à l’intérieur de ses poumons produit de l’électricité. On entend une sorte de crépitement chaque fois qu’il expire."}, {"g": "Ultra-Lune", "t": "Il projette ses poils hérissés comme si c’étaient des aiguilles, avant d’achever ses ennemis ainsi affaiblis avec des décharges de 10 000 volts."}, {"g": "Let's Go Pikachu", "t": "Un Pokémon très sensible et lunatique. Il se charge en électricité chaque fois que son humeur change."}, {"g": "Épée", "t": "S’il est irrité ou surpris, toute la fourrure de son corps se dresse comme des aiguilles pour percer ses ennemis."}, {"g": "Bouclier", "t": "Il se charge d’ions négatifs contenus dans l’air pour envoyer des décharges d’environ 10 000 volts."}],
  136: [{"g": "Noir", "t": "L’air qu’il inspire est chauffé par la glande enflammée de son corps, atteignant les 1 700 °C."}, {"g": "X", "t": "Son corps contient une glande enflammée. Sa température monte à 900 °C avant le combat."}, {"g": "Y", "t": "Pyroli a une poche de feu à l’intérieur de son corps. Après une bonne inspiration, il est capable de recracher des flammes à 1 700 °C."}, {"g": "Rubis Oméga", "t": "La fourrure soyeuse de Pyroli a une fonction anatomique. Elle rejette la chaleur dans l’air pour que son corps ne surchauffe pas. La température du corps de ce Pokémon peut atteindre 900 °C."}, {"g": "Soleil", "t": "Après avoir trouvé une proie et quelques Baies, il crache du feu jusqu’à ce qu’elles soient cuites à point avant de les gober."}, {"g": "Lune", "t": "Sa température moyenne est entre 700 et 800 °C. La poche de feu à l’intérieur de son corps peut atteindre 1 700 °C."}, {"g": "Ultra-Soleil", "t": "Si vous le voyez inspirer profondément, sauvez-vous, car c’est le signe qu’il va attaquer en soufflant une flamme à 1 700 °C !"}, {"g": "Ultra-Lune", "t": "Lorsqu’il est agité, sa poche de feu interne s’enflamme, et sa température corporelle peut alors monter jusqu’à 900 °C."}, {"g": "Let's Go Pikachu", "t": "La poche de feu à l’intérieur de son corps transforme l’air qu’il inspire en flammes à 1 700 ºC qu’il recrache par la bouche."}, {"g": "Épée", "t": "Après avoir emmagasiné suffisamment de chaleur, sa température corporelle peut monter jusqu’à 900 °C."}, {"g": "Bouclier", "t": "Il emmagasine de l’air dans sa poche de flammes et le chauffe à une température de 1 700 °C."}],
  137: [{"g": "Noir", "t": "Ce Pokémon créé par des scientifiques peut arpenter librement le cyberespace."}, {"g": "X", "t": "Un Pokémon créé par l’homme après de longues recherches. Il ne connaît que peu de mouvements."}, {"g": "Y", "t": "Ce Pokémon est fait de programmes et d’algorithmes. Il peut survivre en milieu virtuel."}, {"g": "Rubis Oméga", "t": "Porygon est capable de se décompiler et de retourner à l’état de programme informatique pour entrer dans le cyberespace. Ce Pokémon est protégé contre le piratage, il est donc impossible de le copier."}, {"g": "Soleil", "t": "Un Pokémon artificiel créé il y a vingt ans en utilisant des méthodes à la pointe de la technologie de l’époque."}, {"g": "Lune", "t": "Il peut transformer son corps en données numériques pour pénétrer dans le cyberespace."}, {"g": "Ultra-Soleil", "t": "Un Pokémon artificiel créé il y a vingt ans, et qui est donc complètement dépassé sur bien des points."}, {"g": "Ultra-Lune", "t": "Il a été conçu il y a vingt ans par des chercheurs qui rêvaient de conquérir l’espace. Ce rêve n’est toujours pas devenu réalité."}, {"g": "Let's Go Pikachu", "t": "Ce Pokémon est censé être le seul à pouvoir voler jusque dans l’espace, mais pour l’instant, aucun Porygon n’y est jamais parvenu."}, {"g": "Épée", "t": "C’est le premier Pokémon au monde à avoir été créé à partir de programmes informatiques, grâce à une technologie de pointe."}, {"g": "Bouclier", "t": "Ces dernières années, il s’est rendu très utile dans le cyberespace, qu’il arpente pour s’assurer qu’il n’y a aucune donnée suspecte."}],
  138: [{"g": "Noir", "t": "Un Pokémon ramené à la vie par la science à partir d’un fossile. Il peuplait autrefois les mers."}, {"g": "X", "t": "Un Pokémon préhistorique qui vivait dans les profondeurs marines. Il se déplace en agitant ses 10 tentacules."}, {"g": "Y", "t": "Recréé à partir d’un fossile, il utilise l’air dans sa coquille pour s’enfoncer dans l’eau ou faire surface."}, {"g": "Rubis Oméga", "t": "Amonita est l’un des Pokémon disparus depuis longtemps et qui furent ressuscités à partir de fossiles. Lorsqu’il est attaqué par un ennemi, il se rétracte dans sa coquille."}, {"g": "Ultra-Soleil", "t": "Un Pokémon qui vivait dans les mers antiques. Des fossiles présentant des traces de morsures indiquent qu’il était la proie d’Aéroptéryx."}, {"g": "Ultra-Lune", "t": "Un Pokémon recréé à partir d’un fossile antique. Ces Nautiles se trouvent en des endroits jadis recouverts par les flots."}, {"g": "Let's Go Pikachu", "t": "Un ancien Pokémon reconstitué à partir d’un fossile. Il nageait dans les mers antiques grâce à ses dix tentacules."}, {"g": "Épée", "t": "Ce Pokémon commence à poser problème, car certains spécimens se sont enfuis ou ont été relâchés après avoir été ressuscités."}, {"g": "Bouclier", "t": "Un Pokémon préhistorique aujourd’hui disparu. Il semble flotter lorsqu’il nage en brassant l’eau avec ses dix tentacules."}],
  139: [{"g": "Noir", "t": "On pense que ce Pokémon a disparu parce que sa coquille en spirale était devenue trop grosse."}, {"g": "X", "t": "Ses tentacules sont développés comme s’il s’agissait de bras ou de jambes. Dès qu’il attrape une proie, il la mord."}, {"g": "Y", "t": "Une fois enroulé autour de sa proie, il ne la laisse pas repartir et la dévore avec ses crocs."}, {"g": "Rubis Oméga", "t": "Amonistar utilise ses tentacules pour capturer ses proies. On pense que l’espèce s’est éteinte parce que sa coquille était devenue trop grande et trop lourde, ce qui rendait ses mouvements lents et pesants."}, {"g": "Ultra-Soleil", "t": "On suppose que ce Pokémon antique a disparu en raison de la lourdeur de sa coquille. Il est l’ancêtre présumé des Octillery."}, {"g": "Ultra-Lune", "t": "Il immobilise ses proies avec ses tentacules et leur inflige le coup de grâce à l’aide de ses crocs aiguisés."}, {"g": "Let's Go Pikachu", "t": "Sa bouche est formée de crocs aiguisés. Il aurait disparu car sa coquille, trop grosse, l’empêchait de se déplacer facilement."}, {"g": "Épée", "t": "Il se serait éteint à cause de la taille et du poids importants de sa coquille, qui le ralentissait quand il chassait ses proies."}, {"g": "Bouclier", "t": "Ses crocs sont capables de broyer la roche, mais il ne peut s’attaquer qu’aux proies à portée de ses tentacules."}],
  140: [{"g": "Noir", "t": "On pense qu’il peuplait les plages il y a 300 millions d’années. Il est protégé par une coquille robuste."}, {"g": "Y", "t": "Ce Pokémon a été reconstitué à partir du fossile d’une ancienne créature. Il se protège à l’aide de sa carapace."}, {"g": "Rubis Oméga", "t": "Kabuto est un Pokémon ressuscité à partir d’un fossile. Cependant, on a découvert des spécimens vivants. Ce Pokémon n’a pas changé depuis 300 millions d’années."}, {"g": "Ultra-Soleil", "t": "Un Pokémon qui prospérait il y a 300 millions d’années. On raconte que de rares survivants subsistent dans une certaine région."}, {"g": "Ultra-Lune", "t": "Ce Pokémon, doté d’une solide carapace protectrice, a totalement disparu de la surface de la terre, sauf dans une région particulière."}, {"g": "Let's Go Pikachu", "t": "Un Pokémon reconstitué à partir d’un fossile. Il utilise les yeux situés sur son dos pour regarder alentour quand il se cache au fond de l’eau."}, {"g": "Épée", "t": "Ce Pokémon au bord de l’extinction mue tous les trois jours et renforce ainsi davantage sa carapace."}, {"g": "Bouclier", "t": "On raconte qu’ils se seraient éteints, mais apparemment, on peut souvent en croiser dans une zone particulière."}],
  141: [{"g": "Noir", "t": "On pense que ce Pokémon est venu sur la terre ferme pour suivre l’évolution de ses proies."}, {"g": "X", "t": "Dans l’eau, il se recroqueville sur ses jambes et il agite sa coquille pour nager à très grande vitesse."}, {"g": "Y", "t": "C’est un très bon nageur. Il lacère sa proie de ses longues griffes et en absorbe les fluides corporels."}, {"g": "Rubis Oméga", "t": "Jadis, Kabutops plongeait dans les profondeurs pour trouver ses proies. Apparemment, ce Pokémon vivant sur terre est l’évolution d’une créature marine, comme le prouvent les changements dans ses branchies."}, {"g": "Ultra-Soleil", "t": "Son corps avait commencé à évoluer pour s’adapter à la vie sur la terre ferme, mais il était déjà trop tard, et son espèce s’est éteinte."}, {"g": "Ultra-Lune", "t": "Capable d’atteindre une vitesse de 29 nœuds, il se rue sur ses proies pour les transpercer de ses lames."}, {"g": "Let's Go Pikachu", "t": "Ce Pokémon au corps fin est très bon nageur. Il lacère sa proie de ses longues griffes pour en absorber les fluides corporels."}, {"g": "Épée", "t": "Il lacère sa proie pour boire ses fluides corporels, puis jette son corps en pâture à d’autres Pokémon."}, {"g": "Bouclier", "t": "Nul ne sait pourquoi il s’est éteint. Ce Pokémon préhistorique féroce vivait dans les mers chaudes."}],
  142: [{"g": "Noir", "t": "Un Pokémon qui arpentait le ciel au temps des dinosaures. Ses crocs sont pareils à des scies."}, {"g": "X", "t": "Ce Pokémon a été reconstitué à partir d’une cellule de dinosaure trouvée dans un morceau d’ambre. Il vole très haut en poussant des cris très aigus."}, {"g": "Y", "t": "Ce terrible Pokémon a dominé les cieux d’une autre époque, terrorisant ses ennemis."}, {"g": "Rubis Oméga", "t": "Ptéra est un Pokémon de l’ère des dinosaures. Il fut ressuscité à partir de cellules extraites d’un morceau d’ambre. On pense qu’il était le roi des cieux à l’époque préhistorique."}, {"g": "Soleil", "t": "Un Pokémon de l’époque préhistorique. Il mangeait ses proies en les déchiquetant avec ses crocs acérés comme des scies."}, {"g": "Lune", "t": "Le roi des airs à l’époque préhistorique. La théorie la plus crédible est qu’il aurait été annihilé par la chute d’une énorme météorite."}, {"g": "Ultra-Soleil", "t": "Recréé à partir d’ADN contenu dans de l’ambre, il s’est avéré plus féroce que prévu et a causé la mort de plusieurs personnes."}, {"g": "Ultra-Lune", "t": "L’air suffisant qu’il affichait lorsqu’il volait dans les cieux s’effaçait vite une fois sur terre, où il était faible et peinait à se mouvoir rapidement."}, {"g": "Let's Go Pikachu", "t": "Un Pokémon féroce disparu il y a longtemps. Il a été reconstitué à partir d’ADN fossilisé dans de l’ambre."}, {"g": "Épée", "t": "On raconte qu’aujourd’hui encore, il est impossible de restaurer à la perfection ce Pokémon féroce de l’ère préhistorique."}, {"g": "Bouclier", "t": "Sa dentition semblable à une scie peut même broyer la peau des Pokémon Acier."}],
  143: [{"g": "Noir", "t": "Une fois le ventre plein, il est trop amorphe pour lever le petit doigt. Sautez sur son ventre!"}, {"g": "X", "t": "Ronflex n’est pas satisfait tant qu’il n’a pas avalé ses 400 kg de nourriture quotidienne. Dès qu’il a fini de manger, il commence une sieste pour digérer."}, {"g": "Y", "t": "Son estomac peut digérer n’importe quel type de nourriture, même quand elle est moisie ou pourrie."}, {"g": "Rubis Oméga", "t": "Les journées de Ronflex se résument aux repas et aux siestes. C’est un Pokémon tellement gentil que les enfants n’hésitent pas à jouer sur son énorme ventre."}, {"g": "Soleil", "t": "On dit que son estomac n’a pas d’égal. Même les toxines de Grotadmorv ne sont rien de plus qu’un assaisonnement épicé pour lui."}, {"g": "Lune", "t": "Il mange 400 kg de nourriture par jour. Il arrive que sa sieste commence pendant qu’il mange, mais il continue à manger même endormi."}, {"g": "Ultra-Soleil", "t": "Il ne fait pas grand-chose à part manger et dormir, mais gare à lui quand il décide de passer à l’action !"}, {"g": "Ultra-Lune", "t": "La seule chose qui l’intéresse, c’est manger. Il ne se réveille même pas si quelqu’un grimpe sur son ventre pendant qu’il fait une sieste."}, {"g": "Let's Go Pikachu", "t": "Il peut tout manger, même de la nourriture avariée. Il n’a jamais mal au ventre."}, {"g": "Épée", "t": "Ronflex n’est pas satisfait tant qu’il n’a pas avalé ses 400 kg de nourriture quotidienne. Dès qu’il a fini, il commence une sieste pour digérer."}, {"g": "Bouclier", "t": "L’estomac de ce Pokémon est si résistant qu’il peut même digérer de la nourriture avariée."}],
  144: [{"g": "Noir", "t": "Un Pokémon Oiseau légendaire. Il peut provoquer des blizzards en gelant l’humidité de l’air."}, {"g": "Y", "t": "Le légendaire oiseau des glaces. On dit qu’il apparaît aux gens perdus dans les sommets."}, {"g": "Rubis Oméga", "t": "Artikodin est un Pokémon Oiseau légendaire qui peut contrôler la glace. Le battement de ses ailes gèle l’air tout autour de lui. C’est pourquoi on dit que lorsque ce Pokémon vole, il va neiger."}, {"g": "Let's Go Pikachu", "t": "Un Pokémon oiseau légendaire. L’hiver, il glace la vapeur d’eau contenue dans l’air pour faire de la neige."}, {"g": "Épée", "t": "On raconte que ses belles plumes bleues sont faites de glace. Sa longue queue flotte au vent lorsqu’il vole au-dessus des monts enneigés."}, {"g": "Bouclier", "t": "Il possède le pouvoir de contrôler la glace. Selon les dires, il vivrait sur les sommets recouverts de neiges éternelles."}],
  145: [{"g": "Noir", "t": "Un Pokémon Oiseau légendaire dont on dit qu’il vit dans les nuages d’orage. Il contrôle la foudre."}, {"g": "X", "t": "L’oiseau légendaire de la foudre. Il surgit hors des nuages en lançant d’énormes éclairs."}, {"g": "Rubis Oméga", "t": "Électhor est un Pokémon Oiseau légendaire capable de contrôler l’électricité. Il vit généralement dans les nuages orageux. Ce Pokémon gagne en puissance lorsqu’il est frappé par la foudre."}, {"g": "Let's Go Pikachu", "t": "Ce Pokémon oiseau légendaire apparaît quand le ciel s’assombrit et que la foudre ne cesse de tomber."}, {"g": "Épée", "t": "On dit que ce Pokémon capable de contrôler la foudre installe son nid au creux des nuages d’orage noirs."}, {"g": "Bouclier", "t": "On raconte que lorsque ce Pokémon oiseau légendaire fait vibrer ses plumes, le frottement fait tomber la foudre instantanément."}],
  146: [{"g": "Noir", "t": "L’un des Pokémon Oiseaux légendaires. On dit que sa venue annonce l’arrivée du printemps."}, {"g": "X", "t": "Le légendaire oiseau du feu. Une pluie de flammes surgit à chaque battement de ses ailes."}, {"g": "Rubis Oméga", "t": "Sulfura est un Pokémon Oiseau légendaire capable de contrôler le feu. On raconte que lorsque ce Pokémon est blessé, il se baigne dans le magma en ébullition d’un volcan pour se soigner."}, {"g": "Let's Go Pikachu", "t": "Quand ce Pokémon oiseau légendaire agite ses ailes de feu, même la nuit noire s’embrase et rougeoie."}, {"g": "Épée", "t": "Il s’agit d’un des Pokémon oiseaux légendaires. Des flammes rouges d’une grande beauté étincellent lorsqu’il bat des ailes."}, {"g": "Bouclier", "t": "On raconte qu’il a sauvé des personnes perdues en montagne en illuminant les sentiers à l’aide de ses splendides ailes flamboyantes."}],
  147: [{"g": "Noir", "t": "On l’appelle “Pokémon mirage” en raison de sa rareté. On a découvert sa mue."}, {"g": "X", "t": "On l’appelle « Pokémon mirage » en raison de sa rareté. On a découvert sa mue."}, {"g": "Y", "t": "Ce Pokémon est plein de vitalité. Il mue et grandit très régulièrement."}, {"g": "Rubis Oméga", "t": "Minidraco mue constamment, renouvelant sans arrêt sa peau. En effet, l’énergie vitale de son corps augmente régulièrement et sa mue lui permet d’éviter d’atteindre des niveaux incontrôlables."}, {"g": "Soleil", "t": "Il grandit en enchaînant les mues. Les bottes faites avec la peau de ces mues sont des produits de grand luxe."}, {"g": "Lune", "t": "La première preuve de l’existence de ce Pokémon est due à un pêcheur ayant bataillé 10 heures pour le tirer hors de l’eau."}, {"g": "Ultra-Soleil", "t": "Encore faible, il se cache dans les eaux profondes et se nourrit de ce qui tombe de la surface. Il mène une existence paisible."}, {"g": "Ultra-Lune", "t": "Il grandit en muant quasiment tous les jours. Sa peau est toute douce après la mue."}, {"g": "Let's Go Pikachu", "t": "L’existence de ce Pokémon mythique n’a été confirmée que récemment par un pêcheur."}, {"g": "Épée", "t": "Ce Pokémon vit près des courants d’eau puissants, comme au pied des cascades. Il grandit en opérant une succession de mues."}, {"g": "Bouclier", "t": "On a longtemps douté de l’existence de ce Pokémon. La petite bosse sur son front est en fait sa corne en pleine croissance."}],
  148: [{"g": "Noir", "t": "La météo change brusquement quand il est entouré d’une aura. On dit qu’il peuple les mers et les lacs."}, {"g": "X", "t": "Ses orbes de cristal donnent le pouvoir de contrôler le climat."}, {"g": "Y", "t": "Un Pokémon légendaire plein de charme. Il peut contrôler les variations climatiques."}, {"g": "Rubis Oméga", "t": "Draco stocke une quantité d’énergie considérable dans son corps. On raconte qu’il peut modifier les conditions climatiques autour de lui en déchargeant l’énergie contenue dans les cristaux de son cou et de sa queue."}, {"g": "Soleil", "t": "Beaucoup pensent que les orbes cristallins de ce Pokémon ont le pouvoir de modifier le climat."}, {"g": "Lune", "t": "Il est adoré depuis l’Antiquité dans certaines communautés paysannes en tant que divinité des conditions climatiques."}, {"g": "Ultra-Soleil", "t": "On raconte que ce Pokémon a le pouvoir de modifier le climat. Les offrandes affluent donc au bord des lacs où il vit."}, {"g": "Ultra-Lune", "t": "Voir ce Pokémon serpenter dans le ciel au réveillon présage d’une bonne santé pour la nouvelle année."}, {"g": "Let's Go Pikachu", "t": "Selon des témoins, son corps est baigné d’une étrange aura lui donnant un air mystique."}, {"g": "Épée", "t": "Il vit dans les mers et les lacs aux eaux claires. Sa maîtrise de la météo lui permet de s’élever dans le ciel en se laissant porter par le vent."}, {"g": "Bouclier", "t": "Il contrôle la météo en accumulant de l’énergie dans les orbes au bout de sa queue. Sa silhouette nimbée d’une aura lui confère un air mystique."}],
  149: [{"g": "Noir", "t": "On raconte qu’il vit quelque part en mer. Il guide les équipages naufragés jusqu’à la terre ferme."}, {"g": "X", "t": "Malgré son poids et son physique imposant, Dracolosse est capable de voler. Il peut faire le tour du monde en 16 heures."}, {"g": "Rubis Oméga", "t": "Dracolosse est capable de faire le tour de la planète en seize heures à peine. C’est un Pokémon au grand cœur qui ramène à bon port les navires perdus dans les tempêtes."}, {"g": "Soleil", "t": "On raconte l’histoire d’un naufragé sauvé par ce Pokémon et emmené sur une île paradisiaque uniquement peuplée de Dracolosse."}, {"g": "Lune", "t": "Il est d’un naturel débonnaire, mais si quelque chose parvient à le mettre en colère, il ne se calmera qu’après avoir tout réduit en miettes."}, {"g": "Ultra-Soleil", "t": "Il brave les flots impétueux sans ciller. C’est pour cette raison qu’un capitaine l’ayant vu à l’œuvre l’a surnommé « l’avatar de la mer »."}, {"g": "Ultra-Lune", "t": "De nombreux témoignages racontent que ce Pokémon, de nature bienveillante, aurait sauvé des humains et des Pokémon de la noyade."}, {"g": "Let's Go Pikachu", "t": "On raconte que ce Pokémon vit quelque part dans la mer et qu’il peut voler. Rien n’est moins sûr."}, {"g": "Épée", "t": "Sa gentillesse est telle que s’il voit un Pokémon ou un être humain en train de se noyer, il n’hésite pas à lui venir en aide."}, {"g": "Bouclier", "t": "On l’appelle « l’avatar de la mer ». Nombreux sont les navires arborant une figure de proue en forme de Dracolosse."}],
  150: [{"g": "Noir", "t": "Un Pokémon conçu en réorganisant les gènes de Mew. On raconte qu’il s’agit du Pokémon le plus féroce."}, {"g": "X", "t": "Il est le fruit de nombreuses expériences génétiques horribles et malsaines."}, {"g": "Rubis Oméga", "t": "Mewtwo est un Pokémon créé par manipulation génétique. Cependant, bien que les connaissances scientifiques des humains aient réussi à créer son corps, elles n’ont pas pu doter Mewtwo d’un cœur sensible."}, {"g": "Let's Go Pikachu", "t": "Son ADN est presque le même que celui de Mew, mais sa taille et son caractère sont très différents."}],
  151: [{"g": "Noir", "t": "Nombre de scientifiques voient en lui l’ancêtre des Pokémon car il maîtrise toutes leurs capacités."}, {"g": "Y", "t": "Son ADN contient les codes génétiques de tous les Pokémon. Il peut utiliser nombre de techniques."}, {"g": "Rubis Oméga", "t": "On dit que Mew possède le code génétique de tous les autres Pokémon. Il peut se rendre invisible à sa guise, ce qui lui permet de ne pas se faire remarquer quand il s’approche des gens."}, {"g": "Let's Go Pikachu", "t": "À l’aide d’un microscope, on peut distinguer le pelage extrêmement court, fin et délicat de ce Pokémon."}],
  152: [{"g": "Noir", "t": "Il jauge la température et l’humidité grâce à la feuille sur sa tête. Il raffole des bains de soleil."}, {"g": "X", "t": "Un doux parfum émane de la feuille placée sur sa tête. Il est très gentil et aime dormir au soleil."}, {"g": "Rubis Oméga", "t": "Lorsqu’il se bat, Germignon secoue sa feuille pour tenir son ennemi à distance. Un doux parfum s’en dégage également, apaisant les Pokémon qui se battent et créant une atmosphère agréable et amicale."}],
  153: [{"g": "Noir", "t": "Le collier de bourgeons à son cou répand un arôme épicé qui vous donne du tonus."}, {"g": "X", "t": "Un arôme épicé émane de son cou. Il agit comme un stimulant et lui fait récupérer son énergie."}, {"g": "Rubis Oméga", "t": "Le cou de Macronium est entouré de nombreuses feuilles. Dans chacune d’elles se trouve une pousse d’arbre. Le parfum de cette pousse donne la pêche aux personnes qui le sentent."}],
  154: [{"g": "Noir", "t": "Son souffle a l’incroyable capacité de ranimer les plantes et les fleurs flétries."}, {"g": "X", "t": "L’arôme qui émane de ses pétales contient une substance qui calme les pulsions agressives."}, {"g": "Y", "t": "Le souffle de Méganium a le pouvoir de redonner la santé aux plantes malades ou mortes."}, {"g": "Rubis Oméga", "t": "Le parfum de la fleur de Méganium apaise et calme les esprits. Pendant les combats, ce Pokémon émet son parfum relaxant pour atténuer l’agressivité de l’ennemi."}],
  155: [{"g": "Noir", "t": "Ce Pokémon est un grand timide. Les flammes sur son dos s’intensifient lorsqu’il prend peur."}, {"g": "X", "t": "Il est timide et se roule en boule pour se protéger. Attaqué, il s’enflamme le dos pour riposter."}, {"g": "Rubis Oméga", "t": "Héricendre se protège en faisant jaillir des flammes de son dos. Ces flammes peuvent être violentes si le Pokémon est en colère. Cependant, s’il est fatigué, seules quelques flammèches vacillent laborieusement."}],
  156: [{"g": "Noir", "t": "La chaleur de ses flammes intimide l’ennemi. Elles s’intensifient lorsqu’il se prépare à combattre."}, {"g": "X", "t": "Avant chaque combat, il tourne le dos et montre la puissance de ses flammes."}, {"g": "Y", "t": "Attention ! Quand il tourne le dos dans un combat, c’est qu’il va attaquer avec ses flammes dorsales."}, {"g": "Rubis Oméga", "t": "Feurisson garde ses ennemis à distance grâce à l’intensité de ses flammes et à des rafales d’air brûlant. Ce Pokémon utilise son incroyable agilité pour éviter les attaques, tout en enflammant ses ennemis."}],
  157: [{"g": "Noir", "t": "Il attaque en projetant des flammes. Il se dissimule derrière les vagues de chaleur qu’il produit."}, {"g": "X", "t": "Quand il est furieux, il devient si chaud que tout ce qu’il touche s’enflamme instantanément."}, {"g": "Y", "t": "Il a un coup secret dévastateur. En frottant sa fourrure ardente, il crée une forte explosion."}, {"g": "Rubis Oméga", "t": "Typhlosion se cache derrière un chatoyant nuage de chaleur qu’il crée en attisant ses flammes intenses. Ce Pokémon peut générer des rafales explosives qui réduisent tout en cendres."}],
  158: [{"g": "Noir", "t": "Il broie tout ce qu’il trouve avec ses mâchoires puissantes. Même son Dresseur doit s’en méfier."}, {"g": "X", "t": "Petit mais costaud, il n’hésite pas à mordre tout ce qui passe à portée de ses dents."}, {"g": "Y", "t": "Sa mâchoire surdéveloppée est capable de tout broyer. Même son Dresseur doit s’en méfier."}, {"g": "Rubis Oméga", "t": "Malgré son tout petit corps, la mâchoire de Kaiminus est très puissante. Parfois, ce Pokémon mordille les gens pour jouer, sans se rendre compte que sa morsure peut gravement blesser quelqu’un."}],
  159: [{"g": "Noir", "t": "Quand il mord, il ne lâche pas prise avant que ses crocs se brisent. Ils repoussent par la suite."}, {"g": "X", "t": "Quand il perd un croc, il en repousse un autre. Sa bouche est en permanence composée de 48 dents."}, {"g": "Rubis Oméga", "t": "Une fois que Crocrodil a refermé sa mâchoire sur son ennemi, il est impossible de le faire lâcher prise. Ses crocs sont recourbés comme des hameçons et ne peuvent pas être retirés une fois enfoncés."}],
  160: [{"g": "Noir", "t": "Ce Pokémon à l’air pataud est capable d’attaquer à la vitesse de l’éclair pour mordre sa proie."}, {"g": "Y", "t": "Quand il mord avec sa puissante mâchoire, il secoue sa tête pour déchiqueter sa pauvre victime."}, {"g": "Rubis Oméga", "t": "Aligatueur impressionne ses ennemis en ouvrant son énorme gueule. Pendant les combats, il piétine le sol de ses puissantes pattes arrière avant de charger ses adversaires à pleine vitesse."}],
  161: [{"g": "Noir", "t": "Ce Pokémon très nerveux prend appui sur sa queue pour observer ses alentours."}, {"g": "X", "t": "S’il fait le guet, il prévient les autres d’un danger en criant et en frappant le sol de sa queue."}, {"g": "Y", "t": "Il se tient dressé sur sa queue pour voir les ennemis arriver de loin. À ce moment, il avertit ses amis."}, {"g": "Rubis Oméga", "t": "Lorsqu’un Fouinette dort, un autre monte la garde. La sentinelle réveille les autres au moindre signe de danger. Si un de ces Pokémon est séparé de sa meute, il est incapable de dormir, car il a peur."}],
  162: [{"g": "Noir", "t": "La femelle s’enroule autour des petits pour les bercer. Il accule l’ennemi grâce à sa vitesse."}, {"g": "Y", "t": "Il fabrique un nid qui convient à son corps très fin, et où lui seul peut entrer."}, {"g": "Rubis Oméga", "t": "Fouinar est très mince. Lorsqu’il est attaqué, il peut s’enfuir en se faufilant habilement dans les recoins étroits. Malgré ses pattes courtes, ce Pokémon est très agile et rapide."}],
  163: [{"g": "Noir", "t": "Il hulule chaque jour à la même heure. Dans certaines cultures, il incarne la sagesse."}, {"g": "X", "t": "Il a un sens du timing parfait. Il reste toujours en rythme en balançant sa tête."}, {"g": "Y", "t": "Il se tient toujours sur un pied. Il change de pied si vite qu’on peut à peine distinguer ce mouvement."}, {"g": "Rubis Oméga", "t": "Hoothoot est doté d’un organe interne qui ressent et suit la rotation de la planète. Grâce à cet organe peu ordinaire, ce Pokémon commence à hululer tous les jours exactement à la même heure."}, {"g": "Ultra-Soleil", "t": "Il hoche toujours la tête au même rythme, aussi faisait-il fréquemment office d’horloge par le passé."}, {"g": "Ultra-Lune", "t": "Il hulule toujours à la même heure. Il était autrefois vénéré comme le messager du dieu du temps."}, {"g": "Épée", "t": "Il se tient toujours sur un pied. Il en change si vite qu’on peut à peine distinguer ce mouvement."}, {"g": "Bouclier", "t": "Il hulule chaque jour aux mêmes moments. Certains Dresseurs s’en servent comme d’une montre."}],
  164: [{"g": "Noir", "t": "Ses yeux sont capables de voir distinctement même quand il fait très sombre."}, {"g": "X", "t": "Ses yeux sont adaptés à la nuit. Ils peuvent concentrer la faible lumière dans l’obscurité."}, {"g": "Y", "t": "Quand il réfléchit, il tourne sa tête sur 180° pour optimiser son mode de pensée."}, {"g": "Rubis Oméga", "t": "Dans l’obscurité, Noarfang ne rate jamais une proie. Il le doit à sa vision surdéveloppée qui lui permet de tout voir, même avec une lueur très faible, ainsi qu’à ses ailes très souples et silencieuses."}, {"g": "Ultra-Soleil", "t": "Sa vue perçante lui permettant de distinguer sa proie même dans l’obscurité la plus profonde, il a reçu le surnom d’« empereur de la nuit »."}, {"g": "Ultra-Lune", "t": "Quand il est soucieux, il tourne la tête à 180 degrés. Il ne faut alors surtout pas le déranger, sous peine de recevoir un coup de bec."}, {"g": "Épée", "t": "Ses yeux à la structure particulière sont capables de voir comme en plein jour même quand il fait très sombre."}, {"g": "Bouclier", "t": "Quand il réfléchit, il tourne sa tête sur 180 degrés pour optimiser son mode de pensée."}],
  165: [{"g": "Noir", "t": "Il est si timide qu’il ne se déplace qu’au milieu d’un essaim. Il exprime ses émotions par l’odeur."}, {"g": "X", "t": "Quand le temps se rafraîchit, de nombreux Coxy se réunissent pour conserver un maximum de chaleur."}, {"g": "Y", "t": "Il est timide et reste près de ses semblables. Il a un sens du toucher très développé."}, {"g": "Rubis Oméga", "t": "Coxy sécrète un fluide aromatisé sortant des articulations de ses pattes. Ce fluide lui permet de communiquer avec ses congénères. Ce Pokémon exprime ses sentiments en modifiant l’odeur de ce fluide."}, {"g": "Soleil", "t": "Il est si timide qu’il est inquiet s’il n’est pas en groupe. Les motifs sur son dos diffèrent légèrement d’un individu à l’autre."}, {"g": "Lune", "t": "Il communique avec ses congénères grâce à un fluide odorant. Quand il est en colère, l’odeur en devient vraiment aigre."}, {"g": "Ultra-Soleil", "t": "Ce Pokémon très sensible au froid semble revivre lorsqu’il se trouve dans des régions chaudes comme Alola."}, {"g": "Ultra-Lune", "t": "Extrêmement timide, ce Pokémon défend le nid qu’il partage avec ses congénères en utilisant Protection."}],
  166: [{"g": "Noir", "t": "Il tire sa force de la lumière des étoiles. Plus il y en a et plus ses motifs dorsaux sont grands."}, {"g": "X", "t": "Quand les étoiles brillent dans le ciel, il volette partout en semant derrière lui une poudre brillante."}, {"g": "Y", "t": "Les points sur son dos deviennent plus grands ou plus petits selon le nombre d’étoiles dans le ciel."}, {"g": "Rubis Oméga", "t": "On dit que dans les pays où le ciel est dégagé et où les étoiles illuminent les cieux, vivent d’innombrables quantités de Coxyclaque. La raison en est simple : l’énergie de ce Pokémon provient de la lumière des étoiles."}, {"g": "Soleil", "t": "On dit qu’il se nourrit de la lumière des étoiles, mais il mange aussi des Baies comme les autres. Il dort pendant la journée dans un lit d’herbes."}, {"g": "Lune", "t": "Il se bat en frappant avec ses quatre poings. Chaque coup ne fait pas très mal mais assénées en rafale, ses attaques sont dévastatrices."}, {"g": "Ultra-Soleil", "t": "Le motif qui orne son dos aurait un lien avec les étoiles, mais nul ne sait encore en quoi consiste ce lien."}, {"g": "Ultra-Lune", "t": "Il vole dans le ciel nocturne en répandant une poudre scintillante. Si elle vous touche, quelque chose de positif devrait bientôt vous arriver."}],
  167: [{"g": "Noir", "t": "Il tisse une toile fine mais solide pour poser des pièges et se poste dans l’attente d’une proie."}, {"g": "X", "t": "Il tisse une toile en utilisant un fil fin mais solide, puis il attend tranquillement sa proie."}, {"g": "Y", "t": "Il reste immobile dans sa toile pendant des jours. Il attend que sa proie se rapproche pour la capturer."}, {"g": "Rubis Oméga", "t": "La toile tissée par Mimigal peut être comparée à un second système nerveux. On raconte que ce Pokémon peut déterminer quel type de proie touche sa toile grâce aux infimes vibrations des fils."}, {"g": "Soleil", "t": "Il attend dans sa toile jusqu’à ce qu’un Bombydou, son mets favori, s’y fasse prendre. C’est un Pokémon extrêmement patient."}, {"g": "Lune", "t": "Certains pêcheurs récoltent son fil solide pour tisser des filets et attraper des Pokémon poissons."}, {"g": "Ultra-Soleil", "t": "La toile qu’il tisse avec les fils qu’il sécrète est tellement solide qu’elle peut soutenir une pierre de dix kilos."}, {"g": "Ultra-Lune", "t": "Le poison contenu dans les mandibules de ce Pokémon n’est pas très violent, mais il suffit à immobiliser les proies piégées dans sa toile."}],
  168: [{"g": "Noir", "t": "Il attache un fil à sa proie avant de la libérer. Il s’en servira pour la retrouver, elle et ses amis."}, {"g": "X", "t": "Il peut produire des fils de soie par l’arrière-train ou par la bouche. Il est difficile de différencier les deux."}, {"g": "Rubis Oméga", "t": "À l’extrémité des pattes de Migalos, on trouve de petits crochets qui lui permettent de cavaler sur les surfaces verticales et au plafond. Ce Pokémon peut piéger ses ennemis dans sa solide toile de soie."}, {"g": "Soleil", "t": "Dans certaines régions, on utilise le fil de Migalos pour tisser des étoffes. Leur grande solidité les rend très populaires."}, {"g": "Lune", "t": "Ce Pokémon peut créer du fil avec sa bouche ou son abdomen. Il l’utilise pour ligoter sa proie, puis aspire lentement ses fluides vitaux."}, {"g": "Ultra-Soleil", "t": "Il erre chaque nuit à la recherche d’une proie. Quand il en trouve une, il l’immobilise grâce à ses fils, puis la croque avec ses mandibules."}, {"g": "Ultra-Lune", "t": "Il capture ses proies en projetant un fil qu’il sécrète. À la nuit tombée, il quitte sa toile et part chasser activement."}],
  169: [{"g": "Noir", "t": "La transformation de ses pattes en ailes a certes amélioré sa capacité à voler, mais pas à marcher."}, {"g": "X", "t": "Il vole en silence dans l’obscurité à l’aide de ses quatre ailes. On ne l’entend pas, même s’il est très proche."}, {"g": "Y", "t": "Ses quatre ailes lui permettent de voler furtivement pour approcher ses proies sans les effrayer."}, {"g": "Rubis Oméga", "t": "Lorsque Nostenfer vole depuis longtemps, il utilise ses ailes antérieures ou postérieures en alternance. Il peut aisément changer de paire d’ailes lorsqu’il est fatigué."}, {"g": "Saphir Alpha", "t": "Nostenfer s’approche discrètement de sa proie grâce à ses ailes silencieuses. Ce Pokémon se repose en s’accrochant à une branche avec ses pattes arrière, qui peuvent aussi lui servir d’ailes."}, {"g": "Soleil", "t": "Comme ses pattes sont devenues des ailes, il a du mal à se mouvoir sur terre. Il ne peut que se traîner péniblement au sol."}, {"g": "Lune", "t": "Il vole vite et sans bruit grâce à ses quatre ailes, mord sa proie sans se faire remarquer, et disparaît aussi vite, la laissant exsangue."}, {"g": "Ultra-Soleil", "t": "Ses crocs sont si acérés qu’il peut sucer le sang de ses proies dans l’obscurité sans même qu’elles s’en rendent compte."}, {"g": "Ultra-Lune", "t": "Il se nourrit du sang frais d’humains et de Pokémon. S’il en manque ne serait-ce qu’un instant, il s’affaiblit et ne peut plus voler."}, {"g": "Épée", "t": "Ses pattes sont devenues des ailes. Il fond sur sa proie furtivement puis plante ses crocs dans sa nuque."}, {"g": "Bouclier", "t": "Il vole en contrôlant librement ses quatre ailes et peut se déplacer sans avoir besoin de ralentir, même dans les grottes étroites."}],
  170: [{"g": "Noir", "t": "Il envoie des décharges électriques positives et négatives du bout des antennes pour paralyser sa proie."}, {"g": "X", "t": "Au plus profond de l’océan, son seul moyen de communication est sa lumière qui clignote constamment."}, {"g": "Y", "t": "Il émet avec ses antennes des impulsions positives et négatives qui peuvent électrocuter ses ennemis."}, {"g": "Rubis Oméga", "t": "Loupio relâche des charges électriques positives et négatives de ses deux antennes pour mettre sa proie K.O. Ce Pokémon illumine ses ampoules électriques pour communiquer avec ses congénères."}, {"g": "Saphir Alpha", "t": "Les deux antennes de Loupio sont chargées de cellules qui génèrent un courant de forte intensité. Ces cellules libèrent tellement d’électricité qu’elles vibrent légèrement."}, {"g": "Soleil", "t": "Ses deux antennes étaient à l’origine des ailerons. Il libère de l’électricité pour étourdir ses proies avant de passer à l’attaque."}, {"g": "Lune", "t": "Il vit dans les profondeurs marines que le soleil n’atteint pas. Il utilise ses antennes lumineuses pour communiquer avec ses congénères."}, {"g": "Ultra-Soleil", "t": "Ses deux antennes luisent légèrement pour attirer ses proies. C’est un Pokémon très pratique pour pêcher la nuit."}, {"g": "Ultra-Lune", "t": "Les Loupio marquent les limites de leur territoire en faisant clignoter leurs antennes."}, {"g": "Épée", "t": "Ses antennes proviennent d’anciennes nageoires et sont chargées d’énergies positive et négative."}, {"g": "Bouclier", "t": "Au plus profond de l’océan, son seul moyen de communication est la lumière de ses antennes, qui clignotent constamment."}],
  171: [{"g": "Noir", "t": "La lumière de Lanturn surgit des profondeurs. On le surnomme “étoile des profondeurs”."}, {"g": "X", "t": "La lumière de Lanturn surgit des profondeurs. On le surnomme « étoile des profondeurs »."}, {"g": "Y", "t": "Il aveugle sa proie avec une lumière intense, puis l’avale d’un seul trait une fois immobilisée."}, {"g": "Rubis Oméga", "t": "On surnomme Lanturn « l’étoile des profondeurs » à cause de son antenne lumineuse. Ce Pokémon produit de la lumière en provoquant une réaction chimique entre des bactéries et les fluides corporels de son antenne."}, {"g": "Saphir Alpha", "t": "On sait que Lanturn émet de la lumière. Si on regarde attentivement la mer de nuit à partir d’un bateau, on peut voir la lumière générée par ce Pokémon éclairer les profondeurs. Cela donne à la mer l’apparence d’un ciel étoilé."}, {"g": "Soleil", "t": "Lorsqu’on regarde au fond de la mer au milieu de la nuit et que l’on croit apercevoir le reflet des étoiles, c’est probablement un Lanturn."}, {"g": "Lune", "t": "Il dégage une vive lumière pour éblouir ses proies, puis les achève d’un choc électrique bien senti."}, {"g": "Ultra-Soleil", "t": "Les bactéries nichées dans l’antenne de Lanturn émettent une lumière vive quand elles aspirent ses fluides corporels."}, {"g": "Ultra-Lune", "t": "Ce Pokémon des abysses immobilise ses proies en les aveuglant grâce à la lumière de son antenne, puis les gobe toutes crues."}, {"g": "Épée", "t": "Sa lumière est si intense qu’on peut la voir à la surface de l’eau alors qu’il se trouve à 5 000 mètres de profondeur."}, {"g": "Bouclier", "t": "Il dégage une vive lumière pour éblouir ses proies, puis leur inflige un choc électrique bien senti."}],
  172: [{"g": "Noir", "t": "Les poches électriques de ses joues sont encore petites, mais risquent de l’électrocuter."}, {"g": "X", "t": "Il prouve son courage en touchant la queue électrifiée de ses pairs."}, {"g": "Y", "t": "Il ne sait pas encore stocker l’électricité. Il envoie des décharges par jeu ou par peur."}, {"g": "Rubis Oméga", "t": "Pichu se charge plus facilement en électricité les jours d’orage ou lorsque l’air est très sec. On peut entendre le crépitement de l’électricité statique générée par ce Pokémon."}, {"g": "Saphir Alpha", "t": "Lorsque Pichu joue, il lui arrive de faire des courts-circuits avec un autre Pichu, créant ainsi une gerbe d’étincelles. Du coup, ce Pokémon prend peur et se met à pleurer."}, {"g": "Soleil", "t": "Il ne contrôle pas encore bien son électricité. Si on le laisse sans surveillance, il est capable de s’électrocuter lui-même."}, {"g": "Lune", "t": "Bien qu’il soit adorable, il faut être prêt à supporter ses décharges électriques répétées si l’on veut vivre avec un Pichu."}, {"g": "Ultra-Soleil", "t": "Il ne contrôle pas encore bien l’électricité, et laisse échapper des décharges lorsqu’il est surpris ou en proie à de fortes émotions."}, {"g": "Ultra-Lune", "t": "Les poches de ses joues renferment de l’électricité. Lorsqu’elles sont chargées, il a tellement d’énergie qu’il ne pense qu’à jouer."}, {"g": "Épée", "t": "Malgré sa petite taille, il peut électrocuter de grandes personnes, ce qui le surprend également."}, {"g": "Bouclier", "t": "Les poches électriques de ses joues sont très petites. Lorsqu’elles sont surchargées, il s’électrocute lui-même."}],
  173: [{"g": "Noir", "t": "On dit qu’il se déplace à dos d’étoile filante. Il se montre souvent quand on en voit."}, {"g": "X", "t": "Il ressemble un peu à une étoile. On suppose qu’il est venu sur terre accroché à une météorite."}, {"g": "Y", "t": "On en voit beaucoup lorsque le ciel se remplit d’étoiles filantes. Ils s’éclipsent au lever du soleil."}, {"g": "Rubis Oméga", "t": "Les nuits où il y a des étoiles filantes, on peut voir des Mélo danser en cercle. Ils dansent toute la nuit et ne s’arrêtent qu’à l’aube. Ces Pokémon se désaltèrent alors avec la rosée du matin."}, {"g": "Soleil", "t": "On dit que s’il contemple fixement le ciel lorsque des étoiles filantes passent, c’est parce que cela lui rappelle son bercail."}, {"g": "Lune", "t": "Selon certaines croyances, sa forme prouve qu’il s’agit de la réincarnation d’une étoile. Étrangement, il aime beaucoup les Météno."}, {"g": "Ultra-Soleil", "t": "Les nuits où les étoiles filantes inondent le ciel, il danse en cercle avec ses congénères. On dit qu’admirer ce spectacle porte bonheur."}, {"g": "Ultra-Lune", "t": "Il serait parvenu jusqu’à nous en chevauchant une étoile filante. On le trouve dans les endroits où des météorites sont tombées."}, {"g": "Épée", "t": "On dit qu’il apparaît souvent là où se sont écrasées des météorites."}],
  174: [{"g": "Noir", "t": "Son corps est doux et élastique. Quand il commence à rebondir, on ne peut plus l’arrêter."}, {"g": "X", "t": "Plutôt que de se déplacer avec ses petites pattes, il rebondit avec son corps doux et moelleux."}, {"g": "Y", "t": "Son corps est très doux. Quand il commence à rebondir, il est impossible de l’arrêter."}, {"g": "Rubis Oméga", "t": "Les cordes vocales de Toudoudou ne sont pas assez développées. S’il devait chanter trop longtemps, il se ferait mal à la gorge. Ce Pokémon se gargarise souvent avec de l’eau fraîche puisée dans un ruisseau clair."}, {"g": "Saphir Alpha", "t": "Toudoudou a un corps mou et pelucheux, semblable à de la guimauve. Un parfum doux et sucré s’échappe de son corps, ce qui lui permet d’apaiser et de calmer ses ennemis."}, {"g": "Soleil", "t": "Il adore chanter, mais il n’est pas encore très doué. Il s’améliore progressivement si on le complimente suffisamment."}, {"g": "Lune", "t": "Il se déplace en rebondissant comme une balle. Quand il a beaucoup bougé et qu’il sue, son corps dégage une légère odeur sucrée."}, {"g": "Ultra-Soleil", "t": "Il s’entraîne dur pour maîtriser le chant. Même quand il dort, il continue de faire des gammes dans ses rêves."}, {"g": "Ultra-Lune", "t": "Si on le laissait faire, il passerait son temps à chanter. Il vaut donc mieux l’en empêcher pour préserver sa petite gorge."}, {"g": "Épée", "t": "Il adore chanter. Son corps semblable à de la guimauve dégage une légère odeur sucrée."}, {"g": "Bouclier", "t": "Il se déplace en faisant rebondir son corps tout mou. Lorsque sa température corporelle augmente, il devient rose foncé."}],
  175: [{"g": "Noir", "t": "Il transforme les émotions positives des autres en bonheur qu’il stocke dans sa coquille."}, {"g": "X", "t": "Sa coquille est remplie de joie. On dit que s’il est bien traité, il porte chance."}, {"g": "Y", "t": "Un proverbe nous enseigne que le bonheur touchera celui qui peut faire tenir debout un Togepi endormi."}, {"g": "Rubis Oméga", "t": "L’énergie de Togepi provient des émotions positives et du plaisir exprimé par les gens et les Pokémon. Ce Pokémon accumule les sentiments de bonheur dans sa coquille, puis les partage avec les autres."}, {"g": "Bouclier", "t": "C’est un symbole de chance. On dit que sa coquille est remplie de joie."}],
  176: [{"g": "Noir", "t": "Il parcourt le monde pour distribuer de la joie aux êtres bons."}, {"g": "X", "t": "Il se démoralise vite s’il n’est pas avec des gens sympathiques. Il peut léviter sans battre des ailes."}, {"g": "Y", "t": "On dit qu’il n’apparaît qu’aux cœurs purs et qu’il leur apporte la joie et le bonheur."}, {"g": "Rubis Oméga", "t": "On raconte que Togetic est un Pokémon qui porte chance. Si ce Pokémon remarque quelqu’un doté d’un cœur pur, il apparaît et partage son bonheur avec la personne en question."}, {"g": "Épée", "t": "On dit qu’il se montre aux personnes dotées d’un cœur pur pour leur apporter joie et bonheur."}, {"g": "Bouclier", "t": "Ce Pokémon est capable de léviter sans battre des ailes. Il est vite démoralisé s’il n’est pas en compagnie de gens sympathiques."}],
  177: [{"g": "Noir", "t": "Il mange des cactus en prenant soin d’éviter les bourgeons et les épines. Il ne tient pas en place."}, {"g": "X", "t": "Ses ailes ne sont pas assez développées et il ne peut que planer péniblement. Il fixe toujours quelque chose."}, {"g": "Y", "t": "Il cherche sa nourriture par terre, mais quelquefois il grimpe aux arbres pour manger."}, {"g": "Rubis Oméga", "t": "Natu ne peut pas voler, car ses ailes n’ont pas encore fini de grandir. Si ses yeux croisent le regard de quelqu’un d’autre, il reste immobile et concentré. Mais si la personne en question détourne son regard, il s’enfuit en lieu sûr."}, {"g": "Saphir Alpha", "t": "Natu est capable de sauter très haut. Ce Pokémon bat des ailes et saute sur les branches élevées des arbres pour en récupérer les bourgeons."}, {"g": "Ultra-Soleil", "t": "Bien qu’il ne sache pas encore voler, il peut sauter jusqu’aux plus hautes branches des arbres pour en picorer les bourgeons."}, {"g": "Ultra-Lune", "t": "Son regard fixe semble dévisager les gens. Il s’enfuit en sautillant à la moindre tentative d’approche."}, {"g": "Épée", "t": "Il est très doué pour grimper aux arbres et ainsi manger les bourgeons dont il raffole."}, {"g": "Bouclier", "t": "Ses ailes ne sont pas assez développées donc il ne peut se déplacer qu’en sautillant. Il fixe toujours quelque chose du regard."}],
  178: [{"g": "Noir", "t": "Cet étrange Pokémon peut voir l’avenir et le passé. Il guette sans cesse la course du soleil."}, {"g": "X", "t": "Il peut rester à méditer sans bouger, du lever du soleil jusqu’à la tombée de la nuit."}, {"g": "Y", "t": "On dit qu’il est calme et tranquille car il peut voir en permanence le passé et le futur."}, {"g": "Rubis Oméga", "t": "Xatu se tient debout et immobile toute la journée. Certains pensent que ce Pokémon a adopté cette position à cause de la terreur qu’il a ressentie en prévoyant l’avenir."}, {"g": "Saphir Alpha", "t": "On sait que Xatu se tient toute la journée debout, les yeux perdus vers l’horizon. Certaines personnes le vénèrent comme un Pokémon mystique, persuadées que Xatu a le pouvoir de prédire l’avenir."}, {"g": "Ultra-Soleil", "t": "Ce Pokémon aurait le pouvoir de voir l’avenir. Il n’a malheureusement pas celui de le changer."}, {"g": "Ultra-Lune", "t": "Bien qu’il puisse voir l’avenir, il n’a aucune intention de le changer. Cela expliquerait pourquoi il reste immobile."}, {"g": "Épée", "t": "On dit qu’il reste immobile et silencieux parce qu’il observe simultanément le passé et le futur."}, {"g": "Bouclier", "t": "Capable de voir le passé et l’avenir, ce Pokémon mystérieux consacre toutes ses journées à observer la course du soleil."}],
  179: [{"g": "Noir", "t": "Sa laine fournie enfle lorsqu’il accumule de l’électricité statique. Son contact peut choquer."}, {"g": "Y", "t": "Il garde une grande quantité d’air dans sa toison pour ne pas subir les variations de température."}, {"g": "Rubis Oméga", "t": "L’épaisse fourrure cotonneuse de Wattouat se charge d’électricité statique lorsqu’on la frotte. Plus elle est chargée, plus l’ampoule au bout de sa queue est lumineuse."}, {"g": "Ultra-Soleil", "t": "En raison de leur tendance à stocker l’électricité statique, les vêtements en laine de Wattouat subissent un traitement spécial."}, {"g": "Ultra-Lune", "t": "Il a beau être mignon, sa laine génère de l’électricité quand on la frotte. Tentez de le caresser, et il vous mettra vite au courant !"}],
  180: [{"g": "Noir", "t": "Sa queue s’allume lorsque sa laine se charge d’électricité. Il projette des poils électrifiés."}, {"g": "X", "t": "Sa douce laine stocke facilement l’électricité. Sa peau caoutchouteuse prévient l’électrocution."}, {"g": "Rubis Oméga", "t": "La qualité de la laine de Lainergie se modifie pour générer un maximum d’électricité statique avec un minimum de laine. Les sections glabres de sa peau sont résistantes à l’électricité."}, {"g": "Ultra-Soleil", "t": "Sa peau lisse et élastique étant isolante, on peut la caresser sans risquer de se prendre une décharge électrique."}, {"g": "Ultra-Lune", "t": "Il accumule de l’électricité dans sa toison duveteuse. Il en a tellement stocké qu’il en a perdu sa laine par endroits."}],
  181: [{"g": "Noir", "t": "Le bout de sa queue brille avec intensité. Jadis, on s’en servait pour envoyer des signaux."}, {"g": "X", "t": "Le bout de sa queue brille si fort qu’il peut être vu de très loin. Il sert de balise aux gens."}, {"g": "Rubis Oméga", "t": "Pharamp est si lumineux qu’on peut le voir de l’espace. Jadis, les gens utilisaient la lumière de ce Pokémon pour communiquer et s’envoyer des signaux à grande distance."}, {"g": "Ultra-Soleil", "t": "La lumière de sa queue est si vive qu’on peut la voir depuis l’espace. En général, il l’éteint donc pour éviter de se faire repérer."}, {"g": "Ultra-Lune", "t": "Sa queue brille d’une lumière éclatante. Depuis des temps très anciens, il est vénéré comme le guide des marins."}],
  182: [{"g": "Noir", "t": "À la fin de la saison des pluies, il sort danser en plein air, attiré par la chaleur du soleil."}, {"g": "X", "t": "Les Joliflor se réunissent souvent pour danser. On pense que c’est un rituel pour appeler le soleil."}, {"g": "Rubis Oméga", "t": "Lorsque Joliflor reste exposé à la lumière du soleil, les feuilles autour de son corps se mettent à tournoyer. La danse de ce Pokémon est très célèbre dans les régions du sud."}, {"g": "Saphir Alpha", "t": "Les fleurs de Joliflor sont encore plus jolies s’il s’agit d’une évolution d’un Ortide qui sentait vraiment très mauvais. La nuit, ce Pokémon ferme ses pétales pour dormir."}, {"g": "Épée", "t": "Ce Pokémon vit en nombre dans les tropiques. Quand il danse, ses pétales frottent les uns contre les autres et émettent un son mélodieux."}, {"g": "Bouclier", "t": "Les Joliflor se réunissent parfois pour danser. On pense que c’est un rituel pour invoquer le soleil."}],
  183: [{"g": "Noir", "t": "Sa queue à l’extrémité remplie d’huile fait office de flotteur et lui permet de ne pas couler."}, {"g": "X", "t": "Sa fourrure est imperméable, si bien qu’il reste sec même en jouant dans l’eau."}, {"g": "Y", "t": "Le bout de sa queue renferme une huile plus légère que l’eau qui fait office de flotteur."}, {"g": "Rubis Oméga", "t": "La queue remplie d’huile de Marill lui sert de gilet de sauvetage. Parfois, on peut voir sa queue flotter à la surface. On peut en déduire que ce Pokémon a plongé sous l’eau pour se nourrir de plantes aquatiques."}, {"g": "Saphir Alpha", "t": "Lorsqu’il pêche pour se nourrir sur les rives d’un fleuve rapide, Marill accroche sa queue autour d’un tronc d’arbre pour ne pas être emporté. La queue de ce Pokémon est flexible et résiste à l’étirement."}, {"g": "Épée", "t": "Sa queue ronde lui sert de bouée. La boule au bout de celle-ci est remplie de nutriments qui se sont changés en huile."}, {"g": "Bouclier", "t": "Sa fourrure est hydrophobe, si bien qu’elle sèche en un instant. Il n’a donc jamais froid, même lorsqu’il sort d’une mer glaciale."}],
  184: [{"g": "Noir", "t": "Ses poumons peuvent contenir assez d’air pour lui permettre de passer une journée sous l’eau."}, {"g": "X", "t": "Ses longues oreilles font un radar efficace. Elles décèlent les mouvements dans le lit des rivières."}, {"g": "Y", "t": "Les motifs sur son ventre lui permettent de se camoufler lorsqu’il est dans l’eau."}, {"g": "Rubis Oméga", "t": "Les longues oreilles d’Azumarill sont des capteurs indispensables. Lorsqu’il se concentre pour écouter, ce Pokémon peut identifier les proies aux alentours, même dans les cours d’eau à fort courant ou les rapides."}, {"g": "Saphir Alpha", "t": "Azumarill peut faire des bulles d’air. Il fabrique ces bulles lorsqu’il voit un Pokémon en train de se noyer. Les bulles d’air permettent au Pokémon en difficulté de respirer."}, {"g": "Épée", "t": "Il passe la majeure partie de la journée dans l’eau. Quand il fait beau, il flotte à la surface pour prendre un bain de soleil."}, {"g": "Bouclier", "t": "Il crée des bulles d’air dont il enveloppe gentiment les Azurill venus jouer dans la rivière."}],
  185: [{"g": "Noir", "t": "Il prend l’apparence d’un arbre pour éviter les attaques, mais il déteste l’eau et fuit la pluie."}, {"g": "X", "t": "Il fait semblant d’être un arbre. Sa composition est en fait plus proche de la pierre."}, {"g": "Y", "t": "Il se déguise en arbre pour éviter les problèmes. Il déteste l’eau et se cache par temps de pluie."}, {"g": "Rubis Oméga", "t": "Simularbre se camoufle en arbre pour éviter d’être attaqué par ses ennemis. Mais étant donné que ses pattes restent vertes toute l’année, ce Pokémon est facile à repérer pendant l’hiver."}, {"g": "Soleil", "t": "Il imite un arbre pour passer inaperçu, mais il déteste tellement l’eau qu’il prend ses jambes à son cou s’il se fait arroser."}, {"g": "Lune", "t": "Très populaire, notamment chez les personnes âgées. Plus la partie verte est grande, plus ses fans se l’arrachent."}, {"g": "Ultra-Soleil", "t": "Il fait l’objet de revues spécialisées tant il est populaire auprès des personnes âgées. Ses fans aiment surtout la longueur et l’angle de ses bras."}, {"g": "Ultra-Lune", "t": "La souplesse et la robustesse de ses bras sont le fruit d’un entraînement long et rigoureux qui consiste en une immobilité prolongée."}, {"g": "Épée", "t": "Si une branche remue alors qu’il n’y a pas de vent, c’est qu’il s’agit d’un Simularbre. On n’en croise jamais les jours de pluie."}, {"g": "Bouclier", "t": "Il se déguise en arbre pour éviter de se faire attaquer. Il déteste l’eau et se cache par temps de pluie."}],
  186: [{"g": "Noir", "t": "Il rassemble ses pairs pour les commander. Il utilise son cri pour diriger Ptitard."}, {"g": "X", "t": "Quand trois ou plus se réunissent, ils chantent d’une même voix ressemblant à un beuglement."}, {"g": "Y", "t": "Si Ptitard et Têtarte entendent son cri, ils se rassemblent pour venir le rencontrer."}, {"g": "Rubis Oméga", "t": "Le cheveu bouclé sur la tête de Tarpaud est la preuve de son statut de roi. On raconte que plus son cheveu est long et bouclé, plus ce Pokémon est respecté par ses semblables."}, {"g": "Soleil", "t": "Ils se regroupent sous la lune pour chanter. Leur musique est très bruyante et s’apparente à une dispute, mais certains esthètes l’apprécient."}, {"g": "Lune", "t": "Les Ptitard et Têtarte lui obéissent. Il n’a qu’à donner de la voix pour les faire trembler comme des feuilles."}, {"g": "Ultra-Soleil", "t": "Bien que le chant de ce Pokémon s’apparente à des cris, un musicien s’en est inspiré pour composer une magnifique ballade."}, {"g": "Ultra-Lune", "t": "La longueur et la beauté du cheveu bouclé qui orne la tête de Tarpaud influencent directement le nombre de Ptitard et de Têtarte lui obéissant."}, {"g": "Épée", "t": "Il apparaît sur les rives des étangs à la nuit tombée. Il marque son territoire en poussant des hurlements."}, {"g": "Bouclier", "t": "Le cri des mâles est plus puissant que celui des femelles, qui préfèrent les voix fortes et intimidantes."}],
  187: [{"g": "Noir", "t": "Il dérive avec le vent. Sa présence en nombre dans les champs et les montagnes annonce le printemps."}, {"g": "X", "t": "Son corps est si léger qu’il doit s’agripper au sol pour éviter de s’envoler les jours de brise."}, {"g": "Rubis Oméga", "t": "Ce Pokémon flotte à la dérive, porté par le vent. S’il sent qu’un vent très fort approche, Granivol attache ses feuilles aux autres Granivol pour ne pas être emporté par la bourrasque."}],
  188: [{"g": "Noir", "t": "Il fleurit lorsque les températures remontent. Il flotte dans le ciel pour absorber les rayons du soleil."}, {"g": "X", "t": "Le bourgeon sur sa tête s’ouvre et se ferme en fonction des fluctuations de la température ambiante."}, {"g": "Y", "t": "Il étend ses pétales pour absorber la lumière du soleil. Il flotte pour se rapprocher du soleil."}, {"g": "Rubis Oméga", "t": "La fleur de Floravol éclot lorsque la température atteint 18 °C. L’ouverture de la fleur change en fonction de la température. Certaines personnes se servent de ce Pokémon comme d’un thermomètre."}],
  189: [{"g": "Noir", "t": "Poussé par les vents saisonniers, il fait le tour du globe en semant des spores de coton."}, {"g": "Y", "t": "Même sous un vent très violent, il contrôle sa destination en bougeant ses appendices."}, {"g": "Rubis Oméga", "t": "Cotovol traverse la mer, porté par les vents, pour découvrir de nouveaux territoires. Ce Pokémon se rapproche du sol quand le vent est trop froid."}],
  190: [{"g": "Noir", "t": "Sa queue est aussi agile que ses mains. Il vit en haut des grands arbres."}, {"g": "X", "t": "Il vit sur les plus hautes cimes. Sautant de branche en branche, sa queue lui assure un bon équilibre."}, {"g": "Y", "t": "Sa queue est si forte qu’il peut l’utiliser pour se suspendre aux branches des arbres."}, {"g": "Rubis Oméga", "t": "L’extrémité de la queue de Capumain ressemble à une main et peut être utilisée de façon ingénieuse. Malheureusement, ce Pokémon utilise tellement sa queue que ses véritables mains sont devenues très maladroites."}, {"g": "Ultra-Soleil", "t": "À force d’utiliser sa queue à tort et à travers, elle est devenue plus habile que ses mains. Il l’utilise pour faire son nid en haut des arbres."}, {"g": "Ultra-Lune", "t": "Il guette ses proies depuis la cime des arbres. Quand il aperçoit un Croquine, son mets préféré, il se jette dessus."}],
  191: [{"g": "Noir", "t": "Il tombe du ciel sans crier gare en matinée. On en croise énormément l’année suivant un été froid."}, {"g": "X", "t": "Il tombe du ciel soudainement. S’il est attaqué par un Piafabec, il secoue violemment ses feuilles."}, {"g": "Y", "t": "Il vit en buvant la rosée sur les feuilles. On dit qu’il ne peut rien avaler d’autre."}, {"g": "Rubis Oméga", "t": "Tournegrin essaie de bouger le moins possible. C’est parce qu’il veut conserver tous les nutriments qu’il stocke dans son corps pour son évolution. Il ne mange pas, ne subsistant que grâce à la rosée matinale."}],
  192: [{"g": "Noir", "t": "Les rayons du soleil lui donnent de l’énergie. Il est connu pour migrer vers les régions ensoleillées."}, {"g": "X", "t": "À l’approche des beaux jours, les pétales entourant sa tête deviennent plus chatoyants."}, {"g": "Rubis Oméga", "t": "Héliatronc convertit l’énergie solaire en nutriments. Il remue activement pendant la journée, quand il fait chaud. Il redevient immobile dès que le soleil se couche."}],
  193: [{"g": "Noir", "t": "La vitesse de ses ailes lui permet un vol stationnaire. Il surveille ainsi tout son territoire."}, {"g": "X", "t": "Il voit à 360° sans avoir à tourner la tête. Il ne loupe jamais une proie, même dans son dos."}, {"g": "Y", "t": "En battant des ailes très vite, il peut générer une violente onde de choc qui peut briser les fenêtres."}, {"g": "Rubis Oméga", "t": "Yanma a un champ de vision de 360 degrés sans avoir besoin de bouger les yeux. Il vole incroyablement bien et peut faire des figures acrobatiques. Ce Pokémon descend en piqué sur ses proies."}],
  194: [{"g": "Noir", "t": "Sur la terre ferme, il couvre son corps d’un fluide toxique qui le protège de la déshydratation."}, {"g": "X", "t": "Ce Pokémon vit en eaux froides. Il ne les quitte que pour se nourrir quand il fait froid à l’extérieur."}, {"g": "Y", "t": "Il émerge de l’eau lorsque l’air se rafraîchit pour partir chasser sur les berges."}, {"g": "Rubis Oméga", "t": "Axoloto vit généralement dans l’eau. Mais de temps en temps, il vient sur terre pour chercher à manger. À terre, il recouvre son corps d’un voile visqueux et toxique."}, {"g": "Épée", "t": "Ce Pokémon vit en eaux froides. Si la température extérieure est assez basse, il lui arrive de se rendre sur la terre ferme pour se nourrir."}, {"g": "Bouclier", "t": "Lorsqu’il est sur la terre ferme, il couvre son corps d’un voile toxique qui le protège de la déshydratation."}],
  195: [{"g": "Noir", "t": "De nature placide, il a tendance à se cogner la tête contre les récifs et autres bateaux de passage."}, {"g": "X", "t": "C’est un grand paresseux qui attend au fond de la rivière qu’une proie lui tombe dans le bec."}, {"g": "Y", "t": "Ce Pokémon est très insouciant. Quand il nage, il fonce tête la première dans la coque des bateaux."}, {"g": "Rubis Oméga", "t": "Maraiste trouve sa nourriture en laissant sa bouche ouverte dans l’eau, et attend que ses proies y pénètrent sans faire attention. Comme ce Pokémon est inactif, il n’a jamais très faim."}, {"g": "Épée", "t": "Il a tendance à se cogner la tête contre la coque des navires et les rochers, mais, imperturbable, il continue de nager comme si de rien n’était."}, {"g": "Bouclier", "t": "Il est toujours gluant. Quand il nage, il se cogne souvent la tête au fond des rivières, mais semble s’en moquer."}],
  196: [{"g": "Noir", "t": "Sa fourrure est si sensible qu’il peut détecter les vibrations de l’air et prédire le temps qu’il fera."}, {"g": "X", "t": "Le bout fourchu de sa queue frémit lorsqu’il prédit la prochaine attaque de son adversaire."}, {"g": "Y", "t": "Sa fourrure ultrasensible détecte les vibrations de l’air. Il peut ainsi prédire le temps ou lire les pensées adverses."}, {"g": "Rubis Oméga", "t": "Mentali est extrêmement loyal envers les Dresseurs qu’il respecte. On raconte que ce Pokémon a développé des talents divinatoires pour protéger son Dresseur."}, {"g": "Soleil", "t": "Son pelage court et clairsemé détecte en un instant le moindre mouvement de l’air ou de l’ennemi."}, {"g": "Lune", "t": "Le joyau sur son front projette des ondes psychiques en combat, et s’obscurcit lorsque Mentali est à bout de force."}, {"g": "Ultra-Soleil", "t": "À l’origine, il n’était doté d’aucune compétence particulière, mais il a développé un don de prescience pour se défendre."}, {"g": "Ultra-Lune", "t": "Le joyau sur son front accumulant de la force psychique lorsqu’il est exposé à la lumière du soleil, il préfère les combats de jour."}, {"g": "Épée", "t": "En analysant les courants aériens, il peut prédire la météo ou même les mouvements de son ennemi."}, {"g": "Bouclier", "t": "Le joyau sur le front de Mentali projette des ondes psychiques en combat, et s’obscurcit quand il est à bout de force."}],
  197: [{"g": "Noir", "t": "Quand il s’expose à la lumière de la lune, ses anneaux brillent et il obtient un mystérieux pouvoir."}, {"g": "X", "t": "La lumière de la lune a modifié le code génétique d’Évoli. Il hante les ombres en quête d’une proie."}, {"g": "Y", "t": "Quand il s’expose à la lumière de la lune, ses anneaux brillent et il développe de mystérieux pouvoirs."}, {"g": "Rubis Oméga", "t": "Noctali a évolué suite à une longue exposition aux rayons lunaires. Il se cache dans les recoins sombres et attend patiemment le passage de ses ennemis. Les anneaux sur son corps s’illuminent au moment où il bondit."}, {"g": "Soleil", "t": "Quand il s’énerve, ses pores sécrètent une sueur empoisonnée qu’il envoie dans les yeux de ses ennemis."}, {"g": "Lune", "t": "Son pelage noir lui permet de se fondre dans la nuit. Il attend que sa proie baisse sa garde pour l’attaquer en visant la gorge."}, {"g": "Ultra-Soleil", "t": "Les larges pupilles de ce Pokémon nocturne lui permettent de distinguer parfaitement ses proies même dans l’obscurité la plus profonde."}, {"g": "Ultra-Lune", "t": "Il se cache dans la pénombre pour chasser. Les anneaux sur son corps brillent d’une aura lugubre quand il passe à l’attaque."}, {"g": "Épée", "t": "Quand il s’énerve, ses pores sécrètent une sueur empoisonnée qu’il projette dans les yeux de ses ennemis."}, {"g": "Bouclier", "t": "Les nuits de pleine lune, ou s’il est agité, les anneaux sur sa peau se mettent à briller."}],
  198: [{"g": "Noir", "t": "Quand il est en danger, il tente de semer ses poursuivants dans les chemins montagneux."}, {"g": "X", "t": "Il vole tous les objets brillants qu’il voit. Les Cornèbre et les Miaouss se volent mutuellement."}, {"g": "Y", "t": "Craint et peu aimé, il paraît qu’il porte malheur à ceux qui croisent son chemin la nuit."}, {"g": "Rubis Oméga", "t": "Jadis, Cornèbre était craint et détesté, car on disait qu’il portait malheur. Ce Pokémon est attiré par tout ce qui brille. Parfois, il essaie de voler les bagues des filles."}, {"g": "Soleil", "t": "Il s’éveille au crépuscule et prend son envol à la nuit tombée. Un proverbe local conseille de rentrer chez soi avant l’envol du Cornèbre."}, {"g": "Lune", "t": "Les gens voient en lui un oiseau de malheur, mais il offre des choses brillantes aux Dresseurs dont il devient l’ami."}, {"g": "Ultra-Soleil", "t": "Il est fasciné par tout ce qui brille. Son obsession pour les trésors est telle qu’il va jusqu’à fouiller les nids des Carmache."}, {"g": "Ultra-Lune", "t": "Il cherche des objets brillants pour son chef. Sa réputation d’oiseau de mauvais augure lui vaut la haine de nombreuses personnes."}],
  199: [{"g": "Noir", "t": "La morsure de Kokiyas a fait de lui un génie dont l’intelligence rivalise avec celle d’un prix Nobel."}, {"g": "X", "t": "D’une grande intelligence, il sait rester calme, même en situation stressante."}, {"g": "Y", "t": "Une fois sa tête mordue, des toxines ont envahi Ramoloss et lui ont conféré des pouvoirs immenses."}, {"g": "Rubis Oméga", "t": "Tous les jours, Roigada entreprend des recherches pour résoudre les mystères du monde. Cependant, ce Pokémon oublie tout ce qu’il a appris si le Kokiyas qui se trouve sur sa tête s’en va."}, {"g": "Soleil", "t": "Les toxines injectées dans son corps quand il s’est fait mordre ont fait de lui un génie. Ses pouvoirs psy ont été grandement amplifiés."}, {"g": "Lune", "t": "Il est tellement intelligent qu’il existe un proverbe dans certaines régions qui dit : « Si tu ne sais pas, demande au Roigada. »"}, {"g": "Ultra-Soleil", "t": "Il trouve tout le temps des idées formidables qui pourraient changer le monde, mais il les oublie dans la foulée."}, {"g": "Ultra-Lune", "t": "On l’appelle « le Grand Sage des mers ». Ses fréquents concours d’intelligence avec Gouroutan se terminent souvent par une égalité."}, {"g": "Épée", "t": "Les toxines du Kokiyas ont imprégné le cerveau du Ramoloss, réveillant en lui une intelligence insoupçonnée, comme par miracle."}, {"g": "Bouclier", "t": "Il est capable de résoudre tous les problèmes qu’on lui présente, mais personne ne parvient à comprendre ce qu’il dit."}],
  200: [{"g": "Noir", "t": "Il fait peur aux aventuriers en pleine nuit et se nourrit de leur frayeur."}, {"g": "X", "t": "Il se nourrit de la peur absorbée par ses orbes rouges. Il somnole à l’ombre en journée."}, {"g": "Y", "t": "Il pousse des hurlements la nuit pour effrayer les gens."}, {"g": "Rubis Oméga", "t": "Feuforêve effraie les gens en poussant un cri à faire froid dans le dos, une sorte de lamentation. Ce Pokémon utilise ses sphères rouges pour absorber les sentiments de terreur de ses ennemis et s’en nourrir."}, {"g": "Soleil", "t": "Il ne recule devant rien pour effrayer les humains et leur voler leur énergie vitale. Pour cela, il s’entraîne régulièrement à faire peur."}, {"g": "Lune", "t": "Si vous entendez des pleurs provenant d’une pièce vide, c’est sûrement un Feuforêve qui vous fait une farce."}, {"g": "Ultra-Soleil", "t": "Effrayer les gens est sa raison d’être. Si l’on presse l’oreille contre les sphères rouges de son cou, on peut entendre des gémissements."}, {"g": "Ultra-Lune", "t": "Il adore faire peur aux humains en imitant leurs pleurs, et n’apprécie guère ceux qui ne se laissent pas intimider."}],
  201: [{"g": "Noir", "t": "Quand il est seul, il ne se passe rien... Mais en groupe, il semble habité par un mystérieux pouvoir."}, {"g": "X", "t": "Son corps plat et fin est toujours collé aux murs. On pense que sa forme a une signification."}, {"g": "Y", "t": "Il rappelle une écriture ancienne. Reste à savoir qui du langage ou de Zarbi est apparu en premier."}, {"g": "Rubis Oméga", "t": "Ce Pokémon a la forme d’un caractère d’écriture antique. Personne ne sait si ces écritures antiques sont apparues avant les Zarbi ou le contraire. Des études sont en cours, mais aucun résultat n’a été annoncé."}],
  202: [{"g": "Noir", "t": "Il cherche désespérément à cacher sa queue noire. Certains pensent qu’elle renferme un secret."}, {"g": "X", "t": "Il déteste la lumière et les chocs. S’il est attaqué, il se gonflera pour riposter violemment."}, {"g": "Y", "t": "Pour cacher sa queue noire, il vit discrètement dans l’obscurité. Il n’attaque jamais le premier."}, {"g": "Rubis Oméga", "t": "Si un ou plusieurs Qulbutoké se rencontrent, ils se mesurent les uns aux autres et font des concours d’endurance. Parfois, ils tentent de voir qui peut rester le plus longtemps sans manger. Mieux vaut être prévenu."}, {"g": "Saphir Alpha", "t": "Qulbutoké ne fait rien, à part encaisser des coups. Il n’attaque jamais de lui-même. Cependant, il ne supporte pas qu’on attaque sa queue. Lorsque ça arrive, ce Pokémon essaie d’entraîner son ennemi grâce à Prélèvem. Destin."}, {"g": "Épée", "t": "Il déteste la lumière et les chocs. S’il est attaqué, il se gonfle pour riposter violemment."}, {"g": "Bouclier", "t": "Il vit discrètement dans l’obscurité pour cacher sa queue noire. Il n’attaque jamais en premier."}],
  203: [{"g": "Noir", "t": "La tête qu’il a sur la queue dispose de son propre cerveau et lui permet de couvrir ses arrières."}, {"g": "X", "t": "La tête sur sa queue monte la garde quand il dort. Elle n’a pas besoin de dormir."}, {"g": "Y", "t": "Sa queue possède un cerveau. Si vous vous en approchez, elle vous sentira et vous mordra."}, {"g": "Rubis Oméga", "t": "La tête à l’arrière de Girafarig a aussi un cerveau, mais il est plus petit. Elle attaque en réponse aux sons et aux odeurs. Si on approche de ce Pokémon par derrière, cette petite tête peut tout à coup jaillir et mordre."}, {"g": "Saphir Alpha", "t": "La tête à l’arrière de Girafarig abrite un cerveau trop petit pour penser. En revanche, cette tête arrière n’a pas besoin de dormir, ce qui lui permet de monter la garde tout le temps."}],
  204: [{"g": "Noir", "t": "Il ressemble à une pomme de pin. Sa carapace le protège des Pokémon Oiseaux qui le picorent par erreur."}, {"g": "X", "t": "Il renforce sa carapace en y ajoutant des écorces d’arbre. Il devient alors plus lourd."}, {"g": "Rubis Oméga", "t": "Pomdepik s’accroche à une branche d’arbre et attend patiemment que sa proie passe. Si ce Pokémon est dérangé pendant qu’il mange par quelqu’un qui secoue son arbre, il tombe au sol et explose sans prévenir."}, {"g": "Ultra-Soleil", "t": "Accroché à sa branche, il attend patiemment ses proies favorites : les Pokémon Insecte. Les Bombydou sont son péché mignon."}, {"g": "Ultra-Lune", "t": "Il grandit en utilisant sa salive pour coller l’écorce des arbres sur son corps. Un Pomdepik âgé peut prendre des proportions démesurées."}],
  205: [{"g": "Noir", "t": "Il est prisonnier d’une coquille d’acier. Ses yeux vigilants sont la seule partie visible de son corps."}, {"g": "Y", "t": "Il est totalement fixé à son arbre. Il lance des morceaux de sa carapace pour faire fuir son ennemi."}, {"g": "Rubis Oméga", "t": "Foretress se cache dans sa carapace en acier trempé. La carapace s’ouvre quand il attrape sa proie, mais cela se passe tellement vite qu’il est impossible de voir à l’intérieur."}, {"g": "Ultra-Soleil", "t": "Il attaque tout ce qui s’approche d’un peu trop près en lançant des morceaux de sa coquille d’acier. Il n’a aucun contrôle sur ce réflexe."}, {"g": "Ultra-Lune", "t": "On ne peut voir l’intérieur de sa carapace que lorsqu’il engloutit sa nourriture, mais il est si rapide que personne n’a encore jamais réussi."}],
  206: [{"g": "Noir", "t": "Son nid est un véritable labyrinthe qu’il creuse à l’aide de sa queue. Il sait à peine voler."}, {"g": "X", "t": "Il s’enfuit en creusant à reculons dans le sol avec sa queue dès qu’un ennemi le repère."}, {"g": "Rubis Oméga", "t": "Insolourdo a une perceuse au bout de la queue. Il l’utilise pour creuser des souterrains, à reculons. On dit que ce Pokémon enfouit son nid aux formes complexes sous terre."}, {"g": "Ultra-Soleil", "t": "Il se déplace en creusant dans le sol et partage les tunnels ainsi créés avec les Taupiqueur. Ces Pokémon s’entendent très bien."}, {"g": "Ultra-Lune", "t": "Quand il aperçoit la silhouette d’un humain, il s’enfuit en creusant un trou avec sa queue. Quiconque en voit un peut s’estimer chanceux !"}, {"g": "Épée", "t": "Des savants affirment que ses petites ailes sont la preuve qu’il y a fort longtemps, il était capable de voler."}, {"g": "Bouclier", "t": "Bien que son nid ressemble à un labyrinthe, il ne s’y perd jamais, car il se repère grâce à l’odeur de la terre."}],
  207: [{"g": "Noir", "t": "Il fend l’air et fond sur sa proie pour s’agripper à son visage et la frapper avec son dard."}, {"g": "X", "t": "Il s’accroche souvent aux falaises. Sa proie repérée, il plane vers elle pour l’attaquer."}, {"g": "Y", "t": "Il vole droit vers le visage de sa cible effrayée et s’y accroche pour lui injecter son poison."}, {"g": "Rubis Oméga", "t": "Scorplane plane dans les airs sans un bruit, comme s’il glissait. Ce Pokémon s’accroche au visage de son ennemi grâce aux serres de ses pattes arrière et aux pinces de ses pattes avant, et pique avec son dard empoisonné."}],
  208: [{"g": "Noir", "t": "On pense que son corps s’est transformé à cause du fer contenu dans la terre dont il se nourrit."}, {"g": "X", "t": "Grâce à la température élevée et à la haute pression souterraines, son corps est plus dur que le métal."}, {"g": "Y", "t": "Ses mâchoires robustes peuvent broyer la pierre. Ses yeux percent la pénombre souterraine."}, {"g": "Rubis Oméga", "t": "Steelix vit sous terre, encore plus profondément qu’Onix. On dit que ce Pokémon creuse vers le centre de la planète. On a déjà vu ce Pokémon descendre à plus d’un kilomètre de profondeur."}, {"g": "Épée", "t": "On raconte qu’il s’agit d’un Onix de plus de 100 ans dont la structure corporelle s’est rapprochée de celle du diamant."}, {"g": "Bouclier", "t": "On pense que son corps s’est transformé à force d’avaler le fer contenu dans la terre en creusant."}],
  209: [{"g": "Noir", "t": "Son visage horrible fait fuir les petits Pokémon. Par contre, les femmes le trouvent mignon."}, {"g": "X", "t": "Il est d’une nature joviale. De nombreuses femmes l’apprécient pour sa gentillesse."}, {"g": "Rubis Oméga", "t": "Snubbull terrorise les Pokémon plus petits que lui en montrant les dents et en faisant une grimace. Cependant, ce Pokémon est toujours un peu triste de voir ses ennemis prendre la fuite."}, {"g": "Soleil", "t": "Malgré sa mine renfrognée, il est en réalité plutôt craintif. Son visage faussement intimidant fait craquer les gens."}, {"g": "Lune", "t": "Lorsqu’il n’aboie pas pour effrayer ses adversaires, ce Pokémon aime se la couler douce et dort 12 h par jour."}, {"g": "Ultra-Soleil", "t": "Il s’attache très facilement et aime être cajolé. Une telle sensibilité cachée derrière une mine renfrognée fait fondre beaucoup de jeunes gens."}, {"g": "Ultra-Lune", "t": "Malgré les apparences, c’est un grand timide qui fait souvent l’objet de railleries quand il se trouve au milieu d’un groupe de Pokémon Chiot."}],
  210: [{"g": "Noir", "t": "En dépit des apparences, c’est un grand timide. Quand il s’énerve, il mord de ses énormes crocs."}, {"g": "Y", "t": "Il peut faire fuir presque tous les Pokémon en ouvrant très largement sa mâchoire."}, {"g": "Rubis Oméga", "t": "Granbull a une mâchoire inférieure particulièrement développée. Ses énormes crocs sont tellement lourds qu’ils l’obligent à pencher la tête. Il ne mord jamais sans raison, sauf quand il a peur."}, {"g": "Soleil", "t": "Sa mâchoire inférieure et ses crocs surdimensionnés sont ses armes de prédilection. Il ne mord pas tant qu’on ne l’énerve pas."}, {"g": "Lune", "t": "Encore plus peureux que Snubbull, son apparence ô combien trompeuse lui vaut un succès fou."}, {"g": "Ultra-Soleil", "t": "Sa mâchoire est étonnamment puissante, mais comme il n’aime pas se battre, il n’a pas souvent l’occasion de s’en servir."}, {"g": "Ultra-Lune", "t": "Les jeunes gens en sont fous, mais sa timidité et sa grande délicatesse en font un piètre Pokémon de garde."}],
  211: [{"g": "Noir", "t": "Il envoie ses piquants empoisonnés à la ronde. Sa forme sphérique en fait un piètre nageur."}, {"g": "X", "t": "Pour tirer ses dards empoisonnés, il gonfle son corps en buvant 10 l d’eau subitement."}, {"g": "Y", "t": "Son corps est recouvert de pics provenant de ses écailles. Ils sécrètent un poison étourdissant."}, {"g": "Rubis Oméga", "t": "Qwilfish se gonfle en aspirant de l’eau. Ce Pokémon utilise la pression de l’eau avalée pour envoyer d’un coup les pointes toxiques de son corps. Nager lui demande un gros effort."}, {"g": "Épée", "t": "Lorsqu’il est confronté à plus gros que lui, il avale autant d’eau que possible pour égaler le gabarit de son adversaire."}, {"g": "Bouclier", "t": "Ses petites épines étaient autrefois des écailles. Elles sécrètent des toxines pouvant faire perdre connaissance."}],
  212: [{"g": "Noir", "t": "Les yeux sur ses pinces servent à intimider l’ennemi avant de passer à l’attaque."}, {"g": "X", "t": "Les pinces de ce Pokémon contiennent de l’acier et peuvent réduire en miettes quasiment n’importe quoi."}, {"g": "Y", "t": "Son corps est dur comme l’acier. Il intimide ses ennemis en levant ses pinces pareilles à des yeux."}, {"g": "Rubis Oméga", "t": "Le corps de Cizayox est dur comme de l’acier. Les attaques ordinaires ne le déstabilisent pas. Ce Pokémon bat des ailes pour réguler sa température interne."}, {"g": "Soleil", "t": "Il utilise ses ailes pour réguler sa température corporelle, ce qui empêche sa carcasse d’acier de fondre en cas d’ardent combat."}, {"g": "Lune", "t": "Avec ses puissantes pinces d’acier, ce Pokémon implacable s’acharne sur tout ce qu’il considère comme un ennemi jusqu’à le briser."}, {"g": "Ultra-Soleil", "t": "Son corps est aussi solide que l’acier. Ses pinces, grosses et lourdes, sont plus adaptées au broyage qu’à la capture d’ennemis."}, {"g": "Ultra-Lune", "t": "Il utilise ses énormes pinces dures comme de l’acier pour réduire en miettes ceux qu’il identifie comme des ennemis."}, {"g": "Épée", "t": "Ses grandes pinces représentent un tiers de son poids. Un seul coup de l’une d’entre elles peut réduire un rocher en poussière."}, {"g": "Bouclier", "t": "Malgré son corps fin, sa puissance de frappe est prodigieuse, car même ses muscles sont composés de métal."}],
  213: [{"g": "Noir", "t": "Il stocke des Baies sous sa carapace. Elles fermentent et produisent des jus délicieux."}, {"g": "X", "t": "Sa carapace, creuse comme une jarre, lui sert à stocker des Baies jusqu’à ce qu’elles se transforment en un jus épais et parfumé."}, {"g": "Y", "t": "Il garde des Baies dans sa coquille. Pour éviter les attaques, il s’immobilise sous un rocher."}, {"g": "Rubis Oméga", "t": "Caratroc se cache tranquillement sous les rochers, abritant son corps dans sa carapace solide, pendant qu’il mange les Baies qu’il a mises de côté. Les Baies se mélangent à ses fluides corporels pour produire du jus."}, {"g": "Épée", "t": "Il garde des Baies dans sa carapace. Pour éviter de se faire attaquer, il s’immobilise sous un rocher."}, {"g": "Bouclier", "t": "Les Baies qu’il conserve dans sa carapace en forme d’urne se changent en jus onctueux après un certain temps."}],
  214: [{"g": "Noir", "t": "Il défend vaillamment sa réserve de miel personnelle à grand renfort de coups de corne."}, {"g": "X", "t": "Ce Pokémon est si puissant qu’il peut projeter ses ennemis en l’air grâce à ses cornes."}, {"g": "Y", "t": "Sa force herculéenne lui permet de soulever et de jeter plus de 100 fois son poids."}, {"g": "Rubis Oméga", "t": "Scarhino charge ses ennemis en ligne droite, se glisse dessous, les attrape et les projette violemment d’un coup de sa puissante corne. Ce Pokémon est tellement fort qu’il pourrait déraciner un arbre."}, {"g": "Saphir Alpha", "t": "Scarhino est doté de griffes acérées sur ses pieds. Elles se plantent fermement dans le sol ou dans l’écorce d’un arbre, ce qui permet à ce Pokémon d’être bien stable lorsqu’il veut projeter ses ennemis d’un coup de corne."}, {"g": "Ultra-Soleil", "t": "Il est très fier de sa grosse corne. Il se chamaille souvent avec Lucanon, son plus grand rival."}, {"g": "Ultra-Lune", "t": "Il parcourt les forêts à la recherche de miel. Il est très fier de sa force colossale, mais sa capacité à voler laisse quelque peu à désirer."}, {"g": "Épée", "t": "Il raffole de la sève sucrée dont il détecte le parfum à l’aide de ses deux antennes lorsqu’il parcourt la forêt."}, {"g": "Bouclier", "t": "Ce Pokémon est fier de sa force colossale qui lui permet de soulever cent fois son propre poids avec facilité."}],
  215: [{"g": "Noir", "t": "Ce Pokémon rusé agit parfois en équipe pour voler des œufs, l’un d’entre eux faisant diversion."}, {"g": "X", "t": "Il se nourrit d’œufs volés dans des nids. Ses griffes crochues percent les défenses de l’ennemi."}, {"g": "Y", "t": "Ses griffes sont cachées dans ses pattes. S’il est attaqué, il les sort pour frapper ses ennemis."}, {"g": "Rubis Oméga", "t": "Farfuret grimpe aux arbres en enfonçant ses griffes crochues dans l’écorce. Ce Pokémon cherche les nids qui ne sont pas surveillés et vole les œufs pour les manger pendant que les parents sont partis."}, {"g": "Soleil", "t": "Un Pokémon aussi roublard que fourbe. Il se glisse dans le nid des autres Pokémon en leur absence pour leur dérober leurs œufs."}, {"g": "Lune", "t": "Avec ses griffes, il perce un trou dans les œufs qu’il trouve pour en sucer le contenu. Bête noire des Éleveurs qui le traquent parfois."}, {"g": "Ultra-Soleil", "t": "Il fait équipe avec ses congénères pour voler les œufs des Pokémon oiseaux, mais ils se font la guerre pour décider de qui les mangera."}, {"g": "Ultra-Lune", "t": "Ce chasseur nocturne profite de l’obscurité pour s’attaquer aux Sabelette, mais il se casse parfois les griffes sur leur peau très dure."}, {"g": "Épée", "t": "Ses griffes acérées sont cachées dans ses doigts. S’il se fait attaquer, il les sort pour effrayer son agresseur."}, {"g": "Bouclier", "t": "Un Pokémon aussi cruel que fourbe. Il se glisse dans le nid des autres Pokémon en leur absence pour dérober leurs Œufs."}],
  216: [{"g": "Noir", "t": "Il baigne ses griffes dans le miel pour les lécher. Chaque paire de pattes a un goût unique."}, {"g": "X", "t": "Sa marque en forme de lune brille quand il trouve du miel. Il lèche ses pattes qui en sont toujours couvertes."}, {"g": "Y", "t": "Il se fait des réserves de nourriture dans des cachettes avant l’arrivée de l’hiver."}, {"g": "Rubis Oméga", "t": "Ce Pokémon aime se lécher les paumes quand elles sont encore pleines de miel. Teddiursa concocte son propre miel en mélangeant les fruits et le pollen ramassés par Dardargnan."}, {"g": "Saphir Alpha", "t": "Ce Pokémon aime se lécher les paumes quand elles sont encore pleines de miel. Teddiursa concocte son propre miel en mélangeant les fruits et le pollen récolté par Dardargnan."}],
  217: [{"g": "Noir", "t": "Il marque de ses griffes les arbres de son territoire qui portent des Baies ou des fruits."}, {"g": "X", "t": "Avec sa capacité à sentir toute odeur, il trouve sans faillir de la nourriture enfouie dans le sol."}, {"g": "Y", "t": "Bien que d’une large corpulence, il grimpe aux arbres pour s’y nourrir et y dormir."}, {"g": "Rubis Oméga", "t": "On dit que les Ursaring trouvent leur nourriture dans les cours d’eau et les grands arbres des forêts où ils habitent. Ce Pokémon erre dans la forêt toute la journée pour chercher de la nourriture."}],
  218: [{"g": "Noir", "t": "Son corps est fait de magma. S’il cesse de bouger, il refroidit et durcit."}, {"g": "X", "t": "Commun dans les régions volcaniques, il se déplace sans cesse pour trouver des endroits chauds."}, {"g": "Rubis Oméga", "t": "Du magma en fusion coule dans les veines de Limagma. Si ce Pokémon est refroidi, le magma se solidifie. Son corps devient alors cassant et des morceaux s’en détachent, diminuant ainsi sa taille."}, {"g": "Saphir Alpha", "t": "Les veines de Limagma ne contiennent pas de sang. Au lieu de ça, du magma en fusion circule dans le corps de ce Pokémon, apportant les nutriments et l’oxygène nécessaires à ses organes."}],
  219: [{"g": "Noir", "t": "Sa température corporelle avoisine les 10 000 °C. Des flammes fusent des fissures de sa coquille."}, {"g": "X", "t": "Sa coquille, très fragile, projette régulièrement des flammes qui circulent dans son corps."}, {"g": "Y", "t": "Son corps en ébullition est aussi chaud que de la lave. Des flammes sortent de sa coquille."}, {"g": "Rubis Oméga", "t": "La carapace de Volcaropod est en fait constituée de sa peau, qui s’est durcie après un refroidissement. Elle est très cassante et fragile. Il suffit de la toucher pour qu’elle casse. Il reprend sa forme en plongeant dans le magma."}, {"g": "Saphir Alpha", "t": "La température de Volcaropod est d’environ 10 000 °C. L’eau s’évapore à son contact. Si ce Pokémon se retrouve sous la pluie, les gouttes d’eau forment de la vapeur et couvrent la zone de brouillard."}],
  220: [{"g": "Noir", "t": "Son nez très sensible détecte champignons, Baies et sources chaudes enfouis sous la glace."}, {"g": "X", "t": "Il renifle le sol avec sa truffe pour y dénicher de la nourriture. Il trouve parfois des sources thermales."}, {"g": "Y", "t": "S’il sent une odeur attirante, il fonce tête baissée pour en trouver l’origine."}, {"g": "Rubis Oméga", "t": "Marcacrin cherche sa nourriture en frottant son groin par terre. Son plat préféré est un champignon qui pousse sous l’herbe fanée. Ce Pokémon découvre parfois des sources d’eau chaude."}, {"g": "Épée", "t": "Il creuse le sol avec son groin pour y dénicher de la nourriture. Il trouve parfois des sources d’eau chaude."}, {"g": "Bouclier", "t": "S’il sent une odeur attrayante, il fonce la tête la première pour trouver d’où elle vient."}],
  221: [{"g": "Noir", "t": "Il est protégé du froid mordant par son épais manteau de fourrure. Ses cornes sont formées de glace."}, {"g": "X", "t": "Bien que pourvu de courtes pattes, ses sabots sont pointus pour l’empêcher de glisser sur la glace."}, {"g": "Y", "t": "Ses yeux sont masqués par ses longs poils. Il ne voit rien et se déplace en chargeant."}, {"g": "Rubis Oméga", "t": "Cochignon est recouvert de longs poils épais qui lui permettent de supporter le froid hivernal. Ce Pokémon utilise ses défenses pour déterrer la nourriture cachée sous la glace."}, {"g": "Épée", "t": "S’il charge un ennemi, les poils de son dos se dressent. Il est très sensible au bruit."}, {"g": "Bouclier", "t": "Bien qu’il soit pourvu de pattes courtes, ses sabots larges et pointus l’empêchent de glisser sur la glace."}],
  222: [{"g": "Épée", "t": "Ses branches repoussent si elles sont brisées. Les plus belles sont offertes aux futures mamans comme porte-bonheurs."}, {"g": "Noir", "t": "On en trouve beaucoup dans les mers claires du sud. On dirait qu’il ne peut pas vivre en eau polluée."}, {"g": "X", "t": "Il grandit en permanence. Les exquises excroissances de sa tête sont très recherchées."}, {"g": "Y", "t": "On le trouve souvent dans les mers claires du sud. L’eau polluée décolore son corail et le fait dépérir."}, {"g": "Rubis Oméga", "t": "Les branches de Corayon brillent de sept couleurs quand elles sont exposées à la lumière du soleil. Si une des branches casse, ce Pokémon peut la faire repousser en une nuit."}, {"g": "Saphir Alpha", "t": "Les Corayon se rassemblent dans les mers chaudes, offrant ainsi un abri idéal aux plus petits Pokémon. Quand la température baisse, ce Pokémon migre vers les mers du sud."}, {"g": "Soleil", "t": "Des cornes de corail poussent sur la tête de ce Pokémon. Elles sont assez fragiles, mais repoussent en trois jours seulement."}, {"g": "Lune", "t": "Lorsqu’il est poursuivi par des Vorastérie attirés par les cornes sur sa tête, il les détache de lui-même pour faire diversion et détaler."}, {"g": "Ultra-Soleil", "t": "Les nutriments présents dans les eaux riches d’Alola ont donné à Corayon cette couleur rose si vive et chatoyante."}, {"g": "Ultra-Lune", "t": "À cause de la prolifération de Vorastérie, son prédateur naturel, le Corayon d’Alola a souvent les cornes courtes."}, {"g": "Bouclier", "t": "Ces Pokémon habitués des mers chaudes se trouvaient autrefois en masse sur les côtes de Galar."}],
  223: [{"g": "Noir", "t": "Son puissant jet d’eau ne manque jamais sa cible, même quand il est au fond de l’eau."}, {"g": "X", "t": "Il est très précis quand il crache ses jets d’eau. Il peut toucher une cible mouvante à 100 m."}, {"g": "Y", "t": "Se servant de sa nageoire dorsale, il s’accroche sous un Démanta pour récupérer ses restes."}, {"g": "Rubis Oméga", "t": "Rémoraid aspire de l’eau, puis la recrache à forte pression grâce à ses muscles abdominaux pour attaquer les proies volantes. Quand son évolution approche, ce Pokémon descend le courant des rivières."}, {"g": "Ultra-Soleil", "t": "Il se colle à un Démanta et se nourrit de ses restes. Si le Démanta se fait attaquer, il l’accompagne au combat."}, {"g": "Ultra-Lune", "t": "Surnommé « le tireur d’élite de la mer », il est capable de toucher à coup sûr une cible située à 100 m de distance grâce à son Pistolet à O."}, {"g": "Épée", "t": "Son puissant jet d’eau ne manque jamais sa cible, même à 100 m de distance."}, {"g": "Bouclier", "t": "À l’aide de sa nageoire dorsale en forme de ventouse, il s’accroche sous un Démanta pour récupérer ses restes."}],
  224: [{"g": "Noir", "t": "Il adore se cacher dans les fissures de la roche. Il crache parfois de l’encre sur ses proies."}, {"g": "X", "t": "Il adore se cacher dans les fissures et les épaves, d’où il attaque en crachant de l’encre."}, {"g": "Y", "t": "Il capture ses ennemis avec ses tentacules et les écrase ensuite avec sa tête dure comme la pierre."}, {"g": "Rubis Oméga", "t": "Octillery attrape son ennemi avec ses tentacules. Ce Pokémon essaie de l’immobiliser avant de lui asséner le coup final. Si l’ennemi s’avère trop fort, Octillery lui crache de l’encre à la figure et s’échappe."}, {"g": "Ultra-Soleil", "t": "Il projette une encre spéciale quand il s’enfuit. Celle-ci perturbe l’odorat des Pokémon, même de ceux dotés d’un bon flair."}, {"g": "Ultra-Lune", "t": "Il dort dans les cavités rocheuses. L’encre noire qu’il projette sert aussi d’ingrédient de cuisine."}, {"g": "Épée", "t": "Il adore se cacher dans des trous. Il n’hésite pas à s’approprier les trous creusés par d’autres Pokémon pour y dormir."}],
  225: [{"g": "Noir", "t": "Il dépose sa nourriture dans sa queue enroulée. Il l’offre souvent aux gens égarés en montagne."}, {"g": "Y", "t": "Il passe ses journées à transporter de la nourriture. Il l’offre souvent aux gens égarés en montagne."}, {"g": "Rubis Oméga", "t": "Cadoizo transporte sa nourriture dans sa queue. Il y a longtemps, un célèbre explorateur réussit à atteindre le sommet de la plus haute montagne du monde grâce à un de ces Pokémon, qui partagea sa nourriture avec lui."}, {"g": "Soleil", "t": "Il s’agit à l’origine d’un Pokémon venant du froid, mais les Cadoizo se sont acclimatés à la chaleur d’Alola."}, {"g": "Lune", "t": "Ce Pokémon partage facilement son repas avec d’autres Pokémon et humains, ce qui l’oblige constamment à courir après la nourriture."}, {"g": "Ultra-Soleil", "t": "Il partage sa nourriture avec les personnes en difficulté mais, étant omnivore, il peut lui arriver de leur offrir des Pokémon Insecte."}, {"g": "Ultra-Lune", "t": "Il transporte toute sa nourriture dans sa queue. Le Cadoizo qui a la plus grande devient le chef de la volée."}, {"g": "Épée", "t": "Il transporte de la nourriture toute la journée. Ses réserves de vivres auraient sauvé la vie de nombreuses personnes en péril."}, {"g": "Bouclier", "t": "Ce Pokémon partage facilement son repas avec d’autres Pokémon et avec des humains, ce qui l’oblige à constamment courir après la nourriture."}],
  226: [{"g": "Noir", "t": "Il ignore royalement les Rémoraid qui s’accrochent à ses nageoires pour manger les restes qu’il sème."}, {"g": "X", "t": "Il peut planer au-dessus des vagues sur plus de 100 m en prenant son élan dans la mer."}, {"g": "Rubis Oméga", "t": "Les jours de beau temps, on peut voir des bancs de Démanta sauter au-dessus des vagues. Le Rémoraid qui l’accompagne ne dérange pas ce Pokémon."}, {"g": "Ultra-Soleil", "t": "Une carte postale ou un poster d’un Démanta planant gracieusement au-dessus des vagues est un souvenir typique d’Alola."}, {"g": "Ultra-Lune", "t": "Nombreux sont les surfeurs qui ont trouvé leur vocation après être tombés sous le charme de la nage majestueuse d’un Démanta."}, {"g": "Bouclier", "t": "Il nage paisiblement, sans se soucier des Rémoraid qui s’agrippent à lui pour lui voler ses restes."}],
  227: [{"g": "Noir", "t": "Son corps est prisonnier d’une armure dure comme l’acier, mais il vole à plus de 300 km/h."}, {"g": "X", "t": "Comme il fait son nid dans les ronces, ses petits s’endurcissent à force d’être sans cesse éraflés."}, {"g": "Rubis Oméga", "t": "Airmure est entièrement recouvert d’une armure très dure. Ce Pokémon peut voler à plus de 300 km/h. Il peut mettre ses ennemis en pièces grâce à ses ailes tranchantes comme des sabres."}, {"g": "Saphir Alpha", "t": "Les ailes d’acier d’Airmure s’abîment et se cabossent à force de se battre. Une fois par an, les ailes endommagées repoussent complètement, rendant à leurs bords tranchants leur état d’origine."}, {"g": "Soleil", "t": "Ce Pokémon perd ses plumes fines et acérées durant sa croissance. Jadis, les guerriers s’en servaient pour fabriquer des lames."}, {"g": "Lune", "t": "Son plumage d’acier, bien que très résistant, est sujet à la rouille. C’est pourquoi ce Pokémon préférera rester au nid les jours de pluie."}, {"g": "Ultra-Soleil", "t": "Les couteaux fabriqués à partir des plumes de ce Pokémon sont appréciés des plus grands chefs cuisiniers pour leur tranchant acéré."}, {"g": "Ultra-Lune", "t": "Il peut paraître lourd, avec son armure d’acier, mais il est en fait capable de voler à une vitesse de 300 km/h."}, {"g": "Épée", "t": "Ses plumes sont plus tranchantes que des lames. Il se dispute violemment son territoire avec les Corvaillus."}, {"g": "Bouclier", "t": "Ce Pokémon orne souvent les blasons, car les plumes qu’il perd sont utilisées pour forger des épées."}],
  228: [{"g": "Noir", "t": "Il est assez évolué pour chasser en meute et communiquer par des séries de cris modulés."}, {"g": "X", "t": "Il hurle dès l’aube pour délimiter son territoire. On l’entend à des kilomètres à la ronde."}, {"g": "Y", "t": "Pour traquer leur proie, ils se localisent mutuellement avec des aboiements compris par eux seuls."}, {"g": "Rubis Oméga", "t": "Les Malosse chassent en meute organisée. Ils communiquent entre eux grâce à une série de petits cris pour encercler leur proie. L’étonnant travail d’équipe de ces Pokémon est sans comparaison."}, {"g": "Ultra-Soleil", "t": "Ce Pokémon est doué pour le travail en équipe. C’est un compagnon fidèle qui écoute les ordres de son Dresseur sans sourciller."}, {"g": "Ultra-Lune", "t": "Si ses congénères et lui poussent de sinistres hurlements avant l’aube, c’est pour signaler leur présence à tout le monde."}],
  229: [{"g": "Noir", "t": "En colère, il crache des flammes contenant une toxine qui peut causer des dégâts irréversibles."}, {"g": "X", "t": "Jadis, les gens prenaient son étrange hurlement pour l’appel de la Faucheuse."}, {"g": "Rubis Oméga", "t": "Dans une meute de Démolosse, le leader est doté de cornes inclinées vers l’arrière. Ces Pokémon choisissent leur chef en organisant des combats entre eux."}, {"g": "Ultra-Soleil", "t": "Il crache des flammes empoisonnées pour achever ses proies, qu’il partage avec les autres membres de sa meute."}, {"g": "Ultra-Lune", "t": "Ceux qui le craignaient jadis lui ont donné le surnom de « messager de la Faucheuse » à cause de son hurlement sinistre si particulier."}],
  230: [{"g": "Noir", "t": "Chacun de ses déplacements provoque des tourbillons. Il vit dans les grottes sous-marines."}, {"g": "X", "t": "On dit qu’il se cache dans les grottes sous-marines. Il peut créer des tourbillons en bâillant."}, {"g": "Y", "t": "Il emmagasine de l’énergie en restant dans les fonds marins, là où rien d’autre ne peut survivre."}, {"g": "Rubis Oméga", "t": "Hyporoi vit au fin fond des profondeurs océaniques généralement inhabitées. On a longtemps cru que le bâillement de ce Pokémon créait les tourbillons dans les océans."}, {"g": "Saphir Alpha", "t": "Hyporoi dort au fond de l’océan, où aucune autre forme de vie ne réside. On raconte que lorsqu’une tempête survient, c’est que ce Pokémon s’éveille et erre dans les profondeurs en quête de proies."}, {"g": "Épée", "t": "Il apparaît à la surface de l’océan lorsqu’une tempête arrive. Dès qu’il croise un Dracolosse, un combat féroce s’ensuit."}, {"g": "Bouclier", "t": "Les écailles qui se détachent de son corps brillent d’un éclat si élégant et si intense qu’on les offre aux familles royales."}],
  231: [{"g": "Noir", "t": "Il est fort malgré son aspect ramassé. Il n’a aucun mal à porter un humain adulte sur son dos."}, {"g": "X", "t": "Il se cogne sur celui ou celle qu’il apprécie. Il est cependant si fort qu’il fait souvent mal."}, {"g": "Rubis Oméga", "t": "Pour faire son nid, Phanpy creuse un trou au bord d’une rivière. Il délimite la zone autour de son nid avec sa trompe pour prévenir les autres que ce territoire est le sien."}, {"g": "Saphir Alpha", "t": "Phanpy utilise sa petite trompe pour se doucher. Quand plusieurs d’entre eux se réunissent, ils s’arrosent joyeusement. On peut souvent voir ces Pokémon se sécher au bord de l’eau."}],
  232: [{"g": "Noir", "t": "Il attaque en se roulant en boule pour percuter l’ennemi. Il peut abattre une maison d’un seul coup."}, {"g": "X", "t": "Il a des défenses aiguisées et une peau épaisse. Ses charges peuvent détruire une maison."}, {"g": "Y", "t": "Plus grandes sont ses défenses, plus haut est son rang dans le troupeau. Elles poussent lentement."}, {"g": "Rubis Oméga", "t": "L’attaque favorite de Donphan consiste à se mettre en boule et à charger son ennemi en roulant à pleine vitesse. Une fois qu’il commence à rouler, ce Pokémon a du mal à s’arrêter."}, {"g": "Saphir Alpha", "t": "Si Donphan décidait de charger, il pourrait détruire une maison. Grâce à sa force étonnante, ce Pokémon peut aider à déplacer les rochers et les coulées de boue qui bloquent les chemins de montagne."}],
  233: [{"g": "Noir", "t": "Il a subi une mise à jour censée lui permettre d’explorer d’autres planètes... C’est un échec."}, {"g": "X", "t": "Des recherches poussées ont amélioré ses capacités. Il a appris de nouveaux mouvements."}, {"g": "Y", "t": "On lui a installé un logiciel de terraformation pour lui permettre de travailler dans l’espace."}, {"g": "Rubis Oméga", "t": "Porygon2 fut créé par des humains grâce aux progrès de la science. Ce Pokémon a été doté d’une intelligence artificielle qui lui permet d’apprendre de nouveaux mouvements et des émotions par lui-même."}, {"g": "Soleil", "t": "Cette mise à jour de Porygon a été conçue dans le cadre d’un projet de terraformation, grâce aux avancées scientifiques de l’époque."}, {"g": "Lune", "t": "Version évoluée de Porygon, créée dans l’espoir de pouvoir un jour terraformer des planètes, un rêve loin d’être concrétisé pour l’instant."}, {"g": "Ultra-Soleil", "t": "Grâce à son intelligence artificielle, il peut apprendre beaucoup de choses par lui-même, qu’elles soient utiles... ou un peu superflues."}, {"g": "Ultra-Lune", "t": "Bien qu’il puisse survivre dans l’espace, il peine malheureusement à se mouvoir en apesanteur."}, {"g": "Épée", "t": "Fruit de la mise à jour d’un Porygon avec des données spéciales, il peut apprendre et se développer de manière autonome."}, {"g": "Bouclier", "t": "Depuis qu’on l’a doté d’une intelligence artificielle, il parle un langage mystérieux que seuls ses congénères comprennent."}],
  234: [{"g": "Noir", "t": "Quiconque observe ses antennes ressent une sensation étrange, comme si leur centre l’attirait."}, {"g": "X", "t": "Quiconque observe ses bois ressent une sensation étrange, comme si leur centre l’attirait."}, {"g": "Y", "t": "Ses bois tordus changent le flot de l’air et créent une distorsion spatiale dans la réalité."}, {"g": "Rubis Oméga", "t": "Les superbes bois de Cerfrousse étaient vendus très cher comme œuvres d’art. Ce Pokémon fut chassé et l’espèce proche de l’extinction à cause des gens qui recherchaient leurs précieux bois."}],
  235: [{"g": "Noir", "t": "Il marque son territoire en maniant sa queue comme un pinceau. On dénombre plus de 5 000 marques."}, {"g": "Y", "t": "Arrivé à l’âge adulte, il laisse ses camarades poser leur empreinte de patte sur son dos."}, {"g": "Rubis Oméga", "t": "Queulorior délimite son territoire en libérant un fluide corporel qui sort de sa queue. On a découvert plus de 5 000 traces différentes de fluide laissées par ce Pokémon."}, {"g": "Soleil", "t": "Ce Pokémon marque son territoire en peignant à l’aide du liquide suintant du bout de sa queue."}, {"g": "Lune", "t": "Ce Pokémon peint pour marquer son territoire. On reconnaît les villes peuplées de nombreux Queulorior à leurs murs recouverts de graffitis."}, {"g": "Ultra-Soleil", "t": "La teinte du liquide qui coule de sa queue varie en fonction de son humeur."}, {"g": "Ultra-Lune", "t": "Il se sert du liquide qui sort de sa queue pour dessiner sa marque. Ses fans s’arrachent ses plus beaux tracés à prix d’or."}],
  236: [{"g": "Noir", "t": "Il est réputé pour sa combativité. Il se blesse toujours en défiant des ennemis plus grands."}, {"g": "X", "t": "Il est plein d’énergie. Il se bat tout le temps pour être plus fort, quitte à perdre un combat."}, {"g": "Y", "t": "Pour augmenter ses capacités, il cherche à se battre contre n’importe qui. Il est très courageux."}, {"g": "Rubis Oméga", "t": "Debugant devient nerveux s’il ne s’entraîne pas tous les jours. Lorsqu’un Dresseur élève ce Pokémon, il doit établir et appliquer un programme d’entraînement très complet."}, {"g": "Épée", "t": "Ce Pokémon est débordant d’énergie. Même s’il perd encore et encore, il se relève toujours pour devenir plus fort."}, {"g": "Bouclier", "t": "Même s’il est petit, il vaut mieux ne pas l’ignorer : quand il trouve un adversaire à sa hauteur, il frappe fort et souvent sans prévenir."}],
  237: [{"g": "Noir", "t": "Il combat en tournoyant comme une toupie. La force centrifuge décuple sa puissance destructrice."}, {"g": "Y", "t": "Si sa danse de coups de pied vous fascine, vous risquez de le regretter."}, {"g": "Rubis Oméga", "t": "Kapoera tournoie à toute vitesse sur sa tête, tout en donnant des coups de pied. Cette technique combine des attaques offensives et défensives. Ce Pokémon se déplace plus vite sur la tête qu’en marchant."}, {"g": "Épée", "t": "Il assène des coups de pied tout en tournant sur lui-même. Il va parfois si vite qu’il commence à s’enfoncer dans le sol."}, {"g": "Bouclier", "t": "Après avoir effectué un poirier visant à désorienter son adversaire, il lui assène des coups de pied furieux."}],
  238: [{"g": "Noir", "t": "Il goûte à tout du bout des lèvres. Elles gardent en mémoire ses goûts et ses dégoûts."}, {"g": "X", "t": "Ses lèvres sont la partie la plus sensible de son corps. Il les utilise pour examiner les objets."}, {"g": "Rubis Oméga", "t": "Lippouti court dans tous les sens et tombe assez souvent. Quand il en a l’occasion, il regarde son reflet dans l’eau pour vérifier si son visage n’a pas été sali par ses chutes."}, {"g": "Ultra-Soleil", "t": "Avant même de toucher de ses mains un objet qui l’intéresse, il le tâte de ses lèvres. S’il est sale, il le lèche au passage pour le nettoyer."}, {"g": "Ultra-Lune", "t": "Ses lèvres sont des détecteurs hypersensibles. Il les enduit de sève tous les jours pour les garder hydratées et éviter les gerçures."}, {"g": "Épée", "t": "Quand il s’aperçoit que son visage est sale, il le lave à l’eau, mais la propreté du reste de son corps ne semble pas le préoccuper."}, {"g": "Bouclier", "t": "Ce Pokémon très curieux touche tout et n’importe quoi avec ses lèvres pour déterminer ce qu’il aime et ce qu’il déteste."}],
  239: [{"g": "Noir", "t": "Un faible courant électrique circule entre ses cornes. Attention à ne pas y mettre la main!"}, {"g": "X", "t": "Il génère de l’électricité en battant des bras, mais il n’a aucun moyen de stocker cette énergie."}, {"g": "Y", "t": "Ses cornes s’illuminent lorsqu’il fait tourner ses bras pour générer de l’électricité."}, {"g": "Rubis Oméga", "t": "Élekid stocke de l’électricité dans son corps. S’il touche du métal et décharge sans le faire exprès son électricité, ce Pokémon fait des cercles avec ses bras pour se recharger."}, {"g": "Soleil", "t": "Ce Pokémon « tète » les prises électriques des maisons comme s’il s’agissait de biberons de lait, et ce jusqu’au dernier ampère."}, {"g": "Lune", "t": "Togedemaru et lui se disputent les mêmes sources d’électricité. Leurs combats se terminent souvent par une égalité."}, {"g": "Ultra-Soleil", "t": "Il adore le bruit de la foudre. Si vous l’enregistrez, vous pouvez le lui diffuser à loisir pour le mettre de bonne humeur."}, {"g": "Ultra-Lune", "t": "Lorsqu’il est chargé à bloc, ses cornes émettent une lueur bleuâtre. Attention à ne pas les toucher ou vous risquez l’électrocution !"}, {"g": "Épée", "t": "Il ne tient plus en place quand un orage approche. Lorsqu’il entend le tonnerre gronder, il devient tout excité."}, {"g": "Bouclier", "t": "Il a encore du mal à emmagasiner l’électricité. Pour s’en nourrir, il se faufile dans les maisons à la recherche de prises électriques."}],
  240: [{"g": "Noir", "t": "Son sang est chaud comme du magma et la température de son corps peut atteindre 600 °C."}, {"g": "X", "t": "La température de son corps peut atteindre 600 °C. Son nez et sa bouche laissent échapper des flammèches."}, {"g": "Rubis Oméga", "t": "L’état de santé de Magby peut être deviné selon le type de flamme qu’il crache. Si ce Pokémon crache des flammes jaunes, c’est qu’il est en bonne santé. Lorsqu’il est fatigué, de la fumée noire s’ajoute aux flammes."}, {"g": "Soleil", "t": "Ce Pokémon est souvent aperçu dans les régions volcaniques. Donnez-lui à manger et il vous déclarera sa flamme... littéralement."}, {"g": "Lune", "t": "Magby est le partenaire privilégié d’un potier extrêmement célèbre. Sa flamme légère l’aiderait à créer des œuvres d’un raffinement exquis."}, {"g": "Ultra-Soleil", "t": "Lorsque de petites flammes s’échappent de son nez, c’est qu’il est enrhumé. Le meilleur remède est encore de lui donner un bain de lave."}, {"g": "Ultra-Lune", "t": "Sa température corporelle est d’environ 600 °C. S’il tombe dans une mare, celle-ci s’évapore et il n’en reste plus rien."}, {"g": "Épée", "t": "Ce n’est encore qu’un petit Pokémon craintif. Lorsqu’il est excité ou étonné, du feu s’échappe de son nez ou de sa bouche."}, {"g": "Bouclier", "t": "Il vit près des volcans. À la fin de la journée, il se détend dans un bon bain de magma."}],
  241: [{"g": "Noir", "t": "On raconte que les enfants élevés au lait d’Écrémeuh deviennent des adultes braves et robustes."}, {"g": "X", "t": "Si elle vient d’avoir un petit, son lait est bien plus nutritif que d’habitude."}, {"g": "Y", "t": "Son lait est très nutritif. C’est une boisson parfaite pour les malades et les personnes âgées."}, {"g": "Rubis Oméga", "t": "Écrémeuh produit plus de 20 l de lait par jour. Son lait sucré fait le bonheur des petits et des grands. Les gens qui ne boivent pas de lait en font du yaourt."}, {"g": "Soleil", "t": "Son lait est aussi nutritif qu’hypercalorique. À consommer avec modération, sous peine de finir avec une silhouette « Écrémeuh-esque »."}, {"g": "Lune", "t": "Ce Pokémon est surtout élevé pour son lait, bien que sa stature imposante en fasse un Pokémon de combat tout à fait respectable."}, {"g": "Ultra-Soleil", "t": "Les 20 litres de lait qu’il produit chaque jour gagneront en saveur et en caractère s’il vit dans un pâturage de bonne qualité."}, {"g": "Ultra-Lune", "t": "Son lait est délicieux et très nutritif, mais il ne faut pas en abuser pour éviter d’éventuels petits problèmes de digestion."}, {"g": "Épée", "t": "Grâce à son lait très nutritif, Écrémeuh contribue depuis longtemps au bien-être des humains et des Pokémon."}, {"g": "Bouclier", "t": "Sa santé décline si on ne le trait pas tous les jours. Le goût de son lait varie selon la saison."}],
  242: [{"g": "Noir", "t": "Les œufs que pond Leuphorie sont un concentré de bonheur dont une bouchée suffit à apporter la joie."}, {"g": "Y", "t": "Ce Pokémon au cœur d’or soigne les Pokémon malades. Il ressent la tristesse d’autrui."}, {"g": "Rubis Oméga", "t": "Leuphorie ressent la tristesse grâce à son pelage duveteux. Lorsqu’il la remarque, ce Pokémon se précipite vers la personne triste pour partager avec elle un Œuf Chance, capable de faire naître un sourire sur tout visage."}, {"g": "Soleil", "t": "On dit que les œufs de Leuphorie seraient de véritables concentrés de bonheur, capables d’adoucir les Pokémon les plus hargneux."}, {"g": "Lune", "t": "Le pelage de ce Pokémon lui fait office de radar à émotions. Il est ainsi capable de capter les humeurs des Pokémon et humains alentour."}, {"g": "Ultra-Soleil", "t": "Ses œufs sont si bons qu’il suffirait d’en manger un pour trouver le bonheur. Au marché, c’est le produit qui se vend le plus cher."}, {"g": "Ultra-Lune", "t": "Ce Pokémon déborde de compassion. On raconte que seuls les Leveinard ayant ouvert leur cœur à leur Dresseur peuvent évoluer."}, {"g": "Épée", "t": "Lorsqu’il croise un Pokémon affaibli, il partage son œuf avec ce dernier et lui prodigue des soins jusqu’à ce qu’il soit rétabli."}, {"g": "Bouclier", "t": "Il pond d’étranges œufs remplis de bonheur. On raconte que quiconque en mange un devient aimable envers tout le monde."}],
  243: [{"g": "Noir", "t": "On prétend qu’il est tombé avec la foudre. Il peut lancer des éclairs grâce aux nuages sur son dos."}, {"g": "X", "t": "Le nuage de pluie qu’il porte peut relâcher la foudre à volonté. On dit de lui qu’il est venu avec l’orage."}, {"g": "Y", "t": "Ce terrible Pokémon emmagasine de l’énergie puis court en lançant de puissants éclairs."}, {"g": "Rubis Oméga", "t": "Raikou incarne la vitesse de l’éclair. Les rugissements de ce Pokémon libèrent des ondes de choc provenant du ciel et frappant le sol avec la puissance de la foudre."}],
  244: [{"g": "Noir", "t": "On raconte qu’à chaque fois qu’il rugit, un volcan entre en éruption quelque part."}, {"g": "X", "t": "Un Pokémon qui parcourt le monde. On dit qu’il en naît un à chaque fois qu’un volcan apparaît."}, {"g": "Rubis Oméga", "t": "Entei incarne la colère du magma. On pense que ce Pokémon est né suite à l’éruption d’un volcan. Il peut envoyer d’énormes jets de flammes qui calcinent tout ce qu’ils touchent."}],
  245: [{"g": "Noir", "t": "Il parcourt le vaste monde pour purifier les eaux polluées. Il accompagne le vent du nord."}, {"g": "Y", "t": "Il serait la réincarnation du vent du nord. Il peut purifier instantanément les eaux polluées."}, {"g": "Rubis Oméga", "t": "Suicune incarne la tranquillité d’une source d’eau pure. Il parcourt les plaines avec grâce. Ce Pokémon a le pouvoir de purifier l’eau."}],
  246: [{"g": "Noir", "t": "Un Pokémon qui se nourrit de terre. Après avoir dévoré une montagne, il s’endort pour grandir."}, {"g": "X", "t": "Il se nourrit de terre. Une fois qu’il a absorbé une montagne, il s’endort et commence à évoluer."}, {"g": "Y", "t": "Il vit très profond sous terre. Il n’en sort pour évoluer qu’après avoir dévoré tout ce qui l’entourait."}, {"g": "Rubis Oméga", "t": "Embrylex est né sous terre. Pour remonter à la surface, ce Pokémon doit manger la terre au-dessus de lui. Jusqu’à ce qu’il y parvienne, Embrylex ne peut pas voir le visage de ses parents."}, {"g": "Ultra-Soleil", "t": "Il naît sous terre et doit se frayer un chemin à coups de mâchoire pour rejoindre ses parents à la surface. Il déteste la lumière, qui l’éblouit."}, {"g": "Ultra-Lune", "t": "Il se nourrit des nutriments présents dans le sol. Il lui faut dévorer l’équivalent d’une petite montagne pour se changer en chrysalide."}, {"g": "Épée", "t": "Il naît dans les profondeurs du sol. Après avoir englouti toute la terre qui l’entoure, il fait surface et se change en chrysalide."}, {"g": "Bouclier", "t": "Il vit en se nourrissant de terre. Après avoir dévoré une montagne, il s’endort et entame sa croissance."}],
  247: [{"g": "Noir", "t": "Son corps est dur comme la pierre souterraine. Il file comme une fusée en expulsant des gaz."}, {"g": "Y", "t": "Sa carapace est aussi dure que la pierre et il est très fort. Ses coups peuvent raser une montagne."}, {"g": "Rubis Oméga", "t": "Ymphect crée un gaz dans son corps qu’il comprime puissamment pour se propulser, comme un avion à réaction. Son corps est très solide. Il ne l’endommage pas, même lorsqu’il frappe de l’acier trempé."}, {"g": "Ultra-Soleil", "t": "Impatient d’évoluer, il évacue son stress en libérant des gaz sous haute pression qui le font bondir dans tous les sens. Une vraie plaie !"}, {"g": "Ultra-Lune", "t": "Cette chrysalide est très dangereuse. À l’intérieur de cette carapace solide comme le roc, son nouveau corps se développe."}, {"g": "Épée", "t": "Il peut se déplacer même s’il est coincé dans sa coquille. Sa robustesse et sa vitesse lui confèrent un terrible pouvoir de destruction."}, {"g": "Bouclier", "t": "Malgré son état de chrysalide, il ne reste pas immobile. Sous sa solide carapace, ses pattes sortent déjà."}],
  248: [{"g": "Noir", "t": "Lorsqu’il est en colère, il abat des montagnes et enterre des fleuves. On doit alors modifier les cartes."}, {"g": "X", "t": "D’une main seulement il a assez de force pour faire trembler la terre et s’écrouler une montagne."}, {"g": "Rubis Oméga", "t": "Tyranocif est si incroyablement puissant qu’il peut abattre une montagne pour y faire son nid. Ce Pokémon se promène dans les montagnes pour y trouver de nouveaux adversaires."}, {"g": "Ultra-Soleil", "t": "Il parcourt les montagnes à la recherche d’un adversaire. Si ce dernier n’est pas à la hauteur, il préfère l’ignorer et s’en aller."}, {"g": "Ultra-Lune", "t": "Aucun obstacle n’arrête ce Pokémon lorsqu’il se déplace : les montagnes, il les démolit ; les maisons, il les anéantit."}, {"g": "Épée", "t": "Son corps est invulnérable à toutes les attaques, c’est pourquoi il aime tant mettre ses forces à l’épreuve."}, {"g": "Bouclier", "t": "Son pas est si lourd qu’il fait trembler le sol et s’écrouler même les plus grandes montagnes, ce qui altère la topographie de la zone."}],
  249: [{"g": "Noir", "t": "Il dort dans une faille des grands fonds. Ses battements d’ailes génèrent une tempête de 40 jours."}, {"g": "Y", "t": "Il est supposé être le gardien des sept mers. On raconte qu’il est apparu une nuit de forte tempête."}, {"g": "Rubis Oméga", "t": "Les ailes de Lugia renferment une puissance dévastatrice. Un simple battement de ses ailes peut détruire de petites maisons. Du coup, ce Pokémon a choisi de vivre loin de tout, dans les profondeurs océaniques."}],
  250: [{"g": "Noir", "t": "Ses plumes possèdent sept couleurs. On prétend que sa vue apporte la joie éternelle."}, {"g": "X", "t": "Son corps brille des sept couleurs de l’arc-en-ciel, arc-en-ciel qui se constitue derrière lui quand il vole."}, {"g": "Y", "t": "Il ne se montre qu’à un Dresseur au cœur pur en dévoilant ses magnifiques ailes colorées."}, {"g": "Rubis Oméga", "t": "Les plumes de Ho-Oh brillent de sept couleurs selon l’orientation de son corps par rapport à la lumière. On raconte que ces plumes portent bonheur. On dit aussi que ce Pokémon vit au pied d’un arc-en-ciel."}],
  251: [{"g": "Noir", "t": "Il a le pouvoir de voyager dans le temps. Cependant, on dit qu’il n’apparaît qu’en temps de paix."}, {"g": "X", "t": "Ce Pokémon voyage dans le temps. Les forêts où il apparaît deviennent prodigieusement luxuriantes."}, {"g": "Rubis Oméga", "t": "Ce Pokémon est venu du futur en voyageant dans le temps. On raconte que quand Celebi apparaît, cela signifie que le futur sera bon et agréable."}, {"g": "Épée", "t": "Il possède le pouvoir de voyager dans le temps. Il a été considéré comme une divinité sylvestre à différentes époques."}, {"g": "Bouclier", "t": "Ce Pokémon venu du futur soigne les blessures et donne de la force aux plantes."}],
  252: [{"g": "Noir", "t": "Ses plantes de pieds sont couvertes d’épines lui permettant de marcher au mur et au plafond."}, {"g": "X", "t": "Arcko peut grimper aux murs à l’aide de ses pattes. Grâce à sa queue, il est capable de mesurer l’humidité de l’air et de prédire le temps du jour suivant."}, {"g": "Y", "t": "Les épines de ses plantes de pieds lui permettent de marcher aux murs et au plafond sans tomber."}, {"g": "Rubis Oméga", "t": "Arcko est doté de petits crochets sous les pattes, ce qui lui permet de grimper aux murs. Ce Pokémon attaque en frappant ses ennemis avec son épaisse queue."}, {"g": "Saphir Alpha", "t": "Arcko est cool, calme et serein. Il ne panique jamais, quelle que soit la situation. Quand un ennemi plus gros que lui lui lance un regard de défi, ce Pokémon reste stoïque et ne cède pas un centimètre de terrain."}],
  253: [{"g": "Noir", "t": "Il vit dans les jungles denses. Il saute de branche en branche pour approcher de sa proie."}, {"g": "X", "t": "Les muscles surdéveloppés de ses cuisses permettent à Massko de sauter incroyablement haut."}, {"g": "Rubis Oméga", "t": "Les feuilles qui poussent sur le corps de Massko sont bien pratiques lorsqu’il veut se camoufler dans la forêt. Ce Pokémon est passé maître dans l’art de grimper aux arbres."}, {"g": "Saphir Alpha", "t": "Ce Pokémon vole de branche en branche avec brio. En forêt, aucun Pokémon, même le plus rapide, ne peut espérer attraper un Massko qui s’enfuit."}],
  254: [{"g": "Noir", "t": "Les feuilles sur ses bras peuvent trancher des troncs épais. C’est le meilleur combattant des jungles."}, {"g": "Y", "t": "Il parcourt la jungle avec agilité et attaque ses proies grâce aux feuilles tranchantes sur ses bras."}, {"g": "Rubis Oméga", "t": "Les feuilles qui poussent sur le corps de Jungko sont extrêmement tranchantes. Ce Pokémon est très agile. Il bondit de branche en branche avant de sauter sur son ennemi."}, {"g": "Saphir Alpha", "t": "Jungko a des graines qui lui poussent sur le dos. On dit qu’elles regorgent de nutriments qui revitalisent les arbres. Ce Pokémon s’occupe des forêts avec amour."}],
  255: [{"g": "Noir", "t": "Ses câlins réchauffent car il renferme une fournaise. Il envoie des boules de feu à 1 000 °C."}, {"g": "X", "t": "Poussifeu possède, dans son ventre, une poche de feu qui brûle sans arrêt. Il donne une impression de chaleur quand on lui fait des câlins."}, {"g": "Rubis Oméga", "t": "Poussifeu ne lâche pas son Dresseur d’une semelle, marchant maladroitement derrière lui. Ce Pokémon crache des flammes pouvant atteindre 1 000 °C et des boules de feu qui carbonisent l’ennemi."}, {"g": "Saphir Alpha", "t": "Poussifeu dispose d’un endroit dans son corps pour stocker sa flamme. Si on lui fait un gros câlin, sa flamme s’illumine chaleureusement. Ce Pokémon est couvert d’un duvet très doux."}],
  256: [{"g": "Noir", "t": "Ce maître du coup de pied peut donner 10 coups par seconde. Ses cris aigus intimident l’ennemi."}, {"g": "Y", "t": "Au combat, les flammes dans son corps redoublent d’intensité. Ses coups de pied sont dévastateurs."}, {"g": "Rubis Oméga", "t": "Galifeu muscle ses cuisses et ses mollets en courant dans les champs ou dans les montagnes. Les jambes de ce Pokémon sont très puissantes et rapides, capables de donner 10 coups de pied en 1 seconde."}, {"g": "Saphir Alpha", "t": "Galifeu combat grâce aux flammes ardentes qu’il crache de son bec et à ses coups de pied destructeurs. Le cri de ce Pokémon est très puissant et très gênant pour l’adversaire."}],
  257: [{"g": "Noir", "t": "Des flammes fusent de ses poignets et ses coups brûlent l’ennemi."}, {"g": "X", "t": "Il peut bondir par-dessus un bâtiment de 30 étages. Ses poings enflammés brûlent ses adversaires."}, {"g": "Y", "t": "Quand il est face à un ennemi, il laisse s’échapper des gerbes de flammes par ses poignets. Ses jambes lui permettent de sauter par-dessus les immeubles."}, {"g": "Rubis Oméga", "t": "Au combat, Braségali envoie des flammes ardentes de ses poignets. Il fait preuve d’un courage exceptionnel. Plus l’ennemi est puissant, plus les poignets de ce Pokémon sont ardents."}, {"g": "Saphir Alpha", "t": "Braségali a des jambes incroyablement puissantes. Il peut sauter par-dessus un immeuble de trente étages. Les coups de poing enflammés de ce Pokémon peuvent carboniser ses ennemis."}],
  258: [{"g": "Noir", "t": "Il analyse le courant grâce à la nageoire sur sa tête. Il est assez fort pour soulever des rochers."}, {"g": "X", "t": "Sa grande queue en forme de nageoire lui donne une puissance d’accélération incroyable. Il est très costaud malgré sa taille."}, {"g": "Rubis Oméga", "t": "La nageoire sur la tête de Gobou lui sert de radar hypersensible. Il l’utilise pour sentir les mouvements de l’eau et de l’air. Ainsi, ce Pokémon peut savoir ce qui se passe autour de lui sans avoir à se servir de ses yeux."}, {"g": "Saphir Alpha", "t": "Sous l’eau, Gobou peut respirer grâce aux branchies sur ses joues. S’il se retrouve en difficulté pendant un combat, ce Pokémon déchaîne ses pouvoirs incroyables. Il peut détruire des rochers plus gros que lui."}],
  259: [{"g": "Noir", "t": "Ses jambes robustes lui donnent un bon appui, même dans la boue. Il dort enfoui dans la saleté."}, {"g": "Y", "t": "À force de marcher et de vivre dans la boue, son arrière-train est devenu particulièrement robuste."}, {"g": "Rubis Oméga", "t": "Le corps de Flobio est enveloppé par un film fin et collant qui lui permet de vivre hors de l’eau. Ce Pokémon joue dans la vase sur les plages lorsque la marée est basse."}, {"g": "Saphir Alpha", "t": "Flobio est bien plus rapide dans la boue que dans l’eau. L’arrière-train de ce Pokémon est particulièrement développé, ce qui lui donne la capacité de marcher sur ses pattes arrière."}],
  260: [{"g": "Noir", "t": "Il peut traîner un grand bateau en nageant. Il assomme l’ennemi d’un grand coup de ses bras épais."}, {"g": "X", "t": "Un seul coup de ses puissants bras suffit pour pulvériser même les plus gros rochers."}, {"g": "Rubis Oméga", "t": "Laggron est très fort. Tellement fort qu’il peut aisément tirer un rocher pesant plus d’une tonne. Ce Pokémon est également doté d’une vue si efficace qu’il peut même voir à travers l’eau trouble."}, {"g": "Saphir Alpha", "t": "Laggron peut prédire l’arrivée des tempêtes en utilisant ses nageoires pour sentir les variations dans les vagues et les marées. Si une tempête s’approche, il empile des rochers pour protéger son habitat."}],
  261: [{"g": "Noir", "t": "Un Pokémon très obstiné qui poursuit sa proie jusqu’à ce qu’elle soit épuisée."}, {"g": "Y", "t": "Medhyèna est d’un tempérament tenace. Son odorat très développé lui permet de ne jamais perdre la trace de sa proie."}, {"g": "Rubis Oméga", "t": "Sans se poser de questions, Medhyèna essaie de mordre tout ce qui bouge. Ce Pokémon pourchasse sa proie jusqu’à ce qu’elle s’épuise. Cependant, il se peut qu’il prenne peur et s’enfuie si la proie riposte."}, {"g": "Saphir Alpha", "t": "Medhyèna est omnivore. Il mange de tout. Ses crocs sont très gros, comparés à son corps. Ce Pokémon essaie d’intimider ses ennemis en hérissant les poils de sa queue."}],
  262: [{"g": "Y", "t": "Les Grahyèna forment des meutes de dix qui excellent au travail de groupe pour capturer leurs proies."}, {"g": "Noir", "t": "Il traque ses proies en groupe. Il ne désobéira jamais aux ordres d’un bon Dresseur."}, {"g": "X", "t": "Il obéit toujours aux ordres de son Dresseur si celui-ci est très doué. Son comportement vient de l’époque reculée où il vivait en meute."}, {"g": "Rubis Oméga", "t": "On peut facilement deviner quand Grahyèna se prépare à attaquer. Il grogne et se met à plat ventre. Ce Pokémon mord sauvagement ses ennemis avec ses crocs acérés."}, {"g": "Saphir Alpha", "t": "Les Grahyèna vivent et se déplacent en meute. Leurs réminiscences de la vie sauvage les poussent à n’obéir qu’aux Dresseurs qu’ils considèrent comme réellement talentueux."}],
  263: [{"g": "Noir", "t": "Il marche en zigzaguant et n’a pas son pareil pour trouver des objets dans l’herbe ou sous terre."}, {"g": "Y", "t": "Un Pokémon d’une curiosité insatiable. Il montre de l’intérêt pour tout ce qui l’entoure et passe d’un endroit à un autre en zigzaguant pour tout regarder."}, {"g": "Rubis Oméga", "t": "Zigzaton se promène nerveusement un peu partout. En effet, ce Pokémon est très curieux. Tout ce qu’il voit l’intéresse."}, {"g": "Saphir Alpha", "t": "Les poils sur le dos de Zigzaton sont durs. Il frotte son dos contre les arbres pour marquer son territoire. Ce Pokémon fait parfois le mort pour tromper ses ennemis au combat."}, {"g": "Épée", "t": "Il frotte son pelage dur sur les arbres pour marquer son territoire. Il est plus docile que son cousin de Galar."}, {"g": "Bouclier", "t": "Le Zigzaton de Galar a adopté cette forme dans les autres régions. Il est très doué pour dénicher des choses."}],
  264: [{"g": "Noir", "t": "Il fonce sur sa proie à plus de 100 km/h. Mais il ne peut pas dévier sa course et loupe souvent sa cible."}, {"g": "X", "t": "Il peut courir en ligne droite à plus de 100 km/h. Hélas, il n’est pas doué pour prendre les virages."}, {"g": "Rubis Oméga", "t": "Linéon court très vite et toujours en ligne droite. Si un obstacle survient, il l’évite en prenant un angle droit. Ce Pokémon a beaucoup de mal à suivre les routes légèrement courbées."}, {"g": "Saphir Alpha", "t": "Lorsqu’il chasse, Linéon fonce toujours tout droit sur sa proie à pleine vitesse. Bien que ce Pokémon puisse atteindre 100 km/h, il doit s’arrêter en catastrophe avant de pouvoir tourner."}, {"g": "Épée", "t": "Son pelage est à la fois solide et flexible. Les blaireaux conçus à partir des poils de sa mue sont des produits de très grand luxe."}, {"g": "Bouclier", "t": "Il se sert de sa force de propulsion et de ses griffes aiguisées pour achever ses proies. Il a du mal à courir sur les routes sinueuses."}],
  265: [{"g": "Noir", "t": "Cible favorite des Pokémon Oiseaux, il tente de se protéger avec ses épines venimeuses."}, {"g": "X", "t": "Il adore manger des feuilles. Si un Étourmi l’attaque, il riposte avec les piquants de son postérieur."}, {"g": "Y", "t": "Il habite les forêts et les hautes herbes. Attaqué, il riposte avec les piquants de son postérieur."}, {"g": "Rubis Oméga", "t": "À l’aide de ses pointes arrière, Chenipotte déchire l’écorce des arbres et mange la sève qui coule dessus. Les pattes de ce Pokémon sont dotées de coussinets à ventouses pour adhérer aux parois en verre sans en glisser."}, {"g": "Saphir Alpha", "t": "Chenipotte est la proie de Hélédelle. Ce Pokémon essaie de résister en dirigeant les pointes de son dos vers le prédateur. Il affaiblit son ennemi en lui injectant du poison."}],
  266: [{"g": "Noir", "t": "Il attend d’évoluer dans son cocon de soie accroché aux branches et se nourrit d’eau de pluie."}, {"g": "Y", "t": "Il boit la rosée récoltée par sa soie en attendant d’évoluer. Il est à l’abri dans son robuste cocon."}, {"g": "Rubis Oméga", "t": "Armulys s’accroche à une branche d’arbre avec de la soie pour éviter de tomber. Ce Pokémon y reste tranquillement en attendant son évolution. Il regarde l’extérieur à travers deux petits trous dans son cocon de soie."}, {"g": "Saphir Alpha", "t": "On pensait qu’Armulys pouvait résister à la faim et ne consommait rien avant son évolution. On sait maintenant que ce Pokémon étanche sa soif en récupérant l’eau de pluie déposée sur sa soie."}],
  267: [{"g": "Noir", "t": "Malgré les apparences, il est très agressif et attaque avec sa trompe quand on le dérange."}, {"g": "X", "t": "Réputé pour les motifs de ses ailes aux couleurs vives. Il allonge sa trompe pour butiner le nectar."}, {"g": "Y", "t": "Il est très agressif. Il pique sa proie avec son long museau étroit et absorbe sa vitalité."}, {"g": "Rubis Oméga", "t": "La nourriture préférée de Charmillon est le pollen sucré des fleurs. Si on veut voir ce Pokémon, il suffit de laisser une fleur en pot sur un rebord de fenêtre. Charmillon viendra sûrement voir s’il y a du pollen."}, {"g": "Saphir Alpha", "t": "Charmillon a une longue trompe en spirale, particulièrement pratique pour récupérer le pollen des fleurs. Ce Pokémon se laisse porter par les vents printaniers pendant qu’il butine."}],
  268: [{"g": "Noir", "t": "Rancunier, il n’oublie aucune des attaques subies dans le cocon et se venge une fois qu’il a évolué."}, {"g": "X", "t": "Son corps, constitué de soie fine, durcit avec le temps. Si vous voyez apparaître des fissures, c’est qu’il va très bientôt évoluer."}, {"g": "Rubis Oméga", "t": "Blindalys fabrique son cocon protecteur en s’enveloppant dans la soie qui sort de sa bouche. Une fois la soie autour de son corps, elle se met à durcir. Ce Pokémon prépare son évolution à l’intérieur du cocon."}, {"g": "Saphir Alpha", "t": "Lorsqu’il est attaqué, Blindalys reste immobile, même s’il a très mal. En effet, s’il bougeait, son corps serait affaibli lors de son évolution. En revanche, ce Pokémon n’oubliera pas la douleur endurée."}],
  269: [{"g": "Noir", "t": "Il disperse un nuage de poudre toxique à chaque coup d’aile. Il aime les feuilles d’arbres urbains."}, {"g": "X", "t": "Ce Pokémon nocturne est attiré par les lueurs de la ville et aime les feuilles des arbres urbains."}, {"g": "Y", "t": "Quand on l’attaque, il bat des ailes pour répandre sa poudre toxique. Il sort après le coucher du soleil."}, {"g": "Rubis Oméga", "t": "Papinox est instinctivement attiré par la lumière. Des nuées de ce Pokémon sont attirées par les réverbères des villes, où il sème la pagaille en grignotant les feuilles des arbres en bordure de route."}, {"g": "Saphir Alpha", "t": "Lorsque Papinox bat des ailes, une légère poussière se répand. Cette poussière est en fait un puissant poison capable de mettre au tapis un boxeur professionnel. Ce Pokémon cherche sa nourriture avec ses antennes, comme un radar."}],
  270: [{"g": "Noir", "t": "Il ressemble à une plante aquatique et fait la navette pour les Pokémon qui ne savent pas nager."}, {"g": "Y", "t": "Nénupiot recherche toujours les coins où coule de l’eau pure. S’il reste longtemps sans boire, la feuille sur sa tête commence à faner."}, {"g": "Rubis Oméga", "t": "Nénupiot vit dans les étangs et les lacs, sur lesquels il flotte à la surface. Si sa feuille tombe, il est affaibli. De temps en temps, ce Pokémon sort sur la terre ferme à la recherche d’eau propre."}, {"g": "Saphir Alpha", "t": "On raconte que jadis, Nénupiot vivait sur terre. Mais on pense que ce Pokémon est retourné dans l’eau car la feuille sur sa tête était devenue trop grande et trop lourde. Maintenant, il vit en flottant à la surface de l’eau."}, {"g": "Épée", "t": "Il recherche toujours les endroits où coule de l’eau pure. S’il reste longtemps sans boire, la feuille sur sa tête commence à faner."}, {"g": "Bouclier", "t": "Sa feuille est devenue si grande et si lourde qu’il doit vivre en flottant sur l’eau."}],
  271: [{"g": "Noir", "t": "C’est un mauvais plaisantin. Quand il repère un pêcheur, il tire sur sa ligne pour le déranger."}, {"g": "X", "t": "Il vit au bord de l’eau dans les endroits ensoleillés. Le jour, il s’endort sur un tas d’algues et ne se lève qu’à la nuit tombée."}, {"g": "Rubis Oméga", "t": "Lombre est nocturne, il commence ses activités malicieuses et sournoises au crépuscule. Lorsque ce Pokémon repère des pêcheurs, il s’approche de leur ligne, tire dessus et se moque de leur regard perplexe."}, {"g": "Saphir Alpha", "t": "Le corps de Lombre tout entier est recouvert d’un voile visqueux et glissant. Toucher ce Pokémon est extrêmement déplaisant. On croit souvent à tort que Lombre est un enfant."}, {"g": "Épée", "t": "Ce Pokémon nocturne s’active au crépuscule. Il se nourrit d’algues qui poussent au fond des rivières."}, {"g": "Bouclier", "t": "Il vit au bord de l’eau dans les endroits ensoleillés. Il s’endort sur un tas d’algues dans la journée et ne se lève qu’à la nuit tombée."}],
  272: [{"g": "Noir", "t": "Ses muscles se tonifient au son d’une musique entraînante. Il ne peut pas s’empêcher de danser."}, {"g": "Y", "t": "Les cellules de Ludicolo s’activent s’il entend une musique entraînante, le rendant encore plus puissant."}, {"g": "Rubis Oméga", "t": "Ludicolo ne peut pas s’empêcher de danser quand il entend une musique joyeuse et festive. On raconte que ce Pokémon apparaît lorsqu’il entend les enfants chanter pendant leurs randonnées."}, {"g": "Saphir Alpha", "t": "Lorsque Ludicolo entend un rythme entraînant et joyeux, les cellules de son corps s’activent énergiquement. Même pendant les combats, ce Pokémon montre énormément d’énergie."}, {"g": "Bouclier", "t": "Il bouge son corps sur un rythme entraînant pour décupler ses forces."}],
  273: [{"g": "Noir", "t": "Il ressemble à un gland pendu à une branche. Il adore effrayer les autres Pokémon."}, {"g": "X", "t": "Il se suspend aux branches par l’extrémité de sa tête. Il arrive qu’il tombe s’il est pris de panique."}, {"g": "Rubis Oméga", "t": "Grainipiot s’accroche par la tête aux branches d’arbre. Il en profite alors pour absorber l’humidité de l’arbre. Plus ce Pokémon boit d’eau, plus son corps devient brillant."}, {"g": "Saphir Alpha", "t": "Grainipiot ressemble à s’y méprendre à un gland quand il s’accroche à une branche. Il effraie les autres Pokémon quand il se met à bouger. Ce Pokémon se lustre le corps une fois par jour avec des feuilles."}, {"g": "Épée", "t": "S’il reste immobile, il a l’air d’une Baie. Il adore surprendre les Pokémon qui tentent de le picorer."}, {"g": "Bouclier", "t": "Il se suspend aux branches par l’extrémité de sa tête. Il arrive qu’une bourrasque le fasse tomber."}],
  274: [{"g": "Noir", "t": "Le son de sa flûte d’herbe déstabilise l’auditeur. Il vit au plus profond des forêts."}, {"g": "Y", "t": "Il vit au plus profond des forêts. Le son de sa flûte, faite avec la feuille de sa tête, est inquiétant."}, {"g": "Rubis Oméga", "t": "Les Pifeuil vivent dans des forêts très densément boisées. Il leur arrive de sortir de la forêt pour faire peur aux gens. Ce Pokémon déteste qu’on lui pince son grand nez."}, {"g": "Saphir Alpha", "t": "Ce Pokémon se sert de la feuille sur sa tête pour jouer de la flûte. Le son de la flûte de Pifeuil effraie et décontenance les gens perdus en forêt."}, {"g": "Épée", "t": "Il vit au plus profond des forêts. Sa flûte faite avec la feuille de sa tête émet un son inquiétant."}, {"g": "Bouclier", "t": "Il vit dans les trous des grands arbres. Le sifflement qu’il produit avec sa feuille suffit à remplir ses adversaires d’effroi."}],
  275: [{"g": "Noir", "t": "D’un coup de sa feuille éventail, il génère des bourrasques de 30 m/s capables de souffler une maison."}, {"g": "X", "t": "Ce Pokémon est le gardien des forêts. Il peut lire les pensées de ses ennemis et agir en conséquence."}, {"g": "Rubis Oméga", "t": "Tengalice est un mystérieux Pokémon vivant dans les cimes d’immenses arbres, vieux de plus de mille ans. Il peut créer de formidables tempêtes grâce à ses éventails."}, {"g": "Saphir Alpha", "t": "Les grands éventails de Tengalice peuvent déclencher des bourrasques de vent allant jusqu’à 30 m/s. Le vent déchaîné peut tout envoyer balader. Ce Pokémon a choisi de vivre tranquillement dans la forêt."}, {"g": "Épée", "t": "Ce gardien des forêts inspirait la crainte. Il peut lire les pensées de ses ennemis et agir en conséquence."}, {"g": "Bouclier", "t": "Il vit caché au fond des forêts. On raconte qu’il fait souffler la bise lorsqu’il agite ses grands éventails."}],
  276: [{"g": "Noir", "t": "Ce Pokémon téméraire n’a pas peur d’affronter des ennemis puissants. Il vole en quête de climats chauds."}, {"g": "Y", "t": "Nirondelle ne supporte pas les saisons froides. Il vole vers d’autres terres à la recherche de chaleur et peut ainsi parcourir 300 km par jour."}, {"g": "Rubis Oméga", "t": "Nirondelle défend courageusement son territoire contre ses ennemis, même les plus puissants. Ce vaillant Pokémon est toujours prêt à relever un défi, mais s’il a faim, il se met à pleurer à chaudes larmes."}, {"g": "Saphir Alpha", "t": "Nirondelle est jeune. Il vient de quitter son nid. Du coup, il se sent parfois un peu seul et pleure la nuit. Ce Pokémon se nourrit des Chenipotte qu’il trouve dans les forêts."}],
  277: [{"g": "Noir", "t": "Il vole en cercle en quête d’une proie. Dès qu’il l’a repérée, il fond sur elle en un éclair."}, {"g": "X", "t": "Si les plumes de ses deux queues restent bien droites, cela signifie qu’Hélédelle est en bonne santé. Son élégance est sans pareille."}, {"g": "Y", "t": "Une fois sa proie repérée, il fond sur elle en un éclair et la capture avec ses griffes acérées."}, {"g": "Rubis Oméga", "t": "Hélédelle vole dans les cieux en dessinant de grands arcs. Ce Pokémon plonge en piqué dès qu’il repère sa proie. Il attrape fermement la malheureuse cible dans ses serres, empêchant toute fuite."}, {"g": "Saphir Alpha", "t": "Hélédelle fait attention à bien entretenir ses ailes brillantes. Lorsque deux Hélédelle se rencontrent, ils se nettoient mutuellement les ailes avec attention."}],
  278: [{"g": "Noir", "t": "Il utilise les courants ascendants pour planer en altitude. Son bec lui sert à transporter la nourriture."}, {"g": "X", "t": "Il plane sur les vents marins grâce à ses longues ailes. Il les replie pour se reposer."}, {"g": "Y", "t": "Il niche sur les falaises escarpées face à la mer. Il vole en altitude grâce aux courants ascendants."}, {"g": "Rubis Oméga", "t": "Goélise a l’habitude de transporter ses proies et ses objets de valeur dans son bec avant de les cacher. Ce Pokémon se laisse porter par le vent et vole comme s’il surfait dans les cieux."}, {"g": "Saphir Alpha", "t": "Grâce à ses ailes longues et étroites, Goélise se laisse porter par les courants d’air ascendants venant de la mer. Le long bec de ce Pokémon est bien pratique pour attraper ses proies."}, {"g": "Soleil", "t": "Son ossature légère lui confère un vol gracieux, tandis que le vent s’engouffre sous ses grandes ailes, lui permettant de s’élever au firmament."}, {"g": "Lune", "t": "Les Goélise survolent les mers qui grouillent de Pokémon poissons. Un grand pêcheur a dit : « Si tu veux une bonne prise, suis le Goélise. »"}, {"g": "Ultra-Soleil", "t": "Grâce à ses ailes longues et fines, il se laisse porter par les courants ascendants pour planer jusqu’au firmament."}, {"g": "Ultra-Lune", "t": "Il fait son nid sur les falaises du littoral et survole la mer en cercle à la recherche de son mets favori : les petits Froussardine."}, {"g": "Épée", "t": "Il construit son nid le long des falaises et utilise les courants ascendants pour planer en altitude."}, {"g": "Bouclier", "t": "Il niche dans les falaises. En utilisant les courants d’air, il peut voler sans battre des ailes."}],
  279: [{"g": "Noir", "t": "Ce messager du ciel transporte petits Pokémon et œufs dans son bec en toute sécurité."}, {"g": "X", "t": "Il trempe son grand bec dans la mer pour charrier de l’eau et de nombreuses proies."}, {"g": "Y", "t": "Ce messager du ciel transporte petits Pokémon et Œufs dans son bec en toute sécurité."}, {"g": "Rubis Oméga", "t": "Bekipan est un transporteur volant chargeant des petits Pokémon et des œufs dans son énorme bec. Ce Pokémon construit son nid sur les falaises, face à la mer."}, {"g": "Saphir Alpha", "t": "Bekipan récupère sa nourriture en vol, en rasant l’écume des vagues. Ce Pokémon trempe son énorme bec dans l’eau, puis avale tout en une bouchée."}, {"g": "Soleil", "t": "Le bec de ce Pokémon est énorme, tellement énorme qu’un petit enfant pourrait grimper dedans et s’y cacher sans problème."}, {"g": "Lune", "t": "Les Bekipan mâles ramènent la nourriture, qu’ils transportent dans leur énorme bec jusqu’au nid où les attendent leurs congénères."}, {"g": "Ultra-Soleil", "t": "Il se sert de son énorme bec pour transporter de petits Pokémon, mais nul ne sait où il les emporte..."}, {"g": "Ultra-Lune", "t": "Il pêche les Froussardine à l’aide de son large bec et les avale d’un trait. Il peut en ingurgiter jusqu’à trente d’un coup."}, {"g": "Épée", "t": "Ce messager du ciel transporte les petits Pokémon et les Œufs dans son bec pour les conduire en lieu sûr."}, {"g": "Bouclier", "t": "Avec son grand bec, il transporte de la nourriture qu’il a récoltée en volant la bouche ouverte au ras de la mer, gobant de l’eau au passage."}],
  280: [{"g": "Noir", "t": "Quand ses cornes captent les ondes positives d’un Pokémon ou d’un humain, son corps se réchauffe."}, {"g": "Y", "t": "Il est très sensible aux émotions des gens et des Pokémon. Il se cache au moindre signe d’hostilité."}, {"g": "Rubis Oméga", "t": "Tarsal ressent les émotions des gens grâce à ses cornes. Ce Pokémon se montre rarement, mais il arrive qu’il s’approche d’une personne s’il la sent dans un état d’esprit positif."}, {"g": "Saphir Alpha", "t": "Tarsal a le pouvoir de ressentir les émotions des gens. Si son Dresseur est d’humeur joyeuse, ce Pokémon devient lui aussi gai et enjoué."}, {"g": "Bouclier", "t": "Quand ses cornes rouges captent les ondes positives d’un Pokémon ou d’un humain, tout son corps se réchauffe."}],
  281: [{"g": "Noir", "t": "Quand il sent la joie de son Dresseur, il se met à danser, débordant d’énergie."}, {"g": "X", "t": "Ce Pokémon tire ses pouvoirs psy du soutien de son Dresseur. Il danse et tourne sur lui-même quand il est content."}, {"g": "Y", "t": "Il peut distordre l’espace-temps grâce à ses pouvoirs psy et ainsi voir l’avenir."}, {"g": "Rubis Oméga", "t": "On dit qu’un Kirlia exposé aux émotions positives de son Dresseur devient très beau. Le cerveau surdéveloppé de ce Pokémon lui permet de contrôler les forces télékinétiques."}, {"g": "Saphir Alpha", "t": "Kirlia utilise ses cornes pour amplifier ses pouvoirs télékinétiques. Lorsque ce Pokémon utilise son pouvoir, l’air ambiant se déforme et crée des mirages de paysages qui n’existent pas."}, {"g": "Épée", "t": "Quand il ressent la joie de son Dresseur, il déborde d’énergie et se met à danser en tournant sur lui-même."}, {"g": "Bouclier", "t": "Il peut distordre l’espace-temps grâce à ses pouvoirs psychiques et ainsi voir l’avenir."}],
  282: [{"g": "Noir", "t": "Prêt à tout pour protéger son Dresseur, il peut créer un mini trou noir par sa seule force mentale."}, {"g": "Y", "t": "Gardevoir est capable de prédire l’avenir. Sa puissance augmente quand il protège son Dresseur."}, {"g": "Rubis Oméga", "t": "Gardevoir a le pouvoir de prédire l’avenir. On raconte que lorsqu’il sent que son Dresseur est en danger, il libère une puissante décharge d’énergie télékinétique."}, {"g": "Saphir Alpha", "t": "Gardevoir est doté d’un pouvoir télékinétique lui permettant de déformer les dimensions et de créer un petit trou noir. Ce Pokémon est prêt à risquer sa vie pour protéger son Dresseur."}, {"g": "Épée", "t": "Gardevoir est capable de prédire l’avenir. Il déploie toute sa puissance quand il doit protéger son Dresseur."}, {"g": "Bouclier", "t": "Prêt à tout pour protéger son Dresseur, il peut aller jusqu’à épuiser sa force mentale pour créer un mini trou noir."}],
  283: [{"g": "Noir", "t": "Il semble patiner sur l’eau. Le parfum diffusé par le sommet de sa tête sert à attirer ses proies."}, {"g": "X", "t": "Ils vivent généralement dans les étangs mais, après des averses passagères, on peut en trouver dans des flaques au milieu des villes."}, {"g": "Rubis Oméga", "t": "Du bout de ses pattes, Arakdo sécrète une huile lui permettant de marcher sur l’eau, comme s’il glissait. Ce Pokémon se nourrit des organismes microscopiques présents dans les lacs et les étangs."}, {"g": "Saphir Alpha", "t": "Lorsque Arakdo se sent en danger, le haut de sa tête sécrète un sirop épais et sucré. Certains Pokémon adorent boire de ce sirop."}, {"g": "Soleil", "t": "Ce Pokémon se déplace en glissant à la surface de l’eau. Les Arakdo se chamaillent souvent avec les Araqua pour de la nourriture."}, {"g": "Lune", "t": "Dès qu’il se sent en danger, le sommet de sa tête sécrète un liquide sucré, qui a le don de provoquer le dégoût chez les Pokémon oiseaux."}, {"g": "Ultra-Soleil", "t": "En cas de danger, il sécrète un liquide sucré du sommet de sa tête. Le sirop fabriqué à partir de ce liquide est délicieux étalé sur du pain !"}, {"g": "Ultra-Lune", "t": "Il vit dans les lacs ou les marais où prospèrent les plantes hydrophiles. Il se dispute souvent proies et territoire avec son voisin, Araqua."}],
  284: [{"g": "Noir", "t": "Des motifs en forme d’yeux ornent ses antennes. Ses 4 ailes l’aident à voler dans toutes les directions."}, {"g": "X", "t": "Des motifs en forme d’yeux ornent ses antennes. Ses quatre ailes l’aident à voler dans toutes les directions."}, {"g": "Y", "t": "Ses quatre ailes permettent à ce Pokémon de voler dans toutes les directions."}, {"g": "Rubis Oméga", "t": "Maskadra intimide ses ennemis grâce aux motifs en forme de regard sur ses antennes. En battant des ailes, ce Pokémon peut voler librement dans toutes les directions, même latéralement ou à reculons."}, {"g": "Saphir Alpha", "t": "Les antennes de Maskadra ont la forme de grands yeux qui lancent un regard malfaisant. Si ces « yeux » sont tristes, cela signifie qu’un déluge se prépare."}, {"g": "Soleil", "t": "Ses antennes semblables à des yeux servent à intimider ses ennemis, et ses quatre ailes lui permettent de voler dans toutes les directions."}, {"g": "Lune", "t": "Ses ailes et ses antennes tolèrent mal l’humidité. En cas de pluie, ce Pokémon se réfugie là où le soleil brille pour y faire sécher son corps."}, {"g": "Ultra-Soleil", "t": "Ses protubérances en forme d’yeux servent à intimider ses ennemis. Si cela ne marche pas, il utilise ses quatre ailes pour s’enfuir."}, {"g": "Ultra-Lune", "t": "Ses antennes en forme d’ailes absorbent facilement l’humidité. Par temps de pluie, il attend patiemment au creux d’un arbre."}],
  285: [{"g": "Noir", "t": "Le sommet de sa tête libère des spores empoisonnées. Il est dangereux de les inhaler."}, {"g": "X", "t": "Il préfère les endroits humides. La journée, il reste à la lisière de la forêt. Il libère de la poudre toxique par sa tête."}, {"g": "Rubis Oméga", "t": "Les Balignon vivent dans les sols humides et les recoins sombres des grandes forêts. On les trouve souvent immobiles sous les feuilles mortes. Ce Pokémon se nourrit d’un compost fait de feuilles mortes pourries."}, {"g": "Saphir Alpha", "t": "Lorsque Balignon sent un danger, il secoue son corps et répand ses spores du haut de sa tête. Les spores de ce Pokémon sont si toxiques qu’elles font dépérir les arbres et les herbes."}],
  286: [{"g": "Noir", "t": "Ses petits bras s’étendent quand il donne un coup de poing. Son talent égale celui d’un boxeur pro."}, {"g": "Y", "t": "Il frappe de toutes ses forces ses ennemis étourdis par ses spores empoisonnées."}, {"g": "Rubis Oméga", "t": "Chapignon se rapproche de son ennemi en se servant de son jeu de jambes, puis donne des coups de poing avec ses bras élastiques. La technique de combat de ce Pokémon est digne des meilleurs boxeurs."}, {"g": "Saphir Alpha", "t": "Les graines autour de la queue de Chapignon sont des spores toxiques. Elles sont totalement immangeables. Une simple bouchée d’une graine de ce Pokémon peut causer de grandes douleurs à l’estomac."}],
  287: [{"g": "Noir", "t": "Il passe le plus clair de son temps affalé. Rien qu’à le voir, on a envie de bâiller."}, {"g": "X", "t": "Rien qu’à voir un Parecool, on n’a plus envie de bouger et on s’endort."}, {"g": "Y", "t": "Il dort 20 heures par jour et ne fait rien d’autre, si ce n’est manger trois ou quatre feuilles dans la journée."}, {"g": "Rubis Oméga", "t": "Parecool se prélasse plus de vingt heures par jour. Il bouge tellement peu qu’il n’a presque pas besoin de manger. Le repas quotidien de ce Pokémon n’est constitué que de trois feuilles."}, {"g": "Saphir Alpha", "t": "Le cœur de Parecool ne bat qu’une fois par minute. Quoi qu’il arrive, il se contente de s’avachir, immobile. Il est très rare de voir ce Pokémon se déplacer."}],
  288: [{"g": "Noir", "t": "Son cœur bat dix fois plus vite que la normale, c’est pourquoi il ne tient pas en place."}, {"g": "X", "t": "Son cœur bat tellement vite que son sang bout dans ses veines, l’empêchant de rester immobile même une seconde."}, {"g": "Y", "t": "Quand il ne bouge pas, il accumule du stress et devient très irritable."}, {"g": "Rubis Oméga", "t": "Vigoroth est toujours impatient de se défouler. Il ne supporte pas l’idée de rester sans rien faire, même une minute. Le niveau de stress de ce Pokémon augmente énormément s’il ne peut pas bouger."}, {"g": "Saphir Alpha", "t": "Vigoroth ne tient pas en place. Même quand il essaie de dormir, le sang dans ses veines s’agite, obligeant ce Pokémon à courir comme un fou dans la forêt pour s’épuiser afin de pouvoir se reposer."}],
  289: [{"g": "Noir", "t": "Le Pokémon le plus fainéant du monde. Il s’allonge pour économiser ses forces et contre-attaquer."}, {"g": "X", "t": "Le Pokémon le plus fainéant du monde. Il bouge quand il a mangé tout ce qui était à portée de main."}, {"g": "Y", "t": "C’est le Pokémon le plus paresseux du monde. Il est cependant capable de libérer une puissance phénoménale en une seule attaque."}, {"g": "Rubis Oméga", "t": "Monaflèmit passe toute sa journée allongé à paresser. Il mange toute l’herbe qu’il trouve à portée de main. Ensuite, il change d’endroit, à contrecœur."}, {"g": "Saphir Alpha", "t": "On trouve parfois des cercles de plus de 1 m de rayon totalement désherbés dans les plaines. Ils sont faits par les Monaflèmit qui passent leurs journées allongés à manger toute l’herbe à portée de main."}],
  290: [{"g": "Noir", "t": "Il grandit sous terre et se repère grâce à ses antennes car ses yeux sont quasiment aveugles."}, {"g": "X", "t": "Comme il vit presque toujours sous terre, sa vue est très peu développée et il est presque aveugle. Il utilise ses antennes pour se repérer."}, {"g": "Y", "t": "Il peut passer jusqu’à dix ans sous terre. Les racines des arbres constituent son régime alimentaire."}, {"g": "Rubis Oméga", "t": "Ningale vit depuis des années sous terre, dans l’obscurité la plus totale. Ce Pokémon absorbe les nutriments des racines des arbres. Il reste immobile, attendant patiemment son évolution."}, {"g": "Saphir Alpha", "t": "Ningale vit sous terre. Il utilise ses griffes acérées pour creuser les racines des arbres et en absorber l’humidité et les nutriments. Ce Pokémon ne supporte pas la lumière du soleil."}, {"g": "Épée", "t": "Parce qu’il a longtemps vécu sous terre, il est presque aveugle et utilise ses antennes pour se repérer."}, {"g": "Bouclier", "t": "Il peut passer plus de dix ans sous terre. Les racines des arbres constituent son régime alimentaire."}],
  291: [{"g": "Noir", "t": "Il bouge si vite que l’œil a parfois du mal à le suivre. Ils se regroupent près de la sève des arbres."}, {"g": "X", "t": "C’est la migraine assurée quand il pousse son cri perçant. On le perd facilement de vue tant il est vif."}, {"g": "Y", "t": "Il bouge si vite que l’œil a parfois du mal à le suivre. Les Pokémon de cette espèce se regroupent près de la sève des arbres."}, {"g": "Rubis Oméga", "t": "Ninjask se déplace tellement vite qu’il est impossible de le voir. En revanche, on entend clairement son cri. On a pendant très longtemps cru que ce Pokémon était invisible."}, {"g": "Saphir Alpha", "t": "Si Ninjask n’est pas dressé correctement, il refuse d’obéir à son Dresseur et crie sans arrêt. C’est pourquoi on dit que ce Pokémon peut réellement mettre son Dresseur à l’épreuve."}, {"g": "Épée", "t": "Une écoute prolongée de son cri provoque des maux de tête persistants. On le perd facilement de vue tant il est vif."}, {"g": "Bouclier", "t": "Ce Pokémon est tellement rapide qu’on le dit capable d’éviter toutes les attaques. Il adore se nourrir de la sève sucrée des arbres."}],
  292: [{"g": "Noir", "t": "Une carapace d’insecte laissée à l’abandon. On dit qu’il vole l’âme de celui qui regarde à l’intérieur."}, {"g": "Y", "t": "Un Pokémon étrange que l’on trouve dans les Poké Balls après l’évolution d’un Ningale."}, {"g": "Rubis Oméga", "t": "Le corps robuste de Munja ne bouge pas d’un pouce. En fait, son corps semble être une coquille vide. Certains croient que ce Pokémon peut voler l’âme de quiconque regarderait à l’intérieur de son corps creux."}, {"g": "Saphir Alpha", "t": "Munja est un étrange Pokémon. Il semble apparaître sans raison dans une Poké Ball après l’évolution d’un Ningale. Ce Pokémon bizarre est totalement immobile. Il ne respire même pas."}, {"g": "Épée", "t": "Un Pokémon étrange que l’on trouve dans une Poké Ball après l’évolution d’un Ningale."}, {"g": "Bouclier", "t": "Cet étrange Pokémon, dont le corps est comme une coquille vide, ne respire pas et peut voler sans battre des ailes."}],
  293: [{"g": "Noir", "t": "En temps normal, son cri est pareil à un murmure. Effrayé, il atteint le volume d’un avion à réaction."}, {"g": "X", "t": "Il communique en murmurant, mais se met à hurler s’il sent le moindre danger. Il s’arrête quand on lui bouche les oreilles."}, {"g": "Y", "t": "Il repousse ses ennemis grâce à un cri aussi puissant que le bruit d’un avion à réaction."}, {"g": "Rubis Oméga", "t": "Généralement, la voix de Chuchmur est très douce, à peine audible, même si on tend l’oreille. Pourtant, lorsque ce Pokémon sent l’approche du danger, il se met à crier si fort qu’il peut déchirer des tympans."}, {"g": "Saphir Alpha", "t": "Chuchmur est très timide. S’il commence à pleurer, il s’effraie tout seul et pleure de plus belle. Quand ce Pokémon finit enfin de pleurer, il s’endort, épuisé."}, {"g": "Épée", "t": "Le cri qu’il émet dépasse les 100 décibels et donne une migraine qui dure toute la journée à quiconque se trouve à proximité."}, {"g": "Bouclier", "t": "Quand il se met à crier, il se surprend lui-même et hurle de plus belle. Il continue ainsi jusqu’à ce qu’il se fatigue et tombe de sommeil."}],
  294: [{"g": "Noir", "t": "L’onde de choc provoquée par son cri peut renverser un camion. Il trépigne pour augmenter sa force."}, {"g": "X", "t": "Grâce à ses puissants muscles abdominaux, il peut crier en expulsant l’air qu’il avait aspiré."}, {"g": "Rubis Oméga", "t": "Le hurlement de Ramboum est si fort qu’il peut faire s’effondrer une petite maison en bois. Il se sert de sa voix pour punir ses ennemis. Les oreilles rondes de ce Pokémon servent de haut-parleurs."}, {"g": "Saphir Alpha", "t": "Ramboum hurle en trépignant. Quand il a fini de hurler, ce Pokémon reste incapable d’entendre le moindre son pendant un long moment. Il semble que ce soit son point faible."}, {"g": "Épée", "t": "Ses oreilles lui servant de haut-parleurs peuvent émettre des ondes sonores dont la puissance suffit à balayer une maison."}, {"g": "Bouclier", "t": "Ses hurlements n’affectent pas seulement l’ouïe ; ils provoquent aussi une onde de choc qui balaie les ennemis et leur inflige des dégâts."}],
  295: [{"g": "Noir", "t": "Son hurlement s’entend à 10 km à la ronde. Ses orifices émettent toutes sortes de bruits."}, {"g": "Y", "t": "Au combat, son hurlement fait trembler le sol comme un séisme."}, {"g": "Rubis Oméga", "t": "Brouhabam peut déclencher des tremblements de terre grâce aux vibrations de son hurlement. Lorsque ce Pokémon inspire fortement, cela signifie qu’il se prépare à pousser un gigantesque rugissement."}, {"g": "Saphir Alpha", "t": "Brouhabam communique avec les autres en émettant un sifflement qui provient des tubes de son corps. Ce Pokémon n’élève la voix que pendant les combats."}, {"g": "Épée", "t": "Autrefois, l’Homme se servait du cri puissant de ce Pokémon pour communiquer d’une ville à l’autre sur de longues distances."}, {"g": "Bouclier", "t": "Pour communiquer avec ses semblables, il n’utilise pas que son cri puissant ; il émet aussi des sons par les trous de son corps."}],
  296: [{"g": "Noir", "t": "Il fortifie son corps en fonçant sur des arbres épais. Son nid est entouré d’arbres abattus."}, {"g": "X", "t": "Il fonce sur des arbres larges pour fortifier son corps robuste et son cœur vaillant."}, {"g": "Y", "t": "Il suit un entraînement drastique pour devenir encore plus fort. C’est un Pokémon plein de volonté, et capable de faire face à toutes les attaques."}, {"g": "Rubis Oméga", "t": "Makuhita est tenace. Même s’il est presque battu, il continue à se relever et à attaquer son ennemi. Chaque fois qu’il se relève, ce Pokémon stocke plus d’énergie en vue de sa future évolution."}, {"g": "Saphir Alpha", "t": "Makuhita a un moral d’acier. Il ne désespère jamais. Il mange beaucoup, dort beaucoup et s’entraîne avec rigueur. Son hygiène de vie permet à ce Pokémon d’accumuler un maximum d’énergie."}, {"g": "Soleil", "t": "Les Makuhita d’Alola sont aujourd’hui les plus connus, bien qu’ils aient à l’origine été amenés sur l’archipel depuis des régions étrangères."}, {"g": "Lune", "t": "La journée de ce Pokémon est placée sous le signe de l’entraînement intensif, qui ne s’interrompt que pour manger et faire la sieste."}, {"g": "Ultra-Soleil", "t": "Il s’entraîne en frappant les arbres de la paume de la main. Il peut arriver qu’il s’attaque à un pauvre Noadkoko, qui l’envoie alors valser."}, {"g": "Ultra-Lune", "t": "Il existerait un plat mijoté traditionnel que les Dresseurs cuisinent pour rendre leur Makuhita encore plus fort."}],
  297: [{"g": "Noir", "t": "Il aime mesurer sa force à celle des plus grands Pokémon. Ses coups de paume peuvent projeter un camion."}, {"g": "X", "t": "Il piétine le sol violemment pour concentrer son énergie. Il peut envoyer en l’air un camion de 10 t d’un seul coup de poing."}, {"g": "Rubis Oméga", "t": "Hariyama s’entraîne à donner ses coups directs avec sa paume le plus souvent possible. Un seul de ces puissants coups de paume peut plier un poteau téléphonique en deux."}, {"g": "Saphir Alpha", "t": "Hariyama a l’air un peu enrobé, mais c’est en fait une montagne de muscles. Si ce Pokémon se raidit et contracte ses muscles, son corps devient dur comme de la pierre."}, {"g": "Soleil", "t": "Malgré leur force spectaculaire, les vieux Hariyama préfèrent délaisser le combat au profit de l’entraînement des jeunes Makuhita."}, {"g": "Lune", "t": "Sa force herculéenne lui permet de renverser un camion d’une seule main. Les Hariyama aiment s’adonner à des concours de force pure."}, {"g": "Ultra-Soleil", "t": "Bien qu’il aime les rapports de force, c’est aussi un cœur tendre qui sait respecter et féliciter ses adversaires pour leur combativité."}, {"g": "Ultra-Lune", "t": "Les Hariyama les plus forts ne sont pas forcément les plus grands. Les petits gabarits aussi ont plus d’un tour dans leur sac."}],
  298: [{"g": "Noir", "t": "Sa queue est plus rebondissante qu’une balle du même nom. C’est aussi une massue très puissante."}, {"g": "X", "t": "Un Pokémon qui vit près de l’eau. Au sol, il se déplace rapidement en rebondissant sur sa grosse queue."}, {"g": "Y", "t": "Il fait tournoyer sa queue, connue pour ses qualités nutritives, pour l’abattre comme une puissante massue sur l’ennemi."}, {"g": "Rubis Oméga", "t": "Azurill fait tournoyer sa queue comme un lasso et l’envoie si fort que le reste de son corps est également projeté. Le record de lancer de ce Pokémon est actuellement de 10 m."}, {"g": "Saphir Alpha", "t": "La grande queue d’Azurill est élastique. Elle lui permet de stocker les nutriments nécessaires à sa croissance. Parfois, on voit Azurill s’amuser à rebondir sur sa queue élastique."}, {"g": "Épée", "t": "La boule située au bout de sa queue rebondit telle une balle de caoutchouc. Elle regorge des nutriments nécessaires à la croissance d’Azurill."}, {"g": "Bouclier", "t": "C’est un Pokémon docile, mais si on l’énerve, il n’hésite pas à frapper en faisant tournoyer la grosse boule au bout de sa queue."}],
  299: [{"g": "Noir", "t": "Face au danger, il se protège en augmentant son magnétisme et en attirant tout objet métallique."}, {"g": "X", "t": "Son nez polarisé lui permet de se défendre en augmentant son magnétisme et en attirant tout objet métallique."}, {"g": "Y", "t": "Son nez magnétique pointe constamment vers le nord. Les voyageurs l’observent pour connaître leur position."}, {"g": "Rubis Oméga", "t": "Le nez magnétique de Tarinor pointe toujours vers le nord. Si deux de ces Pokémon se rencontrent, ils ne peuvent pas se faire face car leurs nez magnétiques se repoussent."}, {"g": "Saphir Alpha", "t": "On raconte que Tarinor reste complètement immobile, avec son nez magnétique orienté vers le nord. Cependant, des études minutieuses ont démontré que ce Pokémon se déplace de 1 cm par an."}, {"g": "Soleil", "t": "Le nez de Tarinor, qui fonctionne comme une boussole infaillible, en fait un allié de choix pour tout Dresseur Pokémon."}, {"g": "Lune", "t": "Sa puissance magnétique lui sert à attirer ses proies, mais également des objets métalliques qu’il utilise en guise de bouclier."}, {"g": "Ultra-Soleil", "t": "Il ne se déplace que d’un centimètre par an, mais s’il se sent menacé, il virevolte et s’enfonce dans le sol en un instant."}, {"g": "Ultra-Lune", "t": "Grâce à sa force magnétique, il peut chasser ses proies sans se déplacer, mais il attire parfois ses pires ennemis."}],
  300: [{"g": "Noir", "t": "Il poursuit tout ce qui bouge. On le voit parfois courir en cercle, chassant sa propre queue."}, {"g": "Y", "t": "Un Pokémon très mignon qui aime parfois courir en cercle en chassant sa propre queue."}, {"g": "Rubis Oméga", "t": "Skitty a pris l’habitude de pourchasser les objets mobiles qui le fascinent. On sait que ce Pokémon court souvent après sa queue, jusqu’à ce qu’il ait la tête qui tourne."}, {"g": "Saphir Alpha", "t": "On sait que Skitty court souvent après sa queue. À l’état sauvage, ce Pokémon vit dans les cavités des arbres de la forêt. Il est tellement adorable qu’il a un grand succès comme animal de compagnie."}],
  301: [{"g": "Noir", "t": "Les femmes Dresseurs raffolent de sa sublime fourrure. Il ne possède pas de nid."}, {"g": "X", "t": "Il déteste la saleté et passe son temps à entretenir sa fourrure, confortablement installé."}, {"g": "Rubis Oméga", "t": "Delcatty préfère vivre une existence sans contraintes, au cours de laquelle chacun pourrait faire ce qu’il veut. Comme ce Pokémon mange et dort quand il le décide, son rythme de vie est totalement aléatoire."}, {"g": "Saphir Alpha", "t": "Delcatty peut dormir n’importe où. Il n’a pas de nid permanent. Lorsque d’autres Pokémon lui cherchent des noises pendant son sommeil, il ne répond pas et se contente de partir dormir ailleurs."}],
  302: [{"g": "Noir", "t": "À force de manger des gemmes, les yeux de ce Pokémon des grottes obscures sont devenus des joyaux."}, {"g": "Y", "t": "Ce Pokémon vit dans les grottes obscures et mange des gemmes qu’il déterre avec ses griffes acérées."}, {"g": "Rubis Oméga", "t": "Les Ténéfix mènent une vie tranquille dans les cavernes. Pourtant, ils sont craints, car on raconte que ces Pokémon volent l’esprit des gens quand leurs yeux brillent dans l’obscurité."}, {"g": "Saphir Alpha", "t": "Ténéfix creuse le sol avec ses griffes acérées pour trouver des rochers à manger. Les substances des rochers avalés se cristallisent et remontent sur la peau de ce Pokémon."}, {"g": "Soleil", "t": "Comme il adore tout ce qui brille, il traque souvent les Strassie. Malheureusement, il se fait tout aussi souvent devancer par Carmache."}, {"g": "Lune", "t": "Pokémon redouté de beaucoup, car l’éclat de ses yeux précieux donne l’impression qu’il s’apprête à dérober l’âme de ceux qu’il regarde."}, {"g": "Ultra-Soleil", "t": "Il creuse le sol de ses griffes acérées pour trouver des gemmes, qu’il croque comme s’il s’agissait de chips. Il raffole des Strassie."}, {"g": "Ultra-Lune", "t": "Les éléments présents dans les gemmes qu’il mange remontent à la surface de son corps, formant des motifs d’une infinie variété."}, {"g": "Épée", "t": "Beaucoup de gens le craignent, car l’éclat de ses yeux précieux donne l’impression qu’il s’apprête à dérober l’âme de ceux qu’il regarde."}, {"g": "Bouclier", "t": "Ce Pokémon se nourrit de pierres précieuses. Dans les ténèbres, ses yeux brillent du reflet des joyaux."}],
  303: [{"g": "Noir", "t": "Ses cornes forment une grande mâchoire attachée à sa tête. Elle peut broyer des barres de fer."}, {"g": "X", "t": "Il utilise son visage charmeur pour tromper ses ennemis avant de les mordre avec ses énormes mâchoires."}, {"g": "Rubis Oméga", "t": "Les énormes mâchoires de Mysdibule sont en réalité des cornes en métal transformées. Son visage doux et gentil est un leurre pour tromper l’ennemi. Quand l’ennemi s’y attend le moins, il le croque d’un coup de mâchoire."}, {"g": "Saphir Alpha", "t": "Il ne faut pas se fier au visage mignon de ce Pokémon. Il est très dangereux. Mysdibule leurre son ennemi, puis le croque avec son énorme mâchoire constituée en fait des cornes transformées."}, {"g": "Ultra-Soleil", "t": "Rusé et dangereux, ce Pokémon profite de son air candide pour tromper ses ennemis, et les gobe d’un trait dès qu’ils ont le dos tourné."}, {"g": "Ultra-Lune", "t": "Il possède deux bouches. Celle au sommet de sa tête ne percevant pas les saveurs, il s’en sert pour manger les aliments qui lui déplaisent."}, {"g": "Épée", "t": "Trompés par son visage innocent, ses ennemis se font happer par ses énormes mâchoires et ne peuvent plus s’échapper."}, {"g": "Bouclier", "t": "Ses cornes d’acier forment une grande mâchoire avec laquelle il mord férocement ses adversaires."}],
  304: [{"g": "Noir", "t": "Il vit habituellement au cœur des montagnes. Affamé, il dévore parfois des rails et des voitures."}, {"g": "Y", "t": "L’armure d’acier qui recouvre son corps s’émiette quand il évolue pour laisser place à une nouvelle."}, {"g": "Rubis Oméga", "t": "Ce Pokémon a un corps en acier. Pour constituer son corps, Galekid se nourrit de minerai de fer extrait des montagnes. De temps en temps, il cause de nombreux dégâts en mangeant des ponts ou des rails."}, {"g": "Saphir Alpha", "t": "Galekid a un corps d’acier. En une seule charge, ce Pokémon peut démolir un camion poids lourd. Le camion détruit devient ensuite le repas de ce Pokémon."}, {"g": "Épée", "t": "Il se nourrit de minerai de fer et parfois même de rails pour se fabriquer une armure d’acier qui protège son corps."}, {"g": "Bouclier", "t": "Quand il évolue, il perd son armure d’acier. Autrefois, les gens la ramassaient pour en faire usage dans leur vie quotidienne."}],
  305: [{"g": "Noir", "t": "Il se nourrit du minerai de fer qu’il fore. Il défend son territoire en chargeant avec son corps d’acier."}, {"g": "X", "t": "Il raffole du minerai de fer. Il défend son territoire en chargeant avec son corps d’acier."}, {"g": "Y", "t": "Pour montrer sa force à ses ennemis, Galegon frotte son corps d’acier contre les rochers pour produire de gigantesques étincelles."}, {"g": "Rubis Oméga", "t": "Galegon adoucit son corps d’acier en buvant une eau minérale jusqu’à ce qu’il soit tout boursouflé. Ce Pokémon fait son nid près des sources d’eau minérale riches en nutriments."}, {"g": "Saphir Alpha", "t": "Galegon se nourrit du fer contenu dans les rochers et dans l’eau. Il fait son nid sur les montagnes renfermant du minerai de fer. Du coup, il se confronte souvent aux humains travaillant dans les mines."}, {"g": "Épée", "t": "Vivre au sein de montagnes riches en minerai et abondantes en eau de source lui a souvent valu d’entrer en conflit avec l’Homme."}, {"g": "Bouclier", "t": "Les Galegon se disputent les territoires en luttant au corps à corps, comme le montrent les éraflures sur leur armure d’acier."}],
  306: [{"g": "Noir", "t": "Il creuse des galeries à travers la pierre avec ses cornes d’acier pour trouver le fer qu’il apprécie."}, {"g": "X", "t": "Il établit son territoire sur toute une montagne. Ses cicatrices indiquent son expérience : plus il en a, plus il est fort !"}, {"g": "Rubis Oméga", "t": "Galeking marque son territoire autour d’une montagne entière. Il combat sans merci quiconque pénètre dans son environnement. Ce Pokémon patrouille sans arrêt sur son territoire."}, {"g": "Saphir Alpha", "t": "Galeking est attentif à son environnement. Si sa montagne est ravagée par un glissement de terrain ou un incendie, ce Pokémon laboure la terre, plante des arbres et restaure le paysage."}, {"g": "Épée", "t": "Il terrasse ses ennemis en chargeant et en donnant des coups avec ses cornes acérées capables de transpercer des plaques de fer épaisses."}, {"g": "Bouclier", "t": "Il y a fort longtemps, un roi portait un casque à l’effigie de Galeking, pensant qu’il pourrait ainsi s’approprier sa force."}],
  307: [{"g": "Noir", "t": "Son entraînement d’ermite lui permet de léviter par le seul pouvoir de la méditation."}, {"g": "Y", "t": "Il ne mange qu’une Baie par jour. La faim lui a forgé une volonté de fer."}, {"g": "Rubis Oméga", "t": "Méditikka poursuit un difficile entraînement mental dans les montagnes. Cependant, à chaque fois qu’il médite, ce Pokémon perd sa concentration. Du coup, son entraînement ne s’arrête jamais."}, {"g": "Saphir Alpha", "t": "Méditikka intensifie son énergie intérieure grâce à la méditation. Il lui suffit d’une Baie par jour pour survivre. La diète fait partie de l’entraînement de ce Pokémon."}],
  308: [{"g": "Noir", "t": "Le jeûne lui permet de concentrer son esprit au point de déceler l’aura de ses adversaires."}, {"g": "X", "t": "Charmina évite les attaques en exécutant d’élégants pas de danse avant de lancer une attaque dévastatrice dans son élan."}, {"g": "Y", "t": "Ses pouvoirs psy, renforcés par la pratique du yoga, lui permettent de prédire les mouvements ennemis."}, {"g": "Rubis Oméga", "t": "On dit que grâce à la méditation, Charmina stocke de l’énergie dans son corps et affine son sixième sens. Ce Pokémon se cache des autres en se fondant dans les champs et les montagnes."}, {"g": "Saphir Alpha", "t": "Grâce au pouvoir de la méditation, Charmina a développé son sixième sens. Il peut utiliser des pouvoirs télékinétiques. On sait que ce Pokémon peut méditer pendant un mois sans manger."}],
  309: [{"g": "Noir", "t": "Il améliore ses réflexes en stimulant ses muscles grâce à l’électricité dans sa fourrure."}, {"g": "Y", "t": "Dynavolt stocke de l’électricité statique dans sa fourrure. Il produit des étincelles lorsque le temps devient orageux."}, {"g": "Rubis Oméga", "t": "Dynavolt stocke de l’électricité dans les poils de son corps allongé. Ce Pokémon stimule les muscles de ses jambes avec des charges électriques, ce qui le rend capable d’accélérations fulgurantes."}, {"g": "Saphir Alpha", "t": "Dynavolt court tellement vite que l’œil humain ne peut pas le suivre. La friction générée par sa course est convertie en électricité, puis stockée dans la fourrure de ce Pokémon."}, {"g": "Ultra-Soleil", "t": "La friction de ses poils avec l’air génère de l’électricité statique quand il court et produit un son qui s’apparente à des crépitements."}, {"g": "Ultra-Lune", "t": "Il est très fier de sa vitesse et peut envelopper son corps d’électricité statique en frottant ses longs poils."}, {"g": "Épée", "t": "Il émet des décharges à partir de l’électricité statique accumulée dans sa fourrure. Il produit des étincelles lorsque le temps devient orageux."}, {"g": "Bouclier", "t": "L’électricité statique s’accumule dans sa fourrure. Par temps sec, elle dégage des étincelles."}],
  310: [{"g": "Noir", "t": "Il libère l’électricité par sa crinière. Il crée un nuage d’orage pour appeler la foudre."}, {"g": "X", "t": "Ce Pokémon évite le contact des humains. On raconte qu’il fait son nid là où la foudre est déjà tombée."}, {"g": "Rubis Oméga", "t": "La crinière d’Élecsprint libère constamment de l’électricité. Les étincelles déclenchent parfois des feux de forêt. Au début de ses combats, ce Pokémon crée des nuages orageux."}, {"g": "Saphir Alpha", "t": "Élecsprint peut libérer un courant intense de sa crinière. Cette crinière lui permet de récupérer l’électricité de l’atmosphère. Ce Pokémon peut créer des nuages orageux au-dessus de sa tête."}, {"g": "Ultra-Soleil", "t": "Si un nuage orageux un peu louche apparaît dans le ciel, un Élecsprint se trouve sûrement en dessous. On le dit aussi rapide que l’éclair."}, {"g": "Ultra-Lune", "t": "Il diffuse de l’électricité dans ses membres pour augmenter sa vitesse. C’est également ainsi qu’il apaise ses douleurs musculaires."}, {"g": "Bouclier", "t": "Ce Pokémon évite de se montrer aux humains. On raconte qu’il fait son nid aux endroits où la foudre s’est abattue."}],
  311: [{"g": "Noir", "t": "Il absorbe l’énergie des poteaux électriques et encourage ses amis avec des pompons d’étincelles."}, {"g": "Y", "t": "Il absorbe l’énergie des poteaux électriques et court-circuite son corps pour produire du bruit."}, {"g": "Rubis Oméga", "t": "Posipi sert de supporter à ses partenaires. Chaque fois qu’un membre de son équipe fait une belle action dans un combat, ce Pokémon court-circuite son corps et libère des étincelles pour montrer sa joie."}, {"g": "Saphir Alpha", "t": "Quand Posipi veut encourager son partenaire, des étincelles jaillissent un peu partout de son corps. Si son partenaire perd, ce Pokémon pleure à chaudes larmes."}],
  312: [{"g": "Noir", "t": "Il encourage ses amis. Son corps produit plus d’étincelles quand il est en mauvaise posture."}, {"g": "X", "t": "L’électricité de Posipi et Négapi favorise la circulation sanguine et guérit les courbatures."}, {"g": "Rubis Oméga", "t": "Négapi n’hésite pas à se mettre en danger pour soutenir ses partenaires. Il court-circuite son corps pour faire jaillir des gerbes d’étincelles et donner du cœur à l’ouvrage à ses équipiers."}, {"g": "Saphir Alpha", "t": "Négapi adore encourager son partenaire pendant les combats. Des étincelles jaillissent alors de son corps. Lorsque son partenaire est en difficulté, le corps de ce Pokémon libère encore plus d’étincelles."}],
  313: [{"g": "Noir", "t": "Il communique avec ses pairs en allumant son postérieur la nuit. Il adore le doux parfum de Lumivole."}, {"g": "Y", "t": "Il vit aux abords des étangs. La nuit, son corps émet de la lumière pour communiquer avec d’autres Muciole."}, {"g": "Rubis Oméga", "t": "À la tombée de la nuit, la queue de Muciole émet de la lumière. Il communique avec les autres en ajustant l’intensité et le clignotement de sa lumière. Ce Pokémon est attiré par le doux parfum de Lumivole."}, {"g": "Saphir Alpha", "t": "La queue de Muciole éclaire comme une ampoule. Ensemble, les Muciole dessinent des figures géométriques dans la nuit étoilée. Ce Pokémon adore le parfum dégagé par Lumivole."}],
  314: [{"g": "Noir", "t": "Il utilise son doux parfum pour aider Muciole à décrire des arabesques dans le ciel nocturne."}, {"g": "X", "t": "Il utilise son doux parfum pour aider Muciole à décrire plus de 200 arabesques dans le ciel nocturne."}, {"g": "Rubis Oméga", "t": "Lumivole peut attirer un essaim de Muciole grâce à son doux parfum. Une fois les Muciole rassemblés, ce Pokémon dirige cette nuée lumineuse et lui fait dessiner des figures géométriques dans la nuit étoilée."}, {"g": "Saphir Alpha", "t": "Lumivole dirige un vol de Muciole lumineux pour dessiner des figures dans la nuit étoilée. On raconte que ce Pokémon gagne le respect de ses pairs en composant des figures complexes dans le ciel."}],
  315: [{"g": "Noir", "t": "Plus le Rosélia est en bonne santé et plus son parfum est agréable et relaxant pour son entourage."}, {"g": "X", "t": "Chacune de ses mains sécrète un poison différent. Plus un Rosélia est en bonne santé, plus ses parfums sont puissants."}, {"g": "Y", "t": "Les Rosélia arrosés avec une eau de source riche en nutriments prendraient des couleurs uniques."}, {"g": "Rubis Oméga", "t": "Rosélia utilise ses épines pointues comme projectiles si on tente de cueillir les fleurs sur ses bras. Le parfum de ce Pokémon apporte sérénité et plénitude à ceux qui le sentent."}, {"g": "Saphir Alpha", "t": "En de très rares occasions, on dit qu’un Rosélia peut apparaître en arborant des fleurs aux couleurs inhabituelles. Les épines sur la tête de ce Pokémon contiennent un dangereux poison."}, {"g": "Épée", "t": "Ses fleurs dégagent un parfum relaxant. Plus cet arôme est fort, meilleure est la santé de Rosélia."}, {"g": "Bouclier", "t": "Ses mains sécrètent chacune un poison différent dont il se sert pour attaquer. Plus le parfum de Rosélia est intense, plus sa santé est bonne."}],
  316: [{"g": "Noir", "t": "Il est principalement composé d’un estomac dont les sucs digestifs dissolvent tout ce qu’il avale."}, {"g": "X", "t": "Son corps est principalement constitué d’un estomac dont les sucs digestifs dissolvent tout."}, {"g": "Y", "t": "Il n’y a rien que son estomac ne puisse digérer. Pendant sa digestion, il laisse s’échapper des gaz très bruyants et nauséabonds."}, {"g": "Rubis Oméga", "t": "Virtuellement, le corps de Gloupti n’est qu’un estomac. Il est capable d’avaler des objets aussi gros que lui. L’estomac de ce Pokémon contient un fluide spécial qui lui permet de digérer n’importe quoi."}, {"g": "Saphir Alpha", "t": "Le corps de Gloupti n’est pratiquement qu’un gros estomac. En comparaison, son cœur et son cerveau sont tout petits. L’estomac de ce Pokémon contient des enzymes spéciales capables de tout dissoudre."}],
  317: [{"g": "Noir", "t": "Il avale tout en une bouchée. Ses follicules sécrètent des fluides toxiques qui endorment l’ennemi."}, {"g": "Y", "t": "Il avale tout en une bouchée. Ses sucs digestifs peuvent digérer n’importe quoi."}, {"g": "Rubis Oméga", "t": "Lorsqu’Avaltout repère une proie, il libère une substance terriblement toxique de ses pores et en enduit son ennemi pour l’affaiblir. Ce Pokémon peut ensuite l’avaler d’un coup dans sa gigantesque bouche."}, {"g": "Saphir Alpha", "t": "Avaltout n’a pas de dents, ce qui le force à tout avaler en une bouchée. Quand il bâille, sa bouche prend une taille impressionnante, et on pourrait y placer une roue de voiture."}],
  318: [{"g": "Noir", "t": "Il attaque en banc quand on menace son territoire. Ses dents aiguisées peuvent couler un navire."}, {"g": "X", "t": "Il s’attaque en banc aux bateaux dont il dévore la coque. Les rivières de la jungle forment son habitat."}, {"g": "Y", "t": "Ce Pokémon vit dans les fleuves qui traversent les forêts tropicales. Il attaque en groupe ceux qui s’aventurent sur son territoire."}, {"g": "Rubis Oméga", "t": "Les mâchoires surdéveloppées de Carvanha et ses crocs acérés sont si puissants qu’ils peuvent déchirer la coque des bateaux. De nombreux navires ont été attaqués et coulés par ce Pokémon."}, {"g": "Saphir Alpha", "t": "Si un intrus s’aventure sur le territoire des Carvanha, ils se ruent sur lui et le mordent à l’aide de leurs crocs acérés. En revanche, lorsqu’il est seul, ce Pokémon devient tout à coup très timide."}, {"g": "Soleil", "t": "Il protège son territoire en se déplaçant en banc. Le moindre intrus est raccompagné sans pitié, à grands claquements de mâchoire."}, {"g": "Lune", "t": "En banc, il guette l’odeur du sang et fond sur sa proie sans aucune pitié. Seul, il se montre plus timoré."}, {"g": "Ultra-Soleil", "t": "C’est un couard qui ne chasse jamais tout seul. Dès qu’il se retrouve dans un groupe de cinq, par contre, il devient on ne peut plus féroce !"}, {"g": "Ultra-Lune", "t": "Grâce à sa mâchoire d’acier et ses dents acérées, il déchiquette sans peine les canots. Bargantua et lui se disputent le menu fretin."}, {"g": "Épée", "t": "Il ne s’attaque jamais à une proie tout seul, préférant attendre l’arrivée de ses congénères pour lancer l’assaut."}, {"g": "Bouclier", "t": "Il possède une mâchoire puissante garnie de dents acérées. Les marins ne s’approchent jamais des eaux habitées par les Carvanha."}],
  319: [{"g": "Noir", "t": "Ses crocs lacèrent des feuilles d’acier. Il nage à 120 km/h. On l’appelle “tyran des mers”."}, {"g": "X", "t": "Ses crocs lacèrent des feuilles d’acier. Il nage à 120 km/h. On l’appelle « tyran des mers »."}, {"g": "Y", "t": "Ce petit voyou fend les mers en se propulsant à 120 km/h grâce à son postérieur."}, {"g": "Rubis Oméga", "t": "Surnommé le « tyran des mers », Sharpedo est craint de par le monde. Ses crocs menaçants repoussent lorsqu’ils se brisent. Un seul de ces Pokémon peut détruire un pétrolier gros porteur."}, {"g": "Saphir Alpha", "t": "Sharpedo peut nager à plus de 120 km/h en propulsant de l’eau de mer par l’arrière de son corps. Ce Pokémon a un point faible : il ne peut pas parcourir de longues distances."}, {"g": "Soleil", "t": "Sa vitesse de pointe atteint les 120 km/h et ses dents acérées viennent même à bout de l’acier. On le surnomme le « tyran des mers »."}, {"g": "Lune", "t": "Ce Pokémon a un bien triste passé : il était en effet impitoyablement chassé pour son aileron, fort apprécié des gourmets."}, {"g": "Ultra-Soleil", "t": "On fabrique des accessoires à partir de ses dents, car elles ont la réputation de protéger leurs porteurs des accidents en mer."}, {"g": "Ultra-Lune", "t": "Ce Pokémon extrêmement sensible à l’odeur du sang se déplace en évacuant par son orifice postérieur l’eau de mer qu’il avale."}, {"g": "Épée", "t": "Dès qu’il détecte l’odeur d’une proie, il fonce sur elle à une vitesse de 120 km/h en propulsant de l’eau de mer par son postérieur."}, {"g": "Bouclier", "t": "Surnommé le « tyran des mers », ce Pokémon attaque sans exception tous les navires qui osent s’aventurer sur son territoire."}],
  320: [{"g": "Noir", "t": "Par beau temps, il se pose sur les plages pour jouer et rebondir. Il expulse de l’eau par son évent."}, {"g": "X", "t": "Il rebondit comme un ballon pour s’amuser. Plus il boit d’eau, plus il va haut."}, {"g": "Y", "t": "Il mange près d’une tonne de nourriture par jour. Jouer avec son jet d’eau est son passe-temps favori."}, {"g": "Rubis Oméga", "t": "Les narines de Wailmer sont situées au-dessus de ses yeux. Ce joyeux Pokémon adore effrayer les gens en expulsant de l’eau de mer par les narines."}, {"g": "Saphir Alpha", "t": "Wailmer peut stocker de l’eau dans son corps pour se transformer en balle et rebondir sur le sol. Plus ce Pokémon se remplit d’eau, plus il peut rebondir haut."}, {"g": "Soleil", "t": "Très joueur, il adore faire des blagues. Il engloutit des litres d’eau de mer et enfle comme une baudruche, pour mieux rebondir."}, {"g": "Lune", "t": "Il recrache l’eau avalée par son évent, c’est ce qui le rend si charmant. Il gobe une tonne de Froussardine par jour."}, {"g": "Ultra-Soleil", "t": "Pour se nourrir, il nage en gardant la bouche grande ouverte, et recrache l’eau dont il n’a pas besoin par son évent."}, {"g": "Ultra-Lune", "t": "On raconte que ce Pokémon habitait jadis sur terre. En de rares occasions, on peut en voir se regrouper sur les plages."}, {"g": "Épée", "t": "Il aime faire le beau en recrachant par son évent l’eau qu’il a avalée. Il gobe une tonne de Froussardine chaque jour."}, {"g": "Bouclier", "t": "Il ressemble à un énorme ballon quand il avale de très grandes quantités d’eau de mer. Il dévore une tonne de nourriture par jour."}],
  321: [{"g": "Noir", "t": "Le plus grand des Pokémon. Il peut plonger à une profondeur de 3 000 m en retenant son souffle."}, {"g": "X", "t": "L’énorme fracas résultant de ses sauts par-dessus les vagues peut faire perdre connaissance à ses adversaires."}, {"g": "Rubis Oméga", "t": "Wailord est le plus grand Pokémon découvert à ce jour. Ce Pokémon géant nage lascivement dans les grandes étendues maritimes, avalant d’énormes quantités de nourriture en une seule de ses monstrueuses bouchées."}, {"g": "Saphir Alpha", "t": "Lorsqu’il chasse ses proies, Wailord les rassemble en sautant hors de l’eau et en créant une énorme vague. La vue de plusieurs de ces Pokémon bondissant hors de l’eau laisse généralement sans voix."}, {"g": "Soleil", "t": "Il a pour habitude de chasser en groupe. Sa large gueule lui permet d’engloutir un banc de Froussardine d’un seul coup."}, {"g": "Lune", "t": "Sa taille fait de lui un Pokémon fascinant. Les sites touristiques proposant d’observer les Wailord ont toujours beaucoup de succès."}, {"g": "Ultra-Soleil", "t": "Les Wailord se sont multipliés à force de se gaver de Pokémon poissons, tant et si bien que les pêcheurs doivent les renvoyer vers le large."}, {"g": "Ultra-Lune", "t": "Si un petit Wailmer vient à se faire attaquer par un Sharpedo ou un Sinistrail, les Wailord du banc se regroupent autour de lui pour le protéger."}, {"g": "Épée", "t": "L’énorme fracas causé par ses sauts par-dessus les vagues peut faire perdre connaissance à ses adversaires."}],
  322: [{"g": "Noir", "t": "Son dos bossu renferme une lave bouillonnante. Elle refroidit par temps de pluie, ce qui le ralentit."}, {"g": "Y", "t": "Son corps renferme une lave à plus de 1 200 °C. Sa bosse se contracte lorsqu’il utilise des capacités de type Feu."}, {"g": "Rubis Oméga", "t": "Chamallot est terriblement lent d’esprit. Il ne remarque même pas quand il est touché. Il ne supporte pas d’avoir faim, même une seconde. Le corps de ce Pokémon est comparable à un chaudron de magma bouillonnant."}, {"g": "Saphir Alpha", "t": "Chamallot stocke du magma à 1 200 °C dans son corps. Lorsqu’il est mouillé, le magma se refroidit et durcit. Le corps du Pokémon devient alors très lourd et ses mouvements très lents."}],
  323: [{"g": "Noir", "t": "Il porte des volcans sur son dos. Quand le magma remonte, il frissonne et entre en éruption."}, {"g": "X", "t": "Les volcans sur son dos entrent en éruption tous les dix ans ou chaque fois qu’il se met en colère."}, {"g": "Y", "t": "S’il s’énerve, Camérupt fait jaillir de la lave en fusion par les bosses qui se trouvent sur son dos. Il vit dans les cratères des volcans."}, {"g": "Rubis Oméga", "t": "Le corps de Camérupt renferme un volcan. Du magma à 10 000 °C coule dans ses veines. De temps en temps, les bosses sur le dos de ce Pokémon entrent en éruption et crachent le magma surchauffé."}, {"g": "Saphir Alpha", "t": "Les bosses sur le dos de Camérupt sont apparues après une déformation de ses os. Elles crachent parfois du magma en fusion. Ce Pokémon entre apparemment en éruption lorsqu’il est énervé."}],
  324: [{"g": "Noir", "t": "Il tire son énergie du charbon qu’il brûle dans sa carapace et crache de la suie noire en cas de danger."}, {"g": "X", "t": "Les Chartor vivent dans les mines abandonnées, où ils extraient le charbon avec ardeur."}, {"g": "Rubis Oméga", "t": "Chartor fore les montagnes à la recherche de charbon. Lorsqu’il en trouve, il le met dans les emplacements creux de sa carapace pour le brûler. Quand il est attaqué, ce Pokémon crache une épaisse fumée noire pour s’enfuir."}, {"g": "Saphir Alpha", "t": "Chartor génère de l’énergie en brûlant du charbon. Il s’affaiblit lorsque le feu s’éteint. Lorsqu’il se prépare au combat, ce Pokémon brûle plus de charbon."}, {"g": "Soleil", "t": "Les Chartor peuplent les montagnes abritant de grands gisements de charbon, dont ils se servent comme source d’énergie."}, {"g": "Lune", "t": "Si le feu brûlant sous sa carapace s’éteint, il meurt. Si vous le gardez à la maison, il y a toujours quelque chose qui flambe."}, {"g": "Ultra-Soleil", "t": "Un bon indicateur de sa santé est le débit de la fumée qui s’échappe de sa carapace : s’il est important, c’est qu’il est en pleine forme."}, {"g": "Ultra-Lune", "t": "Il tire son énergie du charbon qu’il fait brûler. Une fois qu’il a tout consommé, il ne peut plus bouger."}, {"g": "Épée", "t": "Il tire son énergie du charbon qu’il brûle dans sa carapace, et crache de la suie noire en cas de danger."}, {"g": "Bouclier", "t": "Les Chartor vivent en grand nombre dans les mines abandonnées, où ils extraient le charbon avec ardeur."}],
  325: [{"g": "Noir", "t": "Il utilise sa queue comme un ressort et bondit partout. Chaque nouveau choc fait battre son cœur."}, {"g": "Y", "t": "Il rebondit sur sa queue pour faire battre son cœur. La perle sur sa tête vient d’un Coquiperl."}, {"g": "Rubis Oméga", "t": "Spoink rebondit sur sa queue. Le choc du rebond fait battre son cœur. Du coup, ce Pokémon ne peut pas s’arrêter de rebondir, sinon, son cœur s’arrête."}, {"g": "Saphir Alpha", "t": "Spoink garde une perle sur sa tête. Elle lui sert à amplifier ses pouvoirs télékinétiques. Il est constamment en quête d’une perle plus grosse."}],
  326: [{"g": "Noir", "t": "Les perles noires amplifient ses pouvoirs psy. Sa danse étrange lui permet de contrôler ses ennemis."}, {"g": "X", "t": "Les perles noires amplifient ses pouvoirs psychiques, lui permettant de contrôler ses ennemis avec sa danse étrange."}, {"g": "Rubis Oméga", "t": "Groret utilise les perles noires situées sur son corps pour amplifier la puissance de ses ondes psychiques et prendre le contrôle de son ennemi. Quand il utilise son pouvoir spécial, ce Pokémon a du mal à respirer."}, {"g": "Saphir Alpha", "t": "Groret utilise les perles noires sur son corps pour exercer ses formidables pouvoirs. Quand il est en action, il entame une étrange danse. Les perles noires de ce Pokémon ont une valeur inestimable."}],
  327: [{"g": "Noir", "t": "Les motifs sur leur fourrure sont propres à chaque Spinda. Son pas chancelant le rend difficile à viser."}, {"g": "Y", "t": "La chance que deux Spinda avec les mêmes motifs se rencontrent est de moins d’une pour quatre milliards."}, {"g": "Rubis Oméga", "t": "On raconte que chaque Spinda dispose d’un agencement de taches tout à fait unique. La démarche chancelante et titubante de ce Pokémon donne l’impression qu’il danse."}, {"g": "Saphir Alpha", "t": "On dit que chaque Spinda dispose d’un agencement de taches unique. Ce Pokémon se déplace bizarrement, comme s’il titubait. Ses mouvements hésitants décontenancent ses ennemis."}, {"g": "Soleil", "t": "Bien qu’il semble peu assuré sur ses pattes, Spinda est quant à lui persuadé d’avancer tout droit, faisant fi de ses embardées."}, {"g": "Lune", "t": "Chaque Spinda possède un pelage unique. Chercher les différences d’un Spinda à l’autre serait même un passe-temps pour certains."}, {"g": "Ultra-Soleil", "t": "Il déambule d’un pas chancelant. S’il marche trop longtemps, il finit par avoir le tournis."}, {"g": "Ultra-Lune", "t": "Chaque Spinda possède un pelage unique. Ce Pokémon esquive les attaques de son adversaire grâce à d’imprévisibles oscillations."}],
  328: [{"g": "Noir", "t": "Il creuse un trou conique dans le sable du désert et se terre en attendant qu’une proie trébuche."}, {"g": "X", "t": "Il vit dans les déserts arides. Pour attraper ses proies, il se place dans un trou et laisse sa gueule grande ouverte en attendant qu’elles tombent dedans."}, {"g": "Y", "t": "Il creuse puis attend ses proies dans son antre, un trou conique dont il est impossible de s’échapper."}, {"g": "Rubis Oméga", "t": "Le nid de Kraknoix consiste en un trou en pente creusé dans le sable, comme une cuvette. Ce Pokémon attend patiemment que sa proie tombe dedans. Ses gigantesques mâchoires sont assez puissantes pour croquer des rochers."}, {"g": "Saphir Alpha", "t": "Kraknoix est un chasseur patient. Dans le désert, il creuse un trou dont on ne peut pas s’échapper et attend que sa proie tombe dedans. Ce Pokémon peut se passer d’eau une semaine entière."}, {"g": "Soleil", "t": "Il peut survivre une semaine entière sans se sustenter. Il attend patiemment au fond de son trou, guettant sa proie."}, {"g": "Lune", "t": "Il creuse des trous dans le sable et brise les rochers qui le gênent d’un coup de mâchoire. Ses terriers ressemblent à un entonnoir."}, {"g": "Ultra-Soleil", "t": "Sa lourde mâchoire peut briser le roc, mais s’il tombe à la renverse, il ne peut plus se relever. Mascaïman en profite alors pour l’attaquer."}, {"g": "Ultra-Lune", "t": "Pour attraper ses proies, il bâtit un nid piégé et attend patiemment. Lorsque la nuit tombe, il s’enfouit dans le sable pour dormir."}, {"g": "Épée", "t": "Il est impossible de s’échapper de son antre en forme de cône qu’il creuse dans le sable du désert."}, {"g": "Bouclier", "t": "Il creuse, puis attend ses proies dans son antre en forme de cône, dont il est impossible de s’échapper."}],
  329: [{"g": "Noir", "t": "Ses violents battements d’ailes génèrent des vagues d’ultrasons qui donnent mal au crâne."}, {"g": "X", "t": "Ses violents battements d’ailes génèrent des vagues d’ultrasons qui donnent d’intenses migraines."}, {"g": "Y", "t": "Il génère des ondes ultrasoniques en battant violemment des ailes. Dès que sa proie est inconsciente, il l’arrose d’acide pour pouvoir l’avaler."}, {"g": "Rubis Oméga", "t": "Pour mettre ses proies K.O., Vibraninf envoie des ultrasons en faisant vibrer ses deux ailes. Les ondes sonores de ce Pokémon sont si puissantes qu’elles peuvent déclencher des maux de tête chez les gens."}, {"g": "Saphir Alpha", "t": "Les ailes de Vibraninf n’ont pas complètement fini de pousser. Elles ne lui servent pas à voler sur de longues distances, mais plutôt à générer des ultrasons en vibrant."}, {"g": "Soleil", "t": "Ses ébauches d’ailes ne lui servent pas tant à voler qu’à produire des ultrasons par frottement pour neutraliser ses ennemis."}, {"g": "Lune", "t": "Pour aider ses ailes à pousser, il fait un vrai carnage tous les jours, arrosant ses moult proies d’acide pour les dissoudre et s’en nourrir."}, {"g": "Ultra-Soleil", "t": "Il émet des ultrasons avec ses ailes pour assommer ses proies, puis les ensable vivantes pour les conserver."}, {"g": "Ultra-Lune", "t": "Il émet de puissantes ondes sonores en battant des ailes, aussi est-il recommandé à son Dresseur de se protéger les tympans."}, {"g": "Épée", "t": "Ses violents battements d’ailes génèrent des vagues d’ultrasons qui donnent des migraines intenses."}, {"g": "Bouclier", "t": "Pour aider ses ailes à pousser, il se nourrit chaque jour d’un grand nombre de proies qu’il dissout en projetant de l’acide."}],
  330: [{"g": "Noir", "t": "Son puissant battement d’ailes provoque des tempêtes de sable. On l’appelle “esprit du désert”."}, {"g": "X", "t": "Il se cache du regard des autres en soulevant le sable du désert avec ses ailes. Une fine peau rouge protège ses yeux du sable."}, {"g": "Y", "t": "On l’appelle « esprit du désert ». Son puissant battement d’ailes provoque des tempêtes de sable qui le dissimulent."}, {"g": "Rubis Oméga", "t": "Libégon est surnommé « l’esprit élémentaire du désert ». Le battement de ses ailes soulève des nuages de sable. C’est pourquoi ce Pokémon est toujours entouré d’une tempête de sable quand il vole."}, {"g": "Saphir Alpha", "t": "Libégon peut déclencher une tempête de sable en battant des ailes. Les ailes créent une suite de notes ressemblant à une mélodie. Comme cette « mélodie » est le seul son audible, on appelle ce Pokémon l’esprit du désert."}, {"g": "Soleil", "t": "Le bruissement de ses ailes est très mélodieux. Les malheureux envoûtés par ce chant se retrouvent prisonniers de sa tempête de sable."}, {"g": "Lune", "t": "Comme il est souvent caché au cœur des tempêtes de sable qu’il déclenche, ce Pokémon n’est que rarement aperçu par l’homme."}, {"g": "Ultra-Soleil", "t": "D’un battement d’ailes, il provoque des tempêtes qui engloutissent les Crocorible. Il partage ses proies avec ses congénères."}, {"g": "Ultra-Lune", "t": "Il n’est pas rare que des gens se perdent dans le désert après avoir succombé au charme du son mélodieux qu’il émet avec ses ailes."}, {"g": "Épée", "t": "Comme il est souvent caché au cœur des tempêtes de sable qu’il déclenche, ce Pokémon n’est que rarement aperçu par l’Homme."}, {"g": "Bouclier", "t": "On l’appelle « l’esprit du désert », car ses battements d’ailes résonnent comme une mélodie entonnée par une voix douce."}],
  331: [{"g": "Blanc", "t": "En stockant l’eau dans son corps, cet habitant du désert peut survivre 30 jours sans boire."}, {"g": "X", "t": "Cacnea vit dans les zones arides. Une fois par an, une fleur jaune éclot sur sa tête."}, {"g": "Y", "t": "Il se sent plus à l’aise dans des endroits hostiles comme le désert. Il peut survivre 30 jours en utilisant seulement l’eau stockée dans son corps."}, {"g": "Rubis Oméga", "t": "Cacnea vit dans les milieux arides, tels les déserts. Sa fleur libère un parfum entêtant pour attirer sa proie. Lorsqu’elle s’approche, ce Pokémon envoie des épines pour la neutraliser."}, {"g": "Saphir Alpha", "t": "Si son environnement est aride et difficile, la fleur de Cacnea devient plus jolie et dégage un parfum délicat. Ce Pokémon se bat en agitant ses bras épineux."}],
  332: [{"g": "Noir", "t": "Il sort la nuit pour chasser. Il traque les proies épuisées après une journée dans le désert."}, {"g": "Y", "t": "Les Cacturne traquent en groupe les voyageurs du désert, guettant les signes de fatigue pour frapper."}, {"g": "Rubis Oméga", "t": "Pendant la journée, Cacturne reste immobile pour éviter de se déshydrater sous le soleil du désert. Ce Pokémon ne commence son activité qu’une fois la nuit tombée, sous une température plus fraîche."}, {"g": "Saphir Alpha", "t": "Lorsqu’un voyageur traverse le désert au milieu de la nuit, les Cacturne le suivent en groupe. Ces Pokémon attendent le bon moment, quand le voyageur est fatigué et qu’il n’est plus capable de bouger."}],
  333: [{"g": "Noir", "t": "Il ne se sent à l’aise que dans un milieu propre et repousse la poussière avec ses ailes."}, {"g": "X", "t": "Son jeu préféré : se poser sur la tête des gens et se faire passer pour un joli chapeau."}, {"g": "Y", "t": "Il toilette constamment ses ailes duveteuses. Il se dépêche de se laver à la moindre salissure pour que ses ailes restent le plus blanc possible."}, {"g": "Rubis Oméga", "t": "Tylton est doté d’ailes légères et duveteuses comme des nuages cotonneux. Ce Pokémon n’est pas très sauvage. Il lui arrive d’atterrir sur la tête des gens et d’y rester, comme un chapeau ouaté."}, {"g": "Saphir Alpha", "t": "Tylton adore nettoyer. S’il repère quelque chose de sale, il l’essuie et le polit avec ses ailes cotonneuses. Lorsque ses ailes se salissent, ce Pokémon trouve un cours d’eau et se lave."}, {"g": "Épée", "t": "Ses ailes ressemblant à du coton contiennent de l’air, ce qui leur confère une texture duveteuse. Elles nécessitent un entretien minutieux."}, {"g": "Bouclier", "t": "Ses ailes en forme de nuage le dissimulent aux yeux des ennemis. On raconte qu’elles sont devenues blanches après plusieurs générations."}],
  334: [{"g": "Y", "t": "Il vole librement en se cachant dans les nuages. Son chant est digne de celui de la plus douée des sopranos."}, {"g": "Noir", "t": "Il aime enlacer ses amis dans ses ailes cotonneuses et ronronner."}, {"g": "X", "t": "Il vole doucement dans le ciel. Ceux qui l’entendent fredonner sont comme plongés dans un rêve."}, {"g": "Rubis Oméga", "t": "Altaria danse et tournoie dans les cieux, au milieu des nuages gonflés et cotonneux. Ce Pokémon chante des mélodies de sa voix cristalline pour offrir aux auditeurs une expérience merveilleuse et inoubliable."}, {"g": "Saphir Alpha", "t": "Altaria chante avec une magnifique voix de soprano. Ses ailes ressemblent à des nuages cotonneux. Ce Pokémon se laisse porter par les courants d’air ascendants et disparaît dans le bleu du ciel."}, {"g": "Épée", "t": "Il vole doucement dans le ciel et fredonne de magnifiques mélodies qui enchantent tous ceux qui les entendent."}, {"g": "Bouclier", "t": "Il est de nature aimable, mais si on le met en colère, il intimide son adversaire en poussant un cri strident et l’attaque sans pitié."}],
  335: [{"g": "Noir", "t": "C’est le rival de Séviper depuis des générations. Ses griffes aiguisées sont son meilleur atout."}, {"g": "Y", "t": "Son poil se hérisse dès qu’il sent un Séviper. Il lacère ses ennemis avec ses griffes acérées."}, {"g": "Rubis Oméga", "t": "Chaque cellule du corps de Mangriff porte les stigmates de sa rivalité avec Séviper. Ce Pokémon est capable d’esquiver les attaques avec une agilité incroyable."}, {"g": "Saphir Alpha", "t": "Mangriff est généralement à quatre pattes, mais lorsqu’il est en colère, il se lève sur ses pattes arrière et montre ses griffes. Ce Pokémon est l’ennemi juré de Séviper depuis plusieurs générations."}],
  336: [{"g": "Noir", "t": "Le rival historique de Mangriff. Il affûte la lame de sa queue sur les rochers avant le combat."}, {"g": "X", "t": "Il rivalise avec Mangriff grâce à la lame affûtée de sa queue qui sécrète un puissant venin."}, {"g": "Y", "t": "Il affûte la lame de sa queue sur des rochers pour la rendre bien tranchante. Le rival de longue date de Mangriff."}, {"g": "Rubis Oméga", "t": "Séviper se querelle avec Mangriff depuis plusieurs générations. Ses cicatrices sont les preuves de ses nombreux combats. Ce Pokémon attaque à l’aide de sa queue, aiguisée comme une épée."}, {"g": "Saphir Alpha", "t": "La queue tranchante comme un sabre de Séviper a deux fonctions : elle peut frapper l’ennemi et lui injecter un poison qu’il sécrète. Ce Pokémon n’oublie jamais sa vieille rancune envers Mangriff."}],
  337: [{"g": "Noir", "t": "On suppose qu’il est lié au cycle lunaire, car il ne sort que les soirs de pleine lune."}, {"g": "Y", "t": "Il a été découvert dans le cratère d’une météorite il y a 40 ans. Son simple regard endort ses ennemis."}, {"g": "Rubis Oméga", "t": "Séléroc fut découvert à côté d’un cratère de météorite. Du coup, certaines personnes pensent que ce Pokémon vient de l’espace. Cependant, rien ne peut prouver cette théorie pour le moment."}, {"g": "Saphir Alpha", "t": "Séléroc ne s’active que pendant la période de pleine lune. Il ne marche pas, mais se déplace en lévitant. Les yeux rouges et intimidants de ce Pokémon pétrifient ses ennemis de terreur."}, {"g": "Épée", "t": "Sa force est liée au cycle lunaire. Il est surtout actif les soirs de pleine lune."}, {"g": "Bouclier", "t": "Il a été découvert dans le cratère d’une météorite il y a 40 ans. Un simple regard de sa part endort ses ennemis."}],
  338: [{"g": "Noir", "t": "Le bruit court que cette nouvelle espèce vient du soleil. Il produit de la lumière en tournoyant."}, {"g": "X", "t": "Il tire sa force de l’énergie solaire. Il est donc particulièrement à l’aise en journée. Il s’illumine quand il tourne."}, {"g": "Y", "t": "Solaroc absorbe l’énergie du soleil pendant la journée. Toujours impassible, il parvient à lire les pensées de ses ennemis."}, {"g": "Rubis Oméga", "t": "Solaroc est une nouvelle espèce de Pokémon. On raconte qu’il serait tombé de l’espace. Il flotte dans les airs et se déplace silencieusement. Au combat, ce Pokémon libère une lumière intense."}, {"g": "Saphir Alpha", "t": "La lumière du soleil est à l’origine du pouvoir de Solaroc. On raconte qu’il peut lire les pensées d’autrui. Ce Pokémon peut libérer une chaleur insoutenable en faisant tournoyer son corps."}, {"g": "Épée", "t": "Il produit une lumière aussi aveuglante que le soleil quand il se met à tournoyer."}, {"g": "Bouclier", "t": "Tirant sa force de l’énergie solaire, il est particulièrement puissant pendant la journée. Il s’illumine quand il tourne."}],
  339: [{"g": "Noir", "t": "Son corps glissant est difficile à attraper. On dit qu’il a été créé dans de la boue solidifiée."}, {"g": "X", "t": "Il enduit son corps d’une substance visqueuse pour glisser et se libérer quand on l’agrippe."}, {"g": "Y", "t": "Ses barbillons font un excellent radar qui lui permet de repérer ses proies, même en eau trouble."}, {"g": "Rubis Oméga", "t": "Les vibrisses sensibles de Barloche agissent comme un système radar sophistiqué. Ce Pokémon se cache dans la boue, laissant dépasser ses vibrisses, et attend que sa proie passe à proximité."}, {"g": "Saphir Alpha", "t": "Le corps de Barloche est couvert d’un voile visqueux. Lorsqu’un ennemi l’attrape, ce Pokémon peut se glisser hors de son étreinte. Il s’affaiblit quand la pellicule visqueuse de son corps s’assèche."}, {"g": "Soleil", "t": "Il se sert de ses barbillons comme d’un radar ultra-sophistiqué. Ils lui permettent de détecter ses proies même dans l’eau boueuse."}, {"g": "Lune", "t": "Son corps tout visqueux le rend impossible à attraper. Il existe des concours d’adresse dont le but est d’attraper des Barloche à mains nues."}, {"g": "Ultra-Soleil", "t": "Son corps est tout visqueux, ce qui lui permet de glisser entre les serres des Pokémon oiseaux afin de s’échapper."}, {"g": "Ultra-Lune", "t": "Ses barbillons sont des organes sensoriels : ils peuvent détecter le goût et les odeurs, comme le font la langue et le nez des humains."}, {"g": "Épée", "t": "Son corps glissant est difficile à attraper. Dans une certaine région, on raconte qu’il est né à partir de boue solidifiée."}, {"g": "Bouclier", "t": "Il sonde les bords boueux des rivières avec ses barbillons. Un film fin et visqueux protège tout son corps."}],
  340: [{"g": "Noir", "t": "Il défend férocement son territoire en déclenchant des secousses terribles."}, {"g": "X", "t": "Il a besoin d’un étang entier pour vivre. Si un ennemi s’approche, il s’énerve et déclenche un séisme."}, {"g": "Y", "t": "Il fait son nid au fond des marais. Il ne se pose pas de questions et avale toutes les créatures qui passent près de lui."}, {"g": "Rubis Oméga", "t": "Quand il s’agit de territoire, Barbicha est très possessif. Un seul de ces Pokémon réclame parfois un étang entier. Si un ennemi s’approche, il fonce sur lui et déclenche un violent tremblement de terre."}, {"g": "Saphir Alpha", "t": "Lorsque Barbicha se déchaîne, il déclenche des secousses sismiques dans un rayon de plus de 5 km autour de lui. Ce Pokémon a le pouvoir de prédire les véritables tremblements de terre."}, {"g": "Soleil", "t": "Ce glouton dévore tout ce qui bouge. La plupart du temps, il reste tapi au fond de son marais, en guettant sa proie."}, {"g": "Lune", "t": "On dit que lorsqu’un banc de Barbicha jaillit hors de l’eau, un tremblement de terre est sur le point de se produire."}, {"g": "Ultra-Soleil", "t": "Il subjugue ses adversaires en déclenchant de violents séismes. Il racle le fond des marais pour se nourrir, avalant proies et vase au passage."}, {"g": "Ultra-Lune", "t": "Sa vision n’étant pas très bonne, il utilise ses barbillons pour capter les vibrations de l’eau et repérer ses proies."}, {"g": "Épée", "t": "Il fait son nid au fond des marais. Il ne se pose pas de question et avale toutes les créatures qui passent près de lui."}, {"g": "Bouclier", "t": "Il a besoin d’un marais entier pour vivre. Si un ennemi s’approche, il s’énerve et déclenche un séisme."}],
  341: [{"g": "Noir", "t": "Sa nature robuste lui permet de vivre sur n’importe quel terrain. Ses pinces ne lâchent jamais prise."}, {"g": "X", "t": "Sa nature robuste lui permet de prospérer dans n’importe quelles eaux, aussi polluées soient-elles."}, {"g": "Rubis Oméga", "t": "Les Écrapince étaient au départ des Pokémon étrangers importés comme animaux domestiques. Ils ont fini par retrouver leur état sauvage. Ce Pokémon est particulièrement robuste et sa population augmente sans arrêt."}, {"g": "Saphir Alpha", "t": "Écrapince attrape ses proies avec ses puissantes pinces. Pour la nourriture, il n’est pas difficile. Il mange de tout. Vivre dans de l’eau sale ne dérange pas ce Pokémon."}, {"g": "Ultra-Soleil", "t": "On voit souvent des Écrapince sur les plages. Il s’agit en fait de Pokémon relâchés par leurs Dresseurs, qui ne parvenaient pas les élever."}, {"g": "Ultra-Lune", "t": "Il peut s’adapter à n’importe quel environnement. Barpau et lui sont d’ailleurs les seuls Pokémon à vivre dans l’eau des égouts !"}, {"g": "Bouclier", "t": "Un Pokémon importé, retourné à l’état sauvage. Il s’adapte même aux rivières les plus polluées."}],
  342: [{"g": "Noir", "t": "C’est un voyou qui utilise ses pinces pour chasser les autres Pokémon hors de sa mare."}, {"g": "Y", "t": "C’est un voyou qui utilise ses pinces pour chasser les autres Pokémon hors de son territoire."}, {"g": "Rubis Oméga", "t": "Colhomard a un tempérament très violent, ce qui le pousse à défier tout ce qui passe près de lui. Certaines formes de vie refusent d’habiter dans les étangs occupés par ce Pokémon et désertent ces eaux."}, {"g": "Saphir Alpha", "t": "Colhomard mue et perd sa carapace régulièrement. Immédiatement après sa mue, sa nouvelle carapace est tendre et molle. Il s’enterre au fond des cours d’eau pour ne pas être attaqué avant que sa carapace ne soit assez dure."}, {"g": "Ultra-Soleil", "t": "D’un tempérament fougueux, il adore se battre, mais perd tout courage si ses pinces tombent. Il n’attend alors qu’une chose : leur repousse !"}, {"g": "Ultra-Lune", "t": "Ses pinces tombent facilement, mais sa chair est poisseuse et dégoûtante, contrairement à celle de Crabagarre et de Flingouste."}, {"g": "Épée", "t": "Ce Pokémon très coriace agite tout le temps ses énormes pinces. Il faut beaucoup de patience pour le dresser."}, {"g": "Bouclier", "t": "Il adore se battre et frappe comme une brute tous ceux qui approchent de sa mare."}],
  343: [{"g": "Noir", "t": "Il se déplace en tournoyant sur son pied. Ce Pokémon rare fut découvert dans de vieilles ruines."}, {"g": "X", "t": "Il se déplace en tournoyant sur son pied. Même mis sur la tête, il peut continuer à tourner."}, {"g": "Rubis Oméga", "t": "Balbuto se déplace en pivotant sur son unique pied. Des peintures rupestres montrant ce Pokémon vivant avec les hommes furent découvertes dans des ruines très anciennes."}, {"g": "Saphir Alpha", "t": "Dès qu’il repère ses congénères, Balbuto les rejoint et ils se mettent tous à crier en chœur. Ce Pokémon arrive à dormir en restant adroitement en équilibre."}, {"g": "Ultra-Soleil", "t": "Des esquisses de Pokémon ressemblant à des Balbuto ont été retrouvées dans des grottes jadis habitées par des hommes préhistoriques."}, {"g": "Ultra-Lune", "t": "Quand il aperçoit des congénères, il les rejoint en émettant des sons stridents. On en a trouvé beaucoup dans de très vieux cimetières."}, {"g": "Épée", "t": "Il se déplace en tournoyant sur son pied. On le voit parfois faire de même sur la tête."}, {"g": "Bouclier", "t": "Ce Pokémon découvert dans des ruines anciennes tourne sur lui-même pour se déplacer. Il se tient toujours sur un pied, même quand il dort."}],
  344: [{"g": "Noir", "t": "Une ancienne figurine d’argile qui s’est animée suite à son exposition à un rayon de lumière étrange."}, {"g": "Y", "t": "Une figurine d’argile fabriquée par une civilisation vieille de 20 000 ans et amenée à la vie."}, {"g": "Rubis Oméga", "t": "On raconte que les Kaorine sont des poupées de boue créées par les premiers hommes et qu’elles furent amenées à la vie après une exposition à un mystérieux rayon. Ce Pokémon se déplace en lévitant."}, {"g": "Saphir Alpha", "t": "Kaorine est un mystérieux Pokémon apparu sous la forme d’une statue en argile fabriquée par une civilisation vieille de plus de 20 000 ans. Ce Pokémon envoie des rayons avec ses mains."}, {"g": "Ultra-Soleil", "t": "Il fond au moindre contact avec l’eau et doit donc entourer son corps d’énergie psychique pour se protéger les jours de pluie."}, {"g": "Ultra-Lune", "t": "Il aurait été fabriqué par une civilisation ancienne, sur le modèle d’un objet mystérieux tombé du ciel. Ses bras peuvent tirer des lasers."}, {"g": "Épée", "t": "Ce Pokémon mystérieux serait né d’une figurine d’argile vieille de près de 20 000 ans."}, {"g": "Bouclier", "t": "Ce Pokémon aurait été créé à partir d’une poupée d’argile confectionnée par une ancienne civilisation. Il se déplace en lévitant."}],
  345: [{"g": "Noir", "t": "Il vivait au fond de la mer il y a 100 millions d’années. La science a permis de le ressusciter."}, {"g": "X", "t": "Il attrape ses proies avec ses tentacules-pétales. Il a disparu il y a cent millions d’années."}, {"g": "Rubis Oméga", "t": "L’espèce des Lilia s’est éteinte il y a environ 100 millions d’années. Cet ancien Pokémon s’accroche à un rocher, sous l’eau, et attrape ses proies à l’aide de ses tentacules en forme de pétales de fleur."}, {"g": "Saphir Alpha", "t": "Lilia est un Pokémon très ancien ressuscité à partir d’un fossile. Il reste en permanence fixé à un rocher. Ce Pokémon balaie l’horizon depuis son perchoir, immobile, en quête de proies."}, {"g": "Ultra-Soleil", "t": "Il vivait déjà dans les mers chaudes il y a fort longtemps. Il imite les algues pour masquer sa présence et gobe toute proie qui l’approche."}, {"g": "Ultra-Lune", "t": "Il s’accroche aux rochers grâce à ses ventouses puissantes. Une fois fixé, aucun courant marin, aussi violent soit-il, ne peut l’en déloger."}, {"g": "Épée", "t": "Reconstitué à partir d’un fossile, ce Pokémon vivait dans les mers chaudes il y a environ 100 millions d’années."}, {"g": "Bouclier", "t": "Accroché aux rochers des profondeurs, il attend qu’une proie s’approche de lui pour l’attraper avec ses tentacules en forme de pétales."}],
  346: [{"g": "Noir", "t": "Vit dans les hauts-fonds des mers chaudes. Il déterre sa proie du sable quand la marée se retire."}, {"g": "Y", "t": "Lorsqu’il chasse, Vacilys utilise ses huit tentacules. Il dissout sa proie à l’aide d’un puissant acide avant de l’avaler."}, {"g": "Rubis Oméga", "t": "Vacilys erre dans les profondeurs de l’océan pour chercher de la nourriture. Ce Pokémon peut allonger son cou à volonté et capturer ses proies à l’aide de ses huit tentacules."}, {"g": "Saphir Alpha", "t": "Le corps de Vacilys lui sert d’ancre et l’empêche d’être emporté quand la mer est déchaînée. Les tentacules de ce Pokémon sécrètent un puissant fluide digestif."}, {"g": "Ultra-Soleil", "t": "Il habitait généralement dans les hauts-fonds, mais parcourait le littoral en quête de proies lorsque la marée était basse."}, {"g": "Ultra-Lune", "t": "Ce carnivore des mers antiques attrape sa proie à l’aide de ses huit tentacules, puis la dissout avec ses sucs digestifs."}, {"g": "Épée", "t": "Il se déplace lentement avec ses petites pattes, mais il peut tripler la longueur de son cou et de ses tentacules pour capturer ses proies."}, {"g": "Bouclier", "t": "Il attrape ses proies à l’aide de ses tentacules, puis les dissout immédiatement avec ses sucs digestifs pour en absorber les nutriments."}],
  347: [{"g": "Noir", "t": "Un ancêtre Pokémon réanimé à partir d’un fossile. Il vivait en mer et chassait avec ses pinces."}, {"g": "X", "t": "C’est un Pokémon préhistorique. Caché derrière les rochers, il utilise ses pinces extensibles pour attraper ses proies."}, {"g": "Rubis Oméga", "t": "Anorith fut ressuscité à partir d’un fossile préhistorique. Ce Pokémon primitif vivait à l’époque dans les eaux tropicales. Il attrape fermement sa proie avec ses deux grandes pinces."}, {"g": "Saphir Alpha", "t": "On raconte qu’Anorith est l’un des ancêtres des Pokémon. Il nageait dans la mer originelle en faisant onduler les huit ailes placées sur les côtés de son corps."}, {"g": "Ultra-Soleil", "t": "Ce Pokémon ranimé à partir d’un fossile vivait dans des eaux très pures. Il ne pourrait donc pas s’acclimater aux océans actuels."}, {"g": "Ultra-Lune", "t": "Ce Pokémon Insecte préhistorique nageait apparemment à une vitesse surprenante grâce à ses huit « ailes »."}, {"g": "Épée", "t": "Restauré à partir d’un fossile, ce Pokémon vivait dans l’océan il y a environ 100 millions d’années et chassait ses proies avec ses deux pinces."}, {"g": "Bouclier", "t": "Ce Pokémon peut nager très vite en agitant ses huit ailes comme des rames de bateau. Il fait partie des ancêtres des Pokémon Insecte."}],
  348: [{"g": "Noir", "t": "Il a gagné la côte après son évolution. Une armure robuste recouvre son corps."}, {"g": "X", "t": "Ce Pokémon au corps blindé peut allonger ou rétracter ses énormes pinces pour embrocher ses proies."}, {"g": "Y", "t": "Rien ne peut transpercer la cuirasse d’Armaldo. Ce Pokémon embroche ses proies avec ses griffes pour les avaler plus facilement."}, {"g": "Rubis Oméga", "t": "Le puissant blindage d’Armaldo peut repousser toute attaque. Les énormes pinces de ce Pokémon peuvent s’allonger ou se rétracter. Elles peuvent transpercer une plaque d’acier."}, {"g": "Saphir Alpha", "t": "Armaldo fait partie d’une espèce de Pokémon qui s’est éteinte à l’époque préhistorique. On raconte que ce Pokémon marchait sur ses pattes arrière, ce qui facilitait sa vie sur la terre ferme."}, {"g": "Ultra-Soleil", "t": "Ce Pokémon terrestre avait pour habitude d’aller chasser ses proies en mer à l’aide de ses armes de prédilection : ses griffes acérées."}, {"g": "Ultra-Lune", "t": "Considéré comme l’un des ancêtres des Pokémon Insecte, il avait quitté la mer pour s’installer sur la terre ferme."}, {"g": "Épée", "t": "Depuis son évolution, il vit sur la terre ferme. Ses membres inférieurs se sont développés et ses coups de queue sont dévastateurs."}, {"g": "Bouclier", "t": "Bien que vivant sur la terre ferme, il est très bon nageur. Il plonge dans la mer à la recherche de proies et les abat avec ses pinces acérées."}],
  349: [{"g": "Noir", "t": "Ce Pokémon a peut-être un physique disgracieux, mais il est robuste et peut survivre dans très peu d’eau."}, {"g": "X", "t": "Il peut vivre dans les fleuves et les lacs pollués car il mange de tout. Personne ne se soucie de lui."}, {"g": "Y", "t": "Son apparence est pathétique. Il forme des bancs dans les rivières riches en plantes aquatiques."}, {"g": "Rubis Oméga", "t": "Les nageoires de Barpau sont abîmées et déchirées dès sa naissance. Ce Pokémon est généralement ignoré à cause de son apparence miséreuse. Il peut vivre dans la mer ou en eau douce."}, {"g": "Saphir Alpha", "t": "Même si le corps de Barpau est en lambeaux, il reste tenace et obstiné, ce qui lui permet de survivre partout. Cependant, ce Pokémon est très lent et un peu bête, ce qui en fait une proie facile."}, {"g": "Soleil", "t": "Ce Pokémon n’a pas beaucoup d’adeptes, du fait de son air miteux. Il est pourtant robuste et n’a pas peur de nager en eaux troubles."}, {"g": "Lune", "t": "Comme il est tout de même franchement laid, ce Pokémon a un succès très mitigé. Sa grande vitalité fait néanmoins l’objet de moult études."}, {"g": "Ultra-Soleil", "t": "Son apparence peu ragoûtante repousse les prédateurs et dissuade les gens de le pêcher. Sa population augmente donc rapidement."}, {"g": "Ultra-Lune", "t": "En raison de sa laideur, la plupart des gens détournent le regard quand ils le croisent. Il a cependant des fans qui le collectionnent."}],
  350: [{"g": "Noir", "t": "Ses splendides écailles aux couleurs de l’arc-en-ciel changent de teinte selon l’angle de vue."}, {"g": "X", "t": "Milobellus est d’une beauté à couper le souffle. Ceux qui en voient un perdent aussitôt l’envie de se battre."}, {"g": "Y", "t": "Le plus beau Pokémon du monde. De nombreuses œuvres d’art représentent Milobellus."}, {"g": "Rubis Oméga", "t": "Certains prétendent que Milobellus est le plus beau de tous les Pokémon. Il a le pouvoir d’apaiser certaines émotions comme la colère ou l’hostilité, afin d’éviter les querelles inutiles."}, {"g": "Saphir Alpha", "t": "Milobellus vit au fond des grands lacs. Lorsque le corps de ce Pokémon devient rose vif, il libère une pulsation d’énergie, capable d’apaiser les esprits agités."}, {"g": "Soleil", "t": "Célébré comme l’un des plus beaux Pokémon, il sert souvent de modèle et d’inspiration aux plus grands artistes."}, {"g": "Lune", "t": "Il vit au fond des lacs à l’eau claire. Il se révèle aux hommes en temps de guerre et apaise leurs cœurs meurtris."}, {"g": "Ultra-Soleil", "t": "Il est considéré comme le plus beau de tous les Pokémon, mais il est loin de faire l’unanimité auprès des fans de Barpau !"}, {"g": "Ultra-Lune", "t": "Le simple fait d’apercevoir cet habitant du fond des grands lacs permettrait de purifier son cœur des troubles qui l’habitent."}, {"g": "Bouclier", "t": "On dit que la beauté de ce Pokémon est telle qu’elle apaise l’esprit de ceux qui le voient."}],
  351: [{"g": "Noir", "t": "Son aspect change avec la météo. On a récemment découvert que ses molécules étaient pareilles à l’eau."}, {"g": "X", "t": "Les variations de température ou d’humidité affectent sa structure cellulaire et son apparence."}, {"g": "Y", "t": "Morphéo a la capacité de changer son apparence en fonction du temps. Il utilise la force de la nature pour combattre."}, {"g": "Rubis Oméga", "t": "L’apparence de Morphéo change en fonction du temps. Ce Pokémon a appris à utiliser l’immense pouvoir de la nature pour protéger son corps minuscule."}, {"g": "Saphir Alpha", "t": "Morphéo emprunte le pouvoir de la nature pour prendre l’apparence du soleil, de la pluie ou de la neige. Le type de ce Pokémon change en fonction du temps."}, {"g": "Soleil", "t": "Son apparence change en fonction du temps. Les changements de température et d’humidité influenceraient sa structure cellulaire."}, {"g": "Lune", "t": "Comme ses cellules réagissent au moindre changement de température ou d’humidité, il ne contrôle pas ses changements d’apparence."}, {"g": "Ultra-Soleil", "t": "Il change de forme en fonction de la météo, mais ce phénomène serait en fait une réaction chimique indépendante de sa volonté."}, {"g": "Ultra-Lune", "t": "Il n’y a pas que son apparence qui change en fonction de la météo : son tempérament aussi ! Plus il y a de vent, plus il se montre agressif."}],
  352: [{"g": "Noir", "t": "Il change de couleur à volonté, mais le motif en zigzag qui orne son ventre reste le même."}, {"g": "Y", "t": "Il se fond dans son environnement en changeant de couleur, mais le motif sur son ventre reste le même."}, {"g": "Rubis Oméga", "t": "Kecleon est capable de modifier les couleurs de son corps pour se fondre dans son environnement. Il y a cependant une exception : ce Pokémon ne peut pas modifier la figure géométrique en zigzag sur son ventre."}, {"g": "Saphir Alpha", "t": "Kecleon change la couleur de son corps pour se fondre dans son environnement, ce qui lui permet de s’approcher de sa proie sans être repéré. Il envoie ensuite sa grande langue élastique pour piéger sa proie qui ne se doute de rien."}, {"g": "Ultra-Soleil", "t": "Il change de couleur pour se camoufler, mais si on cesse de lui prêter attention pendant trop longtemps, il se vexe et ne se montre plus..."}, {"g": "Ultra-Lune", "t": "Sa couleur change quand il se cache, mais varie aussi selon son humeur et son état de santé : plus il est en forme, plus sa couleur est vive."}],
  353: [{"g": "Noir", "t": "Il aime le goût de la vengeance. Ils vivent en rangs sous les gouttières des gens vindicatifs."}, {"g": "X", "t": "Ce Pokémon, très actif la nuit, utilise sa corne pour se repaître de rancune ou de jalousie."}, {"g": "Y", "t": "Il aime le goût de la vengeance. Les Pokémon de cette espèce vivent en rangs sous les gouttières des gens vindicatifs."}, {"g": "Rubis Oméga", "t": "Les Polichombr sont attirés par les sentiments de jalousie et les esprits revanchards. Si quelqu’un veut se venger, ces Pokémon apparaissent en nuée et s’alignent devant la porte des gens concernés."}, {"g": "Saphir Alpha", "t": "Polichombr grandit en se nourrissant des émotions négatives des gens, comme le désir de vengeance ou la jalousie. Il erre dans les villes à la recherche des gens qui n’ont pas le moral."}, {"g": "Ultra-Soleil", "t": "Les gens apprécient ce Pokémon, car il se nourrit de leurs émotions négatives telles que la rancœur et la jalousie."}, {"g": "Ultra-Lune", "t": "Il existe un proverbe ancien qui dit : « Fuis la demeure où les Polichombr se rassemblent en nombre à la pénombre. »"}],
  354: [{"g": "Noir", "t": "Une poupée mue par la tristesse qui la ronge depuis qu’on l’a délaissée. Elle recherche son propriétaire."}, {"g": "Y", "t": "Un très violent sentiment de haine a transformé une poupée de chiffon en Branette. S’il ouvre la bouche, une énergie négative s’en échappe."}, {"g": "Rubis Oméga", "t": "En plantant des aiguilles dans son propre corps, Branette génère de l’énergie permettant de lancer de puissantes malédictions. Au départ, ce Pokémon n’était qu’une malheureuse peluche jetée à la poubelle."}, {"g": "Saphir Alpha", "t": "Une énergie maudite a pénétré le rembourrage d’une vieille peluche abandonnée, donnant ainsi vie à Branette. L’énergie de ce Pokémon s’échappe s’il ouvre la bouche."}, {"g": "Ultra-Soleil", "t": "Animée par la rancune, cette poupée abandonnée traque son ancien propriétaire pour se venger."}, {"g": "Ultra-Lune", "t": "Il est né de la rancune qu’il a ressentie quand il a été abandonné. Il redevient apparemment une poupée si l’on en prend grand soin."}],
  355: [{"g": "Noir", "t": "Les cris des enfants l’amusent. Il effraie les moins sages d’entre eux en traversant les murs."}, {"g": "X", "t": "Il poursuit assidûment sa proie, où qu’elle aille. Il n’abandonne sa traque qu’au lever du soleil."}, {"g": "Y", "t": "On dit que Skelénox emporte les enfants désobéissants à la nuit tombée."}, {"g": "Rubis Oméga", "t": "Skelénox peut traverser n’importe quel mur, même le plus épais. Une fois que ce Pokémon a choisi une cible, il la pourchasse sans relâche jusqu’à l’aube."}, {"g": "Saphir Alpha", "t": "Skelénox erre seul dans l’obscurité de la nuit. On fait souvent peur aux enfants en leur disant que ce Pokémon viendra les chercher s’ils n’obéissent pas à leur maman."}, {"g": "Épée", "t": "On dit que ce Pokémon emporte les enfants désobéissants à la nuit tombée."}, {"g": "Bouclier", "t": "Ce Pokémon devient invisible pour se rapprocher furtivement de ses proies. Il a le pouvoir de traverser les murs."}],
  356: [{"g": "Noir", "t": "Il cherche des feux follets pour les avaler. Ce qui se passe alors dans son corps est un mystère."}, {"g": "X", "t": "Il aspire l’âme de ceux qui regardent dans son corps creux où rougeoie son unique œil."}, {"g": "Y", "t": "Son corps est creux. On raconte que celui qui regarde à l’intérieur finira aspiré par le néant."}, {"g": "Rubis Oméga", "t": "Le corps de Téraclope est totalement creux. Il n’y a rien du tout à l’intérieur. On raconte que son corps est comme un trou noir. Ce Pokémon peut absorber n’importe quoi, mais rien n’en ressort jamais."}, {"g": "Saphir Alpha", "t": "Téraclope peut absorber des objets de toute taille. Ce Pokémon hypnotise son ennemi en faisant des gestes macabres et en attirant l’attention sur son unique œil. L’ennemi hypnotisé obéit ensuite aux ordres de Téraclope."}, {"g": "Épée", "t": "Son corps est complètement creux. Quand il ouvre la bouche, il aspire tout ce qui passe près de lui, à la façon d’un trou noir."}, {"g": "Bouclier", "t": "Il cherche des feux follets pour les avaler. Ce qu’il se passe alors à l’intérieur de son corps vide est un mystère."}],
  357: [{"g": "Noir", "t": "À force de toujours manger le même fruit succulent, il en pousse à la base de son cou."}, {"g": "X", "t": "Ses grandes feuilles lui servent à voler. Il distribue les fruits qui pendent à son cou aux enfants, qui s’en régalent."}, {"g": "Y", "t": "Les succulents fruits de son cou poussent deux fois l’an et font le régal des enfants des tropiques."}, {"g": "Rubis Oméga", "t": "Les enfants adorent les fruits autour du cou de Tropius. Apparemment, son penchant pour les fruits l’a conduit à en faire pousser sur son propre corps. Il les aime tant qu’il en mange sans arrêt."}, {"g": "Saphir Alpha", "t": "Les enfants des tropiques mangent les fruits qui poussent autour du cou de Tropius pour leur goûter. Ce Pokémon peut voler en agitant les feuilles situées sur son dos, comme s’il s’agissait d’ailes."}, {"g": "Ultra-Soleil", "t": "Les fruits qui poussent sur le cou des Tropius d’Alola sont si doux qu’ils surclassent ceux des autres régions."}, {"g": "Ultra-Lune", "t": "Dans les régions où il fait chaud, on trouve des fermes dédiées à l’élevage de ce Pokémon, très apprécié pour les fruits poussant sur son cou."}],
  358: [{"g": "Noir", "t": "Ses cris se répercutent dans son corps creux avant d’exploser en notes mélodieuses et saisissantes."}, {"g": "X", "t": "Il se suspend sous une branche ou un auvent avec la ventouse de sa tête. Son langage comporte sept cris."}, {"g": "Y", "t": "Il émet des cris à ultrasons et chevauche le vent pour parcourir de grandes distances."}, {"g": "Rubis Oméga", "t": "Éoko fait résonner son cri dans son corps creux. Lorsque ce Pokémon est en colère, les échos de son cri génèrent des ultrasons capables d’envoyer voler des ennemis."}, {"g": "Saphir Alpha", "t": "Lorsqu’il y a beaucoup de vent, Éoko pousse des cris, accroché à une branche ou à un auvent par une ventouse placée sur sa tête. Ce Pokémon attrape des Baies avec sa longue queue pour les manger."}],
  359: [{"g": "Noir", "t": "La capacité de sa corne à sentir les catastrophes ayant trop attiré l’attention sur lui, il vit reclus."}, {"g": "X", "t": "Il pressent les catastrophes et n’apparaît aux gens que pour les prévenir d’un danger imminent."}, {"g": "Y", "t": "Absol apparaît dès qu’une catastrophe naturelle est sur le point de se produire. Pour cette raison, les gens ont longtemps pensé qu’il portait malheur."}, {"g": "Rubis Oméga", "t": "Chaque fois qu’Absol apparaît devant des gens, une catastrophe comme un tremblement de terre ou un raz-de-marée survient peu de temps après. Il est devenu tristement célèbre sous l’appellation de Pokémon désastreux."}, {"g": "Saphir Alpha", "t": "Absol a le pouvoir de prédire les catastrophes naturelles. Il vit dans un milieu montagneux aride et accidenté. Ce Pokémon s’éloigne très rarement des montagnes."}, {"g": "Soleil", "t": "Autrefois la cible de superstitions le rendant responsable des catastrophes, il s’est retiré dans les montagnes pour y échapper."}, {"g": "Lune", "t": "On le dit annonciateur de catastrophes, mais c’est en fait un Pokémon paisible. Il prévient les hommes de l’imminence des cataclysmes."}, {"g": "Ultra-Soleil", "t": "Contrairement à ce que son apparence suggère, il s’agit d’un Pokémon bienveillant qui protège les champs et annonce les catastrophes."}, {"g": "Ultra-Lune", "t": "Les anciens le détestent et le nomment « le Pokémon Désastre », mais d’autres l’apprécient pour son aptitude à prédire les catastrophes."}, {"g": "Épée", "t": "Il court par monts et par vaux, rapide comme le vent. Sa corne arquée lui permet de percevoir les signes avant-coureurs des cataclysmes."}, {"g": "Bouclier", "t": "Sa capacité à pressentir le danger lui a autrefois valu la réputation de porter malheur."}],
  360: [{"g": "Noir", "t": "Il se muscle en bousculant ses semblables lors de mêlées. Il raffole des fruits sucrés."}, {"g": "X", "t": "Okéoké adore se déplacer en groupe. Ils se réunissent souvent pour dormir la nuit dans les cavernes."}, {"g": "Rubis Oméga", "t": "Okéoké a toujours un grand sourire qui illumine son visage. On peut savoir s’il est en colère en regardant sa queue. Lorsqu’il est furieux, sa queue remue en frappant le sol."}, {"g": "Saphir Alpha", "t": "Les Okéoké se rassemblent quand la nuit est claire pour jouer à se presser les uns contre les autres. En se poussant, ces Pokémon améliorent leur endurance et s’entraînent à renvoyer de puissantes contre-attaques."}, {"g": "Épée", "t": "Il fait toutes ses activités en groupe. L’une d’elles consiste à se bousculer mutuellement afin de s’endurcir."}, {"g": "Bouclier", "t": "Ces Pokémon adorent se déplacer en groupe. Ils se blottissent les uns contre les autres dans des cavernes pour dormir."}],
  361: [{"g": "Noir", "t": "On dit que des groupes entiers de Stalgamin vivent en harmonie sous des feuilles gigantesques."}, {"g": "Y", "t": "Selon un vieux dicton des régions enneigées : « Stalgamin dans la maison, richesse à l’horizon »."}, {"g": "Rubis Oméga", "t": "Les Stalgamin vivent dans les régions enneigées. Pendant les saisons sans neige, comme le printemps et l’été, ces Pokémon se retirent pour vivre dans les cavernes, au milieu des stalactites et des stalagmites."}, {"g": "Saphir Alpha", "t": "Stalgamin survit en se nourrissant uniquement de neige et d’eau. De vieilles légendes racontent que les maisons visitées par ce Pokémon sont assurées d’être prospères pendant plusieurs générations."}, {"g": "Soleil", "t": "De nombreux spécimens de ce Pokémon vivent dans la région d’Alola. On dit que les maisons abritant un Stalgamin seront prospères."}, {"g": "Lune", "t": "Il ne peut voir le jour que dans les plus froides contrées. Il s’accommode parfaitement de températures atteignant les -100 °C."}, {"g": "Ultra-Soleil", "t": "Il se nourrit principalement de neige et de glace. Le climat chaud d’Alola le contraint à vivre dans des lieux bien spécifiques."}, {"g": "Ultra-Lune", "t": "Il semblerait que toute personne aisée ayant grandi dans les régions enneigées se rappelle avoir joué avec un Stalgamin étant enfant."}, {"g": "Épée", "t": "Quand ce Pokémon apparaît la nuit, il provoque de fortes chutes de neige. Il se nourrit de glace et de neige."}, {"g": "Bouclier", "t": "Il ne peut vivre que dans les plus froides contrées. Il s’accommode parfaitement de températures atteignant les - 100 °C."}],
  362: [{"g": "Noir", "t": "Il empêche ses proies de prendre la fuite en gelant instantanément l’humidité de l’air."}, {"g": "X", "t": "Il gèle l’humidité de l’air pour former une armure de glace protectrice autour de son corps."}, {"g": "Y", "t": "Il a le pouvoir de geler l’humidité ambiante en un instant et peut ainsi pétrifier ses proies."}, {"g": "Rubis Oméga", "t": "Le corps de Oniglali est fait de rochers qu’il endurcit grâce à une couche de glace. Ce Pokémon a le pouvoir de geler l’humidité ambiante et de lui donner n’importe quelle forme."}, {"g": "Saphir Alpha", "t": "Oniglali a le pouvoir de contrôler la glace à volonté. Par exemple, il peut geler sa proie sur place. Une fois la proie immobilisée, ce Pokémon la mange sans se presser."}, {"g": "Soleil", "t": "La légende veut qu’il naisse de la détresse et de la rancœur des alpinistes égarés dans les cimes enneigées."}, {"g": "Lune", "t": "Le souffle glacé qui sort de sa large gueule lui permet de congeler instantanément ses proies. Il les croque ensuite comme des glaçons."}, {"g": "Ultra-Soleil", "t": "Il gèle ses proies avant de les croquer goulûment, même s’il préfère largement les Pokémon déjà glacés, comme les Sorbébé."}, {"g": "Ultra-Lune", "t": "Il gèle les particules d’eau présentes dans l’air pour se couvrir d’une carapace de glace et ainsi pallier la fragilité de son corps."}, {"g": "Épée", "t": "Son corps constitué de glace ne peut pas fondre, même s’il est exposé au feu. Il peut geler l’humidité contenue dans l’air instantanément."}, {"g": "Bouclier", "t": "Il a le pouvoir de geler l’humidité ambiante en un instant et peut ainsi immobiliser ses proies."}],
  363: [{"g": "Noir", "t": "Il gagne la côte en roulant sur les blocs de glace car sa morphologie n’est pas adaptée à la nage."}, {"g": "X", "t": "Il se déplace en roulant, car il n’est pas doué pour la nage. Quand il est heureux, il applaudit avec ses nageoires."}, {"g": "Y", "t": "Son corps est couvert d’une douce fourrure. Elle le protège du sentiment de froid quand il se déplace en roulant sur la glace."}, {"g": "Rubis Oméga", "t": "Obalie est bien plus rapide quand il roule que quand il marche. Lorsque des groupes de ce Pokémon mangent, ils applaudissent tous en même temps pour montrer qu’ils sont contents. Leurs repas sont très bruyants."}, {"g": "Saphir Alpha", "t": "Obalie voyage toujours en faisant rouler son corps tout rond. Lorsque la saison des neiges arrive, on peut voir ce Pokémon rouler sur la glace et traverser la mer."}, {"g": "Épée", "t": "Grâce à son corps composé d’une épaisse couche de graisse qui lui donne sa forme ronde, il se déplace plus vite en roulant qu’en marchant."}, {"g": "Bouclier", "t": "Il scrute la mer en se laissant porter par les vagues. Lorsqu’il repère des proies, il avertit les Kaimorse du groupe."}],
  364: [{"g": "Noir", "t": "Il fait souvent tourner des objets sur son museau pour connaître leur odeur et leur texture."}, {"g": "X", "t": "Il utilise son museau hypersensible pour toucher et comprendre tout ce qu’il voit pour la première fois."}, {"g": "Y", "t": "Pour s’amuser, il fait tourner tout ce qui est rond sur son museau, qu’il s’agisse de Poké Balls ou d’Obalie."}, {"g": "Rubis Oméga", "t": "Phogleur a pris l’habitude de jongler avec tout ce qu’il découvre pour la première fois. Ce Pokémon se divertit parfois en faisant tourner un Obalie sur le bout de son museau."}, {"g": "Saphir Alpha", "t": "Phogleur tient souvent quelque chose en équilibre sur son museau et le fait rouler. Pendant ce temps, ce Pokémon peut sentir l’odeur et la texture de l’objet pour savoir s’il lui plaît ou pas."}, {"g": "Épée", "t": "Cet habitant de la banquise attrape ses proies en les repérant à l’odeur quand il nage."}, {"g": "Bouclier", "t": "Il ne peut pas s’empêcher de faire tourner sur son museau tout ce qui a une forme sphérique, comme les Obalie ou les Poké Balls."}],
  365: [{"g": "Noir", "t": "Il brise la glace avec ses grosses défenses. Sa graisse le protège du froid, mais aussi des attaques."}, {"g": "Y", "t": "Ses robustes défenses pulvérisent la glace, et son épaisse couche de graisse repousse les attaques."}, {"g": "Rubis Oméga", "t": "Les deux énormes défenses de Kaimorse peuvent détruire en un seul coup des blocs de glace de plus de 10 t. L’épaisse couche de graisse de ce Pokémon l’isole lorsque la température est en dessous de zéro."}, {"g": "Saphir Alpha", "t": "Kaimorse nage dans l’eau glacée et détruit les icebergs sur son passage à l’aide de ses grandes et impressionnantes défenses. Son épaisse couche de graisse lui permet de faire rebondir les attaques ennemies."}, {"g": "Épée", "t": "Ils vivent en groupes de 20 à 30 individus. Si un ennemi les attaque, le chef s’interpose pour tous les protéger, au péril de sa vie."}, {"g": "Bouclier", "t": "Ses défenses poussent tout au long de sa vie. Si l’une d’elles se brise au cours d’un combat, au bout d’un an, elle aura repoussé entièrement."}],
  366: [{"g": "Noir", "t": "Il ne produit qu’une perle durant son existence. On raconte qu’elle amplifie les pouvoirs psychiques."}, {"g": "X", "t": "Il ne produit qu’une perle durant son existence, quand il évolue. Elle amplifie les pouvoirs psychiques."}, {"g": "Y", "t": "Ce Pokémon ferme sa coquille pour se protéger du danger. Il ne crée qu’une seule perle de toute sa vie, mais celle-ci est magnifique."}, {"g": "Rubis Oméga", "t": "La puissante coquille de Coquiperl ne sert pas qu’à le protéger. Elle lui permet également de pincer et d’attraper sa proie. Une coquille de Coquiperl adulte porte souvent de nombreuses égratignures et éraflures."}, {"g": "Saphir Alpha", "t": "Coquiperl grandit protégé par sa coquille dure comme de la pierre. Lorsque son corps devient trop grand pour sa coquille, cela signifie que ce Pokémon va bientôt évoluer."}, {"g": "Ultra-Soleil", "t": "Malgré les apparences, c’est un carnivore qui attrape sa proie avec sa coquille et l’immobilise jusqu’à ce qu’elle ne se débatte plus."}, {"g": "Ultra-Lune", "t": "La perle de Coquiperl est tellement précieuse qu’elle peut valoir plus de dix fois la valeur de celle de Kokiyas."}],
  367: [{"g": "Noir", "t": "Il vit loin sous la mer. Il appâte les proies crédules avec sa queue qui rappelle un petit poisson."}, {"g": "X", "t": "Il vit dans les abysses, là où la lumière ne va jamais. Il allume le bout de sa queue, qui ressemble à un poisson, pour attirer ses proies."}, {"g": "Rubis Oméga", "t": "L’existence de Serpang fut longtemps ignorée, car il vit dans les profondeurs abyssales des océans. Les yeux de ce Pokémon sont excellents et peuvent même voir à travers les eaux troubles des grandes profondeurs."}, {"g": "Saphir Alpha", "t": "La queue de Serpang est en forme de poisson. Il l’utilise pour attirer sa proie qu’il avale en une fois grâce à sa bouche béante. Ce Pokémon nage en tortillant son corps comme un serpent."}, {"g": "Ultra-Soleil", "t": "Ce piètre nageur se sert de sa queue pour appâter ses proies. Il les gobe si elles approchent de trop près."}, {"g": "Ultra-Lune", "t": "Il habite dans les profondeurs de l’océan. Un Serpang trouvé sur la plage serait un mauvais présage."}],
  368: [{"g": "Noir", "t": "Au printemps, son corps rose se fait plus vif sans que l’on sache pourquoi. Il vit au fond de la mer."}, {"g": "Y", "t": "Sa façon de se déplacer sous l’eau est d’une élégance incomparable. Du bout de sa fine bouche, il se nourrit des algues qui poussent entre les rochers."}, {"g": "Rubis Oméga", "t": "Rosabyss vit dans les profondeurs des mers du sud. Son corps est conçu pour supporter l’énorme pression des profondeurs abyssales. Du coup, le corps de ce Pokémon n’est pas endommagé par les attaques ordinaires."}, {"g": "Saphir Alpha", "t": "Même si Rosabyss est l’image même de l’élégance et de la beauté quand il nage, il est aussi très cruel. Quand il repère sa proie, ce Pokémon insère sa fine bouche dans le corps de sa proie et aspire ses fluides corporels."}, {"g": "Ultra-Soleil", "t": "La température de l’eau influence la couleur de son corps. À Alola, elle est tellement vive qu’elle en est éblouissante."}, {"g": "Ultra-Lune", "t": "Il se nourrit en aspirant les fluides corporels de ses proies. Le reste tombe au fond de la mer, nourrissant ainsi d’autres Pokémon."}],
  369: [{"g": "Noir", "t": "Un Pokémon rare aperçu lors d’une exploration sous-marine. Il n’a pas évolué depuis 100 millions d’années."}, {"g": "X", "t": "Relicanth n’a connu aucune évolution depuis 100 millions d’années. Il a été découvert pendant une exploration dans les profondeurs de la mer."}, {"g": "Rubis Oméga", "t": "Les Relicanth sont une espèce de Pokémon qui a existé pendant 100 millions d’années sans jamais changer de forme. Ce Pokémon antique se nourrit d’organismes microscopiques avec sa bouche édentée."}, {"g": "Saphir Alpha", "t": "Relicanth est une espèce rare découverte pendant des explorations sous-marines. Son corps peut supporter l’énorme pression des profondeurs océaniques. Il est recouvert d’écailles semblables à des pierres."}, {"g": "Soleil", "t": "Il n’a pas changé d’apparence en 100 millions d’années. La densité de sa couche graisseuse l’aide à supporter la pression des grands fonds."}, {"g": "Lune", "t": "Il a été découvert complètement par hasard au fin fond de l’océan. Sa dentition déplorable le contraint à se nourrir de micro-organismes."}, {"g": "Ultra-Soleil", "t": "On a longtemps cru son espèce disparue. Son nom serait une déformation du patronyme de la personne qui l’a découvert."}, {"g": "Ultra-Lune", "t": "On raconte que s’il n’a pas changé d’apparence en 100 millions d’années, c’est parce qu’il a atteint le stade de forme de vie parfaite."}, {"g": "Épée", "t": "Il peut supporter la pression des profondeurs grâce à ses écailles aussi solides que le roc et à ses vessies natatoires remplies de graisse."}, {"g": "Bouclier", "t": "Découvert lors d’une expédition dans les abysses, son apparence inchangée depuis 100 millions d’années lui a valu le surnom de « fossile vivant »."}],
  370: [{"g": "Noir", "t": "Un habitant des mers chaudes. On dit que le couple qui tombe sur ce Pokémon connaîtra l’amour éternel."}, {"g": "Y", "t": "Pendant la saison des amours, d’innombrables Lovdisc se réunissent près des barrières de corail et donnent l’impression que la mer est rose."}, {"g": "Rubis Oméga", "t": "Lovdisc vit dans les mers peu profondes des tropiques. Ce Pokémon en forme de cœur a gagné son nom en nageant derrière les couples d’amoureux qu’il repérait dans les eaux claires de l’océan."}, {"g": "Saphir Alpha", "t": "Le corps en forme de cœur de Lovdisc représente l’amour et les sentiments. On raconte qu’un couple qui rencontre ce Pokémon s’aimera jusqu’à la fin des temps."}, {"g": "Soleil", "t": "Un Lovdisc esseulé perd tout entrain et baisse sa garde. Le Bekipan n’attend que cela pour frapper."}, {"g": "Lune", "t": "Comme il est très populaire auprès des amoureux, les hôtels fréquentés par les couples en lune de miel en ont souvent dans leur piscine."}, {"g": "Ultra-Soleil", "t": "Il fut un temps où les gens le capturaient en masse pour s’approprier ses écailles en forme de cœur, supposées porter chance en amour."}, {"g": "Ultra-Lune", "t": "Il vit dans les récifs coralliens des mers chaudes, et aime particulièrement dormir entre les cornes des Corayon."}],
  371: [{"g": "Noir", "t": "Il rêve de pouvoir voler un jour. Pour l’heure, il s’entraîne en sautant du haut des falaises."}, {"g": "X", "t": "Il réduit en miettes les plus gros rochers grâce à son cou musculeux et à sa tête dure comme l’acier."}, {"g": "Rubis Oméga", "t": "Draby rêve de pouvoir un jour s’élancer dans les cieux. Bien que voué à l’échec, ce Pokémon se jette des falaises pour essayer de voler. À force, sa tête est devenue aussi dure que de l’acier."}, {"g": "Saphir Alpha", "t": "Draby rêve depuis toujours de voler au milieu des nuages. Ce Pokémon éclate d’énormes rochers avec sa tête, comme pour exorciser le fait qu’il ne puisse pas voler."}, {"g": "Soleil", "t": "Sa lubie de voler lui viendrait d’une information contenue dans ses gènes."}, {"g": "Lune", "t": "Il charge sans distinction tout ce qui l’entoure, distribuant allègrement les coups de tête. Il extériorise ainsi son stress de ne pas voler."}, {"g": "Ultra-Soleil", "t": "Il est jaloux des Pokémon oiseaux. Dès qu’il en voit un voler, il donne des coups de tête dans tous les sens et détruit tout sur son passage."}, {"g": "Ultra-Lune", "t": "Selon certaines théories, il donne des coups de tête pour stimuler les cellules qui lui permettent d’évoluer."}, {"g": "Épée", "t": "Tous les jours, il se jette du haut d’une falaise pour renforcer son corps, dans l’espoir de pouvoir voler un jour."}, {"g": "Bouclier", "t": "La tête de ce Pokémon solitaire est si solide qu’il est capable de fendre en deux un rocher d’un seul coup."}],
  372: [{"g": "Noir", "t": "Ses cellules ont commencé à changer dans sa robuste coquille. Il la perd en évoluant."}, {"g": "Y", "t": "Son corps renforcé repousse toutes les attaques. Cependant, le poids important de cette armure empêche Drackhaus de se déplacer librement."}, {"g": "Rubis Oméga", "t": "À l’intérieur de la carapace blindée de Drackhaus, ses cellules sont en pleine transformation pour créer un nouveau corps. La carapace de ce Pokémon est très lourde, ce qui rend ses mouvements très lents."}, {"g": "Saphir Alpha", "t": "Des excroissances osseuses recouvrent le corps de Drackhaus. Cette carapace est extrêmement dure et le protège des attaques ennemies. En attendant son évolution, ce Pokémon reste caché dans une caverne."}, {"g": "Soleil", "t": "À l’intérieur de sa carapace, ses cellules subissent un bouleversement cataclysmique. Il se prépare ainsi à son évolution."}, {"g": "Lune", "t": "Il se cache sans bouger au fond de sa grotte, sans eau ni nourriture. Les raisons de sa survie sont, à franchement parler, un véritable mystère."}, {"g": "Ultra-Soleil", "t": "À l’intérieur de sa carapace, dont la composition s’apparente à celle des os, son corps subit une véritable révolution cellulaire."}, {"g": "Ultra-Lune", "t": "Il habite au fond des grottes et, bien à l’abri au creux de sa solide carapace, il rêve du jour où il pourra enfin s’envoler dans les cieux."}, {"g": "Épée", "t": "Ce Pokémon emmagasine l’énergie nécessaire à son évolution sous sa carapace dont la composition est identique à celles des os."}, {"g": "Bouclier", "t": "Il se prive de nourriture, résistant à la faim. On dit que son évolution commence lorsque ses réserves d’énergie sont épuisées."}],
  373: [{"g": "Noir", "t": "À force de rêver de pouvoir voler, sa structure cellulaire a évolué et il s’est vu pousser des ailes."}, {"g": "X", "t": "Une fois enragé, plus rien ne peut arrêter Drattak. Il détruit tout ce qu’il voit en utilisant ses griffes ou en crachant des flammes."}, {"g": "Y", "t": "Ses colères sont dévastatrices. Il s’envole et brûle tout sur son passage."}, {"g": "Rubis Oméga", "t": "Drattak a ce physique grâce à son désir de pouvoir s’envoler. On dit que cette puissante envie a déclenché une soudaine mutation moléculaire de ce Pokémon, faisant surgir de splendides ailes."}, {"g": "Saphir Alpha", "t": "En évoluant en Drattak, ce Pokémon réalise un rêve d’enfance, celui d’avoir des ailes. Pour exprimer sa joie, il vole et plane dans les cieux en crachant des flammes."}, {"g": "Soleil", "t": "Quand il est pris de colère, il perd toute mesure et détruit ce qui l’entoure. Tant qu’il lui reste une once d’énergie, il continue de tout dévaster."}, {"g": "Lune", "t": "Il fend l’air et virevolte dans le ciel grâce à ses ailes fraîchement formées. De bonheur, il crache du feu et dévaste toutes les cultures au sol."}, {"g": "Ultra-Soleil", "t": "Maintenant qu’il peut enfin voler, il passe tout son temps à parcourir le ciel et ne redescend que quand il tombe d’épuisement."}, {"g": "Ultra-Lune", "t": "Après avoir prié jour et nuit de tout son cœur, son souhait a enfin été exaucé : ses cellules ont muté pour donner naissance à des ailes !"}, {"g": "Épée", "t": "Ce Pokémon rare a tellement souhaité voler qu’il s’est vu pousser des ailes pendant son évolution."}, {"g": "Bouclier", "t": "Heureux de pouvoir voler dans le ciel, il est souvent de bonne humeur, mais il devient incontrôlable lorsqu’on le met en colère."}],
  374: [{"g": "X", "t": "Il dégage un champ magnétique opposé à celui de la terre, ce qui lui permet de léviter."}, {"g": "Noir", "t": "Il dialogue avec les siens par impulsions magnétiques. En bande, ils se déplacent à l’unisson."}, {"g": "Rubis Oméga", "t": "Au lieu du sang, une force magnétique très puissante coule dans les veines de Terhal. Ce Pokémon communique avec les autres en envoyant des pulsations magnétiques."}, {"g": "Saphir Alpha", "t": "Terhal peut léviter en générant un champ magnétique qui repousse le magnétisme naturel de la terre. Lorsqu’il dort, ce Pokémon s’ancre à une falaise grâce à ses crochets dorsaux."}, {"g": "Soleil", "t": "Toutes ses cellules sont en fait des aimants. Il utilise la force magnétique pour communiquer avec ses congénères."}, {"g": "Lune", "t": "Il attire ses ennemis avec des ondes magnétiques et les pourfend avec ses griffes caudales dès qu’ils sont à portée."}, {"g": "Ultra-Soleil", "t": "Son corps n’est pas traversé par du sang, mais par des champs magnétiques. S’il est fatigué, il suffit de lui donner un aimant à grignoter."}, {"g": "Ultra-Lune", "t": "Quand on l’énerve, il entre dans une colère noire et déchaîne un puissant champ magnétique qui peut endommager les machines alentour."}, {"g": "Épée", "t": "Ce Pokémon peut créer un champ magnétique derrière lui qui attire ses ennemis avec force. Il les embroche alors de ses griffes acérées."}, {"g": "Bouclier", "t": "Les cellules de son corps sont composées d’aimants. Une force magnétique coule dans ses veines à la place du sang."}],
  375: [{"g": "Noir", "t": "Il est formé de deux Terhal soudés. Son corps de fer résiste à un choc avec un avion à réaction."}, {"g": "Y", "t": "Il est formé de deux Terhal soudés. Leurs deux cerveaux étant liés, ses pouvoirs psychiques sont très puissants."}, {"g": "Rubis Oméga", "t": "Lorsque deux Terhal fusionnent, un Métang apparaît. Les cerveaux des Terhal sont reliés par un système nerveux magnétique, ce qui permet à ce Pokémon de générer un puissant pouvoir télékinétique."}, {"g": "Saphir Alpha", "t": "Lorsque deux Terhal fusionnent, un Métang se forme. Les cerveaux des Terhal sont reliés par un système nerveux magnétique. Ce Pokémon dirige ses bras vers l’arrière pour voyager à grande vitesse."}, {"g": "Soleil", "t": "Lorsque deux Terhal fusionnent, leurs pouvoirs psychiques sont doublés. En revanche, ils ne deviennent pas plus futés."}, {"g": "Lune", "t": "Il raffole des minéraux qui émettent des ondes magnétiques. Il peut s’élancer à la poursuite d’un Tarinor à 100 km/h."}, {"g": "Ultra-Soleil", "t": "Grâce à ses deux cerveaux, il peut déchaîner une puissante force psychique qui lui permet d’immobiliser ses proies."}, {"g": "Ultra-Lune", "t": "Il parcourt le ciel à toute allure à la recherche d’une proie. Quand il en trouve une, il l’attrape avec ses griffes acérées et ne la lâche plus."}, {"g": "Épée", "t": "Composé de deux Terhal réunis par l’attraction magnétique, ce Pokémon a vu sa puissance psychique doubler grâce aux deux cerveaux."}, {"g": "Bouclier", "t": "Ce Pokémon vole par magnétisme. Il poursuit ses proies en slalomant à toute allure entre les pics escarpés."}],
  376: [{"g": "Noir", "t": "Il est né de la fusion de plusieurs Métang. Ses quatre cerveaux en font l’égal d’un superordinateur."}, {"g": "X", "t": "Il est né de la fusion de plusieurs Terhal. Ses quatre cerveaux en font l’égal d’un superordinateur."}, {"g": "Rubis Oméga", "t": "Métalosse dispose de quatre cerveaux. Combinés, ces cerveaux peuvent effectuer des calculs très complexes plus vite qu’un ordinateur. Ce Pokémon peut flotter dans l’air en repliant ses jambes."}, {"g": "Saphir Alpha", "t": "Métalosse est le résultat de la fusion de deux Métang. Lorsqu’il chasse, ce Pokémon bloque sa proie au sol, sous son corps massif. Il mange ensuite la victime impuissante avec son énorme bouche, ouverte sur son estomac."}, {"g": "Soleil", "t": "Avec ses quatre groupes de griffes et son corps imposant, il immobilise ses victimes pour ensuite mieux les dévorer."}, {"g": "Lune", "t": "Il est né de l’assemblage de deux Métang. Avec ses quatre cerveaux montés en parallèle, il peut résoudre n’importe quelle équation."}, {"g": "Ultra-Soleil", "t": "Il est aussi fier de sa force physique que de ses pouvoirs psychiques. Il immobilise ses proies avec les griffes d’acier de ses quatre pattes."}, {"g": "Ultra-Lune", "t": "Implacable, il analyse son ennemi encore plus précisément qu’un superordinateur et le pousse dans ses derniers retranchements."}, {"g": "Épée", "t": "Les Métalosse vivant sur des pics enneigés sont très actifs, car leur force magnétique augmente lorsque la température est inférieure à zéro."}, {"g": "Bouclier", "t": "Né de la fusion de deux Métang, il vient à bout de ses ennemis grâce à son cerveau qui est aussi performant qu’un superordinateur."}],
  377: [{"g": "Noir", "t": "Tout son corps est fait de roche. S’il s’ébrèche au combat, il utilise des pierres pour le réparer."}, {"g": "Y", "t": "Les roches qui composent son corps se retrouvent également dans les diverses couches terrestres."}, {"g": "Rubis Oméga", "t": "Regirock fut isolé par les gens il y a très longtemps. Lorsque le corps de ce Pokémon est endommagé au combat, on raconte qu’il cherche des rochers pour se réparer."}, {"g": "Saphir Alpha", "t": "Le corps de Regirock est entièrement constitué de rochers. Récemment, une étude a découvert que ces rochers provenaient de lieux très variés."}, {"g": "Épée", "t": "Il est entièrement composé de pierre. Si jamais une partie de son corps s’effrite, il la répare en y collant des rochers."}, {"g": "Bouclier", "t": "Bien que son corps de pierre ait été examiné avec les technologies les plus modernes, nulle trace de cerveau ou de cœur n’a été trouvée."}],
  378: [{"g": "Noir", "t": "Son corps est fait de glace datant de l’ère glaciaire. Il contrôle un air gelé de -200 °C."}, {"g": "X", "t": "Il reposait dans un glacier depuis des milliers d’années. Même le magma ne peut pas le faire fondre."}, {"g": "Rubis Oméga", "t": "Le corps de Regice fut créé pendant l’ère glaciaire. Son corps est tellement gelé qu’il ne peut pas fondre, même en le brûlant. Ce Pokémon peut contrôler l’air glacé jusqu’à une température de -200 °C."}, {"g": "Saphir Alpha", "t": "Regice se recouvre d’air glacé à -200 °C. Tout ce qui passe à proximité de ce Pokémon gèle sur place. Son corps est si froid qu’il ne fond jamais, même s’il plonge dans du magma."}, {"g": "Épée", "t": "Regice gèle quiconque s’approche de lui en un instant avec de l’air glacé pouvant atteindre -200 °C."}, {"g": "Bouclier", "t": "Ce Pokémon de l’ère glaciaire dont le corps est entièrement composé d’eau gelée serait né sous une épaisse couche de glace."}],
  379: [{"g": "Noir", "t": "Son corps invulnérable fut forgé par la pression souterraine durant des dizaines de milliers d’années."}, {"g": "Y", "t": "Son corps, plus dur que n’importe quel métal, serait creux selon les dernières analyses scientifiques."}, {"g": "Rubis Oméga", "t": "Le corps de Registeel est plus dur que n’importe quel métal existant. Il est apparemment creux. Personne ne sait ce que ce Pokémon mange."}, {"g": "Saphir Alpha", "t": "Il y a très longtemps, Registeel fut emprisonné par les hommes. On pense que l’étrange métal qui compose son corps provient d’une autre planète."}, {"g": "Épée", "t": "Il est fait d’une matière mystérieuse plus solide que n’importe quel métal, mais assez souple pour pouvoir s’étirer ou se rétrécir."}, {"g": "Bouclier", "t": "Il paraît qu’il est né dans le manteau terrestre et qu’il en a émergé il y a environ 10 000 ans."}],
  380: [{"g": "Noir", "t": "Son corps est recouvert d’un duvet qui reflète la lumière et le rend invisible."}, {"g": "X", "t": "Il est doué d’empathie. Le duvet qui recouvre son corps réfléchit la lumière et le rend invisible."}, {"g": "Y", "t": "Latias peut communiquer avec les gens par télépathie. Il change son apparence en renvoyant la lumière."}, {"g": "Rubis Oméga", "t": "Latias est extrêmement sensible aux émotions des gens. S’il ressent une hostilité, ce Pokémon ébouriffe ses plumes et pousse un cri strident pour intimider son ennemi."}, {"g": "Saphir Alpha", "t": "Latias est très intelligent et comprend le langage des hommes. Il est recouvert d’une espèce de duvet ressemblant à du verre. Ce Pokémon s’enveloppe dans ce duvet et reflète la lumière pour changer son apparence."}],
  381: [{"g": "Noir", "t": "Un Pokémon très intelligent. Il peut voler plus vite qu’un avion à réaction en repliant ses ailes."}, {"g": "Y", "t": "Un Pokémon très intelligent qui comprend le langage humain. Il déteste se battre."}, {"g": "Rubis Oméga", "t": "Latios a le pouvoir de faire voir à une personne une image provenant de son subconscient. Ce Pokémon est intelligent et comprend le langage humain."}, {"g": "Saphir Alpha", "t": "Latios n’ouvrira son cœur qu’à un Dresseur doté d’un esprit compatissant. Ce Pokémon peut voler plus vite qu’un avion à réaction en repliant ses pattes avant pour améliorer son aérodynamisme."}],
  382: [{"g": "Noir", "t": "On dit qu’il a fait monter les eaux en causant des pluies diluviennes. Il somnolait dans une fosse marine."}, {"g": "X", "t": "Ennemi juré de Groudon, la légende dit qu’il a étendu les mers en causant déluges et raz de marée."}, {"g": "Rubis Oméga", "t": "Grâce à l’énergie de la nature, il peut accomplir sa Primo-Résurgence pour retrouver son apparence originelle. Ce pouvoir lui permet d’appeler de terribles déluges pour étendre les mers."}, {"g": "Saphir Alpha", "t": "Un Pokémon considéré comme l’avatar des océans. Selon les légendes, il a disputé de nombreux combats avec Groudon pour contrôler l’énergie de la nature."}],
  383: [{"g": "Noir", "t": "Il dormait dans le magma souterrain depuis sa lutte féroce contre Kyogre, il y a longtemps de cela."}, {"g": "X", "t": "Ennemi juré de Kyogre, sa haute chaleur corporelle aurait fait évaporer l’eau et permis aux continents de s’étendre."}, {"g": "Y", "t": "Ce Pokémon légendaire incarne la terre. Il plongea dans un profond sommeil après son combat avec Kyogre."}, {"g": "Rubis Oméga", "t": "Un Pokémon considéré comme l’avatar des continents. Selon les légendes, il a disputé de nombreux combats avec Kyogre pour contrôler l’énergie de la nature."}, {"g": "Saphir Alpha", "t": "Grâce à l’énergie de la nature, il peut accomplir sa Primo-Résurgence pour retrouver son apparence originelle. Ce pouvoir lui permet de créer du magma pour étendre les continents."}],
  384: [{"g": "Noir", "t": "Il vit dans la couche d’ozone, au dessus des nuages. Il est invisible depuis le sol."}, {"g": "X", "t": "Il vit dans la couche d’ozone, au-dessus des nuages. Il est invisible depuis le sol."}, {"g": "Y", "t": "On ne l’a vu pour la première fois que très récemment car il vit dans la lointaine couche d’ozone."}, {"g": "Rubis Oméga", "t": "On raconte qu’il aurait plus de 10 000 ans. Selon les légendes, c’est grâce à lui que Kyogre et Groudon ont cessé de se battre."}, {"g": "Saphir Alpha", "t": "Un Pokémon qui vit dans la couche d’ozone et se nourrit des météorites qu’il intercepte. Leur énergie s’accumule dans son corps, ce qui lui permet de méga-évoluer."}],
  385: [{"g": "Noir", "t": "On raconte qu’une fois tous les mille ans, il a la capacité d’exaucer tous les vœux durant une semaine."}, {"g": "X", "t": "On raconte qu’à son réveil, il exauce les vœux écrits sur les rubans de papier de sa tête."}, {"g": "Y", "t": "On raconte qu’une fois tous les 1 000 ans, il a la capacité d’exaucer tous les vœux durant une semaine."}, {"g": "Rubis Oméga", "t": "Une légende raconte qu’à son réveil, Jirachi réalise n’importe quel souhait inscrit sur les papiers collés sur sa tête. Si ce Pokémon se sent en danger, il se défend sans même se réveiller."}, {"g": "Saphir Alpha", "t": "Jirachi dort depuis mille ans, mais il se réveillera si on lui chante quelque chose avec une voix d’une grande pureté. On raconte qu’il peut exaucer les vœux des gens."}, {"g": "Épée", "t": "Une fois tous les mille ans, le chant d’une voix pure le tire de son sommeil pour sept jours seulement."}, {"g": "Bouclier", "t": "On raconte que lorsqu’il se réveille de son sommeil millénaire, il exauce les vœux écrits sur les rubans de papier de sa tête."}],
  386: [{"g": "Noir", "t": "Il vient d’un virus extraterrestre arrivé avec une météorite et ayant subi une mutation génétique."}, {"g": "Y", "t": "C’est un virus extraterrestre qui a muté en Pokémon. Il apparaît à proximité des aurores boréales."}, {"g": "Rubis Oméga", "t": "L’ADN d’un virus extraterrestre entama une mutation non attendue suite à une exposition à un rayon laser, ce qui créa Deoxys. L’organe cristallin se trouvant sur la poitrine de ce Pokémon semble être son cerveau."}, {"g": "Saphir Alpha", "t": "Deoxys était à l’origine un virus provenant de l’espace. Il est extrêmement intelligent et dispose de pouvoirs télékinétiques. Ce Pokémon envoie des lasers avec l’organe cristallin situé sur sa poitrine."}],
  387: [{"g": "Noir", "t": "La coquille sur son dos est faite de terre. Plus il est en bonne santé, plus elle est humide."}, {"g": "X", "t": "Son corps assimile la lumière du soleil par photosynthèse. Sa carapace est faite de terre durcie."}, {"g": "Y", "t": "Son corps produit de l’oxygène par photosynthèse. La feuille sur sa tête flétrit quand il a soif."}],
  388: [{"g": "Noir", "t": "Il sait d’instinct où trouver une source d’eau pure. Il y transporte d’autres Pokémon sur son dos."}, {"g": "X", "t": "Il vit en forêt près de l’eau. En journée, il la quitte pour dorer sa carapace feuillue au soleil."}],
  389: [{"g": "Noir", "t": "Certains petits Pokémon peuvent naître sur son dos et y passer toute leur vie."}, {"g": "X", "t": "Autrefois, les gens pensaient qu’un gigantesque Torterra vivait sous la surface de la Terre."}, {"g": "Y", "t": "Il arrive que de petits Pokémon se rassemblent sur son dos immobile pour y faire leur nid."}],
  390: [{"g": "Noir", "t": "Il est très agile. Il fait toujours attention d’éteindre la flamme de sa queue avant de se coucher."}, {"g": "X", "t": "La flamme de sa queue est alimentée par un gaz de son estomac. Même la pluie ne saurait l’éteindre."}, {"g": "Y", "t": "La flamme de son postérieur brûle grâce à un gaz de son estomac. Elle faiblit quand il ne va pas bien."}],
  391: [{"g": "Noir", "t": "Il contrôle habilement l’intensité de la flamme de sa queue pour tenir ses adversaires à distance."}, {"g": "Y", "t": "Il attaque en prenant appui sur les murs et les plafonds. Sa queue ardente n’est pas son seul atout."}],
  392: [{"g": "Noir", "t": "Ses techniques de combat inédites à base de pieds et poings enflammés sont redoutables."}, {"g": "X", "t": "Sa couronne de feu trahit son tempérament bouillant. Sa vitesse est inégalée."}, {"g": "Y", "t": "Il fait voltiger ses ennemis grâce à sa vitesse et son style de combat spécial qui utilise ses quatre membres."}],
  393: [{"g": "Noir", "t": "Malgré sa démarche maladroite et ses pertes d’équilibre, il bombe toujours fièrement le torse."}, {"g": "X", "t": "Ce Pokémon est difficile à entraîner car il est très désobéissant et déteste qu’on lui rende service."}, {"g": "Y", "t": "Il est fier et déteste accepter la nourriture qu’on lui offre. Son pelage épais le protège du froid."}],
  394: [{"g": "Noir", "t": "La fierté du Prinplouf est si grande qu’il lui est impossible de vivre en groupe."}, {"g": "X", "t": "Il vit seul, à l’écart de ses pairs. Chaque individu est convaincu d’être meilleur que les autres."}, {"g": "Y", "t": "C’est un Pokémon solitaire. Un seul coup de ses puissantes ailes peut briser un arbre en deux."}],
  395: [{"g": "Noir", "t": "S’il voit son honneur bafoué, il est capable de faire des ravages avec ses ailes tranchantes."}, {"g": "X", "t": "Il nage aussi vite qu’un hors-bord. Le tranchant de ses ailes peut fendre un bloc de glace à la dérive."}, {"g": "Y", "t": "Les trois cornes de son bec sont le symbole de sa force. Celles du chef sont plus grosses que les autres."}],
  396: [{"g": "Noir", "t": "La faiblesse des Étourmi les force à vivre en groupe, mais ils se chamaillent souvent."}, {"g": "X", "t": "Ils volent en nombre. Bien que minuscule, il bat des ailes avec une vigueur impressionnante."}, {"g": "Y", "t": "Ce Pokémon très bruyant parcourt champs et forêts en nuées pour chasser les Pokémon Insecte."}],
  397: [{"g": "Noir", "t": "Conscient de sa propre faiblesse, il vit toujours en groupe, piaillant bruyamment quand il est seul."}, {"g": "X", "t": "Il a coutume de se regrouper en larges volées. Les combats entre Étourvol sont très violents."}, {"g": "Y", "t": "Il peuple les champs et les forêts. Lorsque deux volées se croisent, elles luttent pour le territoire."}],
  398: [{"g": "Noir", "t": "Il combattra sans relâche, même blessé. Il prend grand soin de sa mèche."}, {"g": "X", "t": "Ses ailes et ses pattes ont des muscles développés. Il peut voler en agrippant un petit Pokémon."}, {"g": "Y", "t": "Lorsque Étourvol évolue en Étouraptor, il quitte son groupe pour vivre seul. Ses ailes sont très développées."}],
  399: [{"g": "Noir", "t": "Une étude a montré que les dents du Keunotor poussaient aussi vite que celles du Rattata."}, {"g": "X", "t": "Rien ne peut perturber ses nerfs d’acier. Il est plus agile et énergique qu’il n’y paraît."}, {"g": "Y", "t": "Il ronge constamment des troncs et des pierres pour se faire les incisives. Il niche le long de l’eau."}],
  400: [{"g": "Noir", "t": "Les digues insubmersibles qu’il construit font le bonheur des habitants proches."}, {"g": "X", "t": "Il tranche les branches et les racines de ses incisives aiguisées pour construire des barrages."}, {"g": "Y", "t": "Il construit des barrages de boue et d’écorce le long des fleuves. C’est un ouvrier de renom."}],
  401: [{"g": "Noir", "t": "Quand il tombe du haut de ses petites pattes, ses antennes font un bruit de xylophone."}, {"g": "X", "t": "Il communique au son de ses antennes qui s’entrechoquent. Ce son marque l’arrivée de l’automne."}, {"g": "Y", "t": "Quand ses antennes s’entrechoquent, elles laissent échapper un bruit de xylophone."}],
  402: [{"g": "Noir", "t": "Ses cris sont tellement variés qu’il existe un village où on organise des concours en leur honneur."}, {"g": "X", "t": "Il croise ses bras affûtés devant son torse pour crier. Il compose tout un tas de mélodies."}, {"g": "Y", "t": "Il exprime ses émotions par des mélodies. Les scientifiques étudient actuellement leur structure."}],
  403: [{"g": "Noir", "t": "Ses muscles génèrent un courant électrique lorsqu’ils travaillent. Il s’illumine en cas de danger."}, {"g": "Y", "t": "Sa fourrure étincelle en cas de danger. Il profite du fait que l’ennemi est aveuglé pour s’enfuir."}, {"g": "Épée", "t": "Il produit de l’électricité en contractant ses muscles. S’il tremble d’excitation, c’est le signe qu’il est en train d’en générer en grande quantité."}, {"g": "Bouclier", "t": "Sa fourrure s’illumine grâce à l’électricité. Il agite l’extrémité lumineuse de sa queue pour envoyer des signes à ses congénères."}],
  404: [{"g": "Noir", "t": "Le courant qui circule à la pointe de ses griffes est capable de faire perdre connaissance à ses proies."}, {"g": "X", "t": "L’électricité libérée par ses griffes peut assommer l’ennemi. Il vit en petits groupes."}, {"g": "Épée", "t": "En reliant sa queue à celles de ses congénères, il peut recevoir leur énergie électrique et lancer des décharges encore plus puissantes."}, {"g": "Bouclier", "t": "Quand il croise un ennemi, il se prépare au combat en sortant ses griffes dont les coups ont une puissance qui atteint un million de volts."}],
  405: [{"g": "Noir", "t": "Il est capable de voir à travers les murs pour chasser des proies ou retrouver ses petits égarés."}, {"g": "X", "t": "Quand ses yeux se dorent, il peut repérer une proie cachée, même si elle est derrière un mur."}, {"g": "Y", "t": "Sa capacité à voir à travers tout est très utile pour détecter les moindres dangers."}, {"g": "Épée", "t": "Sa capacité à voir à travers la matière lui permet de repérer en un instant des proies cachées derrière un mur épais."}, {"g": "Bouclier", "t": "Il dort beaucoup pour récupérer la quantité d’énergie électrique énorme qu’il consomme afin de voir à travers la matière."}],
  406: [{"g": "Noir", "t": "Il est sensible aux variations de température et on dit qu’il fleurit quand il sent la chaleur du soleil."}, {"g": "X", "t": "Son bourgeon s’ouvre une fois gorgé de soleil et libère du pollen. Il vit près des sources d’eau pure."}, {"g": "Y", "t": "En hiver, son bourgeon se referme pour résister au froid. Il s’ouvre au printemps et libère du pollen."}, {"g": "Épée", "t": "Plus l’eau dont il se nourrit est pure, plus le niveau de toxicité du pollen qu’il répand est élevé."}, {"g": "Bouclier", "t": "Il est sensible aux variations de température. Quand son bourgeon commence à s’ouvrir, l’arrivée du printemps est imminente."}],
  407: [{"g": "Noir", "t": "Ses mains contenant chacune des toxines différentes sont capables d’asséner de puissants coups."}, {"g": "X", "t": "Il attire ses proies grâce à son parfum, puis les empoisonne ou les étouffe à l’aide de ses bras vénéneux."}, {"g": "Y", "t": "Gracieux comme un danseur, il abat ses fouets ornés d’épines empoisonnées."}, {"g": "Épée", "t": "Après avoir troublé les sens de ses adversaires avec le parfum exquis de ses fleurs, il les frappe violemment avec ses fouets ornés d’épines."}, {"g": "Bouclier", "t": "Sa main gauche administre un poison lent, et la droite, un poison foudroyant. Les deux peuvent être fatals."}],
  408: [{"g": "Noir", "t": "Il vivait dans la jungle il y a 100 millions d’années. Il abat un arbre d’un coup de tête."}, {"g": "X", "t": "On l’a ressuscité à partir d’un fossile de fer en forme de balle. Il abat ses proies à coups de tête."}, {"g": "Y", "t": "Il vivait dans la jungle il y a 100 millions d’années. Il peut abattre un arbre d’un coup de tête."}, {"g": "Soleil", "t": "Il peuplait les jungles il y a 100 millions d’années et se débarrassait de son grand rival, Ptéra, en lui donnant des coups de tête."}, {"g": "Lune", "t": "Auprès des fossiles de Kranidos, il n’est pas rare de trouver des arbres pétrifiés complètement broyés."}, {"g": "Ultra-Soleil", "t": "Un Pokémon préhistorique doté d’un crâne très solide, mais d’un cerveau très peu performant."}, {"g": "Ultra-Lune", "t": "Son crâne extrêmement solide est sa principale caractéristique. Il s’en servait pour faire tomber des arbres les Baies dont il se nourrissait."}],
  409: [{"g": "Noir", "t": "Quand deux Charkos se rentrent dedans, leur crâne extrêmement épais les empêche de s’assommer."}, {"g": "X", "t": "À force de cogner son crâne pourtant hyper résistant, Charkos a un cerveau atrophié."}, {"g": "Y", "t": "Son crâne est dur comme du fer. Cette brute abat des arbres quand elle chasse sa proie dans la jungle."}, {"g": "Soleil", "t": "À force d’enchaîner les coups de tête, sa calotte crânienne s’est épaissie. Son cerveau a donc dû rétrécir et il est plus petit que celui du Kranidos."}, {"g": "Lune", "t": "Des rapports font état d’un Charkos qui, après reconstitution et évolution, aurait pris la fuite en démolissant un gratte-ciel d’un coup de tête."}, {"g": "Ultra-Soleil", "t": "Il y a bien longtemps, les hommes fabriquaient des casques plus solides que l’acier à partir de crânes de Charkos fossilisés."}, {"g": "Ultra-Lune", "t": "Pokémon préhistorique célèbre pour ses coups de tête puissants et son petit cerveau, son extinction serait due à son extrême bêtise."}],
  410: [{"g": "Noir", "t": "Il est si bien protégé qu’il peut déguster Baies et herbe fraîche sans craindre de prédateurs."}, {"g": "X", "t": "Il a l’habitude de polir son visage en le frottant contre un tronc. Il craint les attaques dans le dos."}, {"g": "Y", "t": "Il est né d’un fossile datant de 100 millions d’années. Son visage est très dur."}, {"g": "Soleil", "t": "Dans les nombreux fossiles trouvés, presque aucune plaque faciale ne porte de trace de blessure ou d’ébréchure."}, {"g": "Lune", "t": "Grâce à sa tête très robuste, on suppose qu’il n’avait que très peu d’ennemis. Il vivait dans les forêts primaires, il y a fort longtemps."}, {"g": "Ultra-Soleil", "t": "Cet herbivore, très calme de nature, utilisait la peau durcie de son museau pour déterrer des racines à grignoter."}, {"g": "Ultra-Lune", "t": "On retrouve des fossiles de Dinoclier dans les couches sédimentaires préhistoriques, mais seule sa tête a résisté à l’épreuve du temps."}],
  411: [{"g": "Noir", "t": "En groupe, ils protègent leurs petits en formant autour d’eux une impénétrable muraille."}, {"g": "Y", "t": "Il résiste à toute attaque frontale. C’est un Pokémon docile qui se nourrit d’herbe et de Baies."}, {"g": "Soleil", "t": "S’il peut parer quasiment tous les assauts de face, il est extrêmement vulnérable aux attaques par-derrière."}, {"g": "Lune", "t": "Il vivait dans les mêmes zones que le Charkos. On trouve parfois leurs fossiles embrassés pour l’éternité suite à un K.O. mutuel."}, {"g": "Ultra-Soleil", "t": "Jusqu’à ce qu’on reconstitue ce Pokémon avec succès, on prenait les grands os solides qui couvrent son visage pour sa colonne vertébrale."}, {"g": "Ultra-Lune", "t": "Un Pokémon éteint depuis environ 100 millions d’années. Sa tête incroyablement solide était plus dure que l’acier."}],
  412: [{"g": "Noir", "t": "Nul ne sait comment il y parvient, mais il arrive toujours à se former une cape, où qu’il soit."}, {"g": "X", "t": "Pour se protéger des vents glacés de l’hiver, il s’est tissé une cape de feuilles et de brindilles."}, {"g": "Y", "t": "S’il perd sa cape au combat, il en tisse rapidement une nouvelle avec ce qui lui tombe sous la main."}],
  413: [{"g": "Noir", "t": "À l’évolution, son corps absorbe les matériaux à proximité et peut ainsi présenter divers aspects."}, {"g": "X", "t": "Son apparence varie selon le lieu d’évolution. Son corps est façonné avec les matériaux à disposition."}, {"g": "Y", "t": "Quand Cheniti a évolué, sa cape a fusionné avec son corps. Cheniselle ne s’en sépare jamais."}],
  414: [{"g": "Noir", "t": "Il adore le nectar des fleurs mais n’en récolte pas lui-même. Il préfère en voler à un Apitrini."}, {"g": "X", "t": "Il aime le nectar des fleurs et n’hésite pas à voler celui que récupère Apitrini."}, {"g": "Y", "t": "Ce Pokémon s’active à la nuit tombée pour voler le miel des Apitrini pendant leur sommeil."}],
  415: [{"g": "Noir", "t": "Ce trio inséparable depuis la naissance récolte du miel pour satisfaire Apireine."}, {"g": "Y", "t": "Il récolte le nectar et l’amène à la colonie. La nuit, les Pokémon de cette espèce s’assemblent pour bâtir une ruche et s’endormir."}, {"g": "Épée", "t": "Ce trio est inséparable et pourtant, leur goût pour le nectar diffère légèrement."}, {"g": "Bouclier", "t": "Du lever du soleil à la tombée de la nuit, il récolte du nectar pour Apireine et sa colonie."}],
  416: [{"g": "Noir", "t": "Ce Pokémon utilise des phéromones pour donner des ordres de combat aux larves dans son abdomen."}, {"g": "X", "t": "Son abdomen abrite ses petits. Ce Pokémon utilise des phéromones pour leur donner des ordres."}, {"g": "Y", "t": "Son abdomen est un rayon où vivent ses larves, élevées avec le nectar récolté par Apitrini."}, {"g": "Épée", "t": "Ce Pokémon se bat en dirigeant ses petits. Ces derniers sont prêts à se sacrifier pour leur Apireine."}, {"g": "Bouclier", "t": "Plus la quantité de phéromones qu’il libère est élevée, plus le nombre d’Apitrini qu’il peut diriger est grand."}],
  417: [{"g": "Noir", "t": "Il arrive que deux Pachirisu se frottent les joues pour partager l’électricité qu’ils ont accumulée."}, {"g": "X", "t": "Il roule des boules de poils pleines d’électricité statique et les range dans des souches avec des Baies."}],
  418: [{"g": "Noir", "t": "Il utilise ses deux queues comme une hélice pour se propulser sous l’eau et trancher les algues."}, {"g": "X", "t": "Il nage en faisant tournoyer ses deux queues comme une hélice. Sa bouée s’affaisse quand il plonge."}, {"g": "Y", "t": "Il utilise la bouée autour de son cou pour passer sa tête hors de l’eau et observer les alentours."}],
  419: [{"g": "Noir", "t": "Il chasse souvent près des ports de pêche où il sauve parfois les gens tombés à la mer."}, {"g": "X", "t": "Il flotte grâce à sa bouée très développée. Il vole au secours des gens sur le point de se noyer."}, {"g": "Y", "t": "Il a développé une bouée pour poursuivre ses proies aquatiques. Elle fait office de canot gonflable."}],
  420: [{"g": "Noir", "t": "Sa petite boule rose est nutritive et délicieuse. Les Étourmi en raffolent."}, {"g": "X", "t": "Il rougit au soleil. Quand la petite boule est à court de nutriments, elle fane en signe d’évolution."}, {"g": "Y", "t": "Il aspire les nutriments de sa petite boule pour pouvoir évoluer."}, {"g": "Épée", "t": "Il s’enfuit à la vue des Pokémon oiseaux, dont le mets favori est sa petite boule remplie de nutriments."}, {"g": "Bouclier", "t": "Plus son corps est rouge, plus la saveur de sa petite boule gorgée de nutriments est sucrée et délicieuse."}],
  421: [{"g": "Noir", "t": "Sous un grand soleil, il ouvre ses pétales pour en absorber les rayons."}, {"g": "X", "t": "Une fois gorgé de soleil, il déploie ses pétales et bouge avec vivacité."}, {"g": "Épée", "t": "Pendant sa période de bourgeonnement, il reste presque totalement immobile et attend que le soleil se lève."}, {"g": "Bouclier", "t": "Lorsqu’il se ferme, ses pétales sont si durs qu’il ne craint plus les attaques des Pokémon oiseaux."}],
  422: [{"g": "Noir", "t": "Un étrange liquide mauve s’échappe de son corps, ne lui appuyez pas dessus."}, {"g": "Y", "t": "Il change facilement de couleur ou de forme en fonction de son environnement."}, {"g": "Soleil", "t": "Il vit principalement sur les rivages rocheux. Sa forme et sa couleur peuvent varier selon son environnement et son alimentation."}, {"g": "Lune", "t": "Au toucher, une sécrétion mauve se dépose sur les mains. Faites bien attention, car elle ne part vraiment pas facilement, même en lavant bien."}, {"g": "Ultra-Soleil", "t": "Il vit normalement dans la mer, mais il peut aussi s’installer sur la terre ferme, tant que sa peau reste humide."}, {"g": "Ultra-Lune", "t": "Il sécrète un liquide mauve lorsqu’il se sent en danger. Il s’agirait d’un phénomène similaire aux sueurs froides."}, {"g": "Épée", "t": "Son apparence change selon son environnement. On raconte qu’il adopte celle-ci dans les mers chaudes."}, {"g": "Bouclier", "t": "Si on le caresse trop fort, il sécrète un étrange liquide mauve qui est inoffensif, mais dont la texture est très gluante."}],
  423: [{"g": "Rubis Oméga", "t": "Attaqué par un prédateur, il fuit en libérant un liquide mauve."}, {"g": "Noir", "t": "Ses gènes ont démontré qu’il avait jadis une carapace couvrant la totalité de son dos."}, {"g": "Y", "t": "Jadis, il semble qu’il portait une grande carapace pour se protéger. Il hante les eaux peu profondes."}, {"g": "Soleil", "t": "Il se régénère très vite. Même si des Pokémon poissons en croquent un bout, il est à nouveau comme neuf au bout de quelques heures."}, {"g": "Lune", "t": "Il s’alimente principalement de plancton invisible à l’œil nu. On ne sait toujours pas pourquoi il a quitté l’océan au profit de la terre ferme."}, {"g": "Ultra-Soleil", "t": "La fine soucoupe qui se trouve à l’intérieur de son dos est le dernier vestige de la carapace jadis portée par son espèce."}, {"g": "Ultra-Lune", "t": "Il change de forme et de couleur selon son habitat et son alimentation. On le trouve souvent sur les plages à la faible houle."}, {"g": "Épée", "t": "Il peut rejoindre la terre ferme pour chercher des proies. Il laisse une traînée de bave gluante derrière lui."}, {"g": "Bouclier", "t": "Son corps est caoutchouteux, mais très résistant, car la puissance des chocs qu’il subit se répand sur toute sa surface."}],
  424: [{"g": "Noir", "t": "Ses queues jumelles sont si agiles et efficaces qu’il ne se sert que très rarement de ses bras."}, {"g": "X", "t": "Ils vivent en grandes colonies et relient leurs queues pour former un anneau en signe d’amitié."}, {"g": "Y", "t": "Il se nourrit de noix qu’il épluche avec ses deux queues habiles. Il utilise de moins en moins ses bras."}, {"g": "Ultra-Soleil", "t": "Il se dispute constamment les arbres les plus confortables avec Quartermac et remporte la victoire la moitié du temps."}, {"g": "Ultra-Lune", "t": "Il utilise toujours ses deux queues pour faire la moindre tâche. Il s’en sert aussi pour enlacer les gens qu’il affectionne tout particulièrement."}],
  425: [{"g": "Noir", "t": "Sa façon de flotter sans but au gré du vent lui a valu le surnom de “bouée des esprits égarés”."}, {"g": "X", "t": "Un Pokémon né de l’esprit des gens et des Pokémon. Il aime les saisons chaudes et humides."}, {"g": "Y", "t": "Les enfants qui attrapent des Baudrive disparaissent parfois. On lui donne le surnom de « bouée des esprits égarés »."}, {"g": "Soleil", "t": "Il guide les petits enfants par la main vers l’autre monde. Mais seulement les plus jeunes, car après, ils sont trop lourds pour lui."}, {"g": "Lune", "t": "Si par malheur il éclate, le Baudrive émet alors un bruit terrible, comme un cri déchirant. C’est à vous fendre le cœur."}, {"g": "Ultra-Soleil", "t": "Son corps rond contient une quantité d’âmes impressionnante. Plus il entraîne de personnes avec lui, plus son corps gonfle."}, {"g": "Ultra-Lune", "t": "Né d’une agglomération d’âmes errantes, il entraîne les enfants par la main pour s’en faire des amis."}, {"g": "Épée", "t": "Pour se faire des amis, il s’approche des enfants, mais ces derniers le malmènent souvent, ce qui le pousse à s’enfuir."}, {"g": "Bouclier", "t": "Nés d’une concentration d’âmes, ces Pokémon peuvent apparaître en grand nombre les jours où le taux d’humidité est élevé."}],
  426: [{"g": "Noir", "t": "Des nuées de Grodrive dérivent dans le ciel au crépuscule. Ils disparaissent dès qu’on les voit."}, {"g": "X", "t": "Il peut embarquer des gens et des Pokémon, mais nul ne sait où il va atterrir car il ne fait que flotter."}, {"g": "Y", "t": "Il somnole la journée et s’envole en grands groupes le soir venu. Nul ne sait où ils vont."}, {"g": "Soleil", "t": "Un jour, un homme a grimpé sur un Grodrive pour partir en voyage. Personne ne l’a jamais revu."}, {"g": "Lune", "t": "Même si à la tombée de la nuit on peut observer des nuées entières de Grodrive, elles finissent toujours par s’évanouir dans la nature."}, {"g": "Ultra-Soleil", "t": "Si l’on en croit la rumeur, il serait possible de se rendre dans l’au-delà en se laissant porter par le vent nocturne, accroché à un Grodrive."}, {"g": "Ultra-Lune", "t": "Son gaz est essentiellement composé d’âmes. Si par malheur son corps se dégonfle, on dit qu’il entraîne humains et Pokémon dans sa chute."}, {"g": "Épée", "t": "Ce Pokémon, qui flotte silencieusement au crépuscule, serait né des âmes des défunts rongés par les regrets."}, {"g": "Bouclier", "t": "Il attrape des personnes et des Pokémon pour les transporter vers une destination inconnue."}],
  427: [{"g": "Noir", "t": "Ses oreilles repliées se déroulent avec une force capable de briser un gros rocher."}, {"g": "Y", "t": "Il dresse les oreilles quand il sent un danger. Il dort la tête dans sa fourrure pendant les nuits froides."}, {"g": "Ultra-Soleil", "t": "Il possède peu de force dans ses membres, mais il lui suffit de déplier son oreille comme un ressort pour réduire un rocher en poussière."}, {"g": "Ultra-Lune", "t": "S’il a toujours une oreille repliée, c’est pour être à même de contre-attaquer dès qu’un ennemi tente de s’en prendre à lui."}, {"g": "Épée", "t": "Quand ses deux oreilles sont repliées, c’est signe qu’il ne se sent pas bien physiquement ou mentalement et qu’il a besoin de soins."}, {"g": "Bouclier", "t": "Plus il s’entraîne, plus les coups qu’il assène en déroulant vigoureusement ses oreilles gagnent en puissance."}],
  428: [{"g": "Noir", "t": "Il est capable de décocher de puissants coups de pied si on touche à ses délicates oreilles."}, {"g": "X", "t": "Il détecte le moindre danger. Il file discrètement par petits bonds rapides quand il se sent menacé."}, {"g": "Ultra-Soleil", "t": "Il mue deux fois par an. Les écharpes et les chapeaux fabriqués à partir de ses poils tiennent bien chaud."}, {"g": "Ultra-Lune", "t": "Il est très vigilant et n’aime pas vraiment se battre, mais gare aux coups de patte dévastateurs qu’il peut décocher !"}, {"g": "Épée", "t": "Constamment sur le qui-vive, il donne des coups de pied particulièrement dévastateurs si une menace approche."}, {"g": "Bouclier", "t": "À la fin de la saison chaude, il mue et se recouvre d’une fourrure épaisse et légère pour se préparer à affronter le froid hivernal."}],
  429: [{"g": "Noir", "t": "Pareil à une incantation magique, son cri n’est que très rarement source de joie."}, {"g": "X", "t": "Il psalmodie des incantations. Ce sont souvent des malédictions, mais certaines apportent la joie."}, {"g": "Y", "t": "Un Pokémon insaisissable qui tourmente ses ennemis avec son cri semblable à une incantation."}, {"g": "Soleil", "t": "Un Pokémon aux pouvoirs terrifiants : il sort de nulle part en maugréant des incantations et en lançant des malédictions."}, {"g": "Lune", "t": "Comme Magirêve aurait le pouvoir de réaliser les souhaits des amoureux, certaines personnes se lancent désespérément à sa poursuite."}, {"g": "Ultra-Soleil", "t": "Redouté pour ses sortilèges et ses malédictions, ce Pokémon peut néanmoins faire preuve de bienveillance, si l’envie lui en prend."}, {"g": "Ultra-Lune", "t": "Il susurre des malédictions pour tourmenter ses ennemis et leur infliger de terribles migraines ou des hallucinations terrifiantes."}],
  430: [{"g": "Noir", "t": "Son cri profond peut invoquer une meute de Cornèbre. On l’appelle “le crieur de mauvais augure”."}, {"g": "X", "t": "Son cri profond peut invoquer une meute de Cornèbre. On l’appelle « le crieur de mauvais augure »."}, {"g": "Y", "t": "Ce Pokémon nocturne évolue en grandes volées escortées par des Cornèbre."}, {"g": "Soleil", "t": "Un seul des puissants croassements de ce Pokémon nocturne lui permet de rassembler une centaine de Cornèbre, ses sous-fifres."}, {"g": "Lune", "t": "Si l’un de ses sous-fifres Cornèbre a le malheur de le décevoir ou d’échouer dans sa mission, le Corboss le pourchassera sans le moindre répit."}, {"g": "Ultra-Soleil", "t": "Il ne pardonne jamais la trahison ou la défaite d’un subordonné. Le bien-être de l’ensemble de la volée en dépend."}, {"g": "Ultra-Lune", "t": "Ses sous-fifres font le sale boulot pour lui. Il n’intervient en combat que pour donner le coup de grâce à son ennemi."}],
  431: [{"g": "Noir", "t": "Il a tendance à planter ses griffes dans le nez de son Dresseur s’il n’a pas été nourri à temps."}, {"g": "X", "t": "Il griffe quand il est en colère et ronronne quand il est heureux. Certains aiment ce côté lunatique."}, {"g": "Y", "t": "Lorsqu’il est heureux, sa queue décrit des arabesques comme un ruban de gymnastique rythmique."}],
  432: [{"g": "Noir", "t": "Il plaque ses queues contre son dos pour paraître plus grand. Il soutient un regard des heures."}, {"g": "X", "t": "Il n’hésitera pas à voler le nid d’autres Pokémon et à s’y installer si celui-ci est confortable."}, {"g": "Y", "t": "Il ceinture sa taille de sa queue bifide pour paraître plus imposant."}],
  433: [{"g": "Noir", "t": "Quand il sautille, l’orbe qu’il a dans la bouche s’agite et tinte comme une cloche."}, {"g": "X", "t": "Il produit un bruit de sonnerie à chaque bond. Il assourdit l’ennemi avec ses cris à haute fréquence."}],
  434: [{"g": "Noir", "t": "Son derrière propulse un fluide nauséabond qui peut faire fuir les Pokémon dans un rayon de 2 km."}, {"g": "Y", "t": "Il se protège en expulsant un fluide nocif par son derrière. La puanteur dure 24 heures."}, {"g": "Épée", "t": "Il propulse un liquide extrêmement nauséabond au visage de son adversaire depuis son derrière. Il peut atteindre une cible à cinq mètres."}, {"g": "Bouclier", "t": "S’il lève la queue, c’est qu’il s’apprête à projeter un liquide tellement nauséabond qu’il peut faire perdre connaissance."}],
  435: [{"g": "Noir", "t": "Il attaque en projetant un liquide fétide du bout de sa queue. Mieux vaut l’attaquer par les airs."}, {"g": "X", "t": "Il attaque en projetant un liquide fétide du bout de sa queue. Il peut tirer à 50 m."}, {"g": "Y", "t": "Sa queue projette un fluide puant. Plus on le laisse s’écouler et plus son odeur est insoutenable."}, {"g": "Épée", "t": "Il se bat en projetant avec sa queue un liquide nauséabond qu’il stocke dans son ventre. L’odeur varie selon ce qu’il mange."}, {"g": "Bouclier", "t": "Ce Pokémon, qui creuse son terrier dans le sol, peut projeter un liquide à l’odeur infecte avec le bout de sa queue."}],
  436: [{"g": "Noir", "t": "Certains scientifiques soutiennent que ce Pokémon était jadis aussi réfléchissant qu’un miroir."}, {"g": "X", "t": "Les gens croyaient autrefois que les motifs de son dos renfermaient une puissance mystique."}, {"g": "Y", "t": "Il rappelle des objets trouvés dans des sépultures anciennes. Nul ne sait s’ils sont liés."}, {"g": "Épée", "t": "Il apparaît dans les ruines. Les motifs qui ornent son corps sont mystérieux, car ils appartiennent à une culture étrangère à Galar."}, {"g": "Bouclier", "t": "On raconte qu’il se met à briller et à refléter la vérité quand on le polit, mais il a horreur de cela."}],
  437: [{"g": "Noir", "t": "Il apportait la pluie en créant un portail vers une autre dimension. Il était synonyme de bonne récolte."}, {"g": "X", "t": "Il a longtemps été célébré pour avoir apporté la pluie. On le trouve parfois enterré dans le sol."}, {"g": "Y", "t": "On croyait autrefois que lui adresser des prières faisait pleuvoir et assurait les récoltes."}, {"g": "Épée", "t": "On dit qu’il appelle la pluie. Si on attise sa colère, il se met à gronder en émettant un son lugubre semblable à celui d’une cloche."}, {"g": "Bouclier", "t": "De nombreux savants pensent que ce Pokémon n’est pas originaire de Galar à cause des motifs qui ornent son corps."}],
  438: [{"g": "Noir", "t": "Adepte des climats secs, il régule son humidité en laissant couler ce qui ressemble à des larmes."}, {"g": "X", "t": "Il préfère les sols arides. Il évacue l’eau par ses yeux pour réguler ses fluides corporels."}, {"g": "Soleil", "t": "Comme il a horreur de l’eau, on le trouve surtout dans les régions arides. Avec si peu de verdure alentour, on le repère tout de suite."}, {"g": "Lune", "t": "Il se débarrasse des liquides superflus par ses yeux. La composition chimique de ces liquides ressemble à celle de la sueur humaine."}, {"g": "Ultra-Soleil", "t": "Il évacue tout surplus d’eau par les yeux. Cela ressemble à une crise de larmes et a parfois pour effet d’attendrir ses ennemis."}, {"g": "Ultra-Lune", "t": "Absorber trop d’humidité peut mettre sa vie en danger, c’est pourquoi il « sue » tout excès de liquide par les yeux."}, {"g": "Épée", "t": "Il évacue sa sueur et ses larmes par les yeux. Sa sueur a un goût légèrement salé, tandis que ses larmes ont un soupçon d’amertume."}, {"g": "Bouclier", "t": "Il vit dans les zones rocheuses arides. Quand ses boules vertes sont sèches, elles se mettent à briller légèrement."}],
  439: [{"g": "Noir", "t": "Il imite les mouvements et les expressions des autres pour comprendre leurs sentiments."}, {"g": "X", "t": "Il déstabilise ses ennemis en imitant leurs mouvements et profite de leur stupeur pour décamper."}, {"g": "Y", "t": "Il imite ses ennemis. Une fois imités, ils ne peuvent plus quitter ce Pokémon des yeux."}, {"g": "Ultra-Soleil", "t": "Il fait de son mieux pour imiter les gestes et les expressions de ses adversaires, mais il a encore des progrès à faire."}, {"g": "Ultra-Lune", "t": "Quand un adversaire reste bouche bée face à ses talents de mime, il est tellement content qu’il en oublie de continuer sa performance."}, {"g": "Épée", "t": "Il mime tout ce qu’il voit, et s’entraîne beaucoup pour reproduire les pas de danse élégants des M. Glaquette."}, {"g": "Bouclier", "t": "Il considère les meilleurs danseurs parmi les M. Glaquette comme ses maîtres et s’évertue à mimer leurs mouvements."}],
  440: [{"g": "Noir", "t": "Ce Pokémon ne se sépare jamais de son petit caillou et a tendance à traîner dans les pieds des gens."}, {"g": "X", "t": "Ptiravi transporte un caillou rond en forme d’œuf dans sa poche ventrale pour l’offrir à ses amis."}, {"g": "Y", "t": "Il prend soin de ses bouclettes et couve son caillou comme si c’était son Œuf."}, {"g": "Soleil", "t": "Il transporte un petit caillou rond et blanc dans sa poche ventrale. Il arrive même qu’il le donne aux personnes qu’il aime bien."}, {"g": "Lune", "t": "Comme il est très jeune, il ne peut pas encore pondre d’œuf. À la place, il cherche un joli petit caillou blanc, bien rond."}, {"g": "Ultra-Soleil", "t": "C’est un Pokémon d’un naturel calme. Quiconque tente de s’emparer du caillou de sa poche ventrale s’expose toutefois à un gros caprice."}, {"g": "Ultra-Lune", "t": "Dès qu’il repère un objet rond et blanc, il le range dans sa poche ventrale. Il en ramasse parfois tellement qu’il ne peut plus bouger."}, {"g": "Épée", "t": "Pour imiter Leveinard, il conserve un caillou en forme d’œuf dans sa poche ventrale et en prend grand soin."}, {"g": "Bouclier", "t": "Il prête volontiers son caillou rond à ceux qu’il apprécie, mais éclate en sanglots et se met en colère si on ne le lui rend pas."}],
  441: [{"g": "Noir", "t": "Sa langue comparable à celle de l’homme lui permet d’imiter habilement le langage humain."}, {"g": "X", "t": "Il reproduit le cri de ses ennemis pour faire croire qu’il est des leurs et éviter d’être attaqué."}, {"g": "Y", "t": "On peut lui enseigner quelques mots. S’il s’agit d’un groupe, ils retiendront les mêmes phrases."}],
  442: [{"g": "Noir", "t": "Son mauvais comportement lui a valu d’être enchaîné à une Clé de Voûte par un mystérieux sortilège."}, {"g": "X", "t": "Un Pokémon composé de 108 esprits. Il provient d’une fissure dans une clé de voûte étrange."}, {"g": "Y", "t": "Il fut emprisonné dans la fissure d’une clé de voûte étrange en guise de punition il y a 500 ans."}, {"g": "Épée", "t": "Ce Pokémon est né de la fusion de 108 âmes, mais on raconte que certaines d’entre elles seraient de nature maléfique."}, {"g": "Bouclier", "t": "Pour punir son comportement déplorable, un voyageur a utilisé un mystérieux sortilège pour l’enchaîner à une Clé de Voûte."}],
  443: [{"g": "Noir", "t": "Malgré sa maladresse, son énorme gueule lui permet de lancer des attaques puissantes."}, {"g": "X", "t": "Il niche dans des cavités chauffées par géothermie, dont il bondit pour déchiqueter tout intrus."}, {"g": "Y", "t": "Il niche dans les petits trous horizontaux des murs des grottes. Il bondit pour saisir sa proie."}, {"g": "Soleil", "t": "On le trouve dans les cavernes bien chauffées par géothermie. S’il a froid malgré tout, il dort en tas avec ses congénères pour se réchauffer."}, {"g": "Lune", "t": "Il attend le passage d’une proie pour bondir hors de son trou et la croquer. Dans son élan, il se casse parfois les dents."}, {"g": "Ultra-Soleil", "t": "Il saute sur tout ce qui bouge pour y planter ses dents. Cette manie lui vaut quelques blessures, mais il n’en a que faire."}, {"g": "Ultra-Lune", "t": "Il vient d’un endroit où il fait bien plus chaud que dans la région d’Alola. La facture de chauffage est donc élevée quand on vit avec lui."}, {"g": "Épée", "t": "Il aime les cavités étroites dans les grottes chauffées par géothermie. Elles le tiennent au chaud lorsque le blizzard souffle à l’extérieur."}, {"g": "Bouclier", "t": "Il attaque et entraîne dans son antre tout ce qui bouge, sans distinction. Sa gueule est immense, mais son estomac est relativement petit."}],
  444: [{"g": "Noir", "t": "Toujours à la recherche d’objets brillants, il arpente les grottes pour constituer son butin."}, {"g": "Y", "t": "Carmache accumule les pierres précieuses qu’il déterre quand il entreprend d’agrandir son nid."}, {"g": "Soleil", "t": "Il perd parfois ses écailles quand il mue. Les remèdes à base d’écailles de Carmache sont de puissants toniques."}, {"g": "Lune", "t": "Il adore tout ce qui brille. Au fond de sa tanière, il contemple les joyaux qu’il a dérobés et les Strassie qu’il a kidnappés."}, {"g": "Ultra-Soleil", "t": "Il adore tout ce qui brille, et rien ne l’énerve plus qu’un Ténéfix s’en prenant à un Strassie. S’il est témoin d’une telle agression, il passe à l’attaque."}, {"g": "Ultra-Lune", "t": "Il mue régulièrement au cours de sa croissance. Les écailles ainsi tombées peuvent être pilées pour préparer des remèdes traditionnels."}, {"g": "Épée", "t": "Il émet des ultrasons avec les deux appendices sur sa tête pour sonder les grottes obscures."}, {"g": "Bouclier", "t": "Il cache des pierres précieuses dans le sol de sa grotte, et accueille à coups de griffes et de crocs quiconque ose y pénétrer."}],
  445: [{"g": "Noir", "t": "On dit que lancé à pleine vitesse, il crée des lames de vent avec ses ailes pouvant trancher un arbre."}, {"g": "X", "t": "Quand il se recroqueville et étend ses ailes, on dirait un chasseur. Sa vitesse est supersonique."}, {"g": "Y", "t": "Il vole à la vitesse d’un avion à réaction et ne lâche jamais sa proie."}, {"g": "Soleil", "t": "Il vole aussi vite qu’un avion à réaction. Si en vol il croise une nuée de Pokémon oiseaux, il les avale d’une seule bouchée."}, {"g": "Lune", "t": "Les deux protubérances qu’il a sur la tête lui servent de capteurs. Il peut ainsi détecter les mouvements de proies très éloignées."}, {"g": "Ultra-Soleil", "t": "Il vole à la vitesse du son en quête de nourriture. Drattak et lui se disputent souvent leurs proies dans des combats aériens impressionnants."}, {"g": "Ultra-Lune", "t": "En plus de maximiser son aérodynamisme, ses écailles lisses et pointues ont l’avantage de blesser ses ennemis quand ils l’attaquent."}, {"g": "Épée", "t": "Vivant dans les massifs volcaniques, ce Pokémon chasse ses proies dans le ciel en volant aussi vite qu’un avion à réaction."}, {"g": "Bouclier", "t": "Ce Pokémon très rapide même au sol capture ses proies sur les monts enneigés et rentre vite dans son antre avant que son corps ne gèle."}],
  446: [{"g": "Noir", "t": "Obnubilé par sa quête incessante de nourriture, il oublie parfois qu’il en a caché dans sa fourrure."}, {"g": "X", "t": "Il cache de la nourriture sous les grands poils de son corps, mais il finit souvent par l’oublier."}, {"g": "Y", "t": "Goinfrex cache de la nourriture dans sa fourrure en pagaille. Il avale tout en une bouchée."}, {"g": "Soleil", "t": "Il mange chaque jour l’équivalent de son propre poids. Il consomme sa nourriture en quantité, mais il se moque bien du goût qu’elle a."}, {"g": "Lune", "t": "Dès qu’il voit un mets alléchant, il le ramasse aussitôt et l’avale tout de go. C’est pour cela qu’il grossit à vue d’œil, ce petit glouton."}, {"g": "Ultra-Soleil", "t": "Il a tendance à cacher des aliments dans son épaisse fourrure... et à les oublier là. L’odeur putride qui s’en dégage alors est plutôt gênante."}, {"g": "Ultra-Lune", "t": "Dès qu’il voit quelque chose de comestible, il le ramasse et l’avale tout de go. Son estomac lui permet de digérer même la nourriture avariée."}, {"g": "Épée", "t": "Il ne pense qu’à manger énormément. Il n’a que faire du goût et n’hésite d’ailleurs pas à engloutir de la nourriture avariée."}, {"g": "Bouclier", "t": "Il conserve sa nourriture sous son épaisse fourrure. Il lui arrive d’en offrir un peu à ceux en qui il a confiance."}],
  447: [{"g": "Noir", "t": "Il a la faculté unique de visualiser les émotions telles que la joie ou la colère sous forme d’ondes."}, {"g": "X", "t": "Il communique avec ses semblables grâce à des ondes qui sont modulées en fonction de ses émotions."}, {"g": "Y", "t": "Son aura s’intensifie pour prévenir son entourage quand il a peur ou qu’il est triste."}, {"g": "Soleil", "t": "Il perçoit sous forme d’ondes les émotions des humains et des Pokémon, ainsi que tout ce qui l’entoure."}, {"g": "Lune", "t": "Comme il peut passer la nuit entière à courir, il paraît très robuste et persévérant, mais au fond, c’est encore un bébé."}, {"g": "Ultra-Soleil", "t": "Il peut détecter les émotions des humains et des Pokémon grâce à leur aura. Il ne s’approche pas des individus qu’il juge dangereux."}, {"g": "Ultra-Lune", "t": "Il se sert d’auras pour communiquer avec les siens. Ses ennemis ne peuvent pas espionner ses conversations, car il n’émet aucun son."}, {"g": "Épée", "t": "Il possède assez d’endurance pour passer des nuits entières à courir. Il est difficile de partir en balade avec lui tant il déborde d’énergie."}, {"g": "Bouclier", "t": "Il perçoit sous forme d’aura non seulement les sentiments des autres, mais aussi l’état de la nature."}],
  448: [{"g": "Noir", "t": "Un spécimen bien entraîné peut sentir et identifier les émotions de quelqu’un à plus d’un kilomètre."}, {"g": "X", "t": "Il peut deviner les pensées et les mouvements des autres en analysant leur aura."}, {"g": "Y", "t": "Il peut sentir et identifier les émotions de quelqu’un à plus d’un kilomètre."}, {"g": "Soleil", "t": "Ne se contentant pas de percevoir les auras, il peut également les modifier. Il n’hésite pas à s’en servir en plein combat."}, {"g": "Lune", "t": "Il peut détecter les émotions des individus se trouvant à 1 km, ainsi que leur espèce. Il chasse en meute en se servant des auras."}, {"g": "Ultra-Soleil", "t": "Il peut canaliser son énergie mentale pour déchaîner des auras mystérieuses capables de réduire d’énormes rochers en miettes."}, {"g": "Ultra-Lune", "t": "Grâce à ses auras, il peut détecter toutes les émotions de son adversaire, même celles qu’il préférerait ignorer et qui lui causent du stress."}, {"g": "Épée", "t": "Il chasse ses proies en se servant d’une force appelée aura, dont la puissance est telle qu’elle lui permet de réduire un rocher en poussière."}, {"g": "Bouclier", "t": "Étant capable de lire ce que pensent les humains, ce Pokémon ne s’attache qu’aux Dresseurs dotés d’un cœur pur."}],
  449: [{"g": "Noir", "t": "Il peut obturer ses narines et traverser le sable comme un ver. Il vit en colonies de 10 individus."}, {"g": "X", "t": "Il vit dans des endroits arides. Il exsude du sable granuleux au lieu de transpirer."}, {"g": "Y", "t": "Il se recouvre de sable pour se protéger des microbes. Il n’aime pas l’eau."}, {"g": "Épée", "t": "Il attrape ses proies en se déplaçant la gueule ouverte. Il éjecte ensuite le sable qu’il a avalé au passage en l’expulsant par le nez."}, {"g": "Bouclier", "t": "Il est principalement actif pendant la journée. Il s’enfouit profondément dans le sable pour dormir, car les nuits désertiques sont très froides."}],
  450: [{"g": "Noir", "t": "Facilement irritable, il ouvre ses mâchoires au maximum pour intimider ses adversaires."}, {"g": "X", "t": "Il exhibe sa force en ouvrant grand sa mâchoire, et attaque en soulevant des tornades de sable."}, {"g": "Y", "t": "Il emmagasine du sable qu’il expulse en tornades par les pores de sa peau pour attaquer."}, {"g": "Épée", "t": "Il prend grand soin des Crabicoque, car ils l’aident à se débarrasser des cailloux qui obstruent parfois les orifices de son corps."}, {"g": "Bouclier", "t": "Il entre dans une violente colère quand on l’énerve : il expulse le sable qu’il a accumulé pour provoquer de véritables tempêtes."}],
  451: [{"g": "Noir", "t": "Il saisit sa proie avec les pinces de sa queue et lui injecte un poison. Il peut survivre un an sans manger."}, {"g": "X", "t": "Il saisit sa proie avec les pinces de sa queue, lui injecte un poison et la retient jusqu’à ce qu’il agisse."}, {"g": "Y", "t": "Il attend, en embuscade dans le sable, et empoisonne ses proies avec les pinces de sa queue."}, {"g": "Épée", "t": "Il s’enfouit dans le sable et attend patiemment ses proies. Il a des ancêtres en commun avec Grillepattes."}, {"g": "Bouclier", "t": "Il attaque avec les pinces empoisonnées de sa queue. Le venin se répand alors dans le corps de la victime et la paralyse."}],
  452: [{"g": "Noir", "t": "Fier et robuste, il met un point d’honneur à battre ses adversaires sans utiliser de poison."}, {"g": "X", "t": "Il met ses adversaires en pièces grâce à sa prodigieuse force, puis donne le coup de grâce avec son violent poison."}, {"g": "Y", "t": "Il peut réduire une voiture en pièces avec ses pinces. Le bout de ses pinces contient du poison."}, {"g": "Épée", "t": "Son poison est violent, mais il s’en sert très rarement. Il se déchaîne avec une telle force qu’il pourrait réduire une voiture en pièces."}, {"g": "Bouclier", "t": "Sa férocité lui a valu le surnom de « démon du désert », mais face à un Hippodocus, il est parfaitement docile et évite de le provoquer."}],
  453: [{"g": "Noir", "t": "Son instinct de survie le pousse à ne pas se battre dans les règles. C’est une mascotte populaire."}, {"g": "X", "t": "Ses joues contiennent des glandes toxiques. Il attaque par surprise et utilise son toucher empoisonné."}, {"g": "Y", "t": "Ses glandes se gonflent de venin tout en émettant un son effrayant, le laissant ainsi empoisonner ses proies pétrifiées."}, {"g": "Épée", "t": "Il intimide ses ennemis en faisant résonner les glandes toxiques de ses joues, puis leur porte un coup empoisonné par surprise."}, {"g": "Bouclier", "t": "Dilué, son poison sert de remède. Cela lui a valu de devenir la mascotte populaire d’une entreprise de produits pharmaceutiques."}],
  454: [{"g": "Noir", "t": "Quand il coasse, le poison stocké sous sa gorge est secoué, le rendant ainsi plus efficace."}, {"g": "Y", "t": "Les griffes de ses poings sécrètent une toxine si atroce qu’une simple égratignure peut s’avérer fatale."}, {"g": "Épée", "t": "Il bondit sur ses adversaires pour les transpercer avec ses griffes empoisonnées. Une simple égratignure suffit à les mettre K.O."}, {"g": "Bouclier", "t": "Il lance un coassement viril de victoire quand il parvient à terrasser sa proie. Il s’apparente aux Crapustule."}],
  455: [{"g": "Noir", "t": "Il s’accroche aux arbres des marais et attire ses proies avec sa salive à l’odeur enivrante."}, {"g": "X", "t": "Il attire sa proie avec sa salive odorante avant de la croquer. Il lui faut une journée pour l’avaler."}],
  456: [{"g": "Noir", "t": "La ligne qui fait le tour de son corps stocke l’énergie solaire et brille dans la nuit."}, {"g": "Y", "t": "Après une longue exposition au soleil, les motifs de ses nageoires caudales luisent à la nuit tombée."}, {"g": "Soleil", "t": "Il stocke les rayons solaires grâce aux parties roses de sa peau, qui brillent ensuite. Il s’agirait en fait d’une technique de camouflage."}, {"g": "Lune", "t": "Avec sa double nageoire caudale, il peut bondir hors de l’eau. C’est souvent à ce moment que les Goélise de passage l’attrapent et le gobent."}, {"g": "Ultra-Soleil", "t": "Les motifs roses de sa peau brillent la nuit. Des stations balnéaires l’attirent avec de la nourriture, car il est très aimé des plongeurs."}, {"g": "Ultra-Lune", "t": "Il attire ses proies avec ses nageoires caudales lumineuses. Il passe la journée à la surface et se retire dans les abysses la nuit venue."}],
  457: [{"g": "Rubis Oméga", "t": "Il vit au plus profond de l’océan. Il attire sa proie en illuminant les motifs de ses quatre nageoires."}, {"g": "Noir", "t": "Il rampe au fond de l’océan grâce aux nageoires de son torse. Le Lanturn est son rival."}, {"g": "Y", "t": "Pour éviter de se faire voir par ses ennemis, il rampe au fond de l’eau grâce aux nageoires sur son torse."}, {"g": "Soleil", "t": "Il attire ses proies en émettant de la lumière, mais à son grand dam, cela attire aussi ses prédateurs : les Pokémon poissons carnassiers."}, {"g": "Lune", "t": "Ce Pokémon des profondeurs vit tout au fond de l’océan. Il rampe à l’aide de ses nageoires ventrales et cherche les Staross dont il raffole."}, {"g": "Ultra-Soleil", "t": "La nourriture étant très rare dans les abysses marins, Luminéon doit souvent se disputer ses précieuses proies avec Lanturn."}, {"g": "Ultra-Lune", "t": "Il se déplace en rampant dans les profondeurs de l’océan. Ses nageoires brillent telles des étoiles dans le ciel nocturne."}],
  458: [{"g": "Noir", "t": "On organise des excursions pour le voir surfer sur les vagues au côté des Rémoraid."}, {"g": "X", "t": "Les motifs sur son dos sont différents selon les régions. On le voit souvent dans des bancs de Rémoraid."}, {"g": "Y", "t": "Il nage si proche de la surface que l’on peut voir les motifs sur son dos depuis un bateau."}, {"g": "Ultra-Soleil", "t": "Il est très affectueux et adore les humains. Les excursions permettant d’aller nager avec lui sont très populaires auprès des touristes."}, {"g": "Ultra-Lune", "t": "Il s’approche souvent des bateaux pour sympathiser avec les humains. Le motif qui orne son dos varie selon son habitat."}, {"g": "Épée", "t": "Les Babimanta vivant à Galar semblent un peu engourdis. Cela pourrait être dû à la basse température de la mer."}, {"g": "Bouclier", "t": "Il nage au sein des bancs de Rémoraid. Lorsqu’un prédateur les attaque, il se bat à leurs côtés."}],
  459: [{"g": "Noir", "t": "Curieux de rencontrer des gens, ils se rassemblent autour des traces de pas trouvées dans la montagne."}, {"g": "X", "t": "Il s’aventure jusqu’au pied des montagnes en hiver, mais se réfugie sur les pics neigeux au printemps."}, {"g": "Y", "t": "Au printemps, il fait pousser des Baies pareilles à des crèmes glacées autour de son ventre."}, {"g": "Épée", "t": "Il plante ses pieds dans la neige des montagnes où il vit pour absorber l’air froid et l’humidité."}, {"g": "Bouclier", "t": "Les Baies en forme de crèmes glacées qui poussent sur son ventre sont le mets favori des Darumarond vivant à Galar."}],
  460: [{"g": "Noir", "t": "Il apparaît quand les fleurs des terres enneigées fleurissent et se retire quand elles se fanent."}, {"g": "X", "t": "De larges zones sont recouvertes par la neige de ses blizzards. On l’appelle « monstre des glaces »."}, {"g": "Y", "t": "Il hante les sommets aux neiges éternelles, et se cache en déclenchant des blizzards."}, {"g": "Épée", "t": "Il fait fuir les hordes de Darumarond qui s’en prennent aux Blizzi en se servant de ses grands bras comme de marteaux."}, {"g": "Bouclier", "t": "Ce grand Pokémon déclenche des blizzards. Lorsqu’il agite son corps, tout ce qui l’entoure se retrouve couvert de neige."}],
  461: [{"g": "Noir", "t": "L’évolution l’a rendu encore plus retors. Il communique en griffant des signes dans les pierres."}, {"g": "X", "t": "Il vit dans les régions enneigées, et communique avec ses pairs en gravant des motifs sur les arbres."}, {"g": "Y", "t": "Ils vivent par groupe de 4 ou 5 en région froide et chassent de façon très organisée."}, {"g": "Saphir Alpha", "t": "Ils vivent par groupe de quatre ou cinq en région froide et chassent de façon très organisée."}, {"g": "Soleil", "t": "Il se déplace en groupe de quatre ou cinq. Lors de la chasse, il laisse des signes sur les arbres ou les rochers pour communiquer efficacement."}, {"g": "Lune", "t": "Habitant des régions enneigées, il ne se nourrit que de Goupix et de Sabelette à Alola. Il partage toujours ses proies avec ses amis."}, {"g": "Ultra-Soleil", "t": "Il chasse les Sabelette en équipe : un Dimoret maintient la proie sur le dos, puis un deuxième l’achève d’un coup de griffe."}, {"g": "Ultra-Lune", "t": "Il est devenu assez sournois pour ne plus avoir à se battre pour ses proies. Quiconque entre en contact avec ses griffes souffrira de gelures."}, {"g": "Épée", "t": "Ils chassent en hordes. Grâce à leur bonne coordination, ils peuvent aisément venir à bout de grands Pokémon comme Mammochon."}, {"g": "Bouclier", "t": "Il communique avec ses semblables en gravant des motifs avec ses griffes. Il existerait près de 500 signes différents."}],
  462: [{"g": "Noir", "t": "Des scientifiques ont essayé de faire évoluer un Magnézone en laboratoire, mais ce fut un échec."}, {"g": "X", "t": "Le champ magnétique qu’ils émettent est tel qu’ils ont tendance à s’attirer mutuellement et à s’empêcher de bouger."}, {"g": "Y", "t": "Il a évolué suite à son exposition à un champ magnétique spécial. Ses 3 unités génèrent du magnétisme."}, {"g": "Saphir Alpha", "t": "Il a évolué suite à son exposition à un champ magnétique spécial. Ses trois unités génèrent du magnétisme."}, {"g": "Soleil", "t": "Ses trois unités émettent une force magnétique. Il n’est pas rare que les gens le confondent avec un OVNI quand il vole dans le ciel."}, {"g": "Lune", "t": "Il vole dans le ciel en émettant et en recevant des ondes bien mystérieuses."}, {"g": "Ultra-Soleil", "t": "Il surveille son territoire à l’aide de son radar, et élimine rapidement tout intrus avec son laser destructeur."}, {"g": "Ultra-Lune", "t": "De nombreuses personnes pensent encore qu’il s’agit d’un Pokémon venu de l’espace. Il émet un champ magnétique extrêmement puissant."}, {"g": "Épée", "t": "On raconte qu’il serait contrôlé par une entité extraterrestre grâce à des ondes qu’il capterait avec l’antenne sur sa tête."}, {"g": "Bouclier", "t": "On pense qu’il a évolué après avoir été exposé à un champ magnétique particulier qui a modifié la structure moléculaire de son corps."}],
  463: [{"g": "Noir", "t": "Sa longue langue est couverte en permanence d’une épaisse couche de bave anesthésiante."}, {"g": "X", "t": "Il enroule tout dans sa langue extensible. Ceux qui l’approchent finissent couverts de bave."}, {"g": "Y", "t": "Sa bave anesthésiante est chargée d’une substance capable de faire fondre n’importe quelle matière."}, {"g": "Ultra-Soleil", "t": "Il existe un concours visant à déterminer lequel d’entre eux a la langue la plus longue. Le record actuel est de 25 m."}, {"g": "Ultra-Lune", "t": "Il est bien plus adroit avec sa langue qu’avec ses autres membres, au point qu’elle peut même lui servir à ramasser un grain de riz minuscule."}, {"g": "Épée", "t": "Sa langue a l’incroyable faculté de s’allonger et d’atteindre plusieurs fois la taille de son corps. Ce mystère de la nature reste entier."}, {"g": "Bouclier", "t": "Il est aussi habile avec sa langue que les êtres humains le sont avec leurs mains. En revanche, il est maladroit quand il utilise ses doigts."}],
  464: [{"g": "Noir", "t": "Il peut lancer des pierres à une vitesse saisissante en bandant et relâchant ses muscles en un éclair."}, {"g": "X", "t": "Ses paumes projettent des Racaillou, et son corps couvert de Protecteurs résiste même à une éruption volcanique."}, {"g": "Y", "t": "Il bande ses muscles pour projeter des pierres ou des Racaillou depuis le creux de ses paumes."}, {"g": "Épée", "t": "Il met des rochers ou des Nodulithe dans le creux de ses mains et les tire comme des obus. Il peut ainsi en charger trois par bras."}, {"g": "Bouclier", "t": "Il repousse les attaques avec ses Protecteurs et profite du moment où l’adversaire est déstabilisé pour le transpercer avec sa vrille, dont il est fier."}],
  465: [{"g": "Noir", "t": "Ses bras sont en fait des plantes qui s’attachent à tout ce qu’elles touchent et peuvent repousser."}, {"g": "X", "t": "Il ligote sa proie en étirant ses bras en lianes. Il ne craint pas de perdre un bras face à un ennemi."}, {"g": "Y", "t": "Lorsque vient la belle saison, ses lianes sont si luxuriantes qu’elles cachent ses yeux."}, {"g": "Épée", "t": "La science a récemment découvert que les deux bras qu’il peut allonger à volonté sont en fait des lianes entrelacées."}, {"g": "Bouclier", "t": "Ses lianes poussent plus rapidement s’il vit sous un climat chaud. Quand elles deviennent trop longues, il se les coupe."}],
  466: [{"g": "Noir", "t": "Encaissant les attaques, il vient toucher l’ennemi de ses queues et lui inflige une forte décharge."}, {"g": "X", "t": "Des étincelles bleuâtres jaillissent entre ses 2 cornes quand il accumule beaucoup d’électricité."}, {"g": "Y", "t": "Il place le bout de ses deux queues sur son ennemi et libère une décharge de 20 000 V."}, {"g": "Soleil", "t": "Il connecte le bout de sa queue à son ennemi et libère une violente décharge. L’ennemi est instantanément grillé."}, {"g": "Lune", "t": "Quand il est excité, il se frappe violemment la poitrine de ses poings. Cela fait des étincelles électriques et un vrai roulement de tonnerre."}, {"g": "Ultra-Soleil", "t": "Il tient fermement le bout de sa queue pour charger son poing d’électricité, puis martèle ses ennemis de coups dévastateurs."}, {"g": "Ultra-Lune", "t": "Il suffit d’un seul Élekable pour alimenter tous les bâtiments d’une métropole pendant un an."}, {"g": "Épée", "t": "La quantité d’électricité qu’il génère est proportionnelle à son pouls. Quand il livre un combat, son voltage augmente aussitôt."}, {"g": "Bouclier", "t": "La quantité d’électricité qu’il génère est énorme, même pour un Pokémon Électrik. Il inflige de fortes décharges du bout de ses queues."}],
  467: [{"g": "Noir", "t": "Quand il lance des boules de feu à plus de 2 000 °C, son corps est comme chauffé à blanc."}, {"g": "X", "t": "Il projette des boules de feu à 2 000 °C à bout de bras. Il vit dans les cratères volcaniques."}, {"g": "Y", "t": "Il projette des boules de feu à 2 000 °C du bout de ses bras. Même son souffle est brûlant."}, {"g": "Soleil", "t": "Il vit dans les cratères de volcans. On dit que chaque volcan ne peut abriter qu’un seul couple de Maganon."}, {"g": "Lune", "t": "Son bras peut expulser des boules enflammées d’une température de 2 000 °C. S’il en tire trop d’un coup, son bras commence à fondre."}, {"g": "Ultra-Soleil", "t": "Il existe encore de nombreuses usines qui utilisent les flammes de Maganon pour faire fondre les métaux."}, {"g": "Ultra-Lune", "t": "Il peut terrasser ses ennemis d’une seule boule de feu. Il évite toutefois de s’en servir pour chasser, car sa proie finirait carbonisée."}, {"g": "Épée", "t": "Quand il inspire profondément, les flammes dans son ventre gagnent en intensité et atteignent les 2 000 °C."}, {"g": "Bouclier", "t": "Au fil du temps, son corps est devenu similaire à un volcan, et un de ses organes ressemble désormais à une chambre magmatique."}],
  468: [{"g": "Noir", "t": "Il apprécie particulièrement les gens qui respectent les autres et évitent les conflits inutiles."}, {"g": "X", "t": "On dit qu’il apparaît dans les contrées paisibles pour dispenser mille bienfaits."}, {"g": "Épée", "t": "Il ne se montre jamais en temps de guerre ou de conflit. Ces derniers temps, il est rare de le croiser."}, {"g": "Bouclier", "t": "On dit que ce Pokémon dispense ses bienfaits, ce qui explique pourquoi il est représenté sur les porte-bonheurs depuis fort longtemps."}],
  469: [{"g": "Noir", "t": "Doté de mandibules à la force colossale, il excelle pour mordre ses ennemis en plein vol."}, {"g": "X", "t": "Il excelle dans l’art de mordre ses ennemis en plein vol, et à grande vitesse."}, {"g": "Y", "t": "Il peut voler avec aise tout en portant un adulte dans ses 6 pattes. Les ailes de sa queue lui servent de balancier."}, {"g": "Saphir Alpha", "t": "Il peut voler avec aise tout en portant un adulte dans ses six pattes. Les ailes de sa queue lui servent de balancier."}],
  470: [{"g": "Noir", "t": "Il utilise la photosynthèse comme une plante et a aussi tendance à éviter le combat à tout prix."}, {"g": "X", "t": "Un Phyllali qui dort par beau temps produit un air frais et pur par photosynthèse."}, {"g": "Y", "t": "Il utilise la photosynthèse comme une plante. C’est pourquoi il est toujours entouré d’air pur."}, {"g": "Soleil", "t": "Sa structure cellulaire est plus proche de celle des végétaux que de celle des animaux. Il produit de l’énergie par photosynthèse."}, {"g": "Lune", "t": "Les jeunes Phyllali sentent l’herbe fraîche. Avec l’âge, ce parfum se mue en une odeur de feuilles mortes."}, {"g": "Ultra-Soleil", "t": "Il n’aime pas le conflit, mais s’il doit protéger ses amis, il peut raidir sa queue en forme de feuille et la rendre aussi tranchante qu’une lame."}, {"g": "Ultra-Lune", "t": "Il vit dans le calme des forêts profondes traversées par de jolis ruisseaux, où il se nourrit de lumière et d’eau fraîche."}, {"g": "Épée", "t": "Les habitants de Galar adorent l’odeur unique qui se dégage de ses feuilles, aussi entrent-elles dans la composition d’un parfum très populaire."}, {"g": "Bouclier", "t": "Grâce à sa queue aussi effilée qu’une lame, il est capable de fendre en deux des arbres immenses."}],
  471: [{"g": "Noir", "t": "Il ajuste la température de son corps pour créer un vent de glace en gelant l’air qui l’entoure."}, {"g": "Y", "t": "Il abaisse la température de son corps pour changer ses poils en aiguilles de glace qu’il projette sur l’ennemi."}, {"g": "Soleil", "t": "Il peut contrôler la température de son corps à volonté et générer des cristaux de glace en gelant l’humidité de l’air."}, {"g": "Lune", "t": "Il gèle ses poils pour les transformer en pics de glace, qu’il utilise ensuite pour terrasser ses proies."}, {"g": "Ultra-Soleil", "t": "Pour se protéger, il gèle ses poils jusqu’à les transformer en picots de glace. Sa température corporelle peut descendre jusqu’à -60 °C."}, {"g": "Ultra-Lune", "t": "Il gèle les particules d’eau qui l’entourent pour former de petits cristaux de glace, qu’il utilise ensuite pour lapider ses proies."}, {"g": "Épée", "t": "Totalement subjuguées par la beauté des cristaux de glace qu’il fait tomber, ses proies ne réalisent que trop tard qu’elles sont en train de geler."}, {"g": "Bouclier", "t": "Ce Pokémon exhale un vent glacial qui crée une neige poudreuse. Sa présence est très appréciée dans les stations de ski."}],
  472: [{"g": "Noir", "t": "Le plus petit courant d’air peut lui donner assez d’élan pour faire le tour du monde sans un coup d’aile."}, {"g": "X", "t": "Il guette sa proie, pendu à une branche la tête en bas, et s’en saisit à la première occasion."}, {"g": "Y", "t": "Il vole sans un bruit, et capture ses proies avec sa queue pour leur infliger une morsure critique."}],
  473: [{"g": "Noir", "t": "On a libéré un spécimen de sa prison glacée au bout de 10 000 ans. Il n’en revenait pas."}, {"g": "X", "t": "Un Pokémon si vieux qu’on l’a découvert sous des glaces vieilles de 10 000 ans."}, {"g": "Y", "t": "Ses défenses spectaculaires sont glacées. Il a failli disparaître dans la canicule suivant l’ère glaciaire."}, {"g": "Épée", "t": "On le retrouve dessiné sur des fresques murales vieilles de 10 000 ans. On a cru pendant un temps que son espèce s’était éteinte."}, {"g": "Bouclier", "t": "Comme son physique le laisse deviner, il est très fort. La taille de ses défenses de glace augmente à mesure que la température baisse."}],
  474: [{"g": "Noir", "t": "Il a été modifié pour être capable de travailler dans des dimensions parallèles, mais c’est un échec."}, {"g": "X", "t": "Un logiciel supplémentaire fut installé pour l’améliorer. Mais depuis, il se comporte bizarrement."}, {"g": "Y", "t": "On a modifié son programme pour qu’il puisse parcourir les dimensions, mais ce fut un échec."}, {"g": "Soleil", "t": "Il a été modifié pour devenir encore plus efficace, mais cela a entraîné plusieurs bugs. Maintenant, il se conduit très bizarrement."}, {"g": "Lune", "t": "Un nouveau logiciel était censé lui permettre de voyager entre les dimensions, mais tout ne se passe pas comme prévu et il y a des bugs."}, {"g": "Ultra-Soleil", "t": "Son comportement, manifestement étrange, s’expliquerait par l’incompétence du technicien qui a mis à jour son système d’exploitation."}, {"g": "Ultra-Lune", "t": "Le logiciel qu’on lui a implanté était de toute évidence défaillant. Il s’agit sans doute d’une expérience ratée, vu son étrange comportement."}, {"g": "Épée", "t": "Depuis qu’on lui a ajouté un programme permettant de voyager entre les dimensions, son comportement est devenu instable."}, {"g": "Bouclier", "t": "On dit qu’un nouveau programme l’a fait évoluer, mais les avis des scientifiques divergent quant à savoir s’il s’agit réellement d’une évolution."}],
  475: [{"g": "X", "t": "Comme il peut lire les pensées de ses adversaires, il frappe toujours en premier."}, {"g": "Noir", "t": "Toujours prêt à protéger son prochain, il se bat férocement avec ses coudes en forme d’épées."}, {"g": "Y", "t": "Il frappe avec les grandes lames à ses coudes. Son talent d’escrimeur n’a d’égal que sa courtoisie."}, {"g": "Épée", "t": "Ce Pokémon, que l’on surnomme « l’escrimeur », ne se sert de ses coudes en forme de lames que s’il doit défendre quelque chose."}, {"g": "Bouclier", "t": "Ses sens aiguisés lui indiquent lorsque quelqu’un est en danger. Il accourt alors à la rescousse."}],
  476: [{"g": "Noir", "t": "Il utilise sa force magnétique pour diriger trois petites unités appelées Mini-nez."}, {"g": "X", "t": "Son corps libère une puissante force magnétique. Il dirige trois petites unités appelées Mini-nez."}, {"g": "Soleil", "t": "Il émet un puissant champ magnétique qui rend tous les appareils électriques des alentours inutilisables."}, {"g": "Lune", "t": "Sans avoir besoin de se déplacer, il pilote ses trois Mini-nez à distance afin de capturer ses proies."}, {"g": "Ultra-Soleil", "t": "Il est capable de piloter ses Mini-nez à distance, mais il arrive que l’un d’entre eux s’aventure trop loin et se perde pour ne jamais revenir."}, {"g": "Ultra-Lune", "t": "Il utilise ses trois petites unités pour combattre ses ennemis et capturer ses proies. Le reste de son corps se contente de donner des ordres."}],
  477: [{"g": "Noir", "t": "Son corps se replie sur lui-même pour emprisonner les esprits perdus et les ramener chez eux."}, {"g": "Y", "t": "L’antenne sur sa tête capte les ondes radio du monde des esprits lui ordonnant d’y porter des gens."}, {"g": "Épée", "t": "Nul ne sait s’il est doté d’une volonté propre. Les ondes du monde des esprits le poussent à conduire humains et Pokémon vers l’au-delà."}, {"g": "Bouclier", "t": "Il dévore l’âme de ses ennemis en les engloutissant dans sa bouche ventrale. Il recrache ensuite leur enveloppe corporelle."}],
  478: [{"g": "Noir", "t": "On dit que Momartik gèle ses proies grâce à son souffle à -50 °C avant de les exposer dans sa tanière."}, {"g": "X", "t": "Momartik gèle ses ennemis grâce à son souffle à -50 °C. Ça ne se voit pas, mais son corps est creux."}, {"g": "Y", "t": "On dit dans les régions enneigées qu’il s’agit de la réincarnation d’une jeune fille disparue dans les neiges."}, {"g": "Soleil", "t": "Il congèle les humains et les Pokémon qui lui plaisent. Il les emporte ensuite dans sa tanière pour les admirer à loisir."}, {"g": "Lune", "t": "Il s’agirait d’une stalagmite possédée par l’âme d’une jeune fille disparue dans les cimes enneigées. Il adore les âmes d’hommes."}, {"g": "Ultra-Soleil", "t": "Momartik gèle les Montagnards qui s’aventurent dans les pics enneigés et emmène ceux qu’il trouve beaux dans sa tanière."}, {"g": "Ultra-Lune", "t": "On dit qu’il apparaît dans les zones habitées les soirs de tempête de neige. Si vous entendez toquer à la porte, n’allez pas ouvrir !"}, {"g": "Épée", "t": "Ce Pokémon est né des regrets d’une femme disparue dans les pics enneigés. Il raffole des âmes gelées."}, {"g": "Bouclier", "t": "Il gèle ses proies avec son souffle à - 50 °C, les amène dans son antre, puis les y aligne avec soin."}],
  479: [{"g": "Noir", "t": "Son corps parcouru d’électricité lui permet de prendre le contrôle de certains appareils ménagers."}, {"g": "X", "t": "Un Pokémon longtemps étudié comme source d’énergie pour un moteur très spécial."}, {"g": "Y", "t": "Son corps est fait de plasma. Il cause de gros dégâts en infiltrant des appareils électroniques."}, {"g": "Épée", "t": "L’invention d’un jeune homme a inspiré la création de machines permettant de profiter des compétences de ce Pokémon."}, {"g": "Bouclier", "t": "Son corps composé de plasma lui permet d’infiltrer diverses machines. Il adore surprendre les gens."}],
  480: [{"g": "Noir", "t": "Quand il prit son envol, les hommes apprirent à résoudre les problèmes. Le savoir était né."}, {"g": "X", "t": "On l’appelle « être du savoir ». On raconte que son regard a le pouvoir d’effacer la mémoire."}, {"g": "Y", "t": "On dit que sa venue a fourni aux humains le bon sens nécessaire pour améliorer leur existence."}],
  481: [{"g": "Noir", "t": "Quand il prit son envol, les hommes apprirent à ressentir la joie et la peine. L’émotion était née."}, {"g": "X", "t": "On l’appelle « être de l’émotion ». Il enseigne aux hommes la beauté de la tristesse, la douleur et la joie."}, {"g": "Y", "t": "Il dort au fond d’un lac. On dit que son esprit abandonne son corps pour voler à sa surface."}],
  482: [{"g": "Noir", "t": "Quand il prit son envol, les hommes acquirent la détermination. La volonté était née."}, {"g": "X", "t": "On l’appelle « être de la volonté ». Il dort au fond d’un lac pour maintenir l’équilibre du monde."}, {"g": "Y", "t": "On raconte que Créhelf, Créfollet et Créfadet proviennent du même Œuf."}],
  483: [{"g": "Noir", "t": "On dit que le temps s’écoule au rythme des battements de cœur de ce Pokémon légendaire de Sinnoh."}, {"g": "X", "t": "Les mythes parlent de ce Pokémon. On dit que le temps s’est mis en mouvement à sa naissance."}, {"g": "Y", "t": "Il peut contrôler le temps. Les mythes de Sinnoh en parlent comme d’une divinité ancienne."}],
  484: [{"g": "Noir", "t": "On dit que la stabilité de l’espace est maintenue par le souffle de ce Pokémon légendaire de Sinnoh."}, {"g": "X", "t": "On dit qu’il hante une faille d’une dimension parallèle à la nôtre. Il apparaît dans la mythologie."}, {"g": "Y", "t": "Il peut modeler l’espace. Les mythes de Sinnoh en parlent comme d’une divinité ancienne."}],
  485: [{"g": "Noir", "t": "Son corps est composé d’acier brut dont certaines parties ont fondu à cause de sa propre chaleur."}, {"g": "X", "t": "Il hante les grottes volcaniques. Il rampe au mur et au plafond grâce à ses pieds en forme de croix."}, {"g": "Y", "t": "Le sang de ce Pokémon des cratères bouillonne dans son corps comme du magma."}],
  486: [{"g": "Noir", "t": "On dit qu’il a créé des Pokémon à son image à partir de glace, de roche et de magma."}, {"g": "Y", "t": "Une légende tenace veut que ce Pokémon ait traîné les continents en les attachant à des cordes."}, {"g": "Épée", "t": "Plusieurs légendes à travers le monde racontent que Regigigas aurait créé des Pokémon à son image."}, {"g": "Bouclier", "t": "On raconte qu’après avoir créé des Pokémon avec différentes matières, il aurait placé les continents à leur position actuelle."}],
  487: [{"g": "Noir", "t": "Sa grande violence lui a valu d’être banni. Il observe les hommes en silence depuis le Monde Distorsion."}, {"g": "X", "t": "Il vit dans le Monde Distorsion, un monde à l’opposé du nôtre qui échappe au sens commun."}],
  488: [{"g": "Noir", "t": "Les nuits où le premier croissant de lune est visible, l’arc de sa queue se déploie de façon superbe."}, {"g": "X", "t": "Ses ailes libèrent un rideau de particules brillantes. Ce Pokémon symboliserait le croissant de lune."}, {"g": "Y", "t": "Dormir avec une de ses plumes à la main permet de faire de beaux rêves. On le surnomme « avatar du croissant de lune »."}],
  489: [{"g": "Noir", "t": "Ce Pokémon des mers chaudes revient toujours à son lieu de naissance, peu importe la distance."}, {"g": "X", "t": "Il gonfle la bouée de sa tête et se laisse flotter à la surface quand la mer se réchauffe."}],
  490: [{"g": "Noir", "t": "Il est né avec le pouvoir incroyable de créer des liens avec n’importe quel Pokémon."}, {"g": "Y", "t": "Il possède l’étrange pouvoir de s’entendre avec n’importe quel Pokémon."}],
  491: [{"g": "Noir", "t": "Menacé, ce Pokémon se protège en créant des cauchemars dans l’esprit de ses ennemis."}, {"g": "X", "t": "Il endort humains et Pokémon, et leur fait avoir des cauchemars pour les chasser de son territoire."}, {"g": "Y", "t": "Il a la capacité de bercer les gens pour les faire rêver. Il se montre durant les nuits de nouvelle lune."}],
  492: [{"g": "Noir", "t": "Les fleurs qui couvrent son corps s’ouvrent quand il est câliné avec amour et perçoit de la gratitude."}, {"g": "X", "t": "Il peut dissoudre les toxines dans l’air pour transformer un désert en un champ de fleurs luxuriantes."}, {"g": "Y", "t": "Il prend son essor pour répandre la gratitude lorsque les Gracidées fleurissent."}],
  493: [{"g": "Noir", "t": "On dit que son œuf a éclos dans le néant et qu’il est à l’origine de la création du monde."}, {"g": "X", "t": "La mythologie de Sinnoh veut qu’il soit apparu sous forme d’Œuf et ait créé le monde."}, {"g": "Y", "t": "Dans la mythologie, ce Pokémon existait déjà avant la formation de l’univers."}],
  494: [{"g": "Noir", "t": "Un Pokémon qui amène la victoire. On dit que les Dresseurs qui le possèdent peuvent gagner n’importe quel combat."}, {"g": "Blanc", "t": "Son corps produit une énergie sans limites qu’il peut partager avec ceux qu’il touche."}, {"g": "Y", "t": "L’énergie sans limites qu’il produit donne une force incroyable à ceux qui entrent en contact avec elle."}],
  495: [{"g": "Noir", "t": "Un Pokémon intelligent et très calme. Lorsqu’il a reçu suffisamment de lumière du soleil, il devient plus agile."}, {"g": "Blanc", "t": "Il laisse sa queue prendre le soleil pour sa photosynthèse. Quand il est malade, sa queue pend tristement."}, {"g": "X", "t": "La lumière du soleil augmente fortement son agilité. Ses lianes sont plus habiles que ses mains."}],
  496: [{"g": "Noir", "t": "Il court comme s’il glissait sur le sol. Il déroute l’ennemi par ses mouvements et l’assomme d’un coup de liane."}, {"g": "Blanc", "t": "Il évite les coups en se cachant dans la végétation luxuriante et contre-attaque habilement avec un bon coup de liane."}, {"g": "Y", "t": "La saleté l’empêchant d’utiliser la photosynthèse, il prend grand soin d’être toujours propre."}],
  497: [{"g": "Noir", "t": "Il peut paralyser l’ennemi d’un regard. Il amplifie l’énergie du soleil dans son corps."}, {"g": "Blanc", "t": "Il garde la tête haute pour intimider l’ennemi, et ne combat sérieusement que les ennemis les plus puissants."}, {"g": "X", "t": "Il ne donnera tout son potentiel que contre un ennemi puissant indifférent à son regard écrasant de noblesse."}],
  498: [{"g": "Noir", "t": "Il évite agilement les attaques ennemies et crache des boules de feu par le groin. Il aime griller des Baies pour les manger."}, {"g": "Blanc", "t": "Il crache du feu par le groin. Mais quand il est enrhumé, seule une fumée noirâtre en sort."}, {"g": "Y", "t": "Il adore se goinfrer de Baies grillées, mais il lui arrive de les réduire en cendres dans son excitation."}],
  499: [{"g": "Noir", "t": "Quand le feu dans son corps s’embrase, sa vitesse et son agilité augmentent. En cas d’urgence, il crache de la fumée."}, {"g": "Blanc", "t": "Ce qu’il mange devient du combustible pour le feu dans son estomac. La colère vivifie ses flammes."}, {"g": "X", "t": "Plus il a mangé de Baies, plus il a de combustible, et il peut donc dégager davantage de flammes et de puissance."}],
  500: [{"g": "Noir", "t": "Il embrase ses poings avec les flammes sur son menton et cogne l’ennemi avec. C’est un Pokémon très solidaire."}, {"g": "Blanc", "t": "Il a une barbe enflammée. Il maîtrise des techniques de combat au corps à corps rapides et puissantes."}],
  501: [{"g": "Noir", "t": "Il combat avec le coupillage de son ventre. Il peut parer un assaut et immédiatement contre-attaquer."}, {"g": "Blanc", "t": "Le coupillage sur son ventre est fait de la même matière que ses griffes. Il le détache pour l’utiliser comme une dague."}, {"g": "X", "t": "Le coupillage sur son ventre lui sert non seulement à combattre, mais aussi à trancher les Baies très dures."}],
  502: [{"g": "Noir", "t": "L’apprentissage de sa technique de combat, qui utilise élégamment ses deux coupillages, est extrêmement rigoureux."}, {"g": "Blanc", "t": "Chaque Mateloutre a sa propre technique d’escrime au coupillage, dont il prend un soin tout particulier."}, {"g": "Y", "t": "Chaque Mateloutre a sa propre technique d’escrime au coupillage, acquise grâce à un entraînement drastique."}],
  503: [{"g": "Noir", "t": "Il peut terrasser ses ennemis d’un coup de la lame enchâssée dans son armure, et les faire taire d’un seul regard."}, {"g": "Blanc", "t": "Les pièces d’armure sur ses pattes antérieures sont de grandes lames. Un simple cri peut intimider son ennemi."}, {"g": "X", "t": "Il dissimule de grandes lames qu’il dégaine en un éclair des fourreaux de ses pattes antérieures."}],
  504: [{"g": "Noir", "t": "Ils stockent à manger dans leurs bajoues et font le guet indéfiniment. Ils se font des signes en remuant la queue."}, {"g": "Blanc", "t": "Ils sont très inquiets et se relaient pour surveiller le territoire autour de leur nid. Sans guetteurs, ils ont peur."}, {"g": "Y", "t": "Très prudent, il surveille attentivement son territoire, mais oublie souvent de regarder derrière lui."}],
  505: [{"g": "Noir", "t": "Il attaque en crachant les graines des Baies qu’il accumule dans ses bajoues. S’il voit un ennemi, il dresse la queue."}, {"g": "Blanc", "t": "Il intimide l’ennemi en faisant briller les motifs de son pelage. Ses yeux peuvent voir même dans l’obscurité."}, {"g": "X", "t": "Il intimide l’ennemi en faisant briller son pelage et ses yeux grâce à une substance à l’intérieur de son corps."}],
  506: [{"g": "Noir", "t": "Il fait vaillamment face à des ennemis très puissants, mais il est intelligent et évite les combats trop inégaux."}, {"g": "Blanc", "t": "Les longs poils de son museau font un excellent radar qui analyse les alentours avec une grande acuité."}, {"g": "Y", "t": "Bien que vaillant, il a aussi l’intelligence d’analyser toutes les situations et de fuir quand il anticipe une défaite."}, {"g": "Soleil", "t": "Très sage, il n’aboie et ne mord pas sans raison, ce qui en fait un Pokémon domestique très apprécié des Dresseurs casaniers."}, {"g": "Lune", "t": "Les poils qui masquent son visage lui servent de radar, et lui permettent ainsi d’évaluer la position et la puissance de ses ennemis."}, {"g": "Ultra-Soleil", "t": "Réputé pour sa grande perspicacité, il s’enfuit la queue entre les pattes s’il s’estime trop faible pour gagner."}, {"g": "Ultra-Lune", "t": "Sa docilité en fait un Pokémon facile à élever. Il est notamment populaire auprès des Dresseurs débutants."}, {"g": "Épée", "t": "Ce Pokémon est courageux, mais prudent. Les poils doux qui recouvrent son visage lui permettent de sonder les alentours."}, {"g": "Bouclier", "t": "Ce Pokémon est plus intelligent que la plupart des enfants. Il n’oublie ni l’affection qu’il a reçue ni les mauvais traitements qu’il a pu subir."}],
  507: [{"g": "Noir", "t": "Les poils qui entourent son corps comme un manteau sont extrêmement durs et amortissent les coups."}, {"g": "Blanc", "t": "Il obéit fidèlement aux consignes. Il assiste les Dresseurs depuis très longtemps."}, {"g": "X", "t": "Un Pokémon très loyal qui aide aussi bien les Dresseurs que les autres Pokémon qu’il rencontre."}, {"g": "Soleil", "t": "Son poil long et très dur, pousse à une vitesse ahurissante, et son toilettage coûte un bras. Une plaie à élever."}, {"g": "Lune", "t": "Il est entièrement dévoué aux ordres de son maître. En revanche, il n’obéira jamais à quelqu’un qu’il considère comme inférieur à lui."}, {"g": "Ultra-Soleil", "t": "Son pelage sombre devient si robuste au fil du temps que même des crocs ou des griffes peinent à passer au travers."}, {"g": "Ultra-Lune", "t": "Cela fait si longtemps que ce Pokémon vit en harmonie avec les humains qu’il apparaît même sur des peintures rupestres antiques."}, {"g": "Épée", "t": "Ce Pokémon est très intelligent et affectueux. Une théorie avance qu’il aurait été le premier à devenir le partenaire d’un être humain."}, {"g": "Bouclier", "t": "Les poils sombres qui recouvrent son dos sont si épais et si souples qu’ils peuvent même repousser des crocs acérés."}],
  508: [{"g": "Noir", "t": "Il sauve les gens bloqués dans les montagnes par des tempêtes de neige. Ses longs poils le protègent du froid."}, {"g": "Blanc", "t": "Il est spécialisé dans l’assistance aux personnes perdues en mer ou en montagne. Il est très intelligent."}, {"g": "Y", "t": "Sa soyeuse fourrure à poils longs est assez chaude pour supporter de longues nuits d’hiver en montagne."}, {"g": "Soleil", "t": "Sagesse, gentillesse et bravoure sont les mots qui qualifient le mieux ce Pokémon, devenu l’inséparable partenaire des équipes de secours."}, {"g": "Lune", "t": "Modèle de sagesse, il ne s’en prend jamais aux humains sans raison, et assume volontiers le rôle de nounou pour les parents occupés."}, {"g": "Ultra-Soleil", "t": "Son long pelage le protège parfaitement du froid. Malheureusement pour lui, cela n’est pas très utile à Alola."}, {"g": "Ultra-Lune", "t": "Il possède un pelage long et épais. Jadis, dans les régions froides, chaque foyer en élevait un."}, {"g": "Épée", "t": "Il apprécierait tant la compagnie des êtres humains qu’il ne faudrait pas plus de trois jours pour apprivoiser un Mastouffe sauvage."}, {"g": "Bouclier", "t": "Sa moustache remarquable fait sa fierté, car sa longueur permettrait de déterminer la hiérarchie au sein de l’espèce."}],
  509: [{"g": "Noir", "t": "Il vole les gens pour le plaisir, mais il est tellement mignon que ses victimes finissent toujours par lui pardonner."}, {"g": "Blanc", "t": "Il détourne l’attention de ses victimes avec ses gestes mignons pour mieux les détrousser. En colère, il griffe."}, {"g": "Épée", "t": "Il vole les biens des personnes rien que pour voir leur visage désemparé. Son plus grand rival est Goupilou."}, {"g": "Bouclier", "t": "Malheur à qui se laisse berner par ses gestes adorables : une fois les gens à sa portée, il les griffe sans crier gare, en ricanant."}],
  510: [{"g": "Noir", "t": "Un Pokémon insaisissable. Son style et son pelage magnifique attirent de nombreux Dresseurs."}, {"g": "Blanc", "t": "Il s’approche sans un bruit de sa proie et l’abat d’un coup par derrière sans jamais être repéré."}, {"g": "X", "t": "Sa ligne élégante cache une musculature féline qui lui permet de surprendre lors de ses attaques nocturnes."}, {"g": "Y", "t": "Il s’approche sans un bruit de sa proie et l’abat d’un coup par-derrière sans jamais être repéré."}, {"g": "Épée", "t": "On se laisse facilement éblouir par son pelage magnifique et son allure élégante, mais gare à son caractère imprévisible et agressif."}, {"g": "Bouclier", "t": "Sans un bruit, il approche ses victimes par-derrière pour les frapper. Il dispute son territoire avec les Roublenard."}],
  511: [{"g": "Noir", "t": "Il vit dans les forêts profondes. Manger la feuille qui pousse sur sa tête fait disparaître la fatigue."}, {"g": "Blanc", "t": "Les feuilles qui poussent sur sa tête soignent la fatigue. Il en donne aux Pokémon affaiblis."}, {"g": "Y", "t": "Il est très doué pour trouver des Baies et aime les partager avec ses amis sans rien demander en échange."}],
  512: [{"g": "Noir", "t": "Il a un tempérament violent et se bat avec sa queue pleine d’épines. La feuille sur sa tête est très amère."}, {"g": "Blanc", "t": "Il frappe ses ennemis avec sa queue couverte de pointes. Un Pokémon au caractère agressif."}],
  513: [{"g": "Noir", "t": "Quand il s’énerve, la mèche sur sa tête chauffe à 300 °C. Il s’en sert pour griller des Baies et les manger."}, {"g": "Blanc", "t": "Il vit dans les cratères des volcans. L’intérieur de la mèche qu’il a sur la tête peut atteindre 300 °C."}, {"g": "X", "t": "Un Pokémon très intelligent qui adore cuire ses Baies avant de les manger. Il aime aussi aider les humains."}],
  514: [{"g": "Noir", "t": "Il adore les aliments sucrés. Ils lui servent d’énergie pour alimenter le feu à l’intérieur de son corps."}, {"g": "Blanc", "t": "Son corps est en combustion. Il projette des flammèches par la tête et la queue pour carboniser ses ennemis."}, {"g": "Y", "t": "Quand il est excité, des flammèches brûlantes dansent sur sa tête et sa queue. Il raffole des choses sucrées."}],
  515: [{"g": "Noir", "t": "L’eau contenue dans la mèche sur sa tête est pleine de nutriments. Elle fait pousser les plantes avec vigueur."}, {"g": "Blanc", "t": "Il supporte mal les environnements secs. Il s’humidifie avec sa queue en aspirant l’eau stockée dans la mèche sur sa tête."}, {"g": "X", "t": "Sa houppette est chargée d’eau et de nutriments. Il nourrit les plantes et les arbres avec sa queue."}],
  516: [{"g": "Noir", "t": "Il stocke de l’eau dans les mèches de sa tête. Quand il est à sec, il se ravitaille en aspirant de l’eau par la queue."}, {"g": "Blanc", "t": "Le jet d’eau à haute pression qu’il propulse par la queue est assez puissant pour traverser un mur de béton."}, {"g": "Y", "t": "Il aime les endroits où l’eau est pure. Il se ravitaille en eau en l’aspirant avec sa queue."}],
  517: [{"g": "Noir", "t": "Quand Munna mange un rêve, celui-ci est aussitôt oublié par le rêveur. Il lévite en permanence."}, {"g": "Blanc", "t": "Il se nourrit des rêves des gens et des Pokémon. Quand le rêve est agréable, il crache une fumée rose."}, {"g": "X", "t": "Il apparaît aux humains et aux Pokémon qui font des mauvais rêves et mange leurs cauchemars pour les en libérer."}, {"g": "Épée", "t": "Il apparaît en pleine nuit, à côté de l’oreiller. Quand il se nourrit de rêves, les motifs de son corps luisent légèrement."}, {"g": "Bouclier", "t": "Il se nourrit de songes et expire de la fumée qui prend la couleur rose si le rêve est joyeux, ou noire s’il s’agit d’un cauchemar."}],
  518: [{"g": "Noir", "t": "La fumée qui sort de son front contient les rêves de nombreuses personnes et ceux de nombreux Pokémon."}, {"g": "Blanc", "t": "Il peut matérialiser les rêves qu’il a mangés. La fumée qui sort de son front prend la forme des objets vus en rêve."}, {"g": "Y", "t": "La fumée qui sort de son front change de couleur selon le contenu des rêves qu’il a mangés."}, {"g": "Épée", "t": "Il est recommandé de ne pas l’approcher quand la fumée qui sort de son front a une teinte noire, sinon son cauchemar risque de se matérialiser."}, {"g": "Bouclier", "t": "Il est sans cesse assoupi, plongé dans ses rêves. Il vaut mieux éviter de le déranger, car il est toujours mal luné au réveil."}],
  519: [{"g": "Noir", "t": "Il suit scrupuleusement les consignes de son Dresseur, mais il a du mal à comprendre les ordres trop compliqués."}, {"g": "Blanc", "t": "Ces Pokémon vivent en ville. Ils sont peu farouches et se regroupent souvent dans les parcs ou sur les places."}, {"g": "X", "t": "Un Pokémon très distrait qui oublie les ordres de son Dresseur et reste planté à en attendre de nouveaux."}, {"g": "Épée", "t": "On en trouve là où vivent les humains. Mieux vaut éviter de les nourrir, sous peine d’en voir arriver des centaines."}, {"g": "Bouclier", "t": "Il n’est pas très malin et un peu distrait, mais beaucoup de Dresseurs l’apprécient pour son caractère affectueux et sa bonne volonté."}],
  520: [{"g": "Noir", "t": "Aussi éloigné qu’il puisse se trouver, il parvient toujours à retourner auprès de son Dresseur."}, {"g": "Blanc", "t": "On dit que tout au fond de la forêt où il vit, il y aurait un pays paisible qui n’a jamais connu la guerre."}, {"g": "Y", "t": "Quel que soit le lieu où il se trouve, il arrive toujours à retrouver son Dresseur comme son propre nid."}, {"g": "Épée", "t": "Il vole relativement vite et peut parcourir des kilomètres sans oublier où se trouvent son Dresseur et son nid."}, {"g": "Bouclier", "t": "Il est intelligent et possède une bonne mémoire. On raconte que les livreurs le choisissent souvent comme partenaire."}],
  521: [{"g": "Noir", "t": "Le mâle intimide ses ennemis avec ses caroncules. La femelle vole mieux que le mâle."}, {"g": "Blanc", "t": "Le mâle a une parure sur la tête. Ils sont très farouches et ne s’attachent qu’à leur Dresseur."}, {"g": "Y", "t": "Ils sont très farouches et ne s’attachent qu’à leur Dresseur. Les mâles ont une parure sur la tête."}, {"g": "Épée", "t": "Ce Pokémon a une excellente technique de vol. Les femelles ont plus d’endurance que les mâles, mais ces derniers peuvent voler plus vite."}, {"g": "Bouclier", "t": "Ce Pokémon est aussi intelligent qu’il est arrogant. Les Dresseurs de Déflaisan sont tenus en haute estime."}],
  522: [{"g": "Noir", "t": "Leur crinière scintille quand ils lâchent une décharge électrique. Ils se servent de ces scintillements pour communiquer."}, {"g": "Blanc", "t": "Il apparaît quand le ciel est à l’orage. Il capte les éclairs avec sa crinière et accumule de l’électricité."}, {"g": "Y", "t": "Sa crinière luit quand il lâche des décharges. Il module leur rythme et leur nombre pour communiquer avec ses pairs."}],
  523: [{"g": "Noir", "t": "Il réagit à la vitesse de l’éclair. Lorsqu’il est en plein galop, on peut entendre le grondement du tonnerre."}, {"g": "Blanc", "t": "Il est agressif et projette des charges électriques dans toutes les directions quand il est en colère. Faites attention!"}, {"g": "X", "t": "De caractère violent, il envoie avec sa crinière des arcs électriques de tous les côtés lorsqu’il se sent provoqué."}],
  524: [{"g": "Noir", "t": "Il a une oreille hexagonale. Son corps, compressé dans des strates profondes, est dur comme de l’acier."}, {"g": "Blanc", "t": "On l’a découvert dans une fissure après un grand tremblement de terre il y a 100 ans. Il possède un noyau d’énergie."}, {"g": "Soleil", "t": "Ce Pokémon est né dans les entrailles de la terre. Il adore comparer sa solidité à celle de ses amis, Racaillou et Strassie."}, {"g": "Lune", "t": "La cavité hexagonale qu’il arbore est son oreille. Il se précipite vers tout ce qu’il entend, mais perd l’équilibre et chute dès que le son s’arrête."}, {"g": "Ultra-Soleil", "t": "Sa cavité hexagonale est une oreille. Il se met en colère si l’on tente d’y plonger la main, car c’est là que se trouve son noyau d’énergie."}, {"g": "Ultra-Lune", "t": "Ce Pokémon a été découvert dans une faille rocheuse. La terre qui constitue son corps remonte à plusieurs centaines d’années."}, {"g": "Épée", "t": "Son corps est aussi dur que le fer, mais si on le laisse longtemps dans l’eau, il paraît qu’il ramollit légèrement."}, {"g": "Bouclier", "t": "Il se déplace en réagissant aux sons environnants. Son noyau d’énergie rend son corps légèrement chaud au toucher."}],
  525: [{"g": "Noir", "t": "Quand il est gonflé à bloc, ses cristaux orangés scintillent. Il cherche de l’eau souterraine dans les grottes."}, {"g": "Blanc", "t": "L’énergie de son corps qu’il ne parvient pas à retenir s’écoule à l’extérieur et forme des cristaux orangés."}, {"g": "Y", "t": "Quand il est en forme, son noyau devient visible. Il peut se déplacer dans toutes les directions sans se tourner."}, {"g": "Soleil", "t": "Chaque cristal orangé sur son corps est un condensé d’énergie pouvant fournir du carburant à une centaine de poids lourds."}, {"g": "Lune", "t": "Il explore les grottes à la recherche de nappes phréatiques. L’eau étant l’une de ses faiblesses, il ne peut la boire que par petites lapées."}, {"g": "Ultra-Soleil", "t": "L’énergie qui émane de son corps s’est transformée en cristaux orangés suffisamment durs pour briser le diamant."}, {"g": "Ultra-Lune", "t": "Géolithe est parfois pris pour cible à cause de ses cristaux orangés de grande valeur, formés d’énergie condensée."}, {"g": "Épée", "t": "Mieux vaut rester sur ses gardes quand ses cristaux orange se mettent à briller, car cela indique qu’il va déchaîner son énergie pour frapper."}, {"g": "Bouclier", "t": "Il sonde les environs grâce au son. Lorsqu’un importun le met en colère, il se lance à sa poursuite sans changer l’orientation de son corps."}],
  526: [{"g": "Noir", "t": "Il comprime de l’énergie dans son corps, et ses attaques sont assez puissantes pour renverser des montagnes."}, {"g": "Blanc", "t": "Il amplifie dans son corps l’énergie du soleil absorbée par ses cristaux orangés et la projette par la bouche."}, {"g": "X", "t": "Il amplifie dans son noyau l’énergie du soleil absorbée par son corps et la projette en une boule de lumière."}, {"g": "Soleil", "t": "Il absorbe les rayons solaires pour tirer des balles d’énergie incroyablement destructrices. Une arme inutilisable s’il pleut ou s’il fait nuit."}, {"g": "Lune", "t": "Ce Pokémon jouit d’une force physique hors-norme, ce qui fait de lui le meilleur allié des chefs de chantier."}, {"g": "Ultra-Soleil", "t": "D’innombrables fissures se dessinent à la surface de son corps lorsqu’il déchaîne toute son énergie."}, {"g": "Ultra-Lune", "t": "Il peut absorber les rayons du soleil et les rejeter sous forme d’énergie, mais il se cache généralement au plus profond de la terre."}, {"g": "Épée", "t": "Sa robustesse lui vaut parfois de travailler sur les chantiers et dans les carrières en compagnie des Hommes et des Pachyradjah."}, {"g": "Bouclier", "t": "Il est capable d’envoyer des boules d’énergie assez puissantes pour balayer un camion-benne, mais il ne peut tirer que les jours ensoleillés."}],
  527: [{"g": "Noir", "t": "Il vit dans les forêts sombres et les grottes. Il émet des ultrasons par le nez pour se diriger."}, {"g": "Blanc", "t": "Il s’accroche aux murs des cavernes en se servant de son nez comme ventouse. Il y laisse une trace en forme de cœur."}, {"g": "Y", "t": "Son nez est comme une ventouse. Il laisse une marque en forme de cœur qui, paraît-il, porte bonheur."}, {"g": "Épée", "t": "La présence de marques en forme de cœur sur les parois des grottes indique la présence de Chovsourir à l’intérieur."}, {"g": "Bouclier", "t": "Il virevolte gaiement et émet des ultrasons pour trouver des Pokémon Insecte à grignoter."}],
  528: [{"g": "Noir", "t": "Il émet des ondes sonores de différentes fréquences par le nez. Certaines peuvent briser des rochers."}, {"g": "Blanc", "t": "Le mâle courtise la femelle à l’aide d’ultrasons. Les écouter met de très bonne humeur."}, {"g": "X", "t": "Sa queue s’agite frénétiquement quand il émet ses ultrasons assez puissants pour pulvériser du béton."}, {"g": "Épée", "t": "Émettre des ondes sonores ultra-puissantes le fatigue tellement qu’il n’a plus de forces pour voler."}, {"g": "Bouclier", "t": "Certaines contrées le vénèrent et pensent que la forme de son nez est un symbole de chance et de bonheur."}],
  529: [{"g": "Noir", "t": "Il peut creuser à plus de 50 km/h et faire la course avec une voiture roulant sur le terrain qu’il creuse."}, {"g": "Blanc", "t": "Il se propulse à grande vitesse sous la terre en joignant ses griffes et en tourbillonnant sur lui-même."}, {"g": "Y", "t": "Il tourbillonne sur lui-même pour se déplacer sous terre. Il peut atteindre les 50 km/h en ligne droite."}, {"g": "Épée", "t": "Il fonce sur ses proies en joignant ses griffes et en tourbillonnant sur lui-même."}, {"g": "Bouclier", "t": "Les cultivateurs le détestent, car il abîme leurs légumes en creusant la terre avec ses griffes."}],
  530: [{"g": "Noir", "t": "Ses vrilles en acier peuvent transpercer des poutres en fer. Il est très employé dans la construction de tunnels."}, {"g": "Blanc", "t": "Il se creuse des terriers labyrinthiques à 100 m sous terre. Il lui arrive de percer les galeries du métro."}, {"g": "Épée", "t": "On confond souvent les cavernes creusées par les Minotaupe avec des grottes naturelles."}, {"g": "Bouclier", "t": "On l’appelle le « roi de la vrille ». Il creuse la terre à une vitesse pouvant atteindre 150 km/h."}],
  531: [{"g": "Noir", "t": "Il ausculte les gens avec ses antennes auriculaires pour juger de leurs émotions ou de leur santé."}, {"g": "Blanc", "t": "Sa capacité auditive est exceptionnelle. Il émet des sons imperceptibles pour sonder les alentours, comme un sonar."}, {"g": "X", "t": "Son ouïe est si développée qu’il arrive à juger de la santé des gens ou à savoir quand un Œuf va éclore."}, {"g": "Épée", "t": "Son ouïe est si fine qu’il est capable d’entendre un caillou tomber à 2 km."}, {"g": "Bouclier", "t": "Ce Pokémon gentil est capable de deviner les émotions et l’état de santé des autres rien qu’en les touchant avec ses antennes."}],
  532: [{"g": "Noir", "t": "Il combat avec une poutre. Quand il en arrive à transporter de lourds madriers sans problème, l’évolution est proche."}, {"g": "Blanc", "t": "Il porte toujours une poutre. Il apparaît sur les chantiers pour aider aux travaux."}, {"g": "Y", "t": "Il porte toujours une poutre en bois et aime aider aux travaux. Il passe à un lourd madrier quand il grandit."}, {"g": "Épée", "t": "Il aime donner un coup de main sur les chantiers. Lorsque le travail cesse à cause de la pluie, il brandit sa poutre de colère."}, {"g": "Bouclier", "t": "Lorsque Charpenti est capable de soulever une poutre faisant trois fois son poids, le jour de son évolution est proche."}],
  533: [{"g": "Noir", "t": "Même une armée de catcheurs se jetant sur son corps hyper musclé ne le ferait pas ciller."}, {"g": "Blanc", "t": "Il entretient sa forme en transportant une poutre en acier et fait des concours de culturisme avec ses camarades."}, {"g": "X", "t": "Ce Pokémon hyper musclé manipule avec habileté les poutres métalliques et peut démanteler un immeuble en un clin d’œil."}, {"g": "Épée", "t": "Il participe à des concours de gonflette avec ses congénères et les Machopeur. Le perdant ne se montre plus en public pendant quelque temps."}, {"g": "Bouclier", "t": "Il manie la poutre métallique avec habileté. Il est doué pour démanteler une bâtisse, mais peu adroit lorsqu’il s’agit d’en construire une."}],
  534: [{"g": "Noir", "t": "On pense que la recette du ciment a été enseignée aux humains par un Bétochef il y a 2 000 ans."}, {"g": "Blanc", "t": "Il peut manier sans effort apparent les piliers de béton dont il se sert comme de cannes."}, {"g": "Y", "t": "Il utilise l’effet centrifuge pour manier sans trop d’effort ses piliers de béton et déclencher des attaques puissantes."}, {"g": "Épée", "t": "Le béton préparé par Bétochef est bien plus solide qu’un béton ordinaire, même si les mêmes ingrédients sont utilisés."}, {"g": "Bouclier", "t": "Quand il décide de passer aux choses sérieuses, il jette ses piliers de béton et saute sur son adversaire pour le frapper du poing."}],
  535: [{"g": "Noir", "t": "Il prévient ses camarades du danger en faisant vibrer ses joues pour générer un signal d’alarme très aigu."}, {"g": "Blanc", "t": "Il fait vibrer ses joues pour émettre des sons imperceptibles pour l’homme. Il communique grâce à leur rythme."}, {"g": "X", "t": "Il fait vibrer ses joues pour émettre des sons inaudibles pour les humains et alerter ses semblables des dangers."}, {"g": "Épée", "t": "Lorsqu’un Tritonde pousse des cris aigus sous l’eau, des ondes ravissantes se propagent à la surface."}, {"g": "Bouclier", "t": "Il communique avec ses compagnons en émettant des ondes. Son cri d’alerte est inaudible pour les humains et les autres Pokémon."}],
  536: [{"g": "Noir", "t": "Quand il fait vibrer la bosse sur sa tête, il provoque des ondulations dans l’eau, mais aussi des tremblements de terre."}, {"g": "Blanc", "t": "Il vit dans l’eau et sur la terre ferme. Il attrape ses proies avec sa langue longue et gluante."}, {"g": "Y", "t": "Il vit dans l’eau et sur la terre ferme. Il immobilise ses proies avec sa langue longue et gluante."}, {"g": "Épée", "t": "Il affaiblit ses proies en émettant des ondes si fortes qu’elles leur donnent la migraine. Ensuite, il les saisit avec sa langue gluante."}, {"g": "Bouclier", "t": "Il lui arrive de pousser des cris ravissants. Plus ses protubérances sont grosses, plus le son porte loin."}],
  537: [{"g": "Noir", "t": "Il fait gicler un liquide paralysant des pustules sur sa tête, et attaque ses ennemis à coups de vibrations."}, {"g": "Blanc", "t": "Son coup de poing est plus fort quand il fait vibrer la pustule dessus. Il peut briser un gros rocher d’un coup."}, {"g": "Épée", "t": "En faisant vibrer tous les pustules de son corps, il peut provoquer des secousses similaires à celles d’un séisme. Il est proche des Cradopaud."}, {"g": "Bouclier", "t": "Ce Pokémon est un excellent masseur grâce aux vibrations de ses pustules. Les personnes âgées l’apprécient particulièrement."}],
  538: [{"g": "Noir", "t": "Quand il noue sa ceinture, il devient plus puissant. Les Judokrak sauvages tressent leur ceinture avec des lianes."}, {"g": "Blanc", "t": "Ils aiment projeter ceux qui sont plus grands qu’eux. On les trouve toujours par groupes de cinq."}, {"g": "Y", "t": "Ils aiment projeter ceux qui sont plus grands qu’eux. Ils changent de ceinture quand ils progressent."}, {"g": "Épée", "t": "Ses techniques de projection sont sans égal. Quand il se bat, sa sueur coule sur sa ceinture et lui donne une teinte plus foncée."}, {"g": "Bouclier", "t": "Ils s’entraînent intensément par groupes de cinq. Ceux qui ne peuvent pas suivre le rythme abandonnent leur ceinture et se retirent."}],
  539: [{"g": "Noir", "t": "Dans les montagnes où il s’entraîne, on peut l’entendre donner des coups de poing aux rochers et aux grands arbres."}, {"g": "Blanc", "t": "Quand il noue sa ceinture, il est plus concentré et ses coups font plus mal. Il s’énerve si on gêne son entraînement."}, {"g": "X", "t": "Pour accéder à la maîtrise ultime du karaté, il se retire dans les montagnes et s’entraîne nuit et jour."}, {"g": "Épée", "t": "Il cherche à tout prix à devenir plus fort. Il est conseillé de ne pas le déranger quand il s’entraîne en montagne."}, {"g": "Bouclier", "t": "Après avoir suivi un entraînement intensif, la puissance du tranchant de sa main est telle qu’il peut fendre la mer en deux."}],
  540: [{"g": "Noir", "t": "Quand il éclot, Manternel lui coud son vêtement. Il dort en cachant son visage sous sa capuche."}, {"g": "Blanc", "t": "Il fait des vêtements en découpant des feuilles et en les cousant avec le fil adhésif qu’il sécrète par la bouche."}, {"g": "Y", "t": "La mascotte des créateurs de mode. Il découpe ses vêtements dans les feuilles qu’il trouve."}],
  541: [{"g": "Noir", "t": "Dans les forêts où il vit, la végétation pousse bien car il transforme les feuilles mortes en engrais."}, {"g": "Blanc", "t": "Il se protège du froid en s’emmitouflant dans une feuille. Il se déplace en forêt et mange les feuilles tombées par terre."}],
  542: [{"g": "Noir", "t": "Quand il trouve de petits Pokémon, il leur coud des vêtements de feuilles en utilisant ses coupoirs et son fil adhésif."}, {"g": "Blanc", "t": "Il réchauffe les œufs avec la chaleur de l’humus. Il fabrique des langes pour les Larveyette avec des feuilles."}, {"g": "X", "t": "Il fabrique des vêtements de feuilles pour les Pokémon encore jeunes grâce à son fil de soie adhésif."}, {"g": "Y", "t": "Il réchauffe les Œufs avec la chaleur de l’humus. Il fabrique des langes pour les Larveyette avec des feuilles."}],
  543: [{"g": "Noir", "t": "Sa morsure est très venimeuse. Elle paralyse même les grands Pokémon Oiseaux, ses prédateurs."}, {"g": "Blanc", "t": "Il sonde les alentours avec les antennes sur sa tête et sa queue. Il est extrêmement brutal."}, {"g": "Épée", "t": "Bien qu’appartenant à des espèces similaires, les Venipatte et les Grillepattes se livrent à des conflits violents lorsqu’ils se croisent."}, {"g": "Bouclier", "t": "Ses crocs sont extrêmement venimeux. Dès qu’il voit une proie à son goût, il bondit sur elle sans penser aux conséquences."}],
  544: [{"g": "Noir", "t": "Protégé par sa solide carapace, il fonce sur ses ennemis en roulant comme un pneu."}, {"g": "Blanc", "t": "En général, il reste immobile. Mais quand on l’attaque, il se met à tourbillonner à toute vitesse et fonce sur l’ennemi."}, {"g": "Épée", "t": "Il se propulse sur ses ennemis en tournant très vite sur lui-même. Il peut ainsi atteindre une vitesse d’environ 100 km/h."}, {"g": "Bouclier", "t": "Il se protège avec sa solide carapace et ses épines empoisonnées tandis qu’il rassemble l’énergie nécessaire à son évolution."}],
  545: [{"g": "Noir", "t": "Il accule l’ennemi par ses mouvements rapides et l’attaque avec ses cornes. Il ne s’arrête qu’au coup de grâce."}, {"g": "Blanc", "t": "Il inocule du poison à ses ennemis par les griffes de son cou. Il est extrêmement agressif."}, {"g": "X", "t": "Il paralyse l’ennemi avec les griffes de son cou avant de mettre fin au combat grâce à son poison virulent."}, {"g": "Épée", "t": "Après avoir saisi sa proie à l’aide des griffes de son cou, il la plaque au sol puis la transperce avec ses épines empoisonnées."}, {"g": "Bouclier", "t": "Il défend son territoire avec acharnement contre son ennemi Scolocendre. Le perdant sert de dîner au vainqueur."}],
  546: [{"g": "Noir", "t": "Si on l’attaque, il projette un nuage de coton. L’ennemi le confond avec lui, ce qui permet à Doudouvet de s’enfuir."}, {"g": "Blanc", "t": "Il dérive librement au gré du vent. Les jours de pluie, il s’alourdit et se réfugie au pied des arbres."}, {"g": "Y", "t": "Pokémon à l’instinct grégaire, ils se collent les uns aux autres et finissent par former un gros nuage."}, {"g": "Soleil", "t": "Les Doudouvet se collent entre eux quand ils se rencontrent. Lorsqu’ils sont assez nombreux, ils forment de véritables cumulonimbus vivants."}, {"g": "Lune", "t": "Le coton qu’il produit est utilisé dans la confection d’oreillers et de couettes de haute qualité, qui allient légèreté et fraîcheur."}, {"g": "Ultra-Soleil", "t": "Il projette un nuage de coton pour se protéger. Quand il pleut, son coton s’imbibe d’eau et le rend si lourd qu’il est incapable de bouger."}, {"g": "Ultra-Lune", "t": "Lorsqu’on l’attaque, il sème du coton pour faire diversion. Celui-ci repousse tout de suite."}, {"g": "Épée", "t": "Il sème du coton pour se protéger. Il lui arrive d’être emporté par une tempête à l’autre bout du monde."}, {"g": "Bouclier", "t": "Les marques de luxe utilisent les étoffes splendides issues du mélange des cotons de Doudouvet et de Blancoton."}],
  547: [{"g": "Noir", "t": "Il se faufile comme le vent par les espaces les plus étroits, en laissant une touffe de poils blancs."}, {"g": "Blanc", "t": "Il apparaît dans un tourbillon de vent, s’introduit dans les maisons par les interstices et y joue de mauvais tours."}, {"g": "X", "t": "Il apparaît dans un tourbillon de vent, s’introduit dans les maisons et y joue de mauvais tours."}, {"g": "Ultra-Lune", "t": "Ce Pokémon sans domicile fixe se laisse porter par les tornades et sème la zizanie partout où il passe."}, {"g": "Soleil", "t": "Il s’introduit chez les gens à la faveur d’un courant d’air, répand du coton aux quatre coins de la pièce puis repart comme si de rien n’était."}, {"g": "Lune", "t": "Ce Pokémon se déplace au gré du vent. Lorsqu’il souffle trop fort, il arrive que Farfaduvet perde le coton qu’il porte sur sa tête."}, {"g": "Ultra-Soleil", "t": "Ce petit chenapan s’introduit chez les gens, cache leurs affaires et répand du coton aux quatre coins de la pièce."}, {"g": "Épée", "t": "Il joue de mauvais tours en répandant son coton. Si on le mouille, il s’alourdit et ne peut plus bouger, ce qui l’oblige à s’avouer vaincu."}, {"g": "Bouclier", "t": "Son coton se met à gonfler sous les rayons du soleil. Quand il est trop volumineux, il s’effiloche et se répand aux alentours."}],
  548: [{"g": "Noir", "t": "Les feuilles sur sa tête sont très amères, mais elles remettent d’aplomb les corps les plus éreintés."}, {"g": "Blanc", "t": "Il aime les zones bien irriguées et riches en nutriments. On sait que là où il vit, les cultures sont florissantes."}, {"g": "Soleil", "t": "Les feuilles sur sa tête sont amères à en cracher ses papilles, mais peuvent requinquer les corps les plus meurtris, surtout en infusion."}, {"g": "Lune", "t": "Il est recommandé de tailler de temps à autre les feuilles de Chlorobule afin qu’il acquière une forme parfaitement ronde et harmonieuse."}, {"g": "Ultra-Soleil", "t": "En raison de leurs vertus revigorantes, les feuilles de sa tête sont séchées au soleil puis bues en infusion par les personnes âgées."}, {"g": "Ultra-Lune", "t": "À cheval sur la qualité de la terre et de l’eau, il migre avec ses congénères lorsque son environnement se dégrade."}, {"g": "Épée", "t": "Il apparaît non loin des eaux propres. On utilise parfois les infusions préparées avec les feuilles de sa tête pour éloigner les insectes."}, {"g": "Bouclier", "t": "Plus ses feuilles sont foncées, plus il est en bonne santé. Il s’installe parfois dans les champs ou les parterres de fleurs bien entretenus."}],
  549: [{"g": "Noir", "t": "Même les Dresseurs confirmés ont du mal à faire éclore sa belle fleur. Un Pokémon apprécié des célébrités."}, {"g": "Blanc", "t": "La fleur sur sa tête a des propriétés relaxantes. Elle se fane si on ne s’en occupe pas avec attention."}, {"g": "Soleil", "t": "La main la plus verte au monde ne saurait faire éclore une fleur de Fragilady aussi belle que celles qui s’épanouissent à l’état sauvage."}, {"g": "Lune", "t": "Dès lors qu’une Fragilady trouve un compagnon mâle, sa si jolie fleur se dessèche, se flétrit et finit par se faner."}, {"g": "Ultra-Soleil", "t": "Le parfum de sa fleur calme les nerfs et apaise l’esprit. Il varie légèrement selon la composition de la terre dans laquelle Fragilady a poussé."}, {"g": "Ultra-Lune", "t": "Sa beauté lui confère une grande popularité auprès des autres Pokémon. Si l’on ne prend pas soin de la fleur sur sa tête, elle fane."}, {"g": "Épée", "t": "On raconte que même les meilleurs horticulteurs ont énormément de mal à faire éclore sa fleur."}, {"g": "Bouclier", "t": "L’huile essentielle extraite de sa fleur dégage un parfum exceptionnel, mais elle coûte extrêmement cher."}],
  550: [{"g": "Noir", "t": "Les bleus et les rouges se détestent cordialement et se battent dès qu’ils s’aperçoivent. Un Pokémon très violent."}, {"g": "Blanc", "t": "Les rouges et les bleus se détestent, mais il y en a toujours un ou deux dans un groupe de l’autre couleur."}, {"g": "X", "t": "Les rouges et les bleus se détestent et se battent dès qu’ils s’aperçoivent. Un Pokémon violent mais délicieux."}, {"g": "Ultra-Soleil", "t": "C’est un Pokémon d’une grande férocité. Les Bargantua bleus et les Bargantua rouges se livrent une guerre territoriale sans merci."}, {"g": "Ultra-Lune", "t": "Il est si violent que tous les Pokémon disparaissent des lacs où un banc de Bargantua s’installe, à part les Écrapince et les Colhomard."}, {"g": "Épée", "t": "Le capturer est un défi que les Pêcheurs aiment relever. Ils vont jusqu’à en libérer illégalement dans les lacs, ce qui conduit à leur prolifération."}, {"g": "Bouclier", "t": "On l’utilisait autrefois en cuisine. La chair grasse des Bargantua à motif rouge était plutôt destinée aux jeunes."}],
  551: [{"g": "Noir", "t": "Il vit dans le sable des déserts. Le sable chauffé par le soleil empêche son corps de refroidir."}, {"g": "Blanc", "t": "Il se déplace dans le sable en gardant le nez et les yeux à découvert. La membrane noire protège ses yeux."}, {"g": "Soleil", "t": "Ce Pokémon avance tapi dans le sable, une manière pour lui de se cacher des prédateurs et de maintenir sa température corporelle."}, {"g": "Lune", "t": "Tapi dans le sable, il attend qu’une proie passe pour lui croquer la patte. Il a notamment un gros faible pour les Kraknoix en guise d’apéritif."}, {"g": "Ultra-Soleil", "t": "Les températures tropicales d’Alola sont idéales pour ce Pokémon, que l’on peut même parfois rencontrer en dehors du désert."}, {"g": "Ultra-Lune", "t": "N’étant pas très bon chasseur, il se nourrit de la charogne qu’il trouve dans les dunes, ce qui lui vaut son surnom de « nettoyeur du désert »."}, {"g": "Épée", "t": "Il se protège du froid qui sévit la nuit dans le désert en s’enfouissant profondément dans le sable, où il dort jusqu’au lever du soleil."}, {"g": "Bouclier", "t": "Malgré son petit gabarit, il a beaucoup de force dans les pattes arrière. Il parcourt le désert comme s’il nageait dans le sable."}],
  552: [{"g": "Noir", "t": "Ils vivent en petits groupes. La membrane qui couvre leurs yeux les protège du soleil."}, {"g": "Blanc", "t": "La membrane spéciale qui recouvre ses yeux détecte la chaleur et lui permet de voir dans le noir."}, {"g": "Soleil", "t": "Les Escroco se déplacent en bandes, souvent menées par une femelle. La plupart du temps, les mâles se chargent de collecter la nourriture."}, {"g": "Lune", "t": "Grâce à la membrane spéciale qui recouvre ses yeux, il peut distinguer parfaitement ses environs, même en pleine nuit."}, {"g": "Ultra-Soleil", "t": "Son corps supportant mal les baisses de température, il s’ensable profondément lorsque les nuits sont trop fraîches."}, {"g": "Ultra-Lune", "t": "Il garde une partie de ses prises en réserve dans le sable, au cas où il rentrerait bredouille de la chasse."}, {"g": "Épée", "t": "Il chasse de nuit sans difficulté grâce à ses yeux particuliers qui lui permettent de voir dans l’obscurité."}, {"g": "Bouclier", "t": "Bien que ses yeux particuliers lui permettent de voir dans l’obscurité, les nuits sont si froides dans le désert qu’il ne se déplace presque pas."}],
  553: [{"g": "Noir", "t": "Il ne laisse jamais échapper ses proies. Ses mâchoires surpuissantes peuvent broyer une voiture."}, {"g": "Blanc", "t": "Ses yeux ont les mêmes propriétés que des jumelles et lui permettent de voir les objets très éloignés en agrandi."}, {"g": "X", "t": "Un Pokémon extrêmement violent qui broie tout ce qui lui passe sous les yeux avec ses mâchoires."}, {"g": "Soleil", "t": "Ses yeux perçants lui permettent de détecter une petite proie à 50 km, même au cœur d’une tempête de sable."}, {"g": "Lune", "t": "Ses mâchoires sont si puissantes qu’il lui arrive de plier ou découper le corps de ses victimes sans même s’en rendre compte."}, {"g": "Ultra-Soleil", "t": "Il peut repérer une proie à une distance de 50 km. Il s’approche alors en « nageant » dans le sable, puis lui saute dessus pour la croquer."}, {"g": "Ultra-Lune", "t": "Lors des tempêtes de sable provoquées par Libégon, il se terre dans le sol, à l’affût d’une proie."}, {"g": "Épée", "t": "Il peut broyer d’épaisses plaques de fer d’un simple coup de mâchoire. On l’appelle le « tyran des sables »."}, {"g": "Bouclier", "t": "Il aime la violence, mais sait aussi se montrer patient lorsqu’il doit passer plusieurs jours dans le sable à attendre une proie."}],
  554: [{"g": "Noir", "t": "Quand le feu brûle dans son corps, il est tout excité et court partout. Quand le feu s’apaise, il s’endort."}, {"g": "Blanc", "t": "Les gens d’autrefois avaient l’habitude de mettre ses crottes brûlantes sous leurs vêtements pour se réchauffer."}, {"g": "Y", "t": "Quand il dort, ses pattes se rétractent et les flammes qui brûlent à 600 °C dans son corps s’apaisent."}, {"g": "Épée", "t": "La flamme qui brûle dans son corps est sa source d’énergie. Si le feu s’affaiblit, il s’endort sur-le-champ."}, {"g": "Bouclier", "t": "On a beau le pousser ou le tirer, quand il dort, rien ne le fait vaciller. Cette qualité lui a valu de devenir un emblème pour les porte-bonheurs."}],
  555: [{"g": "Noir", "t": "Il entretient des flammes à 1 400 °C dans son corps. De quoi détruire un camion-benne d’un coup de poing!"}, {"g": "Blanc", "t": "S’il a le dessous au combat, il se fige comme un rocher, fait le vide dans son esprit et combat avec sa force mentale."}, {"g": "X", "t": "S’il est blessé dans un combat, il se fige comme un rocher, fait le vide dans son esprit et aiguise ses sens."}, {"g": "Y", "t": "Il entretient des flammes à 1 400 °C dans son corps. De quoi détruire un camion-benne d’un coup de poing !"}, {"g": "Épée", "t": "Véritable tête brûlée, il possède assez de force dans ses gros bras pour réduire en poussière un camion-benne à coups de poing."}, {"g": "Bouclier", "t": "Sa puissance augmente à mesure que la flamme de son corps s’intensifie. La température de celle-ci peut parfois dépasser les 1 400 °C."}],
  556: [{"g": "Noir", "t": "Avec une danse et des sons saccadés, il fait fuir ses prédateurs, les Pokémon Oiseaux dévoreurs de graines de fleur."}, {"g": "Blanc", "t": "Il vit dans les endroits secs. Quand il bouge son corps en rythme, il fait un bruit de maracas."}, {"g": "Épée", "t": "Il produit un bruit de maracas. Quand il danse à un rythme enjoué, il surprend les Pokémon oiseaux, qui s’enfuient alors à tire-d’aile."}, {"g": "Bouclier", "t": "Il sème les graines de ses fleurs une fois par an. Celles-ci abondent en nutriments et représentent une denrée précieuse dans le désert."}],
  557: [{"g": "Noir", "t": "Il peut facilement creuser son trou dans les pierres les plus dures grâce au liquide sécrété par sa bouche."}, {"g": "Blanc", "t": "Il perce un caillou et s’en sert comme maison. Quand on lui casse, il est anxieux jusqu’à ce qu’il en trouve un autre."}, {"g": "Y", "t": "Lorsqu’il trouve un caillou à sa taille, il y creuse un trou avec le fluide qui sort de sa bouche et s’en sert comme maison."}, {"g": "Épée", "t": "Quand il trouve un caillou qui lui plaît, il y creuse un trou et s’en sert comme d’une maison. C’est l’ennemi juré des Nodulithe et des Charbi."}, {"g": "Bouclier", "t": "S’il ne trouve pas de bon caillou à creuser pour s’y loger, il élit domicile dans un des trous du corps d’Hippodocus."}],
  558: [{"g": "Noir", "t": "Entre eux, les querelles de territoire sont fréquentes et violentes. Celui qui se fait briser son rocher a perdu."}, {"g": "Blanc", "t": "Il est assez endurant pour voyager des jours durant dans des zones desséchées avec son lourd rocher sur le dos."}, {"g": "Épée", "t": "Il préfère les endroits secs, et rentre dans son rocher quand il pleut. Il défend farouchement son territoire."}, {"g": "Bouclier", "t": "Ses meilleures armes sont ses pinces. Elles sont si dures qu’elles peuvent ébrécher les Protecteurs de Rhinastoc."}],
  559: [{"g": "Noir", "t": "Il remonte sa peau jusqu’à son cou pour se protéger. Elle a une constitution élastique qui absorbe les coups."}, {"g": "Blanc", "t": "Quiconque a le malheur de croiser son regard se prend un coup de tête. Il a le crâne très dur."}, {"g": "Y", "t": "Ses coups de tête sont sa fierté. Seul problème : sa tête est un peu trop lourde, et il perd souvent l’équilibre."}, {"g": "Ultra-Soleil", "t": "Il traîne en bandes et distribue des coups de tête à ceux qui osent croiser son regard."}, {"g": "Ultra-Lune", "t": "Pour se protéger, il remonte sa peau plissée jusqu’à son cou. Plus la peau est longue, plus Baggiguane inspirera de respect."}, {"g": "Épée", "t": "C’est un Pokémon dangereux qui distribue des coups de tête à quiconque ose croiser son regard."}, {"g": "Bouclier", "t": "Il se protège grâce à sa peau robuste. On dit que quand celle-ci ne peut plus s’étirer davantage, c’est qu’il est sur le point d’évoluer."}],
  560: [{"g": "Noir", "t": "Ils se regroupent pour rosser ceux qui pénètrent sur leur territoire. Ils crachent un venin corrosif."}, {"g": "Blanc", "t": "La plus grande crête détermine le meneur du groupe. Il détruit des blocs de béton à coups de pied."}, {"g": "X", "t": "Son baggy de peau le protège quand il donne des coups de pied. Les meneurs sont ceux qui ont la plus grande crête."}, {"g": "Ultra-Soleil", "t": "Ses airs de gros dur cachent en fait un grand cœur dévoué à sa famille, sa bande et son territoire."}, {"g": "Ultra-Lune", "t": "Il provoque ses ennemis en crachant. Il passe toute sa vie sans s’aventurer hors des frontières bien définies de son territoire."}, {"g": "Épée", "t": "Son coup de pied nonchalant possède une force de destruction si grande qu’il peut briser les piliers en béton de Bétochef."}, {"g": "Bouclier", "t": "Il est de nature violente, mais au fond de lui, il tient à sa famille, à ses amis et à son territoire."}],
  561: [{"g": "Noir", "t": "On dit qu’il parcourt toujours le même itinéraire parce qu’il a gardé la mémoire de la ville antique qu’il protégeait."}, {"g": "Blanc", "t": "Il était le dieu protecteur d’une ville antique. Il repoussait les envahisseurs à coups de pouvoir psychique."}, {"g": "Y", "t": "Dieu protecteur d’une ville antique, il suivait toujours le même itinéraire afin de prévenir tout risque d’invasion."}, {"g": "Épée", "t": "Il vole grâce à ses pouvoirs psychiques. Certains disent qu’il était le dieu protecteur d’une ville antique, d’autres, son messager."}, {"g": "Bouclier", "t": "En fouillant sous le sable du désert survolé par Cryptéro, on a retrouvé les vestiges de ce que l’on croit être une ville antique."}],
  562: [{"g": "Noir", "t": "Le motif de son masque est son visage quand il était humain. Parfois, il le regarde et se met à pleurer."}, {"g": "Blanc", "t": "Il est né de l’âme d’un défunt inhumé dans une tombe antique. Il a conservé ses anciens souvenirs."}, {"g": "Épée", "t": "Il passe ses nuits à errer dans les ruines. On raconte que le masque qu’il porte représente son visage quand il était humain."}, {"g": "Bouclier", "t": "Il est né de l’âme d’un être humain d’un peuple antique. Il erre dans les ruines à la recherche de quiconque reconnaîtra son visage."}],
  563: [{"g": "Noir", "t": "Il paraît qu’il avale les gens et les transforme en momies. Il adore manger des lingots d’or."}, {"g": "Blanc", "t": "Il prend l’apparence d’un beau cercueil pour punir les pilleurs de tombes. Son corps est recouvert d’or pur."}, {"g": "Y", "t": "Il prend l’apparence d’un beau cercueil. Les pilleurs de tombes imprudents finissent enfermés à l’intérieur."}, {"g": "Épée", "t": "Son corps en or brille de mille feux. On raconte qu’il ne se souvient désormais plus de l’époque où il était un être humain."}, {"g": "Bouclier", "t": "On le voit souvent représenté sur les murs des vieilles sépultures des rois en tant que symbole de leur richesse."}],
  564: [{"g": "Noir", "t": "Il a été recréé à partir d’un fossile préhistorique. Il peut plonger jusqu’à 1 000 mètres de profondeur."}, {"g": "Blanc", "t": "Il nageait dans les océans il y a 100 millions d’années. Il lui arrive de rallier la terre ferme pour attaquer ses proies."}, {"g": "Soleil", "t": "L’étude de sa structure squelettique suggère qu’il était autrefois capable de plonger jusqu’à 1 000 m de profondeur."}, {"g": "Lune", "t": "Ancêtre présumé de nombreuses espèces de Pokémon tortues, il peuplait les mers chaudes du monde il y a environ 100 millions d’années."}, {"g": "Ultra-Soleil", "t": "Il a été recréé à partir d’un fossile préhistorique. Il vivait autrefois dans la mer, mais avait su s’adapter pour chasser aussi sur la terre ferme."}, {"g": "Ultra-Lune", "t": "Son terrain de chasse s’étendait sur un très vaste territoire, de la terre ferme jusqu’à 1 000 m sous les mers."}, {"g": "Épée", "t": "Il vivait dans la mer pendant l’ère préhistorique. Il lui arrive de s’aventurer sur la terre ferme pour chasser, bien qu’il ne puisse que ramper."}, {"g": "Bouclier", "t": "Ancêtre présumé de nombreuses espèces de Pokémon tortues, il a été restauré à partir d’un fossile."}],
  565: [{"g": "Noir", "t": "Il vit sur terre et en mer. Ses bras surpuissants peuvent percer des trous dans la coque des paquebots."}, {"g": "Blanc", "t": "Ses mâchoires sont très puissantes. Il dévore sans distinction ses proies, l’acier et les rochers."}, {"g": "Y", "t": "Ses bras puissants serrent ses proies jusqu’à l’évanouissement. Il les dévore ensuite, carapace et os compris."}, {"g": "Soleil", "t": "Pour se constituer une carapace solide, il devait réduire en miettes les os et coquilles riches en minéraux de ses proies avant de les avaler."}, {"g": "Lune", "t": "Aussi à l’aise sur terre que dans l’eau, ce Pokémon chasse ses proies à la surface puis les entraîne sous la mer pour les noyer."}, {"g": "Ultra-Soleil", "t": "L’incroyable puissance de sa mâchoire lui permettait de broyer facilement les coquilles d’Amonistar ou d’Amonita pour les manger."}, {"g": "Ultra-Lune", "t": "Afin de renforcer sa carapace, ce Pokémon va même jusqu’à manger la coquille et les os de ses proies."}, {"g": "Épée", "t": "Il dévore les os et la coquille de ses proies, ce qui épaissit et renforce sa propre carapace."}, {"g": "Bouclier", "t": "Bien qu’il soit moins à l’aise sur terre que dans l’eau, il s’aventure sur le rivage pour se nourrir."}],
  566: [{"g": "Noir", "t": "On dit qu’il serait l’ancêtre de tous les Pokémon Oiseaux. Il ne sait pas voler et se déplace en sautant d’arbre en arbre."}, {"g": "Blanc", "t": "Un Pokémon recréé à partir d’un fossile. On pense qu’il est l’ancêtre de tous les Pokémon Oiseaux."}, {"g": "Soleil", "t": "Il est l’ancêtre commun de tous les Pokémon oiseaux. Incapable de voler, il se déplaçait en planant depuis la cime des arbres."}, {"g": "Lune", "t": "Ce Pokémon était apparemment incapable de voler. Il savait néanmoins planer depuis la cime des arbres pour fondre sur ses proies."}, {"g": "Ultra-Soleil", "t": "Il a longtemps été considéré comme l’ancêtre commun de tous les Pokémon oiseaux, mais des études récentes réfutent cette théorie."}, {"g": "Ultra-Lune", "t": "Bien qu’il ait des ailes, ce Pokémon antique recréé à partir d’un fossile est incapable de voler."}, {"g": "Épée", "t": "Les recherches ont montré que ce Pokémon restauré à partir d’un fossile ne pouvait pas voler, mais qu’il était très doué en saut."}, {"g": "Bouclier", "t": "On dit que c’est l’ancêtre des Pokémon oiseaux. Il vivait à la cime des arbres et se nourrissait de Baies et de Pokémon Insecte."}],
  567: [{"g": "Noir", "t": "Il s’envole après avoir pris de l’élan. Il est assez intelligent pour chasser ses proies en groupe."}, {"g": "Blanc", "t": "Il est plus doué pour courir que pour voler. Il fonce sur ses proies aussi vite qu’une voiture pour les attraper."}, {"g": "Y", "t": "Il est plus doué pour courir que pour voler. Il doit s’élancer à 40 km/h avant de pouvoir s’envoler."}, {"g": "Soleil", "t": "Bien qu’ayant enfin acquis la capacité de voler, ce Pokémon préférait bien souvent courir sur le sol, à une vitesse moyenne de 40 km/h."}, {"g": "Lune", "t": "Ce Pokémon avait pour habitude de chasser en groupe. Une partie de la volée était chargée d’acculer la proie, et l’autre de porter l’estoc."}, {"g": "Ultra-Soleil", "t": "Les plumes de ce Pokémon antique sont si fines que seuls les experts les plus talentueux peuvent leur rendre justice en le reconstituant."}, {"g": "Ultra-Lune", "t": "On dit que c’est l’ancêtre des Pokémon oiseaux. Les muscles de ses ailes étant assez faibles, il doit prendre son élan pour s’envoler."}, {"g": "Épée", "t": "Pour s’envoler, il doit d’abord prendre son élan sur 4 km à une vitesse de 40 km/h."}, {"g": "Bouclier", "t": "Il savait voler, mais il semble qu’il était beaucoup plus doué pour chasser ses proies sur la terre ferme."}],
  568: [{"g": "Noir", "t": "Il aime les endroits mal tenus. Le gaz qu’il rote endort pendant une semaine."}, {"g": "Blanc", "t": "Il est né de la mutation d’un sac poubelle contenant des déchets industriels."}, {"g": "Soleil", "t": "Il affectionne particulièrement les endroits insalubres. À Alola, il n’est pas rare de voir des Tadmorv courir après des Miamiasme."}, {"g": "Lune", "t": "Une fois qu’il a gobé assez d’ordures, il relâche un gaz toxique par la bouche. Ne le respirez pas, surtout s’il n’y a aucun hôpital à la ronde."}, {"g": "Ultra-Soleil", "t": "Il laisse échapper un gaz toxique quand il respire. Les Grotadmorv, par l’odeur alléchés, accourent alors en salivant."}, {"g": "Ultra-Lune", "t": "Le gaz toxique qu’il laisse échapper par sa bouche peut s’avérer dangereux pour les enfants et les jeunes Pokémon qui le respirent."}, {"g": "Épée", "t": "Il raffole des endroits sales. Si on laisse traîner des ordures dans une pièce trop longtemps, il finit par en faire son domicile."}, {"g": "Bouclier", "t": "Il est né d’un sac poubelle rempli d’ordures. Le gaz empoisonné qu’il exhale est très apprécié des Smogogo de Galar."}],
  569: [{"g": "Noir", "t": "Il étrangle ses ennemis avec son bras droit et les achève avec le gaz puant et empoisonné qu’il exhale par la bouche."}, {"g": "Blanc", "t": "Il aspire les déchets et les intègre à son corps. Les doigts de sa main droite exsudent un fluide empoisonné."}, {"g": "X", "t": "Il étrangle ses ennemis avec son bras gauche et les achève avec le gaz puant et empoisonné qu’il exhale par la bouche."}, {"g": "Y", "t": "Il aspire les déchets et les intègre à son corps pour produire des gaz et des fluides toxiques."}, {"g": "Soleil", "t": "Méfiez-vous du poison qu’il projette de son bras droit, sans quoi ses toxines non identifiées vous feront passer un sale quart d’heure."}, {"g": "Lune", "t": "Il fut un temps où les Miasmax étaient LE fléau d’Alola. Heureusement, leur population a vite diminué après l’arrivée des Tadmorv."}, {"g": "Ultra-Soleil", "t": "Il maîtrise son adversaire de son bras gauche, puis l’arrose d’un liquide toxique paralysant."}, {"g": "Ultra-Lune", "t": "Ce serait pour pouvoir faire face à Grotadmorv, son ennemi juré, que le Miasmax d’Alola est légèrement plus robuste que les autres."}, {"g": "Épée", "t": "Il produit du poison dans son corps à partir des ordures qu’il ingurgite. Selon ce qu’il mange, la composition des toxines diffère."}, {"g": "Bouclier", "t": "Le liquide qu’il projette de son bras droit est si toxique que si une créature fragile en est aspergée, elle succombe sur-le-champ."}],
  570: [{"g": "Noir", "t": "Il a le pouvoir de prendre l’apparence des autres. On dit qu’il se transforme souvent en petit enfant silencieux."}, {"g": "Blanc", "t": "Il peut se transformer en humain ou en d’autres Pokémon. Il se protège du danger en dissimulant sa vraie identité."}, {"g": "X", "t": "Il prend l’apparence de son adversaire pour le désorienter et prendre la fuite grâce à la confusion causée."}, {"g": "Ultra-Soleil", "t": "Timide de nature, il change constamment d’apparence, sauf quand il est entouré de ses congénères."}, {"g": "Ultra-Lune", "t": "Si un enfant volubile a soudain perdu sa langue, méfiez-vous ! C’est peut-être un Zorua qui a pris son apparence..."}, {"g": "Épée", "t": "À cause de sa timidité, il aurait développé la capacité de changer son apparence."}, {"g": "Bouclier", "t": "Il lui arrive de se changer en être humain, surtout en enfant, pour venir chercher de la nourriture en ville."}],
  571: [{"g": "Noir", "t": "Ces Pokémon protègent les leurs en prenant l’apparence de leurs ennemis. Ils forment des groupes très soudés."}, {"g": "Blanc", "t": "Il peut mystifier instantanément des foules d’humains. Il protège son habitat en créant des illusions de paysages."}, {"g": "Ultra-Soleil", "t": "Il est non seulement capable de changer d’apparence, mais il peut également créer des illusions pour hypnotiser les humains."}, {"g": "Ultra-Lune", "t": "Les humains qui osent menacer son habitat finissent par errer éternellement dans les bois, victimes de ses illusions."}, {"g": "Épée", "t": "Doté d’un grand sens de la camaraderie, ce Pokémon peut créer des illusions effrayantes pour protéger son habitat et ses congénères."}, {"g": "Bouclier", "t": "Les Dresseurs en manque de compagnie ordonnent à Zoroark de leur montrer une illusion pour tromper leur solitude."}],
  572: [{"g": "Noir", "t": "Ils se saluent en se caressant mutuellement le corps avec la queue, qu’ils gardent toujours immaculée."}, {"g": "Blanc", "t": "Un Pokémon qui aime la propreté. Chez lui, il enlève sans cesse la poussière en utilisant sa queue comme un plumeau."}, {"g": "X", "t": "Ils se saluent en s’époussetant les uns les autres avec leur queue qui leur sert de plumeau."}, {"g": "Ultra-Soleil", "t": "Ce maniaque de la propreté ne supporte pas la moindre saleté. Il utilise sa queue comme une serpillière pour tout nettoyer."}, {"g": "Ultra-Lune", "t": "Il lui faut bien une journée entière pour laver sa queue après s’en être servi pour faire le ménage dans son nid et épousseter son corps."}, {"g": "Épée", "t": "Il époussette les saletés avec sa queue. Il est d’une aide précieuse pour faire le ménage, mais il est très tatillon sur la propreté."}, {"g": "Bouclier", "t": "Les Chinchidou se saluent en se frottant la queue. Celui qui a la plus volumineuse en tire une certaine fierté."}],
  573: [{"g": "Noir", "t": "Leurs poils blancs sont recouverts d’une graisse spéciale qui leur permet d’esquiver facilement les attaques."}, {"g": "Blanc", "t": "La texture de ses poils blancs est incomparable. Elle n’attire ni la poussière, ni l’électricité statique."}, {"g": "Y", "t": "Son corps est recouvert d’une sorte de lubrifiant qui fait glisser les coups sur lui comme si de rien n’était."}, {"g": "Ultra-Soleil", "t": "Grâce à la sécrétion huileuse dont ses poils blancs sont recouverts, les attaques glissent sur sa fourrure comme sur de la soie."}, {"g": "Ultra-Lune", "t": "Le liquide que son corps sécrète est étrangement huileux. C’est un remède efficace pour les personnes qui ont la peau sèche."}, {"g": "Épée", "t": "Il ne supporte pas de voir le moindre grain de poussière. Il utilise l’huile qu’il sécrète pour recouvrir son nid d’un revêtement protecteur."}, {"g": "Bouclier", "t": "La sécrétion huileuse de ses poils lui permet de dévier les attaques. Elle s’arrache à prix d’or sur les marchés."}],
  574: [{"g": "Noir", "t": "Concentre des pouvoirs psychiques dans ses antennes semblables à des rubans, et regarde fixement... mais quoi?"}, {"g": "Blanc", "t": "Fixe les Pokémon et les Dresseurs du regard comme s’il y avait quelque chose que personne d’autre ne pouvait voir."}, {"g": "X", "t": "Concentre des pouvoirs psychiques dans ses antennes semblables à des rubans, et regarde fixement… mais quoi ?"}, {"g": "Épée", "t": "Il n’est encore qu’un enfant, mais il lui arrive de se battre avec l’énergie psychique concentrée dans ses antennes en forme de rubans."}, {"g": "Bouclier", "t": "Parfois, ce Pokémon chuchote alors qu’il n’y a personne aux alentours. On raconte qu’il parle à une entité que personne ne peut voir."}],
  575: [{"g": "Noir", "t": "Hypnotise les Pokémon et les gens. Il y a de nombreuses légendes de gens enlevés dans leur sommeil par des Mesmérella."}, {"g": "Blanc", "t": "Tire son énergie de la lumière des étoiles et marque leur position en faisant léviter des pierres la nuit."}, {"g": "Y", "t": "On dit qu’ils apparaissent les nuits étoilées et manipulent les enfants pour jouer avec eux."}, {"g": "Épée", "t": "On raconte qu’il enlève les enfants endormis pendant les nuits étoilées. Cela lui vaut d’être considéré comme un démon punisseur."}, {"g": "Bouclier", "t": "Ses pouvoirs psychiques semblent atteindre leur paroxysme pendant les nuits étoilées, mais nul ne sait s’il a un rapport avec l’espace."}],
  576: [{"g": "Noir", "t": "Ses pouvoirs psychiques plient l’espace aux alentours. On y voit des étoiles éloignées de millions d’années-lumière."}, {"g": "Blanc", "t": "Prédit l’avenir à partir de la position et du mouvement des étoiles. Perçoit aussi l’espérance de vie des Dresseurs."}, {"g": "Épée", "t": "Il prédit l’avenir à partir du mouvement des étoiles. Il dispose de grands pouvoirs psychiques, mais il n’est pas de nature hostile."}, {"g": "Bouclier", "t": "Les criminels à qui Sidérella a révélé les derniers instants de leur vie ont tous été portés disparus le jour même."}],
  577: [{"g": "Noir", "t": "Ils repoussent leurs assaillants avec leurs pouvoirs psychiques et communiquent entre eux par télépathie."}, {"g": "Blanc", "t": "Son corps est enrobé dans un fluide spécial, ce qui lui permet de vivre dans n’importe quel environnement."}, {"g": "Épée", "t": "Ils communiquent entre eux par télépathie. S’ils subissent un choc physique violent, le fluide qui entoure leur corps se met à fuir."}, {"g": "Bouclier", "t": "On raconte que le curieux fluide qui entoure le corps de ce Pokémon lui permet de survivre dans l’espace."}],
  578: [{"g": "Noir", "t": "Il possède deux cerveaux séparés qui le font parfois agir de façon totalement incohérente."}, {"g": "Blanc", "t": "Il dégage sa puissance maximale quand ses cerveaux réfléchissent à la même chose."}, {"g": "Y", "t": "Il dégage le maximum de sa puissance psychique quand ses deux cerveaux réfléchissent à la même chose."}, {"g": "Épée", "t": "On prétend que lorsque ses deux cerveaux agissent à l’unisson, la portée de sa force mentale peut s’étendre sur un rayon d’un kilomètre."}, {"g": "Bouclier", "t": "Étant donné que ses deux cerveaux sont rarement sur la même longueur d’onde, il est impossible de prédire son comportement."}],
  579: [{"g": "Noir", "t": "Quand ils se tiennent par la main, leurs cerveaux forment un réseau qui démultiplie leurs pouvoirs psychiques."}, {"g": "Blanc", "t": "Il combat avec ses bras assez puissants pour broyer des rochers. C’est un Pokémon très intelligent."}, {"g": "X", "t": "Ses bras, faits d’une matière conduisant ses pouvoirs psychiques, sont assez puissants pour broyer des rochers."}, {"g": "Épée", "t": "Fier d’avoir des bras, il préfère s’en servir pour assommer ses adversaires plutôt que d’avoir recours à ses pouvoirs psychiques."}, {"g": "Bouclier", "t": "S’il ne s’agissait pas d’un poison violent que seul Symbios peut boire, son curieux fluide pourrait, selon les dires, rendre plus intelligent."}],
  580: [{"g": "Noir", "t": "Un Pokémon Oiseau doué pour la plongée. Il nage sous l’eau à la recherche de sphaigne, son plat préféré."}, {"g": "Blanc", "t": "Quand on l’attaque, il s’ébroue et fait jaillir de la vapeur d’eau de tout son corps. Il se cache dedans pour s’enfuir."}, {"g": "Y", "t": "Un Pokémon doué pour la plongée qui passe son temps sous l’eau à chercher des sphaignes, son plat préféré."}],
  581: [{"g": "Noir", "t": "Ils se mettent à danser à la tombée de la nuit. Le Lakmécygne qui danse au centre est le chef de la troupe."}, {"g": "Blanc", "t": "Ses coups de bec sont très efficaces. Il plie son long cou et en inflige un douloureux enchaînement."}, {"g": "X", "t": "Un Pokémon gracieux, mais aussi robuste. Il peut voler des milliers de kilomètres grâce à ses ailes puissantes."}],
  582: [{"g": "Noir", "t": "Il exhale une haleine à -50 °C. Il fabrique des cristaux de neige et fait neiger autour de lui."}, {"g": "Blanc", "t": "Ce Pokémon est né d’un glaçon qui a baigné dans la lumière du matin. Il se cache dans la neige pour dormir."}, {"g": "Soleil", "t": "Né dans une colonne de glace, ce Pokémon peut créer des flocons de neige de son souffle glacé, voire même faire tomber la neige en été."}, {"g": "Lune", "t": "Serrer Sorbébé contre soi procure une délicieuse sensation de fraîcheur. Dans les régions chaudes, c’est le Pokémon à avoir à la maison."}, {"g": "Ultra-Soleil", "t": "Son souffle glacé descend jusqu’à -50 °C. Il fond peu à peu quand il se retrouve dans un endroit chaud."}, {"g": "Ultra-Lune", "t": "Il est né d’une stalactite de glace qui, face au soleil du matin, a fait le vœu de ne pas fondre. Il se terre dans la neige pour dormir la nuit."}, {"g": "Épée", "t": "Il ne peut pas vivre dans les contrées chaudes. Il souffle un air glacial pour faire tomber la neige, puis s’y plonge pour dormir."}, {"g": "Bouclier", "t": "On raconte qu’il est né de stalactites. Il gèle les alentours en soufflant de l’air à - 50 °C pour améliorer son confort."}],
  583: [{"g": "Noir", "t": "Un Pokémon qui vit dans les montagnes enneigées. Il a émigré au sud durant l’ère glaciaire, il y a bien longtemps."}, {"g": "Blanc", "t": "Il se cache de ses ennemis en émettant une myriade de petites particules de glace."}, {"g": "X", "t": "Il pétrifie ses ennemis en refroidissant l’air ambiant et en le changeant en une myriade de petites particules de glace."}, {"g": "Soleil", "t": "Son corps fond les jours de canicule. Il suffit heureusement de le congeler pour qu’il reprenne forme, mais il restera un tantinet flagada."}, {"g": "Lune", "t": "Déjà présent à l’ère glaciaire, ce Pokémon peut contrôler les particules de glace pour geler ses ennemis, qu’il éclate ensuite d’un coup de boule."}, {"g": "Ultra-Soleil", "t": "Il souffle des particules de glace pour geler ses ennemis. Les Sorboul d’Alola sont plus petits que la moyenne."}, {"g": "Ultra-Lune", "t": "Ce robuste Pokémon a survécu à l’ère glaciaire. Il est extrêmement populaire dans les régions chaudes."}, {"g": "Épée", "t": "Il boit de l’eau pure pour gonfler son corps de glace. On le voit rarement les jours ensoleillés."}, {"g": "Bouclier", "t": "Bien qu’il gèle ses ennemis en soufflant de l’air à - 100 °C, sa gentillesse l’empêche de leur ôter la vie."}],
  584: [{"g": "Noir", "t": "Il avale de l’eau en grande quantité et la transforme en nuages neigeux. Il souffle du blizzard sur ses ennemis."}, {"g": "Blanc", "t": "Quand ses deux têtes se fâchent en même temps, il émet un blizzard de ses cornes et enfouit les alentours sous la neige."}, {"g": "Y", "t": "Il avale de grandes quantités d’eau et la transforme en nuages de neige. Il souffle du blizzard quand il se fâche."}, {"g": "Soleil", "t": "Chacune de ses deux têtes possède un cerveau distinct. Elles doivent s’entendre pour que Sorbouboul souffle son blizzard sur l’ennemi."}, {"g": "Lune", "t": "Il peut perdre l’une de ses têtes et continuer à vivre sa vie sans souci. Des flocons de neige sont fabriqués en permanence dans son corps."}, {"g": "Ultra-Soleil", "t": "Ses deux bouches peuvent souffler du blizzard. Sa capacité à créer de la neige à volonté le rend populaire auprès des skieurs et snowboarders."}, {"g": "Ultra-Lune", "t": "Sorbouboul est né lorsque deux Sorboul, à moitié fondus par le soleil, se sont collés l’un à l’autre et ont été soudés par la gelée nocturne."}, {"g": "Épée", "t": "Lorsqu’il a les nerfs en boule, il provoque un blizzard qui gèle tout le monde, alliés comme adversaires."}, {"g": "Bouclier", "t": "La température de son corps est d’environ - 6 °C. On raconte que ce Pokémon naît lorsque deux Sorboul se collent l’un à l’autre."}],
  585: [{"g": "Noir", "t": "Son pelage prend la même couleur et la même odeur que les hautes herbes. S’il sent un ennemi, il court s’y réfugier."}, {"g": "Blanc", "t": "Quand la saison change, il change de pelage et d’odeur. Un Pokémon qui annonce le passage des saisons."}, {"g": "X", "t": "Son pelage change selon la saison, et dans une moindre mesure en fonction de l’humidité et de la température."}],
  586: [{"g": "Noir", "t": "Il change d’habitat selon les saisons. Les gens constatent le passage des saisons en regardant ses ramures."}, {"g": "Blanc", "t": "Le feuillage qui pousse sur sa ramure change au fil des saisons. Celui qui a la plus belle dirige le troupeau."}, {"g": "Y", "t": "Il change d’habitat selon les saisons. Certains disent même qu’il est celui qui apporte le printemps."}],
  587: [{"g": "Noir", "t": "Il accumule dans ses membranes l’électricité qu’il produit dans ses bajoues, et la relâche tout en planant."}, {"g": "Blanc", "t": "Il vit au sommet des arbres de la forêt. Il plane en déchargeant l’électricité de ses membranes semblables à une cape."}, {"g": "Soleil", "t": "Telle une cape de super-héros, sa membrane de peau lui permet de planer. Il décharge alors son électricité sur ses ennemis... et ses alliés."}, {"g": "Lune", "t": "L’électricité lui sert à griller à point fruits et Pokémon Insecte. Il fait généralement son nid dans les arbres creusés par les Picassaut."}, {"g": "Ultra-Soleil", "t": "Il plane dans les airs une fois qu’il est chargé en électricité. Les nuits où le tonnerre gronde, des centaines d’Emolga se regroupent dans le ciel."}, {"g": "Ultra-Lune", "t": "Les Pokémon oiseaux ne s’approchent pas de lui car il décharge de l’électricité en planant. Il peut donc garder sa nourriture pour lui tout seul."}, {"g": "Épée", "t": "Il virevolte dans le ciel en libérant des gerbes d’électricité. Son vol est gracieux, mais peut s’avérer dangereux."}, {"g": "Bouclier", "t": "Les Baies sucrées sont son péché mignon. Il lui arrive d’en conserver beaucoup trop dans ses bajoues, ce qui l’empêche de bien planer."}],
  588: [{"g": "Noir", "t": "Un Pokémon mystérieux qui évolue quand il reçoit un stimulus électrique en étant proche d’un Escargaume."}, {"g": "Blanc", "t": "Quand il sent un danger, il se défend en crachant un liquide acide. Il chasse les Escargaume."}, {"g": "Y", "t": "Pour une raison inconnue, ce Pokémon évolue s’il subit une décharge électrique pendant qu’il attaque un Escargaume."}, {"g": "Épée", "t": "Son corps étrangement structuré a la faculté de réagir à l’électricité. Il évolue lorsqu’il croise un Escargaume."}, {"g": "Bouclier", "t": "Il crache un liquide qui dissout les coquilles des Escargaume pour se régaler de leur contenu."}],
  589: [{"g": "Rubis Oméga", "t": "Ce Pokémon se protège avec la carapace dérobée à un Escargaume et attaque avec ses deux redoutables lances."}, {"g": "Noir", "t": "Il vole à toute vitesse et frappe tout ennemi de ses lances pointues. Il combat bravement contre les plus forts que lui."}, {"g": "Blanc", "t": "Un Pokémon qui a évolué en portant la carapace d’un Escargaume. Une armure de fer protège tout son corps."}, {"g": "Épée", "t": "Il a volé la coquille d’Escargaume pour obtenir une armure parfaite. Il jouit d’une très grande popularité à Galar."}, {"g": "Bouclier", "t": "Il charge ses ennemis en brandissant ses lances. Il existe un célèbre tableau représentant la joute entre un Lançargot et un Palarticho."}],
  590: [{"g": "Noir", "t": "Grâce à sa ressemblance mystérieuse avec une Poké Ball, il attire ses ennemis et relâche des spores empoisonnées."}, {"g": "Blanc", "t": "Pour une raison inconnue, il ressemble à une Poké Ball. Il repousse ses ennemis à l’aide de spores empoisonnées."}, {"g": "Y", "t": "Son apparence de Poké Ball trompe ses ennemis, qu’il étourdit à l’aide de ses spores empoisonnées."}, {"g": "Épée", "t": "On ignore toujours l’origine ou la signification de sa forte ressemblance avec une Poké Ball."}, {"g": "Bouclier", "t": "Les spores qu’il libère de ses mains sont très toxiques, mais si on les sèche bien, elles peuvent soulager les maux de ventre."}],
  591: [{"g": "Noir", "t": "Il danse en faisant tournoyer les coupoles en forme de Poké Ball de ses bras pour attirer ses proies."}, {"g": "Blanc", "t": "Il se sert de ses coupoles en forme de Poké Ball pour attirer ses proies, mais peu de Pokémon se laissent avoir."}, {"g": "Épée", "t": "Si l’on ne nettoie pas rapidement les spores empoisonnées qu’il répand, celles-ci donnent naissance à des champignons."}, {"g": "Bouclier", "t": "Ce Pokémon a tendance à très peu se déplacer. Quand il voit une Poké Ball abandonnée au sol, il reste immobile à côté."}],
  592: [{"g": "Noir", "t": "Il s’enfonce dans les profondeurs de la mer en emmenant son ennemi, qu’il ligote avec ses bras fins comme des voiles."}, {"g": "Blanc", "t": "Il paralyse ses proies avec du poison et les entraîne jusqu’à son antre, qu’on dit situé à 8 000 m de profondeur."}, {"g": "Y", "t": "Il enserre ses proies dans ses voiles et les entraîne sous la surface de la mer jusqu’à plus de 8 000 m de profondeur."}, {"g": "Ultra-Soleil", "t": "Il enroule ses membres en forme de voiles autour de ses proies, puis les entraîne dans les abysses."}, {"g": "Ultra-Lune", "t": "Ses membres en forme de voiles sont couverts de dards venimeux invisibles qui lui servent à paralyser ses ennemis avant de les noyer."}, {"g": "Épée", "t": "Il utilise ses membres en forme de voiles pour enlacer ses proies et les entraîner à 8 000 m de profondeur sous la surface de l’eau."}, {"g": "Bouclier", "t": "Certaines légendes racontent que les Viskuse sont les habitants d’une ancienne cité engloutie qui ont été changés en Pokémon."}],
  593: [{"g": "Noir", "t": "Les bateaux qui s’aventurent sur son territoire coulent, et Moyade aspire l’énergie vitale des marins."}, {"g": "Blanc", "t": "Il se déplace en projetant l’eau de mer qu’il accumule dans son corps. Son plat préféré est l’énergie vitale."}, {"g": "X", "t": "Il est presque entièrement fait d’eau de mer. On dit qu’il vit dans un palais fait des épaves des bateaux qu’il a coulés."}, {"g": "Ultra-Soleil", "t": "On le trouve souvent près des bateaux de croisière et des pétroliers, où il cherche des proies à entraîner dans les abysses."}, {"g": "Ultra-Lune", "t": "On raconte que ce Pokémon, redouté par les marins, ôte la vie de ses proies en les entraînant dans les abysses."}, {"g": "Épée", "t": "Son corps est composé presque entièrement d’une substance identique à l’eau de mer. Les épaves de navires sont ses bastions."}, {"g": "Bouclier", "t": "Les nuits de pleine lune, ils se réunissent à la surface de la mer pour attendre leurs proies."}],
  594: [{"g": "Noir", "t": "La membrane spéciale qui entoure son corps a la capacité de guérir les blessures."}, {"g": "Blanc", "t": "Il vit en dérivant dans les grands océans. Quand il trouve des Pokémon blessés, il les ramène jusqu’à la côte."}, {"g": "Y", "t": "Il berce les Pokémon blessés dans ses nageoires et les guérit grâce à la membrane dont il est recouvert."}, {"g": "Soleil", "t": "Il recueille les Pokémon blessés et referme leurs plaies grâce à son mucus spécial. Par pur altruisme ? Nul ne le sait."}, {"g": "Lune", "t": "Il se laisse dériver au gré des courants océaniques profonds. De nombreux Pokémon Eau se rassemblent toujours autour de lui."}, {"g": "Ultra-Soleil", "t": "Ses talents de guérisseur sont tels que les marins l’emportent quand ils embarquent pour une longue traversée."}, {"g": "Ultra-Lune", "t": "On pense qu’il protège les Pokémon affaiblis parce qu’il partage avec eux les mêmes prédateurs."}],
  595: [{"g": "Noir", "t": "Les Statitik qui vivent en ville ont appris à aspirer le courant depuis les prises électriques des maisons."}, {"g": "Blanc", "t": "Il s’accroche aux Pokémon plus grands et aspire leur électricité statique. Il la stocke dans ses poches-accus."}, {"g": "X", "t": "Ne produisant pas lui-même d’électricité, il s’accroche aux Pokémon plus grands et aspire leur électricité statique."}, {"g": "Épée", "t": "Il s’accroche au corps des autres Pokémon pour absorber leur électricité statique. Il est incapable d’en produire tout seul."}, {"g": "Bouclier", "t": "Il s’accroche aux autres Pokémon pour aspirer leur électricité statique. On en trouve souvent collés au postérieur de Voltoutou."}],
  596: [{"g": "Noir", "t": "Quand on l’attaque, il projette une multitude de fils électrifiés pour créer une barrière électrique."}, {"g": "Blanc", "t": "Il tend des pièges avec ses fils électriques. Il déguste tranquillement ses proies une fois électrocutées."}, {"g": "Épée", "t": "Il attaque en projetant les poils de son abdomen chargés en électricité. La victime reste alors paralysée pendant trois jours et trois nuits."}, {"g": "Bouclier", "t": "Il piège les oisillons qui ne savent pas encore voler en tissant une toile électrique près des nids des Pokémon oiseaux."}],
  597: [{"g": "Noir", "t": "Quand il sent un danger, il réagit en projetant toutes ses épines d’un coup et s’enfuit en roulant sur lui-même."}, {"g": "Blanc", "t": "Il s’accroche aux parois des grottes à l’aide de ses épines et absorbe les minéraux contenus dans la roche."}, {"g": "Y", "t": "Il s’accroche aux parois des grottes et en absorbe les minéraux. Il projette ses épines en cas de danger."}, {"g": "Épée", "t": "Il se protège en projetant ses épines, mais il lui faut beaucoup d’entraînement pour réussir à tirer dans une direction précise."}, {"g": "Bouclier", "t": "Il aime les grottes pleines de mousse. Les enzymes contenues dans ces plantes l’aident à obtenir des épines grandes et solides."}],
  598: [{"g": "Noir", "t": "Il combat avec ses trois tentacules épineux. Un coup de ses épines d’acier peut briser en deux de gros rochers."}, {"g": "Blanc", "t": "Il s’accroche aux plafonds des grottes et attaque les proies qui passent en dessous avec ses épines d’acier."}, {"g": "X", "t": "Il attaque grâce à ses trois tentacules épineux et lance des épines d’acier pour réduire ses ennemis en poussière."}, {"g": "Épée", "t": "Il fissure la roche avec ses épines pour ensuite absorber les nutriments qui s’y trouvent grâce à l’extrémité de ses tentacules."}, {"g": "Bouclier", "t": "Ses épines sont plus solides que l’acier. Il plante celles de ses tentacules dans les parois rocheuses pour se déplacer."}],
  599: [{"g": "Noir", "t": "La compatibilité entre ses deux rouages est prédéterminée. Ceux-ci ne se fixeront à aucun autre."}, {"g": "Blanc", "t": "Le mouvement de ses deux corps enchâssés produit l’énergie qui lui est nécessaire pour vivre."}, {"g": "Épée", "t": "Ses deux rouages sont plus soudés que des jumeaux. Si on essaie de les combiner à d’autres rouages, ils ne s’entendent pas très bien."}, {"g": "Bouclier", "t": "Les humains auraient inventé les mécanismes à engrenages il y a fort longtemps, en observant ce Pokémon."}],
  600: [{"g": "Noir", "t": "Ils communiquent entre eux en changeant leur sens de rotation. Plus ils sont en colère, plus ils tournent vite."}, {"g": "Blanc", "t": "Il attaque en lançant ses mini-rouages à grande vitesse. Il est en fâcheuse posture s’ils ne reviennent pas."}, {"g": "Y", "t": "Le plus grand des rouages projette le plus petit pour attaquer. Ce dernier risque de dépérir s’il ne revient pas."}, {"g": "Épée", "t": "Quand le combat devient sérieux, la partie extérieure du grand rouage s’aligne parfaitement avec le petit pour accélérer leur rotation."}, {"g": "Bouclier", "t": "Ce Pokémon symbolisant la technologie industrielle est souvent utilisé dans le logo des entreprises de Galar."}],
  601: [{"g": "Blanc", "t": "Il accumule rapidement de l’énergie en faisant tourner très vite le rouage qui contient son noyau rouge."}, {"g": "Noir", "t": "Son noyau rouge lui permet d’accumuler de l’énergie qu’il projette ensuite aux alentours grâce à ses pics."}, {"g": "Épée", "t": "Il peut envoyer de terribles décharges électriques de la pointe de ses pics. Il accumule de grandes quantités d’énergie dans son noyau rouge."}, {"g": "Bouclier", "t": "Bien que son nouveau rouage à pointes ne soit pas doué de vie, il parvient à le faire tourner à grande vitesse avec les deux autres."}],
  602: [{"g": "Noir", "t": "Tout seuls, ils ne dégagent pas beaucoup d’électricité, mais un banc d’Anchwatt produit la même puissance qu’un éclair."}, {"g": "Blanc", "t": "Ils agissent en groupes. Ils possèdent un organe produisant de l’électricité et lancent des décharges en cas de danger."}, {"g": "Y", "t": "Tout seul, il ne dégage pas beaucoup d’électricité. Mais un banc d’Anchwatt produit des décharges surpuissantes."}],
  603: [{"g": "Noir", "t": "Ses taches rondes émettent de l’électricité. Il s’enroule autour de ses proies et les électrocute."}, {"g": "Blanc", "t": "Un Pokémon doté d’un gros appétit. Il paralyse ses proies avec des décharges électriques avant de les manger."}, {"g": "X", "t": "Ses taches émettent de l’électricité quand il s’enroule autour de ses proies pour les paralyser avant de les dévorer."}],
  604: [{"g": "Noir", "t": "Il peut sortir de l’eau à la force de ses bras pour attraper des proies sur la rive. Il retourne à l’eau en un instant."}, {"g": "Blanc", "t": "Il s’attache à ses proies avec sa bouche-ventouse et les électrocute avec ses crocs."}],
  605: [{"g": "Noir", "t": "Avec son puissant pouvoir psychique, il peut compresser le cerveau de ses ennemis et déclencher des migraines."}, {"g": "Blanc", "t": "Il est apparu soudainement des confins d’un désert il y a 50 ans. Personne ne l’avait jamais vu auparavant."}, {"g": "Y", "t": "On dit qu’il est apparu soudainement il y a 50 ans des confins d’un désert où un OVNI se serait écrasé."}, {"g": "Ultra-Soleil", "t": "Il possède de redoutables pouvoirs psychiques. La plupart des signalements d’extraterrestres correspondent à des Lewsor qui se promènent."}, {"g": "Ultra-Lune", "t": "Ce Pokémon est nimbé de mystère. On raconte qu’il serait apparu il y a 50 ans, après la chute d’un OVNI."}, {"g": "Épée", "t": "S’il se tient près d’une télé, d’étranges panoramas apparaissent à l’écran. On raconte qu’il s’agirait de paysages venus des terres natales de Lewsor."}, {"g": "Bouclier", "t": "Ce Pokémon a été découvert il y a environ 50 ans. Son cerveau surdéveloppé lui permet d’utiliser ses pouvoirs psychiques avec aisance."}],
  606: [{"g": "Noir", "t": "Il peut manipuler les souvenirs de ses ennemis et fait clignoter ses doigts tricolores pour discuter avec ses amis."}, {"g": "Blanc", "t": "Il manipule l’esprit avec ses pouvoirs psychiques et peut modifier les images conservées dans les souvenirs."}, {"g": "X", "t": "Il fait clignoter ses doigts tricolores pour communiquer avec ses semblables. Son langage reste un mystère."}, {"g": "Ultra-Soleil", "t": "Il peut modifier les souvenirs avec ses pouvoirs psychiques. Vous ne le savez pas encore, mais vous avez peut-être déjà tout oublié..."}, {"g": "Ultra-Lune", "t": "Ses pouvoirs psychiques sont redoutables. Il peut contrôler ses adversaires et modifier leurs souvenirs grâce à ses doigts tricolores."}, {"g": "Épée", "t": "À chaque fois que Neitram se matérialise dans une pâture, un Moumouflon disparaît dans des circonstances mystérieuses."}, {"g": "Bouclier", "t": "Il peut manipuler les souvenirs de son adversaire à loisir. Parfois, on l’aperçoit en train de vagabonder au-dessus des champs de blé."}],
  607: [{"g": "Noir", "t": "Sa flamme brûle en consumant l’énergie vitale des gens et des Pokémon."}, {"g": "Blanc", "t": "Il fait semblant de guider ses victimes à la lueur de sa flamme, mais c’est pour mieux aspirer leur énergie vitale."}, {"g": "Épée", "t": "Son corps est tiède, réchauffé par sa flamme. Il prend les personnes égarées par la main et les guide vers le monde des esprits."}, {"g": "Bouclier", "t": "Plus les victimes dont il aspire l’énergie vitale sont jeunes, plus sa flamme grandit et luit lugubrement."}],
  608: [{"g": "Noir", "t": "Un Pokémon craint pour être de mauvais augure. Il erre dans les villes à la recherche d’âmes de défunts."}, {"g": "Blanc", "t": "Il apparaît au moment du trépas et aspire l’âme à l’instant même où elle quitte le corps."}, {"g": "X", "t": "Il aspire les âmes pour entretenir sa flamme. Il erre dans les hôpitaux dans l’attente d’un trépas."}, {"g": "Épée", "t": "Comme il apparaît dès qu’une personne est sur le point de trépasser, les gens le craignent et le prennent pour un messager de la mort."}, {"g": "Bouclier", "t": "Il se cache en ville en se faisant passer pour un lampadaire. Lorsqu’il repère une personne dont l’heure est proche, il la suit en catimini."}],
  609: [{"g": "Noir", "t": "Il brûle en aspirant les âmes, et hypnotise ses ennemis en faisant osciller les flammes de ses bras."}, {"g": "Blanc", "t": "Les victimes des flammes de Lugulabre voient leur âme aspirée jusqu’à ce que leur corps ne soit plus que coquille vide."}, {"g": "Y", "t": "Les âmes consumées par ses flammes étranges sont condamnées à l’errance pour l’éternité."}, {"g": "Épée", "t": "Il s’installe dans les résidences anciennes. Pour hypnotiser son adversaire, il agite les flammes de ses bras de manière inquiétante."}, {"g": "Bouclier", "t": "On raconte que dans les manoirs éclairés par des Lugulabre, les funérailles s’enchaînent sans discontinuer."}],
  610: [{"g": "Noir", "t": "Il broie les Baies à grands coups de crocs. Ceux-ci repoussent plusieurs fois, toujours plus forts et aiguisés."}, {"g": "Blanc", "t": "Il laisse la marque de ses crocs dans les arbres pour marquer son territoire. Ses crocs repoussent dès qu’ils tombent."}, {"g": "Épée", "t": "Il vit dans des terriers qu’il creuse à même le sol, et organise des concours avec ses camarades pour voir qui peut briser la Baie la plus dure."}, {"g": "Bouclier", "t": "Il joue avec ses congénères à se donner de grands coups de crocs. Peu importe s’ils se cassent : ils repousseront aussitôt."}],
  611: [{"g": "Noir", "t": "Comme ses crocs brisés ne repoussent pas, il les aiguise après le combat grâce à une pierre ramassée près d’un fleuve."}, {"g": "Blanc", "t": "Leurs crocs peuvent découper des rochers. Leurs querelles de territoire sont extrêmement violentes."}, {"g": "Y", "t": "Comme ses crocs brisés ne repoussent pas, il les aiguise avec soin après le combat sur les pierres des rivières."}, {"g": "Épée", "t": "Une fois cassés, ses crocs ne repoussent pas. Après les combats, il les aiguise avec soin sur les pierres d’un ruisseau."}, {"g": "Bouclier", "t": "Son épiderme est dur comme une armure. Il est passé maître dans l’art de charger l’ennemi tout en le transperçant de ses crocs."}],
  612: [{"g": "Noir", "t": "Il est doux, mais ne pardonne pas à ceux qui viennent saccager son territoire. Ses crocs peuvent découper de l’acier."}, {"g": "Blanc", "t": "Ses crocs sont tellement puissants qu’ils peuvent découper l’acier sans s’émousser. Son armure est très solide."}, {"g": "Épée", "t": "Ses longs crocs robustes sont sa plus grande fierté. Il lèche le sol pour en absorber les minéraux et ainsi renforcer sa dentition."}, {"g": "Bouclier", "t": "D’un naturel doux, il est cependant redoutable lorsqu’il se fâche. Il est très fier de ses crocs qui peuvent même découper des poutres d’acier."}],
  613: [{"g": "Noir", "t": "Quand il est malade, sa goutte au nez dégèle et ses capacités de type Glace deviennent moins efficaces."}, {"g": "Blanc", "t": "Il a toujours la goutte au nez. Il l’aspire pour déclencher ses capacités. La morve en est la matière première."}, {"g": "Y", "t": "Sa roupie indique sa santé. S’il est en forme, elle sera épaisse et la puissance de ses attaques glacées augmentera."}, {"g": "Épée", "t": "Quand il est en forme, sa goutte au nez devient encore plus visqueuse. Il n’hésite pas à s’essuyer le nez sur un adversaire qui lui déplaît."}, {"g": "Bouclier", "t": "Il renifle avant d’utiliser une capacité. Le froid intense contenu dans sa morve lui permet de lancer les capacités de type Glace."}],
  614: [{"g": "Noir", "t": "Il fait lui-même geler son haleine. Il est bon nageur et sillonne les mers du nord à la recherche de ses proies."}, {"g": "Blanc", "t": "Il gèle son haleine et en fait des crocs et des griffes de glace pour combattre. Il vit dans les terres gelées du nord."}, {"g": "X", "t": "Il aime les mers glaciales du nord. Il y trace son chemin en créant des îlots de glace pour éviter de nager."}, {"g": "Épée", "t": "Les crocs qu’il façonne en gelant son souffle sont plus durs que l’acier. Il sillonne les eaux des mers glaciales à la recherche de nourriture."}, {"g": "Bouclier", "t": "Il sillonne les mers glaciales avec aisance. Quand il est fatigué, il gèle l’eau de mer d’un souffle et se repose sur l’iceberg improvisé."}],
  615: [{"g": "Noir", "t": "Si sa température monte, il se dissipe en vapeur d’eau et disparaît. Quand elle diminue, il redevient de glace."}, {"g": "Blanc", "t": "Né d’un nuage neigeux, il attrape ses proies à l’aide de sa chaîne faite de cristaux de givre."}, {"g": "Y", "t": "Il attrape ses proies à l’aide de sa chaîne faite de cristaux de givre et les gèle à près de -100 °C."}, {"g": "Épée", "t": "Il gèle ceux qu’il croise à l’aide de ses chaînes faites de givre, puis les emmène vers un lieu inconnu."}, {"g": "Bouclier", "t": "Lorsqu’il fait trop chaud, il s’évapore, ce qui explique pourquoi on ne le voit presque pas en été."}],
  616: [{"g": "Noir", "t": "Quand on l’attaque, il referme sa visière pour se défendre, et projette un poison visqueux."}, {"g": "Blanc", "t": "Il évolue quand il baigne dans une énergie électrique avec un Carabing. La cause en est inconnue."}, {"g": "X", "t": "S’il est à proximité d’un Carabing et que les deux reçoivent une décharge électrique, ils évoluent en même temps."}, {"g": "Épée", "t": "Il se recroqueville dans sa carapace en fermant la visière lorsque des ennemis approchent. Carabing peut néanmoins en forcer l’entrée."}, {"g": "Bouclier", "t": "Il a l’étrange faculté de réagir à l’énergie électrique. On ne sait trop pourquoi, mais quand il se trouve aux côtés de Carabing, il évolue."}],
  617: [{"g": "Noir", "t": "Quand son corps s’assèche, il faiblit. Il s’en prémunit en s’enroulant dans plusieurs couches d’une fine muqueuse."}, {"g": "Blanc", "t": "Il s’est bien allégé en se débarrassant de sa lourde carapace. Il se bat avec l’agilité d’un ninja."}, {"g": "Épée", "t": "Il se bat avec célérité en projetant du poison. Il est si cool qu’il est souvent le héros de films ou de bandes dessinées à succès."}, {"g": "Bouclier", "t": "Il est bien plus agile sans sa coquille. La membrane en forme de bandelettes qui l’entoure l’empêche de se dessécher."}],
  618: [{"g": "Noir", "t": "Sa peau est si dure qu’il peut se faire piétiner par un sumo sans rien sentir. Il sourit en émettant de l’électricité."}, {"g": "Blanc", "t": "Tapi dans la boue ou les sédiments, il attend sa proie patiemment et la paralyse avec une décharge électrique."}, {"g": "Épée", "t": "Les vasières sont son habitat de prédilection. Il a développé un organe générant de l’électricité grâce aux bactéries présentes dans la boue."}, {"g": "Bouclier", "t": "Lorsque les parties jaunes de son corps envoient une puissante décharge électrique, il ébauche un sourire. Personne ne sait pourquoi."}],
  619: [{"g": "Noir", "t": "Il découpe ses ennemis avec ses griffes acérées et les terrasse avec ses enchaînements de coups hyper fluides."}, {"g": "Blanc", "t": "Il emploie des enchaînements élégants. Lorsqu’il se concentre, leur vitesse et leur tranchant augmentent."}, {"g": "X", "t": "Il se flatte d’être très rapide. Pour compenser la faiblesse de ses coups, il en assène un très grand nombre."}, {"g": "Ultra-Soleil", "t": "Au petit jour, on peut voir des meutes de Kungfouine qui s’entraînent en effectuant des mouvements lents et méthodiques."}, {"g": "Ultra-Lune", "t": "Il s’isole en montagne pour s’entraîner avec ses congénères. Les techniques de coups de pied ou de poing changent d’une meute à l’autre."}, {"g": "Épée", "t": "Les Kungfouine bien entraînés sont capables d’asséner plus de cent coups par minute du tranchant de la main."}, {"g": "Bouclier", "t": "De nature brutale malgré sa petite taille, il inflige une série de coups majestueux aux inconscients qui s’approchent trop près de lui."}],
  620: [{"g": "Noir", "t": "Il se sert des poils de ses pattes antérieures comme de fouets. Ses coups ultrarapides sont invisibles à l’œil nu."}, {"g": "Blanc", "t": "Il combat à l’aide des longs poils de ses pattes antérieures. Ils font aussi mal qu’un fouet."}, {"g": "Y", "t": "Il combat à l’aide des longs poils de ses pattes antérieures. Une fois lancé dans ses enchaînements, rien ne l’arrête."}, {"g": "Ultra-Soleil", "t": "Il accule son ennemi avec une rafale d’attaques fulgurantes, puis concentre son énergie pour lui donner le coup de grâce."}, {"g": "Ultra-Lune", "t": "Le cri lugubre de Shaofouine annonce qu’il est sur le point de déchaîner une pluie de coups si rapides qu’ils en sont invisibles."}, {"g": "Épée", "t": "Lorsqu’il fait face à un adversaire vraiment redoutable, il coupe les poils de ses mains avec les dents pour améliorer son agilité."}, {"g": "Bouclier", "t": "Ses coups de pied ultrarapides et invisibles à l’œil nu peuvent réduire un énorme rocher en poussière."}],
  621: [{"g": "Noir", "t": "Il utilise ses ailes pour emmagasiner la chaleur du soleil. Si la température de son corps baisse, il ne peut plus bouger."}, {"g": "Blanc", "t": "Il sillonne les grottes étroites, capturant ses proies avec ses griffes acérées. Sa face est dure comme le roc."}, {"g": "Ultra-Soleil", "t": "La peau rouge de sa gueule est dure comme le roc. Il accule ses ennemis dans les boyaux des cavernes et les attaque à coups de tête."}, {"g": "Ultra-Lune", "t": "Il se faufile dans les tunnels creusés par les Taupiqueur et les Triopikeur. Il attend ensuite tranquillement qu’une proie passe à sa portée."}, {"g": "Épée", "t": "Il vit sous terre, mais il doit impérativement s’exposer au soleil, car il devient incapable de bouger lorsque son corps se refroidit."}, {"g": "Bouclier", "t": "Féroce et perfide, Drakkarmin s’approprie les terriers creusés par d’autres Pokémon pour en faire son antre."}],
  622: [{"g": "Noir", "t": "Il se meut grâce à l’énergie stockée dans son corps. Personne ne sait d’où vient cette énergie mystérieuse."}, {"g": "Blanc", "t": "On pense que ce Pokémon est le produit de la technologie d’une civilisation ancienne."}, {"g": "Y", "t": "Ce Pokémon fait de terre glaise, produit de la technologie d’une civilisation antique, vit depuis des millénaires."}, {"g": "Ultra-Soleil", "t": "Une mystérieuse énergie l’alimente depuis l’Antiquité, mais, qui sait ? Cette énergie n’est peut-être pas éternelle..."}, {"g": "Ultra-Lune", "t": "Les anciens, désirant avoir un serviteur, l’auraient façonné avec de l’argile. En revanche, on ignore toujours d’où provient son énergie."}, {"g": "Épée", "t": "Ce Pokémon très ancien a été façonné avec de l’argile. On ne sait pourquoi certains spécimens n’ont de cesse d’aligner de grosses pierres."}, {"g": "Bouclier", "t": "Ce Pokémon fait d’argile continue de respecter les ordres que son maître lui a donnés il y a quelques millénaires."}],
  623: [{"g": "Noir", "t": "Il vole à la vitesse du son. Si le sceau sur sa poitrine est retiré, il perd tout contrôle de lui-même."}, {"g": "Blanc", "t": "Ses créateurs d’une lointaine époque lui auraient ordonné de protéger les humains et les Pokémon."}, {"g": "Ultra-Soleil", "t": "Il aurait été créé dans les temps anciens pour servir de bête de somme. La voix de son maître fait loi."}, {"g": "Ultra-Lune", "t": "Gare au sceau de sa poitrine ! S’il est brisé, Golemastoc perd le contrôle et charge avec fureur. Il peut alors raser une ville entière."}, {"g": "Épée", "t": "Les murs des châteaux de jadis disposaient de créneaux, par lesquels les Golemastoc pouvaient tirer leurs rayons d’énergie."}, {"g": "Bouclier", "t": "Son énergie viendrait d’un mécanisme à mouvement perpétuel interne, mais jusqu’à présent, personne n’en a la preuve."}],
  624: [{"g": "Noir", "t": "Tout son corps est fait de lames. Si une lame s’émousse, il va l’aiguiser contre une pierre au bord d’une rivière."}, {"g": "Blanc", "t": "Obéissant aux directives d’un Scalproie, il s’agrippe à ses proies pour les poignarder."}, {"g": "Y", "t": "Ignorant leurs propres blessures, ils se jettent en groupe sur l’ennemi pour le déchirer de leur corps fait de lames."}, {"g": "Ultra-Soleil", "t": "Après avoir dépecé ses ennemis, il va sur les berges pour aiguiser ses lames sur une pierre. Chaque Scalpion a d’ailleurs son caillou fétiche."}, {"g": "Ultra-Lune", "t": "Il obéit à Scalproie au doigt et à l’œil sur le champ de bataille. Il fait résonner ses lames l’une contre l’autre une fois son ennemi tranché."}, {"g": "Épée", "t": "Il accule ses ennemis en jouant de ses lames acérées, qu’il aiguise sur les pierres des berges."}, {"g": "Bouclier", "t": "Il vit en meute, sous les ordres d’un Scalproie. Il s’entraîne sans relâche en rêvant du jour où il sera chef de meute à son tour."}],
  625: [{"g": "Noir", "t": "Ils dirigent les groupes de Scalpion. Ils se battent pour la suprématie sur le groupe, et les perdants en sont exclus."}, {"g": "Blanc", "t": "Il chasse avec un groupe de Scalpion sous ses ordres, mais c’est lui qui donne le coup de grâce."}, {"g": "X", "t": "Un Pokémon sans pitié qui tranche en deux ses proies immobilisées par les cohortes de Scalpion qu’il commande."}, {"g": "Ultra-Soleil", "t": "Peu importe la puissance du Scalproie, il abdique de son rôle de chef si la lame de sa tête subit la moindre ébréchure."}, {"g": "Ultra-Lune", "t": "Il dirige une cohorte de Scalpion. Il ne laisse transparaître aucune émotion lorsqu’il assène le coup de grâce."}, {"g": "Épée", "t": "Il dirige des cohortes de Scalpion. Il garde constamment ses sous-fifres à l’œil pour parer à toute velléité de mutinerie."}, {"g": "Bouclier", "t": "Sa recherche des meilleurs endroits où trouver des pierres pour affûter ses lames le conduit souvent à affronter des Incisache."}],
  626: [{"g": "Noir", "t": "Son pelage fourni absorbe les chocs et lui permet d’asséner sans broncher le plus violent des coups de tête."}, {"g": "Blanc", "t": "Il charge tout ce qui bouge sans réfléchir. Il peut faire dérailler un train en marche."}, {"g": "Épée", "t": "Il peut détruire une voiture d’un coup de tête. Plus sa crinière est volumineuse, plus son rang au sein du troupeau est élevé."}, {"g": "Bouclier", "t": "Les Frison vivent en troupeau d’une vingtaine d’individus. Pour une raison inconnue, si l’un d’eux trahit le groupe, il perd sa crinière."}],
  627: [{"g": "Noir", "t": "Il casse les Baies avec ses serres. Il combat courageusement, quelle que soit la force de l’adversaire."}, {"g": "Blanc", "t": "Il défie sans discernement même les ennemis puissants. Il devient plus fort en multipliant les combats."}, {"g": "Soleil", "t": "Il s’attaque à tout ce qui bouge, sans discrimination. Ses blessures et échecs ne font que le rendre plus fort."}, {"g": "Lune", "t": "Il agrippe ses proies avec ses serres effilées et les picore. Il lui arrive de manger des Baies, mais au fond c’est un carnivore."}, {"g": "Ultra-Soleil", "t": "Grâce à ses pattes puissantes et à ses serres robustes, il arrive même à briser la coquille de Kokiyas pour se délecter de son contenu."}, {"g": "Ultra-Lune", "t": "C’est un guerrier endurci dès sa naissance. Il commence d’ailleurs par défier ses parents au combat pour leur prouver sa valeur."}, {"g": "Épée", "t": "Il ne peut pas s’empêcher de défier les Pokémon qui ont l’air forts. Lorsqu’il perd, il pousse un cri assourdissant."}, {"g": "Bouclier", "t": "Sa poigne est telle qu’il peut réduire en miettes les plus dures des Baies. Belliqueux de nature, il n’hésite pas à défier tout le monde."}],
  628: [{"g": "Noir", "t": "Pour les siens, il combat au mépris du danger. Il est capable de soulever une voiture haut dans le ciel."}, {"g": "Blanc", "t": "Un chevalier du ciel brave et intrépide. Plus son corps porte de cicatrices, plus il est respecté de ses congénères."}, {"g": "X", "t": "Un chevalier du ciel, brave et intrépide. Pour les siens, il combat au mépris du danger, sans jamais fléchir."}, {"g": "Soleil", "t": "Rien n’effraie cet intrépide Pokémon, pas même la mort. Jadis, les gens d’Alola le surnommaient « le preux chevalier du ciel » avec respect."}, {"g": "Lune", "t": "Jadis, l’Homme a menacé son habitat. Tous les Gueriaigle se sont alors rassemblés et ont fait front commun pour repousser la menace."}, {"g": "Ultra-Soleil", "t": "Les balafres ne font qu’ajouter à sa renommée, mais les blessures dans le dos, synonymes de fuite en combat, sont mal vues par la volée."}, {"g": "Ultra-Lune", "t": "Surnommé « le héros céleste », il est tellement fier qu’il préfère endurer mille souffrances plutôt que de choisir la fuite."}, {"g": "Épée", "t": "C’est un Pokémon fier et vaillant. Sa bravoure lui vaut d’être souvent utilisé comme emblème sur les blasons."}, {"g": "Bouclier", "t": "Son caractère agressif et violent lui a valu de perdre son rôle de transporteur à Galar au profit de Corvaillus."}],
  629: [{"g": "Noir", "t": "Ses ailes sont trop petites pour lui permettre de voler. Quand l’évolution approche, il sort lui-même de sa coquille."}, {"g": "Blanc", "t": "Il trouve des os convenables pour protéger ses arrières, puis harcèle les Pokémon plus faibles que lui."}, {"g": "X", "t": "Ses ailes sont trop petites pour lui permettre de voler. Quand l’évolution approche, il sort lui-même du crâne qui le protège."}, {"g": "Y", "t": "Ses ailes sont trop petites pour voler. Il protège son croupion avec un crâne apporté par un Vaututrice."}, {"g": "Soleil", "t": "Il protège son tendre popotin avec le crâne d’une de ses proies. Il en change régulièrement en grandissant."}, {"g": "Lune", "t": "Il est encore très joueur. Ses ailes n’étant pas assez développées pour lui permettre de voler, il se déplace en sautillant."}, {"g": "Ultra-Soleil", "t": "Sa culotte est un cadeau de Vaututrice. Ses petites ailes ne pouvant pas le porter, il est condamné à sautiller en rêvant au grand azur."}, {"g": "Ultra-Lune", "t": "Ce petit est en pleine croissance et forcit à vue d’œil. Il doit donc régulièrement changer le crâne qui lui sert de culotte."}, {"g": "Épée", "t": "Ils protègent leur derrière en portant un crâne comme couche. Ils se disputent les plus douillets d’entre eux."}, {"g": "Bouclier", "t": "Il grandit vite. Au sein du nid, les petits Vostourno héritent des couches en crâne de leurs aînés."}],
  630: [{"g": "Noir", "t": "Il construit des nids en os. Il attrape les proies affaiblies avec ses serres et les transporte allègrement au nid."}, {"g": "Blanc", "t": "Il guette le sol depuis les airs et fond sur les proies affaiblies. Il aime s’apprêter avec des ossements."}, {"g": "X", "t": "Il tournoie dans les airs en quête d’une proie sur laquelle il fondra avant de l’emporter avec aisance à son nid."}, {"g": "Soleil", "t": "Les Vaututrice femelles se parent d’ossements pour leur parade nuptiale. On attend toujours de découvrir si les mâles existent ou pas."}, {"g": "Lune", "t": "Il tournoie, haut dans le ciel, à la recherche d’un Pokémon affaibli. Sa proie favorite est le petit Osselait."}, {"g": "Ultra-Soleil", "t": "Il utilise avec dextérité les ossements de ses proies pour construire son nid. La plupart de ces os appartenaient à des Osselait."}, {"g": "Ultra-Lune", "t": "Il est toujours à la recherche de nourriture pour Vostourno. Quand il trouve un Pokémon affaibli, il fond sur la proie et l’emporte dans son nid."}, {"g": "Épée", "t": "Malgré son naturel brutal, il recueille volontiers les Vostourno égarés et prend soin d’eux jusqu’à ce qu’ils soient en âge de quitter le nid."}, {"g": "Bouclier", "t": "Il se pare d’ossements qu’il a ramassés. Il semblerait qu’il choisisse la forme des os qu’il porte selon les dernières tendances."}],
  631: [{"g": "Noir", "t": "Il aspire de l’air par la queue et entretient un brasier dans son corps. C’est le prédateur des Fermite."}, {"g": "Blanc", "t": "Avec sa langue de feu à haute température, il fait fondre le corps d’acier des Fermite pour les dévorer."}, {"g": "Y", "t": "Il aspire de l’air par la queue et le transforme en une langue de feu qui fait fondre les Fermite dont il se régale."}, {"g": "Épée", "t": "Il aspire de l’air par le bout de sa queue et produit ainsi sa fameuse langue de feu. Si on lui bouche la queue, il se sent mal."}, {"g": "Bouclier", "t": "Il se sert de sa flamme comme d’une langue. Il fait fondre peu à peu l’exosquelette des Fermite pour se délecter de leur chair."}],
  632: [{"g": "Noir", "t": "Ils portent une armure de fer et se regroupent pour contrer les attaques de leurs prédateurs, les Aflamanoir."}, {"g": "Blanc", "t": "Ils creusent des galeries dans les montagnes. Les tunnels des Fermite sont de vrais labyrinthes."}, {"g": "X", "t": "Ils travaillent de concert pour protéger leur colonie des terribles attaques de leur prédateur naturel, Aflamanoir."}, {"g": "Épée", "t": "Il dépose ses Œufs tout au fond de son terrier. Lorsqu’un Aflamanoir l’attaque, il se défend à l’aide de ses mandibules."}, {"g": "Bouclier", "t": "Sa grande mâchoire réduit même les rochers en miettes. Il se bat avec sa colonie pour protéger ses Œufs des attaques des Dunaconda."}],
  633: [{"g": "Noir", "t": "Il mord tout ce qui bouge, et mange tout ce qu’il trouve. Il vaut mieux éviter de s’en approcher."}, {"g": "Blanc", "t": "Comme il ne voit rien, il perçoit son environnement en mordant et en fonçant à tout va. Il est couvert de plaies."}, {"g": "Y", "t": "Comme il ne voit rien, il perçoit son environnement en mordant et en fonçant à tout va."}, {"g": "Épée", "t": "Il mord d’abord et réfléchit ensuite. On dit qu’il n’oublie jamais l’odeur de la nourriture qu’il aime."}, {"g": "Bouclier", "t": "Comme il ne voit rien, il se repère en mâchouillant tout ce qui se trouve autour de lui."}],
  634: [{"g": "Noir", "t": "Quand il a mangé tout ce qui traînait sur son territoire, il migre vers d’autres horizons. Ses 2 têtes s’entendent mal."}, {"g": "Blanc", "t": "Ses deux têtes s’entendent mal. Même en mangeant, elles se cherchent des noises et dévorent à qui mieux mieux."}, {"g": "X", "t": "Ses deux têtes s’entendent mal et sont en compétition permanente pour savoir qui mangera le plus et qui sera le chef."}, {"g": "Épée", "t": "Il cherche des proies en arpentant son territoire. Ses deux têtes se disputent souvent pour savoir quelle direction prendre."}, {"g": "Bouclier", "t": "Ses deux têtes se disputent la même proie. Il est toujours couvert de blessures, même s’il n’a affronté personne."}],
  635: [{"g": "Noir", "t": "Un Pokémon violent qui patrouille le ciel avec ses six ailes et se jette sur tout ce qui bouge, pensant voir un ennemi."}, {"g": "Blanc", "t": "Les têtes sur ses bras n’ont pas de cerveau. Avec ses trois têtes, il dévore et détruit tout."}, {"g": "Y", "t": "Un Pokémon effrayant. Ses trois têtes dévorent tout ce qui bouge jusqu’à satiété."}, {"g": "Épée", "t": "Il dévore tout ce qui bouge. Bon nombre de légendes mentionnent des villages entiers rasés par un Trioxhydre."}, {"g": "Bouclier", "t": "Chacune de ses trois têtes mord à tour de rôle. Il attaque ses adversaires sans relâche, jusqu’à ce qu’ils s’écroulent."}],
  636: [{"g": "Noir", "t": "On dit que ce Pokémon serait né du soleil. Lorsqu’il évolue, tout son corps est enveloppé de flammes."}, {"g": "Blanc", "t": "Il vit au pied des volcans. Il repousse ceux qui l’attaquent avec les flammes qui jaillissent de ses cinq cornes."}, {"g": "X", "t": "On dit que ce Pokémon serait né du soleil. Il évolue en enveloppant son corps des flammes qui jaillissent de ses cornes."}, {"g": "Ultra-Soleil", "t": "Il se bat en projetant des flammes par ses cinq cornes. Ces gerbes de feu dévastatrices peuvent atteindre les 3 000 °C."}, {"g": "Ultra-Lune", "t": "Il se sert de flammes pour se défendre. Jadis, les anciens pensaient qu’il nichait dans le soleil."}, {"g": "Épée", "t": "Il y a fort longtemps, les gens croyaient que les Pyronille étaient tombés du soleil."}, {"g": "Bouclier", "t": "La température de son corps est très élevée. Il projette des flammes du bout de ses cornes pour intimider ses ennemis et ses proies."}],
  637: [{"g": "Noir", "t": "On dit que quand le ciel s’est obscurci à cause des cendres d’un volcan, le feu d’un Pyrax aurait remplacé le soleil."}, {"g": "Blanc", "t": "Quand il se bat, il fait pleuvoir des écailles enflammées de ses six ailes et transforme les alentours en mer de feu."}, {"g": "Ultra-Soleil", "t": "Il décrit des cercles dans le ciel en faisant pleuvoir des écailles enflammées. Il était jadis surnommé « le courroux solaire »."}, {"g": "Ultra-Lune", "t": "Selon la légende, il serait né d’un cocon de flammes et serait venu à la rescousse des humains et des Pokémon souffrant du froid."}, {"g": "Épée", "t": "Certains disent qu’il répand ses écailles ardentes pour provoquer des incendies, d’autres, pour sauver ceux qui souffrent du froid."}, {"g": "Bouclier", "t": "Né d’un cocon enflammé, ce Pokémon apparaît sur d’anciennes fresques représenté comme une divinité du feu."}],
  638: [{"g": "Noir", "t": "Un Pokémon légendaire qui a combattu les humains pour protéger les Pokémon. Il est d’un naturel calme et posé."}, {"g": "Blanc", "t": "Il possède un corps et un cœur de fer. Il peut mater les Pokémon les plus agressifs d’un simple regard."}, {"g": "Y", "t": "Un corps et un cœur en acier trempé, jadis au service de la défense des Pokémon blessés par les humains."}, {"g": "Épée", "t": "Selon la légende, il aurait défié les Hommes, aux côtés de Terrakium et de Viridium, pour protéger les Pokémon d’Unys."}, {"g": "Bouclier", "t": "Dès la naissance, il a un air de chef. Même le plus terrible des adversaires file doux face à lui."}],
  639: [{"g": "Noir", "t": "Il a combattu les humains pour protéger les Pokémon ayant perdu leur foyer à cause de leurs guerres fratricides."}, {"g": "Blanc", "t": "Sa puissance d’impact lui permet d’enfoncer d’un seul coup le rempart d’un château. Un Pokémon de légende."}, {"g": "Y", "t": "Un Pokémon de légende. Grâce à sa puissance phénoménale, il aurait détruit un château pour sauver des Pokémon."}, {"g": "Épée", "t": "Il possède un pouvoir incommensurable. Il se montre impitoyable envers ceux qui s’en prennent aux petits Pokémon."}, {"g": "Bouclier", "t": "Selon une légende d’Unys, Terrakium se serait jadis dressé contre les humains pour protéger les Pokémon."}],
  640: [{"g": "Noir", "t": "Il a défié les humains pour protéger les siens. Son nom est resté dans la légende."}, {"g": "Blanc", "t": "Ses cornes sont des lames effilées. Il lacère ses ennemis dans un mouvement tourbillonnant."}, {"g": "Y", "t": "Il lacère ses ennemis avec une agilité sans égale. La légende raconte qu’il protège les Pokémon."}, {"g": "Épée", "t": "Selon la légende, il aurait combattu aux côtés de Cobaltium et de Terrakium pour protéger les Pokémon d’Unys."}, {"g": "Bouclier", "t": "Rapide comme le vent, il s’abat tel un tourbillon sur ses ennemis avant de les transpercer sans pitié de ses cornes acérées."}],
  641: [{"g": "Noir", "t": "Le bas de son corps est entouré d’une masse d’énergie semblable à un nuage. Il vole dans le ciel à 300 km/h."}, {"g": "Blanc", "t": "L’énergie dégagée par sa queue provoque d’énormes tempêtes dont la force peut renverser des maisons."}],
  642: [{"g": "Noir", "t": "Les terres qu’il a survolées sont recouvertes d’innombrables traces des éclairs qu’il y a fait tomber."}, {"g": "Blanc", "t": "Sa queue lance des décharges électriques. Il vole dans le ciel d’Unys et fait tomber des éclairs."}, {"g": "Y", "t": "Il vole dans le ciel d’Unys et fait tomber des éclairs, provoquant des incendies qui font sa mauvaise réputation."}],
  643: [{"g": "Noir", "t": "Un Pokémon mythique. Il projette de sa queue un tourbillon de flammes capable de tout emporter."}, {"g": "Blanc", "t": "Quand sa queue s’embrase, l’énergie thermique dégagée modifie l’atmosphère et bouleverse la météo du monde entier."}, {"g": "X", "t": "Un Pokémon légendaire assez puissant pour embraser le monde entier. Il soutient les défenseurs de la Réalité."}, {"g": "Épée", "t": "Il vole grâce à la propulsion générée par les flammes de sa queue. Il serait capable de réduire le monde en cendres."}, {"g": "Bouclier", "t": "Selon un mythe, lorsque les gens ne font aucun cas de la Réalité et s’abandonnent à la cupidité, Reshiram rase le pays entier avec ses flammes."}],
  644: [{"g": "Noir", "t": "Sa queue produit de l’électricité. Il dissimule son corps dans un nuage électrique et plane dans le ciel d’Unys."}, {"g": "Blanc", "t": "Un Pokémon mythique. Il possède dans sa queue un énorme générateur qui produit de l’électricité."}, {"g": "X", "t": "Un Pokémon légendaire assez puissant pour foudroyer le monde entier. Il soutient ceux qui suivent leur Idéal."}, {"g": "Épée", "t": "Lorsque sa queue se met à tourner comme un réacteur, il produit des éclairs qui transpercent tout autour de lui."}, {"g": "Bouclier", "t": "Selon la légende, lorsque les gens perdent tout sens de ce qui est juste, Zekrom réduit le pays entier en cendres avec de terribles éclairs."}],
  645: [{"g": "Noir", "t": "Il fait fructifier les cultures partout où il passe, c’est pourquoi on l’appelle “le dieu des moissons”."}, {"g": "Blanc", "t": "L’énergie déversée par sa queue enrichit les sols en nutriments et favorise les cultures."}, {"g": "X", "t": "Il fait fructifier les cultures partout où il passe, c’est pourquoi on l’appelle « le dieu des moissons »."}, {"g": "Y", "t": "Il utilise l’énergie qu’il tire du vent et de la foudre pour enrichir les sols en nutriments pour les cultures."}],
  646: [{"g": "Noir", "t": "Son corps produit une énergie à très basse température, mais le souffle glacé qu’il exhale l’a gelé lui-même."}, {"g": "Blanc", "t": "Il a le pouvoir de générer un souffle d’un froid inimaginable, mais a fini par se geler lui-même."}, {"g": "X", "t": "Il attend le héros qui saura réanimer son corps de glace incomplet en partageant avec lui son Idéal et sa Réalité."}, {"g": "Épée", "t": "Il possède une puissance qui dépasse celle de Reshiram et de Zekrom, mais il a scellé son corps grâce à son souffle glacé."}, {"g": "Bouclier", "t": "Il se serait congelé lui-même avec son souffle glacé pour stabiliser sa structure cellulaire."}],
  647: [{"g": "Noir", "t": "Il projette de l’eau depuis ses sabots et se déplace ainsi à grande vitesse. Sa botte secrète est le coup de sabot."}, {"g": "Blanc", "t": "Il parcourt le monde en courant à la surface des mers et des cours d’eau. Il apparaît là où l’eau est très pure."}, {"g": "Y", "t": "Lorsqu’il est résolu, de l’énergie sature son corps et le propulse à des vitesses qui dépassent la perception humaine."}, {"g": "Épée", "t": "Cobaltium, Terrakium et Viridium lui ont appris à se battre. Il poursuit son entraînement en parcourant le monde."}, {"g": "Bouclier", "t": "Lorsqu’il livre un combat difficile, la corne sur son front se renforce et se développe, ce qui éveillerait sa véritable puissance."}],
  648: [{"g": "Noir", "t": "Sa voix si particulière lui permet de chanter des mélodies qui ensorcellent les gens et modifient leurs émotions."}, {"g": "Blanc", "t": "De nombreux succès musicaux ont été composés en s’inspirant des mélodies chantées par Meloetta."}, {"g": "X", "t": "Les mélodies enivrantes de Meloetta touchent les Pokémon, pouvant les rendre heureux ou tristes."}],
  649: [{"g": "Noir", "t": "Il y a 300 millions d’années, il était craint comme l’ultime prédateur. Il a été modifié par la Team Plasma."}, {"g": "Blanc", "t": "Un Pokémon Insecte des temps anciens modifié par la Team Plasma. Le canon dans son dos a été grandement amélioré."}, {"g": "Y", "t": "Un Pokémon existant depuis 300 millions d’années, et modifié par la Team Plasma. Il a maintenant un canon dans le dos."}],
  650: [{"g": "X", "t": "Lorsqu’il rassemble ses forces, les piquants souples qui recouvrent sa tête deviennent si durs et acérés qu’ils pourraient transpercer un rocher."}, {"g": "Y", "t": "Sa tête et son dos sont recouverts d’une carapace tellement dure que même une collision avec un camion ne lui ferait rien."}],
  651: [{"g": "X", "t": "La carapace qui recouvre son corps le protège des attaques adverses, et ses piquants lui permettent de contre-attaquer."}, {"g": "Y", "t": "Il renforce ses membres inférieurs en se ruant violemment sur ses congénères. Naturellement paisible, il ne provoque jamais un combat."}],
  652: [{"g": "X", "t": "Il est si puissant qu’il pourrait renverser un char de 50 t d’un seul assaut. Il se sert de son corps comme d’un bouclier pour protéger ses alliés."}, {"g": "Y", "t": "Il se défend en joignant ses poings devant son visage. Dans cette posture, il peut même résister à l’onde de choc d’une explosion."}],
  653: [{"g": "X", "t": "En cas de coup de fatigue, il grignote des rameaux pour recharger ses batteries. Ses oreilles dégagent une chaleur qui dépasse les 200 °C."}, {"g": "Y", "t": "Il a toujours une brindille avec lui en cas de petit creux. Il projette de l’air chaud par ses oreilles pour intimider ses ennemis."}],
  654: [{"g": "X", "t": "Il allume la branche plantée dans sa queue en la frottant contre son pelage et s’en sert au combat."}, {"g": "Y", "t": "Quand il saisit la branche plantée dans sa queue, elle prend feu par friction. Il peut communiquer avec ses congénères en agitant ce bâton enflammé."}],
  655: [{"g": "X", "t": "Peut prédire l’avenir s’il se concentre en fixant la flamme qui danse au bout de sa canne."}, {"g": "Y", "t": "Ses pouvoirs psychiques lui permettent de créer des tourbillons de flammes à 3 000 °C qui enveloppent et consument ses ennemis."}],
  656: [{"g": "X", "t": "Sa poitrine et son dos sécrètent une mousse qui lui permet de subir moins de dégâts en amortissant le choc des attaques."}, {"g": "Y", "t": "Il protège son corps en l’entourant d’une mousse délicate. Malgré son apparence insouciante, ce Pokémon est en fait constamment à l’affût."}],
  657: [{"g": "X", "t": "Il est capable de lancer des pierres recouvertes de mousse avec une précision suffisante pour toucher une canette vide à 30 m."}, {"g": "Y", "t": "Son agilité est incomparable. Il peut gravir une tour de 600 m de haut en moins d’une minute."}],
  658: [{"g": "X", "t": "Il transforme des jets d’eau sous pression en redoutables shuriken. Une fois lancés, ils tournent si vite qu’ils peuvent même couper le métal."}, {"g": "Y", "t": "Aussi insaisissable qu’un ninja, il se joue de ses ennemis grâce à sa célérité, et les tranche de ses Sheauriken."}],
  659: [{"g": "X", "t": "Ses larges oreilles lui permettent de creuser des terriers. Il est capable de forer sans s’arrêter pendant toute une nuit."}, {"g": "Y", "t": "Il est doté d’oreilles ressemblant à des pelles. À force de creuser des galeries, leur puissance est telle qu’elles peuvent trancher de grosses racines."}, {"g": "Épée", "t": "Il est très doué pour creuser avec ses oreilles. Il peut forer un terrier atteignant dix mètres de profondeur en une nuit."}, {"g": "Bouclier", "t": "Il est sensible au danger. Lorsqu’il entend le battement d’ailes de Corvaillus, il creuse prestement un terrier et s’y cache."}],
  660: [{"g": "X", "t": "Ses grandes oreilles sont si musclées qu’il peut soulever un rocher d’une tonne sans broncher. Ce Pokémon est souvent utilisé sur les chantiers."}, {"g": "Y", "t": "Ses oreilles sont de véritables excavateurs, venant à bout des blocs de pierre les plus durs. Après l’effort, il se repose en paressant."}, {"g": "Épée", "t": "Aussi puissant qu’une pelleteuse, il peut venir à bout de la roche la plus dure. On fait souvent appel à lui pour forer des tunnels."}, {"g": "Bouclier", "t": "La fourrure de son ventre est un excellent isolant thermique. Jadis, on fabriquait des vêtements chauds en se servant de sa mue."}],
  661: [{"g": "X", "t": "Peu farouche, il communique avec ses congénères par un doux gazouillis et par des signaux de la queue."}, {"g": "Y", "t": "Son chant est harmonieux, mais trompeur ! Les ennemis qui pénètrent sur son territoire se retrouvent confrontés à un déluge de violence."}, {"g": "Soleil", "t": "C’est un Pokémon affectueux et très facile à élever, mais une fois en situation de combat, il devient un adversaire implacable."}, {"g": "Lune", "t": "Quand il est tout excité, sa température peut doubler et ses hormones bouillonnent."}, {"g": "Ultra-Soleil", "t": "Bien qu’il soit affectueux, il peut brusquement augmenter sa température et infliger des brûlures à ceux qui le touchent par surprise."}, {"g": "Ultra-Lune", "t": "Une agréable chaleur émane toujours de son petit corps. Dans les régions froides, il n’est pas rare qu’il dorme dans le lit de son Dresseur."}, {"g": "Épée", "t": "Son chant mélodieux est en fait une tentative d’intimidation. Il picore sans merci tout individu qui pénètre dans son territoire."}, {"g": "Bouclier", "t": "Quand il est surexcité, sa température corporelle augmente d’un coup, à tel point qu’il est possible de se brûler en le touchant à mains nues."}],
  662: [{"g": "X", "t": "Il crache des étincelles pour brûler les hautes herbes et attraper les proies surprises qui tentent d’échapper à l’incendie."}, {"g": "Y", "t": "Il possède une poche remplie de feu sur son ventre. Plus elle émet de chaleur, plus il vole vite. Cependant, elle met quelque temps à chauffer."}, {"g": "Soleil", "t": "Il crache des escarbilles par le bec, en visant sa proie. Une fois celle-ci capturée, il la fait rôtir avant de la déguster."}, {"g": "Lune", "t": "Son territoire s’étend sur plusieurs kilomètres. L’intrusion d’autres Braisillon n’est en aucun cas tolérée."}, {"g": "Ultra-Soleil", "t": "Il enflamme des touffes d’herbe en crachant des escarbilles. Il n’a plus qu’à s’emparer des Pokémon Insecte qui s’enfuient pour les gober."}, {"g": "Ultra-Lune", "t": "À peine décolle-t-il que sa vitesse lui permet déjà de rivaliser avec les Pokémon oiseaux les plus rapides."}, {"g": "Épée", "t": "Il lance des étincelles dans le terrier de ses proies pour les effrayer. Dès qu’elles en émergent, il les attaque à coups de serres."}, {"g": "Bouclier", "t": "De nature belliqueuse, il dispose d’un fort instinct territorial. Quand il chasse, il se dispute régulièrement les proies avec ses congénères."}],
  663: [{"g": "X", "t": "Exalté par un combat sans merci, il s’envole en semant dans son sillage les escarbilles du feu qui couve dans son plumage."}, {"g": "Y", "t": "Quand il s’abat sur ses proies, sa vitesse dépasse les 500 km/h. Il les achève d’un puissant coup de serre."}, {"g": "Soleil", "t": "Il raffole des Goélise et des Picassaut. Il déstabilise ses proies d’un bon coup de patte avant de les capturer avec ses serres acérées."}, {"g": "Lune", "t": "Il fond sur ses proies en piqué à 500 km/h, semant derrière lui une pluie d’escarbilles échappées de ses ailes."}, {"g": "Ultra-Soleil", "t": "Son plumage résistant est ignifugé. Jadis, la combinaison portée par les pompiers était faite de plumes de Flambusard."}, {"g": "Ultra-Lune", "t": "La plupart de ses proies sont des Pokémon oiseaux. Il surgit sans prévenir et propulse sa victime au sol d’un puissant coup de patte."}, {"g": "Épée", "t": "Flambusard chasse surtout les Pokémon oiseaux. Il intimide ses adversaires en produisant des étincelles avec son plumage."}, {"g": "Bouclier", "t": "Flambusard attaque à une vitesse de 500 km/h. Il achève ses proies d’un puissant coup de patte sans leur laisser la moindre chance de fuir."}],
  664: [{"g": "X", "t": "Lorsqu’il est poursuivi par un Pokémon Oiseau, il projette une poudre noire qui paralyse tous ceux qu’elle touche."}, {"g": "Y", "t": "La poudre qui recouvre son corps l’aide à réguler sa température. Il peut s’adapter à tous les climats."}],
  665: [{"g": "X", "t": "Vit caché sous le couvert des buissons. Poursuivi par un ennemi, il tente de l’intimider en hérissant les poils qui lui couvrent le corps."}, {"g": "Y", "t": "Même les becs acérés des Pokémon Oiseaux ne parviennent pas à meurtrir son corps très dur. Il se défend en crachant de la poudre."}],
  666: [{"g": "X", "t": "Les ailes des Prismillon arborent différents motifs en fonction de leur aire d’origine. Il est possible que le climat y soit pour quelque chose."}, {"g": "Y", "t": "Selon le climat de sa région d’origine, les motifs de ses ailes sont différents. Il sème des écailles aux couleurs vives."}],
  667: [{"g": "X", "t": "Plus l’adversaire auquel il est confronté est fort, plus la température de sa crinière augmente, l’énergie générée se diffusant alors dans tout son corps."}, {"g": "Y", "t": "Il n’hésite pas à quitter la horde et à mener une existence solitaire pour mieux pouvoir s’entraîner. Il a le sang chaud et ne rechigne pas au combat."}, {"g": "Ultra-Soleil", "t": "Il est élevé avec ses congénères au sein de la troupe, mais dès qu’il peut chasser seul, il doit partir et vivre par ses propres moyens."}, {"g": "Ultra-Lune", "t": "Il déborde d’énergie et de curiosité. Quand il se fâche ou qu’il s’apprête à se battre, sa courte crinière s’échauffe."}],
  668: [{"g": "X", "t": "Le mâle qui possède la crinière de feu la plus imposante devient le chef de la horde."}, {"g": "Y", "t": "Son souffle peut atteindre les 6 000 °C et il s’en sert pour intimider l’ennemi. Dans la horde, les femelles protègent les petits."}, {"g": "Ultra-Soleil", "t": "Le mâle a tendance à se prélasser à longueur de journée. Si un ennemi surgit, en revanche, il défend ses congénères au péril de sa vie."}, {"g": "Ultra-Lune", "t": "Son souffle enflammé atteint les 6 000 °C, mais il ne l’utilise jamais contre ses proies. Il préfère en effet la viande crue."}],
  669: [{"g": "Ultra-Lune", "t": "Il confectionne la couronne qui orne sa tête en récoltant du pollen. Elle recèle de nombreuses propriétés curatives."}, {"g": "X", "t": "Capable de libérer et de contrôler la force cachée des plantes. La fleur qu’il tient fait partie de lui."}, {"g": "Y", "t": "Après avoir trouvé une fleur à son goût, il ne la quitte plus de toute sa vie. Il se laisse porter au gré du vent."}, {"g": "Ultra-Soleil", "t": "Bien qu’il soit vulnérable sans le pouvoir de sa fleur, il voyagera jusqu’à en trouver une de la couleur et de la forme qu’il préfère."}],
  670: [{"g": "X", "t": "Il survole les champs de fleurs, et prend soin de celles qui sont sur le point de faner. Au combat, il fait appel à leur force cachée."}, {"g": "Y", "t": "Quand les fleurs d’une plate-bande bien soignée éclosent, il apparaît et célèbre la floraison en dansant avec une très grande élégance."}, {"g": "Ultra-Soleil", "t": "Il cultive des fleurs et les utilise en tant qu’armes. Plus une fleur est belle, plus elle renferme de puissance."}, {"g": "Ultra-Lune", "t": "Il fait profiter ses fleurs de ses pouvoirs et met tout son cœur à leur entretien. Gare à ceux qui ravagent ses plates-bandes !"}],
  671: [{"g": "X", "t": "Les jardins fleuris sont son territoire. Il se baigne dans l’énergie dégagée par les plantes en fleurs pour l’absorber."}, {"g": "Y", "t": "Les châtelains de jadis invitaient les Florges sur leurs terres et leur confiaient la réalisation de leurs jardins."}, {"g": "Ultra-Soleil", "t": "Il contrôle les fleurs qu’il cultive. Les tempêtes de pétales qu’il déchaîne sont aussi belles que redoutables."}, {"g": "Ultra-Lune", "t": "Il peut vivre des centaines d’années, et consacre sa longue existence à l’entretien des jardins."}],
  672: [{"g": "X", "t": "Ce Pokémon paisible serait le premier à avoir jamais cohabité avec les humains."}, {"g": "Y", "t": "Tant qu’il a de l’eau et du soleil en abondance, ce Pokémon n’a pas besoin de nourriture. Les feuilles sur son dos produisent son énergie par photosynthèse."}],
  673: [{"g": "X", "t": "Quand son Dresseur le tient par une corne, il est capable de deviner ses plus subtils changements d’humeur et de s’y adapter."}, {"g": "Y", "t": "Ce Pokémon vit dans les régions montagneuses. Le chef du troupeau s’impose à l’issue d’un combat de cornes."}],
  674: [{"g": "Y", "t": "Il fait de son mieux pour avoir un air patibulaire, mais il sourit béatement dès qu’on lui caresse la tête."}, {"g": "X", "t": "Il fait son possible pour intimider ses adversaires avec un regard menaçant, mais sans succès. Il a l’habitude de constamment mâcher une feuille."}, {"g": "Soleil", "t": "Il grandit en copiant les poses et les mimiques de ce gros cador de Pandarbare, qu’il considère comme son mentor."}, {"g": "Lune", "t": "C’est juste pour se donner un air qu’il mâche une feuille. Comme c’est un petit galopin, il est déconseillé aux Dresseurs inexpérimentés."}, {"g": "Ultra-Soleil", "t": "Il suit Pandarbare comme son ombre et le considère comme son chef. S’il fait une grosse bêtise, on lui confisque sa feuille."}, {"g": "Ultra-Lune", "t": "Il essaie à tout prix d’intimider son adversaire. S’il vous fait les gros yeux, faites-lui plaisir et prenez l’air apeuré !"}, {"g": "Épée", "t": "C’est en copiant son mentor, Pandarbare, qu’il apprend toutes les ficelles du métier, de l’art du combat à la capture des proies."}, {"g": "Bouclier", "t": "Il dévisage toujours ses adversaires d’un air renfrogné pour être pris au sérieux, mais dès que la tension retombe, son sourire reprend le dessus."}],
  675: [{"g": "X", "t": "D’un tempérament fougueux, il ne supporte pas que l’on s’en prenne aux faibles. Sa feuille lui permet de deviner les actions de l’ennemi."}, {"g": "Y", "t": "Il encaisse les attaques de plein fouet sans même tiquer et il poursuit sa route. Il étale ses ennemis d’un coup de patte capable de briser un poteau électrique."}, {"g": "Soleil", "t": "Ses gros bras sont sa plus grande fierté. Si vous voulez devenir un Dresseur de Pandarbare, il va falloir jouer des poings !"}, {"g": "Lune", "t": "Il peut détecter les mouvements ennemis grâce aux vibrations de sa feuille. Avec ses amis, ce grand lunatique a en fait le cœur sur la main."}, {"g": "Ultra-Soleil", "t": "Ce Pokémon féroce est très fier de ses gros bras. Beaucoup de Dresseurs l’apprécient pour son côté truculent."}, {"g": "Ultra-Lune", "t": "Il est du genre à laisser ses poings parler : il martèle ses ennemis et charge avec assez de force pour envoyer voler un camion-benne."}, {"g": "Épée", "t": "Ce Pokémon agressif a recours à la force pour faire taire ceux qui le contrarient. Il adore combattre les Ixon."}, {"g": "Bouclier", "t": "Il anticipe les mouvements de son adversaire grâce à sa feuille. Ses coups de poing peuvent réduire un camion-benne en un tas de ferraille."}],
  676: [{"g": "X", "t": "Si son abondante fourrure gagne à être toilettée, ce n’est pas qu’une question de style. En effet, cela lui permet également de se mouvoir plus librement."}, {"g": "Y", "t": "Il y a fort longtemps dans la région de Kalos, ce Pokémon fut le gardien des rois et des reines."}, {"g": "Ultra-Soleil", "t": "Il fut un temps où la noblesse organisait des concours pour déterminer quel Couafarel arborait la plus belle coupe."}, {"g": "Ultra-Lune", "t": "Sa fourrure pousse indéfiniment, mais il refuse de se faire couper la toison par une personne en qui il n’a pas confiance."}],
  677: [{"g": "X", "t": "Il couvre la source de ses pouvoirs psychiques hors du commun avec ses oreilles afin d’éviter les accidents."}, {"g": "Y", "t": "Il a quelques difficultés à contrôler son pouvoir psychique. Grâce à celui-ci, il peut projeter en l’air tous les objets dans un rayon de 100 m."}, {"g": "Épée", "t": "Sous son masque inexpressif, il est en fait constamment en train d’essayer de contenir ses puissants pouvoirs psychiques."}, {"g": "Bouclier", "t": "Il possède des pouvoirs psychiques si puissants qu’il peut faire valser un catcheur. Malheureusement, il a du mal à les contrôler."}],
  678: [{"g": "X", "t": "S’il se sent menacé, il lève les oreilles et déchaîne un pouvoir psychique capable de réduire en miettes un camion de 10 t."}, {"g": "Y", "t": "Les motifs en forme d’yeux à l’intérieur de ses oreilles émettent une force psychique tellement puissante qu’il est contraint de les garder couverts."}, {"g": "Épée", "t": "Les motifs en forme d’yeux, à l’intérieur de ses oreilles, sont la source de ses pouvoirs psychiques. La plupart du temps, il cache ces pouvoirs."}, {"g": "Bouclier", "t": "Le mâle a un instinct de défense très développé. Il n’hésite pas à lancer une attaque à pleine puissance pour protéger ses partenaires et lui."}],
  679: [{"g": "X", "t": "Ce Pokémon naît quand l’âme d’un défunt prend possession d’une épée ancienne. Il s’accroche aux humains pour absorber leur énergie vitale."}, {"g": "Y", "t": "Si quelqu’un s’aventure à l’empoigner, il enroule son étoffe bleue autour du bras de l’infortuné et aspire son énergie vitale jusqu’à ce que ce dernier s’écroule."}, {"g": "Épée", "t": "L’âme de Monorpale est celle d’un humain qui a été tué il y a fort longtemps, par la même lame qui forme maintenant son corps."}, {"g": "Bouclier", "t": "L’œil bleu sur la garde de la lame est le véritable corps de Monorpale. Il aspire l’énergie vitale des gens avec son étoffe usée par le temps."}],
  680: [{"g": "X", "t": "En évoluant, Monorpale se divise en deux épées qui communiquent par télépathie pour mieux découper leur adversaire en morceaux."}, {"g": "Y", "t": "Même les sabreurs chevronnés sont incapables de parer les assauts continus et complexes menés de concert par ces deux épées."}, {"g": "Épée", "t": "Il s’est dédoublé en évoluant. Il intimide ses ennemis à grands coups de bruits métalliques en entrechoquant ses deux lames."}, {"g": "Bouclier", "t": "Ses deux lames abattent leurs proies en enchaînant les attaques et les parades à un rythme effréné."}],
  681: [{"g": "X", "t": "Ils ont fait le bonheur de générations de rois. Leurs pouvoirs psychiques leur permettent de contrôler hommes et Pokémon."}, {"g": "Y", "t": "Il peut déceler les qualités régaliennes dans les âmes humaines. On raconte que celui ou celle qui obtient sa faveur deviendra à coup sûr roi ou reine."}, {"g": "Épée", "t": "Grâce à son corps en acier et à sa barrière psychique, il peut se défendre en affaiblissant toutes sortes d’attaques."}, {"g": "Bouclier", "t": "Grâce à ses puissants pouvoirs spirituels, il a contrôlé des humains et des Pokémon pour créer un pays conforme à ses idéaux."}],
  682: [{"g": "X", "t": "Son corps dégage un parfum qui envoûte ceux qui le respirent et change en fonction de son alimentation."}, {"g": "Y", "t": "Par le passé, les femmes de la noblesse ne se parfumaient pas, mais étaient accompagnées d’un Fluvetin exhalant leur parfum favori."}, {"g": "Épée", "t": "Ce Pokémon sécrète son doux parfum grâce à un organe en forme de poche. S’il modifie son alimentation, l’odeur de son parfum change."}, {"g": "Bouclier", "t": "Une douce odeur qui charme les gens émane de son corps. Les dames nobles raffolaient de lui."}],
  683: [{"g": "X", "t": "Ce Pokémon est capable d’émettre toutes sortes d’odeurs pour incommoder son adversaire et augmenter ses chances de gagner."}, {"g": "Y", "t": "Son parfum est tellement capiteux qu’un Dresseur n’appréciant pas pleinement son odeur aura toutes les difficultés du monde à cheminer à ses côtés."}, {"g": "Épée", "t": "Un parfum capiteux émane constamment de sa fourrure. Ce parfum est si fort qu’il peut priver son Dresseur d’odorat."}, {"g": "Bouclier", "t": "Il peut émettre une puanteur si infâme qu’elle prive ses ennemis de leur combativité, ou un parfum si réconfortant qu’il encourage ses alliés."}],
  684: [{"g": "X", "t": "Il immobilise son adversaire à l’aide de filaments blancs, sucrés et collants qui ressemblent à de la barbe à papa."}, {"g": "Y", "t": "Il se gave de sucreries à longueur de journée, à tel point que sa fourrure finit par ressembler à de la barbe à papa, sucrée et poisseuse."}, {"g": "Épée", "t": "Il mange son propre poids en sucre chaque jour. S’il n’a pas sa dose de sucreries, il devient horriblement grognon."}, {"g": "Bouclier", "t": "Sa douce fourrure possède une odeur sucrée comme la barbe à papa. Il produit des filaments gluants pour empêtrer ses adversaires."}],
  685: [{"g": "X", "t": "La finesse de son odorat lui permet de distinguer les nuances de parfums les plus subtiles, ce qui en fait un compagnon idéal pour les pâtissiers."}, {"g": "Y", "t": "Son odorat est des millions de fois plus développé que celui d’un humain. Il se repère dans l’espace grâce aux odeurs qui flottent autour de lui."}, {"g": "Épée", "t": "Il peut diagnostiquer l’état de santé mentale et physique de quelqu’un rien qu’à l’odorat. Un tel don pourrait avoir des applications en médecine."}, {"g": "Bouclier", "t": "Sa fourrure est si aérée qu’elle le rend très doux et très agréable au toucher, et bien plus léger qu’il en a l’air."}],
  686: [{"g": "X", "t": "Éblouis par les points lumineux qui clignotent sur son corps, les ennemis perdent toute envie de se battre."}, {"g": "Y", "t": "Il ébranle le moral des ennemis lui cherchant noise grâce aux clignotements qu’il émet. Il profite de cette diversion pour se cacher."}, {"g": "Ultra-Soleil", "t": "Il attire ses proies en faisant clignoter son corps, puis les immobilise en les enserrant de ses longs tentacules."}, {"g": "Ultra-Lune", "t": "Il fait clignoter ses points lumineux à différentes fréquences pour échanger des informations avec ses congénères."}, {"g": "Épée", "t": "Il fait clignoter son corps lumineux en tournoyant. Il communique avec ses congénères à l’aide de signaux de lumière."}, {"g": "Bouclier", "t": "Il sape la combativité de son adversaire en faisant clignoter son corps lumineux, puis profite de cet instant de répit pour s’enfuir."}],
  687: [{"g": "X", "t": "Doté des pouvoirs hypnotiques les plus puissants du règne des Pokémon, il manipule son adversaire à sa guise."}, {"g": "Y", "t": "Il attire ses ennemis en les hypnotisant, avant de les enserrer de ses tentacules et de les neutraliser avec son suc gastrique."}, {"g": "Ultra-Soleil", "t": "Les personnes malintentionnées tentent souvent de s’approprier ses grands pouvoirs hypnotiques pour servir leurs mauvais desseins."}, {"g": "Ultra-Lune", "t": "Il fait briller les motifs qui ornent son corps afin d’attirer ses proies. L’extrémité de ses tentacules est aussi coupante qu’un rasoir."}, {"g": "Épée", "t": "Il manipule à sa guise ceux qui se sont laissé hypnotiser en observant son corps lumineux trop longtemps."}, {"g": "Bouclier", "t": "On raconte que ses pouvoirs hypnotiques seraient à l’origine d’évènements qui ont bouleversé le cours de l’Histoire."}],
  688: [{"g": "X", "t": "Chaque rocher abrite deux Opermine. S’ils se disputent, l’un d’entre eux part à la recherche d’un nouveau logis."}, {"g": "Y", "t": "Ils prennent de l’élan avec tout leur corps et soulèvent ainsi leur pierre pour se déplacer. Ils mangent les algues échouées sur le rivage."}, {"g": "Épée", "t": "Ils vivent par groupes de deux sur un rocher qui leur convient en bord de mer. À marée haute, le duo coopère pour capturer des proies."}, {"g": "Bouclier", "t": "Il faut que les deux bras travaillent bien ensemble s’ils souhaitent survivre, sinon leur défense et leur attaque en souffrent grandement."}],
  689: [{"g": "X", "t": "Après évolution, les deux Opermine laissent place à sept créatures qui ont la puissance cumulée de sept Opermine."}, {"g": "Y", "t": "Ses jambes et ses bras sont dotés d’une volonté propre. Cependant, ils suivent généralement les ordres donnés."}, {"g": "Épée", "t": "Sept Opermine s’assemblent pour former un Golgopathe. La tête commande les autres membres."}, {"g": "Bouclier", "t": "Il scrute les environs avec les yeux de ses paumes. En cas d’urgence, ses membres peuvent prendre des initiatives pour triompher de l’ennemi."}],
  690: [{"g": "X", "t": "Il se cache parmi les algues en décomposition pour mieux approcher ses proies, qu’il achève en les aspergeant de poison."}, {"g": "Y", "t": "Sa ressemblance avec le varech pourri est confondante. Il se soustrait à l’attention de ses ennemis en attendant de pouvoir évoluer."}, {"g": "Ultra-Soleil", "t": "Il reste tapi au fond des océans, à l’abri des plus gros Pokémon. Il se nourrit principalement d’algues pourries."}, {"g": "Ultra-Lune", "t": "Comme il n’est pas très bon nageur, il se contente de s’entortiller autour des algues. À Alola, on le trouve souvent près de Sinistrail."}, {"g": "Épée", "t": "Il se mêle aux algues en décomposition flottant à la surface des océans afin de surprendre et de dévorer les Pokémon qui viennent s’en nourrir."}, {"g": "Bouclier", "t": "Ressembler à une algue en décomposition lui permet d’échapper à ses ennemis en se cachant au milieu des résidus de plantes aquatiques."}],
  691: [{"g": "X", "t": "Il asperge tous ceux qui osent pénétrer sur son territoire d’un poison assez corrosif pour dissoudre la coque d’un pétrolier."}, {"g": "Y", "t": "Il paraît que les navires qui s’aventurent dans les eaux peuplées de Kravarech ne reviennent jamais de leur périple."}, {"g": "Ultra-Soleil", "t": "Les étourdis qui divaguent du côté de chez lui se font chasser à grands jets de poison. Curieusement, il adore Sinistrail."}, {"g": "Ultra-Lune", "t": "Il attend sa proie tapi au milieu des algues, et attaque en crachant un poison si corrosif qu’il peut même dissoudre le métal."}, {"g": "Épée", "t": "Avec son poison capable de dissoudre le métal, il réduit à l’état d’épave les navires-citernes qui pénètrent sur son territoire."}, {"g": "Bouclier", "t": "Il sort la crête sur sa tête à la surface de l’eau et l’expose à la lumière du soleil pour produire de l’énergie draconique."}],
  692: [{"g": "X", "t": "Sa pince projette un jet d’eau sous pression suffisamment puissant pour abattre ses proies en plein vol."}, {"g": "Y", "t": "Il est capable de transformer son corps en canon à eau, grâce à la combustion d’un gaz interne. À bout portant, il peut réduire un rocher en miettes."}, {"g": "Ultra-Soleil", "t": "Sa pince, à la chair délicieuse, tombe parfois. Il se fait alors tout petit et se cache le temps qu’elle repousse."}, {"g": "Ultra-Lune", "t": "Il se déplace en propulsant de l’eau par sa pince droite. Il n’est cependant pas très agile et est incapable de nager droit."}, {"g": "Épée", "t": "S’il perd ses pinces au combat, d’autres repoussent à la place. La chair qu’elles contiennent est un mets très apprécié à Galar."}, {"g": "Bouclier", "t": "Il concentre du gaz dans sa pince droite et le fait exploser pour tirer une rafale d’eau sur ses ennemis, comme une balle de pistolet."}],
  693: [{"g": "X", "t": "Son énorme pince projette de véritables obus d’eau capables de transpercer la coque d’un pétrolier."}, {"g": "Y", "t": "La force de propulsion générée par l’expulsion de l’eau via la tuyère située à l’arrière de sa pince peut lui conférer une vitesse de 60 nœuds."}, {"g": "Ultra-Soleil", "t": "Il aspire de l’eau et la projette sous pression pour attaquer. Le jet est si puissant qu’il perce même d’épaisses plaques d’acier."}, {"g": "Ultra-Lune", "t": "La chair de sa pince droite est très ferme. Les pinces tombées sont vendues à l’étranger comme ingrédients de cuisine."}, {"g": "Épée", "t": "Il projette des obus d’eau sur ses ennemis après les avoir localisés grâce aux antennes situées sur son énorme pince."}, {"g": "Bouclier", "t": "Sa pince droite est un canon pouvant projeter des obus d’eau assez puissants pour couler un navire-citerne."}],
  694: [{"g": "X", "t": "Ce Pokémon vit dans le désert. Il n’a pas besoin de se nourrir, car il est capable d’absorber l’énergie du soleil."}, {"g": "Y", "t": "Les plis de peau de chaque côté de sa tête sont dotés de cellules produisant de l’électricité quand elles sont exposées à la lumière du soleil."}, {"g": "Épée", "t": "Il absorbe les rayons du soleil en dépliant la peau de sa tête pour produire l’électricité nécessaire à ses puissantes capacités Électrik."}, {"g": "Bouclier", "t": "Il peut générer de l’électricité grâce au soleil. Si on le dérange en pleine production d’énergie, cela le stresse et l’affaiblit."}],
  695: [{"g": "X", "t": "L’électricité que produit un seul Iguolta en agitant sa collerette suffit à alimenter un immeuble entier."}, {"g": "Y", "t": "Il augmente sa puissance motrice en stimulant les muscles de ses pattes avec des décharges électriques. Il peut ainsi parcourir 100 m en 5 s."}, {"g": "Épée", "t": "Il était révéré dans un royaume des sables aujourd’hui disparu. Il est arrivé à Galar dans une cargaison de pierres précieuses."}, {"g": "Bouclier", "t": "Lorsqu’il déploie sa collerette pour emmagasiner la lumière du soleil, il génère à lui seul assez d’électricité pour alimenter une grande ville."}],
  696: [{"g": "X", "t": "Ramené à la vie à partir d’un fossile, ce Pokémon très capricieux devient violent à la moindre contrariété."}, {"g": "Y", "t": "Ses énormes mâchoires ont tant de puissance qu’elles peuvent compresser une voiture sans problème. Ce Pokémon vivait il y a 100 millions d’années."}, {"g": "Ultra-Soleil", "t": "Sa mâchoire géante est d’une puissance redoutable. Le Pokémon reconstitué serait légèrement différent de son modèle antique."}, {"g": "Ultra-Lune", "t": "Il est un peu égoïste et aime être le centre d’attention. Il arrive que ses partenaires de jeu finissent avec de graves blessures."}, {"g": "Épée", "t": "Ce Pokémon ancien a été ranimé à partir d’un fossile. Égoïste et violent, il peut détruire n’importe quoi avec son énorme mâchoire."}, {"g": "Bouclier", "t": "Capricieux, il veut toujours être le centre de l’attention. Il peut gravement blesser son Dresseur en essayant de jouer avec lui."}],
  697: [{"g": "X", "t": "Dans les temps anciens, aucun Pokémon ne pouvait rivaliser avec lui. Ses puissantes mâchoires peuvent réduire une épaisse plaque de métal en confettis."}, {"g": "Y", "t": "Il y a 100 millions d’années, ce Pokémon régnait en maître absolu. Personne ne pouvait se mesurer à lui."}, {"g": "Ultra-Soleil", "t": "La reconstitution de Pokémon est un art imparfait. D’aucuns pensent même qu’il était en fait couvert d’une robe semblable à un plumage."}, {"g": "Ultra-Lune", "t": "Il régnait sur le monde en maître incontesté. Sa mâchoire est si puissante qu’il n’a aucun mal à croquer une voiture."}, {"g": "Épée", "t": "Ce Pokémon a vécu il y a 100 millions d’années. Il est très violent, mais sa contenance noble lui donne des airs de royauté."}, {"g": "Bouclier", "t": "Ce Pokémon peut réduire une voiture en miettes d’un seul coup de mâchoire. Il était considéré comme le roi du monde préhistorique."}],
  698: [{"g": "X", "t": "Pokémon ancien, ramené à la vie après la découverte d’une partie de son corps conservée dans la glace pendant 100 millions d’années."}, {"g": "Y", "t": "Ce Pokémon placide vivait dans des contrées au climat froid, loin de la menace d’un violent prédateur comme Rexillius."}, {"g": "Ultra-Soleil", "t": "Amagara vivait jadis dans les terres glacées. On dit que lorsqu’il pousse un cri, une aurore boréale nimbe le ciel nocturne."}, {"g": "Ultra-Lune", "t": "Il a été reconstitué, mais son corps n’est pas adapté aux températures actuelles, ce qui affecte probablement son espérance de vie."}, {"g": "Épée", "t": "Ce Pokémon a été ressuscité à partir d’un fossile. Jadis, il vivait en meute dans des terres froides, où peu de ses prédateurs résidaient."}, {"g": "Bouclier", "t": "Un Pokémon ancien qui s’est éteint. On trouve parfois des spécimens conservés dans la glace."}],
  699: [{"g": "X", "t": "Les cristaux qui parsèment son corps lui permettent de piéger ses ennemis dans la glace en émettant de l’air refroidi à -150 °C."}, {"g": "Y", "t": "En utilisant ses cristaux, il peut créer en un instant un mur de glace pour se protéger des attaques ennemies."}, {"g": "Ultra-Soleil", "t": "Un Dragmara a été retrouvé dans un glacier, en parfait état de conservation, ce qui a fait la une des actualités."}, {"g": "Ultra-Lune", "t": "La température de la surface de son corps est de -150 °C. Ce Pokémon est généralement très calme et très doux."}, {"g": "Épée", "t": "Ce Pokémon a été ressuscité à partir d’un fossile. On raconte qu’une aurore boréale apparaît dans le ciel nocturne quand il hurle à la lune."}, {"g": "Bouclier", "t": "Lorsqu’il se laisse emporter par sa rage, il relâche des bourrasques glacées qui gèlent tout ce qui l’entoure."}],
  700: [{"g": "X", "t": "Pour arrêter le combat, il émet des ondes apaisantes avec ses rubans."}, {"g": "Y", "t": "Il enroule ses rubans sensoriels autour du bras de son Dresseur adoré et chemine paisiblement à ses côtés."}, {"g": "Soleil", "t": "Grâce à ses antennes semblables à des rubans, il peut émettre des ondes neutralisant l’hostilité et ainsi endormir la méfiance de ses proies."}, {"g": "Lune", "t": "Lorsqu’il trouve une proie, il agite ses antennes en forme de rubans pour la distraire. Ensuite, il passe à l’attaque."}, {"g": "Ultra-Soleil", "t": "Une fois le combat entamé, il n’hésite pas une seconde, même contre un Pokémon de type Dragon dix fois plus gros que lui."}, {"g": "Ultra-Lune", "t": "Enrouler l’une de ses antennes en forme de ruban autour du bras de son Dresseur lui permet de connaître ses sentiments."}, {"g": "Épée", "t": "Grâce à ses antennes semblables à des rubans, il peut émettre des ondes neutralisant l’hostilité et ainsi mettre fin aux querelles."}, {"g": "Bouclier", "t": "Un conte de Galar relate la victoire d’un beau Nymphali sur un terrible Pokémon Dragon."}],
  701: [{"g": "X", "t": "Malgré sa petite taille, son intelligence lui permet d’affronter sans trembler de grands Pokémon tels que les Mackogneur ou les Hariyama."}, {"g": "Y", "t": "Il utilise ses ailes pour contrôler avec précision sa posture en vol. Ses attaques aériennes sont difficiles à parer."}, {"g": "Ultra-Soleil", "t": "Il terrasse ses adversaires grâce à sa vitesse, mais se pavane tant avant de lancer sa botte secrète qu’il se retrouve parfois en difficulté."}, {"g": "Ultra-Lune", "t": "Il combat ses adversaires en sautillant pour se retrouver dans leur angle mort. Il maîtrise de formidables techniques de clés articulaires."}, {"g": "Épée", "t": "Il utilise des tactiques basées sur son agilité pour fatiguer son adversaire, et termine le combat par une magnifique frappe décisive."}, {"g": "Bouclier", "t": "Il prend toujours la pose avant de donner le coup de grâce à son adversaire. Certains en profitent pour contre-attaquer."}],
  702: [{"g": "X", "t": "Ses moustaches lui servent d’antennes, et lui permettent d’envoyer et de recevoir des signaux pour communiquer à distance avec ses congénères."}, {"g": "Y", "t": "Il utilise sa queue pour pomper l’énergie des centrales électriques ou pour se brancher sur les prises des maisons. Ses moustaches envoient des décharges."}, {"g": "Ultra-Soleil", "t": "Il s’introduit chez les gens pour voler l’électricité via les prises de courant. On sait qui blâmer en cas de facture d’électricité trop élevée !"}, {"g": "Ultra-Lune", "t": "Les moustaches du haut lui servent de capteurs pour inspecter son environnement ; celles du bas lui permettent de décharger de l’électricité."}, {"g": "Épée", "t": "Il capte les ondes émises par ses congénères avec ses moustaches. Cela lui permet de savoir où trouver de la nourriture ou de l’électricité."}, {"g": "Bouclier", "t": "Puisqu’il a du mal à générer sa propre électricité, il en vole aux autres Pokémon Électrik ou via les prises de courant."}],
  703: [{"g": "X", "t": "Ce Pokémon vient des profondeurs de la terre, où la chaleur et la pression sont intenses. La pierre qui orne sa tête émet de l’énergie."}, {"g": "Y", "t": "Il sommeille sous terre depuis son apparition, il y a plusieurs centaines de millions d’années. On le découvre parfois en creusant des cavernes."}, {"g": "Soleil", "t": "Les Strassie sont nés sous la terre, à de hautes pressions et températures. Ils se défendent en lançant des lasers depuis leurs cristaux."}, {"g": "Lune", "t": "Il ne s’agit pas d’un Pokémon particulièrement rare, mais son allure strass et paillettes attire les gens."}, {"g": "Ultra-Soleil", "t": "Au plus profond de la terre se trouverait un royaume de pierres précieuses où vivent la reine des Strassie et son peuple."}, {"g": "Ultra-Lune", "t": "Pour éviter que les pierres précieuses de leur corps ne ternissent, les Strassie se les polissent mutuellement avec leurs moustaches."}, {"g": "Épée", "t": "Ce Pokémon élimine les ennemis qui l’attaquent en projetant un laser d’énergie généré par les pierres précieuses incrustées dans son corps."}, {"g": "Bouclier", "t": "On raconte qu’il existerait quelque part dans le monde un filon regorgeant de Strassie, qui abriterait également leur reine."}],
  704: [{"g": "X", "t": "C’est le plus faible de tous les Pokémon Dragon. Pour éviter que son corps ne se dessèche, il recherche les lieux humides et ombragés."}, {"g": "Y", "t": "Son corps est recouvert d’une membrane gluante, aussi les coups des ennemis glissent sur lui sans lui faire le moindre mal."}, {"g": "Soleil", "t": "C’est le plus faible de tous les Pokémon Dragon. Sa peau doit rester hydratée pour respirer, c’est pourquoi il préfère vivre tapi dans l’ombre."}, {"g": "Lune", "t": "Son corps est recouvert d’une membrane gluante protectrice, mais pleine de germes. Lavez-vous les mains si vous le touchez !"}, {"g": "Ultra-Soleil", "t": "Ses cornes lui permettent d’inspecter les alentours. Elles sont si sensibles que tout son corps se fige si on les pince."}, {"g": "Ultra-Lune", "t": "Son corps est majoritairement composé d’eau. Il meurt s’il se dessèche, aussi préfère-t-il vivre tapi dans l’ombre."}, {"g": "Épée", "t": "Son corps est principalement composé d’eau. S’il se déshydrate, il devient tout rabougri. C’est le plus faible des Pokémon Dragon."}, {"g": "Bouclier", "t": "Ses cornes sont des organes sensoriels qui lui permettent de se cacher quand il détecte des ennemis. C’est grâce à cela qu’il vit toujours."}],
  705: [{"g": "X", "t": "Il repousse ses ennemis en sécrétant un fluide qui dissout tout ce qu’il touche. Suite à une dégénérescence de ses yeux, il est aveugle."}, {"g": "Y", "t": "Ses quatre cornes constituant un radar extrêmement puissant, il n’a besoin ni de nez ni d’oreilles pour percevoir les sons et les odeurs."}, {"g": "Soleil", "t": "Comme il a du mal à distinguer ses alliés de ses proies, la faim peut parfois le pousser à asperger ses amis de son solvant."}, {"g": "Lune", "t": "Comme il n’a pas de dent, il sécrète un solvant dont il asperge ses proies pour les liquéfier et les boire en smoothie."}, {"g": "Ultra-Soleil", "t": "Il se déplace en rampant lentement. Ses organes et son cerveau se trouvent dans sa protubérance dorsale en forme de spirale."}, {"g": "Ultra-Lune", "t": "Son corps est recouvert d’un mucus capable de faire fondre n’importe quoi. Pensez à mettre des gants adaptés si vous voulez le toucher !"}, {"g": "Épée", "t": "Étant donné sa faiblesse, c’est uniquement grâce à son fluide pouvant tout dissoudre qu’il a échappé à une extinction quasi certaine."}, {"g": "Bouclier", "t": "Son petit cerveau est caché dans la bosse qui est sur son dos. Il ne pense pas à grand-chose, si ce n’est à se nourrir et à fuir devant ses ennemis."}],
  706: [{"g": "X", "t": "Ce Pokémon Dragon peu farouche aime faire la fête à son Dresseur adoré, le couvrant au passage de sa bave collante."}, {"g": "Y", "t": "Il attaque grâce à ses cornes extensibles. Ses coups sont aussi puissants que ceux de 100 boxeurs professionnels réunis."}, {"g": "Soleil", "t": "Ce Pokémon adore la compagnie humaine. Si son Dresseur ne lui donne pas assez d’amour, il pleure à grosses larmes visqueuses."}, {"g": "Lune", "t": "Ceux qui l’importunent en le pensant inoffensif peuvent vite se retrouver du mauvais côté de ses cornes et goûter de sa puissante queue."}, {"g": "Ultra-Soleil", "t": "Très câlin, ce Pokémon a tendance à se frotter aux gens auxquels il s’attache avec son corps visqueux. Dresseurs de Muplodocus, tenez bon."}, {"g": "Ultra-Lune", "t": "Une épaisse couche de graisse se trouve sous sa peau visqueuse et lui permet d’encaisser les attaques ennemies."}, {"g": "Épée", "t": "Il arrive qu’il ne comprenne pas les ordres de son Dresseur et qu’il le regarde d’un air ahuri. Cette réaction adorable l’a rendu populaire."}, {"g": "Bouclier", "t": "Il attaque à l’aide de ses longues cornes. Ses coups sont cent fois plus puissants que ceux d’un champion poids lourds de boxe."}],
  707: [{"g": "X", "t": "Ce Pokémon collectionne les clés qu’il agite devant ses ennemis pour les intimider."}, {"g": "Y", "t": "Comme il ne se sépare jamais d’une clé qu’il trouve à son goût, les gens lui confient celle de leurs coffres, afin d’éviter de se faire voler."}, {"g": "Soleil", "t": "Malgré son caractère paisible, ce Pokémon ne peut s’empêcher de se faufiler dans les foyers pour en voler les clés, qu’il aime collectionner."}, {"g": "Lune", "t": "Il insère l’appendice situé sur sa tête dans les interstices en métal afin d’en extraire les ions. Il collectionne les clés pour une raison inconnue."}, {"g": "Ultra-Soleil", "t": "Nul ne sait pourquoi il collectionne les clés, mais il est aux anges dès qu’on lui en donne une. Il n’accepte toutefois que les passe-partout."}, {"g": "Ultra-Lune", "t": "Il vivait autrefois dans les mines, mais quand les minéraux dont il se délectait se sont faits plus rares, il a migré vers les villages."}, {"g": "Épée", "t": "Ce Pokémon collectionne les clés. Si on lui en confie une particulièrement importante, il la protègera coûte que coûte."}, {"g": "Bouclier", "t": "Il absorbe les ions métalliques avec l’appendice sur sa tête. Il paraît qu’il ressemble à une clé car il tient à imiter cet objet qu’il aime tant."}],
  708: [{"g": "X", "t": "Ce Pokémon apparaît lorsqu’un esprit possède un arbre en décomposition. Il vit dans les forêts où les humains n’osent pas s’aventurer."}, {"g": "Y", "t": "D’après la légende, cette espèce de Pokémon aurait vu le jour quand des âmes d’enfants perdus dans la forêt auraient possédé des souches d’arbres."}, {"g": "Soleil", "t": "Ce Pokémon est une souche d’arbre possédée par l’âme d’un enfant mort en forêt. Son cri ressemble à des pleurs."}, {"g": "Lune", "t": "Une légende raconte qu’il est possible de créer une panacée en infusant les feuilles vertes qui poussent sur ses branches."}, {"g": "Ultra-Soleil", "t": "Il imite la voix d’un enfant pour inciter les gens à se perdre au plus profond des bois. Il espère ainsi se faire de nouveaux amis."}, {"g": "Ultra-Lune", "t": "Il est né lorsqu’une âme est venue se loger dans une souche. Les infusions de ses feuilles vertes permettent de guérir toutes les maladies."}, {"g": "Épée", "t": "Ce Pokémon prend vie lorsque l’âme d’un enfant disparu en forêt prend possession d’une souche d’arbre."}, {"g": "Bouclier", "t": "Il imite des cris d’enfants pour pousser les adultes à venir se perdre au plus profond de la forêt."}],
  709: [{"g": "X", "t": "Commande aux autres arbres. Il emprisonne jusqu’à la fin de leurs jours les humains qui abîment la forêt."}, {"g": "Y", "t": "Ses racines sont un véritable système nerveux qui lui permet de contrôler les arbres de la forêt. Il se montre très gentil envers les Pokémon vivant dans son écorce."}, {"g": "Soleil", "t": "On raconte que ce Pokémon mange tous ceux qui s’en prennent à sa forêt. Il est toutefois très gentil avec ses voisins sylvains."}, {"g": "Lune", "t": "Grâce à ses racines, il contrôle les arbres de la forêt où il a élu refuge, et maudit quiconque a le malheur de les abattre."}, {"g": "Ultra-Soleil", "t": "Les bûcherons n’entrent pas dans les bois sans Pokémon Feu, effrayés par cette créature considérée comme un fantôme sylvestre."}, {"g": "Ultra-Lune", "t": "Il contrôle les arbres environnants grâce aux racines qui poussent au bout de ses pieds, et attaque quiconque saccage la forêt."}, {"g": "Épée", "t": "Les bûcherons qui viennent couper des arbres en forêt ont peur d’être dévorés par Desséliande. Il est gentil avec les Pokémon habitant les bois."}, {"g": "Bouclier", "t": "Il étire les fines racines de ses pieds pour établir une connexion avec les autres arbres de la forêt et ainsi les contrôler."}],
  710: [{"g": "X", "t": "Ce Pokémon est né du mariage d’un esprit piégé dans le monde des vivants et d’une citrouille. Il commence à s’animer au coucher du soleil."}, {"g": "Y", "t": "Il paraît qu’il accompagne les âmes des défunts jusque dans l’au-delà, pour qu’elles puissent goûter au repos éternel."}, {"g": "Épée", "t": "Les âmes errantes de ce monde s’introduisent dans son corps pour rejoindre l’au-delà."}, {"g": "Bouclier", "t": "Il peut manipuler les humains et les Pokémon en les hypnotisant grâce à la lumière qui filtre par les trous de son ventre en forme de citrouille."}],
  711: [{"g": "X", "t": "Les nuits de nouvelle lune, ce Pokémon erre dans les rues en chantant d’une voix lugubre. Ceux qui l’entendent sont maudits."}, {"g": "Y", "t": "Il enserre ses proies dans ses bras, semblables à de longues mèches de cheveux. Il se délecte de leur souffrance en chantonnant gaiement."}, {"g": "Épée", "t": "Les lugubres lamentations nocturnes de son ventre seraient en fait les cris de souffrance d’âmes en peine, résonnant depuis l’au-delà."}, {"g": "Bouclier", "t": "Les soirs de nouvelle lune, il frappe aux portes des maisons. Si quelqu’un a le malheur de lui ouvrir, il l’emporte aussitôt dans l’au-delà."}],
  712: [{"g": "X", "t": "La glace qui couvre son corps bloque les attaques ennemies. Si elle se fissure, il la reconstitue immédiatement en soufflant de l’air glacé."}, {"g": "Y", "t": "Il gèle ses ennemis d’une bourrasque à -100 °C. Il vit en troupeau avec ses congénères, dans les neiges éternelles des hautes montagnes."}, {"g": "Épée", "t": "Grâce à son souffle glacé à - 100 °C, il peut geler l’humidité dans l’air et se façonner une carapace de glace."}, {"g": "Bouclier", "t": "Il vit dans les régions les plus froides, agrippé aux Séracrawl. Il gèle ses pattes sur leur dos pour se maintenir en place."}],
  713: [{"g": "X", "t": "Son immense corps recouvert de glace est aussi solide que de l’acier. Quand il se déplace, il écrase tout qui se trouve sur son passage."}, {"g": "Y", "t": "Quand on le voit transportant les petits Grelaçon qui vivent sur son dos, il y a une ressemblance certaine avec les véhicules déplaçant les fusées."}, {"g": "Rubis Oméga", "t": "Son immense corps recouvert de glace est aussi solide que de l’acier. Quand il se déplace, il écrase tout ce qui se trouve sur son passage."}, {"g": "Épée", "t": "Il sillonne les eaux glacées des pôles en se mêlant aux icebergs, une foule de Grelaçon collée à son dos."}, {"g": "Bouclier", "t": "Les crevasses sur son dos s’approfondissent au cours de la journée, mais se comblent de nouveau pendant la nuit."}],
  714: [{"g": "X", "t": "Il apprécie les grottes les plus sombres. Ses grandes oreilles lui permettent de générer des ultrasons d’une fréquence de 200 000 Hz."}, {"g": "Y", "t": "Les ultrasons à 200 000 Hz qu’il émet suffiraient à rendre groggy le plus chevronné des lutteurs."}, {"g": "Ultra-Soleil", "t": "Il adore les fruits et, en véritable gourmet, il ne mange que ceux qui sont bien mûrs. Il utilise ses ultrasons pour déterminer le degré de maturité."}, {"g": "Ultra-Lune", "t": "Il vole à la recherche de fruits à manger. Il peut déterminer si un fruit est mûr ou non grâce à ses ultrasons."}, {"g": "Épée", "t": "À la tombée de la nuit, il quitte la grotte où il réside et s’envole à la recherche de fruits mûrs avec ses ultrasons."}, {"g": "Bouclier", "t": "Il peut contrôler des ondes à n’importe quelle fréquence du spectre. Même les plus grands Pokémon ne peuvent supporter ses ultrasons."}],
  715: [{"g": "X", "t": "Les nuits sans lune, il quadrille le ciel à la recherche d’une proie. Dans l’obscurité, aucun Pokémon ne peut rivaliser avec lui."}, {"g": "Y", "t": "Il peut littéralement pulvériser de gros rochers grâce aux ultrasons émis par ses oreilles. Il surgit des ténèbres pour attaquer par surprise."}, {"g": "Ultra-Soleil", "t": "D’ordinaire violent, il vous mange littéralement dans la main si vous lui donnez des fruits mûrs, son mets favori."}, {"g": "Ultra-Lune", "t": "Ce Pokémon sanguinaire attaque tout ce qui entre dans son champ de vision avec ses ultrasons capables de pulvériser des rochers."}, {"g": "Épée", "t": "Il n’hésite pas à anéantir ses pauvres adversaires qui se retrouvent sans défense dans les ténèbres. Il est d’une nature cruelle et impulsive."}, {"g": "Bouclier", "t": "Il plane dans les ténèbres, blessant ses ennemis à coups d’ultrasons pouvant briser des rochers avant de les achever de ses crocs acérés."}],
  716: [{"g": "X", "t": "On dit que ce Pokémon immortel peut offrir ses forces vitales. Il a été ranimé après avoir passé 1 000 ans endormi sous la forme d’un arbre."}, {"g": "Y", "t": "D’après la légende, quand ses bois brillent de sept couleurs, cela signifie qu’il prodigue la vie éternelle."}],
  717: [{"g": "X", "t": "Lorsque les plumes de sa queue et de ses ailes sont déployées et virent au rouge, ce Pokémon légendaire absorbe l’énergie vitale de ce qui l’entoure."}, {"g": "Y", "t": "Quand il sent que la fin de sa vie est proche, il aspire la force vitale des êtres vivants et retourne à l’état de cocon."}],
  718: [{"g": "X", "t": "Lorsque l’écosystème de Kalos est menacé, ce Pokémon apparaît et utilise son mystérieux pouvoir."}, {"g": "Y", "t": "Il paraît qu’il vit au fond d’une grotte, d’où il surveillerait les personnes qui détruisent l’écosystème."}, {"g": "Soleil", "t": "La forme que Zygarde prend lorsqu’il rassemble 50 % de ses Cellules. Il désintègre sans merci tout ennemi qui ose s’opposer à lui."}, {"g": "Lune", "t": "Ce Pokémon surveille l’équilibre de l’écosystème en permanence. Si l’on en croit la rumeur, il aurait un grand pouvoir caché..."}, {"g": "Ultra-Soleil", "t": "La forme que Zygarde prend lorsqu’il rassemble 50 % de ses Cellules. Sa mission est de surveiller l’écosystème."}, {"g": "Ultra-Lune", "t": "Ce Pokémon serait capable de prendre une forme encore plus puissante quand il se bat contre un ennemi qui menace l’écosystème."}],
  719: [{"g": "X", "t": "Ce Pokémon est une mutation spontanée de Strassie. Son corps rose et luisant est d’une beauté incomparable."}, {"g": "Y", "t": "Il peut créer une multitude de diamants en un instant en serrant ses mains, simplement en compressant les molécules de carbone contenues dans l’air."}],
  720: [{"g": "X", "t": "Ce fauteur de troubles est doté d’anneaux qui déforment l’espace et lui permettent d’expédier au loin n’importe quel objet."}, {"g": "Y", "t": "Il a la faculté de téléporter les choses en les faisant passer au travers de ses anneaux. Il envoie les objets qui lui plaisent dans une cachette connue de lui seul."}, {"g": "Rubis Oméga", "t": "Il possède une puissance considérable sous son apparence véritable. Une légende raconte qu’il désirait si fort un trésor caché dans un château qu’il déroba l’édifice tout entier."}, {"g": "Saphir Alpha", "t": "On raconte que grâce à ses six anneaux et ses six énormes bras, il est capable de dérober tout ce qui lui plaît. Mais son pouvoir a été scellé, et il a été réduit à l’état d’un être minuscule."}],
  721: [{"g": "X", "t": "Il est capable de générer un nuage de vapeur pour se cacher. Il vit dans des montagnes inhabitées."}, {"g": "Y", "t": "Il évacue la vapeur qui s’accumule à l’intérieur de son corps par les bras situés sur son dos. Ce jet est assez puissant pour raser des montagnes."}],
  722: [{"g": "Soleil", "t": "Ce Pokémon ne baisse jamais sa garde. Pendant la journée, il accumule de l’énergie par photosynthèse, pour mieux agir la nuit venue."}, {"g": "Lune", "t": "Il s’approche de ses ennemis en glissant dans les airs sans faire le moindre bruit, puis leur assène de puissants coups de patte."}, {"g": "Ultra-Soleil", "t": "Il attaque en tirant des plumes acérées. La force de ses coups de patte est également redoutable."}, {"g": "Ultra-Lune", "t": "Il se sent à l’aise dans les endroits sombres et étroits. Il se sert parfois de la poche ou du sac de son Dresseur comme d’un nid."}, {"g": "Épée", "t": "En vol, il attaque en lançant ses plumes aiguisées comme des lames. Au corps à corps, il se bat en donnant de violents coups de patte."}, {"g": "Bouclier", "t": "Pendant la journée, il emmagasine de l’énergie par photosynthèse. La nuit, il plane silencieusement à la recherche de proies."}],
  723: [{"g": "Soleil", "t": "Légèrement vaniteux, il aime prendre soin de ses ailes quand il en a le temps. Il refuse parfois de se battre si ses plumes sont trop sales."}, {"g": "Lune", "t": "Il lance des plumes aussi effilées que des lames de rasoir pour abattre ennemis et proies. Il touche dans le mille presque à chaque fois."}, {"g": "Ultra-Soleil", "t": "Ce narcissique est un amoureux de la propreté. Il refuse parfois d’obéir si l’on ne prend pas grand soin de ses plumes."}, {"g": "Ultra-Lune", "t": "Il détecte très facilement la présence d’ennemis à proximité, et élimine ceux qui se trouvent dans son dos en tirant des plumes acérées."}, {"g": "Épée", "t": "Il vise les points faibles de ses ennemis et les frappe successivement de ses plumes affûtées comme des couteaux."}, {"g": "Bouclier", "t": "Il prend grand soin de son plumage, s’assurant ainsi d’avoir une apparence impeccable et des plumes aiguisées à souhait."}],
  724: [{"g": "Soleil", "t": "Les plumes de ses ailes lui servent de flèches. Sa précision au tir est si grande qu’il peut atteindre un gravillon à 100 m."}, {"g": "Lune", "t": "Malgré sa grande vigilance et son air posé, il a tendance à céder à la panique dès qu’il est pris de court."}, {"g": "Ultra-Soleil", "t": "Les plumes de ses ailes lui servent de flèches. Quand il doit à tout prix toucher sa cible, il tire sur les lianes de son cou pour se concentrer."}, {"g": "Ultra-Lune", "t": "Il est capable de décocher ses plumes sur son ennemi en un dixième de seconde, s’assurant ainsi la victoire en un clin d’œil."}, {"g": "Épée", "t": "Il décoche les plumes acérées de ses ailes comme des flèches. Il ne rate jamais sa cible."}, {"g": "Bouclier", "t": "Il décoche ses plumes acérées en un dixième de seconde. Sa victime n’a pas le temps de le voir agir qu’elle est déjà grièvement touchée."}],
  725: [{"g": "Soleil", "t": "Les poils qu’il avale pendant sa toilette brûlent et forment une flamme dans son ventre. Celle-ci change selon la façon dont il la recrache."}, {"g": "Lune", "t": "Ce Pokémon n’exprime jamais ses émotions. Il aime la vie en solitaire, et n’accorde pas sa confiance au premier venu."}, {"g": "Ultra-Soleil", "t": "Laissez ce Pokémon respirer ou il se renfermera sur lui-même. Même s’il devient affectueux, allez-y doucement avec les caresses."}, {"g": "Ultra-Lune", "t": "Il renouvelle son pelage deux fois par an. Quand arrive la période de sa mue, il met le feu à son ancienne fourrure."}, {"g": "Épée", "t": "Dès qu’il a un instant, il fait sa toilette. Il déclenche ses attaques Feu en enflammant les poils qu’il a avalés en se léchant."}, {"g": "Bouclier", "t": "Quiconque essaie de le caresser avant d’avoir gagné sa confiance s’expose à de sérieuses griffures."}],
  726: [{"g": "Soleil", "t": "Il porte à son cou une cloche de feu. Lorsqu’il crache des flammes, cette dernière se met à tinter bruyamment."}, {"g": "Lune", "t": "Il est très fier de ses pattes avant musclées, et ne se gêne pas pour le montrer en tordant des barres de fer d’un seul coup de poing."}, {"g": "Ultra-Soleil", "t": "Il sait être affectueux avec son Dresseur, mais il ne connaît pas sa force. Câlinez-le, et vous vous retrouverez couvert de griffures."}, {"g": "Ultra-Lune", "t": "Quand la mèche sur sa tête est dressée, c’est qu’il se porte bien. Dans le cas contraire, elle est plate et tombe vers l’arrière."}, {"g": "Épée", "t": "La poche à feu située à la base de son cou gagne en température pendant les combats et émet un bruit semblable à un grelot."}, {"g": "Bouclier", "t": "Quand il fait face à un adversaire redoutable, il redouble de combativité et la puissance calorifère de sa clochette augmente."}],
  727: [{"g": "Soleil", "t": "Un Pokémon brutal qui n’en fait qu’à sa tête. Selon son humeur du moment, il lui arrive d’ignorer sciemment les ordres de son Dresseur."}, {"g": "Lune", "t": "Après avoir asséné une pluie de coups de pied et de poing à son adversaire, il l’asperge de flammes ardentes sortant de son nombril."}, {"g": "Ultra-Soleil", "t": "Un Pokémon brutal qui n’en fait qu’à sa tête. Selon son humeur du moment, il lui arrive parfois d’ignorer sciemment les ordres de son Dresseur."}, {"g": "Ultra-Lune", "t": "Les flammes autour de ses hanches brûlent d’une ardeur redoublée quand sa combativité s’embrase."}, {"g": "Épée", "t": "Les flammes qui émanent de son nombril dépassent les 2 000 °C. Il n’est jamais aussi à l’aise que lorsque tous les coups sont permis."}, {"g": "Bouclier", "t": "Bien qu’il soit parfois brutal, il sait aussi se montrer attentionné en venant en aide aux petits Pokémon."}],
  728: [{"g": "Soleil", "t": "Connu pour son tempérament de battant, il rassemble l’eau de son corps au bout de son museau en un ballon qu’il projette sur l’ennemi."}, {"g": "Lune", "t": "Ce Pokémon fabrique des ballons remplis d’eau pour se battre. Il ne peut produire un gros ballon qu’au prix d’un entraînement rigoureux."}, {"g": "Ultra-Soleil", "t": "À force de s’entraîner quotidiennement, les ballons qu’il gonfle avec son nez grossissent de jour en jour."}, {"g": "Ultra-Lune", "t": "Il monte sur un ballon d’eau élastique pour effectuer de grands sauts. Son style de combat est on ne peut plus acrobatique."}, {"g": "Épée", "t": "Il fabrique des ballons élastiques pour se battre. Ils blessent l’ennemi en explosant à son contact."}, {"g": "Bouclier", "t": "Il s’entraîne sans relâche tous les jours pour réussir à créer de gros ballons de bonne qualité."}],
  729: [{"g": "Soleil", "t": "Danseur hors pair, il produit des ballons d’eau à la chaîne afin d’éclabousser l’adversaire lors d’un impitoyable ballet funeste."}, {"g": "Lune", "t": "Il est très soucieux du bien-être des autres et n’hésite pas à exécuter une petite danse s’il sent que son Dresseur a le moral à zéro."}, {"g": "Ultra-Soleil", "t": "Il est tout excité quand il est témoin d’une danse qu’il ne connaît pas. Il s’entraîne alors comme un forcené jusqu’à la maîtriser à la perfection."}, {"g": "Ultra-Lune", "t": "Il utilise ses pattes pour lancer des ballons d’eau sur ses ennemis. Les ballons explosent au moment de l’impact."}, {"g": "Épée", "t": "Il esquive les attaques de ses adversaires avec ses légers pas de danse, puis leur assène une rafale de coups avec ses ballons."}, {"g": "Bouclier", "t": "Les soirs où la mer est calme, il danse avec ses congénères au son des chants d’Oratoria, le chef du groupe."}],
  730: [{"g": "Soleil", "t": "Il contrôle ses ballons d’eau par son chant, dont la mélodie, apprise auprès de ses semblables, se transmet de génération en génération."}, {"g": "Lune", "t": "Son chant est son principal atout en combat. Son Dresseur devra donc veiller à tout prix à la bonne santé de ses cordes vocales."}, {"g": "Ultra-Soleil", "t": "Pour lui, le combat est une performance artistique. Il chante et danse de toute son âme pour abattre ses proies."}, {"g": "Ultra-Lune", "t": "Surnommé « la diva », il offre un spectacle enchanteur lorsqu’il dirige un chœur composé de ses congénères à la lumière de la lune."}, {"g": "Épée", "t": "Il manie ses ballons d’eau avec les ondes sonores qu’il émet. Celles-ci ressemblent à un chant céleste et mélodieux."}, {"g": "Bouclier", "t": "Les combats sont une véritable performance artistique, pour lui. Les spectateurs sont charmés par son chant et la danse de ses ballons."}],
  731: [{"g": "Soleil", "t": "Il creuse les arbres à raison de seize coups de bec par seconde. Le trou creusé lui sert ensuite à stocker des provisions ou à faire son nid."}, {"g": "Lune", "t": "Il se nourrit essentiellement de fruits, dont il conserve les pépins dans son bec pour en canarder ses ennemis, telle une mitraillette."}, {"g": "Ultra-Soleil", "t": "On peut deviner son état d’esprit et de santé en étudiant le rythme auquel il tape contre les arbres avec son bec dur."}, {"g": "Ultra-Lune", "t": "Son cou fin renferme des muscles étonnamment puissants. Il tape contre les arbres à raison de seize coups de bec par seconde."}],
  732: [{"g": "Soleil", "t": "Il garde toujours dans son bec les pépins des fruits qu’il mange, ce qui lui permet de faire feu dès qu’un ennemi se présente."}, {"g": "Lune", "t": "En déformant son bec, il peut produire une ribambelle de sons différents, plus bruyants les uns que les autres. Le cauchemar des voisins."}, {"g": "Ultra-Soleil", "t": "Ce Pokémon est capable de produire plus de cent sons différents en recourbant le bout de son bec."}, {"g": "Ultra-Lune", "t": "Il crache violemment les noyaux des Baies qu’il a mangées. Ils s’éparpillent au sol et donnent naissance à de nouvelles plantes."}],
  733: [{"g": "Soleil", "t": "Pendant le combat, son bec chauffe et dépasse allègrement les 100 °C. Ses adversaires repartent généralement avec de graves brûlures."}, {"g": "Lune", "t": "Il fait exploser ses gaz digestifs pour propulser les pépins qu’il a dans le bec, avec une force capable de réduire en miettes de gros rochers."}, {"g": "Ultra-Soleil", "t": "Ils communiquent entre eux en se frappant mutuellement sur le bec. La force et la cadence des coups en disent long sur leur état d’esprit."}, {"g": "Ultra-Lune", "t": "Les couples de Bazoucan sont réputés pour leur harmonie. On en amène souvent aux mariages pour porter bonheur aux jeunes époux."}],
  734: [{"g": "Soleil", "t": "Avec ses crocs acérés, il ne peut s’empêcher de mordre tout ce qui bouge. Il fut introduit à Alola il y a longtemps, depuis une autre région."}, {"g": "Lune", "t": "Il furète du matin au soir en quête de nourriture. La nuit, exténué, il tombe comme une brique et s’endort sur place."}, {"g": "Ultra-Soleil", "t": "Son estomac occupe la plus grande partie de son long corps. Le Dresseur de ce gros mangeur doit prévoir un budget nourriture conséquent."}, {"g": "Ultra-Lune", "t": "Il mange de tout, mais aime particulièrement les proies fraîches, voire encore vives. Il erre sur les routes à leur recherche."}],
  735: [{"g": "Soleil", "t": "Lorsqu’il est sur les traces d’une proie, ce Pokémon n’est pas du genre à abandonner. Sauf le soir, lorsqu’il tombe de sommeil."}, {"g": "Lune", "t": "Il est accro au goût des Rattata et Rattatac, mais n’en croise pas beaucoup car ceux-ci sont nocturnes. Heureusement, il sait rester patient."}, {"g": "Ultra-Soleil", "t": "À l’origine, on ne le trouvait pas à Alola, mais il y a été introduit il y a bien longtemps pour faire face à la prolifération de Rattata."}, {"g": "Ultra-Lune", "t": "D’un naturel très patient, il ne peut toutefois s’empêcher de bondir sur son plat favori, Rattata, s’il en voit un."}],
  736: [{"g": "Soleil", "t": "Il creuse l’écorce des arbres avec ses robustes mandibules pour en siroter la sève. Il vit en temps normal dans le sol."}, {"g": "Lune", "t": "Bien souvent, il se rend là où vivent les Pokémon Électrik, afin de se prémunir des attaques des Pokémon oiseaux."}, {"g": "Ultra-Soleil", "t": "Larvibule n’aime pas les intrus, alors ne mettez pas la main dans son nid, sous peine de vous faire mordre !"}, {"g": "Ultra-Lune", "t": "Il crache un fil gluant pour empêtrer ses ennemis. Une fois immobilisés, il les attaque en les mordant de ses puissantes mandibules."}, {"g": "Épée", "t": "Ses mandibules peuvent briser de très grosses branches. Même Minisange, son ennemi naturel, s’enfuit à tire-d’aile devant lui."}, {"g": "Bouclier", "t": "Il creuse son terrier dans le sol de la forêt avec ses grandes mandibules. Il raffole de la sève sucrée."}],
  737: [{"g": "Soleil", "t": "Avec son corps capable de stocker l’électricité comme une batterie, il a déjà sauvé la mise à plus d’un campeur peu prévoyant."}, {"g": "Lune", "t": "Son processus de digestion produit de l’électricité, qui est immédiatement stockée dans une poche prévue à cet effet."}, {"g": "Ultra-Soleil", "t": "Il passe son temps à manger du terreau, tapi sans bouger sous les feuilles mortes. Gare à la décharge si vous lui marchez dessus !"}, {"g": "Ultra-Lune", "t": "Sa solide carapace lui sert de protection en cas d’attaque. Si un ennemi s’acharne, il riposte avec une décharge électrique."}, {"g": "Épée", "t": "Il est bien protégé par sa robuste carapace, et se défend en générant un courant électrique au bout de ses mandibules."}, {"g": "Bouclier", "t": "Il possède une poche dans laquelle il emmagasine l’électricité qu’il produit en digérant des feuilles mortes."}],
  738: [{"g": "Soleil", "t": "Il virevolte dans tous les sens, guettant la faille pour frapper. Il concentre l’électricité dans ses grandes mandibules pour foudroyer l’ennemi."}, {"g": "Lune", "t": "Il possède un organe spécial pouvant produire de l’électricité. Les Pokémon oiseaux ne font pas le poids face à son rayon électrique."}, {"g": "Ultra-Soleil", "t": "Il possède un organe électrogène sur le ventre. Il concentre de l’énergie dans ses mandibules avant de libérer une puissante décharge."}, {"g": "Ultra-Lune", "t": "Il déroute l’ennemi avec ses pirouettes acrobatiques, puis profite de sa surprise pour l’attaquer grâce à un rayon électrique."}, {"g": "Épée", "t": "L’électricité qu’il produit dans son ventre s’accumule dans ses larges mandibules. Il la libère sous forme d’un rayon puissant."}, {"g": "Bouclier", "t": "S’il emporte un Chrysapile en tant que batterie de secours, il peut tirer une salve de rayons électriques extrêmement puissants en plein vol."}],
  739: [{"g": "Soleil", "t": "Il protège ses points faibles avec ses pinces en guettant le moment propice pour riposter. Il crache de l’écume lorsqu’il tombe K.O."}, {"g": "Lune", "t": "Ses pinces se décrochent lorsqu’il s’en sert trop pour frapper, mais repoussent heureusement aussitôt. Leur chair est fine et délicieuse."}, {"g": "Ultra-Soleil", "t": "Ses robustes pinces sont aussi efficaces pour l’attaque que pour la défense. Les combats de Crabagarre ressemblent à des matchs de boxe."}, {"g": "Ultra-Lune", "t": "Il grimpe parfois sur un Noadkoko qu’il a pris pour un cocotier. Il se fait alors éjecter puis piétiner par le Noadkoko courroucé."}],
  740: [{"g": "Soleil", "t": "Il rêvait d’atteindre le sommet d’un pic enneigé, mais s’est égaré en chemin. Il a dû évoluer pour survivre au froid et a acquis un pelage fourni."}, {"g": "Lune", "t": "Il distribue les coups de pince au petit bonheur la chance. En dernier recours, il les décroche et les envoie telles des roquettes."}, {"g": "Ultra-Soleil", "t": "Il concentre le froid dans ses pinces avant de frapper. Ses coups sont suffisamment puissants pour réduire un épais mur de glace en morceaux."}, {"g": "Ultra-Lune", "t": "Agir ou réfléchir ? Crabominable choisit de frapper ! On raconte qu’il serait déjà parvenu à repousser une avalanche à coups de pince."}],
  741: [{"g": "Soleil", "t": "Il réunit ses ailes pour générer du feu. Sa chorégraphie envoûtante noie l’ennemi sous un torrent de flammes."}, {"g": "Lune", "t": "Après avoir bu du Nectar Rouge, Plumeline se lance dans une ardente danse qui consume le cœur de ses ennemis."}, {"g": "Ultra-Soleil", "t": "Il envoûte ses ennemis avec une danse fougueuse, et profite de leur inattention pour les noyer sous un torrent de flammes."}, {"g": "Ultra-Lune", "t": "Un Plumeline ayant bu du Nectar Rouge. D’un naturel passionné, il brûle de rage quand son Dresseur se trompe d’ordre."}],
  742: [{"g": "Soleil", "t": "Il se nourrit du nectar et du pollen des fleurs. Ayant la capacité de percevoir l’aura des choses, il sait quelles fleurs vont bientôt éclore."}, {"g": "Lune", "t": "Ils volettent gaiement en nombre au-dessus de la tête de certaines personnes dont l’aura s’apparenterait à celle d’une fleur."}, {"g": "Ultra-Soleil", "t": "Il aime le nectar et le pollen, et se dispute ces denrées avec Papilusion dans les champs de fleurs."}, {"g": "Ultra-Lune", "t": "Il perçoit l’aura des êtres vivants, ce qui lui permet de se jouer de son adversaire en prévoyant et en anticipant ses mouvements."}, {"g": "Épée", "t": "Ce Pokémon raffole du pollen et du nectar. Il volette souvent près des Tournicoton pour collecter leur pollen."}, {"g": "Bouclier", "t": "Il perçoit l’aura de son ennemi et anticipe ses mouvements. Il parvient ainsi à éviter les attaques et à riposter dans la foulée."}],
  743: [{"g": "Soleil", "t": "Il confectionne de petites boules de pollen de diverses natures, certaines lui servant de repas, d’autres à attaquer l’ennemi."}, {"g": "Lune", "t": "Certaines boules de pollen de Rubombelle sont très utiles d’un point de vue nutritif. Vendues en complément alimentaire, elles font un carton."}, {"g": "Ultra-Soleil", "t": "Il déteste la pluie car elle mouille le pollen. Quand la météo se dégrade, il se cache alors dans le creux d’un arbre et attend sans bouger."}, {"g": "Ultra-Lune", "t": "Il peut prévoir le temps qu’il va faire grâce à l’humidité et à la direction du vent. Il ne pointe le bout de ses ailes que par beau temps."}, {"g": "Épée", "t": "Il mélange du nectar et du pollen pour créer des boules qui ont divers effets, selon les quantités et les ingrédients utilisés."}, {"g": "Bouclier", "t": "Il a horreur d’être trempé par la pluie. On ne le voit que très rarement à Galar, région connue pour son temps couvert."}],
  744: [{"g": "Soleil", "t": "Comme il s’attache facilement à son Dresseur, on le conseille souvent aux débutants, bien qu’il ait tendance à devenir plus rebelle avec l’âge."}, {"g": "Lune", "t": "Ce Pokémon vit depuis toujours avec les humains. Lorsque son Dresseur est triste, il reste à ses côtés pour le soutenir moralement."}, {"g": "Ultra-Soleil", "t": "Il devient de plus en plus sauvage et agressif en grandissant. Il n’est pas rare que son Dresseur l’abandonne, ne sachant plus qu’en faire."}, {"g": "Ultra-Lune", "t": "Il frotte les cailloux pointus de son cou contre son Dresseur en signe d’affection. C’est adorable, mais douloureux."}, {"g": "Épée", "t": "Ce Pokémon s’attache vite à son Dresseur, mais a une fâcheuse tendance à le mordre, ce qui peut compliquer son entraînement."}, {"g": "Bouclier", "t": "Il intimide ses ennemis en cognant les rochers autour de son cou contre le sol. Au premier signe de faiblesse, il passe à l’assaut."}],
  745: [{"g": "Soleil", "t": "Il fait tourner en bourrique ses ennemis à cause de sa vitesse. Outre ses crocs et ses griffes, il peut compter sur le roc acéré de sa crinière."}, {"g": "Lune", "t": "Pour peu qu’on l’élève comme il se doit, ce Pokémon restera à jamais fidèle à son Dresseur et deviendra son partenaire le plus dévoué."}, {"g": "Ultra-Soleil", "t": "Les rocs de sa crinière sont aiguisés comme des couteaux. Il poursuit patiemment sa cible pour l’affaiblir et lui porter le coup de grâce."}, {"g": "Ultra-Lune", "t": "Les rocs de sa crinière sont plus acérés que des couteaux. Les morceaux qui s’en détachent sont considérés comme des porte-bonheur."}, {"g": "Épée", "t": "C’est un Pokémon calme et prudent. Les pierres dans sa crinière sont aussi tranchantes que des lames de rasoir."}, {"g": "Bouclier", "t": "Il poursuit ses proies avec rapidité et patience. Une fois la cible acculée, il attaque toujours son point faible avec ses crocs."}],
  746: [{"g": "Soleil", "t": "Quand il est dans le pétrin, ses yeux deviennent luisants. Ses semblables accourent alors et forment avec lui un banc de combat."}, {"g": "Lune", "t": "Avec son air chétif et sa chair appétissante, tous les Pokémon en ont après lui... mais ceux qui ont essayé ont eu des problèmes."}, {"g": "Ultra-Soleil", "t": "Il se déplace en banc pour pallier sa faiblesse, mais il n’est pas rare de voir un Froussardine nager en solitaire."}, {"g": "Ultra-Lune", "t": "Il fait briller ses pupilles pour rameuter ses congénères lorsque la situation tourne mal. Le signal est visible à 40 km de distance."}, {"g": "Épée", "t": "Individuellement, ils sont très faibles. Ils ont donc développé une tactique de déplacement en banc pour résister aux ennemis."}, {"g": "Bouclier", "t": "Ses yeux se mouillent quand il sent le danger approcher. Le scintillement de ses larmes sert de signal pour que ses congénères se rassemblent."}],
  747: [{"g": "Soleil", "t": "Les épines sur sa tête transpercent et empoisonnent l’ennemi. Ses dix tentacules se chargent ensuite du reste."}, {"g": "Lune", "t": "Il rampe le long des fonds marins et des plages de sable. Les cornes de corail des Corayon sont ses biscuits apéritifs préférés."}, {"g": "Ultra-Soleil", "t": "Son amour des cornes de Corayon lui vaut l’hostilité des artisans qui les récoltent dans la nature pour en faire des objets."}, {"g": "Ultra-Lune", "t": "Une nuit lui suffit à régénérer n’importe quelle partie de son corps, à l’exception de sa tête, et ce, quelle que soit l’étendue des dégâts."}, {"g": "Épée", "t": "Ses piqûres causent un engourdissement qui se mue en démangeaisons si terribles qu’elles poussent la victime à se gratter jusqu’au sang."}, {"g": "Bouclier", "t": "Contrairement aux Vorastérie d’Alola, ceux de Galar ne font pas grand cas des cornes de Corayon."}],
  748: [{"g": "Soleil", "t": "Il arpente le fond des océans du haut de ses douze pattes, en laissant derrière lui une traînée de miettes de Corayon."}, {"g": "Lune", "t": "Son poison provoque chez sa victime des douleurs aiguës pendant trois jours et trois nuits, et laisse des séquelles irréversibles."}, {"g": "Ultra-Soleil", "t": "Il attaque ses ennemis en projetant des épines empoisonnées, et il utilise ses griffes pour transpercer ceux qui l’approchent de trop près."}, {"g": "Ultra-Lune", "t": "Avec ses douze pattes, il crée un dôme protecteur qui lui permet de ne pas subir l’influence des marées."}, {"g": "Épée", "t": "Pour endurer les températures peu clémentes de Galar, il forme un dôme hermétique avec ses pattes pour conserver sa chaleur corporelle."}, {"g": "Bouclier", "t": "Sa poche à venin interne regorge d’un poison si violent que même un Wailord en souffrirait pendant trois jours entiers."}],
  749: [{"g": "Soleil", "t": "La boue qui lui colle aux pattes lui sert de semelle antidérapante. Il peut ainsi courir à toute allure avec vigueur et assurance."}, {"g": "Lune", "t": "Un Pokémon très têtu, qui aime faire les choses à son rythme. Il passe ses journées à mâcher de la terre pour en faire de la boue et jouer avec."}, {"g": "Ultra-Soleil", "t": "Il adore jouer dans la boue. S’il ne prend pas son bain de boue quotidien, il tombe dans un tel état de stress qu’il n’obéit plus à son Dresseur."}, {"g": "Ultra-Lune", "t": "Ce Pokémon costaud n’a aucun mal à porter des fardeaux pesant cinquante fois son poids."}, {"g": "Épée", "t": "Il est si fort qu’il peut aisément porter des charges allant jusqu’à 50 fois son poids. C’est un expert dans l’art d’utiliser la boue."}, {"g": "Bouclier", "t": "Il mâche de la terre pour créer une boue dont il s’enduit les jambes. Celle-ci lui permet alors d’arpenter même les routes accidentées."}],
  750: [{"g": "Soleil", "t": "Une fois sèche, la boue qu’il crache reste solide même sous le vent et la pluie. Elle était autrefois très utilisée dans les revêtements muraux."}, {"g": "Lune", "t": "C’est le spécialiste du gros coup de sabot boueux. Grâce à cela, il peut facilement réduire un camion entier en un tas de ferraille."}, {"g": "Ultra-Soleil", "t": "Il reste calme et impassible en toutes circonstances. Il mélange sa salive à de la terre pour créer une boue spéciale dans sa bouche."}, {"g": "Ultra-Lune", "t": "Il peut parcourir les chemins de montagne pendant trois jours et trois nuits en tirant un fardeau de dix tonnes sans se reposer."}, {"g": "Épée", "t": "Il recouvre ses jambes d’une croûte de boue, les rendant ainsi plus dures que la pierre. Il peut alors détruire un camion d’un seul coup de jambe."}, {"g": "Bouclier", "t": "Il a assez d’endurance pour arpenter tout Galar sans relâche en tirant des charges dépassant les dix tonnes."}],
  751: [{"g": "Soleil", "t": "Il lui arrive d’aller chercher sa nourriture sur la terre ferme. Sa bulle lui sert alors aussi bien à respirer qu’à protéger sa tête molle."}, {"g": "Lune", "t": "Dès qu’il tombe sur une proie ou un prédateur, il ouvre les hostilités en lui lançant de l’eau provenant de la bulle qui entoure sa tête."}, {"g": "Ultra-Soleil", "t": "Quand deux Araqua se croisent, ils comparent la taille de leur bulle. Celui qui a la plus petite doit céder le passage."}, {"g": "Ultra-Lune", "t": "L’oxygène contenu dans l’eau étant le seul qu’il puisse respirer, il met toujours sa tête dans une bulle quand il est sur la terre ferme."}, {"g": "Épée", "t": "Il enveloppe sa tête dans une bulle d’eau qu’il a gonflée avec son abdomen. Il aime en comparer la taille avec celles de ses congénères."}, {"g": "Bouclier", "t": "Il vit principalement dans l’eau, mais s’il a besoin de s’aventurer sur la terre ferme pour chasser ses proies, il protège sa tête avec une bulle d’eau."}],
  752: [{"g": "Soleil", "t": "Il se bat en donnant des « coups de bulle ». Les plus petits Pokémon peuvent se retrouver piégés à l’intérieur de sa bulle et mourir noyés."}, {"g": "Lune", "t": "Bien plus attentionné qu’il n’y paraît, il n’hésite pas à recueillir dans sa bulle ses camarades plus petits et fragiles."}, {"g": "Ultra-Soleil", "t": "Il passe la plupart de son temps dans l’eau. S’il est rassasié, il peut conserver ses proies dans sa bulle pour les manger plus tard."}, {"g": "Ultra-Lune", "t": "Il a pour habitude d’enfermer ce qui lui est cher dans sa bulle. Si son Dresseur n’est pas vigilant, Tarenbulle essaiera de l’y ranger lui aussi !"}, {"g": "Épée", "t": "Il piège ses proies dans des bulles qu’il lance avec ses pattes. Une fois qu’elles se sont noyées, il prend son temps pour les déguster."}, {"g": "Bouclier", "t": "Il prend soin de petits Araqua en les abritant dans sa bulle et en les laissant grignoter les restes de ses repas."}],
  753: [{"g": "Soleil", "t": "La journée, il passe son temps à flâner au soleil et à faire la sieste. Le soir venu, il part à la recherche d’un lieu plus sûr pour passer la nuit."}, {"g": "Lune", "t": "Le corps de Mimantis dégage un léger parfum sucré, qui a le don d’attirer les Bombydou dans les hautes herbes où il se cache."}, {"g": "Ultra-Soleil", "t": "Quand le jour se lève, il déploie ses quatre feuilles pour prendre un bain de soleil. Une odeur agréable émane du haut de sa tête."}, {"g": "Ultra-Lune", "t": "Il raffole de la lumière du jour. Sa couleur devient de plus en plus vive à mesure qu’il s’abreuve des rayons du soleil."}, {"g": "Épée", "t": "Il dégage une odeur délicieuse quand il prend le soleil, ce qui attire tous les Pokémon Insecte des alentours."}, {"g": "Bouclier", "t": "La journée, il dort tranquillement au soleil pour en absorber les rayons. La nuit, il se réveille et vaque à ses occupations."}],
  754: [{"g": "Soleil", "t": "Préserver ses couleurs éclatantes requiert un travail titanesque. On trouve tout de même des gens assez fous pour s’y atteler."}, {"g": "Lune", "t": "Ses pétales en forme de faux envoient des rayons capables de couper un bloc de métal en deux avec une facilité déconcertante."}, {"g": "Ultra-Soleil", "t": "C’est pour se protéger qu’il se fait passer pour un Pokémon Insecte. Les pétales de ses bras sont extrêmement coupants."}, {"g": "Ultra-Lune", "t": "Sa façon de trancher ses ennemis ressemble à une danse. Son élégance lui a valu le titre de « plus beau Pokémon Plante »."}, {"g": "Épée", "t": "Un magnifique Pokémon qui ressemble à une fleur. Les Floramantis bien entraînés arborent une couleur très vive."}, {"g": "Bouclier", "t": "Les pétales sur ses deux bras sont fins, mais très tranchants. Ils peuvent également absorber la lumière pour la renvoyer sous forme de laser."}],
  755: [{"g": "Soleil", "t": "Il répand des spores luminescentes qui clignotent autour de lui. Quiconque aperçoit ces lumières tombe dans un sommeil profond."}, {"g": "Lune", "t": "Le jour, il dort tout en absorbant des nutriments à la racine des arbres. Le soir, il se lève et part à la recherche d’un nouvel arbre où se poser."}, {"g": "Ultra-Soleil", "t": "Il répand des spores luminescentes autour de lui. Malgré le danger qu’il représente, les balades nocturnes dans les bois où il vit sont populaires."}, {"g": "Ultra-Lune", "t": "Il aime les endroits sombres et humides. La nuit, il fait rayonner les spores contenues dans ses chapeaux."}, {"g": "Épée", "t": "Ses chapeaux sont délicieux, et les Pokémon de la forêt s’en délectent. Heureusement pour lui, ses couvre-chefs repoussent en une nuit."}, {"g": "Bouclier", "t": "Il vit dans les forêts sombres même en plein jour. Il dissémine des spores clignotantes pour endormir ses ennemis."}],
  756: [{"g": "Soleil", "t": "Il est risqué de s’aventurer la nuit dans un bois peuplé de Lampignon. Attirés par leur lumière envoûtante, certains n’en sont jamais revenus."}, {"g": "Lune", "t": "Il projette des spores clignotantes qui hypnotisent et endorment ses proies, avant de venir absorber leur énergie vitale."}, {"g": "Ultra-Soleil", "t": "Il endort ses victimes puis aspire leur énergie vitale avec ses doigts. Il aide ses congénères affaiblis en partageant cette énergie avec eux."}, {"g": "Ultra-Lune", "t": "Quand un conflit territorial éclate entre Parasect et lui, un brouillard de spores envahit toute la zone."}, {"g": "Épée", "t": "Il attire ses proies et les endort grâce au clignotement de ses spores. Il aspire ensuite leur énergie vitale du bout de ses doigts."}, {"g": "Bouclier", "t": "Il ne faut pas s’approcher des lumières qui luisent la nuit au fond des bois, sous peine de se faire endormir par un Lampignon."}],
  757: [{"g": "Soleil", "t": "Il consume ses fluides corporels pour générer un gaz toxique qui étourdit ses ennemis. Il ne lui reste alors qu’à les achever."}, {"g": "Lune", "t": "Habitant des volcans et des régions rocheuses arides, il exhale un gaz toxique au parfum doux pour attirer et piéger les Pokémon Insecte."}, {"g": "Ultra-Soleil", "t": "La femelle domine le mâle, qui ne peut évoluer en raison de carences nutritionnelles. Il lui offre en effet presque toutes ses proies en tribut."}, {"g": "Ultra-Lune", "t": "Il attaque après avoir fait chanceler ses ennemis avec son gaz toxique. Cela ne fonctionne pas très bien sur les Spinda, chancelants de base."}, {"g": "Épée", "t": "Il fait chauffer le liquide qu’il sécrète dans ses poches à venin avec la flamme de sa queue pour créer un gaz toxique."}, {"g": "Bouclier", "t": "Il s’approche de ses proies par-derrière et les asperge d’un gaz empoisonné avant qu’elles n’aient le temps de réagir, les clouant sur place."}],
  758: [{"g": "Soleil", "t": "Curieusement, cette espèce ne compte que des femelles. Ces dernières aiment s’entourer de nombreux admirateurs Tritox mâles."}, {"g": "Lune", "t": "Son gaz toxique est riche en phéromones. Il est possible d’isoler ces dernières pour concocter un puissant parfum aphrodisiaque."}, {"g": "Ultra-Soleil", "t": "Ce Pokémon habite au fin fond des cavernes. Il se fait servir par des Tritox envoûtés par ses phéromones."}, {"g": "Ultra-Lune", "t": "Malamandre punit sans merci les Tritox qui rentrent bredouilles de la chasse, généralement d’une gifle de sa paume enflammée."}, {"g": "Épée", "t": "Il n’existe que des spécimens femelles. Elles envoûtent les Tritox mâles grâce à leurs nuages de phéromones."}, {"g": "Bouclier", "t": "Les conflits entre Malamandre seraient réglés par un simple calcul : le spécimen dont la suite comporte le plus de Tritox l’emporte."}],
  759: [{"g": "Soleil", "t": "Il est à croquer, sauf lorsqu’il s’énerve et frappe à tout va. Dans ce cas, laissez-le tranquille ou vous finirez à coup sûr dans le décor."}, {"g": "Lune", "t": "Ne tentez pas de le caresser s’il ne vous connaît pas assez : il entrerait dans une rage folle, et vous encourriez un grand danger."}, {"g": "Ultra-Soleil", "t": "Il est si fort qu’il peut abattre un grand arbre. L’odeur que dégage l’organe sur son derrière lui permet de communiquer avec ses semblables."}, {"g": "Ultra-Lune", "t": "Il déteste être touché ou pris dans les bras, et se débat de toutes ses forces pour se dégager."}, {"g": "Épée", "t": "Sa fourrure duveteuse est très agréable à caresser, mais ceux qui la touchent sans prévenir s’exposent à une correction brutale."}, {"g": "Bouclier", "t": "Sa façon de remuer les pattes pour se défendre semble adorable, mais ce Pokémon est si puissant qu’il pourrait fendre un tronc de la sorte."}],
  760: [{"g": "Soleil", "t": "Sa force physique hors norme le rend assez dangereux. D’ailleurs, les zones qu’il habite sont systématiquement interdites d’accès."}, {"g": "Lune", "t": "Il fête chaque victoire par une accolade avec son Dresseur, au grand dam de ce dernier, et en particulier de sa colonne vertébrale."}, {"g": "Ultra-Soleil", "t": "Il fait de grands gestes avec ses pattes pour intimider et mettre en garde ses ennemis. Mieux vaut alors prendre ses jambes à son cou !"}, {"g": "Ultra-Lune", "t": "Sa force colossale fait sa fierté. De nombreuses personnes le considèrent comme le Pokémon le plus dangereux d’Alola."}, {"g": "Épée", "t": "Il serre fort contre lui ceux qu’il considère comme ses compagnons, mais ses câlins sont assez puissants pour broyer les os."}, {"g": "Bouclier", "t": "Il abat ses proies à l’aide de techniques à faire pâlir d’envie des combattants professionnels, puis les emporte sous les bras dans sa tanière."}],
  761: [{"g": "Soleil", "t": "Une odeur terriblement appétissante émane du corps des Croquine. Alléchés, les Bazoucan rappliquent et les gobent goulument."}, {"g": "Lune", "t": "Trop sucrée pour être consommée telle quelle, la sueur de Croquine doit être diluée dans l’eau pour obtenir un jus sucré juste comme il faut."}, {"g": "Ultra-Soleil", "t": "Son odeur appétissante en fait la cible idéale des Pokémon oiseaux, mais comme il n’est pas très malin, ça lui est égal."}, {"g": "Ultra-Lune", "t": "Pour résister aux Pokémon oiseaux qui tentent de le manger, il fait tourner le sépale qui est sur sa tête, mais c’est généralement peine perdue."}, {"g": "Épée", "t": "La douce odeur fruitée qui émane de son corps stimule énormément l’appétit des Pokémon oiseaux."}, {"g": "Bouclier", "t": "La sueur sucrée qu’il produit lorsqu’on l’attaque est délicieuse. L’odeur de celle-ci lui attire encore plus d’ennemis."}],
  762: [{"g": "Soleil", "t": "Pour mieux se défendre, il a fait pousser sur son corps un calice assez solide pour résister aux coups de bec des Pokémon oiseaux."}, {"g": "Lune", "t": "Il passe son temps à gambader joyeusement. Sa silhouette pleine d’entrain et son parfum agréable ont le don d’attirer les autres Pokémon."}, {"g": "Ultra-Soleil", "t": "Confiant en la protection offerte par son solide calice, il n’hésite pas à jouer avec les Pokémon oiseaux. Il se fait picorer, mais il s’en moque."}, {"g": "Ultra-Lune", "t": "Sa démarche sautillante fait balancer le calice qui se dresse sur sa tête. Recevoir un coup de sépale est très douloureux !"}, {"g": "Épée", "t": "Il danse en tournant sur lui-même et répand une douce odeur dans son sillage. Sentir celle-ci provoque un profond sentiment de bonheur."}, {"g": "Bouclier", "t": "Lorsqu’un Bleuseille le picore, il commence par se défendre avec son calice, et lui assène ensuite de violents coups de pied."}],
  763: [{"g": "Soleil", "t": "Spécialiste du coup de pied bien placé, ce Pokémon prend un malin plaisir à savater ses ennemis au sol en riant aux éclats."}, {"g": "Lune", "t": "Ce Pokémon est connu pour la forme parfaite de ses jambes. Les instituts de beauté n’hésitent pas à l’utiliser comme mascotte dans leurs pubs."}, {"g": "Ultra-Soleil", "t": "Ce véritable virtuose du coup de pied peut mettre K.O. un champion de kick-boxing en une seule frappe."}, {"g": "Ultra-Lune", "t": "Ce Pokémon bagarreur possède un jeu de jambes hors du commun. Il éclate de rire entre chaque coup de pied qu’il assène à sa victime."}, {"g": "Épée", "t": "Ce Pokémon au cœur cruel est redouté, car il piétine ses ennemis avec ses longues jambes sans aucune pitié."}, {"g": "Bouclier", "t": "Ce Pokémon frappe violemment ses ennemis de la pointe dure de ses jambes, ce qui leur inflige des dégâts irréversibles au corps et à l’âme."}],
  764: [{"g": "Soleil", "t": "Sa liane gluante diffuse des nutriments dans les fleurs qu’elle happe. Ces dernières dégagent alors un léger parfum."}, {"g": "Lune", "t": "Utilisées en bain, les fleurs qui se collent sur sa liane possèdent des vertus relaxantes. Elles ont déjà séduit les gens du monde entier."}, {"g": "Ultra-Soleil", "t": "Il ramasse des fleurs en déployant la liane gluante accrochée à sa tête et s’en agrémente. Il se sent mal à l’aise lorsqu’il n’en a pas."}, {"g": "Ultra-Lune", "t": "Il cueille des fleurs qu’il colle sur son corps grâce à ses fluides corporels. Le parfum qui émane de ses pétales a des vertus apaisantes."}, {"g": "Épée", "t": "Il orne son corps de fleurs qu’il cueille avec sa liane. Mystérieusement, celles-ci ne se fanent jamais."}, {"g": "Bouclier", "t": "Ce Pokémon dégage un parfum agréable qui varie d’un spécimen à l’autre, car chaque Guérilande s’habille de fleurs différentes."}],
  765: [{"g": "Soleil", "t": "Célébré pour son intelligence exceptionnelle, ce Pokémon vous prendra de haut si vous débutez. À réserver aux Dresseurs aguerris."}, {"g": "Lune", "t": "Il vit perché sur les arbres au plus profond de la jungle. Plus rarement, on le croise sur le littoral, en plein concours d’intelligence avec un Roigada."}, {"g": "Ultra-Soleil", "t": "Il médite généralement en haut des arbres. Il se permet de lancer des Poké Balls sur les autres Pokémon et leur donne des ordres."}, {"g": "Ultra-Lune", "t": "Les Gouroutan ne s’entendent pas bien entre eux. Ils ne cessent de se provoquer en duel pour comparer leur degré d’intelligence."}, {"g": "Épée", "t": "D’un mouvement de son éventail tissé avec des feuilles et des poils, il peut manipuler les Pokémon et les forcer à agir selon sa volonté."}, {"g": "Bouclier", "t": "Il connaît la forêt sur le bout des doigts. Lorsqu’il trouve un Pokémon blessé, il cherche des plantes médicinales pour le soigner."}],
  766: [{"g": "Soleil", "t": "Ils se rassemblent par groupes de vingt. Dans cette formation très soudée, nul ne songerait une seule seconde à abandonner ses alliés."}, {"g": "Lune", "t": "Il choisit les Baies les plus dures pour s’en servir au combat : un stratagème bien rodé que les chefs de groupe enseignent à leurs alliés."}, {"g": "Ultra-Soleil", "t": "Il utilise sa salive pour coller des feuilles sur ses épaules. Leur disposition indique son appartenance à un groupe particulier."}, {"g": "Ultra-Lune", "t": "Les Baies constituent à la fois son arme et la base de son alimentation. Celui qui peut les lancer le plus loin devient le chef du groupe."}, {"g": "Épée", "t": "Ils obéissent à leur chef au doigt et à l’œil, et travaillent en équipe pour dénicher leurs Baies favorites."}, {"g": "Bouclier", "t": "Ils vivent en groupes de vingt individus où chacun a un rôle précis, ce qui leur a permis de survivre dans un environnement impitoyable."}],
  767: [{"g": "Soleil", "t": "De nature poltronne, il prend ses nombreuses pattes à son cou au moindre danger et balaie le sol sur son passage."}, {"g": "Lune", "t": "Il vit aussi bien en bord de mer que dans les fonds marins. Véritable aspirateur sur pattes, il avale n’importe quelle nourriture, même pourrie."}, {"g": "Ultra-Soleil", "t": "Il ramasse tout ce qu’il trouve par terre, y compris des pièces. Cela lui vaut d’être pris pour cible par les Cornèbre et les Miaouss."}, {"g": "Ultra-Lune", "t": "Un Pokémon timoré qui se sauve à toutes pattes dès que l’on s’approche de lui."}, {"g": "Épée", "t": "Ce véritable nettoyeur de la nature mange tout, même la nourriture avariée et les déchets. Les environs de son nid sont toujours impeccables."}, {"g": "Bouclier", "t": "Ils se déplacent en groupe, toujours en alerte. Dès qu’ils détectent une présence ennemie, ils s’enfuient dans toutes les directions."}],
  768: [{"g": "Soleil", "t": "Il fait miroiter ses énormes griffes acérées avant d’attaquer. Elles sont assez puissantes pour fendre en deux l’air comme la mer."}, {"g": "Lune", "t": "Il utilise ses six pattes pour se battre. Habitant des grottes sous-marines, il passe son temps plongé dans un silence méditatif."}, {"g": "Ultra-Soleil", "t": "La carapace qui recouvre son corps est aussi dure que le diamant. Il ne recule devant rien pour gagner."}, {"g": "Ultra-Lune", "t": "Ses griffes rétractiles sont sa plus grande arme. Il se fait parfois accompagner d’une suite de Sovkipou."}, {"g": "Épée", "t": "Il ne recule devant rien pour gagner. Il profite de l’inattention de son adversaire pour lui administrer un coup décisif de ses petites griffes antérieures."}, {"g": "Bouclier", "t": "Il vit dans des trous ou des épaves au fond de l’océan. Il se bat souvent contre Krakos, et le perdant sert de repas au gagnant."}],
  769: [{"g": "Soleil", "t": "Ce Pokémon est né de la rancœur d’un voyageur mort dans l’indifférence, laquelle s’est incarnée dans un pâté de sable."}, {"g": "Lune", "t": "Ceux qui ont le malheur de mettre la main dans sa gueule deviennent ses pantins. Il est prêt à tout pour agrandir son corps en forme de dune."}, {"g": "Ultra-Soleil", "t": "Il tient beaucoup à la pelle sur sa tête. Si un enfant cherche à la récupérer, il se bat sans retenir ses coups pour la garder."}, {"g": "Ultra-Lune", "t": "Détruisez vos pâtés de sable avant de rentrer chez vous, sinon une âme pourrait les posséder et les transformer en Bacabouh."}, {"g": "Épée", "t": "Ce Pokémon est né lorsqu’une âme rancunière s’est incarnée dans un pâté de sable. Il tient énormément à la pelle sur sa tête."}, {"g": "Bouclier", "t": "Il vit principalement sur les plages de sable et peut agrandir son corps en prenant le contrôle des gens qui mettent la main dans sa gueule."}],
  770: [{"g": "Soleil", "t": "Il a possédé un humain pour que ce dernier le remodèle en château de sable, décuplant au passage ses pouvoirs de malédiction."}, {"g": "Lune", "t": "On trouve de nombreux ossements sous ses tours, restes de pauvres hères capturés. Leur énergie a servi à nourrir ce Pokémon."}, {"g": "Ultra-Soleil", "t": "Chacun de ses grains de sable a sa volonté propre. Trépassable gobe de petits Pokémon pour absorber leur énergie vitale."}, {"g": "Ultra-Lune", "t": "Ce terrifiant Pokémon déclenche des tempêtes de sable pour immobiliser ses victimes, puis absorbe leur énergie vitale."}, {"g": "Épée", "t": "On l’appelle aussi le « cauchemar des plages ». Il contrôle le sable pour ensevelir ses proies et aspirer leur âme."}, {"g": "Bouclier", "t": "Bien qu’il déteste l’eau, il vit sur les plages. Quand la pluie s’abat sur lui, il est incapable de conserver sa forme de château de sable."}],
  771: [{"g": "Soleil", "t": "Il vit en bord de mer, ou en eaux peu profondes. Ses organes peuvent sortir de son corps pour saisir de la nourriture ou frapper l’ennemi."}, {"g": "Lune", "t": "On en rencontre beaucoup sur les plages. Le mucus gluant qui entoure son corps est idéal pour soulager les coups de soleil."}, {"g": "Ultra-Soleil", "t": "Lancer à la mer les Concombaffe venus s’échouer sur le rivage était une habitude qui s’est depuis muée en une véritable tradition."}, {"g": "Ultra-Lune", "t": "Tout son corps est recouvert d’un mucus gluant. Veillez à ne pas glisser dessus : il en profiterait pour vous mettre une grosse claque !"}, {"g": "Épée", "t": "Il vit dans les eaux chaudes des hauts-fonds. S’il croise un ennemi, il l’attaque en lui crachant ses organes internes au visage."}, {"g": "Bouclier", "t": "Le fluide visqueux qui le recouvre garde sa peau bien hydratée, ce qui lui permet de vivre plusieurs jours sur la terre ferme sans se dessécher."}],
  772: [{"g": "Soleil", "t": "Le lourd masque qu’il porte est un limiteur qui l’empêche d’exprimer toute l’étendue de sa puissance. Il recèle une force mystérieuse."}, {"g": "Lune", "t": "Ce Pokémon créé de toutes pièces porte un masque qui contient sa puissance et l’empêche de perdre le contrôle et de tout détruire."}, {"g": "Ultra-Soleil", "t": "Développé en tant qu’arme dans un but bien précis, il est devenu incontrôlable lors d’une expérience et a dû être cryogénisé."}, {"g": "Ultra-Lune", "t": "On lui fait porter un masque qui limite sa puissance afin d’éviter qu’il n’en perde le contrôle et sème le chaos."}, {"g": "Épée", "t": "On raconte qu’il aurait été recréé à Galar suite à un vol de documents de recherche hautement confidentiels."}, {"g": "Bouclier", "t": "Il a été créé artificiellement d’après un Pokémon mythique. Il est muni d’un masque afin de contenir sa puissance."}],
  773: [{"g": "Soleil", "t": "La confiance qu’il place en son Dresseur a réveillé ses pouvoirs. Il est à présent capable de changer de type à loisir durant le combat."}, {"g": "Lune", "t": "Son nom lui a été donné par le jeune homme qui a le premier réussi à faire évoluer Type:0."}, {"g": "Ultra-Soleil", "t": "Il a réveillé tout son potentiel et a évolué. Briser son lourd masque a décuplé sa vitesse."}, {"g": "Ultra-Lune", "t": "Il a réussi à briser son masque grâce à la force mentale qu’il a acquise en établissant un lien puissant avec son Dresseur."}, {"g": "Épée", "t": "Un lien fort avec son Dresseur lui a permis de libérer tout son potentiel. Il peut changer de type à volonté."}, {"g": "Bouclier", "t": "La relation de confiance qui le lie à son Dresseur est le facteur décisif qui lui permet de libérer tout son potentiel."}],
  774: [{"g": "Soleil", "t": "Il vivait dans la couche d’ozone, avant que sa carapace, devenue trop lourde, ne finisse par le faire chuter sur la terre ferme."}, {"g": "Lune", "t": "La carapace qui le recouvre peut être arrachée par une violente attaque. Il est le fruit d’une mutation de nanoparticules."}, {"g": "Ultra-Soleil", "t": "Il vit dans la couche d’ozone, où des Pokémon plus forts que lui cherchent à le manger. Il tombe à terre lorsqu’il tente de s’enfuir."}, {"g": "Ultra-Lune", "t": "Sa carapace, pourtant très solide, éclate en mille morceaux quand il s’écrase sur la terre en tombant du ciel."}],
  775: [{"g": "Soleil", "t": "Il rejoint et quitte ce monde en dormant. Son existence se déroule comme un rêve paisible. Il dort du sommeil du juste toute sa vie durant."}, {"g": "Lune", "t": "La bûche qu’il tient est un cadeau de naissance de ses parents. S’il est bien apprivoisé, il s’accrochera au bras de son Dresseur."}, {"g": "Ultra-Soleil", "t": "Il dort continuellement depuis sa naissance. Lorsqu’il est en phase de sommeil profond, il ne bouge plus d’un poil."}, {"g": "Ultra-Lune", "t": "Ce Pokémon passe sa vie entière à dormir à cause des composants anesthésiants qui se trouvent dans les feuilles qu’il mange."}],
  776: [{"g": "Soleil", "t": "Sa carapace est très instable. Si on la heurte par mégarde, elle explose. Le creux sur son ventre est son point faible."}, {"g": "Lune", "t": "Il peut cracher des flammes et du gaz toxique par les naseaux. Ses excréments sont des explosifs qui peuvent servir à plein de choses."}, {"g": "Ultra-Soleil", "t": "Il vit dans les volcans et se nourrit de soufre et de minéraux. Les composants de ses repas renforcent sa carapace explosive."}, {"g": "Ultra-Lune", "t": "Sa carapace explosive est très dangereuse, mais elle est sensible à l’humidité. Il se cache donc au fond de sa grotte les jours de pluie."}, {"g": "Épée", "t": "Il s’abrite derrière une carapace couverte d’explosifs. Lorsqu’un ennemi l’attaque, il riposte à grands coups de déflagrations."}, {"g": "Bouclier", "t": "Il vit dans les volcans. Le soufre dont il se nourrit rend sa carapace explosive. Même ses selles sont dangereuses, car elles sont instables."}],
  777: [{"g": "Soleil", "t": "Les épines de ce Pokémon sont normalement baissées, mais quand il s’énerve, elles se dressent afin de pourfendre ses agresseurs."}, {"g": "Lune", "t": "Sa longue épine dorsale lui sert de paratonnerre. Il attire les éclairs et emmagasine la foudre dans sa poche électrique."}, {"g": "Ultra-Soleil", "t": "Les quatorze épines de son dos se hérissent de leur propre chef quand il est surpris ou excité."}, {"g": "Ultra-Lune", "t": "Il ne produit pas beaucoup d’électricité par lui-même, aussi se recharge-t-il quand il y a de l’orage."}, {"g": "Épée", "t": "Grâce à sa longue épine dorsale, il capte le tonnerre et les attaques des Pokémon Électrik, puis stocke leur courant dans sa poche électrique."}, {"g": "Bouclier", "t": "En cas de danger, il se roule en boule, dresse ses épines dorsales et lance des décharges électriques au hasard."}],
  778: [{"g": "Soleil", "t": "Sa véritable apparence est inconnue. Les chercheurs qui ont vu sous son déguisement sont littéralement morts de peur."}, {"g": "Lune", "t": "Son apparence est si effrayante qu’il doit se déguiser pour oser s’approcher des gens et des autres Pokémon."}, {"g": "Ultra-Soleil", "t": "Ce Pokémon docile déteste la solitude, mais il oppose une résistance acharnée si l’on essaie de jeter un coup d’œil sous son déguisement."}, {"g": "Ultra-Lune", "t": "Une bourrasque a un jour permis à un Dresseur de voir sous le déguisement de Mimiqui. Il est mort le soir même dans d’atroces souffrances."}, {"g": "Épée", "t": "Il se cache sous des guenilles en forme de Pikachu pour avoir l’air moins effrayant, mais cela le rend encore plus inquiétant."}, {"g": "Bouclier", "t": "Les malheureux chercheurs qui ont regardé sous son déguisement en lambeaux ont succombé à une mystérieuse maladie."}],
  779: [{"g": "Soleil", "t": "Lorsqu’il utilise l’appendice sur sa tête pour projeter ses pouvoirs psychiques, il émet un bruit aussi irritant qu’un grincement de dents."}, {"g": "Lune", "t": "Il engourdit ses proies grâce à sa force mentale avant de les dévorer avec ses grosses dents. Il peut briser les Kokiyas sans problème."}, {"g": "Ultra-Soleil", "t": "Enfoui dans le sable, il projette ses pouvoirs psychiques via l’appendice qu’il a sur la tête, et scanne les environs en attendant sa proie."}, {"g": "Ultra-Lune", "t": "Sa peau est si épaisse que même les épines de Vorastérie ne peuvent la percer. Il les croque bruyamment grâce à ses dents solides."}],
  780: [{"g": "Soleil", "t": "C’est une bonne pâte de nature, mais si par malheur il s’énerve, il peut détruire tout ce qui l’entoure de son souffle puissant."}, {"g": "Lune", "t": "Il adore les enfants rieurs. Il n’hésite pas à descendre de sa montagne pour venir en ville jouer avec ses petits amis."}, {"g": "Ultra-Soleil", "t": "S’il apprend qu’un enfant avec lequel il s’est lié d’amitié est persécuté par ses camarades, il trouve leur maison et la réduit en cendres."}, {"g": "Ultra-Lune", "t": "Il vient en ville pour jouer avec les enfants, et les protège en cas de danger. Les parents peuvent donc avoir l’esprit tranquille !"}, {"g": "Épée", "t": "Il vit dans les montagnes culminant à plus de 3 000 m d’altitude. Il se rend parfois en ville pour jouer avec les petits enfants."}, {"g": "Bouclier", "t": "Il est d’un naturel sociable et aimable, mais quand il se met en colère, il déchaîne des bourrasques qui emportent tout sur leur passage."}],
  781: [{"g": "Soleil", "t": "Avec un bon coup d’ancre bien senti, il peut même assommer un Wailord. Son véritable corps est la partie composée de limon."}, {"g": "Lune", "t": "C’est une réincarnation de l’âme des algues. Son corps est formé de détritus marins qu’il enveloppe de limon."}, {"g": "Ultra-Soleil", "t": "Il enserre ses victimes de ses algues vertes pour aspirer leur énergie vitale. Il ne chasse que les grosses proies, comme les Wailord."}, {"g": "Ultra-Lune", "t": "Les algues vertes formant sa chaîne s’étendent sur plusieurs centaines de mètres. Il s’entend bien avec Venalgue."}, {"g": "Épée", "t": "Ce Pokémon Spectre naît lorsque les algues dérivant au fond de l’océan se fixent sur des morceaux d’épaves de navire."}, {"g": "Bouclier", "t": "Il tend des guets-apens à ses proies en larguant son ancre dans la mer. Il peut absorber l’énergie vitale de grosses proies comme Wailord."}],
  782: [{"g": "Soleil", "t": "Il communique ses sentiments en frottant ses écailles. Les montagnes peuplées de Bébécaille bruissent d’un écho métallique."}, {"g": "Lune", "t": "Il vit dans les montagnes inhabitées. En affrontant d’autres Bébécaille, il grandit et se développe petit à petit."}, {"g": "Ultra-Soleil", "t": "Il frotte violemment l’écaille de sa tête sur des pierres et sur le sol pour intimider ses ennemis ou pour communiquer avec ses congénères."}, {"g": "Ultra-Lune", "t": "Il ne tourne jamais le dos à son adversaire en combat. Les guerriers d’autrefois s’en faisaient un compagnon, car ils appréciaient sa bravoure."}, {"g": "Épée", "t": "Il apprend à se battre en entrechoquant l’écaille qu’il a sur la tête avec celle de ses congénères, ce qui renforce sa technique et son esprit."}, {"g": "Bouclier", "t": "Il communique avec ses congénères en faisant cliqueter ses écailles dures comme du métal."}],
  783: [{"g": "Soleil", "t": "Il se jette sur ses proies en poussant un terrible cri de guerre. Il les déchiquette ensuite avec ses poings écaillés."}, {"g": "Lune", "t": "Ses écailles poussent très vite. Chaque nouvelle écaille est plus dure et plus pointue que l’ancienne."}, {"g": "Ultra-Soleil", "t": "Il fait tinter ses écailles en les frottant les unes contre les autres, et passe à l’attaque quand le rythme atteint son point culminant."}, {"g": "Ultra-Lune", "t": "On broie les écailles qu’il a perdues pour fabriquer des casseroles et des poêles à bonne conductivité thermique."}, {"g": "Épée", "t": "Ses écailles arrachées et son corps couvert de cicatrices sont la preuve de sa puissance. Il les montre à son adversaire vaincu en se pavanant."}, {"g": "Bouclier", "t": "Après avoir fait tinter ses écailles et poussé un terrible cri de guerre, il charge ses ennemis et les lacère de ses griffes acérées."}],
  784: [{"g": "Soleil", "t": "Quand il voit un ennemi, il cherche à l’intimider en faisant sonner les écailles de sa queue. Les plus faibles perdent contenance et s’enfuient."}, {"g": "Lune", "t": "Ses écailles lui servent aussi bien en attaque qu’en défense. Jadis, les hommes s’en servaient pour fabriquer des armes et des objets usuels."}, {"g": "Ultra-Soleil", "t": "Quand il hurle pour fêter sa victoire sur une proie, on entend ses congénères se réjouir de toutes parts dans un grand tintement métallique."}, {"g": "Ultra-Lune", "t": "Il se bat vaillamment avec ses poings couverts d’écailles d’acier. Il est particulièrement fier de l’impact de ses uppercuts."}, {"g": "Épée", "t": "Quand il rencontre un ennemi, il fait sonner les écailles de sa queue pour l’intimider. Il n’affronte que ceux qui ne se laissent pas impressionner."}, {"g": "Bouclier", "t": "Dans les ruines, on trouve parfois des fresques représentant des guerriers antiques qui portent des armures faites avec ses écailles."}],
  785: [{"g": "Soleil", "t": "Gardien de Mele-Mele, il est curieux de tout. Il a le pouvoir d’appeler les nuages orageux pour stocker la foudre dans son corps."}, {"g": "Lune", "t": "Il déstabilise ses ennemis avec sa vitesse ébouriffante. Il pique souvent des colères noires, mais il en oublie aussitôt la raison."}, {"g": "Ultra-Soleil", "t": "Bien qu’on le considère comme une divinité protectrice, il peut se montrer cruel envers les humains et les Pokémon qui l’ont offensé."}, {"g": "Ultra-Lune", "t": "Il est le gardien de Mele-Mele et le maître de la foudre. D’un naturel curieux, il apparaît devant les humains de temps à autre."}],
  786: [{"g": "Soleil", "t": "Pokémon candide mais terriblement cruel, c’est le gardien d’Akala. Il puise son énergie dans le parfum entêtant des fleurs."}, {"g": "Lune", "t": "Avec ses ailes délicates, il répand une poudre mystérieuse et lumineuse quand il vole. Il suffit de le toucher pour retrouver aussitôt le sourire."}, {"g": "Ultra-Soleil", "t": "C’est le gardien d’Akala. Il saupoudre une pluie d’écailles scintillantes sur les humains et les Pokémon blessés pour les soigner."}, {"g": "Ultra-Lune", "t": "Bien qu’on le considère comme une divinité protectrice, cette incarnation parfaite de la nature est aussi innocente que cruelle."}],
  787: [{"g": "Soleil", "t": "Il arrache de grands arbres et fait des moulinets avec. Il a le pouvoir de rendre la végétation luxuriante pour ensuite se nourrir de cette force."}, {"g": "Lune", "t": "C’est l’indolent gardien d’Ula-Ula. Il se sert de la végétation pour immobiliser ses ennemis, avant de les empaler avec ses cornes."}, {"g": "Ultra-Soleil", "t": "Bien qu’on le connaisse comme une divinité protectrice, il peut se montrer sans pitié envers ceux qu’il considère comme ses ennemis."}, {"g": "Ultra-Lune", "t": "Il est le gardien d’Ula-Ula et le maître des plantes. Il évite les combats inutiles en faisant tinter sa queue pour signaler son arrivée."}],
  788: [{"g": "Soleil", "t": "Il confond ses ennemis grâce au brouillard et les pousse à s’en prendre à eux-mêmes. Il puise son énergie dans les courants marins."}, {"g": "Lune", "t": "Gardien de Poni, il a le pouvoir de contrôler l’eau. On raconte qu’il peut produire une eau limpide qui nettoie toutes les impuretés."}, {"g": "Ultra-Soleil", "t": "Gardien de Poni et maître de l’eau, il vit au plus profond de la brume. C’est notamment pour cette raison qu’il est à la fois craint et vénéré."}, {"g": "Ultra-Lune", "t": "Il ne faut pas se laisser berner par son statut de divinité protectrice : il lui arrive de mettre en pièces ceux qui osent s’approcher de trop près."}],
  789: [{"g": "Soleil", "t": "Son corps est composé d’un gaz très volatile. Il croît lentement, en accumulant les poussières atmosphériques au gré de ses déplacements."}, {"g": "Lune", "t": "Jadis, on l’appelait l’enfant des étoiles. On raconte qu’il viendrait d’un autre monde, mais rien n’est prouvé."}, {"g": "Ultra-Soleil", "t": "Son corps est composé d’un gaz très instable. Il se fait emporter par la moindre brise, mais n’a pas l’air de s’en soucier pour autant."}, {"g": "Ultra-Lune", "t": "Nul ne sait s’il vient vraiment de ce monde. En cas de danger, il se téléporte vers un endroit sûr pour s’y cacher."}, {"g": "Épée", "t": "Il vient d’un autre univers. Son corps gazeux est si léger que la moindre brise peut l’emporter."}, {"g": "Bouclier", "t": "De nature curieuse et peu méfiante, il se retrouve souvent dans des situations dangereuses. Il peut se téléporter en cas de danger."}],
  790: [{"g": "Soleil", "t": "On pourrait le croire mort car il ne bouge pas du tout. Au toucher, il reste tiède. On le surnomme « cocon céleste » depuis l’Antiquité."}, {"g": "Lune", "t": "Sous sa lourde carapace, il amasse secrètement quelque chose en son sombre noyau. Il viendrait d’un autre monde."}, {"g": "Ultra-Soleil", "t": "Un antique roi d’Alola lui a donné le surnom de « cocon céleste » et a même érigé un autel en son honneur."}, {"g": "Ultra-Lune", "t": "Il continue à grandir en absorbant de la lumière. Sa carapace dorée est étonnamment solide."}, {"g": "Épée", "t": "La carapace qui le recouvre est plus dure que tout ce qui est connu par l’Homme. Il grandit en absorbant la lumière des étoiles."}, {"g": "Bouclier", "t": "Il aspire avec force la poussière de l’atmosphère et travaille sans relâche pour produire dans son noyau l’énergie nécessaire à son évolution."}],
  791: [{"g": "Soleil", "t": "Il viendrait d’un autre monde. Tout son corps émet une puissante lumière qui peut changer la nuit la plus noire en un jour radieux."}, {"g": "Lune", "t": "On suppose que c’est l’évolution de Cosmog lorsqu’il s’agit d’un mâle. Son troisième œil apparaît quand il s’en va vers un autre monde."}, {"g": "Ultra-Soleil", "t": "Lorsqu’il ouvre une Ultra-Brèche, il arrive que de l’énergie et des formes de vie d’autres mondes se retrouvent dans le nôtre."}, {"g": "Ultra-Lune", "t": "Des documents extrêmement anciens le décrivent comme « celui qui dévore le soleil »."}, {"g": "Épée", "t": "Quand tout son corps émet de la lumière et qu’il prend la forme du soleil, il peut repousser les ténèbres et illuminer le monde."}, {"g": "Bouclier", "t": "Jadis, on le surnommait « celui qui dévore le soleil ». Une lumière inextinguible rayonne de son corps."}],
  792: [{"g": "Soleil", "t": "On suppose que c’est l’évolution de Cosmog lorsqu’il s’agit d’une femelle. Son troisième œil apparaît quand il s’envole vers un autre monde."}, {"g": "Lune", "t": "Cet être mystérieux viendrait d’un autre monde. Il absorbe continuellement la lumière, transformant le jour en nuit noire."}, {"g": "Ultra-Soleil", "t": "Des documents extrêmement anciens le décrivent comme « celui qui invite la lune »."}, {"g": "Ultra-Lune", "t": "Il lui arrive d’invoquer dans ce monde des créatures et des puissances inconnues via une brèche menant à d’autres dimensions."}, {"g": "Épée", "t": "Il a pour surnom « celui qui invite la lune ». Il vit en transformant toutes sortes de lumière en énergie."}, {"g": "Bouclier", "t": "Il capture toute la lumière qui l’entoure pour prendre la forme de la pleine lune et éclairer les ténèbres nocturnes."}],
  793: [{"g": "Soleil", "t": "L’une des mystérieuses Ultra-Chimères. On l’aurait vue parasiter des gens en pleine rue, les rendant extrêmement violents."}, {"g": "Lune", "t": "Nul ne sait si cette Ultra-Chimère possède une conscience propre, mais on l’aurait aperçue en train d’imiter les gestes d’une jeune fille."}, {"g": "Ultra-Soleil", "t": "Une forme de vie d’un autre monde, communément appelée « Ultra-Chimère ». On la pense porteuse d’une violente neurotoxine."}, {"g": "Ultra-Lune", "t": "Il est venu dans ce monde à travers une Ultra-Brèche. Tel un parasite, il aurait besoin d’un hôte, Pokémon ou humain, pour survivre."}],
  794: [{"g": "Soleil", "t": "Personne ne sait si cette Ultra-Chimère venue d’un autre monde montre ses muscles pour être admirée ou pour intimider ceux qu’elle rencontre."}, {"g": "Lune", "t": "L’une des mystérieuses Ultra-Chimères. On l’aurait aperçue réduisant un camion à benne en miettes d’un seul coup de poing."}, {"g": "Ultra-Soleil", "t": "Cette créature venue d’ailleurs est dangereuse dans notre monde, mais il semblerait qu’elle soit très commune dans le sien."}, {"g": "Ultra-Lune", "t": "Ce type d’Ultra-Chimère adore exhiber ses muscles gonflés à l’extrême."}],
  795: [{"g": "Soleil", "t": "L’une des dangereuses Ultra-Chimères. On l’aurait aperçue en train de courir à une vitesse prodigieuse."}, {"g": "Lune", "t": "L’une des Ultra-Chimères. Elle semble refuser de toucher les choses de ce monde, comme si tout était souillé à ses yeux."}, {"g": "Ultra-Soleil", "t": "Une forme de vie venant d’un autre monde. Son corps gracile cache une puissance insoupçonnée."}, {"g": "Ultra-Lune", "t": "Cette créature venue d’ailleurs est dangereuse dans notre monde, mais il semblerait qu’elle soit très commune dans le sien."}],
  796: [{"g": "Soleil", "t": "L’une des mystérieuses Ultra-Chimères. On l’aurait vue émettre une formidable quantité d’électricité autour d’elle."}, {"g": "Lune", "t": "Une créature échappée de l’Ultra-Brèche. Elle a attaqué une centrale électrique, aussi suppose-t-on qu’elle se nourrit d’électricité."}, {"g": "Ultra-Soleil", "t": "Cette créature venue d’ailleurs est dangereuse dans notre monde, mais il semblerait qu’elle soit très commune dans le sien."}, {"g": "Ultra-Lune", "t": "Certains spécimens de ce type d’Ultra-Chimère plantent leurs membres dans le sol à la manière d’un arbre et restent immobiles."}],
  797: [{"g": "Soleil", "t": "Une Ultra-Chimère qui a traversé l’Ultra-Brèche. On l’aurait aperçue parcourir le ciel à grande vitesse."}, {"g": "Lune", "t": "Une espèce d’Ultra-Chimère. On l’aurait aperçue expulsant du gaz par ses deux bras et réduisant une forêt tout entière en cendres."}, {"g": "Ultra-Soleil", "t": "Cette dangereuse créature fait partie des Ultra-Chimères. On peut détecter des pics d’énergie émis par ses bras gigantesques."}, {"g": "Ultra-Lune", "t": "Cette créature venue d’ailleurs est dangereuse dans notre monde, mais il semblerait qu’elle soit très commune dans le sien."}],
  798: [{"g": "Soleil", "t": "Une Ultra-Chimère venue de l’Ultra-Brèche. Elle ne semble pas agressive, bien que son corps tout entier soit une arme tranchante."}, {"g": "Lune", "t": "Une espèce d’Ultra-Chimère. On l’aurait aperçue coupant un pylône métallique en deux d’un seul tranchant."}, {"g": "Ultra-Soleil", "t": "Le corps de cette Ultra-Chimère semble fin comme du papier, mais il est aussi tranchant qu’un sabre affûté."}, {"g": "Ultra-Lune", "t": "Cette créature venue d’ailleurs est dangereuse dans notre monde, mais il semblerait qu’elle soit très commune dans le sien."}],
  799: [{"g": "Soleil", "t": "Une espèce d’Ultra-Chimère. On l’aurait aperçue dévorant des montagnes et des gratte-ciel."}, {"g": "Lune", "t": "L’une des dangereuses Ultra-Chimères. Elle est constamment en train de manger, mais ne semble pas produire d’excréments."}, {"g": "Ultra-Soleil", "t": "Cette créature venue d’ailleurs est dangereuse dans notre monde, mais il semblerait qu’elle soit très commune dans le sien."}, {"g": "Ultra-Lune", "t": "Cette créature inconnue appelée « Ultra-Chimère » semble constamment affamée : elle mange en permanence."}],
  800: [{"g": "Soleil", "t": "Une créature endormie sous terre. On suppose qu’il s’agit d’une Ultra-Chimère et qu’elle serait venue d’un autre monde, il y a bien longtemps."}, {"g": "Lune", "t": "La lumière semble être sa source d’énergie. Une créature extrêmement agressive, capable d’émettre des rayons laser au moindre prétexte."}, {"g": "Ultra-Soleil", "t": "Il semble souffrir dans sa recherche désespérée de lumière, sa source d’énergie. On pense qu’il vient d’un autre monde."}, {"g": "Ultra-Lune", "t": "S’il ne dévore pas assez de lumière, sa source d’énergie, il accumule les impuretés. Il noircit et finit par ne plus pouvoir bouger."}, {"g": "Épée", "t": "La lumière est sa source d’énergie. Les impuretés que son corps a accumulées en dormant sous terre lui ont donné cette couleur noire."}, {"g": "Bouclier", "t": "Sa quête de lumière, sa source de vie, le rend violent. Il détruit tout sur son passage avec ses rayons laser."}],
  801: [{"g": "Soleil", "t": "Ce Pokémon a été créé de toutes pièces il y a 500 ans. Il comprend ce qu’on lui dit, mais il n’est pas doué de parole."}, {"g": "Lune", "t": "Son corps mécanique n’est qu’une enveloppe. Sa véritable nature est une âme artificielle nommée Animacœur."}, {"g": "Ultra-Soleil", "t": "Il accède à la conscience des individus en se synchronisant avec eux. Cette faculté l’aide à prendre soin d’eux."}, {"g": "Ultra-Lune", "t": "Il a été créé par un scientifique il y a environ 500 ans de cela. Sa véritable essence est un organe nommé Animacœur."}],
  802: [{"g": "Soleil", "t": "Il dissimule son apparence aux autres en se tapissant dans l’ombre. Son existence pourrait se révéler n’être qu’une fable."}, {"g": "Lune", "t": "En se glissant dans l’ombre de son adversaire, il peut copier ses mouvements et ses forces. C’est un Pokémon au caractère timide et craintif."}, {"g": "Ultra-Soleil", "t": "Il se fond dans l’ombre de son adversaire pour imiter sa force et ses attaques. La copie surpasse alors l’original."}, {"g": "Ultra-Lune", "t": "Il se terre dans les ombres des humains et des Pokémon. Il peut lire dans l’esprit de ses hôtes et copier leurs habilités."}, {"g": "Épée", "t": "Il s’est glissé dans l’ombre d’un maître du kung-fu. Il s’est aussi approprié sa botte secrète ultime en copiant ses mouvements."}, {"g": "Bouclier", "t": "Ce Pokémon ayant la capacité de se dissimuler dans les ombres, il est resté très longtemps caché aux yeux du monde."}],
  803: [{"g": "Ultra-Soleil", "t": "Dans son monde, cette Ultra-Chimère est fort appréciée pour son naturel conciliant, qui fait d’elle un compagnon de voyage idéal."}, {"g": "Ultra-Lune", "t": "Cette Ultra-Chimère venue d’un autre monde ricane lorsqu’elle asperge ses proies de venin grâce au dard qu’elle a sur la tête."}],
  804: [{"g": "Ultra-Soleil", "t": "Son corps contient des hectolitres de poison. Il fait partie de ces créatures que l’on nomme « Ultra-Chimères »."}, {"g": "Ultra-Lune", "t": "Cette Ultra-Chimère utilise son aiguillon pour sécréter un venin toxique, luisant et gluant."}],
  805: [{"g": "Ultra-Soleil", "t": "Il est sorti d’une Ultra-Brèche. Il est composé de plusieurs petites entités qui s’assemblent pour n’en former qu’une seule."}, {"g": "Ultra-Lune", "t": "On suppose que cette mystérieuse forme de vie est une Ultra-Chimère. Si un mur se met en branle et vous attaque sans prévenir, c’est lui."}],
  806: [{"g": "Ultra-Soleil", "t": "Il s’approche des gens avec son allure désarticulée et fait subitement exploser sa tête. Ce serait une Ultra-Chimère."}, {"g": "Ultra-Lune", "t": "Cette Ultra-Chimère sortie d’une Ultra-Brèche provoque des explosions pour surprendre l’ennemi et en profite pour voler son énergie."}],
  807: [{"g": "Ultra-Soleil", "t": "Il déchiquette son adversaire avec ses griffes chargées d’électricité. Même si sa cible évite l’attaque, elle reçoit un coup de jus."}, {"g": "Ultra-Lune", "t": "Il prend l’ennemi par surprise en attaquant plus vite que l’éclair, et le débite en morceaux avec ses griffes acérées."}, {"g": "Épée", "t": "Il fonce sur ses ennemis à la vitesse de l’éclair et les déchiquette à l’aide de ses griffes chargées à haute tension."}, {"g": "Bouclier", "t": "Il envoie des décharges électriques avec les coussinets de ses pattes. Quand il court, on peut voir des éclairs et entendre la foudre."}],
  808: [{"g": "Let's Go Pikachu", "t": "Ce Pokémon fait fondre le fer et les autres métaux contenus dans le sol pour les intégrer à son corps composé d’acier fondu."}, {"g": "Épée", "t": "Il se nourrit du métal qu’il fait fondre, et produit de l’énergie en faisant circuler du métal liquide dans son corps."}, {"g": "Bouclier", "t": "Les Meltan vivent en groupe. Quand l’heure de l’évolution a sonné, le plus fort d’entre eux absorbe ses camarades pour changer de forme."}],
  809: [{"g": "Let's Go Pikachu", "t": "Autrefois vénéré pour son aptitude à produire du fer, ce Pokémon a mystérieusement ressuscité après 3 000 ans."}, {"g": "Épée", "t": "En fin de vie, son corps rouille et se brise en mille morceaux. Ces derniers renaissent ensuite sous forme de Meltan."}, {"g": "Bouclier", "t": "On dit que, grâce à la force centrifuge, les coups de poing qu’il assène avec ses lourds écrous seraient les plus dévastateurs parmi les Pokémon."}],
  810: [{"g": "Épée", "t": "Le rythme qu’il crée en tapant avec son bâton très spécial génère des ondes sonores qui ont le pouvoir de vivifier les plantes."}, {"g": "Bouclier", "t": "Il attaque en frappant frénétiquement avec son bâton. Son enthousiasme grandit à mesure que le rythme s’accélère."}],
  811: [{"g": "Épée", "t": "Les Badabouin qui parviennent à suivre le rythme le plus effréné avec leurs deux bâtons sont les plus respectés par leurs camarades."}, {"g": "Bouclier", "t": "Il est tellement concentré à battre à un rythme effréné que même lorsque son adversaire tombe K.O., il ne s’en rend pas compte."}],
  812: [{"g": "Épée", "t": "Il contrôle le pouvoir de sa souche singulière en tapant en rythme dessus. Il se bat en manipulant des racines."}, {"g": "Bouclier", "t": "Celui qui possède les meilleures techniques de percussion devient le chef. De nature calme, il privilégie l’harmonie du groupe."}],
  813: [{"g": "Épée", "t": "Il court pour augmenter sa température et faire circuler l’énergie incandescente dans son corps. Il peut ainsi déployer toute sa puissance."}, {"g": "Bouclier", "t": "Quand il est prêt à se battre, la partie qui surmonte son museau ainsi que les coussinets de ses pattes postérieures émettent de la chaleur."}],
  814: [{"g": "Épée", "t": "Son pelage épais lui permet de mieux résister au froid et d’augmenter la température de ses capacités Feu."}, {"g": "Bouclier", "t": "Pour parfaire son jeu de jambes, il cueille des Baies puis drible avec, le tout sans se servir de ses mains."}],
  815: [{"g": "Épée", "t": "Il drible avec des pierres pour en faire des ballons enflammés, avant de tirer sur ses adversaires pour les brûler."}, {"g": "Bouclier", "t": "Exceptionnel en attaque comme en défense, il s’exalte quand on l’encourage, mais il lui arrive de se mettre en danger en jouant solo."}],
  816: [{"g": "Épée", "t": "Quand il a peur, il pleure des larmes contenant une substance lacrymogène d’une puissance équivalente à celle de cent oignons."}, {"g": "Bouclier", "t": "Sa peau change de couleur et le rend invisible quand elle est mouillée, comme un camouflage."}],
  817: [{"g": "Épée", "t": "Il crée des bombes à eau grâce au liquide qu’il sécrète avec la paume de ses mains. Il s’en sert dans les combats où la stratégie prime."}, {"g": "Bouclier", "t": "Paresseux, mais malin, il parsème son territoire de pièges pour empêcher ses ennemis d’y pénétrer."}],
  818: [{"g": "Épée", "t": "Il a plus d’un tour dans son sac : il peut tirer des gerbes d’eau du bout de ses doigts et planer dans les airs grâce à ses membranes dorsales."}, {"g": "Bouclier", "t": "Il repère le point faible de l’ennemi grâce à sa membrane nictitante, puis il transperce sa cible en tirant des jets d’eau à Mach 3 du bout des doigts."}],
  819: [{"g": "Épée", "t": "On le trouve partout à Galar. S’il n’a pas de Baies en réserve dans ses deux joues, il devient anxieux."}, {"g": "Bouclier", "t": "Comme il mange tout le temps des Baies, il est plus costaud qu’il n’en a l’air. Il parcourt les champs à la recherche de sa précieuse denrée."}],
  820: [{"g": "Épée", "t": "Il amasse tellement de Baies dans sa queue qu’elles tombent les unes après les autres, mais il est si étourdi qu’il ne s’en rend pas compte."}, {"g": "Bouclier", "t": "On rencontre souvent ce Pokémon à Galar. Aucune coquille de Baie ne résiste à ses incisives, dont il est très fier."}],
  821: [{"g": "Épée", "t": "Ce Pokémon brave affronte même les adversaires les plus redoutables. Il devient plus fort à mesure qu’il subit les contre-attaques."}, {"g": "Bouclier", "t": "Son petit corps lui permet de se jouer d’ennemis bien plus grands que lui en volant à toute vitesse pour les piquer où ils sont vulnérables."}],
  822: [{"g": "Épée", "t": "Il est capable d’utiliser des objets avec ses serres : il peut par exemple saisir et lancer des pierres ou même enrouler une corde autour d’un ennemi."}, {"g": "Bouclier", "t": "Après avoir surmonté tant de rudes combats, il a appris à déterminer avec précision la puissance de ses adversaires."}],
  823: [{"g": "Épée", "t": "Il n’a aucun rival dans le ciel de Galar. L’aspect intimidant de son corps d’acier noir et lustré inspire la crainte chez ses ennemis."}, {"g": "Bouclier", "t": "Grâce à son adresse remarquable en vol et sa grande intelligence, il travaille comme taxi volant de Galar."}],
  824: [{"g": "Épée", "t": "Comme il passe tout son temps à recueillir des informations, son intelligence est très développée, mais sa force physique laisse à désirer."}, {"g": "Bouclier", "t": "On le voit souvent dans les champs. Les poils de son corps lui servent à capter ce qu’il se passe autour de lui."}],
  825: [{"g": "Épée", "t": "Il ne bouge presque pas, mais il est bien vivant. On dit qu’il aurait découvert ses pouvoirs psychiques à force de jeûner dans sa coquille."}, {"g": "Bouclier", "t": "Il se développe dans sa coquille et se prépare à évoluer en sondant les alentours grâce à ses pouvoirs psychiques."}],
  826: [{"g": "Épée", "t": "Il est renommé pour son intelligence. Son gros cerveau est un indicateur de la puissance de ses pouvoirs psychiques."}, {"g": "Bouclier", "t": "Il déploie ses pouvoirs psychiques pour sonder les alentours, sur un rayon pouvant atteindre 10 km."}],
  827: [{"g": "Épée", "t": "Il vit en subtilisant la nourriture des autres Pokémon. Grâce à ses coussinets moelleux, il ne fait aucun bruit quand il marche."}, {"g": "Bouclier", "t": "Rusé et vigilant, il prend la poudre d’escampette après avoir volé de la nourriture en prenant soin d’effacer ses traces de pas avec sa queue."}],
  828: [{"g": "Épée", "t": "Il marque sa victime pour la suivre à l’odeur. Sitôt qu’elle est distraite, il s’empresse de lui voler ses biens."}, {"g": "Bouclier", "t": "Grâce à son corps leste et ses griffes acérées, il va et vient en dérobant Œufs et nourriture. Son ennemi juré est Fulgudog."}],
  829: [{"g": "Épée", "t": "Quand il plante son unique pied pour absorber la lumière du soleil, ses pétales prennent une couleur éclatante."}, {"g": "Bouclier", "t": "Nombreux sont ceux qui ont décidé d’en élever un après avoir été charmés par sa manière de chanter en virevoltant au gré de la brise."}],
  830: [{"g": "Épée", "t": "Les graines de son duvet sont remplies de nutriments. Elles sont emportées par le vent et redonnent vitalité aux plantes et aux Pokémon."}, {"g": "Bouclier", "t": "Les fils tissés à partir du duvet sur sa tête sont satinés et absolument somptueux. Le textile ainsi créé est typique de la région de Galar."}],
  831: [{"g": "Épée", "t": "Son pelage frisé est doux et rebondi comme un coussin. Une telle toison le protègerait même s’il chutait d’une falaise."}, {"g": "Bouclier", "t": "Si ses poils poussent trop, il ne peut plus bouger. Les étoffes tissées avec son pelage sont étonnamment solides."}],
  832: [{"g": "Épée", "t": "La texture de sa laine est si élastique que la surface des tapis fabriqués avec ce matériau est aussi rebondissante que celle d’un trampoline."}, {"g": "Bouclier", "t": "Ses splendides cornes lui servent à attirer les membres de l’autre sexe. Il ne s’en sert jamais pour se battre."}],
  833: [{"g": "Épée", "t": "Il a pour habitude de mordre tout ce qui lui passe sous les yeux. On raconte qu’il fait cela parce que ses incisives qui poussent le démangent."}, {"g": "Bouclier", "t": "La corne sur sa tête est aussi dure que la roche. Il s’en sert pour se battre et lorsque l’ennemi flanche, il le mord et ne le lâche plus."}],
  834: [{"g": "Épée", "t": "De nature très violente, il mord fermement ses proies avec sa mâchoire, assez puissante pour broyer une barre de fer."}, {"g": "Bouclier", "t": "Son cou extensible lui permet d’atteindre des ennemis éloignés en un instant pour leur porter un coup décisif avec ses crocs aiguisés."}],
  835: [{"g": "Épée", "t": "Lorsqu’il court, on peut voir de l’électricité se former à la base de sa queue. Ce Pokémon est très populaire auprès des bergers de Galar."}, {"g": "Bouclier", "t": "Ce glouton assiste les humains dans leur travail en échange de friandises. Il court sans arrêt, le corps enveloppé d’électricité."}],
  836: [{"g": "Épée", "t": "Il produit de l’électricité puis la transfère dans ses pattes pour mieux courir. Ainsi, il peut foncer pendant trois jours et trois nuits."}, {"g": "Bouclier", "t": "Il se sert de l’énergie électrique pour augmenter la puissance de ses membres. Sa vitesse maximale dépasse de peu les 90 km/h."}],
  837: [{"g": "Épée", "t": "On l’a découvert dans une mine il y a 400 ans. Son corps est presque entièrement composé d’une substance identique au charbon."}, {"g": "Bouclier", "t": "Il parcourt sans difficulté les sentiers rocheux accidentés à la manière d’un monocycle. Il a besoin de brûler du charbon pour vivre."}],
  838: [{"g": "Épée", "t": "Il produit du charbon dans son corps. Jadis, les habitants de Galar ramassaient ce charbon au sol et s’en servaient pour leurs besoins quotidiens."}, {"g": "Bouclier", "t": "Il peut faire tourner ses pattes très vite pour se déplacer à une vitesse de 30 km/h. Il peut aussi souffler des flammes à 1 000 °C."}],
  839: [{"g": "Épée", "t": "Il est d’une nature paisible, mais si les humains tentent de piller ses mines, il enrage et brûle tout avec des flammes à 1 500 °C."}, {"g": "Bouclier", "t": "Lorsqu’il s’engage dans un combat, son tas de charbon brûle et vire au rouge, ce qui répand de petites étincelles qui calcinent ce qui l’entoure."}],
  840: [{"g": "Épée", "t": "Il vit toujours dans sa pomme. S’il croise un Pokémon oiseau, son prédateur naturel, il se fait passer pour un simple fruit pour se protéger."}, {"g": "Bouclier", "t": "À la naissance, il s’installe dans une pomme et grandit en se nourrissant de sa chair. Son évolution dépend de la saveur du fruit."}],
  841: [{"g": "Épée", "t": "Il a évolué après avoir mangé une pomme acide. Il concentre dans ses joues un liquide si corrosif qu’il peut provoquer des brûlures."}, {"g": "Bouclier", "t": "Il vole avec ses ailes faites de pelures de pomme et crache une substance très acide. Il peut aussi prendre la forme de ce fruit."}],
  842: [{"g": "Épée", "t": "Il a évolué après avoir mangé une pomme sucrée. Il attire ses proies, les Pokémon Insecte, en dégageant un parfum mielleux."}, {"g": "Bouclier", "t": "Son corps est recouvert de nectar. La peau de son dos, particulièrement sucrée, constituait jadis le goûter des enfants."}],
  843: [{"g": "Épée", "t": "Il amasse le sable qu’il avale en creusant dans la poche de son cou. Elle peut en contenir jusqu’à huit kilos."}, {"g": "Bouclier", "t": "En expulsant du sable par les narines, il aveugle son adversaire et en profite pour se cacher sous terre."}],
  844: [{"g": "Épée", "t": "Il peut expulser 100 kg de sable de ses narines en compressant tout son corps. Quand il est à court de sable, il a tendance à se dérober."}, {"g": "Bouclier", "t": "S’il s’enroule d’une manière aussi particulière, c’est pour optimiser l’expulsion de sable par ses narines."}],
  845: [{"g": "Épée", "t": "Il est assez puissant pour terrasser un ennemi d’un seul coup, mais il est tellement nigaud qu’il oublie contre qui il se bat."}, {"g": "Bouclier", "t": "Très glouton, il avale les Embrochet d’une seule bouchée, mais il lui arrive de se tromper et de tenter de gober un autre Pokémon."}],
  846: [{"g": "Épée", "t": "Sa mâchoire fine et aiguisée fait sa fierté. À peine voit-il le moindre mouvement qu’il fonce dans sa direction."}, {"g": "Bouclier", "t": "Lorsqu’il a le ventre plein, il a beaucoup plus de mal à se déplacer, et c’est à ce moment précis qu’il se fait gober par les Nigosier."}],
  847: [{"g": "Épée", "t": "Sa mâchoire pointue comme une lance est aussi dure que l’acier, et sa chair serait, contre toute attente, succulente."}, {"g": "Bouclier", "t": "Il charge d’un coup en faisant tourner sa nageoire caudale. Il peut transpercer ses proies à une vitesse dépassant les 100 nœuds."}],
  848: [{"g": "Épée", "t": "Sa peau sécrète les toxines accumulées dans sa poche de poison interne. Quand on le touche, on se fait électrocuter."}, {"g": "Bouclier", "t": "Par un procédé chimique, il change son poison en électricité. L’intensité du courant est faible, mais peut engourdir un ennemi."}],
  849: [{"g": "Épée", "t": "Lorsqu’il gratte l’excroissance sur son ventre pour produire de l’électricité, on peut entendre un son similaire à celui d’une guitare."}, {"g": "Bouclier", "t": "Impatient et bagarreur, ce Pokémon avale de grandes gorgées d’eau croupie pour en absorber toute la toxicité."}],
  850: [{"g": "Épée", "t": "Il produit de la chaleur grâce au gaz inflammable qu’il emmagasine dans son corps. La partie jaune de son abdomen est particulièrement brûlante."}, {"g": "Bouclier", "t": "Il enserre fermement ses proies avec son corps brûlant et, quand elles sont bien grillées, il les dévore."}],
  851: [{"g": "Épée", "t": "Quand il génère de la chaleur, sa température est d’environ 800 °C. Il se sert de son corps comme d’un fouet pour sauter sur ses ennemis."}, {"g": "Bouclier", "t": "Il est de nature agressive. Non seulement son corps brûlant est dangereux, mais il possède en plus d’énormes crocs très pointus."}],
  852: [{"g": "Épée", "t": "Il se rend sur la terre ferme pour se nourrir. Très curieux, son premier réflexe est de frapper tout ce qu’il voit avec ses tentacules."}, {"g": "Bouclier", "t": "Il a l’intelligence d’un enfant de trois ans. Il perd souvent ses tentacules, mais comme ils repoussent, il ne s’en soucie guère."}],
  853: [{"g": "Épée", "t": "Son corps est un amas de muscles. La puissance des prises d’étranglement qu’il exécute avec ses tentacules est saisissante."}, {"g": "Bouclier", "t": "Mû par le besoin de tester la force de ses bras, il se rend sur la terre ferme pour trouver un adversaire. Il retourne à l’eau après le combat."}],
  854: [{"g": "Épée", "t": "On raconte que ce Pokémon est né lorsqu’une âme esseulée a plongé dans un reste de thé noir froid."}, {"g": "Bouclier", "t": "Il élit domicile dans des tasses de thé anciennes de grand renom. Parmi celles-ci se trouvent de nombreuses contrefaçons."}],
  855: [{"g": "Épée", "t": "Il élit domicile dans des théières antiques. La plupart sont des contrefaçons, mais il lui arrive dans de très rares cas de trouver des originaux."}, {"g": "Bouclier", "t": "Dès qu’il voit un reste de thé noir, il se verse dedans pour donner naissance à un Polthégeist."}],
  856: [{"g": "Épée", "t": "La protubérance sur sa tête lui permet de percevoir les émotions des êtres vivants. Il n’accorde sa confiance qu’aux gens calmes."}, {"g": "Bouclier", "t": "Il aime les lieux inhabités. S’il perçoit des émotions trop fortes, il s’enfuit aussi vite que possible."}],
  857: [{"g": "Épée", "t": "S’il ressent des émotions trop fortes, il en fera taire la source, quelle qu’elle soit, en utilisant des méthodes assez violentes."}, {"g": "Bouclier", "t": "Il frappe ses ennemis avec ses tresses pour les faire taire. Sa puissance est telle qu’il peut mettre K.O. un boxeur professionnel d’un seul coup."}],
  858: [{"g": "Épée", "t": "Il éloigne les autres êtres vivants en émettant des ondes psychiques pouvant donner des maux de tête épouvantables."}, {"g": "Bouclier", "t": "On l’appelle aussi la « sorcière de la forêt ». Ce Pokémon lacère quiconque fait trop de bruit avec les griffes de son tentacule."}],
  859: [{"g": "Épée", "t": "Pour se refaire une santé, il hume l’énergie négative que les humains et les Pokémon dégagent quand ils sont irrités."}, {"g": "Bouclier", "t": "Il se glisse dans les foyers pour commettre un larcin et en profite pour se nourrir de l’énergie négative des habitants contrariés."}],
  860: [{"g": "Épée", "t": "Sa technique de combat consiste à faire semblant de se prosterner devant son adversaire pour le transpercer avec ses cheveux aiguisés."}, {"g": "Bouclier", "t": "La nuit, il ruse pour attirer ses proies dans la forêt. On raconte qu’il a le pouvoir de faire pousser les cultures agricoles."}],
  861: [{"g": "Épée", "t": "Il enroule ses cheveux autour de son corps pour augmenter sa masse musculaire, ce qui lui donne assez de force pour enserrer un Mackogneur."}, {"g": "Bouclier", "t": "Ses cheveux sont comme des muscles filandreux qu’il peut détacher pour saisir ses adversaires, tels des tentacules."}],
  862: [{"g": "Épée", "t": "Il possède une puissance vocale remarquable. On appelle Blocage sa technique qui consiste à intimider l’ennemi avec son cri guttural."}, {"g": "Bouclier", "t": "Il a évolué après avoir enchaîné de nombreux combats. Le cri qu’il pousse lorsqu’il fait un « X » avec ses bras ébranle n’importe quel ennemi."}],
  863: [{"g": "Épée", "t": "La fourrure sur sa tête s’est endurcie et a pris la forme d’un casque en fer. Il est de nature très bagarreuse."}, {"g": "Bouclier", "t": "Il s’est tant adonné au combat qu’il a évolué : il est désormais doté de griffes redoutables qui prennent la forme de dagues en s’allongeant."}],
  864: [{"g": "Épée", "t": "Son énergie spectrale accrue s’est répandue hors de sa coquille. Il protège l’âme de son noyau avec son corps spirituel."}, {"g": "Bouclier", "t": "Ceux qui ont le malheur de toucher le corps spirituel qui protège son noyau se retrouveront immobilisés, comme changés en pierre."}],
  865: [{"g": "Épée", "t": "Seuls les Canarticho ayant survécu à de nombreux combats atteignent ce stade d’évolution. Si son poireau se flétrit, il se retire du champ de bataille."}, {"g": "Bouclier", "t": "Il pare les attaques avec le tranchant de son solide poireau, et contre-attaque avec la pointe de la tige. Son arme est également comestible."}],
  866: [{"g": "Épée", "t": "Véritable virtuose des claquettes, il se donne en spectacle en dansant d’un pas léger tout en jonglant avec sa canne de glace."}, {"g": "Bouclier", "t": "Ses gestes hilarants le rendent très populaire. Il peut libérer ses pouvoirs psychiques depuis le motif sur son ventre."}],
  867: [{"g": "Épée", "t": "Les motifs antiques qui ont été gravés en y incorporant une puissante malédiction ont aspiré l’âme de Tutafeh avant de prendre vie."}, {"g": "Bouclier", "t": "Quiconque touchera son corps semblable à une ombre devra endurer la vision des souvenirs effroyables gravés dans ses motifs."}],
  868: [{"g": "Épée", "t": "Son corps de crème s’est composé à partir de particules au parfum sucré flottant dans l’air."}, {"g": "Bouclier", "t": "Les pâtissiers connaissent tous ce vieil adage : Quand Crèmy apparaît, le succès est assuré."}],
  869: [{"g": "Épée", "t": "Il offre aux Dresseurs auxquels il accorde toute sa confiance des Baies décorées avec de la crème."}, {"g": "Bouclier", "t": "Quand il est heureux, la crème qu’il produit avec ses mains devient plus sucrée et plus onctueuse."}],
  870: [{"g": "Épée", "t": "C’est une entité unique composée d’un chef et de cinq cadets. Ces derniers obéissent sans sourciller à leur supérieur hiérarchique."}, {"g": "Bouclier", "t": "À six, ils représentent un Pokémon unique. Ils peuvent changer de formation et comptent sur leur travail d’équipe en combat."}],
  871: [{"g": "Épée", "t": "Il libère de l’électricité depuis la pointe de ses épines, et se nourrit des algues accrochées aux rochers en les arrachant avec ses dents aiguisées."}, {"g": "Bouclier", "t": "Chacune de ses épines est chargée en électricité. S’il en perd une, celle-ci continue d’émettre un courant électrique pendant trois heures."}],
  872: [{"g": "Épée", "t": "Il crache un fil gelé qu’il utilise pour s’accrocher à une branche : il dort ainsi en imitant une stalactite."}, {"g": "Bouclier", "t": "Il se nourrit de la neige entassée sur le sol. Plus il en mange, plus les épines sur son dos grandissent."}],
  873: [{"g": "Épée", "t": "La température de ses ailes est de - 180 °C. Quand il vole, ses écailles gelées tombent sur le paysage comme des flocons de neige."}, {"g": "Bouclier", "t": "Sans pitié pour les vandales, il bat ses ailes gelées pour provoquer des blizzards et punir quiconque ose souiller les champs et les collines."}],
  874: [{"g": "Épée", "t": "Il se tient immobile au milieu des plaines et passe son temps à observer la course du soleil dans le ciel. Son jeu de jambes est phénoménal."}, {"g": "Bouclier", "t": "Tous les ans à la même date, ils arrivent de nulle part pour se réunir en cercle. C’est une de leurs coutumes."}],
  875: [{"g": "Épée", "t": "Originaire d’une contrée polaire, ce Pokémon a débarqué dans la région ballotté par les flots. Il garde toujours la tête froide."}, {"g": "Bouclier", "t": "Ne supportant pas la chaleur, il se rafraîchit toujours la tête avec de la glace. Il pêche de quoi se nourrir à l’aide de son cheveu."}],
  876: [{"g": "Épée", "t": "Il peut sentir les émotions d’autrui avec ses cornes. Le mâle reste aux côtés de son Dresseur pour s’occuper de lui, à l’image d’un domestique."}, {"g": "Bouclier", "t": "Avec ses cornes, il peut percevoir les émotions des êtres vivants alentour. Celles qui sont positives lui servent de source d’énergie."}],
  877: [{"g": "Épée", "t": "Il a toujours un petit creux. Il grignote les graines qu’il a mises dans ses sortes de poches pour produire de l’électricité."}, {"g": "Bouclier", "t": "Il a beau manger, il a tout le temps faim. Il a toujours des graines grillées à l’électricité sur lui."}],
  878: [{"g": "Épée", "t": "Ce Pokémon est assez costaud pour porter des charges de cinq tonnes sans problème. Il utilise sa trompe pour creuser le sol."}, {"g": "Bouclier", "t": "Les travaux physiques, c’est son affaire. Son corps de cuivre rouille sous la pluie et prend une vive couleur verte."}],
  879: [{"g": "Épée", "t": "Sa peau verte résiste bien à l’eau. Il s’est installé dans la région il y a longtemps et a travaillé en coopération avec les Hommes."}, {"g": "Bouclier", "t": "Ces Pokémon vivent en troupeau. L’étreinte de leur trompe est si forte qu’elle suffit à réduire un rocher en poussière."}],
  880: [{"g": "Épée", "t": "Jadis, la partie inférieure de son corps musclé le rendait invincible, mais il s’est éteint après avoir mangé toutes les plantes dont il se nourrissait."}, {"g": "Bouclier", "t": "Il envoie des décharges avec les muscles puissants de sa queue. La partie supérieure de son corps est trop petite par rapport à la partie inférieure."}],
  881: [{"g": "Épée", "t": "Quand la partie supérieure de son corps, couverte de glace, frissonne, il produit de l’électricité. Il éprouve de grandes difficultés à marcher."}, {"g": "Bouclier", "t": "Autrefois, il vivait en bord de mer et conservait sa nourriture dans la glace de son corps, mais il s’est éteint, car il avait du mal à se déplacer."}],
  882: [{"g": "Épée", "t": "La force de ses pattes et de ses mâchoires le rendait presque invincible, mais à trop chasser ses proies, celles-ci ont disparu, et lui avec."}, {"g": "Bouclier", "t": "Ses pattes robustes lui permettent de courir à plus de 60 km/h, mais en revanche, il ne peut respirer que sous l’eau."}],
  883: [{"g": "Épée", "t": "Il gèle les alentours pour capturer ses proies, mais comme sa bouche est sur le dessus de sa tête, il a beaucoup de mal à les manger."}, {"g": "Bouclier", "t": "Aucune attaque ne pouvait égratigner la peau de son visage, mais il s’est éteint, car il avait du mal à respirer."}],
  884: [{"g": "Épée", "t": "Son corps, semblable à du métal poli, allie légèreté et solidité. Malheureusement, il rouille facilement."}, {"g": "Bouclier", "t": "Son corps, composé d’un métal spécial, est léger et lui offre une excellente mobilité. Il est toutefois sensible à la pluie et vit donc dans les grottes."}],
  885: [{"g": "Épée", "t": "Revenu à la vie sous forme de Pokémon Spectre, il erre au-dessus de la mer dans laquelle il vivait autrefois."}, {"g": "Bouclier", "t": "Seul, il est si faible qu’il ne saurait rivaliser avec un enfant, mais en coopérant avec ses semblables, il peut devenir assez fort pour évoluer."}],
  886: [{"g": "Épée", "t": "Il vole à une vitesse de 200 km/h et se bat aux côtés d’un Fantyrm, dont il prend soin jusqu’à son évolution."}, {"g": "Bouclier", "t": "Il prend soin du Fantyrm sur sa tête. Quand ce dernier n’est plus là, il panique et tente de le remplacer par un autre Pokémon."}],
  887: [{"g": "Épée", "t": "Il vit en compagnie de Fantyrm qui logent dans les trous de ses cornes. Quand il passe à l’attaque, il les propulse à la vitesse du son."}, {"g": "Bouclier", "t": "Il paraît que les Fantyrm installés dans ses cornes attendent impatiemment le moment où ils seront propulsés à la vitesse du son."}],
  888: [{"g": "Épée", "t": "Également surnommé « héros légendaire », ce Pokémon absorbe du métal et se change en arme pour se battre."}, {"g": "Bouclier", "t": "On dit qu’il s’agit de la figure fraternelle et du rival de Zamazenta, un Pokémon plongé dans un long sommeil."}],
  889: [{"g": "Épée", "t": "Ce Pokémon sauva autrefois Galar en joignant ses forces à celles du roi des Hommes. Il absorbe du métal quand il passe au combat."}, {"g": "Bouclier", "t": "Ce Pokémon, changé en statue, est resté pétrifié si longtemps qu’il a failli tomber dans l’oubli."}],
  890: [{"g": "Épée", "t": "Il devient actif en absorbant l’énergie qui émerge du sol de Galar grâce au noyau situé sur sa poitrine."}, {"g": "Bouclier", "t": "Il se trouvait dans une météorite qui s’est écrasée il y a 20 000 ans. Il semble y avoir un lien entre ce Pokémon et le phénomène Dynamax."}],
  891: [{"g": "Épée", "t": "Il suit un entraînement rigoureux pour parfaire ses techniques. La forme de son évolution dépend des capacités qu’il a assimilées."}, {"g": "Bouclier", "t": "Lorsqu’il tire sur les longs poils blancs sur sa tête, il devient plus combatif et de l’énergie jaillit de sous son nombril."}],
  892: [{"g": "Épée", "t": "Adepte des techniques pouvant mettre K.O. en un seul coup, il se jette sur son adversaire et le frappe de son poing robuste."}, {"g": "Bouclier", "t": "Il vit dans une lointaine région montagneuse où il peaufine ses techniques et muscle ses jambes en courant le long des falaises abruptes."}],
  893: [{"g": "Épée", "t": "Ils vivent en groupe dans la jungle, où les autres Pokémon les craignent à cause de leur nature agressive."}, {"g": "Bouclier", "t": "Lorsque ses lianes se détachent de son corps, elles fertilisent le sol et favorisent la croissance des plantes de la forêt."}],
  894: [{"g": "Épée", "t": "Son corps est un véritable concentré d’énergie électrique. On raconte que si on lui retire ses anneaux, sa puissance cachée se libère."}, {"g": "Bouclier", "t": "Son corps est entièrement composé d’organes générant de l’électricité. Il peut produire assez d’énergie pour alimenter tout Galar."}],
  895: [{"g": "Épée", "t": "Une théorie stipule que ses bras ont la forme de la tête d’un Pokémon Dragon des temps anciens, mais aucune preuve ne l’atteste."}, {"g": "Bouclier", "t": "Son corps est entièrement composé de cristaux d’énergie draconique. Il possèderait les pouvoirs de tous les Pokémon Dragon."}],
  896: [{"g": "Épée", "t": "Violent au point de s’emparer de tout ce qu’il désire par la force, ce Pokémon est capable de libérer un puissant air glacial de ses sabots."}, {"g": "Bouclier", "t": "Ce Pokémon à la force hors du commun porte un masque composé de glace cent fois plus solide que le diamant."}],
  897: [{"g": "Épée", "t": "Il se sert de tous ses sens pour se repérer, sauf celui de la vue. Un coup de ses sabots suffirait à séparer l’âme du corps de sa cible."}, {"g": "Bouclier", "t": "Ce Pokémon friand de silence et de solitude galope à travers les ténèbres nocturnes et aspire l’énergie vitale des êtres endormis."}],
  898: [{"g": "Épée", "t": "Doté de pouvoirs de guérison et d’abondance, ce Pokémon miséricordieux régnait sur Galar il y a fort longtemps."}, {"g": "Bouclier", "t": "Ce roi légendaire qui a régné sur Galar il y a fort longtemps possède le pouvoir d’apaiser les cœurs et de faire germer les plantes."}]
};
